-- 和合本全文数据（文件序号见文件名 bible_cuv_data_NN.sql）。先运行 bible_cuv_schema.sql 建表，再按序号依次运行各数据文件。可重复运行（冲突自动跳过）。
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 34, 1, '约西亚登基的时候年八岁，在耶路撒冷作王三十一年。'),
('CUV', '历代志下', 14, 34, 2, '他行耶和华眼中看为正的事，效法他祖大卫所行的，不偏左右。'),
('CUV', '历代志下', 14, 34, 3, '他作王第八年，尚且年幼，就寻求他祖大卫的神。到了十二年才洁净犹大和耶路撒冷，除掉邱坛、木偶、雕刻的像，和铸造的像。'),
('CUV', '历代志下', 14, 34, 4, '众人在他面前拆毁巴力的坛，砍断坛上高高的日像，又把木偶和雕刻的像，并铸造的像打碎成灰，撒在祭偶像人的坟上，'),
('CUV', '历代志下', 14, 34, 5, '将他们祭司的骸骨烧在坛上，洁净了犹大和耶路撒冷；'),
('CUV', '历代志下', 14, 34, 6, '又在玛拿西、以法莲、西缅、拿弗他利各城，和四围破坏之处，都这样行；'),
('CUV', '历代志下', 14, 34, 7, '又拆毁祭坛，把木偶和雕刻的像打碎成灰，砍断以色列遍地所有的日像，就回耶路撒冷去了。'),
('CUV', '历代志下', 14, 34, 8, '约西亚王十八年，净地净殿之后，就差遣亚萨利雅的儿子沙番、邑宰玛西雅、约哈斯的儿子史官约亚去修理耶和华─他神的殿。'),
('CUV', '历代志下', 14, 34, 9, '他们就去见大祭司希勒家，将奉到神殿的银子交给他；这银子是看守殿门的利未人从玛拿西、以法莲，和一切以色列剩下的人，以及犹大、便雅悯众人，并耶路撒冷的居民收来的。'),
('CUV', '历代志下', 14, 34, 10, '又将这银子交给耶和华殿里督工的，转交修理耶和华殿的工匠，'),
('CUV', '历代志下', 14, 34, 11, '就是交给木匠、石匠，买凿成的石头和架木与栋梁，修犹大王所毁坏的殿。'),
('CUV', '历代志下', 14, 34, 12, '这些人办事诚实，督工的是利未人米拉利的子孙雅哈、俄巴底；督催的是哥辖的子孙撒迦利亚、米书兰；还有善于作乐的利未人。'),
('CUV', '历代志下', 14, 34, 13, '他们又监管扛抬的人，督催一切做工的。利未人中也有作书记、作司事、作守门的。'),
('CUV', '历代志下', 14, 34, 14, '他们将奉到耶和华殿的银子运出来的时候，祭司希勒家偶然得了摩西所传耶和华的律法书。'),
('CUV', '历代志下', 14, 34, 15, '希勒家对书记沙番说：我在耶和华殿里得了律法书。遂将书递给沙番。'),
('CUV', '历代志下', 14, 34, 16, '沙番把书拿到王那里，回复王说：凡交给仆人们办的都办理了。'),
('CUV', '历代志下', 14, 34, 17, '耶和华殿里的银子倒出来，交给督工的和匠人的手里了。'),
('CUV', '历代志下', 14, 34, 18, '书记沙番又对王说：祭司希勒家递给我一卷书。沙番就在王面前读那书。'),
('CUV', '历代志下', 14, 34, 19, '王听见律法上的话，就撕裂衣服，'),
('CUV', '历代志下', 14, 34, 20, '吩咐希勒家与沙番的儿子亚希甘、米迦的儿子亚比顿、书记沙番，和王的臣仆亚撒雅说：'),
('CUV', '历代志下', 14, 34, 21, '你们去为我、为以色列和犹大剩下的人，以这书上的话求问耶和华；因我们列祖没有遵守耶和华的言语，没有照这书上所记的去行，耶和华的烈怒就倒在我们身上。'),
('CUV', '历代志下', 14, 34, 22, '于是，希勒家和王所派的众人都去见女先知户勒大。户勒大是掌管礼服沙龙的妻，沙龙是哈斯拉的孙子、特瓦的儿子。户勒大住在耶路撒冷第二区；他们请问于他。'),
('CUV', '历代志下', 14, 34, 23, '他对他们说：耶和华─以色列的神如此说：你们可以回复那差遣你们来见我的人说，'),
('CUV', '历代志下', 14, 34, 24, '耶和华如此说：我必照著在犹大王面前所读那书上的一切咒诅，降祸与这地和其上的居民；'),
('CUV', '历代志下', 14, 34, 25, '因为他们离弃我，向别神烧香，用他们手所做的惹我发怒，所以我的忿怒如火倒在这地上，总不息灭。'),
('CUV', '历代志下', 14, 34, 26, '然而差遣你们来求问耶和华的犹大王，你们要这样回复他说：耶和华─以色列的神如此说：至于你所听见的话，'),
('CUV', '历代志下', 14, 34, 27, '就是听见我指著这地和其上居民所说的话，你便心里敬服，在我面前自卑，撕裂衣服，向我哭泣，因此我应允了你。这是我─耶和华说的。'),
('CUV', '历代志下', 14, 34, 28, '我必使你平平安安地归到坟墓，到你列祖那里，我要降与这地和其上居民的一切灾祸，你也不至亲眼看见。他们就回复王去了。'),
('CUV', '历代志下', 14, 34, 29, '王差遣人招聚犹大和耶路撒冷的众长老来。'),
('CUV', '历代志下', 14, 34, 30, '王和犹大众人，与耶路撒冷的居民，并祭司利未人，以及所有的百姓，无论大小，都一同上到耶和华的殿；王就把殿里所得的约书念给他们听。'),
('CUV', '历代志下', 14, 34, 31, '王站在他的地位上，在耶和华面前立约，要尽心尽性地顺从耶和华，遵守他的诫命、法度、律例，成就这书上所记的约言；'),
('CUV', '历代志下', 14, 34, 32, '又使住耶路撒冷和便雅悯的人都服从这约。于是耶路撒冷的居民都遵行他们列祖之神的约。'),
('CUV', '历代志下', 14, 34, 33, '约西亚从以色列各处将一切可憎之物尽都除掉，使以色列境内的人都事奉耶和华─他们的神。约西亚在世的日子，就跟从耶和华─他们列祖的神，总不离开。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 35, 1, '约西亚在耶路撒冷向耶和华守逾越节。正月十四日，就宰了逾越节的羊羔。'),
('CUV', '历代志下', 14, 35, 2, '王分派祭司各尽其职，又勉励他们办耶和华殿中的事；'),
('CUV', '历代志下', 14, 35, 3, '又对那归耶和华为圣、教训以色列人的利未人说：你们将圣约柜安放在以色列王大卫儿子所罗门建造的殿里，不必再用肩扛抬。现在要事奉耶和华─你们的神，服事他的民以色列。'),
('CUV', '历代志下', 14, 35, 4, '你们应当按著宗族，照著班次，遵以色列王大卫和他儿子所罗门所写的，自己预备。'),
('CUV', '历代志下', 14, 35, 5, '要按著你们的弟兄，这民宗族的班次，站在圣所，每班中要利未宗族的几个人。'),
('CUV', '历代志下', 14, 35, 6, '要宰逾越节的羊羔，洁净自己，为你们的弟兄预备了，好遵守耶和华藉摩西所吩咐的话。'),
('CUV', '历代志下', 14, 35, 7, '约西亚从群畜中赐给在那里所有的人民，绵羊羔和山羊羔三万只，牛三千只，作逾越节的祭物；这都是出自王的产业中。'),
('CUV', '历代志下', 14, 35, 8, '约西亚的众首领也乐意将牺牲给百姓和祭司利未人；又有管理神殿的希勒家、撒迦利亚、耶歇将羊羔二千六百只，牛三百只，给祭司作逾越节的祭物。'),
('CUV', '历代志下', 14, 35, 9, '利未人的族长歌楠雅和他两个兄弟示玛雅、拿坦业，与哈沙比雅、耶利、约撒拔将羊羔五千只，牛五百只，给利未人作逾越节的祭物。'),
('CUV', '历代志下', 14, 35, 10, '这样，供献的事齐备了。祭司站在自己的地方，利未人按著班次站立，都是照王所吩咐的。'),
('CUV', '历代志下', 14, 35, 11, '利未人宰了逾越节的羊羔，祭司从他们手里接过血来洒在坛上；利未人剥皮，'),
('CUV', '历代志下', 14, 35, 12, '将燔祭搬来，按著宗族的班次分给众民，好照摩西书上所写的，献给耶和华；献牛也是这样。'),
('CUV', '历代志下', 14, 35, 13, '他们按著常例，用火烤逾越节的羊羔。别的圣物用锅，用釜，用罐煮了，速速地送给众民。'),
('CUV', '历代志下', 14, 35, 14, '然后为自己和祭司预备祭物；因为祭司亚伦的子孙献燔祭和脂油，直到晚上。所以利未人为自己和祭司亚伦的子孙，预备祭物。'),
('CUV', '历代志下', 14, 35, 15, '歌唱的亚萨之子孙，照著大卫、亚萨、希幔，和王的先见耶杜顿所吩咐的，站在自己的地位上。守门的看守各门，不用离开他们的职事，因为他们的弟兄利未人给他们预备祭物。'),
('CUV', '历代志下', 14, 35, 16, '当日，供奉耶和华的事齐备了，就照约西亚王的吩咐守逾越节，献燔祭在耶和华的坛上。'),
('CUV', '历代志下', 14, 35, 17, '当时在耶路撒冷的以色列人守逾越节，又守除酵节七日。'),
('CUV', '历代志下', 14, 35, 18, '自从先知撒母耳以来，在以色列中没有守过这样的逾越节，以色列诸王也没有守过，像约西亚、祭司、利未人、在那里的犹大人，和以色列人，以及耶路撒冷居民所守的逾越节。'),
('CUV', '历代志下', 14, 35, 19, '这逾越节是约西亚作王十八年守的。'),
('CUV', '历代志下', 14, 35, 20, '这事以后，约西亚修完了殿，有埃及王尼哥上来，要攻击靠近伯拉河的迦基米施；约西亚出去抵挡他。'),
('CUV', '历代志下', 14, 35, 21, '他差遣使者来见约西亚，说：犹大王啊，我与你何干？我今日来不是要攻击你，乃是要攻击与我争战之家，并且神吩咐我速行，你不要干预神的事，免得他毁灭你，因为神是与我同在。'),
('CUV', '历代志下', 14, 35, 22, '约西亚却不肯转去离开他，改装要与他打仗，不听从神藉尼哥之口所说的话，便来到米吉多平原争战。'),
('CUV', '历代志下', 14, 35, 23, '弓箭手射中约西亚王。王对他的臣仆说：我受了重伤，你拉我出阵罢！'),
('CUV', '历代志下', 14, 35, 24, '他的臣仆扶他下了战车，上了次车，送他到耶路撒冷，他就死了，葬在他列祖的坟墓里。犹大人和耶路撒冷人都为他悲哀。'),
('CUV', '历代志下', 14, 35, 25, '耶利米为约西亚作哀歌。所有歌唱的男女也唱哀歌，追悼约西亚，直到今日；而且在以色列中成了定例。这歌载在哀歌书上。'),
('CUV', '历代志下', 14, 35, 26, '约西亚其余的事和他遵著耶和华律法上所记而行的善事，'),
('CUV', '历代志下', 14, 35, 27, '并他自始至终所行的，都写在以色列和犹大列王记上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '历代志下', 14, 36, 1, '国民立约西亚的儿子约哈斯在耶路撒冷接续他父作王。'),
('CUV', '历代志下', 14, 36, 2, '约哈斯登基的时候年二十三岁，在耶路撒冷作王三个月。'),
('CUV', '历代志下', 14, 36, 3, '埃及王在耶路撒冷废了他，又罚犹大国银子一百他连得，金子一他连得。'),
('CUV', '历代志下', 14, 36, 4, '埃及王尼哥立约哈斯的哥哥以利雅敬作犹大和耶路撒冷的王，改名叫约雅敬，又将约哈斯带到埃及去了。'),
('CUV', '历代志下', 14, 36, 5, '约雅敬登基的时候年二十五岁，在耶路撒冷作王十一年，行耶和华─他神眼中看为恶的事。'),
('CUV', '历代志下', 14, 36, 6, '巴比伦王尼布甲尼撒上来攻击他，用铜链锁著他，要将他带到巴比伦去。'),
('CUV', '历代志下', 14, 36, 7, '尼布甲尼撒又将耶和华殿里的器皿带到巴比伦，放在他神的庙里(或作自己的宫里)。'),
('CUV', '历代志下', 14, 36, 8, '约雅敬其余的事和他所行可憎的事，并他一切的行为，都写在以色列和犹大列王记上。他儿子约雅斤接续他作王。'),
('CUV', '历代志下', 14, 36, 9, '约雅斤登基的时候年八岁(王下二四章八节作十八岁)，在耶路撒冷作王三个月零十天，行耶和华眼中看为恶的事。'),
('CUV', '历代志下', 14, 36, 10, '过了一年，尼布甲尼撒差遣人将约雅斤和耶和华殿里各样宝贵的器皿带到巴比伦，就立约雅斤的叔叔（原文兄）西底家作犹大和耶路撒冷的王。'),
('CUV', '历代志下', 14, 36, 11, '西底家登基的时候年二十一岁，在耶路撒冷作王十一年，'),
('CUV', '历代志下', 14, 36, 12, '行耶和华─他神眼中看为恶的事。先知耶利米以耶和华的话劝他，他仍不在耶利米面前自卑。'),
('CUV', '历代志下', 14, 36, 13, '尼布甲尼撒曾使他指著神起誓，他却背叛，强项硬心，不归服耶和华─以色列的神。'),
('CUV', '历代志下', 14, 36, 14, '众祭司长和百姓也大大犯罪，效法外邦人一切可憎的事，污秽耶和华在耶路撒冷分别为圣的殿。'),
('CUV', '历代志下', 14, 36, 15, '耶和华─他们列祖的神因为爱惜自己的民和他的居所，从早起来差遣使者去警戒他们。'),
('CUV', '历代志下', 14, 36, 16, '他们却嘻笑神的使者，藐视他的言语，讥诮他的先知，以致耶和华的忿怒向他的百姓发作，无法可救。'),
('CUV', '历代志下', 14, 36, 17, '所以，耶和华使迦勒底人的王来攻击他们，在他们圣殿里用刀杀了他们的壮丁，不怜恤他们的少男处女、老人白叟。耶和华将他们都交在迦勒底王手里。'),
('CUV', '历代志下', 14, 36, 18, '迦勒底王将神殿里的大小器皿与耶和华殿里的财宝，并王和众首领的财宝，都带到巴比伦去了。'),
('CUV', '历代志下', 14, 36, 19, '迦勒底人焚烧神的殿，拆毁耶路撒冷的城墙，用火烧了城里的宫殿，毁坏了城里宝贵的器皿。'),
('CUV', '历代志下', 14, 36, 20, '凡脱离刀剑的，迦勒底王都掳到巴比伦去，作他和他子孙的仆婢，直到波斯国兴起来。'),
('CUV', '历代志下', 14, 36, 21, '这就应验耶和华藉耶利米口所说的话：地享受安息；因为地土荒凉便守安息，直满了七十年。'),
('CUV', '历代志下', 14, 36, 22, '波斯王古列元年，耶和华为要应验藉耶利米口所说的话，就激动波斯王古列的心，使他下诏通告全国，说：'),
('CUV', '历代志下', 14, 36, 23, '波斯王古列如此说：耶和华─天上的神已将天下万国赐给我，又嘱咐我在犹大的耶路撒冷为他建造殿宇。你们中间凡作他子民的，可以上去，愿耶和华─他的神与他同在。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯拉记', 15, 1, 1, '波斯王古列元年，耶和华为要应验藉耶利米口所说的话，就激动波斯王古列的心，使他下诏通告全国说：'),
('CUV', '以斯拉记', 15, 1, 2, '「波斯王古列如此说：『耶和华天上的神已将天下万国赐给我，又嘱咐我在犹大.的耶路撒冷为他建造殿宇。'),
('CUV', '以斯拉记', 15, 1, 3, '在你们中间凡作他子民的，可以上犹大的耶路撒冷，在耶路撒冷重建耶和华─以色列神的殿（只有他是神）。愿神与这人同在。'),
('CUV', '以斯拉记', 15, 1, 4, '凡剩下的人，无论寄居何处，那地的人要用金银、财物、牲畜帮助他，另外也要为耶路撒冷神的殿甘心献上礼物。』」'),
('CUV', '以斯拉记', 15, 1, 5, '于是，犹大和便雅悯的族长、祭司、利未人，就是一切被神激动他心的人，都起来要上耶路撒冷去建造耶和华的殿。'),
('CUV', '以斯拉记', 15, 1, 6, '他们四围的人就拿银器、金子、财物、牲畜、珍宝帮助他们（原文是坚固他们的手），另外还有甘心献的礼物。'),
('CUV', '以斯拉记', 15, 1, 7, '古列王也将耶和华殿的器皿拿出来，这器皿是尼布甲尼撒从耶路撒冷掠来、放在自己神之庙中的。'),
('CUV', '以斯拉记', 15, 1, 8, '波斯王古列派库官米提利达将这器皿拿出来，按数交给犹大的首领设巴萨。'),
('CUV', '以斯拉记', 15, 1, 9, '器皿的数目记在下面：金盘三十个，银盘一千个，刀二十九把，'),
('CUV', '以斯拉记', 15, 1, 10, '金碗三十个，银碗之次的四百一十个，别样的器皿一千件。'),
('CUV', '以斯拉记', 15, 1, 11, '金银器皿共有五千四百件。被掳的人从巴比伦上耶路撒冷的时候，设巴萨将这一切都带上来。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯拉记', 15, 2, 1, '巴比伦王尼布甲尼撒从前掳到巴比伦之犹大省的人，现在他们的子孙从被掳到之地回耶路撒冷和犹大，各归本城'),
('CUV', '以斯拉记', 15, 2, 2, '他们是同著所罗巴伯、耶书亚、尼希米、西莱雅、利来雅、末底改、必珊、米斯拔、比革瓦伊、利宏、巴拿回来的。'),
('CUV', '以斯拉记', 15, 2, 3, '以色列人民的数目记在下面：巴录的子孙二千一百七十二名；'),
('CUV', '以斯拉记', 15, 2, 4, '示法提雅的子孙三百七十二名；'),
('CUV', '以斯拉记', 15, 2, 5, '亚拉的子孙七百七十五名；'),
('CUV', '以斯拉记', 15, 2, 6, '巴哈•摩押的后裔，就是耶书亚和约押的子孙二千八百一十二名；'),
('CUV', '以斯拉记', 15, 2, 7, '以拦的子孙一千二百五十四名；'),
('CUV', '以斯拉记', 15, 2, 8, '萨土的子孙九百四十五名；'),
('CUV', '以斯拉记', 15, 2, 9, '萨改的子孙七百六十名；'),
('CUV', '以斯拉记', 15, 2, 10, '巴尼的子孙六百四十二名；'),
('CUV', '以斯拉记', 15, 2, 11, '比拜的子孙六百二十三名；'),
('CUV', '以斯拉记', 15, 2, 12, '押甲的子孙一千二百二十二名；'),
('CUV', '以斯拉记', 15, 2, 13, '亚多尼干的子孙六百六十六名；'),
('CUV', '以斯拉记', 15, 2, 14, '比革瓦伊的子孙二千零五十六名；'),
('CUV', '以斯拉记', 15, 2, 15, '亚丁的子孙四百五十四名；'),
('CUV', '以斯拉记', 15, 2, 16, '亚特的后裔，就是希西家的子孙，九十八名；'),
('CUV', '以斯拉记', 15, 2, 17, '比赛的子孙三百二十三名；'),
('CUV', '以斯拉记', 15, 2, 18, '约拉的子孙一百一十二名；'),
('CUV', '以斯拉记', 15, 2, 19, '哈顺的子孙二百二十三名；'),
('CUV', '以斯拉记', 15, 2, 20, '吉罢珥人九十五名；'),
('CUV', '以斯拉记', 15, 2, 21, '伯利恒人一百二十三名；'),
('CUV', '以斯拉记', 15, 2, 22, '尼陀法人五十六名；'),
('CUV', '以斯拉记', 15, 2, 23, '亚拿突人一百二十八名；'),
('CUV', '以斯拉记', 15, 2, 24, '亚斯玛弗人四十二名；'),
('CUV', '以斯拉记', 15, 2, 25, '基列•耶琳人、基非拉人、比录人共七百四十三名；'),
('CUV', '以斯拉记', 15, 2, 26, '拉玛人、迦巴人共六百二十一名；'),
('CUV', '以斯拉记', 15, 2, 27, '默玛人一百二十二名；'),
('CUV', '以斯拉记', 15, 2, 28, '伯特利人、艾人共二百二十三名；'),
('CUV', '以斯拉记', 15, 2, 29, '尼波人五十二名；'),
('CUV', '以斯拉记', 15, 2, 30, '末必人一百五十六名；'),
('CUV', '以斯拉记', 15, 2, 31, '别的以拦子孙一千二百五十四名；'),
('CUV', '以斯拉记', 15, 2, 32, '哈琳的子孙三百二十名；'),
('CUV', '以斯拉记', 15, 2, 33, '罗德人、哈第人、阿挪人共七百二十五名；'),
('CUV', '以斯拉记', 15, 2, 34, '耶利哥人三百四十五名；'),
('CUV', '以斯拉记', 15, 2, 35, '西拿人三千六百三十名。'),
('CUV', '以斯拉记', 15, 2, 36, '祭司：耶书亚家耶大雅的子孙九百七十三名；'),
('CUV', '以斯拉记', 15, 2, 37, '音麦的子孙一千零五十二名；'),
('CUV', '以斯拉记', 15, 2, 38, '巴施户珥的子孙一千二百四十七名；'),
('CUV', '以斯拉记', 15, 2, 39, '哈琳的子孙一千零一十七名。'),
('CUV', '以斯拉记', 15, 2, 40, '利未人：何达威雅的后裔，就是耶书亚和甲篾的子孙七十四名。'),
('CUV', '以斯拉记', 15, 2, 41, '歌唱的：亚萨的子孙一百二十八名。'),
('CUV', '以斯拉记', 15, 2, 42, '守门的：沙龙的子孙、亚特的子孙、达们的子孙、亚谷的子孙、哈底大的子孙、朔拜的子孙，共一百三十九名。'),
('CUV', '以斯拉记', 15, 2, 43, '尼提宁（就是殿役）：西哈的子孙、哈苏巴的子孙、答巴俄的子孙、'),
('CUV', '以斯拉记', 15, 2, 44, '基绿的子孙、西亚的子孙、巴顿的子孙、'),
('CUV', '以斯拉记', 15, 2, 45, '利巴拿的子孙、哈迦巴的子孙、亚谷的子孙、'),
('CUV', '以斯拉记', 15, 2, 46, '哈甲的子孙、萨买的子孙、哈难的子孙、'),
('CUV', '以斯拉记', 15, 2, 47, '吉德的子孙、迦哈的子孙、利亚雅的子孙、'),
('CUV', '以斯拉记', 15, 2, 48, '利汛的子孙、尼哥大的子孙、迦散的子孙、'),
('CUV', '以斯拉记', 15, 2, 49, '乌撒的子孙、巴西亚的子孙、比赛的子孙、'),
('CUV', '以斯拉记', 15, 2, 50, '押拿的子孙、米乌宁的子孙、尼普心的子孙、'),
('CUV', '以斯拉记', 15, 2, 51, '巴卜的子孙、哈古巴的子孙、哈忽的子孙、'),
('CUV', '以斯拉记', 15, 2, 52, '巴洗律的子孙、米希大的子孙、哈沙的子孙、'),
('CUV', '以斯拉记', 15, 2, 53, '巴柯的子孙、西西拉的子孙、答玛的子孙、'),
('CUV', '以斯拉记', 15, 2, 54, '尼细亚的子孙、哈提法的子孙。'),
('CUV', '以斯拉记', 15, 2, 55, '所罗门仆人的后裔，就是琐太的子孙、琐斐列的子孙、比路大的子孙、'),
('CUV', '以斯拉记', 15, 2, 56, '雅拉的子孙、达昆的子孙、吉德的子孙、'),
('CUV', '以斯拉记', 15, 2, 57, '示法提雅的子孙、哈替的子孙、玻黑列哈斯巴音的子孙、亚米的子孙。'),
('CUV', '以斯拉记', 15, 2, 58, '尼提宁和所罗门仆人的后裔共三百九十二名。'),
('CUV', '以斯拉记', 15, 2, 59, '从特•米拉、特•哈萨、基绿、押但、音麦上来的，不能指明他们的宗族谱系是以色列人不是；'),
('CUV', '以斯拉记', 15, 2, 60, '他们是第来雅的子孙、多比雅的子孙、尼哥大的子孙，共六百五十二名。'),
('CUV', '以斯拉记', 15, 2, 61, '祭司中，哈巴雅的子孙、哈哥斯的子孙、巴西莱的子孙；因为他们的先祖娶了基列人巴西莱的女儿为妻，所以起名叫巴西莱。'),
('CUV', '以斯拉记', 15, 2, 62, '这三家的人在族谱之中寻查自己的谱系，却寻不著，因此算为不洁，不准供祭司的职任。'),
('CUV', '以斯拉记', 15, 2, 63, '省长对他们说：「不可吃至圣的物，直到有用乌陵和土明决疑的祭司兴起来。」'),
('CUV', '以斯拉记', 15, 2, 64, '会众共有四万二千三百六十名。'),
('CUV', '以斯拉记', 15, 2, 65, '此外，还有他们的仆婢七千三百三十七名，又有歌唱的男女二百名。'),
('CUV', '以斯拉记', 15, 2, 66, '他们有马七百三十六匹，骡子二百四十五匹，'),
('CUV', '以斯拉记', 15, 2, 67, '骆驼四百三十五只，驴六千七百二十匹。'),
('CUV', '以斯拉记', 15, 2, 68, '有些族长到了耶路撒冷耶和华殿的地方，便为神的殿甘心献上礼物，要重新建造。'),
('CUV', '以斯拉记', 15, 2, 69, '他们量力捐入工程库的金子六万一千达利克，银子五千弥拿，并祭司的礼服一百件。'),
('CUV', '以斯拉记', 15, 2, 70, '于是祭司、利未人、民中的一些人、歌唱的、守门的、尼提宁，并以色列众人，各住在自己的城里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯拉记', 15, 3, 1, '到了七月，以色列人住在各城；那时他们如同一人，聚集在耶路撒冷。'),
('CUV', '以斯拉记', 15, 3, 2, '约萨达的儿子耶书亚和他的弟兄众祭司，并撒拉铁的儿子所罗巴伯与他的弟兄，都起来建筑以色列神的坛，要照神人摩西律法书上所写的，在坛上献燔祭。'),
('CUV', '以斯拉记', 15, 3, 3, '他们在原有的根基上筑坛，因惧怕邻国的民，又在其上向耶和华早晚献燔祭，'),
('CUV', '以斯拉记', 15, 3, 4, '又照律法书上所写的守住棚节，按数照例献每日所当献的燔祭；'),
('CUV', '以斯拉记', 15, 3, 5, '其后献常献的燔祭，并在月朔与耶和华的一切圣节献祭，又向耶和华献各人的甘心祭。'),
('CUV', '以斯拉记', 15, 3, 6, '从七月初一日起，他们就向耶和华献燔祭。但耶和华殿的根基尚未立定。'),
('CUV', '以斯拉记', 15, 3, 7, '他们又将银子给石匠、木匠，把粮食、酒、油给西顿人、推罗人，使他们将香柏树从利巴嫩运到海里，浮海运到约帕，是照波斯王古列所允准的。'),
('CUV', '以斯拉记', 15, 3, 8, '百姓到了耶路撒冷神殿的地方。第二年二月，撒拉铁的儿子所罗巴伯，约萨达的儿子耶书亚和其余的弟兄，就是祭司、利未人，并一切被掳归回耶路撒冷的人，都兴工建造；又派利未人，从二十岁以外的，督理建造耶和华殿的工作。'),
('CUV', '以斯拉记', 15, 3, 9, '于是犹大（在二章四十节作何达威雅）的后裔，就是耶书亚和他的子孙与弟兄，甲篾和他的子孙，利未人希拿达的子孙与弟兄，都一同起来，督理那在神殿做工的人。'),
('CUV', '以斯拉记', 15, 3, 10, '匠人立耶和华殿根基的时候，祭司皆穿礼服吹号，亚萨的子孙利未人敲钹，照以色列王大卫所定的例，都站著赞美耶和华。'),
('CUV', '以斯拉记', 15, 3, 11, '他们彼此唱和，赞美称谢耶和华说：他本为善，他向以色列人永发慈爱。他们赞美耶和华的时候，众民大声呼喊，因耶和华殿的根基已经立定。'),
('CUV', '以斯拉记', 15, 3, 12, '然而有许多祭司、利未人、族长，就是见过旧殿的老年人，现在亲眼看见立这殿的根基，便大声哭号，也有许多人大声欢呼，'),
('CUV', '以斯拉记', 15, 3, 13, '甚至百姓不能分辨欢呼的声音和哭号的声音；因为众人大声呼喊，声音听到远处。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯拉记', 15, 4, 1, '犹大和便雅悯的敌人听说被掳归回的人为耶和华─以色列的神建造殿宇，'),
('CUV', '以斯拉记', 15, 4, 2, '就去见所罗巴伯和以色列的族长，对他们说：「请容我们与你们一同建造；因为我们寻求你们的神，与你们一样。自从亚述王以撒哈顿带我们上这地以来，我们常祭祀神。」'),
('CUV', '以斯拉记', 15, 4, 3, '但所罗巴伯、耶书亚，和其余以色列的族长对他们说：「我们建造神的殿与你们无干，我们自己为耶和华─以色列的神协力建造，是照波斯王古列所吩咐的。」'),
('CUV', '以斯拉记', 15, 4, 4, '那地的民，就在犹大人建造的时候，使他们的手发软，扰乱他们；'),
('CUV', '以斯拉记', 15, 4, 5, '从波斯王古列年间，直到波斯王大利乌登基的时候，贿买谋士，要败坏他们的谋算。'),
('CUV', '以斯拉记', 15, 4, 6, '在亚哈随鲁才登基的时候，上本控告犹大和耶路撒冷的居民。'),
('CUV', '以斯拉记', 15, 4, 7, '亚达薛西年间，比施兰、米特利达、他别，和他们的同党上本奏告波斯王亚达薛西。本章是用亚兰文字，亚兰方言。'),
('CUV', '以斯拉记', 15, 4, 8, '省长利宏、书记伸帅要控告耶路撒冷人，也上本奏告亚达薛西王。'),
('CUV', '以斯拉记', 15, 4, 9, '省长利宏、书记伸帅，和同党的底拿人、亚法萨提迦人、他毗拉人、亚法撒人、亚基卫人、巴比伦人、书珊迦人、底亥人、以拦人，'),
('CUV', '以斯拉记', 15, 4, 10, '和尊大的亚斯那巴所迁移、安置在撒玛利亚城，并大河西一带地方的人等，'),
('CUV', '以斯拉记', 15, 4, 11, '上奏亚达薛西王说：「河西的臣民云云：'),
('CUV', '以斯拉记', 15, 4, 12, '王该知道，从王那里上到我们这里的犹大人，已经到耶路撒冷重建这反叛恶劣的城，筑立根基，建造城墙。'),
('CUV', '以斯拉记', 15, 4, 13, '如今王该知道，他们若建造这城，城墙完毕就不再与王进贡，交课，纳税，终久王必受亏损。'),
('CUV', '以斯拉记', 15, 4, 14, '我们既食御盐，不忍见王吃亏，因此奏告于王。'),
('CUV', '以斯拉记', 15, 4, 15, '请王考察先王的实录，必在其上查知这城是反叛的城，与列王和各省有害；自古以来，其中常有悖逆的事，因此这城曾被拆毁。'),
('CUV', '以斯拉记', 15, 4, 16, '我们谨奏王知，这城若再建造，城墙完毕，河西之地王就无分了。」'),
('CUV', '以斯拉记', 15, 4, 17, '那时王谕覆省长利宏、书记伸帅，和他们的同党，就是住撒玛利亚并河西一带地方的人，说：愿你们平安云云。'),
('CUV', '以斯拉记', 15, 4, 18, '你们所上的本，已经明读在我面前。'),
('CUV', '以斯拉记', 15, 4, 19, '我已命人考查，得知此城古来果然背叛列王，其中常有反叛悖逆的事。'),
('CUV', '以斯拉记', 15, 4, 20, '从前耶路撒冷也有大君王统管河西全地，人就给他们进贡，交课，纳税。'),
('CUV', '以斯拉记', 15, 4, 21, '现在你们要出告示命这些人停工，使这城不得建造，等我降旨。'),
('CUV', '以斯拉记', 15, 4, 22, '你们当谨慎，不可迟延，为何容害加重，使王受亏损呢？」'),
('CUV', '以斯拉记', 15, 4, 23, '亚达薛西王的上谕读在利宏和书记伸帅，并他们的同党面前，他们就急忙往耶路撒冷去见犹大人，用势力强迫他们停工。'),
('CUV', '以斯拉记', 15, 4, 24, '于是，在耶路撒冷神殿的工程就停止了，直停到波斯王大利乌第二年。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯拉记', 15, 5, 1, '那时，先知哈该和易多的孙子撒迦利亚奉以色列神的名向犹大和耶路撒冷的犹大人说劝勉的话。'),
('CUV', '以斯拉记', 15, 5, 2, '于是撒拉铁的儿子所罗巴伯和约萨达的儿子耶书亚都起来动手建造耶路撒冷神的殿，有神的先知在那里帮助他们。'),
('CUV', '以斯拉记', 15, 5, 3, '当时河西的总督达乃和示他•波斯乃，并他们的同党来问说：「谁降旨让你们建造这殿，修成这墙呢？」'),
('CUV', '以斯拉记', 15, 5, 4, '我们便告诉他们建造这殿的人叫甚么名字。'),
('CUV', '以斯拉记', 15, 5, 5, '神的眼目看顾犹大的长老，以致总督等没有叫他们停工，直到这事奏告大利乌，得著他的回谕。'),
('CUV', '以斯拉记', 15, 5, 6, '河西的总督达乃和示他•波斯乃，并他们的同党，就是住河西的亚法萨迦人，上本奏告大利乌王。'),
('CUV', '以斯拉记', 15, 5, 7, '本上写著说：愿大利乌王诸事平安。'),
('CUV', '以斯拉记', 15, 5, 8, '王该知道，我们往犹大省去，到了至大神的殿，这殿是用大石建造的。梁木插入墙内，工作甚速，他们手下亨通。'),
('CUV', '以斯拉记', 15, 5, 9, '我们就问那些长老说：『谁降旨让你们建造这殿，修成这墙呢？』'),
('CUV', '以斯拉记', 15, 5, 10, '又问他们的名字，要记录他们首领的名字，奏告于王。'),
('CUV', '以斯拉记', 15, 5, 11, '他们回答说：『我们是天地之神的仆人，重建前多年所建造的殿，就是以色列的一位大君王建造修成的。'),
('CUV', '以斯拉记', 15, 5, 12, '只因我们列祖惹天上的神发怒，神把他们交在迦勒底人巴比伦王尼布甲尼撒的手中，他就拆毁这殿，又将百姓掳到巴比伦。'),
('CUV', '以斯拉记', 15, 5, 13, '然而巴比伦王古列元年，他降旨允准建造神的这殿。'),
('CUV', '以斯拉记', 15, 5, 14, '神殿中的金、银器皿，就是尼布甲尼撒从耶路撒冷的殿中掠去带到巴比伦庙里的，古列王从巴比伦庙里取出来，交给派为省长的，名叫设巴萨，'),
('CUV', '以斯拉记', 15, 5, 15, '对他说可以将这些器皿带去，放在耶路撒冷的殿中，在原处建造神的殿。'),
('CUV', '以斯拉记', 15, 5, 16, '于是这设巴萨来建立耶路撒冷神殿的根基。这殿从那时直到如今尚未造成。』'),
('CUV', '以斯拉记', 15, 5, 17, '现在王若以为美，请察巴比伦王的府库，看古列王降旨允准在耶路撒冷建造神的殿没有，王的心意如何？请降旨晓谕我们。」')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯拉记', 15, 6, 1, '于是大利乌王降旨，要寻察典籍库内，就是在巴比伦藏宝物之处；'),
('CUV', '以斯拉记', 15, 6, 2, '在玛代省亚马他城的宫内寻得一卷，其中记著说：'),
('CUV', '以斯拉记', 15, 6, 3, '古列王元年，他降旨论到耶路撒冷神的殿，要建造这殿为献祭之处，坚立殿的根基。殿高六十肘，宽六十肘，'),
('CUV', '以斯拉记', 15, 6, 4, '用三层大石头，一层新木头，经费要出于王库；'),
('CUV', '以斯拉记', 15, 6, 5, '并且神殿的金银器皿，就是尼布甲尼撒从耶路撒冷的殿中掠到巴比伦的，要归还带到耶路撒冷的殿中，各按原处放在神的殿里。'),
('CUV', '以斯拉记', 15, 6, 6, '「现在河西的总督达乃和示他波斯乃，并你们的同党，就是住河西的亚法萨迦人，你们当远离他们。'),
('CUV', '以斯拉记', 15, 6, 7, '不要拦阻神殿的工作，任凭犹大人的省长和犹大人的长老在原处建造神的这殿。'),
('CUV', '以斯拉记', 15, 6, 8, '我又降旨，吩咐你们向犹大人的长老为建造神的殿当怎样行，就是从河西的款项中，急速拨取贡银作他们的经费，免得耽误工作。'),
('CUV', '以斯拉记', 15, 6, 9, '他们与天上的神献燔祭所需用的公牛犊、公绵羊、绵羊羔，并所用的麦子、盐、酒、油，都要照耶路撒冷祭司的话，每日供给他们，不得有误；'),
('CUV', '以斯拉记', 15, 6, 10, '好叫他们献馨香的祭给天上的神，又为王和王众子的寿命祈祷。'),
('CUV', '以斯拉记', 15, 6, 11, '我再降旨，无论谁更改这命令，必从他房屋中拆出一根梁来，把他举起，悬在其上，又使他的房屋成为粪堆。'),
('CUV', '以斯拉记', 15, 6, 12, '若有王和民伸手更改这命令，拆毁这殿，愿那使耶路撒冷的殿作为他名居所的神将他们灭绝。我─大利乌降这旨意，当速速遵行。」'),
('CUV', '以斯拉记', 15, 6, 13, '于是，河西总督达乃和示他•波斯乃，并他们的同党，因大利乌王所发的命令，就急速遵行。'),
('CUV', '以斯拉记', 15, 6, 14, '犹大长老因先知哈该和易多的孙子撒迦利亚所说劝勉的话就建造这殿，凡事亨通。他们遵著以色列神的命令和波斯王古列、大利乌、亚达薛西的旨意，建造完毕。'),
('CUV', '以斯拉记', 15, 6, 15, '大利乌王第六年，亚达月初三日，这殿修成了。'),
('CUV', '以斯拉记', 15, 6, 16, '以色列的祭司和利未人，并其余被掳归回的人都欢欢喜喜地行奉献神殿的礼。'),
('CUV', '以斯拉记', 15, 6, 17, '行奉献神殿的礼就献公牛一百只，公绵羊二百只，绵羊羔四百只，又照以色列支派的数目献公山羊十二只，为以色列众人作赎罪祭；'),
('CUV', '以斯拉记', 15, 6, 18, '且派祭司和利未人按著班次在耶路撒冷事奉神，是照摩西律法书上所写的。'),
('CUV', '以斯拉记', 15, 6, 19, '正月十四日，被掳归回的人守逾越节。'),
('CUV', '以斯拉记', 15, 6, 20, '原来，祭司和利未人一同自洁，无一人不洁净。利未人为被掳归回的众人和他们的弟兄众祭司，并为自己宰逾越节的羊羔。'),
('CUV', '以斯拉记', 15, 6, 21, '从掳到之地归回的以色列人和一切除掉所染外邦人污秽、归附他们、要寻求耶和华─以色列神的人都吃这羊羔，'),
('CUV', '以斯拉记', 15, 6, 22, '欢欢喜喜地守除酵节七日；因为耶和华使他们欢喜，又使亚述王的心转向他们，坚固他们的手，作以色列神殿的工程。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯拉记', 15, 7, 1, '这事以后，波斯王亚达薛西年间，有个以斯拉，他是西莱雅的儿子，西莱雅是亚撒利雅的儿子，亚撒利雅是希勒家的儿子，'),
('CUV', '以斯拉记', 15, 7, 2, '希勒家是沙龙的儿子，沙龙是撒督的儿子，撒督是亚希突的儿子，'),
('CUV', '以斯拉记', 15, 7, 3, '亚希突是亚玛利雅的儿子，亚玛利雅是亚撒利雅的儿子，亚撒利雅是米拉约的儿子，'),
('CUV', '以斯拉记', 15, 7, 4, '米拉约是西拉希雅的儿子，西拉希雅是乌西的儿子，乌西是布基的儿子，'),
('CUV', '以斯拉记', 15, 7, 5, '布基是亚比书的儿子，亚比书是非尼哈的儿子，非尼哈是以利亚撒的儿子，以利亚撒是大祭司亚伦的儿子。'),
('CUV', '以斯拉记', 15, 7, 6, '这以斯拉从巴比伦上来，他是敏捷的文士，通达耶和华─以色列神所赐摩西的律法书。王允准他一切所求的，是因耶和华─他神的手帮助他。'),
('CUV', '以斯拉记', 15, 7, 7, '亚达薛西王第七年，以色列人、祭司、利未人、歌唱的、守门的、尼提宁，有上耶路撒冷的。'),
('CUV', '以斯拉记', 15, 7, 8, '王第七年五月，以斯拉到了耶路撒冷。'),
('CUV', '以斯拉记', 15, 7, 9, '正月初一日，他从巴比伦起程；因他神施恩的手帮助他，五月初一日就到了耶路撒冷。'),
('CUV', '以斯拉记', 15, 7, 10, '以斯拉定志考究遵行耶和华的律法，又将律例典章教训以色列人。'),
('CUV', '以斯拉记', 15, 7, 11, '祭司以斯拉是通达耶和华诫命和赐以色列之律例的文士。亚达薛西王赐给他们谕旨，上面写著说：'),
('CUV', '以斯拉记', 15, 7, 12, '「诸王之王亚达薛西，达于祭司以斯拉通达天上神律法大德的文士，云云。'),
('CUV', '以斯拉记', 15, 7, 13, '住在我国中的以色列人、祭司、利未人，凡甘心上耶路撒冷去的，我降旨准他们与你同去。'),
('CUV', '以斯拉记', 15, 7, 14, '王与七个谋士既然差你去，照你手中神的律法书察问犹大和耶路撒冷的景况；'),
('CUV', '以斯拉记', 15, 7, 15, '又带金银，就是王和谋士甘心献给住耶路撒冷、以色列神的，'),
('CUV', '以斯拉记', 15, 7, 16, '并带你在巴比伦全省所得的金银，和百姓、祭司乐意献给耶路撒冷─他们神殿的礼物。'),
('CUV', '以斯拉记', 15, 7, 17, '所以你当用这金银，急速买公牛、公绵羊、绵羊羔，和同献的素祭奠祭之物，献在耶路撒冷─你们神殿的坛上。'),
('CUV', '以斯拉记', 15, 7, 18, '剩下的金银，你和你的弟兄看著怎样好，就怎样用，总要遵著你们神的旨意。'),
('CUV', '以斯拉记', 15, 7, 19, '所交给你神殿中使用的器皿，你要交在耶路撒冷神面前。'),
('CUV', '以斯拉记', 15, 7, 20, '你神殿里若再有需用的经费，你可以从王的府库里支取。'),
('CUV', '以斯拉记', 15, 7, 21, '「我─亚达薛西王又降旨与河西的一切库官，说：『通达天上神律法的文士祭司以斯拉，无论向你们要甚么，你们要速速地备办，'),
('CUV', '以斯拉记', 15, 7, 22, '就是银子直到一百他连得，麦子一百柯珥，酒一百罢特，油一百罢特，盐不计其数，也要给他。'),
('CUV', '以斯拉记', 15, 7, 23, '凡天上之神所吩咐的，当为天上神的殿详细办理。为何使忿怒临到王和王众子的国呢？'),
('CUV', '以斯拉记', 15, 7, 24, '我又晓谕你们，至于祭司、利未人、歌唱的、守门的，和尼提宁，并在神殿当差的人，不可叫他们进贡，交课，纳税。』'),
('CUV', '以斯拉记', 15, 7, 25, '「以斯拉啊，要照著你神赐你的智慧，将所有明白你神律法的人立为士师、审判官，治理河西的百姓，使他们教训一切不明白神律法的人。'),
('CUV', '以斯拉记', 15, 7, 26, '凡不遵行你神律法和王命令的人就当速速定他的罪，或治死，或充军，或抄家，或囚禁。」'),
('CUV', '以斯拉记', 15, 7, 27, '以斯拉说：耶和华─我们列祖的神是应当称颂的！因他使王起这心意修饰耶路撒冷耶和华的殿，'),
('CUV', '以斯拉记', 15, 7, 28, '又在王和谋士，并大能的军长面前施恩于我。因耶和华─我神的手帮助我，我就得以坚强，从以色列中招聚首领，与我一同上来。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯拉记', 15, 8, 1, '当亚达薛西王年间，同我从巴比伦上来的人，他们的族长和他们的家谱记在下面：'),
('CUV', '以斯拉记', 15, 8, 2, '属非尼哈的子孙有革顺；属以他玛的子孙有但以理；属大卫的子孙有哈突；'),
('CUV', '以斯拉记', 15, 8, 3, '属巴录的后裔，就是示迦尼的子孙有撒迦利亚，同著他，按家谱计算，男丁一百五十人；'),
('CUV', '以斯拉记', 15, 8, 4, '属巴哈•摩押的子孙有西拉希雅的儿子以利约乃，同著他有男丁二百；'),
('CUV', '以斯拉记', 15, 8, 5, '属示迦尼的子孙有雅哈悉的儿子，同著他有男丁三百；'),
('CUV', '以斯拉记', 15, 8, 6, '属亚丁的子孙有约拿单的儿子以别，同著他有男丁五十；'),
('CUV', '以斯拉记', 15, 8, 7, '属以拦的子孙有亚他利雅的儿子耶筛亚，同著他有男丁七十；'),
('CUV', '以斯拉记', 15, 8, 8, '属示法提雅的子孙有米迦勒的儿子西巴第雅，同著他有男丁八十；'),
('CUV', '以斯拉记', 15, 8, 9, '属约押的子孙有耶歇的儿子俄巴底亚，同著他有男丁二百一十八；'),
('CUV', '以斯拉记', 15, 8, 10, '属示罗密的子孙有约细斐的儿子，同著他有男丁一百六十；'),
('CUV', '以斯拉记', 15, 8, 11, '属比拜的子孙有比拜的儿子撒迦利亚，同著他有男丁二十八；'),
('CUV', '以斯拉记', 15, 8, 12, '属押甲的子孙有哈加坦的儿子约哈难，同著他有男丁一百一十；'),
('CUV', '以斯拉记', 15, 8, 13, '属亚多尼干的子孙，就是末尾的，他们的名字是以利法列、耶利、示玛雅，同著他们有男丁六十；'),
('CUV', '以斯拉记', 15, 8, 14, '属比革瓦伊的子孙有乌太和撒布，同著他们有男丁七十。'),
('CUV', '以斯拉记', 15, 8, 15, '我招聚这些人在流入亚哈瓦的河边，我们在那里住了三日。我查看百姓和祭司，见没有利未人在那里，'),
('CUV', '以斯拉记', 15, 8, 16, '就召首领以利以谢、亚列、示玛雅、以利拿单、雅立、以利拿单、拿单、撒迦利亚、米书兰，又召教习约雅立和以利拿单。'),
('CUV', '以斯拉记', 15, 8, 17, '我打发他们往迦西斐雅地方去见那里的首领易多，又告诉他们当向易多和他的弟兄尼提宁说甚么话叫他们为我们神的殿带使用的人来。'),
('CUV', '以斯拉记', 15, 8, 18, '蒙我们神施恩的手帮助我们，他们在以色列的曾孙、利未的孙子、抹利的后裔中带一个通达人来；还有示利比和他的众子与弟兄共一十八人。'),
('CUV', '以斯拉记', 15, 8, 19, '又有哈沙比雅，同著他有米拉利的子孙耶筛亚，并他的众子和弟兄共二十人。'),
('CUV', '以斯拉记', 15, 8, 20, '从前大卫和众首领派尼提宁服事利未人，现在从这尼提宁中也带了二百二十人来，都是按名指定的。'),
('CUV', '以斯拉记', 15, 8, 21, '那时，我在亚哈瓦河边宣告禁食，为要在我们神面前克苦己心，求他使我们和妇人孩子，并一切所有的，都得平坦的道路。'),
('CUV', '以斯拉记', 15, 8, 22, '我求王拨步兵马兵帮助我们抵挡路上的仇敌，本以为羞耻；因我曾对王说：「我们神施恩的手必帮助一切寻求他的；但他的能力和忿怒必攻击一切离弃他的。」'),
('CUV', '以斯拉记', 15, 8, 23, '所以我们禁食祈求我们的神，他就应允了我们。'),
('CUV', '以斯拉记', 15, 8, 24, '我分派祭司长十二人，就是示利比、哈沙比雅，和他们的弟兄十人，'),
('CUV', '以斯拉记', 15, 8, 25, '将王和谋士、军长，并在那里的以色列众人为我们神殿所献的金银和器皿，都秤了交给他们。'),
('CUV', '以斯拉记', 15, 8, 26, '我秤了交在他们手中的银子有六百五十他连得；银器重一百他连得；金子一百他连得；'),
('CUV', '以斯拉记', 15, 8, 27, '金碗二十个，重一千达利克；上等光铜的器皿两个，宝贵如金。'),
('CUV', '以斯拉记', 15, 8, 28, '我对他们说：你们归耶和华为圣，器皿也为圣；金银是甘心献给耶和华─你们列祖之神的。'),
('CUV', '以斯拉记', 15, 8, 29, '你们当警醒看守，直到你们在耶路撒冷耶和华殿的库内，在祭司长和利未族长，并以色列的各族长面前过了秤。」'),
('CUV', '以斯拉记', 15, 8, 30, '于是，祭司、利未人按著分量接受金银和器皿，要带到耶路撒冷我们神的殿里。'),
('CUV', '以斯拉记', 15, 8, 31, '正月十二日，我们从亚哈瓦河边起行，要往耶路撒冷去。我们神的手保佑我们，救我们脱离仇敌和路上埋伏之人的手。'),
('CUV', '以斯拉记', 15, 8, 32, '我们到了耶路撒冷，在那里住了三日。'),
('CUV', '以斯拉记', 15, 8, 33, '第四日，在我们神的殿里把金银和器皿都秤了，交在祭司乌利亚的儿子米利末的手中。同著他有非尼哈的儿子以利亚撒，还有利未人耶书亚的儿子约撒拔和宾内的儿子挪亚底。'),
('CUV', '以斯拉记', 15, 8, 34, '当时都点了数目，按著分量写在册上。'),
('CUV', '以斯拉记', 15, 8, 35, '从掳到之地归回的人向以色列的神献燔祭，就是为以色列众人献公牛十二只，公绵羊九十六只，绵羊羔七十七只，又献公山羊十二只作赎罪祭，这都是向耶和华焚献的。'),
('CUV', '以斯拉记', 15, 8, 36, '他们将王的谕旨交给王所派的总督与河西的省长，他们就帮助百姓，又供给神殿里所需用的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯拉记', 15, 9, 1, '这事做完了，众首领来见我，说：「以色列民和祭司并利未人，没有离绝迦南人、赫人、比利洗人、耶布斯人、亚扪人、摩押人、埃及人、亚摩利人，仍效法这些国的民，行可憎的事。'),
('CUV', '以斯拉记', 15, 9, 2, '因他们为自己和儿子娶了这些外邦女子为妻，以致圣洁的种类和这些国的民混杂；而且首领和官长在这事上为罪魁。」'),
('CUV', '以斯拉记', 15, 9, 3, '我一听见这事，就撕裂衣服和外袍，拔了头发和胡须，惊惧忧闷而坐。'),
('CUV', '以斯拉记', 15, 9, 4, '凡为以色列神言语战兢的，都因这被掳归回之人所犯的罪聚集到我这里来。我就惊惧忧闷而坐，直到献晚祭的时候。'),
('CUV', '以斯拉记', 15, 9, 5, '献晚祭的时候我起来，心中愁苦，穿著撕裂的衣袍，双膝跪下向耶和华─我的神举手，'),
('CUV', '以斯拉记', 15, 9, 6, '说：我的神啊，我抱愧蒙羞，不敢向我神仰面；因为我们的罪孽灭顶，我们的罪恶滔天。'),
('CUV', '以斯拉记', 15, 9, 7, '从我们列祖直到今日，我们的罪恶甚重；因我们的罪孽，我们和君王、祭司都交在外邦列王的手中，杀害、掳掠、抢夺、脸上蒙羞正如今日的光景。'),
('CUV', '以斯拉记', 15, 9, 8, '现在耶和华─我们的神暂且施恩与我们，给我们留些逃脱的人，使我们安稳如钉子钉在他的圣所，我们的神好光照我们的眼目，使我们在受辖制之中稍微复兴。'),
('CUV', '以斯拉记', 15, 9, 9, '我们是奴仆，然而在受辖制之中，我们的神仍没有丢弃我们，在波斯王眼前向我们施恩，叫我们复兴，能重建我们神的殿，修其毁坏之处，使我们在犹大和耶路撒冷有墙垣。'),
('CUV', '以斯拉记', 15, 9, 10, '「我们的神啊，既是如此，我们还有甚么话可说呢？因为我们已经离弃你的命令，'),
('CUV', '以斯拉记', 15, 9, 11, '就是你藉你仆人众先知所吩咐的说：『你们要去得为业之地是污秽之地；因列国之民的污秽和可憎的事，叫全地从这边直到那边满了污秽。'),
('CUV', '以斯拉记', 15, 9, 12, '所以不可将你们的女儿嫁他们的儿子，也不可为你们的儿子娶他们的女儿，永不可求他们的平安和他们的利益，这样你们就可以强盛，吃这地的美物，并遗留这地给你们的子孙永远为业。』'),
('CUV', '以斯拉记', 15, 9, 13, '神啊，我们因自己的恶行和大罪，遭遇了这一切的事，并且你刑罚我们轻于我们罪所当得的，又给我们留下这些人。'),
('CUV', '以斯拉记', 15, 9, 14, '我们岂可再违背你的命令，与这行可憎之事的民结亲呢？若这样行，你岂不向我们发怒，将我们灭绝，以致没有一个剩下逃脱的人吗？'),
('CUV', '以斯拉记', 15, 9, 15, '耶和华─以色列的神啊，因你是公义的，我们这剩下的人才得逃脱，正如今日的光景。看哪，我们在你面前有罪恶，因此无人在你面前站立得住。」')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯拉记', 15, 10, 1, '以斯拉祷告，认罪，哭泣，俯伏在神殿前的时候，有以色列中的男女孩童聚集到以斯拉那里，成了大会，众民无不痛哭。'),
('CUV', '以斯拉记', 15, 10, 2, '属以拦的子孙、耶歇的儿子示迦尼对以斯拉说：我们在此地娶了外邦女子为妻，干犯了我们的神，然而以色列人还有指望。'),
('CUV', '以斯拉记', 15, 10, 3, '现在当与我们的神立约，休这一切的妻，离绝他们所生的，照著我主和那因神命令战兢之人所议定的，按律法而行。'),
('CUV', '以斯拉记', 15, 10, 4, '你起来，这是你当办的事，我们必帮助你，你当奋勉而行。」'),
('CUV', '以斯拉记', 15, 10, 5, '以斯拉便起来，使祭司长和利未人，并以色列众人起誓说，必照这话去行；他们就起了誓。'),
('CUV', '以斯拉记', 15, 10, 6, '以斯拉从神殿前起来，进入以利亚实的儿子约哈难的屋里，到了那里不吃饭，也不喝水；因为被掳归回之人所犯的罪，心里悲伤。'),
('CUV', '以斯拉记', 15, 10, 7, '他们通告犹大和耶路撒冷被掳归回的人，叫他们在耶路撒冷聚集。'),
('CUV', '以斯拉记', 15, 10, 8, '凡不遵首领和长老所议定、三日之内不来的，就必抄他的家，使他离开被掳归回之人的会。'),
('CUV', '以斯拉记', 15, 10, 9, '于是，犹大和便雅悯众人，三日之内都聚集在耶路撒冷。那日正是九月二十日，众人都坐在神殿前的宽阔处；因这事，又因下大雨，就都战兢。'),
('CUV', '以斯拉记', 15, 10, 10, '祭司以斯拉站起来，对他们说：你们有罪了；因你们娶了外邦的女子为妻，增添以色列人的罪恶。'),
('CUV', '以斯拉记', 15, 10, 11, '现在当向耶和华─你们列祖的神认罪，遵行他的旨意，离绝这些国的民和外邦的女子。」'),
('CUV', '以斯拉记', 15, 10, 12, '会众都大声回答说：我们必照著你的话行，'),
('CUV', '以斯拉记', 15, 10, 13, '只是百姓众多，又逢大雨的时令，我们不能站在外头，这也不是一两天办完的事，因我们在这事上犯了大罪；'),
('CUV', '以斯拉记', 15, 10, 14, '不如为全会众派首领办理。凡我们城邑中娶外邦女子为妻的，当按所定的日期，同著本城的长老和士师而来，直到办完这事，神的烈怒就转离我们了。」'),
('CUV', '以斯拉记', 15, 10, 15, '惟有亚撒黑的儿子约拿单，特瓦的儿子雅哈谢阻挡（或译：总办）这事，并有米书兰和利未人沙比太帮助他们。'),
('CUV', '以斯拉记', 15, 10, 16, '被掳归回的人如此而行。祭司以斯拉和些族长按著宗族都指名见派；在十月初一日，一同在座查办这事，'),
('CUV', '以斯拉记', 15, 10, 17, '到正月初一日，才查清娶外邦女子的人数。'),
('CUV', '以斯拉记', 15, 10, 18, '在祭司中查出娶外邦女子为妻的，就是耶书亚的子孙约萨达的儿子，和他弟兄玛西雅、以利以谢、雅立、基大利；'),
('CUV', '以斯拉记', 15, 10, 19, '他们便应许必休他们的妻。他们因有罪，就献群中的一只公绵羊赎罪。'),
('CUV', '以斯拉记', 15, 10, 20, '音麦的子孙中，有哈拿尼、西巴第雅。'),
('CUV', '以斯拉记', 15, 10, 21, '哈琳的子孙中，有玛西雅、以利雅、示玛雅、耶歇、乌西雅。'),
('CUV', '以斯拉记', 15, 10, 22, '巴施户珥的子孙中，有以利约乃、玛西雅、以实玛利、拿坦业、约撒拔、以利亚撒。'),
('CUV', '以斯拉记', 15, 10, 23, '利未人中，有约撒拔、示每、基拉雅（基拉雅就是基利他），还有毗他希雅、犹大、以利以谢。'),
('CUV', '以斯拉记', 15, 10, 24, '歌唱的人中有以利亚实。守门的人中，有沙龙、提联、乌利。'),
('CUV', '以斯拉记', 15, 10, 25, '以色列人巴录的子孙中，有拉米、耶西雅、玛基雅、米雅民、以利亚撒、玛基雅、比拿雅。'),
('CUV', '以斯拉记', 15, 10, 26, '以拦的子孙中，有玛他尼、撒迦利亚、耶歇、押底、耶利末、以利雅。'),
('CUV', '以斯拉记', 15, 10, 27, '萨土的子孙中，有以利约乃、以利亚实、玛他尼、耶利末、撒拔、亚西撒。'),
('CUV', '以斯拉记', 15, 10, 28, '比拜的子孙中，有约哈难、哈拿尼雅、萨拜、亚勒。'),
('CUV', '以斯拉记', 15, 10, 29, '巴尼的子孙中，有米书兰、玛鹿、亚大雅、雅述、示押、耶利末。'),
('CUV', '以斯拉记', 15, 10, 30, '巴哈•摩押的子孙中，有阿底拿、基拉、比拿雅、玛西雅、玛他尼、比撒列、宾内、玛拿西。'),
('CUV', '以斯拉记', 15, 10, 31, '哈琳的子孙中，有以利以谢、伊示雅、玛基雅、示玛雅、西缅、'),
('CUV', '以斯拉记', 15, 10, 32, '便雅悯、玛鹿、示玛利雅。'),
('CUV', '以斯拉记', 15, 10, 33, '哈顺的子孙中，有玛特乃、玛达他、撒拔、以利法列、耶利买、玛拿西、示每。'),
('CUV', '以斯拉记', 15, 10, 34, '巴尼的子孙中，有玛玳、暗兰、乌益、'),
('CUV', '以斯拉记', 15, 10, 35, '比拿雅、比底雅、基禄、'),
('CUV', '以斯拉记', 15, 10, 36, '瓦尼雅、米利末、以利亚实、'),
('CUV', '以斯拉记', 15, 10, 37, '玛他尼、玛特乃、雅扫、'),
('CUV', '以斯拉记', 15, 10, 38, '巴尼、宾内、示每、'),
('CUV', '以斯拉记', 15, 10, 39, '示利米雅、拿单、亚大雅、'),
('CUV', '以斯拉记', 15, 10, 40, '玛拿底拜、沙赛、沙赖、'),
('CUV', '以斯拉记', 15, 10, 41, '亚萨利、示利米雅、示玛利雅、'),
('CUV', '以斯拉记', 15, 10, 42, '沙龙、亚玛利雅、约瑟。'),
('CUV', '以斯拉记', 15, 10, 43, '尼波的子孙中，有耶利、玛他提雅、撒拔、西比拿、雅玳、约珥、比拿雅。'),
('CUV', '以斯拉记', 15, 10, 44, '这些人都娶了外邦女子为妻，其中也有生了儿女的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '尼希米记', 16, 1, 1, '哈迦利亚的儿子尼希米的言语如下：亚达薛西王二十年基斯流月，我在书珊城的宫中。'),
('CUV', '尼希米记', 16, 1, 2, '那时，有我一个弟兄哈拿尼，同著几个人从犹大来。我问他们那些被掳归回、剩下逃脱的犹大人和耶路撒冷的光景。'),
('CUV', '尼希米记', 16, 1, 3, '他们对我说：那些被掳归回剩下的人在犹大省遭大难，受凌辱；并且耶路撒冷的城墙拆毁，城门被火焚烧。'),
('CUV', '尼希米记', 16, 1, 4, '我听见这话，就坐下哭泣，悲哀几日，在天上的神面前禁食祈祷，说：'),
('CUV', '尼希米记', 16, 1, 5, '耶和华─天上的神，大而可畏的神啊，你向爱你、守你诫命的人守约施慈爱。'),
('CUV', '尼希米记', 16, 1, 6, '愿你睁眼看，侧耳听，你仆人昼夜在你面前为你众仆人以色列民的祈祷，承认我们以色列人向你所犯的罪；我与我父家都有罪了。'),
('CUV', '尼希米记', 16, 1, 7, '我们向你所行的甚是邪恶，没有遵守你藉著仆人摩西所吩咐的诫命、律例、典章。'),
('CUV', '尼希米记', 16, 1, 8, '求你记念所吩咐你仆人摩西的话，说：你们若犯罪，我就把你们分散在万民中；'),
('CUV', '尼希米记', 16, 1, 9, '但你们若归向我，谨守遵行我的诫命，你们被赶散的人虽在天涯，我也必从那里将他们招聚回来，带到我所选择立为我名的居所。'),
('CUV', '尼希米记', 16, 1, 10, '这都是你的仆人、你的百姓，就是你用大力和大能的手所救赎的。'),
('CUV', '尼希米记', 16, 1, 11, '主啊，求你侧耳听你仆人的祈祷，和喜爱敬畏你名众仆人的祈祷，使你仆人现今亨通，在王面前蒙恩。我是作王酒政的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '尼希米记', 16, 2, 1, '亚达薛西王二十年尼散月，在王面前摆酒，我拿起酒来奉给王。我素来在王面前没有愁容。'),
('CUV', '尼希米记', 16, 2, 2, '王对我说：你既没有病，为甚么面带愁容呢？这不是别的，必是你心中愁烦。于是我甚惧怕。'),
('CUV', '尼希米记', 16, 2, 3, '我对王说：愿王万岁！我列祖坟墓所在的那城荒凉，城门被火焚烧，我岂能面无愁容么？'),
('CUV', '尼希米记', 16, 2, 4, '王问我说：你要求甚么？于是我默祷天上的神。'),
('CUV', '尼希米记', 16, 2, 5, '我对王说：仆人若在王眼前蒙恩，王若喜欢，求王差遣我往犹大，到我列祖坟墓所在的那城去，我好重新建造。'),
('CUV', '尼希米记', 16, 2, 6, '那时王后坐在王的旁边。王问我说：你去要多少日子？几时回来？我就定了日期。于是王喜欢差遣我去。'),
('CUV', '尼希米记', 16, 2, 7, '我又对王说：王若喜欢，求王赐我诏书，通知大河西的省长准我经过，直到犹大；'),
('CUV', '尼希米记', 16, 2, 8, '又赐诏书，通知管理王园林的亚萨，使他给我木料，做属殿营楼之门的横梁和城墙，与我自己房屋使用的。王就允准我，因我神施恩的手帮助我。'),
('CUV', '尼希米记', 16, 2, 9, '王派了军长和马兵护送我。我到了河西的省长那里，将王的诏书交给他们。'),
('CUV', '尼希米记', 16, 2, 10, '和伦人参巴拉，并为奴的亚扪人多比雅，听见有人来为以色列人求好处，就甚恼怒。'),
('CUV', '尼希米记', 16, 2, 11, '我到了耶路撒冷，在那里住了三日。'),
('CUV', '尼希米记', 16, 2, 12, '我夜间起来，有几个人也一同起来；但神使我心里要为耶路撒冷做甚么事，我并没有告诉人。除了我骑的牲口以外，也没有别的牲口在我那里。'),
('CUV', '尼希米记', 16, 2, 13, '当夜我出了谷门，往野狗井去（野狗：或译龙），到了粪厂门，察看耶路撒冷的城墙，见城墙拆毁，城门被火焚烧。'),
('CUV', '尼希米记', 16, 2, 14, '我又往前，到了泉门和王池，但所骑的牲口没有地方过去。'),
('CUV', '尼希米记', 16, 2, 15, '于是夜间沿溪而上，察看城墙，又转身进入谷门，就回来了。'),
('CUV', '尼希米记', 16, 2, 16, '我往哪里去，我做甚么事，官长都不知道。我还没有告诉犹大平民、祭司、贵胄、官长，和其余做工的人。'),
('CUV', '尼希米记', 16, 2, 17, '以后，我对他们说：我们所遭的难，耶路撒冷怎样荒凉，城门被火焚烧，你们都看见了。来罢，我们重建耶路撒冷的城墙，免得再受凌辱！'),
('CUV', '尼希米记', 16, 2, 18, '我告诉他们我神施恩的手怎样帮助我，并王对我所说的话。他们就说：我们起来建造罢！于是他们奋勇做这善工。'),
('CUV', '尼希米记', 16, 2, 19, '但和伦人参巴拉，并为奴的亚扪人多比雅和亚拉伯人基善听见就嗤笑我们，藐视我们，说：你们做甚么呢？要背叛王么？'),
('CUV', '尼希米记', 16, 2, 20, '我回答他们说：天上的神必使我们亨通。我们作他仆人的，要起来建造；你们却在耶路撒冷无分、无权、无纪念。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '尼希米记', 16, 3, 1, '那时，大祭司以利亚实和他的弟兄众祭司起来建立羊门，分别为圣，安立门扇，又筑城墙到哈米亚楼，直到哈楠业楼，分别为圣。'),
('CUV', '尼希米记', 16, 3, 2, '其次是耶利哥人建造。其次是音利的儿子撒刻建造。'),
('CUV', '尼希米记', 16, 3, 3, '哈西拿的子孙建立鱼门，架横梁、安门扇，和闩锁。'),
('CUV', '尼希米记', 16, 3, 4, '其次是哈哥斯的孙子、乌利亚的儿子米利末修造。其次是米示萨别的孙子、比利迦的儿子米书兰修造。其次是巴拿的儿子撒督修造。'),
('CUV', '尼希米记', 16, 3, 5, '其次是提哥亚人修造；但是他们的贵胄不用肩（原文是颈项）担他们主的工作。'),
('CUV', '尼希米记', 16, 3, 6, '巴西亚的儿子耶何耶大与比所玳的儿子米书兰修造古门，架横梁，安门扇和闩锁。'),
('CUV', '尼希米记', 16, 3, 7, '其次是基遍人米拉提，米伦人雅顿与基遍人，并属河西总督所管的米斯巴人修造。'),
('CUV', '尼希米记', 16, 3, 8, '其次是银匠哈海雅的儿子乌薛修造。其次是做香的哈拿尼雅修造。这些人修坚耶路撒冷，直到宽墙。'),
('CUV', '尼希米记', 16, 3, 9, '其次是管理耶路撒冷一半、户珥的儿子利法雅修造。'),
('CUV', '尼希米记', 16, 3, 10, '其次是哈路抹的儿子耶大雅对著自己的房屋修造。其次是哈沙尼的儿子哈突修造。'),
('CUV', '尼希米记', 16, 3, 11, '哈琳的儿子玛基雅和巴哈摩押的儿子哈述修造一段，并修造炉楼。'),
('CUV', '尼希米记', 16, 3, 12, '其次是管理耶路撒冷那一半、哈罗黑的儿子沙龙和他的女儿们修造。'),
('CUV', '尼希米记', 16, 3, 13, '哈嫩和撒挪亚的居民修造谷门，立门，安门扇和闩锁，又建筑城墙一千肘，直到粪厂门。'),
('CUV', '尼希米记', 16, 3, 14, '管理伯哈基琳、利甲的儿子玛基雅修造粪厂门，立门，安门扇和闩锁。'),
('CUV', '尼希米记', 16, 3, 15, '管理米斯巴、各荷西的儿子沙仑修造泉门，立门，盖门顶，安门扇和闩锁，又修造靠近王园西罗亚池的墙垣，直到那从大卫城下来的台阶。'),
('CUV', '尼希米记', 16, 3, 16, '其次是管理伯夙一半、押卜的儿子尼希米修造，直到大卫坟地的对面，又到挖成的池子，并勇士的房屋。'),
('CUV', '尼希米记', 16, 3, 17, '其次是利未人巴尼的儿子利宏修造。其次是管理基伊拉一半、哈沙比雅为他所管的本境修造。'),
('CUV', '尼希米记', 16, 3, 18, '其次是利未人弟兄中管理基伊拉那一半、希拿达的儿子巴瓦伊修造。'),
('CUV', '尼希米记', 16, 3, 19, '其次是管理米斯巴、耶书亚的儿子以谢修造一段，对著武库的上坡、城墙转弯之处。'),
('CUV', '尼希米记', 16, 3, 20, '其次是萨拜的儿子巴录竭力修造一段，从城墙转弯，直到大祭司以利亚实的府门。'),
('CUV', '尼希米记', 16, 3, 21, '其次是哈哥斯的孙子、乌利亚的儿子米利末修造一段，从以利亚实的府门，直到以利亚实府的尽头。'),
('CUV', '尼希米记', 16, 3, 22, '其次是住平原的祭司修造。'),
('CUV', '尼希米记', 16, 3, 23, '其次是便雅悯与哈述对著自己的房屋修造。其次是亚难尼的孙子、玛西雅的儿子亚撒利雅在靠近自己的房屋修造。'),
('CUV', '尼希米记', 16, 3, 24, '其次是希拿达的儿子宾内修造一段，从亚撒利雅的房屋直到城墙转弯，又到城角。'),
('CUV', '尼希米记', 16, 3, 25, '乌赛的儿子巴拉修造对著城墙的转弯和王上宫凸出来的城楼，靠近护卫院的那一段。其次是巴录的儿子毗大雅修造。'),
('CUV', '尼希米记', 16, 3, 26, '（尼提宁住在俄斐勒，直到朝东水门的对面和凸出来的城楼。）'),
('CUV', '尼希米记', 16, 3, 27, '其次是提哥亚人又修一段，对著那凸出来的大楼，直到俄斐勒的墙。'),
('CUV', '尼希米记', 16, 3, 28, '从马门往上，众祭司各对自己的房屋修造。'),
('CUV', '尼希米记', 16, 3, 29, '其次是音麦的儿子撒督对著自己的房屋修造。其次是守东门、示迦尼的儿子示玛雅修造。'),
('CUV', '尼希米记', 16, 3, 30, '其次是示利米雅的儿子哈拿尼雅和萨拉的第六子哈嫩又修一段。其次是比利迦的儿子米书兰对著自己的房屋修造。'),
('CUV', '尼希米记', 16, 3, 31, '其次是银匠玛基雅修造到尼提宁和商人的房屋，对著哈米弗甲门，直到城的角楼。'),
('CUV', '尼希米记', 16, 3, 32, '银匠与商人在城的角楼和羊门中间修造。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '尼希米记', 16, 4, 1, '参巴拉听见我们修造城墙就发怒，大大恼恨，嗤笑犹大人，'),
('CUV', '尼希米记', 16, 4, 2, '对他弟兄和撒玛利亚的军兵说：这些软弱的犹大人做甚么呢？要保护自己么？要献祭么？要一日成功么？要从土堆里拿出火烧的石头再立墙么？'),
('CUV', '尼希米记', 16, 4, 3, '亚扪人多比雅站在旁边，说：他们所修造的石墙，就是狐狸上去也必跐倒。'),
('CUV', '尼希米记', 16, 4, 4, '我们的神啊，求你垂听，因为我们被藐视。求你使他们的毁谤归于他们的头上，使他们在掳到之地作为掠物。'),
('CUV', '尼希米记', 16, 4, 5, '不要遮掩他们的罪孽，不要使他们的罪恶从你面前涂抹，因为他们在修造的人眼前惹动你的怒气。'),
('CUV', '尼希米记', 16, 4, 6, '这样，我们修造城墙，城墙就都连络，高至一半，因为百姓专心做工。'),
('CUV', '尼希米记', 16, 4, 7, '参巴拉、多比雅、亚拉伯人、亚扪人、亚实突人听见修造耶路撒冷城墙，著手进行堵塞破裂的地方，就甚发怒。'),
('CUV', '尼希米记', 16, 4, 8, '大家同谋要来攻击耶路撒冷，使城内扰乱。'),
('CUV', '尼希米记', 16, 4, 9, '然而，我们祷告我们的神，又因他们的缘故，就派人看守，昼夜防备。'),
('CUV', '尼希米记', 16, 4, 10, '犹大人说：灰土尚多，扛抬的人力气已经衰败，所以我们不能建造城墙。'),
('CUV', '尼希米记', 16, 4, 11, '我们的敌人且说：趁他们不知不见，我们进入他们中间，杀他们，使工作止住。'),
('CUV', '尼希米记', 16, 4, 12, '那靠近敌人居住的犹大人十次从各处来见我们，说：你们必要回到我们那里。'),
('CUV', '尼希米记', 16, 4, 13, '所以我使百姓各按宗族拿刀、拿枪、拿弓站在城墙后边低洼的空处。'),
('CUV', '尼希米记', 16, 4, 14, '我察看了，就起来对贵胄、官长，和其余的人说：不要怕他们！当记念主是大而可畏的。你们要为弟兄、儿女、妻子、家产争战。'),
('CUV', '尼希米记', 16, 4, 15, '仇敌听见我们知道他们的心意，见神也破坏他们的计谋，就不来了。我们都回到城墙那里，各做各的工。'),
('CUV', '尼希米记', 16, 4, 16, '从那日起，我的仆人一半做工，一半拿枪、拿盾牌、拿弓、穿（或译：拿）铠甲，官长都站在犹大众人的后边。'),
('CUV', '尼希米记', 16, 4, 17, '修造城墙的，扛抬材料的，都一手做工一手拿兵器。'),
('CUV', '尼希米记', 16, 4, 18, '修造的人都腰间佩刀修造，吹角的人在我旁边。'),
('CUV', '尼希米记', 16, 4, 19, '我对贵胄、官长，和其余的人说：这工程浩大，我们在城墙上相离甚远；'),
('CUV', '尼希米记', 16, 4, 20, '你们听见角声在哪里，就聚集到我们那里去。我们的神必为我们争战。'),
('CUV', '尼希米记', 16, 4, 21, '于是，我们做工，一半拿兵器，从天亮直到星宿出现的时候。'),
('CUV', '尼希米记', 16, 4, 22, '那时，我又对百姓说：各人和他的仆人当在耶路撒冷住宿，好在夜间保守我们，白昼做工。'),
('CUV', '尼希米记', 16, 4, 23, '这样，我和弟兄仆人，并跟从我的护兵都不脱衣服，出去打水也带兵器。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '尼希米记', 16, 5, 1, '百姓和他们的妻大大呼号，埋怨他们的弟兄犹大人。'),
('CUV', '尼希米记', 16, 5, 2, '有的说：我们和儿女人口众多，要去得粮食度命；'),
('CUV', '尼希米记', 16, 5, 3, '有的说：我们典了田地、葡萄园、房屋，要得粮食充饥；'),
('CUV', '尼希米记', 16, 5, 4, '有的说：我们已经指著田地、葡萄园，借了钱给王纳税。'),
('CUV', '尼希米记', 16, 5, 5, '我们的身体与我们弟兄的身体一样；我们的儿女与他们的儿女一般。现在我们将要使儿女作人的仆婢，我们的女儿已有为婢的；我们并无力拯救，因为我们的田地、葡萄园已经归了别人。'),
('CUV', '尼希米记', 16, 5, 6, '我听见他们呼号说这些话，便甚发怒。'),
('CUV', '尼希米记', 16, 5, 7, '我心里筹划，就斥责贵胄和官长说：你们各人向弟兄取利！于是我招聚大会攻击他们。'),
('CUV', '尼希米记', 16, 5, 8, '我对他们说：我们尽力赎回我们弟兄，就是卖与外邦的犹大人；你们还要卖弟兄，使我们赎回来么？他们就静默不语，无话可答。'),
('CUV', '尼希米记', 16, 5, 9, '我又说：你们所行的不善！你们行事不当敬畏我们的神么？不然，难免我们的仇敌外邦人毁谤我们。'),
('CUV', '尼希米记', 16, 5, 10, '我和我的弟兄与仆人也将银钱粮食借给百姓；我们大家都当免去利息。'),
('CUV', '尼希米记', 16, 5, 11, '如今我劝你们将他们的田地、葡萄园、橄榄园、房屋，并向他们所取的银钱、粮食、新酒，和油，百分之一的利息都归还他们。'),
('CUV', '尼希米记', 16, 5, 12, '众人说：我们必归还，不再向他们索要，必照你的话行。我就召了祭司来，叫众人起誓，必照著所应许的而行。'),
('CUV', '尼希米记', 16, 5, 13, '我也抖著胸前的衣襟，说：凡不成就这应许的，愿神照样抖他离开家产和他劳碌得来的，直到抖空了。会众都说：阿们！又赞美耶和华。百姓就照著所应许的去行。'),
('CUV', '尼希米记', 16, 5, 14, '自从我奉派作犹大地的省长，就是从亚达薛西王二十年直到三十二年，共十二年之久，我与我弟兄都没有吃省长的俸禄。'),
('CUV', '尼希米记', 16, 5, 15, '在我以前的省长加重百姓的担子，每日索要粮食和酒，并银子四十舍客勒，就是他们的仆人也辖制百姓；但我因敬畏神不这样行。'),
('CUV', '尼希米记', 16, 5, 16, '并且我恒心修造城墙，并没有置买田地；我的仆人也都聚集在那里做工。'),
('CUV', '尼希米记', 16, 5, 17, '除了从四围外邦中来的犹大人以外，有犹大平民和官长一百五十人在我席上吃饭。'),
('CUV', '尼希米记', 16, 5, 18, '每日预备一只公牛，六只肥羊，又预备些飞禽；每十日一次，多预备各样的酒。虽然如此，我并不要省长的俸禄，因为百姓服役甚重。'),
('CUV', '尼希米记', 16, 5, 19, '我的神啊，求你记念我为这百姓所行的一切事，施恩与我。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '尼希米记', 16, 6, 1, '参巴拉、多比雅、亚拉伯人基善和我们其余的仇敌听见我已经修完了城墙，其中没有破裂之处（那时我还没有安门扇），'),
('CUV', '尼希米记', 16, 6, 2, '参巴拉和基善就打发人来见我，说：请你来，我们在阿挪平原的一个村庄相会。他们却想害我。'),
('CUV', '尼希米记', 16, 6, 3, '于是我差遣人去见他们，说：我现在办理大工，不能下去。焉能停工下去见你们呢？'),
('CUV', '尼希米记', 16, 6, 4, '他们这样四次打发人来见我，我都如此回答他们。'),
('CUV', '尼希米记', 16, 6, 5, '参巴拉第五次打发仆人来见我，手里拿著未封的信，'),
('CUV', '尼希米记', 16, 6, 6, '信上写著说：外邦人中有风声，迦施慕（就是基善，见二章十九节）也说，你和犹大人谋反，修造城墙，你要作他们的王；'),
('CUV', '尼希米记', 16, 6, 7, '你又派先知在耶路撒冷指著你宣讲，说在犹大有王。现在这话必传与王知；所以请你来，与我们彼此商议。'),
('CUV', '尼希米记', 16, 6, 8, '我就差遣人去见他，说：你所说的这事，一概没有，是你心里捏造的。'),
('CUV', '尼希米记', 16, 6, 9, '他们都要使我们惧怕，意思说，他们的手必软弱，以致工作不能成就。神啊，求你坚固我的手。'),
('CUV', '尼希米记', 16, 6, 10, '我到了米希大别的孙子、第来雅的儿子示玛雅家里；那时，他闭门不出。他说：我们不如在神的殿里会面，将殿门关锁；因为他们要来杀你，就是夜里来杀你。'),
('CUV', '尼希米记', 16, 6, 11, '我说：像我这样的人岂要逃跑呢？像我这样的人岂能进入殿里保全生命呢？我不进去！'),
('CUV', '尼希米记', 16, 6, 12, '我看明神没有差遣他，是他自己说这话攻击我，是多比雅和参巴拉贿买了他。'),
('CUV', '尼希米记', 16, 6, 13, '贿买他的缘故，是要叫我惧怕，依从他犯罪，他们好传扬恶言毁谤我。'),
('CUV', '尼希米记', 16, 6, 14, '我的神啊，多比雅、参巴拉、女先知挪亚底，和其余的先知要叫我惧怕，求你记念他们所行的这些事。'),
('CUV', '尼希米记', 16, 6, 15, '以禄月二十五日，城墙修完了，共修了五十二天。'),
('CUV', '尼希米记', 16, 6, 16, '我们一切仇敌、四围的外邦人听见了便惧怕，愁眉不展；因为见这工作完成是出乎我们的神。'),
('CUV', '尼希米记', 16, 6, 17, '在那些日子，犹大的贵胄屡次寄信与多比雅，多比雅也来信与他们。'),
('CUV', '尼希米记', 16, 6, 18, '在犹大有许多人与多比雅结盟；因他是亚拉的儿子，示迦尼的女婿，并且他的儿子约哈难娶了比利迦儿子米书兰的女儿为妻。'),
('CUV', '尼希米记', 16, 6, 19, '他们常在我面前说多比雅的善行，也将我的话传与他。多比雅又常寄信来，要叫我惧怕。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '尼希米记', 16, 7, 1, '城墙修完，我安了门扇，守门的、歌唱的，和利未人都已派定。'),
('CUV', '尼希米记', 16, 7, 2, '我就派我的弟兄哈拿尼和营楼的宰官哈拿尼雅管理耶路撒冷；因为哈拿尼雅是忠信的，又敬畏神过于众人。'),
('CUV', '尼希米记', 16, 7, 3, '我吩咐他们说：等到太阳上升才可开耶路撒冷的城门；人尚看守的时候就要关门上闩；也当派耶路撒冷的居民各按班次看守自己房屋对面之处。'),
('CUV', '尼希米记', 16, 7, 4, '城是广大，其中的民却稀少，房屋还没有建造。'),
('CUV', '尼希米记', 16, 7, 5, '我的神感动我心，招聚贵胄、官长，和百姓，要照家谱计算。我找著第一次上来之人的家谱，其上写著：'),
('CUV', '尼希米记', 16, 7, 6, '巴比伦王尼布甲尼撒从前掳去犹大省的人，现在他们的子孙从被掳到之地回耶路撒冷和犹大，各归本城。'),
('CUV', '尼希米记', 16, 7, 7, '他们是同著所罗巴伯、耶书亚、尼希米、亚撒利雅、拉米、拿哈玛尼、末底改、必珊、米斯毗列、比革瓦伊、尼宏、巴拿回来的。'),
('CUV', '尼希米记', 16, 7, 8, '以色列人民的数目记在下面：巴录的子孙二千一百七十二名；'),
('CUV', '尼希米记', 16, 7, 9, '示法提雅的子孙三百七十二名；'),
('CUV', '尼希米记', 16, 7, 10, '亚拉的子孙六百五十二名；'),
('CUV', '尼希米记', 16, 7, 11, '巴哈摩押的后裔，就是耶书亚和约押的子孙二千八百一十八名；'),
('CUV', '尼希米记', 16, 7, 12, '以拦的子孙一千二百五十四名；'),
('CUV', '尼希米记', 16, 7, 13, '萨土的子孙八百四十五名；'),
('CUV', '尼希米记', 16, 7, 14, '萨改的子孙七百六十名；'),
('CUV', '尼希米记', 16, 7, 15, '宾内的子孙六百四十八名；'),
('CUV', '尼希米记', 16, 7, 16, '比拜的子孙六百二十八名；'),
('CUV', '尼希米记', 16, 7, 17, '押甲的子孙二千三百二十二名；'),
('CUV', '尼希米记', 16, 7, 18, '亚多尼干的子孙六百六十七名；'),
('CUV', '尼希米记', 16, 7, 19, '比革瓦伊的子孙二千零六十七名；'),
('CUV', '尼希米记', 16, 7, 20, '亚丁的子孙六百五十五名；'),
('CUV', '尼希米记', 16, 7, 21, '亚特的后裔，就是希西家的子孙九十八名；'),
('CUV', '尼希米记', 16, 7, 22, '哈顺的子孙三百二十八名；'),
('CUV', '尼希米记', 16, 7, 23, '比赛的子孙三百二十四名；'),
('CUV', '尼希米记', 16, 7, 24, '哈拉的子孙一百一十二名；'),
('CUV', '尼希米记', 16, 7, 25, '基遍人九十五名；'),
('CUV', '尼希米记', 16, 7, 26, '伯利恒人和尼陀法人共一百八十八名；'),
('CUV', '尼希米记', 16, 7, 27, '亚拿突人一百二十八名；'),
('CUV', '尼希米记', 16, 7, 28, '伯亚斯玛弗人四十二名；'),
('CUV', '尼希米记', 16, 7, 29, '基列耶琳人、基非拉人、比录人共七百四十三名；'),
('CUV', '尼希米记', 16, 7, 30, '拉玛人和迦巴人共六百二十一名；'),
('CUV', '尼希米记', 16, 7, 31, '默玛人一百二十二名；'),
('CUV', '尼希米记', 16, 7, 32, '伯特利人和艾人共一百二十三名；'),
('CUV', '尼希米记', 16, 7, 33, '别的尼波人五十二名；'),
('CUV', '尼希米记', 16, 7, 34, '别的以拦子孙一千二百五十四名；'),
('CUV', '尼希米记', 16, 7, 35, '哈琳的子孙三百二十名；'),
('CUV', '尼希米记', 16, 7, 36, '耶利哥人三百四十五名；'),
('CUV', '尼希米记', 16, 7, 37, '罗德人、哈第人、阿挪人共七百二十一名；'),
('CUV', '尼希米记', 16, 7, 38, '西拿人三千九百三十名。'),
('CUV', '尼希米记', 16, 7, 39, '祭司：耶书亚家，耶大雅的子孙九百七十三名；'),
('CUV', '尼希米记', 16, 7, 40, '音麦的子孙一千零五十二名；'),
('CUV', '尼希米记', 16, 7, 41, '巴施户珥的子孙一千二百四十七名；'),
('CUV', '尼希米记', 16, 7, 42, '哈琳的子孙一千零一十七名。'),
('CUV', '尼希米记', 16, 7, 43, '利未人：何达威的后裔，就是耶书亚和甲篾的子孙七十四名。'),
('CUV', '尼希米记', 16, 7, 44, '歌唱的：亚萨的子孙一百四十八名。'),
('CUV', '尼希米记', 16, 7, 45, '守门的：沙龙的子孙、亚特的子孙、达们的子孙、亚谷的子孙、哈底大的子孙、朔拜的子孙，共一百三十八名。'),
('CUV', '尼希米记', 16, 7, 46, '尼提宁（就是殿役）：西哈的子孙、哈苏巴的子孙、答巴俄的子孙、'),
('CUV', '尼希米记', 16, 7, 47, '基绿的子孙、西亚的子孙、巴顿的子孙、'),
('CUV', '尼希米记', 16, 7, 48, '利巴拿的子孙、哈迦巴的子孙、萨买的子孙、'),
('CUV', '尼希米记', 16, 7, 49, '哈难的子孙、吉德的子孙、迦哈的子孙、'),
('CUV', '尼希米记', 16, 7, 50, '利亚雅的子孙、利汛的子孙、尼哥大的子孙、'),
('CUV', '尼希米记', 16, 7, 51, '迦散的子孙、乌撒的子孙、巴西亚的子孙、'),
('CUV', '尼希米记', 16, 7, 52, '比赛的子孙、米乌宁的子孙、尼普心的子孙、'),
('CUV', '尼希米记', 16, 7, 53, '巴卜的子孙、哈古巴的子孙、哈忽的子孙、'),
('CUV', '尼希米记', 16, 7, 54, '巴洗律的子孙、米希大的子孙、哈沙的子孙、'),
('CUV', '尼希米记', 16, 7, 55, '巴柯的子孙、西西拉的子孙、答玛的子孙、'),
('CUV', '尼希米记', 16, 7, 56, '尼细亚的子孙、哈提法的子孙。'),
('CUV', '尼希米记', 16, 7, 57, '所罗门仆人的后裔，就是琐太的子孙、琐斐列的子孙、比路大的子孙、'),
('CUV', '尼希米记', 16, 7, 58, '雅拉的子孙、达昆的子孙、吉德的子孙、'),
('CUV', '尼希米记', 16, 7, 59, '示法提雅的子孙、哈替的子孙、玻黑列哈斯巴音的子孙、亚们的子孙。'),
('CUV', '尼希米记', 16, 7, 60, '尼提宁和所罗门仆人的后裔共三百九十二名。'),
('CUV', '尼希米记', 16, 7, 61, '从特米拉、特哈萨、基绿、亚顿、音麦上来的，不能指明他们的宗族谱系是以色列人不是；'),
('CUV', '尼希米记', 16, 7, 62, '他们是第莱雅的子孙、多比雅的子孙、尼哥大的子孙，共六百四十二名。'),
('CUV', '尼希米记', 16, 7, 63, '祭司中，哈巴雅的子孙、哈哥斯的子孙、巴西莱的子孙；因为他们的先祖娶了基列人巴西莱的女儿为妻，所以起名叫巴西莱。'),
('CUV', '尼希米记', 16, 7, 64, '这三家的人在族谱之中寻查自己的谱系，却寻不著，因此算为不洁，不准供祭司的职任。'),
('CUV', '尼希米记', 16, 7, 65, '省长对他们说：不可吃至圣的物，直到有用乌陵和土明决疑的祭司兴起来。'),
('CUV', '尼希米记', 16, 7, 66, '会众共有四万二千三百六十名。'),
('CUV', '尼希米记', 16, 7, 67, '此外，还有他们的仆婢七千三百三十七名，又有歌唱的男女二百四十五名。'),
('CUV', '尼希米记', 16, 7, 68, '他们有马七百三十六匹，骡子二百四十五匹，'),
('CUV', '尼希米记', 16, 7, 69, '骆驼四百三十五只，驴六千七百二十匹。'),
('CUV', '尼希米记', 16, 7, 70, '有些族长为工程捐助。省长捐入库中的金子一千达利克，碗五十个，祭司的礼服五百三十件。'),
('CUV', '尼希米记', 16, 7, 71, '又有族长捐入工程库的金子二万达利克，银子二千二百弥拿。'),
('CUV', '尼希米记', 16, 7, 72, '其余百姓所捐的金子二万达利克，银子二千弥拿，祭司的礼服六十七件。'),
('CUV', '尼希米记', 16, 7, 73, '于是祭司、利未人、守门的、歌唱的、民中的一些人、尼提宁，并以色列众人，各住在自己的城里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '尼希米记', 16, 8, 1, '到了七月，以色列人住在自己的城里。那时，他们如同一人聚集在水门前的宽阔处，请文士以斯拉将耶和华藉摩西传给以色列人的律法书带来。'),
('CUV', '尼希米记', 16, 8, 2, '七月初一日，祭司以斯拉将律法书带到听了能明白的男女会众面前。'),
('CUV', '尼希米记', 16, 8, 3, '在水门前的宽阔处，从清早到晌午，在众男女、一切听了能明白的人面前读这律法书。众民侧耳而听。'),
('CUV', '尼希米记', 16, 8, 4, '文士以斯拉站在为这事特备的木台上。玛他提雅、示玛、亚奈雅、乌利亚、希勒家，和玛西雅站在他的右边；毗大雅、米沙利、玛基雅、哈顺、哈拔大拿、撒迦利亚，和米书兰站在他的左边。'),
('CUV', '尼希米记', 16, 8, 5, '以斯拉站在众民以上，在众民眼前展开这书。他一展开，众民就都站起来。'),
('CUV', '尼希米记', 16, 8, 6, '以斯拉称颂耶和华至大的神；众民都举手应声说：阿们！阿们！就低头，面伏于地，敬拜耶和华。'),
('CUV', '尼希米记', 16, 8, 7, '耶书亚、巴尼、示利比、雅悯、亚谷、沙比太、荷第雅、玛西雅、基利他、亚撒利雅、约撒拔、哈难、毗莱雅，和利未人使百姓明白律法；百姓都站在自己的地方。'),
('CUV', '尼希米记', 16, 8, 8, '他们清清楚楚地念神的律法书，讲明意思，使百姓明白所念的。'),
('CUV', '尼希米记', 16, 8, 9, '省长尼希米和作祭司的文士以斯拉，并教训百姓的利未人，对众民说：今日是耶和华─你们神的圣日，不要悲哀哭泣。这是因为众民听见律法书上的话都哭了；'),
('CUV', '尼希米记', 16, 8, 10, '又对他们说：你们去吃肥美的，喝甘甜的，有不能预备的就分给他，因为今日是我们主的圣日。你们不要忧愁，因靠耶和华而得的喜乐是你们的力量。'),
('CUV', '尼希米记', 16, 8, 11, '于是利未人使众民静默，说：今日是圣日；不要作声，也不要忧愁。'),
('CUV', '尼希米记', 16, 8, 12, '众民都去吃喝，也分给人，大大快乐，因为他们明白所教训他们的话。'),
('CUV', '尼希米记', 16, 8, 13, '次日，众民的族长、祭司，和利未人都聚集到文士以斯拉那里，要留心听律法上的话。'),
('CUV', '尼希米记', 16, 8, 14, '他们见律法上写著，耶和华藉摩西吩咐以色列人要在七月节住棚，'),
('CUV', '尼希米记', 16, 8, 15, '并要在各城和耶路撒冷宣传报告说：你们当上山，将橄榄树、野橄榄树、番石榴树、棕树，和各样茂密树的枝子取来，照著所写的搭棚。'),
('CUV', '尼希米记', 16, 8, 16, '于是百姓出去，取了树枝来，各人在自己的房顶上，或院内，或神殿的院内，或水门的宽阔处，或以法莲门的宽阔处搭棚。'),
('CUV', '尼希米记', 16, 8, 17, '从掳到之地归回的全会众就搭棚，住在棚里。从嫩的儿子约书亚的时候直到这日，以色列人没有这样行。于是众人大大喜乐。'),
('CUV', '尼希米记', 16, 8, 18, '从头一天直到末一天，以斯拉每日念神的律法书。众人守节七日，第八日照例有严肃会。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '尼希米记', 16, 9, 1, '这月二十四日，以色列人聚集禁食，身穿麻衣，头蒙灰尘。'),
('CUV', '尼希米记', 16, 9, 2, '以色列人（人：原文是种类）就与一切外邦人离绝，站著承认自己的罪恶和列祖的罪孽。'),
('CUV', '尼希米记', 16, 9, 3, '那日的四分之一站在自己的地方念耶和华─他们神的律法书，又四分之一认罪，敬拜耶和华─他们的神。'),
('CUV', '尼希米记', 16, 9, 4, '耶书亚、巴尼、甲篾、示巴尼、布尼、示利比、巴尼、基拿尼站在利未人的台上，大声哀求耶和华─他们的神。'),
('CUV', '尼希米记', 16, 9, 5, '利未人耶书亚、甲篾、巴尼、哈沙尼、示利比、荷第雅、示巴尼、毗他希雅说：你们要站起来称颂耶和华─你们的神，永世无尽。耶和华啊，你荣耀之名是应当称颂的！超乎一切称颂和赞美。'),
('CUV', '尼希米记', 16, 9, 6, '你，惟独你是耶和华！你造了天和天上的天，并天上的万象，地和地上的万物，海和海中所有的；这一切都是你所保存的。天军也都敬拜你。'),
('CUV', '尼希米记', 16, 9, 7, '你是耶和华神，曾拣选亚伯兰，领他出迦勒底的吾珥，给他改名叫亚伯拉罕。'),
('CUV', '尼希米记', 16, 9, 8, '你见他在你面前心里诚实，就与他立约，应许把迦南人、赫人、亚摩利人、比利洗人、耶布斯人、革迦撒人之地赐给他的后裔，且应验了你的话，因为你是公义的。'),
('CUV', '尼希米记', 16, 9, 9, '你曾看见我们列祖在埃及所受的困苦，垂听他们在红海边的哀求，'),
('CUV', '尼希米记', 16, 9, 10, '就施行神迹奇事在法老和他一切臣仆，并他国中的众民身上。你也得了名声，正如今日一样，因为你知道他们向我们列祖行事狂傲。'),
('CUV', '尼希米记', 16, 9, 11, '你又在我们列祖面前把海分开，使他们在海中行走干地，将追赶他们的人抛在深海，如石头抛在大水中；'),
('CUV', '尼希米记', 16, 9, 12, '并且白昼用云柱引导他们，黑夜用火柱照亮他们当行的路。'),
('CUV', '尼希米记', 16, 9, 13, '你也降临在西乃山，从天上与他们说话，赐给他们正直的典章、真实的律法、美好的条例与诫命，'),
('CUV', '尼希米记', 16, 9, 14, '又使他们知道你的安息圣日，并藉你仆人摩西传给他们诫命、条例、律法。'),
('CUV', '尼希米记', 16, 9, 15, '从天上赐下粮食充他们的饥，从磐石使水流出解他们的渴，又吩咐他们进去得你起誓应许赐给他们的地。'),
('CUV', '尼希米记', 16, 9, 16, '但我们的列祖行事狂傲，硬著颈项不听从你的诫命；'),
('CUV', '尼希米记', 16, 9, 17, '不肯顺从，也不记念你在他们中间所行的奇事，竟硬著颈项，居心背逆，自立首领，要回他们为奴之地。但你是乐意饶恕人，有恩典，有怜悯，不轻易发怒，有丰盛慈爱的神，并不丢弃他们。'),
('CUV', '尼希米记', 16, 9, 18, '他们虽然铸了一只牛犊，彼此说这是领你出埃及的神，因而大大惹动你的怒气；'),
('CUV', '尼希米记', 16, 9, 19, '你还是大施怜悯，在旷野不丢弃他们。白昼，云柱不离开他们，仍引导他们行路；黑夜，火柱也不离开他们，仍照亮他们当行的路。'),
('CUV', '尼希米记', 16, 9, 20, '你也赐下你良善的灵教训他们；未尝不赐吗哪使他们糊口，并赐水解他们的渴。'),
('CUV', '尼希米记', 16, 9, 21, '在旷野四十年，你养育他们，他们就一无所缺：衣服没有穿破，脚也没有肿。'),
('CUV', '尼希米记', 16, 9, 22, '并且你将列国之地照分赐给他们，他们就得了西宏之地、希实本王之地，和巴珊王噩之地。'),
('CUV', '尼希米记', 16, 9, 23, '你也使他们的子孙多如天上的星，带他们到你所应许他们列祖进入得为业之地。'),
('CUV', '尼希米记', 16, 9, 24, '这样，他们进去得了那地，你在他们面前制伏那地的居民，就是迦南人；将迦南人和其君王，并那地的居民，都交在他们手里，让他们任意而待。'),
('CUV', '尼希米记', 16, 9, 25, '他们得了坚固的城邑、肥美的地土、充满各样美物的房屋、凿成的水井、葡萄园、橄榄园，并许多果木树。他们就吃而得饱，身体肥胖，因你的大恩，心中快乐。'),
('CUV', '尼希米记', 16, 9, 26, '然而，他们不顺从，竟背叛你，将你的律法丢在背后，杀害那劝他们归向你的众先知，大大惹动你的怒气。'),
('CUV', '尼希米记', 16, 9, 27, '所以你将他们交在敌人的手中，磨难他们。他们遭难的时候哀求你，你就从天上垂听，照你的大怜悯赐给他们拯救者，救他们脱离敌人的手。'),
('CUV', '尼希米记', 16, 9, 28, '但他们得平安之后，又在你面前行恶，所以你丢弃他们在仇敌的手中，使仇敌辖制他们。然而他们转回哀求你，你仍从天上垂听，屡次照你的怜悯拯救他们，'),
('CUV', '尼希米记', 16, 9, 29, '又警戒他们，要使他们归服你的律法。他们却行事狂傲，不听从你的诫命，干犯你的典章（人若遵行就必因此活著），扭转肩头，硬著颈项，不肯听从。'),
('CUV', '尼希米记', 16, 9, 30, '但你多年宽容他们，又用你的灵藉众先知劝戒他们，他们仍不听从，所以你将他们交在列国之民的手中。'),
('CUV', '尼希米记', 16, 9, 31, '然而你大发怜悯，不全然灭绝他们，也不丢弃他们；因为你是有恩典、有怜悯的神。'),
('CUV', '尼希米记', 16, 9, 32, '我们的神啊，你是至大、至能、至可畏、守约施慈爱的神。我们的君王、首领、祭司、先知、列祖，和你的众民，从亚述列王的时候直到今日所遭遇的苦难，现在求你不要以为小。'),
('CUV', '尼希米记', 16, 9, 33, '在一切临到我们的事上，你却是公义的；因你所行的是诚实，我们所做的是邪恶。'),
('CUV', '尼希米记', 16, 9, 34, '我们的君王、首领、祭司、列祖都不遵守你的律法，不听从你的诫命和你警戒他们的话。'),
('CUV', '尼希米记', 16, 9, 35, '他们在本国里沾你大恩的时候，在你所赐给他们这广大肥美之地上不事奉你，也不转离他们的恶行。'),
('CUV', '尼希米记', 16, 9, 36, '我们现今作了奴仆；至于你所赐给我们列祖享受其上的土产，并美物之地，看哪，我们在这地上作了奴仆！'),
('CUV', '尼希米记', 16, 9, 37, '这地许多出产归了列王，就是你因我们的罪所派辖制我们的。他们任意辖制我们的身体和牲畜，我们遭了大难。'),
('CUV', '尼希米记', 16, 9, 38, '因这一切的事，我们立确实的约，写在册上。我们的首领、利未人，和祭司都签了名。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '尼希米记', 16, 10, 1, '签名的是：哈迦利亚的儿子─省长尼希米，和西底家；'),
('CUV', '尼希米记', 16, 10, 2, '祭司：西莱雅、亚撒利雅、耶利米、'),
('CUV', '尼希米记', 16, 10, 3, '巴施户珥、亚玛利雅、玛基雅、'),
('CUV', '尼希米记', 16, 10, 4, '哈突、示巴尼、玛鹿、'),
('CUV', '尼希米记', 16, 10, 5, '哈琳、米利末、俄巴底亚、'),
('CUV', '尼希米记', 16, 10, 6, '但以理、近顿、巴录、'),
('CUV', '尼希米记', 16, 10, 7, '米书兰、亚比雅、米雅民、'),
('CUV', '尼希米记', 16, 10, 8, '玛西亚、璧该、示玛雅；'),
('CUV', '尼希米记', 16, 10, 9, '又有利未人，就是亚散尼的儿子耶书亚、希拿达的子孙宾内、甲篾；'),
('CUV', '尼希米记', 16, 10, 10, '还有他们的弟兄示巴尼、荷第雅、基利他、毗莱雅、哈难、'),
('CUV', '尼希米记', 16, 10, 11, '米迦、利合、哈沙比雅、'),
('CUV', '尼希米记', 16, 10, 12, '撒刻、示利比、示巴尼、'),
('CUV', '尼希米记', 16, 10, 13, '荷第雅、巴尼、比尼努；'),
('CUV', '尼希米记', 16, 10, 14, '又有民的首领，就是巴录、巴哈摩押、以拦、萨土、巴尼、'),
('CUV', '尼希米记', 16, 10, 15, '布尼、押甲、比拜、'),
('CUV', '尼希米记', 16, 10, 16, '亚多尼雅、比革瓦伊、亚丁、'),
('CUV', '尼希米记', 16, 10, 17, '亚特、希西家、押朔、'),
('CUV', '尼希米记', 16, 10, 18, '荷第雅、哈顺、比赛、'),
('CUV', '尼希米记', 16, 10, 19, '哈拉、亚拿突、尼拜、'),
('CUV', '尼希米记', 16, 10, 20, '抹比押、米书兰、希悉、'),
('CUV', '尼希米记', 16, 10, 21, '米示萨别、撒督、押杜亚、'),
('CUV', '尼希米记', 16, 10, 22, '毗拉提、哈难、亚奈雅、'),
('CUV', '尼希米记', 16, 10, 23, '何细亚、哈拿尼雅、哈述、'),
('CUV', '尼希米记', 16, 10, 24, '哈罗黑、毗利哈、朔百、'),
('CUV', '尼希米记', 16, 10, 25, '利宏、哈沙拿、玛西雅、'),
('CUV', '尼希米记', 16, 10, 26, '亚希雅、哈难、亚难、'),
('CUV', '尼希米记', 16, 10, 27, '玛鹿、哈琳、巴拿。'),
('CUV', '尼希米记', 16, 10, 28, '其余的民、祭司、利未人、守门的、歌唱的、尼提宁，和一切离绝邻邦居民归服神律法的，并他们的妻子、儿女，凡有知识能明白的，'),
('CUV', '尼希米记', 16, 10, 29, '都随从他们贵胄的弟兄，发咒起誓，必遵行神藉他仆人摩西所传的律法，谨守遵行耶和华─我们主的一切诫命、典章、律例；'),
('CUV', '尼希米记', 16, 10, 30, '并不将我们的女儿嫁给这地的居民，也不为我们的儿子娶他们的女儿。'),
('CUV', '尼希米记', 16, 10, 31, '这地的居民若在安息日，或甚么圣日，带了货物或粮食来卖给我们，我们必不买。每逢第七年必不耕种，凡欠我们债的必不追讨。'),
('CUV', '尼希米记', 16, 10, 32, '我们又为自己定例，每年各人捐银一舍客勒三分之一，为我们神殿的使用，'),
('CUV', '尼希米记', 16, 10, 33, '就是为陈设饼、常献的素祭，和燔祭，安息日、月朔、节期所献的与圣物，并以色列人的赎罪祭，以及我们神殿里一切的费用。'),
('CUV', '尼希米记', 16, 10, 34, '我们的祭司、利未人，和百姓都掣签，看每年是哪一族按定期将献祭的柴奉到我们神的殿里，照著律法上所写的，烧在耶和华─我们神的坛上。'),
('CUV', '尼希米记', 16, 10, 35, '又定每年将我们地上初熟的土产和各样树上初熟的果子都奉到耶和华的殿里。'),
('CUV', '尼希米记', 16, 10, 36, '又照律法上所写的，将我们头胎的儿子和首生的牛羊都奉到我们神的殿，交给我们神殿里供职的祭司；'),
('CUV', '尼希米记', 16, 10, 37, '并将初熟之麦子所磨的面和举祭、各样树上初熟的果子、新酒与油奉给祭司，收在我们神殿的库房里，把我们地上所产的十分之一奉给利未人，因利未人在我们一切城邑的土产中当取十分之一。'),
('CUV', '尼希米记', 16, 10, 38, '利未人取十分之一的时候，亚伦的子孙中，当有一个祭司与利未人同在。利未人也当从十分之一中取十分之一，奉到我们神殿的屋子里，收在库房中。'),
('CUV', '尼希米记', 16, 10, 39, '以色列人和利未人要将五谷、新酒，和油为举祭，奉到收存圣所器皿的屋子里，就是供职的祭司、守门的、歌唱的所住的屋子。这样，我们就不离弃我们神的殿。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '尼希米记', 16, 11, 1, '百姓的首领住在耶路撒冷。其余的百姓掣签，每十人中使一人来住在圣城耶路撒冷，那九人住在别的城邑。'),
('CUV', '尼希米记', 16, 11, 2, '凡甘心乐意住在耶路撒冷的，百姓都为他们祝福。'),
('CUV', '尼希米记', 16, 11, 3, '以色列人、祭司、利未人、尼提宁，和所罗门仆人的后裔都住在犹大城邑，各在自己的地业中。本省的首领住在耶路撒冷的记在下面：'),
('CUV', '尼希米记', 16, 11, 4, '其中有些犹大人和便雅悯人。犹大人中有法勒斯的子孙、乌西雅的儿子亚他雅。乌西雅是撒迦利雅的儿子；撒迦利雅是亚玛利雅的儿子；亚玛利雅是示法提雅的儿子；示法提雅是玛勒列的儿子。'),
('CUV', '尼希米记', 16, 11, 5, '又有巴录的儿子玛西雅。巴录是谷何西的儿子；谷何西是哈赛雅的儿子；哈赛雅是亚大雅的儿子；亚大雅是约雅立的儿子；约雅立是撒迦利雅的儿子；撒迦利雅是示罗尼的儿子。'),
('CUV', '尼希米记', 16, 11, 6, '住在耶路撒冷、法勒斯的子孙共四百六十八名，都是勇士。'),
('CUV', '尼希米记', 16, 11, 7, '便雅悯人中有米书兰的儿子撒路。米书兰是约叶的儿子；约叶是毗大雅的儿子；毗大雅是哥赖雅的儿子；哥赖雅是玛西雅的儿子；玛西雅是以铁的儿子；以铁是耶筛亚的儿子。'),
('CUV', '尼希米记', 16, 11, 8, '其次有迦拜、撒来的子孙，共九百二十八名。'),
('CUV', '尼希米记', 16, 11, 9, '细基利的儿子约珥是他们的长官。哈西努亚的儿子犹大是耶路撒冷的副官。'),
('CUV', '尼希米记', 16, 11, 10, '祭司中有雅斤，又有约雅立的儿子耶大雅；'),
('CUV', '尼希米记', 16, 11, 11, '还有管理神殿的西莱雅。西莱雅是希勒家的儿子；希勒家是米书兰的儿子；米书兰是撒督的儿子；撒督是米拉约的儿子；米拉约是亚希突的儿子。'),
('CUV', '尼希米记', 16, 11, 12, '还有他们的弟兄在殿里供职的，共八百二十二名；又有耶罗罕的儿子亚大雅。耶罗罕是毗拉利的儿子；毗拉利是暗洗的儿子；暗洗是撒迦利亚的儿子；撒迦利亚是巴施户珥的儿子；巴施户珥是玛基雅的儿子。'),
('CUV', '尼希米记', 16, 11, 13, '还有他的弟兄作族长的，二百四十二名；又有亚萨列的儿子亚玛帅。亚萨列是亚哈赛的儿子；亚哈赛是米实利末的儿子；米实利末是音麦的儿子。'),
('CUV', '尼希米记', 16, 11, 14, '还有他们弟兄、大能的勇士共一百二十八名。哈基多琳的儿子撒巴第业是他们的长官。'),
('CUV', '尼希米记', 16, 11, 15, '利未人中有哈述的儿子示玛雅。哈述是押利甘的儿子；押利甘是哈沙比雅的儿子；哈沙比雅是布尼的儿子。'),
('CUV', '尼希米记', 16, 11, 16, '又有利未人的族长沙比太和约撒拔管理神殿的外事。'),
('CUV', '尼希米记', 16, 11, 17, '祈祷的时候，为称谢领首的是米迦的儿子玛他尼。米迦是撒底的儿子；撒底是亚萨的儿子；又有玛他尼弟兄中的八布迦为副。还有沙母亚的儿子押大。沙母亚是加拉的儿子；加拉是耶杜顿的儿子。'),
('CUV', '尼希米记', 16, 11, 18, '在圣城的利未人共二百八十四名。'),
('CUV', '尼希米记', 16, 11, 19, '守门的是亚谷和达们，并守门的弟兄，共一百七十二名。'),
('CUV', '尼希米记', 16, 11, 20, '其余的以色列人、祭司、利未人都住在犹大的一切城邑，各在自己的地业中。'),
('CUV', '尼希米记', 16, 11, 21, '尼提宁却住在俄斐勒；西哈和基斯帕管理他们。'),
('CUV', '尼希米记', 16, 11, 22, '在耶路撒冷、利未人的长官，管理神殿事务的是歌唱者亚萨的子孙、巴尼的儿子乌西。巴尼是哈沙比雅的儿子；哈沙比雅是玛他尼的儿子；玛他尼是米迦的儿子。'),
('CUV', '尼希米记', 16, 11, 23, '王为歌唱的出命令，每日供给他们必有一定之粮。'),
('CUV', '尼希米记', 16, 11, 24, '犹大儿子谢拉的子孙、米示萨别的儿子毗他希雅辅助王办理犹大民的事。'),
('CUV', '尼希米记', 16, 11, 25, '至于村庄和属村庄的田地，有犹大人住在基列亚巴和属基列亚巴的乡村；底本和属底本的乡村；叶甲薛和属叶甲薛的村庄；'),
('CUV', '尼希米记', 16, 11, 26, '耶书亚、摩拉大、伯帕列、'),
('CUV', '尼希米记', 16, 11, 27, '哈萨书亚、别是巴，和属别是巴的乡村；'),
('CUV', '尼希米记', 16, 11, 28, '洗革拉、米哥拿，和属米哥拿的乡村；'),
('CUV', '尼希米记', 16, 11, 29, '音临门、琐拉、耶末、'),
('CUV', '尼希米记', 16, 11, 30, '撒挪亚、亚杜兰，和属这两处的村庄；拉吉和属拉吉的田地；亚西加和属亚西加的乡村。他们所住的地方是从别是巴直到欣嫩谷。'),
('CUV', '尼希米记', 16, 11, 31, '便雅悯人从迦巴起，住在密抹、亚雅、伯特利和属伯特利的乡村。'),
('CUV', '尼希米记', 16, 11, 32, '亚拿突、挪伯、亚难雅、'),
('CUV', '尼希米记', 16, 11, 33, '夏琐、拉玛、基他音、'),
('CUV', '尼希米记', 16, 11, 34, '哈叠、洗编、尼八拉、'),
('CUV', '尼希米记', 16, 11, 35, '罗德、阿挪、匠人之谷。'),
('CUV', '尼希米记', 16, 11, 36, '利未人中有几班曾住在犹大地归于便雅悯的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '尼希米记', 16, 12, 1, '同著撒拉铁的儿子所罗巴伯和耶书亚回来的祭司与利未人记在下面：祭司是西莱雅、耶利米、以斯拉、'),
('CUV', '尼希米记', 16, 12, 2, '亚玛利雅、玛鹿、哈突、'),
('CUV', '尼希米记', 16, 12, 3, '示迦尼、利宏、米利末、'),
('CUV', '尼希米记', 16, 12, 4, '易多、近顿、亚比雅、'),
('CUV', '尼希米记', 16, 12, 5, '米雅民、玛底雅、璧迦、'),
('CUV', '尼希米记', 16, 12, 6, '示玛雅、约雅立、耶大雅、'),
('CUV', '尼希米记', 16, 12, 7, '撒路、亚木、希勒家、耶大雅。这些人在耶书亚的时候作祭司和他们弟兄的首领。'),
('CUV', '尼希米记', 16, 12, 8, '利未人是耶书亚、宾内、甲篾、示利比、犹大、玛他尼。这玛他尼和他的弟兄管理称谢的事。'),
('CUV', '尼希米记', 16, 12, 9, '他们的弟兄八布迦和乌尼照自己的班次与他们相对。'),
('CUV', '尼希米记', 16, 12, 10, '耶书亚生约雅金；约雅金生以利亚实；以利亚实生耶何耶大；'),
('CUV', '尼希米记', 16, 12, 11, '耶何耶大生约拿单；约拿单生押杜亚。'),
('CUV', '尼希米记', 16, 12, 12, '在约雅金的时候，祭司作族长的西莱雅族（或译：班；本段同）有米拉雅；耶利米族有哈拿尼雅；'),
('CUV', '尼希米记', 16, 12, 13, '以斯拉族有米书兰；亚玛利雅族有约哈难；'),
('CUV', '尼希米记', 16, 12, 14, '米利古族有约拿单；示巴尼族有约瑟；'),
('CUV', '尼希米记', 16, 12, 15, '哈琳族有押拿；米拉约族有希勒恺；'),
('CUV', '尼希米记', 16, 12, 16, '易多族有撒迦利亚；近顿族有米书兰；'),
('CUV', '尼希米记', 16, 12, 17, '亚比雅族有细基利；米拿民族某；摩亚底族有毗勒太；'),
('CUV', '尼希米记', 16, 12, 18, '璧迦族有沙母亚；示玛雅族有约拿单；'),
('CUV', '尼希米记', 16, 12, 19, '约雅立族有玛特乃；耶大雅族有乌西；'),
('CUV', '尼希米记', 16, 12, 20, '撒来族有加莱；亚木族有希伯；'),
('CUV', '尼希米记', 16, 12, 21, '希勒家族有哈沙比雅；耶大雅族有拿坦业。'),
('CUV', '尼希米记', 16, 12, 22, '至于利未人，当以利亚实、耶何耶大、约哈难、押杜亚的时候，他们的族长记在册上。波斯王大利乌在位的时候，作族长的祭司也记在册上。'),
('CUV', '尼希米记', 16, 12, 23, '利未人作族长的记在历史上，直到以利亚实的儿子约哈难的时候。'),
('CUV', '尼希米记', 16, 12, 24, '利未人的族长是哈沙比雅、示利比、甲篾的儿子耶书亚，与他们弟兄的班次相对，照著神人大卫的命令一班一班地赞美称谢。'),
('CUV', '尼希米记', 16, 12, 25, '玛他尼、八布迦、俄巴底亚、米书兰、达们、亚谷是守门的，就是在库房那里守门。'),
('CUV', '尼希米记', 16, 12, 26, '这都是在约撒达的孙子、耶书亚的儿子约雅金和省长尼希米，并祭司文士以斯拉的时候，有职任的。'),
('CUV', '尼希米记', 16, 12, 27, '耶路撒冷城墙告成的时候，众民就把各处的利未人招到耶路撒冷，要称谢、歌唱、敲钹、鼓瑟、弹琴，欢欢喜喜地行告成之礼。'),
('CUV', '尼希米记', 16, 12, 28, '歌唱的人从耶路撒冷的周围和尼陀法的村庄与伯吉甲，又从迦巴和押玛弗的田地聚集，因为歌唱的人在耶路撒冷四围为自己立了村庄。'),
('CUV', '尼希米记', 16, 12, 29, 'a'),
('CUV', '尼希米记', 16, 12, 30, '祭司和利未人就洁净自己，也洁净百姓和城门，并城墙。'),
('CUV', '尼希米记', 16, 12, 31, '我带犹大的首领上城，使称谢的人分为两大队，排列而行：第一队在城上往右边向粪厂门行走，'),
('CUV', '尼希米记', 16, 12, 32, '在他们后头的有何沙雅与犹大首领的一半，'),
('CUV', '尼希米记', 16, 12, 33, '又有亚撒利雅、以斯拉、米书兰、'),
('CUV', '尼希米记', 16, 12, 34, '犹大、便雅悯、示玛雅、耶利米。'),
('CUV', '尼希米记', 16, 12, 35, '还有些吹号之祭司的子孙，约拿单的儿子撒迦利亚。约拿单是示玛雅的儿子；示玛雅是玛他尼的儿子；玛他尼是米该亚的儿子；米该亚是撒刻的儿子；撒刻是亚萨的儿子；'),
('CUV', '尼希米记', 16, 12, 36, '又有撒迦利亚的弟兄示玛雅、亚撒利、米拉莱、基拉莱、玛艾、拿坦业、犹大、哈拿尼，都拿著神人大卫的乐器，文士以斯拉引领他们。'),
('CUV', '尼希米记', 16, 12, 37, '他们经过泉门往前，从大卫城的台阶随地势而上，在大卫宫殿以上，直行到朝东的水门。'),
('CUV', '尼希米记', 16, 12, 38, '第二队称谢的人要与那一队相迎而行。我和民的一半跟随他们，在城墙上过了炉楼，直到宽墙；'),
('CUV', '尼希米记', 16, 12, 39, '又过了以法莲门、古门、鱼门、哈楠业楼、哈米亚楼，直到羊门，就在护卫门站住。'),
('CUV', '尼希米记', 16, 12, 40, '于是，这两队称谢的人连我和官长的一半，站在神的殿里。'),
('CUV', '尼希米记', 16, 12, 41, '还有祭司以利亚金、玛西雅、米拿民、米该雅、以利约乃、撒迦利亚、哈楠尼亚吹号；'),
('CUV', '尼希米记', 16, 12, 42, '又有玛西雅、示玛雅、以利亚撒、乌西、约哈难、玛基雅、以拦，和以谢奏乐。歌唱的就大声歌唱，伊斯拉希雅管理他们。'),
('CUV', '尼希米记', 16, 12, 43, '那日，众人献大祭而欢乐；因为神使他们大大欢乐，连妇女带孩童也都欢乐，甚至耶路撒冷中的欢声听到远处。'),
('CUV', '尼希米记', 16, 12, 44, '当日，派人管理库房，将举祭、初熟之物和所取的十分之一，就是按各城田地，照律法所定归给祭司和利未人的分，都收在里头。犹大人因祭司和利未人供职，就欢乐了。'),
('CUV', '尼希米记', 16, 12, 45, '祭司利未人遵守神所吩咐的，并守洁净的礼。歌唱的、守门的，照著大卫和他儿子所罗门的命令也如此行。'),
('CUV', '尼希米记', 16, 12, 46, '古时，在大卫和亚萨的日子，有歌唱的伶长，并有赞美称谢神的诗歌。'),
('CUV', '尼希米记', 16, 12, 47, '当所罗巴伯和尼希米的时候，以色列众人将歌唱的、守门的，每日所当得的分供给他们，又给利未人当得的分；利未人又给亚伦的子孙当得的分。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '尼希米记', 16, 13, 1, '当日，人念摩西的律法书给百姓听，遇见书上写著说，亚扪人和摩押人永不可入神的会；'),
('CUV', '尼希米记', 16, 13, 2, '因为他们没有拿食物和水来迎接以色列人，且雇了巴兰咒诅他们，但我们的神使那咒诅变为祝福。'),
('CUV', '尼希米记', 16, 13, 3, '以色列民听见这律法，就与一切闲杂人绝交'),
('CUV', '尼希米记', 16, 13, 4, '先是蒙派管理我们神殿中库房的祭司以利亚实与多比雅结亲，'),
('CUV', '尼希米记', 16, 13, 5, '便为他预备一间大屋子，就是从前收存素祭、乳香、器皿，和照命令供给利未人、歌唱的、守门的五谷、新酒，和油的十分之一，并归祭司举祭的屋子。'),
('CUV', '尼希米记', 16, 13, 6, '那时我不在耶路撒冷；因为巴比伦王亚达薛西三十二年，我回到王那里。过了多日，我向王告假。'),
('CUV', '尼希米记', 16, 13, 7, '我来到耶路撒冷，就知道以利亚实为多比雅在神殿的院内预备屋子的那件恶事。'),
('CUV', '尼希米记', 16, 13, 8, '我甚恼怒，就把多比雅的一切家具从屋里都抛出去，'),
('CUV', '尼希米记', 16, 13, 9, '吩咐人洁净这屋子，遂将神殿的器皿和素祭、乳香又搬进去。'),
('CUV', '尼希米记', 16, 13, 10, '我见利未人所当得的分无人供给他们，甚至供职的利未人与歌唱的俱各奔回自己的田地去了。'),
('CUV', '尼希米记', 16, 13, 11, '我就斥责官长说：为何离弃神的殿呢？我便招聚利未人，使他们照旧供职。'),
('CUV', '尼希米记', 16, 13, 12, '犹大众人就把五谷、新酒，和油的十分之一送入库房。'),
('CUV', '尼希米记', 16, 13, 13, '我派祭司示利米雅、文士撒督，和利未人毗大雅作库官管理库房；副官是哈难。哈难是撒刻的儿子；撒刻是玛他尼的儿子。这些人都是忠信的，他们的职分是将所供给的分给他们的弟兄。'),
('CUV', '尼希米记', 16, 13, 14, '我的神啊，求你因这事记念我，不要涂抹我为神的殿与其中的礼节所行的善。'),
('CUV', '尼希米记', 16, 13, 15, '那些日子，我在犹大见有人在安息日醡酒（原文是踹酒醡），搬运禾捆驮在驴上，又把酒、葡萄、无花果，和各样的担子在安息日担入耶路撒冷，我就在他们卖食物的那日警戒他们。'),
('CUV', '尼希米记', 16, 13, 16, '又有推罗人住在耶路撒冷；他们把鱼和各样货物运进来，在安息日卖给犹大人。'),
('CUV', '尼希米记', 16, 13, 17, '我就斥责犹大的贵胄说：你们怎么行这恶事犯了安息日呢？'),
('CUV', '尼希米记', 16, 13, 18, '从前你们列祖岂不是这样行，以致我们神使一切灾祸临到我们和这城么？现在你们还犯安息日，使忿怒越发临到以色列！'),
('CUV', '尼希米记', 16, 13, 19, '在安息日的前一日，耶路撒冷城门有黑影的时候，我就吩咐人将门关锁，不过安息日不准开放。我又派我几个仆人管理城门，免得有人在安息日担甚么担子进城。'),
('CUV', '尼希米记', 16, 13, 20, '于是商人和贩卖各样货物的，一两次住宿在耶路撒冷城外。'),
('CUV', '尼希米记', 16, 13, 21, '我就警戒他们说：你们为何在城外住宿呢？若再这样，我必下手拿办你们。从此以后，他们在安息日不再来了。'),
('CUV', '尼希米记', 16, 13, 22, '我吩咐利未人洁净自己，来守城门，使安息日为圣。我的神啊，求你因这事记念我，照你的大慈爱怜恤我。'),
('CUV', '尼希米记', 16, 13, 23, '那些日子，我也见犹大人娶了亚实突、亚扪、摩押的女子为妻。'),
('CUV', '尼希米记', 16, 13, 24, '他们的儿女说话，一半是亚实突的话，不会说犹大的话，所说的是照著各族的方言。'),
('CUV', '尼希米记', 16, 13, 25, '我就斥责他们，咒诅他们，打了他们几个人，拔下他们的头发，叫他们指著神起誓，必不将自己的女儿嫁给外邦人的儿子，也不为自己和儿子娶他们的女儿。'),
('CUV', '尼希米记', 16, 13, 26, '我又说：以色列王所罗门不是在这样的事上犯罪么？在多国中并没有一王像他，且蒙他神所爱，神立他作以色列全国的王；然而连他也被外邦女子引诱犯罪。'),
('CUV', '尼希米记', 16, 13, 27, '如此，我岂听你们行这大恶，娶外邦女子干犯我们的神呢？'),
('CUV', '尼希米记', 16, 13, 28, '大祭司以利亚实的孙子、耶何耶大的一个儿子是和伦人参巴拉的女婿，我就从我这里把他赶出去。'),
('CUV', '尼希米记', 16, 13, 29, '我的神啊，求你记念他们的罪；因为他们玷污了祭司的职任，违背你与祭司利未人所立的约。'),
('CUV', '尼希米记', 16, 13, 30, '这样，我洁净他们，使他们离绝一切外邦人，派定祭司和利未人的班次，使他们各尽其职。'),
('CUV', '尼希米记', 16, 13, 31, '我又派百姓按定期献柴和初熟的土产。我的神啊，求你记念我，施恩与我。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯帖记', 17, 1, 1, '亚哈随鲁作王，从印度直到古实，统管一百二十七省。'),
('CUV', '以斯帖记', 17, 1, 2, '亚哈随鲁王在书珊城的宫登基；'),
('CUV', '以斯帖记', 17, 1, 3, '在位第三年，为他一切首领臣仆设摆筵席，有波斯和玛代的权贵，就是各省的贵胄与首领，在他面前。'),
('CUV', '以斯帖记', 17, 1, 4, '他把他荣耀之国的丰富和他美好威严的尊贵给他们看了许多日，就是一百八十日。'),
('CUV', '以斯帖记', 17, 1, 5, '这日子满了，又为所有住书珊城的大小人民在御园的院子里设摆筵席七日。'),
('CUV', '以斯帖记', 17, 1, 6, '有白色、绿色、蓝色的帐子，用细麻绳、紫色绳从银环内系在白玉石柱上；有金银的床榻摆在红、白、黄、黑玉石铺的石地上。'),
('CUV', '以斯帖记', 17, 1, 7, '用金器皿赐酒，器皿各有不同。御酒甚多，足显王的厚意。'),
('CUV', '以斯帖记', 17, 1, 8, '喝酒有例，不准勉强人，因王吩咐宫里的一切臣宰，让人各随己意。'),
('CUV', '以斯帖记', 17, 1, 9, '王后瓦实提在亚哈随鲁王的宫内也为妇女设摆筵席。'),
('CUV', '以斯帖记', 17, 1, 10, '第七日，亚哈随鲁王饮酒，心中快乐，就吩咐在他面前侍立的七个太监米户幔、比斯他、哈波拿、比革他、亚拔他、西达、甲迦，'),
('CUV', '以斯帖记', 17, 1, 11, '请王后瓦实提头戴王后的冠冕到王面前，使各等臣民看他的美貌，因为他容貌甚美。'),
('CUV', '以斯帖记', 17, 1, 12, '王后瓦实提却不肯遵太监所传的王命而来，所以王甚发怒，心如火烧。'),
('CUV', '以斯帖记', 17, 1, 13, '那时，在王左右常见王面、国中坐高位的，有波斯和玛代的七个大臣，就是甲示拿、示达、押玛他、他施斯、米力、玛西拿、米母干，都是达时务的明哲人。按王的常规，办事必先询问知例明法的人。王问他们说：'),
('CUV', '以斯帖记', 17, 1, 14, 'a'),
('CUV', '以斯帖记', 17, 1, 15, '「王后瓦实提不遵太监所传的王命，照例应当怎样办理呢？」'),
('CUV', '以斯帖记', 17, 1, 16, '米母干在王和众首领面前回答说：王后瓦实提这事，不但得罪王，并且有害于王各省的臣民；'),
('CUV', '以斯帖记', 17, 1, 17, '因为王后这事必传到众妇人的耳中，说：『亚哈随鲁王吩咐王后瓦实提到王面前，他却不来』，他们就藐视自己的丈夫。'),
('CUV', '以斯帖记', 17, 1, 18, '今日波斯和玛代的众夫人听见王后这事，必向王的大臣照样行；从此必大开藐视和忿怒之端。'),
('CUV', '以斯帖记', 17, 1, 19, '王若以为美，就降旨写在波斯和玛代人的例中，永不更改，不准瓦实提再到王面前，将他王后的位分赐给比他还好的人。'),
('CUV', '以斯帖记', 17, 1, 20, '所降的旨意传遍通国（国度本来广大），所有的妇人，无论丈夫贵贱都必尊敬他。」'),
('CUV', '以斯帖记', 17, 1, 21, '王和众首领都以米母干的话为美，王就照这话去行，'),
('CUV', '以斯帖记', 17, 1, 22, '发诏书，用各省的文字、各族的方言通知各省，使为丈夫的在家中作主，各说本地的方言。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯帖记', 17, 2, 1, '这事以后，亚哈随鲁王的忿怒止息，就想念瓦实提和他所行的，并怎样降旨办他。'),
('CUV', '以斯帖记', 17, 2, 2, '于是王的侍臣对王说：不如为王寻找美貌的处女。'),
('CUV', '以斯帖记', 17, 2, 3, '王可以派官在国中的各省招聚美貌的处女到书珊城（或译：宫）的女院，交给掌管女子的太监希该，给他们当用的香品。'),
('CUV', '以斯帖记', 17, 2, 4, '王所喜爱的女子可以立为王后，代替瓦实提。」王以这事为美，就如此行。'),
('CUV', '以斯帖记', 17, 2, 5, '书珊城有一个犹大人，名叫末底改，是便雅悯人基士的曾孙，示每的孙子，睚珥的儿子。'),
('CUV', '以斯帖记', 17, 2, 6, '从前巴比伦王尼布甲尼撒将犹大王耶哥尼雅（又名约雅斤）和百姓从耶路撒冷掳去，末底改也在其内。'),
('CUV', '以斯帖记', 17, 2, 7, '末底改抚养他叔叔的女儿哈大沙（后名以斯帖），因为他没有父母。这女子又容貌俊美；他父母死了，末底改就收他为自己的女儿。'),
('CUV', '以斯帖记', 17, 2, 8, '王的谕旨传出，就招聚许多女子到书珊城，交给掌管女子的希该；以斯帖也送入王宫，交付希该。'),
('CUV', '以斯帖记', 17, 2, 9, '希该喜悦以斯帖，就恩待他，急忙给他需用的香品和他所当得的分，又派所当得的七个宫女服事他，使他和他的宫女搬入女院上好的房屋。'),
('CUV', '以斯帖记', 17, 2, 10, '以斯帖未曾将籍贯宗族告诉人，因为末底改嘱咐他不可叫人知道。'),
('CUV', '以斯帖记', 17, 2, 11, '末底改天天在女院前边行走，要知道以斯帖平安不平安，并后事如何。'),
('CUV', '以斯帖记', 17, 2, 12, '众女子照例先洁净身体十二个月：六个月用没药油，六个月用香料和洁身之物。满了日期，然后挨次进去见亚哈随鲁王。'),
('CUV', '以斯帖记', 17, 2, 13, '女子进去见王是这样：从女院到王宫的时候，凡他所要的都必给他。'),
('CUV', '以斯帖记', 17, 2, 14, '晚上进去，次日回到女子第二院，交给掌管妃嫔的太监沙甲；除非王喜爱他，再提名召他，就不再进去见王。'),
('CUV', '以斯帖记', 17, 2, 15, '末底改叔叔亚比孩的女儿，就是末底改收为自己女儿的以斯帖，按次序当进去见王的时候，除了掌管女子的太监希该所派定给他的，他别无所求。凡看见以斯帖的都喜悦他。'),
('CUV', '以斯帖记', 17, 2, 16, '亚哈随鲁王第七年十月，就是提别月，以斯帖被引入宫见王。'),
('CUV', '以斯帖记', 17, 2, 17, '王爱以斯帖过于爱众女，他在王眼前蒙宠爱比众处女更甚。王就把王后的冠冕戴在他头上，立他为王后，代替瓦实提。'),
('CUV', '以斯帖记', 17, 2, 18, '王因以斯帖的缘故给众首领和臣仆设摆大筵席，又豁免各省的租税，并照王的厚意大颁赏赐。'),
('CUV', '以斯帖记', 17, 2, 19, '第二次招聚处女的时候，末底改坐在朝门。'),
('CUV', '以斯帖记', 17, 2, 20, '以斯帖照著末底改所嘱咐的，还没有将籍贯宗族告诉人；因为以斯帖遵末底改的命，如抚养他的时候一样。'),
('CUV', '以斯帖记', 17, 2, 21, '当那时候，末底改坐在朝门，王的太监中有两个守门的，辟探和提列，恼恨亚哈随鲁王，想要下手害他。'),
('CUV', '以斯帖记', 17, 2, 22, '末底改知道了，就告诉王后以斯帖。以斯帖奉末底改的名，报告于王；'),
('CUV', '以斯帖记', 17, 2, 23, '究察这事，果然是实，就把二人挂在木头上，将这事在王面前写于历史上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯帖记', 17, 3, 1, '这事以后，亚哈随鲁王抬举亚甲族哈米大他的儿子哈曼，使他高升，叫他的爵位超过与他同事的一切臣宰。'),
('CUV', '以斯帖记', 17, 3, 2, '在朝门的一切臣仆都跪拜哈曼，因为王如此吩咐；惟独末底改不跪不拜。'),
('CUV', '以斯帖记', 17, 3, 3, '在朝门的臣仆问末底改说：「你为何违背王的命令呢？」'),
('CUV', '以斯帖记', 17, 3, 4, '他们天天劝他，他还是不听，他们就告诉哈曼，要看末底改的事站得住站不住，因他已经告诉他们自己是犹大人。'),
('CUV', '以斯帖记', 17, 3, 5, '哈曼见末底改不跪不拜，他就怒气填胸。'),
('CUV', '以斯帖记', 17, 3, 6, '他们已将末底改的本族告诉哈曼；他以为下手害末底改一人是小事，就要灭绝亚哈随鲁王通国所有的犹大人，就是末底改的本族。'),
('CUV', '以斯帖记', 17, 3, 7, '亚哈随鲁王十二年正月，就是尼散月，人在哈曼面前，按日日月月掣普珥，就是掣签，要定何月何日为吉，择定了十二月，就是亚达月。'),
('CUV', '以斯帖记', 17, 3, 8, '哈曼对亚哈随鲁王说：有一种民散居在王国各省的民中；他们的律例与万民的律例不同，也不守王的律例，所以容留他们与王无益。'),
('CUV', '以斯帖记', 17, 3, 9, '王若以为美，请下旨意灭绝他们；我就捐一万他连得银子交给掌管国帑的人，纳入王的府库。」'),
('CUV', '以斯帖记', 17, 3, 10, '于是王从自己手上摘下戒指给犹大人的仇敌─亚甲族哈米大他的儿子哈曼。'),
('CUV', '以斯帖记', 17, 3, 11, '王对哈曼说：「这银子仍赐给你，这民也交给你，你可以随意待他们。」'),
('CUV', '以斯帖记', 17, 3, 12, '正月十三日，就召了王的书记来，照著哈曼一切所吩咐的，用各省的文字、各族的方言，奉亚哈随鲁王的名写旨意，传与总督和各省的省长，并各族的首领；又用王的戒指盖印，'),
('CUV', '以斯帖记', 17, 3, 13, '交给驿卒传到王的各省，吩咐将犹大人，无论老少妇女孩子，在一日之间，十二月，就是亚达月十三日，全然剪除，杀戮灭绝，并夺他们的财为掠物。'),
('CUV', '以斯帖记', 17, 3, 14, '抄录这旨意，颁行各省，宣告各族，使他们预备等候那日。'),
('CUV', '以斯帖记', 17, 3, 15, '驿卒奉王命急忙起行，旨意也传遍书珊城。王同哈曼坐下饮酒，书珊城的民却都慌乱。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯帖记', 17, 4, 1, '末底改知道所做的这一切事，就撕裂衣服，穿麻衣，蒙灰尘，在城中行走，痛哭哀号。'),
('CUV', '以斯帖记', 17, 4, 2, '到了朝门前停住脚步，因为穿麻衣的不可进朝门。'),
('CUV', '以斯帖记', 17, 4, 3, '王的谕旨所到的各省各处，犹大人大大悲哀，禁食哭泣哀号，穿麻衣躺在灰中的甚多。'),
('CUV', '以斯帖记', 17, 4, 4, '王后以斯帖的宫女和太监来把这事告诉以斯帖，他甚是忧愁，就送衣服给末底改穿，要他脱下麻衣，他却不受。'),
('CUV', '以斯帖记', 17, 4, 5, '以斯帖就把王所派伺候他的一个太监，名叫哈他革召来，吩咐他去见末底改，要知道这是甚么事，是甚么缘故。'),
('CUV', '以斯帖记', 17, 4, 6, '于是哈他革出到朝门前的宽阔处见末底改。'),
('CUV', '以斯帖记', 17, 4, 7, '末底改将自己所遇的事，并哈曼为灭绝犹大人应许捐入王库的银数都告诉了他；'),
('CUV', '以斯帖记', 17, 4, 8, '又将所抄写传遍书珊城要灭绝犹大人的旨意交给哈他革，要给以斯帖看，又要给他说明，并嘱咐他进去见王，为本族的人在王面前恳切祈求。'),
('CUV', '以斯帖记', 17, 4, 9, '哈他革回来，将末底改的话告诉以斯帖；'),
('CUV', '以斯帖记', 17, 4, 10, '以斯帖就吩咐哈他革去见末底改，说：'),
('CUV', '以斯帖记', 17, 4, 11, '「王的一切臣仆和各省的人民都知道有一个定例：若不蒙召，擅入内院见王的，无论男女必被治死；除非王向他伸出金杖，不得存活。现在我没有蒙召进去见王已经三十日了。」'),
('CUV', '以斯帖记', 17, 4, 12, '人就把以斯帖这话告诉末底改。'),
('CUV', '以斯帖记', 17, 4, 13, '末底改托人回复以斯帖说：你莫想在王宫里强过一切犹大人，得免这祸。'),
('CUV', '以斯帖记', 17, 4, 14, '此时你若闭口不言，犹大人必从别处得解脱，蒙拯救；你和你父家必致灭亡。焉知你得了王后的位分不是为现今的机会吗？」'),
('CUV', '以斯帖记', 17, 4, 15, '以斯帖就吩咐人回报末底改说：'),
('CUV', '以斯帖记', 17, 4, 16, '「你当去招聚书珊城所有的犹大人，为我禁食三昼三夜，不吃不喝；我和我的宫女也要这样禁食。然后我违例进去见王，我若死就死吧！」'),
('CUV', '以斯帖记', 17, 4, 17, '于是末底改照以斯帖一切所吩咐的去行。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯帖记', 17, 5, 1, '第三日，以斯帖穿上朝服，进王宫的内院，对殿站立。王在殿里坐在宝座上，对著殿门。'),
('CUV', '以斯帖记', 17, 5, 2, '王见王后以斯帖站在院内，就施恩于她，向她伸出手中的金杖；以斯帖便向前摸杖头。'),
('CUV', '以斯帖记', 17, 5, 3, '王对他说：「王后以斯帖啊，你要甚么？你求甚么，就是国的一半也必赐给你。」'),
('CUV', '以斯帖记', 17, 5, 4, '以斯帖说：「王若以为美，就请王带著哈曼今日赴我所预备的筵席。」'),
('CUV', '以斯帖记', 17, 5, 5, '王说：「叫哈曼速速照以斯帖的话去行。」于是王带著哈曼赴以斯帖所预备的筵席。'),
('CUV', '以斯帖记', 17, 5, 6, '在酒席筵前，王又问以斯帖说：「你要甚么，我必赐给你；你求甚么，就是国的一半也必为你成就。」'),
('CUV', '以斯帖记', 17, 5, 7, '以斯帖回答说：我有所要，我有所求。'),
('CUV', '以斯帖记', 17, 5, 8, '我若在王眼前蒙恩，王若愿意赐我所要的，准我所求的，就请王带著哈曼再赴我所要预备的筵席。明日我必照王所问的说明。」'),
('CUV', '以斯帖记', 17, 5, 9, '那日哈曼心中快乐，欢欢喜喜地出来；但见末底改在朝门不站起来，连身也不动，就满心恼怒末底改。'),
('CUV', '以斯帖记', 17, 5, 10, '哈曼暂且忍耐回家，叫人请他朋友和他妻子细利斯来。'),
('CUV', '以斯帖记', 17, 5, 11, '哈曼将他富厚的荣耀、众多的儿女，和王抬举他使他超乎首领臣仆之上，都述说给他们听。'),
('CUV', '以斯帖记', 17, 5, 12, '哈曼又说：王后以斯帖预备筵席，除了我之外不许别人随王赴席。明日王后又请我随王赴席；'),
('CUV', '以斯帖记', 17, 5, 13, '只是我见犹大人末底改坐在朝门，虽有这一切荣耀，也与我无益。」'),
('CUV', '以斯帖记', 17, 5, 14, '他的妻细利斯和他一切的朋友对他说：「不如立一个五丈高的木架，明早求王将末底改挂在其上，然后你可以欢欢喜喜地随王赴席。」哈曼以这话为美，就叫人做了木架。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯帖记', 17, 6, 1, '那夜王睡不著觉，就吩咐人取历史来，念给他听。'),
('CUV', '以斯帖记', 17, 6, 2, '正遇见书上写著说：王的太监中有两个守门的，辟探和提列，想要下手害亚哈随鲁王，末底改将这事告诉王后。'),
('CUV', '以斯帖记', 17, 6, 3, '王说：「末底改行了这事，赐他甚么尊荣爵位没有？」伺候王的臣仆回答说：「没有赐他甚么。」'),
('CUV', '以斯帖记', 17, 6, 4, '王说：「谁在院子里？」（那时哈曼正进王宫的外院，要求王将末底改挂在他所预备的木架上。）'),
('CUV', '以斯帖记', 17, 6, 5, '臣仆说：「哈曼站在院内。」王说：「叫他进来。」'),
('CUV', '以斯帖记', 17, 6, 6, '哈曼就进去。王问他说：「王所喜悦尊荣的人，当如何待他呢？」哈曼心里说：「王所喜悦尊荣的，不是我是谁呢？」'),
('CUV', '以斯帖记', 17, 6, 7, '哈曼就回答说：王所喜悦尊荣的，'),
('CUV', '以斯帖记', 17, 6, 8, '当将王常穿的朝服和戴冠的御马，'),
('CUV', '以斯帖记', 17, 6, 9, '都交给王极尊贵的一个大臣，命他将衣服给王所喜悦尊荣的人穿上，使他骑上马，走遍城里的街市，在他面前宣告说：王所喜悦尊荣的人，就如此待他。」'),
('CUV', '以斯帖记', 17, 6, 10, '王对哈曼说：「你速速将这衣服和马，照你所说的，向坐在朝门的犹大人末底改去行。凡你所说的，一样不可缺。」'),
('CUV', '以斯帖记', 17, 6, 11, '于是哈曼将朝服给末底改穿上，使他骑上马，走遍城里的街市，在他面前宣告说：「王所喜悦尊荣的人，就如此待他。」'),
('CUV', '以斯帖记', 17, 6, 12, '末底改仍回到朝门，哈曼却忧忧闷闷地蒙著头，急忙回家去了，'),
('CUV', '以斯帖记', 17, 6, 13, '将所遇的一切事详细说给他的妻细利斯和他的众朋友听。他的智慧人和他的妻细利斯对他说：「你在末底改面前始而败落，他如果是犹大人，你必不能胜他，终必在他面前败落。」'),
('CUV', '以斯帖记', 17, 6, 14, '他们还与哈曼说话的时候，王的太监来催哈曼快去赴以斯帖所预备的筵席。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯帖记', 17, 7, 1, '王带著哈曼来赴王后以斯帖的筵席。'),
('CUV', '以斯帖记', 17, 7, 2, '这第二次在酒席筵前，王又问以斯帖说：「王后以斯帖啊，你要甚么，我必赐给你；你求甚么，就是国的一半也必为你成就。」'),
('CUV', '以斯帖记', 17, 7, 3, '王后以斯帖回答说：我若在王眼前蒙恩，王若以为美，我所愿的，是愿王将我的性命赐给我；我所求的，是求王将我的本族赐给我。'),
('CUV', '以斯帖记', 17, 7, 4, '因我和我的本族被卖了，要剪除杀戮灭绝我们。我们若被卖为奴为婢，我也闭口不言；但王的损失，敌人万不能补足。」'),
('CUV', '以斯帖记', 17, 7, 5, '亚哈随鲁王问王后以斯帖说：「擅敢起意如此行的是谁？这人在哪里呢？」'),
('CUV', '以斯帖记', 17, 7, 6, '以斯帖说：「仇人敌人就是这恶人哈曼！」哈曼在王和王后面前就甚惊惶。'),
('CUV', '以斯帖记', 17, 7, 7, '王便大怒，起来离开酒席往御园去了。哈曼见王定意要加罪与他，就起来，求王后以斯帖救命。'),
('CUV', '以斯帖记', 17, 7, 8, '王从御园回到酒席之处，见哈曼伏在以斯帖所靠的榻上；王说：「他竟敢在宫内、在我面前凌辱王后吗？」这话一出王口，人就蒙了哈曼的脸。'),
('CUV', '以斯帖记', 17, 7, 9, '伺候王的一个太监名叫哈波拿，说：「哈曼为那救王有功的末底改做了五丈高的木架，现今立在哈曼家里。」王说：「把哈曼挂在其上。」'),
('CUV', '以斯帖记', 17, 7, 10, '于是人将哈曼挂在他为末底改所预备的木架上。王的忿怒这才止息。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯帖记', 17, 8, 1, '当日，亚哈随鲁王把犹大人仇敌哈曼的家产赐给王后以斯帖。末底改也来到王面前，因为以斯帖已经告诉王，末底改是她的亲属。'),
('CUV', '以斯帖记', 17, 8, 2, '王摘下自己的戒指，就是从哈曼追回的，给了末底改。以斯帖派末底改管理哈曼的家产。'),
('CUV', '以斯帖记', 17, 8, 3, '以斯帖又俯伏在王脚前，流泪哀告，求他除掉亚甲族哈曼害犹大人的恶谋。'),
('CUV', '以斯帖记', 17, 8, 4, '王向以斯帖伸出金杖；以斯帖就起来，站在王前，'),
('CUV', '以斯帖记', 17, 8, 5, '说：亚甲族哈米大他的儿子哈曼设谋传旨，要杀灭在王各省的犹大人。现今王若愿意，我若在王眼前蒙恩，王若以为美，若喜悦我，请王另下旨意，废除哈曼所传的那旨意。'),
('CUV', '以斯帖记', 17, 8, 6, '我何忍见我本族的人受害？何忍见我同宗的人被灭呢？」'),
('CUV', '以斯帖记', 17, 8, 7, '亚哈随鲁王对王后以斯帖和犹大人末底改说：「因哈曼要下手害犹大人，我已将他的家产赐给以斯帖，人也将哈曼挂在木架上。'),
('CUV', '以斯帖记', 17, 8, 8, '现在你们可以随意奉王的名写谕旨给犹大人，用王的戒指盖印；因为奉王名所写、用王戒指盖印的谕旨，人都不能废除。」'),
('CUV', '以斯帖记', 17, 8, 9, '三月，就是西弯月二十三日，将王的书记召来，按著末底改所吩咐的，用各省的文字、各族的方言，并犹大人的文字方言写谕旨，传给那从印度直到古实一百二十七省的犹大人和总督省长首领。'),
('CUV', '以斯帖记', 17, 8, 10, '末底改奉亚哈随鲁王的名写谕旨，用王的戒指盖印，交给骑御马圈快马的驿卒，传到各处。'),
('CUV', '以斯帖记', 17, 8, 11, '谕旨中，王准各省各城的犹大人在一日之间，十二月，就是亚达月十三日，聚集保护性命，剪除杀戮灭绝那要攻击犹大人的一切仇敌和他们的妻子儿女，夺取他们的财为掠物。'),
('CUV', '以斯帖记', 17, 8, 12, 'a'),
('CUV', '以斯帖记', 17, 8, 13, '抄录这谕旨，颁行各省，宣告各族，使犹大人预备等候那日，在仇敌身上报仇。'),
('CUV', '以斯帖记', 17, 8, 14, '于是骑快马的驿卒被王命催促，急忙起行；谕旨也传遍书珊城。'),
('CUV', '以斯帖记', 17, 8, 15, '末底改穿著蓝色白色的朝服，头戴大金冠冕，又穿紫色细麻布的外袍，从王面前出来；书珊城的人民都欢呼快乐。'),
('CUV', '以斯帖记', 17, 8, 16, '犹大人有光荣，欢喜快乐而得尊贵。'),
('CUV', '以斯帖记', 17, 8, 17, '王的谕旨所到的各省各城，犹大人都欢喜快乐，设摆筵宴，以那日为吉日。那国的人民，有许多因惧怕犹大人，就入了犹大籍。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯帖记', 17, 9, 1, '十二月，乃亚达月十三日，王的谕旨将要举行，就是犹大人的仇敌盼望辖制他们的日子，犹大人反倒辖制恨他们的人。'),
('CUV', '以斯帖记', 17, 9, 2, '犹大人在亚哈随鲁王各省的城里聚集，下手击杀那要害他们的人。无人能敌挡他们，因为各族都惧怕他们。'),
('CUV', '以斯帖记', 17, 9, 3, '各省的首领、总督、省长，和办理王事的人，因惧怕末底改，就都帮助犹大人。'),
('CUV', '以斯帖记', 17, 9, 4, '末底改在朝中为大，名声传遍各省，日渐昌盛。'),
('CUV', '以斯帖记', 17, 9, 5, '犹大人用刀击杀一切仇敌，任意杀灭恨他们的人。'),
('CUV', '以斯帖记', 17, 9, 6, '在书珊城，犹大人杀灭了五百人；'),
('CUV', '以斯帖记', 17, 9, 7, '又杀巴珊大他、达分、亚斯帕他、'),
('CUV', '以斯帖记', 17, 9, 8, '破拉他、亚大利雅、亚利大他、'),
('CUV', '以斯帖记', 17, 9, 9, '帕玛斯他、亚利赛、亚利代、瓦耶撒他；'),
('CUV', '以斯帖记', 17, 9, 10, '这十人都是哈米大他的孙子、犹大人仇敌哈曼的儿子。犹大人却没有下手夺取财物。'),
('CUV', '以斯帖记', 17, 9, 11, '当日，将书珊城被杀的人数呈在王前。'),
('CUV', '以斯帖记', 17, 9, 12, '王对王后以斯帖说：「犹大人在书珊城杀灭了五百人，又杀了哈曼的十个儿子，在王的各省不知如何呢？现在你要甚么，我必赐给你；你还求甚么，也必为你成就。」'),
('CUV', '以斯帖记', 17, 9, 13, '以斯帖说：「王若以为美，求你准书珊的犹大人，明日也照今日的旨意行，并将哈曼十个儿子的尸首挂在木架上。」'),
('CUV', '以斯帖记', 17, 9, 14, '王便允准如此行。旨意传在书珊，人就把哈曼十个儿子的尸首挂起来了。'),
('CUV', '以斯帖记', 17, 9, 15, '亚达月十四日，书珊的犹大人又聚集在书珊，杀了三百人，却没有下手夺取财物。'),
('CUV', '以斯帖记', 17, 9, 16, '在王各省其余的犹大人也都聚集保护性命，杀了恨他们的人七万五千，却没有下手夺取财物。这样，就脱离仇敌，得享平安。'),
('CUV', '以斯帖记', 17, 9, 17, '亚达月十三日，行了这事；十四日安息，以这日为设筵欢乐的日子。'),
('CUV', '以斯帖记', 17, 9, 18, '但书珊的犹大人，这十三日、十四日聚集杀戮仇敌；十五日安息，以这日为设筵欢乐的日子。'),
('CUV', '以斯帖记', 17, 9, 19, '所以住无城墙乡村的犹大人，如今都以亚达月十四日为设筵欢乐的吉日，彼此餽送礼物。'),
('CUV', '以斯帖记', 17, 9, 20, '末底改记录这事，写信与亚哈随鲁王各省远近所有的犹大人，'),
('CUV', '以斯帖记', 17, 9, 21, '嘱咐他们每年守亚达月十四、十五两日，'),
('CUV', '以斯帖记', 17, 9, 22, '以这月的两日为犹大人脱离仇敌得平安、转忧为喜、转悲为乐的吉日。在这两日设筵欢乐，彼此餽送礼物，赒济穷人。'),
('CUV', '以斯帖记', 17, 9, 23, '于是，犹大人按著末底改所写与他们的信，应承照初次所守的守为永例；'),
('CUV', '以斯帖记', 17, 9, 24, '是因犹大人的仇敌亚甲族哈米大他的儿子哈曼设谋杀害犹大人，掣普珥，就是掣签，为要杀尽灭绝他们；'),
('CUV', '以斯帖记', 17, 9, 25, '这事报告于王，王便降旨使哈曼谋害犹大人的恶事归到他自己的头上，并吩咐把他和他的众子都挂在木架上。'),
('CUV', '以斯帖记', 17, 9, 26, '照著普珥.的名字，犹大人就称这两日为「普珥日」。他们因这信上的话，又因所看见所遇见的事，'),
('CUV', '以斯帖记', 17, 9, 27, '就应承自己与后裔，并归附他们的人，每年按时必守这两日，永远不废。'),
('CUV', '以斯帖记', 17, 9, 28, '各省各城、家家户户、世世代代纪念遵守这两日，使这「普珥日」在犹大人中不可废掉，在他们后裔中也不可忘记。'),
('CUV', '以斯帖记', 17, 9, 29, '亚比孩的女儿─王后以斯帖和犹大人末底改以全权写第二封信，坚嘱犹大人守这「普珥日」，'),
('CUV', '以斯帖记', 17, 9, 30, '用和平诚实话写信给亚哈随鲁王国中一百二十七省所有的犹大人，'),
('CUV', '以斯帖记', 17, 9, 31, '劝他们按时守这「普珥日」，禁食呼求，是照犹大人末底改和王后以斯帖所嘱咐的，也照犹大人为自己与后裔所应承的。'),
('CUV', '以斯帖记', 17, 9, 32, '以斯帖命定守「普珥日」，这事也记录在书上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以斯帖记', 17, 10, 1, '亚哈随鲁王使旱地和海岛的人民都进贡。'),
('CUV', '以斯帖记', 17, 10, 2, '他以权柄能力所行的，并他抬举末底改使他高升的事，岂不都写在玛代和波斯王的历史上吗？'),
('CUV', '以斯帖记', 17, 10, 3, '犹大人末底改作亚哈随鲁王的宰相，在犹大人中为大，得他众弟兄的喜悦，为本族的人求好处，向他们说和平的话。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 1, 1, '乌斯地有一个人名叫约伯；那人完全正直，敬畏神，远离恶事。'),
('CUV', '约伯记', 18, 1, 2, '他生了七个儿子，三个女儿。'),
('CUV', '约伯记', 18, 1, 3, '他的家产有七千羊，三千骆驼，五百对牛，五百母驴，并有许多仆婢。这人在东方人中就为至大。'),
('CUV', '约伯记', 18, 1, 4, '他的儿子按著日子各在自己家里设摆筵宴，就打发人去，请了他们的三个姊妹来，与他们一同吃喝。'),
('CUV', '约伯记', 18, 1, 5, '筵宴的日子过了，约伯打发人去叫他们自洁。他清早起来，按著他们众人的数目献燔祭；因为他说：恐怕我儿子犯了罪，心中弃掉神。约伯常常这样行。'),
('CUV', '约伯记', 18, 1, 6, '有一天，神的众子来侍立在耶和华面前，撒但也来在其中。'),
('CUV', '约伯记', 18, 1, 7, '耶和华问撒但说：「你从哪里来？」撒但回答说：「我从地上走来走去，往返而来。」'),
('CUV', '约伯记', 18, 1, 8, '耶和华问撒但说：「你曾用心察看我的仆人约伯没有？地上再没有人像他完全正直，敬畏神，远离恶事。」'),
('CUV', '约伯记', 18, 1, 9, '撒但回答耶和华说：约伯敬畏神，岂是无故呢？'),
('CUV', '约伯记', 18, 1, 10, '你岂不是四面圈上篱笆围护他和他的家，并他一切所有的吗？他手所做的都蒙你赐福；他的家产也在地上增多。'),
('CUV', '约伯记', 18, 1, 11, '你且伸手毁他一切所有的；他必当面弃掉你。」'),
('CUV', '约伯记', 18, 1, 12, '耶和华对撒但说：「凡他所有的都在你手中；只是不可伸手加害于他。」于是撒但从耶和华面前退去。'),
('CUV', '约伯记', 18, 1, 13, '有一天，约伯的儿女正在他们长兄的家里吃饭喝酒，'),
('CUV', '约伯记', 18, 1, 14, '有报信的来见约伯，说：牛正耕地，驴在旁边吃草，'),
('CUV', '约伯记', 18, 1, 15, '示巴人忽然闯来，把牲畜掳去，并用刀杀了仆人；惟有我一人逃脱，来报信给你。」'),
('CUV', '约伯记', 18, 1, 16, '他还说话的时候，又有人来说：「神从天上降下火来，将群羊和仆人都烧灭了；惟有我一人逃脱，来报信给你。」'),
('CUV', '约伯记', 18, 1, 17, '他还说话的时候，又有人来说：「迦勒底人分作三队忽然闯来，把骆驼掳去，并用刀杀了仆人；惟有我一人逃脱，来报信给你。」'),
('CUV', '约伯记', 18, 1, 18, '他还说话的时候，又有人来说：你的儿女正在他们长兄的家里吃饭喝酒，'),
('CUV', '约伯记', 18, 1, 19, '不料，有狂风从旷野刮来，击打房屋的四角，房屋倒塌在少年人身上，他们就都死了；惟有我一人逃脱，来报信给你。」'),
('CUV', '约伯记', 18, 1, 20, '约伯便起来，撕裂外袍，剃了头，伏在地上下拜，'),
('CUV', '约伯记', 18, 1, 21, '说：「我赤身出于母胎，也必赤身归回；赏赐的是耶和华，收取的也是耶和华。耶和华的名是应当称颂的。」'),
('CUV', '约伯记', 18, 1, 22, '在这一切的事上约伯并不犯罪，也不以神为愚妄（或译：也不妄评神）。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 2, 1, '又有一天，神的众子来侍立在耶和华面前，撒但也来在其中。'),
('CUV', '约伯记', 18, 2, 2, '耶和华问撒但说：你从哪里来？撒但回答说：我从地上走来走去，往返而来。'),
('CUV', '约伯记', 18, 2, 3, '耶和华问撒但说：你曾用心察看我的仆人约伯没有？地上再没有人像他完全正直，敬畏神，远离恶事。你虽激动我攻击他，无故地毁灭他，他仍然持守他的纯正。'),
('CUV', '约伯记', 18, 2, 4, '撒但回答耶和华说：人以皮代皮，情愿舍去一切所有的，保全性命。'),
('CUV', '约伯记', 18, 2, 5, '你且伸手伤他的骨头和他的肉，他必当面弃掉你。'),
('CUV', '约伯记', 18, 2, 6, '耶和华对撒但说：他在你手中，只要存留他的性命。'),
('CUV', '约伯记', 18, 2, 7, '于是撒但从耶和华面前退去，击打约伯，使他从脚掌到头顶长毒疮。'),
('CUV', '约伯记', 18, 2, 8, '约伯就坐在炉灰中，拿瓦片刮身体。'),
('CUV', '约伯记', 18, 2, 9, '他的妻子对他说：你仍然持守你的纯正么？你弃掉神，死了罢！'),
('CUV', '约伯记', 18, 2, 10, '约伯却对他说：你说话像愚顽的妇一样。嗳！难道我们从神手里得福，不也受祸么？在这一切的事上约伯并不以口犯罪。'),
('CUV', '约伯记', 18, 2, 11, '约伯的三个朋友─提幔人以利法、书亚人比勒达、拿玛人琐法─听说有这一切的灾祸临到他身上，各人就从本处约会同来，为他悲伤，安慰他。'),
('CUV', '约伯记', 18, 2, 12, '他们远远地举目观看，认不出他来，就放声大哭。各人撕裂外袍，把尘土向天扬起来，落在自己的头上。'),
('CUV', '约伯记', 18, 2, 13, '他们就同他七天七夜坐在地上，一个人也不向他说句话，因为他极其痛苦。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 3, 1, '此后，约伯开口咒诅自己的生日，'),
('CUV', '约伯记', 18, 3, 2, '说：'),
('CUV', '约伯记', 18, 3, 3, '愿我生的那日和说怀了男胎的那夜都灭没。'),
('CUV', '约伯记', 18, 3, 4, '愿那日变为黑暗；愿神不从上面寻找他；愿亮光不照于其上。'),
('CUV', '约伯记', 18, 3, 5, '愿黑暗和死荫索取那日；愿密云停在其上；愿日蚀恐吓他。'),
('CUV', '约伯记', 18, 3, 6, '愿那夜被幽暗夺取，不在年中的日子同乐，也不入月中的数目。'),
('CUV', '约伯记', 18, 3, 7, '愿那夜没有生育，其间也没有欢乐的声音。'),
('CUV', '约伯记', 18, 3, 8, '愿那咒诅日子且能惹动鳄鱼的咒诅那夜。'),
('CUV', '约伯记', 18, 3, 9, '愿那夜黎明的星宿变为黑暗，盼亮却不亮，也不见早晨的光线（原文是眼皮）；'),
('CUV', '约伯记', 18, 3, 10, '因没有把怀我胎的门关闭，也没有将患难对我的眼隐藏。'),
('CUV', '约伯记', 18, 3, 11, '我为何不出母胎而死？为何不出母腹绝气？'),
('CUV', '约伯记', 18, 3, 12, '为何有膝接收我？为何有奶哺养我？'),
('CUV', '约伯记', 18, 3, 13, '不然，我就早已躺卧安睡，'),
('CUV', '约伯记', 18, 3, 14, '和地上为自己重造荒邱的君王、谋士，'),
('CUV', '约伯记', 18, 3, 15, '或与有金子、将银子装满了房屋的王子一同安息；'),
('CUV', '约伯记', 18, 3, 16, '或像隐而未现、不到期而落的胎，归于无有，如同未见光的婴孩。'),
('CUV', '约伯记', 18, 3, 17, '在那里恶人止息搅扰，困乏人得享安息，'),
('CUV', '约伯记', 18, 3, 18, '被囚的人同得安逸，不听见督工的声音。'),
('CUV', '约伯记', 18, 3, 19, '大小都在那里；奴仆脱离主人的辖制。'),
('CUV', '约伯记', 18, 3, 20, '受患难的人为何有光赐给他呢？心中愁苦的人为何有生命赐给他呢？'),
('CUV', '约伯记', 18, 3, 21, '他们切望死，却不得死；求死，胜于求隐藏的珍宝。'),
('CUV', '约伯记', 18, 3, 22, '他们寻见坟墓就快乐，极其欢喜。'),
('CUV', '约伯记', 18, 3, 23, '人的道路既然遮隐，神又把他四面围困，为何有光赐给他呢？'),
('CUV', '约伯记', 18, 3, 24, '我未曾吃饭就发出叹息；我唉哼的声音涌出如水。'),
('CUV', '约伯记', 18, 3, 25, '因我所恐惧的临到我身，我所惧怕的迎我而来。'),
('CUV', '约伯记', 18, 3, 26, '我不得安逸，不得平静，也不得安息，却有患难来到。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 4, 1, '提幔人以利法回答说：'),
('CUV', '约伯记', 18, 4, 2, '人若想与你说话，你就厌烦么？但谁能忍住不说呢？'),
('CUV', '约伯记', 18, 4, 3, '你素来教导许多的人，又坚固软弱的手。'),
('CUV', '约伯记', 18, 4, 4, '你的言语曾扶助那将要跌倒的人；你又使软弱的膝稳固。'),
('CUV', '约伯记', 18, 4, 5, '但现在祸患临到你，你就昏迷，挨近你，你便惊惶。'),
('CUV', '约伯记', 18, 4, 6, '你的倚靠不是在你敬畏神么？你的盼望不是在你行事纯正么？'),
('CUV', '约伯记', 18, 4, 7, '请你追想：无辜的人有谁灭亡？正直的人在何处剪除？'),
('CUV', '约伯记', 18, 4, 8, '按我所见，耕罪孽、种毒害的人都照样收割。'),
('CUV', '约伯记', 18, 4, 9, '神一出气，他们就灭亡；神一发怒，他们就消没。'),
('CUV', '约伯记', 18, 4, 10, '狮子的吼叫和猛狮的声音尽都止息；少壮狮子的牙齿也都敲掉。'),
('CUV', '约伯记', 18, 4, 11, '老狮子因绝食而死；母狮之子也都离散。'),
('CUV', '约伯记', 18, 4, 12, '我暗暗地得了默示；我耳朵也听其细微的声音。'),
('CUV', '约伯记', 18, 4, 13, '在思念夜中、异象之间，世人沉睡的时候，'),
('CUV', '约伯记', 18, 4, 14, '恐惧、战兢临到我身，使我百骨打战。'),
('CUV', '约伯记', 18, 4, 15, '有灵从我面前经过，我身上的毫毛直立。'),
('CUV', '约伯记', 18, 4, 16, '那灵停住，我却不能辨其形状；有影像在我眼前。我在静默中听见有声音说：'),
('CUV', '约伯记', 18, 4, 17, '必死的人岂能比神公义么？人岂能比造他的主洁净么？'),
('CUV', '约伯记', 18, 4, 18, '主不信靠他的臣仆，并且指他的使者为愚昧；'),
('CUV', '约伯记', 18, 4, 19, '何况那住在土房、根基在尘土里、被蠹虫所毁坏的人呢？'),
('CUV', '约伯记', 18, 4, 20, '早晚之间，就被毁灭，永归无有，无人理会。'),
('CUV', '约伯记', 18, 4, 21, '他帐棚的绳索岂不从中抽出来呢？他死，且是无智慧而死。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 5, 1, '你且呼求，有谁答应你？诸圣者之中，你转向哪一位呢？'),
('CUV', '约伯记', 18, 5, 2, '忿怒害死愚妄人；嫉妒杀死痴迷人。'),
('CUV', '约伯记', 18, 5, 3, '我曾见愚妄人扎下根，但我忽然咒诅他的住处。'),
('CUV', '约伯记', 18, 5, 4, '他的儿女远离稳妥的地步，在城门口被压，并无人搭救。'),
('CUV', '约伯记', 18, 5, 5, '他的庄稼有饥饿的人吃尽了，就是在荆棘里的也抢去了；他的财宝有网罗张口吞灭了。'),
('CUV', '约伯记', 18, 5, 6, '祸患原不是从土中出来；患难也不是从地里发生。'),
('CUV', '约伯记', 18, 5, 7, '人生在世必遇患难，如同火星飞腾。'),
('CUV', '约伯记', 18, 5, 8, '至于我，我必仰望神，把我的事情托付他。'),
('CUV', '约伯记', 18, 5, 9, '他行大事不可测度，行奇事不可胜数：'),
('CUV', '约伯记', 18, 5, 10, '降雨在地上，赐水于田里；'),
('CUV', '约伯记', 18, 5, 11, '将卑微的安置在高处，将哀痛的举到稳妥之地；'),
('CUV', '约伯记', 18, 5, 12, '破坏狡猾人的计谋，使他们所谋的不得成就。'),
('CUV', '约伯记', 18, 5, 13, '他叫有智慧的中了自己的诡计，使狡诈人的计谋速速灭亡。'),
('CUV', '约伯记', 18, 5, 14, '他们白昼遇见黑暗，午间摸索如在夜间。'),
('CUV', '约伯记', 18, 5, 15, '神拯救穷乏人脱离他们口中的刀和强暴人的手。'),
('CUV', '约伯记', 18, 5, 16, '这样，贫寒的人有指望，罪孽之辈必塞口无言。'),
('CUV', '约伯记', 18, 5, 17, '神所惩治的人是有福的！所以你不可轻看全能者的管教。'),
('CUV', '约伯记', 18, 5, 18, '因为他打破，又缠裹；他击伤，用手医治。'),
('CUV', '约伯记', 18, 5, 19, '你六次遭难，他必救你；就是七次，灾祸也无法害你。'),
('CUV', '约伯记', 18, 5, 20, '在饥荒中，他必救你脱离死亡；在争战中，他必救你脱离刀剑的权力。'),
('CUV', '约伯记', 18, 5, 21, '你必被隐藏，不受口舌之害；灾殃临到，你也不惧怕。'),
('CUV', '约伯记', 18, 5, 22, '你遇见灾害饥馑，就必嬉笑；地上的野兽，你也不惧怕。'),
('CUV', '约伯记', 18, 5, 23, '因为你必与田间的石头立约；田里的野兽也必与你和好。'),
('CUV', '约伯记', 18, 5, 24, '你必知道你帐棚平安，要查看你的羊圈，一无所失；'),
('CUV', '约伯记', 18, 5, 25, '也必知道你的后裔将来发达，你的子孙像地上的青草。'),
('CUV', '约伯记', 18, 5, 26, '你必寿高年迈才归坟墓，好像禾捆到时收藏。'),
('CUV', '约伯记', 18, 5, 27, '这理，我们已经考察，本是如此。你须要听，要知道是与自己有益。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 6, 1, '约伯回答说：'),
('CUV', '约伯记', 18, 6, 2, '惟愿我的烦恼称一称，我一切的灾害放在天平里；'),
('CUV', '约伯记', 18, 6, 3, '现今都比海沙更重，所以我的言语急躁。'),
('CUV', '约伯记', 18, 6, 4, '因全能者的箭射入我身；其毒，我的灵喝尽了；神的惊吓摆阵攻击我。'),
('CUV', '约伯记', 18, 6, 5, '野驴有草岂能叫唤？牛有料岂能吼叫？'),
('CUV', '约伯记', 18, 6, 6, '物淡而无盐岂可吃么？蛋青有甚么滋味呢？'),
('CUV', '约伯记', 18, 6, 7, '看为可厌的食物，我心不肯挨近。'),
('CUV', '约伯记', 18, 6, 8, '惟愿我得著所求的，愿神赐我所切望的!'),
('CUV', '约伯记', 18, 6, 9, '就是愿神把我压碎，伸手将我剪除。'),
('CUV', '约伯记', 18, 6, 10, '我因没有违弃那圣者的言语，就仍以此为安慰，在不止息的痛苦中还可踊跃。'),
('CUV', '约伯记', 18, 6, 11, '我有甚么气力使我等候？我有甚么结局使我忍耐？'),
('CUV', '约伯记', 18, 6, 12, '我的气力岂是石头的气力？我的肉身岂是铜的呢？'),
('CUV', '约伯记', 18, 6, 13, '在我岂不是毫无帮助么？智慧岂不是从我心中赶出净尽么？'),
('CUV', '约伯记', 18, 6, 14, '那将要灰心、离弃全能者、不敬畏神的人，他的朋友当以慈爱待他。'),
('CUV', '约伯记', 18, 6, 15, '我的弟兄诡诈，好像溪水，又像溪水流干的河道。'),
('CUV', '约伯记', 18, 6, 16, '这河因结冰发黑，有雪藏在其中；'),
('CUV', '约伯记', 18, 6, 17, '天气渐暖就随时消化，日头炎热便从原处干涸。'),
('CUV', '约伯记', 18, 6, 18, '结伴的客旅离弃大道，顺河偏行，到荒野之地死亡。'),
('CUV', '约伯记', 18, 6, 19, '提玛结伴的客旅瞻望；示巴同伙的人等候。'),
('CUV', '约伯记', 18, 6, 20, '他们因失了盼望就抱愧，来到那里便蒙羞。'),
('CUV', '约伯记', 18, 6, 21, '现在你们正是这样，看见惊吓的事便惧怕。'),
('CUV', '约伯记', 18, 6, 22, '我岂说：请你们供给我，从你们的财物中送礼物给我？'),
('CUV', '约伯记', 18, 6, 23, '岂说：拯救我脱离敌人的手么？救赎我脱离强暴人的手么？'),
('CUV', '约伯记', 18, 6, 24, '请你们教导我，我便不作声；使我明白在何事上有错。'),
('CUV', '约伯记', 18, 6, 25, '正直的言语力量何其大！但你们责备是责备甚么呢？'),
('CUV', '约伯记', 18, 6, 26, '绝望人的讲论既然如风，你们还想要驳正言语么？'),
('CUV', '约伯记', 18, 6, 27, '你们想为孤儿拈阄，以朋友当货物。'),
('CUV', '约伯记', 18, 6, 28, '现在请你们看看我，我决不当面说谎。'),
('CUV', '约伯记', 18, 6, 29, '请你们转意，不要不公；请再转意，我的事有理。'),
('CUV', '约伯记', 18, 6, 30, '我的舌上岂有不义么？我的口里岂不辨奸恶么？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 7, 1, '人在世上岂无争战么？他的日子不像雇工人的日子么？'),
('CUV', '约伯记', 18, 7, 2, '像奴仆切慕黑影，像雇工人盼望工价；'),
('CUV', '约伯记', 18, 7, 3, '我也照样经过困苦的日月，夜间的疲乏为我而定。'),
('CUV', '约伯记', 18, 7, 4, '我躺卧的时候便说：我何时起来，黑夜就过去呢？我尽是反来覆去，直到天亮。'),
('CUV', '约伯记', 18, 7, 5, '我的肉体以虫子和尘土为衣；我的皮肤才收了口又重新破裂。'),
('CUV', '约伯记', 18, 7, 6, '我的日子比梭更快，都消耗在无指望之中。'),
('CUV', '约伯记', 18, 7, 7, '求你想念，我的生命不过是一口气；我的眼睛必不再见福乐。'),
('CUV', '约伯记', 18, 7, 8, '观看我的人，他的眼必不再见我；你的眼目要看我，我却不在了。'),
('CUV', '约伯记', 18, 7, 9, '云彩消散而过；照样，人下阴间也不再上来。'),
('CUV', '约伯记', 18, 7, 10, '他不再回自己的家；故土也不再认识他。'),
('CUV', '约伯记', 18, 7, 11, '我不禁止我口；我灵愁苦，要发出言语；我心苦恼，要吐露哀情。'),
('CUV', '约伯记', 18, 7, 12, '我对神说：我岂是洋海，岂是大鱼，你竟防守我呢？'),
('CUV', '约伯记', 18, 7, 13, '若说：我的床必安慰我，我的榻必解释我的苦情，'),
('CUV', '约伯记', 18, 7, 14, '你就用梦惊骇我，用异象恐吓我，'),
('CUV', '约伯记', 18, 7, 15, '甚至我宁肯噎死，宁肯死亡，胜似留我这一身的骨头。'),
('CUV', '约伯记', 18, 7, 16, '我厌弃性命，不愿永活。你任凭我罢，因我的日子都是虚空。'),
('CUV', '约伯记', 18, 7, 17, '人算甚么，你竟看他为大，将他放在心上？'),
('CUV', '约伯记', 18, 7, 18, '每早鉴察他，时刻试验他？'),
('CUV', '约伯记', 18, 7, 19, '你到何时才转眼不看我，才任凭我咽下唾沫呢？'),
('CUV', '约伯记', 18, 7, 20, '鉴察人的主啊，我若有罪，于你何妨？为何以我当你的箭靶子，使我厌弃自己的性命？'),
('CUV', '约伯记', 18, 7, 21, '为何不赦免我的过犯，除掉我的罪孽？我现今要躺卧在尘土中；你要殷勤地寻找我，我却不在了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 8, 1, '书亚人比勒达回答说：'),
('CUV', '约伯记', 18, 8, 2, '这些话你要说到几时？口中的言语如狂风要到几时呢？'),
('CUV', '约伯记', 18, 8, 3, '神岂能偏离公平？全能者岂能偏离公义？'),
('CUV', '约伯记', 18, 8, 4, '或者你的儿女得罪了他；他使他们受报应。'),
('CUV', '约伯记', 18, 8, 5, '你若殷勤地寻求神，向全能者恳求；'),
('CUV', '约伯记', 18, 8, 6, '你若清洁正直，他必定为你起来，使你公义的居所兴旺。'),
('CUV', '约伯记', 18, 8, 7, '你起初虽然微小，终久必甚发达。'),
('CUV', '约伯记', 18, 8, 8, '请你考问前代，追念他们的列祖所查究的。'),
('CUV', '约伯记', 18, 8, 9, '我们不过从昨日才有，一无所知；我们在世的日子好像影儿。'),
('CUV', '约伯记', 18, 8, 10, '他们岂不指教你，告诉你，从心里发出言语来呢？'),
('CUV', '约伯记', 18, 8, 11, '蒲草没有泥岂能发长？芦荻没有水岂能生发？'),
('CUV', '约伯记', 18, 8, 12, '尚青的时候，还没有割下，比百样的草先枯槁。'),
('CUV', '约伯记', 18, 8, 13, '凡忘记神的人，景况也是这样；不虔敬人的指望要灭没。'),
('CUV', '约伯记', 18, 8, 14, '他所仰赖的必折断；他所倚靠的是蜘蛛网。'),
('CUV', '约伯记', 18, 8, 15, '他要倚靠房屋，房屋却站立不住；他要抓住房屋，房屋却不能存留。'),
('CUV', '约伯记', 18, 8, 16, '他在日光之下发青，蔓子爬满了园子；'),
('CUV', '约伯记', 18, 8, 17, '他的根盘绕石堆，扎入石地。'),
('CUV', '约伯记', 18, 8, 18, '他若从本地被拔出，那地就不认识他，说：我没有见过你。'),
('CUV', '约伯记', 18, 8, 19, '看哪，这就是他道中之乐；以后必另有人从地而生。'),
('CUV', '约伯记', 18, 8, 20, '神必不丢弃完全人，也不扶助邪恶人。'),
('CUV', '约伯记', 18, 8, 21, '他还要以喜笑充满你的口，以欢呼充满你的嘴。'),
('CUV', '约伯记', 18, 8, 22, '恨恶你的要披戴惭愧；恶人的帐棚必归于无有。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 9, 1, '约伯回答说：'),
('CUV', '约伯记', 18, 9, 2, '我真知道是这样；但人在神面前怎能成为义呢？'),
('CUV', '约伯记', 18, 9, 3, '若愿意与他争辩，千中之一也不能回答。'),
('CUV', '约伯记', 18, 9, 4, '他心里有智慧，且大有能力。谁向神刚硬而得亨通呢？'),
('CUV', '约伯记', 18, 9, 5, '他发怒，把山翻倒挪移，山并不知觉。'),
('CUV', '约伯记', 18, 9, 6, '他使地震动，离其本位，地的柱子就摇撼。'),
('CUV', '约伯记', 18, 9, 7, '他吩咐日头不出来，就不出来，又封闭众星。'),
('CUV', '约伯记', 18, 9, 8, '他独自铺张苍天，步行在海浪之上。'),
('CUV', '约伯记', 18, 9, 9, '他造北斗、参星、昴星，并南方的密宫；'),
('CUV', '约伯记', 18, 9, 10, '他行大事，不可测度，行奇事，不可胜数。'),
('CUV', '约伯记', 18, 9, 11, '他从我旁边经过，我却不看见；他在我面前行走，我倒不知觉。'),
('CUV', '约伯记', 18, 9, 12, '他夺取，谁能阻挡？谁敢问他：你做甚么？'),
('CUV', '约伯记', 18, 9, 13, '神必不收回他的怒气；扶助拉哈伯的，屈身在他以下。'),
('CUV', '约伯记', 18, 9, 14, '既是这样，我怎敢回答他，怎敢选择言语与他辩论呢？'),
('CUV', '约伯记', 18, 9, 15, '我虽有义，也不回答他，只要向那审判我的恳求。'),
('CUV', '约伯记', 18, 9, 16, '我若呼吁，他应允我；我仍不信他真听我的声音。'),
('CUV', '约伯记', 18, 9, 17, '他用暴风折断我，无故地加增我的损伤。'),
('CUV', '约伯记', 18, 9, 18, '我就是喘一口气，他都不容，倒使我满心苦恼。'),
('CUV', '约伯记', 18, 9, 19, '若论力量，他真有能力！若论审判，他说谁能将我传来呢？'),
('CUV', '约伯记', 18, 9, 20, '我虽有义，自己的口要定我为有罪；我虽完全，我口必显我为弯曲。'),
('CUV', '约伯记', 18, 9, 21, '我本完全，不顾自己；我厌恶我的性命。'),
('CUV', '约伯记', 18, 9, 22, '善恶无分，都是一样；所以我说，完全人和恶人，他都灭绝。'),
('CUV', '约伯记', 18, 9, 23, '若忽然遭杀害之祸，他必戏笑无辜的人遇难。'),
('CUV', '约伯记', 18, 9, 24, '世界交在恶人手中；蒙蔽世界审判官的脸，若不是他，是谁呢？'),
('CUV', '约伯记', 18, 9, 25, '我的日子比跑信的更快，急速过去，不见福乐。'),
('CUV', '约伯记', 18, 9, 26, '我的日子过去如快船，如急落抓食的鹰。'),
('CUV', '约伯记', 18, 9, 27, '我若说：我要忘记我的哀情，除去我的愁容，心中畅快；'),
('CUV', '约伯记', 18, 9, 28, '我因愁苦而惧怕，知道你必不以我为无辜。'),
('CUV', '约伯记', 18, 9, 29, '我必被你定为有罪，我何必徒然劳苦呢？'),
('CUV', '约伯记', 18, 9, 30, '我若用雪水洗身，用碱洁净我的手，'),
('CUV', '约伯记', 18, 9, 31, '你还要扔我在坑里，我的衣服都憎恶我。'),
('CUV', '约伯记', 18, 9, 32, '他本不像我是人，使我可以回答他，又使我们可以同听审判。'),
('CUV', '约伯记', 18, 9, 33, '我们中间没有听讼的人可以向我们两造按手。'),
('CUV', '约伯记', 18, 9, 34, '愿他把杖离开我，不使惊惶威吓我。'),
('CUV', '约伯记', 18, 9, 35, '我就说话，也不惧怕他，现在我却不是那样。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 10, 1, '我厌烦我的性命，必由著自己述说我的哀情；因心里苦恼，我要说话，'),
('CUV', '约伯记', 18, 10, 2, '对神说：不要定我有罪，要指示我，你为何与我争辩？'),
('CUV', '约伯记', 18, 10, 3, '你手所造的，你又欺压，又藐视，却光照恶人的计谋。这事你以为美么？'),
('CUV', '约伯记', 18, 10, 4, '你的眼岂是肉眼？你查看岂像人查看么？'),
('CUV', '约伯记', 18, 10, 5, '你的日子岂像人的日子，你的年岁岂像人的年岁，'),
('CUV', '约伯记', 18, 10, 6, '就追问我的罪孽，寻察我的罪过么？'),
('CUV', '约伯记', 18, 10, 7, '其实，你知道我没有罪恶，并没有能救我脱离你手的。'),
('CUV', '约伯记', 18, 10, 8, '你的手创造我，造就我的四肢百体，你还要毁灭我。'),
('CUV', '约伯记', 18, 10, 9, '求你记念─制造我如抟泥一般，你还要使我归于尘土么？'),
('CUV', '约伯记', 18, 10, 10, '你不是倒出我来好像奶，使我凝结如同奶饼么？'),
('CUV', '约伯记', 18, 10, 11, '你以皮和肉为衣给我穿上，用骨与筋把我全体联络。'),
('CUV', '约伯记', 18, 10, 12, '你将生命和慈爱赐给我；你也眷顾保全我的心灵。'),
('CUV', '约伯记', 18, 10, 13, '然而，你待我的这些事早已藏在你心里；我知道你久有此意。'),
('CUV', '约伯记', 18, 10, 14, '我若犯罪，你就察看我，并不赦免我的罪孽。'),
('CUV', '约伯记', 18, 10, 15, '我若行恶，便有了祸；我若为义，也不敢抬头，正是满心羞愧，眼见我的苦情。'),
('CUV', '约伯记', 18, 10, 16, '我若昂首自得，你就追捕我如狮子，又在我身上显出奇能。'),
('CUV', '约伯记', 18, 10, 17, '你重立见证攻击我，向我加增恼怒，如军兵更换著攻击我。'),
('CUV', '约伯记', 18, 10, 18, '你为何使我出母胎呢？不如我当时气绝，无人得见我；'),
('CUV', '约伯记', 18, 10, 19, '这样，就如没有我一般，一出母胎就被送入坟墓。'),
('CUV', '约伯记', 18, 10, 20, '我的日子不是甚少么？求你停手宽容我，叫我在往而不返之先─就是往黑暗和死荫之地以先─可以稍得畅快。'),
('CUV', '约伯记', 18, 10, 21, 'a'),
('CUV', '约伯记', 18, 10, 22, '那地甚是幽暗，是死荫混沌之地；那里的光好像幽暗。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 11, 1, '拿玛人琐法回答说：'),
('CUV', '约伯记', 18, 11, 2, '这许多的言语岂不该回答么？多嘴多舌的人岂可称为义么？'),
('CUV', '约伯记', 18, 11, 3, '你夸大的话岂能使人不作声么？你戏笑的时候岂没有人叫你害羞么？'),
('CUV', '约伯记', 18, 11, 4, '你说：我的道理纯全；我在你眼前洁净。'),
('CUV', '约伯记', 18, 11, 5, '惟愿神说话；愿他开口攻击你，'),
('CUV', '约伯记', 18, 11, 6, '并将智慧的奥秘指示你；他有诸般的智识。所以当知道神追讨你比你罪孽该得的还少。'),
('CUV', '约伯记', 18, 11, 7, '你考察就能测透神吗？你岂能尽情测透全能者吗？'),
('CUV', '约伯记', 18, 11, 8, '他的智慧高于天，你还能做甚么？深于阴间，你还能知道甚么？'),
('CUV', '约伯记', 18, 11, 9, '其量比地长，比海宽。'),
('CUV', '约伯记', 18, 11, 10, '他若经过，将人拘禁，招人受审，谁能阻挡他呢？'),
('CUV', '约伯记', 18, 11, 11, '他本知道虚妄的人；人的罪孽，他虽不留意，还是无所不见。'),
('CUV', '约伯记', 18, 11, 12, '空虚的人却毫无知识；人生在世好像野驴的驹子。'),
('CUV', '约伯记', 18, 11, 13, '你若将心安正，又向主举手；'),
('CUV', '约伯记', 18, 11, 14, '你手里若有罪孽，就当远远地除掉，也不容非义住在你帐棚之中。'),
('CUV', '约伯记', 18, 11, 15, '那时，你必仰起脸来毫无斑点；你也必坚固，无所惧怕。'),
('CUV', '约伯记', 18, 11, 16, '你必忘记你的苦楚，就是想起也如流过去的水一样。'),
('CUV', '约伯记', 18, 11, 17, '你在世的日子要比正午更明，虽有黑暗仍像早晨。'),
('CUV', '约伯记', 18, 11, 18, '你因有指望就必稳固，也必四围巡查，坦然安息。'),
('CUV', '约伯记', 18, 11, 19, '你躺卧，无人惊吓，且有许多人向你求恩。'),
('CUV', '约伯记', 18, 11, 20, '但恶人的眼目必要失明。他们无路可逃；他们的指望就是气绝。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 12, 1, '约伯回答说：'),
('CUV', '约伯记', 18, 12, 2, '你们真是子民哪，你们死亡，智慧也就灭没了。'),
('CUV', '约伯记', 18, 12, 3, '但我也有聪明，与你们一样，并非不及你们。你们所说的，谁不知道呢？'),
('CUV', '约伯记', 18, 12, 4, '我这求告神、蒙他应允的人竟成了朋友所讥笑的；公义完全人竟受了人的讥笑。'),
('CUV', '约伯记', 18, 12, 5, '安逸的人心里藐视灾祸；这灾祸常常等待滑脚的人。'),
('CUV', '约伯记', 18, 12, 6, '强盗的帐棚兴旺，惹神的人稳固，神多将财物送到他们手中。'),
('CUV', '约伯记', 18, 12, 7, '你且问走兽，走兽必指教你；又问空中的飞鸟，飞鸟必告诉你；'),
('CUV', '约伯记', 18, 12, 8, '或与地说话，地必指教你；海中的鱼也必向你说明。'),
('CUV', '约伯记', 18, 12, 9, '看这一切，谁不知道是耶和华的手做成的呢？'),
('CUV', '约伯记', 18, 12, 10, '凡活物的生命和人类的气息都在他手中。'),
('CUV', '约伯记', 18, 12, 11, '耳朵岂不试验言语，正如上膛尝食物么？'),
('CUV', '约伯记', 18, 12, 12, '年老的有智慧；寿高的有知识。'),
('CUV', '约伯记', 18, 12, 13, '在神有智慧和能力；他有谋略和知识。'),
('CUV', '约伯记', 18, 12, 14, '他拆毁的，就不能再建造；他捆住人，便不得开释。'),
('CUV', '约伯记', 18, 12, 15, '他把水留住，水便枯干；他再发出水来，水就翻地。'),
('CUV', '约伯记', 18, 12, 16, '在他有能力和智慧，被诱惑的与诱惑人的都是属他。'),
('CUV', '约伯记', 18, 12, 17, '他把谋士剥衣掳去，又使审判官变成愚人。'),
('CUV', '约伯记', 18, 12, 18, '他放松君王的绑，又用带子捆他们的腰。'),
('CUV', '约伯记', 18, 12, 19, '他把祭司剥衣掳去，又使有能的人倾败。'),
('CUV', '约伯记', 18, 12, 20, '他废去忠信人的讲论，又夺去老人的聪明。'),
('CUV', '约伯记', 18, 12, 21, '他使君王蒙羞被辱，放松有力之人的腰带。'),
('CUV', '约伯记', 18, 12, 22, '他将深奥的事从黑暗中彰显，使死荫显为光明。'),
('CUV', '约伯记', 18, 12, 23, '他使邦国兴旺而又毁灭；他使邦国开广而又掳去。'),
('CUV', '约伯记', 18, 12, 24, '他将地上民中首领的聪明夺去，使他们在荒废无路之地漂流；'),
('CUV', '约伯记', 18, 12, 25, '他们无光，在黑暗中摸索，又使他们东倒西歪，像醉酒的人一样。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 13, 1, '这一切，我眼都见过；我耳都听过，而且明白。'),
('CUV', '约伯记', 18, 13, 2, '你们所知道的，我也知道，并非不及你们。'),
('CUV', '约伯记', 18, 13, 3, '我真要对全能者说话；我愿与神理论。'),
('CUV', '约伯记', 18, 13, 4, '你们是编造谎言的，都是无用的医生。'),
('CUV', '约伯记', 18, 13, 5, '惟愿你们全然不作声；这就算为你们的智慧！'),
('CUV', '约伯记', 18, 13, 6, '请你们听我的辩论，留心听我口中的分诉。'),
('CUV', '约伯记', 18, 13, 7, '你们要为神说不义的话么？为他说诡诈的言语么？'),
('CUV', '约伯记', 18, 13, 8, '你们要为神徇情么？要为他争论么？'),
('CUV', '约伯记', 18, 13, 9, '他查出你们来，这岂是好么？人欺哄人，你们也要照样欺哄他么？'),
('CUV', '约伯记', 18, 13, 10, '你们若暗中徇情，他必要责备你们。'),
('CUV', '约伯记', 18, 13, 11, '他的尊荣岂不叫你们惧怕么？他的惊吓岂不临到你们么？'),
('CUV', '约伯记', 18, 13, 12, '你们以为可记念的箴言是炉灰的箴言；你们以为可靠的坚垒是淤泥的坚垒。'),
('CUV', '约伯记', 18, 13, 13, '你们不要作声，任凭我罢！让我说话，无论如何我都承当。'),
('CUV', '约伯记', 18, 13, 14, '我何必把我的肉挂在牙上，将我的命放在手中。'),
('CUV', '约伯记', 18, 13, 15, '他必杀我；我虽无指望，然而我在他面前还要辩明我所行的。'),
('CUV', '约伯记', 18, 13, 16, '这要成为我的拯救，因为不虔诚的人不得到他面前。'),
('CUV', '约伯记', 18, 13, 17, '你们要细听我的言语，使我所辩论的入你们的耳中。'),
('CUV', '约伯记', 18, 13, 18, '我已陈明我的案，知道自己有义。'),
('CUV', '约伯记', 18, 13, 19, '有谁与我争论，我就情愿缄默不言，气绝而亡。'),
('CUV', '约伯记', 18, 13, 20, '惟有两件不要向我施行，我就不躲开你的面：'),
('CUV', '约伯记', 18, 13, 21, '就是把你的手缩回，远离我身；又不使你的惊惶威吓我。'),
('CUV', '约伯记', 18, 13, 22, '这样，你呼叫，我就回答；或是让我说话，你回答我。'),
('CUV', '约伯记', 18, 13, 23, '我的罪孽和罪过有多少呢？求你叫我知道我的过犯与罪愆。'),
('CUV', '约伯记', 18, 13, 24, '你为何掩面、拿我当仇敌呢？'),
('CUV', '约伯记', 18, 13, 25, '你要惊动被风吹的叶子么？要追赶枯干的碎秸么？'),
('CUV', '约伯记', 18, 13, 26, '你按罪状刑罚我，又使我担当幼年的罪孽；'),
('CUV', '约伯记', 18, 13, 27, '也把我的脚上了木狗，并窥察我一切的道路，为我的脚掌划定界限。'),
('CUV', '约伯记', 18, 13, 28, '我已经像灭绝的烂物，像虫蛀的衣裳。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 14, 1, '人为妇人所生，日子短少，多有患难；'),
('CUV', '约伯记', 18, 14, 2, '出来如花，又被割下，飞去如影，不能存留。'),
('CUV', '约伯记', 18, 14, 3, '这样的人你岂睁眼看他么？又叫我来受审么？'),
('CUV', '约伯记', 18, 14, 4, '谁能使洁净之物出于污秽之中呢？无论谁也不能！'),
('CUV', '约伯记', 18, 14, 5, '人的日子既然限定，他的月数在你那里，你也派定他的界限，使他不能越过，'),
('CUV', '约伯记', 18, 14, 6, '便求你转眼不看他，使他得歇息，直等他像雇工人完毕他的日子。'),
('CUV', '约伯记', 18, 14, 7, '树若被砍下，还可指望发芽，嫩枝生长不息；'),
('CUV', '约伯记', 18, 14, 8, '其根虽然衰老在地里，干也死在土中，'),
('CUV', '约伯记', 18, 14, 9, '及至得了水气，还要发芽，又长枝条，像新栽的树一样。'),
('CUV', '约伯记', 18, 14, 10, '但人死亡而消灭；他气绝，竟在何处呢？'),
('CUV', '约伯记', 18, 14, 11, '海中的水绝尽，江河消散干涸。'),
('CUV', '约伯记', 18, 14, 12, '人也是如此，躺下不再起来，等到天没有了，仍不得复醒，也不得从睡中唤醒。'),
('CUV', '约伯记', 18, 14, 13, '惟愿你把我藏在阴间，存于隐密处，等你的忿怒过去；愿你为我定了日期，记念我。'),
('CUV', '约伯记', 18, 14, 14, '人若死了岂能再活呢？我只要在我一切争战的日子，等我被释放（或译：改变）的时候来到。'),
('CUV', '约伯记', 18, 14, 15, '你呼叫，我便回答；你手所做的，你必羡慕。'),
('CUV', '约伯记', 18, 14, 16, '但如今你数点我的脚步，岂不窥察我的罪过么？'),
('CUV', '约伯记', 18, 14, 17, '我的过犯被你封在囊中，也缝严了我的罪孽。'),
('CUV', '约伯记', 18, 14, 18, '山崩变为无有；磐石挪开原处。'),
('CUV', '约伯记', 18, 14, 19, '水流消磨石头，所流溢的洗去地上的尘土；你也照样灭绝人的指望。'),
('CUV', '约伯记', 18, 14, 20, '你攻击人常常得胜，使他去世；你改变他的容貌，叫他往而不回。'),
('CUV', '约伯记', 18, 14, 21, '他儿子得尊荣，他也不知道，降为卑，他也不觉得。'),
('CUV', '约伯记', 18, 14, 22, '但知身上疼痛，心中悲哀。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 15, 1, '提幔人以利法回答说：'),
('CUV', '约伯记', 18, 15, 2, '智慧人岂可用虚空的知识回答，用东风充满肚腹呢？'),
('CUV', '约伯记', 18, 15, 3, '他岂可用无益的话和无济于事的言语理论呢？'),
('CUV', '约伯记', 18, 15, 4, '你是废弃敬畏的意，在神面前阻止敬虔的心。'),
('CUV', '约伯记', 18, 15, 5, '你的罪孽指教你的口；你选用诡诈人的舌头。'),
('CUV', '约伯记', 18, 15, 6, '你自己的口定你有罪，并非是我；你自己的嘴见证你的不是。'),
('CUV', '约伯记', 18, 15, 7, '你岂是头一个被生的人么？你受造在诸山之先么？'),
('CUV', '约伯记', 18, 15, 8, '你曾听见神的密旨么？你还将智慧独自得尽么？'),
('CUV', '约伯记', 18, 15, 9, '你知道甚么是我们不知道的呢？你明白甚么是我们不明白的呢？'),
('CUV', '约伯记', 18, 15, 10, '我们这里有白发的和年纪老迈的，比你父亲还老。'),
('CUV', '约伯记', 18, 15, 11, '神用温和的话安慰你，你以为太小么？'),
('CUV', '约伯记', 18, 15, 12, '你的心为何将你逼去？你的眼为何冒出火星，'),
('CUV', '约伯记', 18, 15, 13, '使你的灵反对神，也任你的口发这言语？'),
('CUV', '约伯记', 18, 15, 14, '人是甚么，竟算为洁净呢？妇人所生的是甚么，竟算为义呢？'),
('CUV', '约伯记', 18, 15, 15, '神不信靠他的众圣者；在他眼前，天也不洁净，'),
('CUV', '约伯记', 18, 15, 16, '何况那污秽可憎、喝罪孽如水的世人呢！'),
('CUV', '约伯记', 18, 15, 17, '我指示你，你要听；我要述说所看见的，'),
('CUV', '约伯记', 18, 15, 18, '就是智慧人从列祖所受，传说而不隐瞒的。'),
('CUV', '约伯记', 18, 15, 19, '（这地惟独赐给他们，并没有外人从他们中间经过。）'),
('CUV', '约伯记', 18, 15, 20, '恶人一生之日劬劳痛苦；强暴人一生的年数也是如此。'),
('CUV', '约伯记', 18, 15, 21, '惊吓的声音常在他耳中；在平安时，抢夺的必临到他那里。'),
('CUV', '约伯记', 18, 15, 22, '他不信自己能从黑暗中转回；他被刀剑等候。'),
('CUV', '约伯记', 18, 15, 23, '他漂流在外求食，说：哪里有食物呢？他知道黑暗的日子在他手边预备好了。'),
('CUV', '约伯记', 18, 15, 24, '急难困苦叫他害怕，而且胜了他，好像君王预备上阵一样。'),
('CUV', '约伯记', 18, 15, 25, '他伸手攻击神，以骄傲攻击全能者，'),
('CUV', '约伯记', 18, 15, 26, '挺著颈项，用盾牌的厚凸面向全能者直闯；'),
('CUV', '约伯记', 18, 15, 27, '是因他的脸蒙上脂油，腰积成肥肉。'),
('CUV', '约伯记', 18, 15, 28, '他曾住在荒凉城邑，无人居住、将成乱堆的房屋。'),
('CUV', '约伯记', 18, 15, 29, '他不得富足，财物不得常存，产业在地上也不加增。'),
('CUV', '约伯记', 18, 15, 30, '他不得出离黑暗。火燄要将他的枝子烧干；因神口中的气，他要灭亡（原文是走去）。'),
('CUV', '约伯记', 18, 15, 31, '他不用倚靠虚假欺哄自己，因虚假必成为他的报应。'),
('CUV', '约伯记', 18, 15, 32, '他的日期未到之先，这事必成就；他的枝子不得青绿。'),
('CUV', '约伯记', 18, 15, 33, '他必像葡萄树的葡萄，未熟而落；又像橄榄树的花，一开而谢。'),
('CUV', '约伯记', 18, 15, 34, '原来不敬虔之辈必无生育；受贿赂之人的帐棚必被火烧。'),
('CUV', '约伯记', 18, 15, 35, '他们所怀的是毒害，所生的是罪孽；心里所预备的是诡诈。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 16, 1, '约伯回答说：'),
('CUV', '约伯记', 18, 16, 2, '这样的话我听了许多；你们安慰人，反叫人愁烦。'),
('CUV', '约伯记', 18, 16, 3, '虚空的言语有穷尽么？有甚么话惹动你回答呢？'),
('CUV', '约伯记', 18, 16, 4, '我也能说你们那样的话；你们若处在我的境遇，我也会联络言语攻击你们，又能向你们摇头。'),
('CUV', '约伯记', 18, 16, 5, '但我必用口坚固你们，用嘴消解你们的忧愁。'),
('CUV', '约伯记', 18, 16, 6, '我虽说话，忧愁仍不得消解；我虽停住不说，忧愁就离开我么？'),
('CUV', '约伯记', 18, 16, 7, '但现在神使我困倦，使亲友远离我，'),
('CUV', '约伯记', 18, 16, 8, '又抓住我，作见证攻击我；我身体的枯瘦也当面见证我的不是。'),
('CUV', '约伯记', 18, 16, 9, '主发怒撕裂我，逼迫我，向我切齿；我的敌人怒目看我。'),
('CUV', '约伯记', 18, 16, 10, '他们向我开口，打我的脸羞辱我，聚会攻击我。'),
('CUV', '约伯记', 18, 16, 11, '神把我交给不敬虔的人，把我扔到恶人的手中。'),
('CUV', '约伯记', 18, 16, 12, '我素来安逸，他折断我，掐住我的颈项，把我摔碎，又立我为他的箭靶子。'),
('CUV', '约伯记', 18, 16, 13, '他的弓箭手四面围绕我；他破裂我的肺腑，并不留情，把我的胆倾倒在地上，'),
('CUV', '约伯记', 18, 16, 14, '将我破裂又破裂，如同勇士向我直闯。'),
('CUV', '约伯记', 18, 16, 15, '我缝麻布在我皮肤上，把我的角放在尘土中。'),
('CUV', '约伯记', 18, 16, 16, '我的脸因哭泣发紫，在我的眼皮上有死荫。'),
('CUV', '约伯记', 18, 16, 17, '我的手中却无强暴；我的祈祷也是清洁。'),
('CUV', '约伯记', 18, 16, 18, '地啊，不要遮盖我的血！不要阻挡我的哀求！'),
('CUV', '约伯记', 18, 16, 19, '现今，在天有我的见证，在上有我的中保。'),
('CUV', '约伯记', 18, 16, 20, '我的朋友讥诮我，我却向神眼泪汪汪。'),
('CUV', '约伯记', 18, 16, 21, '愿人得与神辩白，如同人与朋友辩白一样；'),
('CUV', '约伯记', 18, 16, 22, '因为再过几年，我必走那往而不返之路。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 17, 1, '我的心灵消耗，我的日子灭尽；坟墓为我预备好了。'),
('CUV', '约伯记', 18, 17, 2, '真有戏笑我的在我这里，我眼常见他们惹动我。'),
('CUV', '约伯记', 18, 17, 3, '愿主拿凭据给我，自己为我作保。在你以外谁肯与我击掌呢？'),
('CUV', '约伯记', 18, 17, 4, '因你使他们心不明理，所以你必不高举他们。'),
('CUV', '约伯记', 18, 17, 5, '控告他的朋友、以朋友为可抢夺的，连他儿女的眼睛也要失明。'),
('CUV', '约伯记', 18, 17, 6, '神使我作了民中的笑谈；他们也吐唾沫在我脸上。'),
('CUV', '约伯记', 18, 17, 7, '我的眼睛因忧愁昏花；我的百体好像影儿。'),
('CUV', '约伯记', 18, 17, 8, '正直人因此必惊奇；无辜的人要兴起攻击不敬虔之辈。'),
('CUV', '约伯记', 18, 17, 9, '然而，义人要持守所行的道；手洁的人要力上加力。'),
('CUV', '约伯记', 18, 17, 10, '至于你们众人，可以再来辩论罢！你们中间，我找不著一个智慧人。'),
('CUV', '约伯记', 18, 17, 11, '我的日子已经过了；我的谋算、我心所想望的已经断绝。'),
('CUV', '约伯记', 18, 17, 12, '他们以黑夜为白昼，说：亮光近乎黑暗。'),
('CUV', '约伯记', 18, 17, 13, '我若盼望阴间为我的房屋，若下榻在黑暗中，'),
('CUV', '约伯记', 18, 17, 14, '若对朽坏说：你是我的父；对虫说：你是我的母亲姊妹；'),
('CUV', '约伯记', 18, 17, 15, '这样，我的指望在哪里呢？我所指望的谁能看见呢？'),
('CUV', '约伯记', 18, 17, 16, '等到安息在尘土中，这指望必下到阴间的门闩那里了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 18, 1, '书亚人比勒达回答说：'),
('CUV', '约伯记', 18, 18, 2, '你寻索言语要到几时呢？你可以揣摩思想，然后我们就说话。'),
('CUV', '约伯记', 18, 18, 3, '我们为何算为畜生，在你眼中看作污秽呢？'),
('CUV', '约伯记', 18, 18, 4, '你这恼怒将自己撕裂的，难道大地为你见弃、磐石挪开原处么？'),
('CUV', '约伯记', 18, 18, 5, '恶人的亮光必要熄灭；他的火燄必不照耀。'),
('CUV', '约伯记', 18, 18, 6, '他帐棚中的亮光要变为黑暗；他以上的灯也必熄灭。'),
('CUV', '约伯记', 18, 18, 7, '他坚强的脚步必见狭窄；自己的计谋必将他绊倒。'),
('CUV', '约伯记', 18, 18, 8, '因为他被自己的脚陷入网中，走在缠人的网罗上。'),
('CUV', '约伯记', 18, 18, 9, '圈套必抓住他的脚跟；机关必擒获他。'),
('CUV', '约伯记', 18, 18, 10, '活扣为他藏在土内；羁绊为他藏在路上。'),
('CUV', '约伯记', 18, 18, 11, '四面的惊吓要使他害怕，并且追赶他的脚跟。'),
('CUV', '约伯记', 18, 18, 12, '他的力量必因饥饿衰败；祸患要在他旁边等候。'),
('CUV', '约伯记', 18, 18, 13, '他本身的肢体要被吞吃；死亡的长子要吞吃他的肢体。'),
('CUV', '约伯记', 18, 18, 14, '他要从所倚靠的帐棚被拔出来，带到惊吓的王那里。'),
('CUV', '约伯记', 18, 18, 15, '不属他的必住在他的帐棚里；硫磺必撒在他所住之处。'),
('CUV', '约伯记', 18, 18, 16, '下边，他的根本要枯干；上边，他的枝子要剪除。'),
('CUV', '约伯记', 18, 18, 17, '他的记念在地上必然灭亡；他的名字在街上也不存留。'),
('CUV', '约伯记', 18, 18, 18, '他必从光明中被撵到黑暗里，必被赶出世界。'),
('CUV', '约伯记', 18, 18, 19, '在本民中必无子无孙；在寄居之地也无一人存留。'),
('CUV', '约伯记', 18, 18, 20, '以后来的要惊奇他的日子，好像以前去的受了惊骇。'),
('CUV', '约伯记', 18, 18, 21, '不义之人的住处总是这样；此乃不认识神之人的地步。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 19, 1, '约伯回答说：'),
('CUV', '约伯记', 18, 19, 2, '你们搅扰我的心，用言语压碎我要到几时呢？'),
('CUV', '约伯记', 18, 19, 3, '你们这十次羞辱我；你们苦待我也不以为耻。'),
('CUV', '约伯记', 18, 19, 4, '果真我有错，这错乃是在我。'),
('CUV', '约伯记', 18, 19, 5, '你们果然要向我夸大，以我的羞辱为证指责我，'),
('CUV', '约伯记', 18, 19, 6, '就该知道是神倾覆我，用网罗围绕我。'),
('CUV', '约伯记', 18, 19, 7, '我因委曲呼叫，却不蒙应允；我呼求，却不得公断。'),
('CUV', '约伯记', 18, 19, 8, '神用篱笆拦住我的道路，使我不得经过；又使我的路径黑暗。'),
('CUV', '约伯记', 18, 19, 9, '他剥去我的荣光，摘去我头上的冠冕。'),
('CUV', '约伯记', 18, 19, 10, '他在四围攻击我，我便归于死亡，将我的指望如树拔出来。'),
('CUV', '约伯记', 18, 19, 11, '他的忿怒向我发作，以我为敌人。'),
('CUV', '约伯记', 18, 19, 12, '他的军旅一齐上来，修筑战路攻击我，在我帐棚的四围安营。'),
('CUV', '约伯记', 18, 19, 13, '他把我的弟兄隔在远处，使我所认识的全然与我生疏。'),
('CUV', '约伯记', 18, 19, 14, '我的亲戚与我断绝；我的密友都忘记我。'),
('CUV', '约伯记', 18, 19, 15, '在我家寄居的，和我的使女都以我为外人；我在他们眼中看为外邦人。'),
('CUV', '约伯记', 18, 19, 16, '我呼唤仆人，虽用口求他，他还是不回答。'),
('CUV', '约伯记', 18, 19, 17, '我口的气味，我妻子厌恶；我的恳求，我同胞也憎嫌。'),
('CUV', '约伯记', 18, 19, 18, '连小孩子也藐视我；我若起来，他们都嘲笑我。'),
('CUV', '约伯记', 18, 19, 19, '我的密友都憎恶我；我平日所爱的人向我翻脸。'),
('CUV', '约伯记', 18, 19, 20, '我的皮肉紧贴骨头；我只剩牙皮逃脱了。'),
('CUV', '约伯记', 18, 19, 21, '我朋友啊，可怜我！可怜我！因为神的手攻击我。'),
('CUV', '约伯记', 18, 19, 22, '你们为甚么仿佛神逼迫我，吃我的肉还以为不足呢？'),
('CUV', '约伯记', 18, 19, 23, '惟愿我的言语现在写上，都记录在书上；'),
('CUV', '约伯记', 18, 19, 24, '用铁笔镌刻，用铅灌在磐石上，直存到永远。'),
('CUV', '约伯记', 18, 19, 25, '我知道我的救赎主活著，末了必站立在地上。'),
('CUV', '约伯记', 18, 19, 26, '我这皮肉灭绝之后，我必在肉体之外得见神。'),
('CUV', '约伯记', 18, 19, 27, '我自己要见他，亲眼要看他，并不像外人。我的心肠在我里面消灭了！'),
('CUV', '约伯记', 18, 19, 28, '你们若说：我们逼迫他要何等地重呢？惹事的根乃在乎他；'),
('CUV', '约伯记', 18, 19, 29, '你们就当惧怕刀剑；因为忿怒惹动刀剑的刑罚，使你们知道有报应（原文是审判）。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 20, 1, '拿玛人琐法回答说：'),
('CUV', '约伯记', 18, 20, 2, '我心中急躁，所以我的思念叫我回答。'),
('CUV', '约伯记', 18, 20, 3, '我已听见那羞辱我，责备我的话；我的悟性叫我回答。'),
('CUV', '约伯记', 18, 20, 4, '你岂不知亘古以来，自从人生在地，'),
('CUV', '约伯记', 18, 20, 5, '恶人夸胜是暂时的，不敬虔人的喜乐不过转眼之间么？'),
('CUV', '约伯记', 18, 20, 6, '他的尊荣虽达到天上，头虽顶到云中，'),
('CUV', '约伯记', 18, 20, 7, '他终必灭亡，像自己的粪一样；素来见他的人要说：他在哪里呢？'),
('CUV', '约伯记', 18, 20, 8, '他必飞去如梦，不再寻见，速被赶去，如夜间的异象。'),
('CUV', '约伯记', 18, 20, 9, '亲眼见过他的，必不再见他；他的本处也再见不著他。'),
('CUV', '约伯记', 18, 20, 10, '他的儿女要求穷人的恩；他的手要赔还不义之财。'),
('CUV', '约伯记', 18, 20, 11, '他的骨头虽然有青年之力，却要和他一同躺卧在尘土中。'),
('CUV', '约伯记', 18, 20, 12, '他口内虽以恶为甘甜，藏在舌头底下，'),
('CUV', '约伯记', 18, 20, 13, '爱恋不舍，含在口中；'),
('CUV', '约伯记', 18, 20, 14, '他的食物在肚里却要化为酸，在他里面成为虺蛇的恶毒。'),
('CUV', '约伯记', 18, 20, 15, '他吞了财宝，还要吐出；神要从他腹中掏出来。'),
('CUV', '约伯记', 18, 20, 16, '他必吸饮虺蛇的毒气；蝮蛇的舌头也必杀他。'),
('CUV', '约伯记', 18, 20, 17, '流奶与蜜之河，他不得再见。'),
('CUV', '约伯记', 18, 20, 18, '他劳碌得来的要赔还，不得享用（原文是吞下）；不能照所得的财货欢乐。'),
('CUV', '约伯记', 18, 20, 19, '他欺压穷人，且又离弃；强取非自己所盖的房屋（或译：强取房屋不得再建造）。'),
('CUV', '约伯记', 18, 20, 20, '他因贪而无厌，所喜悦的连一样也不能保守。'),
('CUV', '约伯记', 18, 20, 21, '其余的没有一样他不吞灭，所以他的福乐不能长久。'),
('CUV', '约伯记', 18, 20, 22, '他在满足有余的时候，必到狭窄的地步；凡受苦楚的人都必加手在他身上。'),
('CUV', '约伯记', 18, 20, 23, '他正要充满肚腹的时候，神必将猛烈的忿怒降在他身上；正在他吃饭的时候，要将这忿怒像雨降在他身上。'),
('CUV', '约伯记', 18, 20, 24, '他要躲避铁器；铜弓的箭要将他射透。'),
('CUV', '约伯记', 18, 20, 25, '他把箭一抽，就从他身上出来；发光的箭头从他胆中出来，有惊惶临在他身上。'),
('CUV', '约伯记', 18, 20, 26, '他的财宝归于黑暗；人所不吹的火要把他烧灭，要把他帐棚中所剩下的烧毁。'),
('CUV', '约伯记', 18, 20, 27, '天要显明他的罪孽；地要兴起攻击他。'),
('CUV', '约伯记', 18, 20, 28, '他的家产必然过去；神发怒的日子，他的货物都要消灭。'),
('CUV', '约伯记', 18, 20, 29, '这是恶人从神所得的分，是神为他所定的产业。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 21, 1, '约伯回答说：'),
('CUV', '约伯记', 18, 21, 2, '你们要细听我的言语，就算是你们安慰我。'),
('CUV', '约伯记', 18, 21, 3, '请宽容我，我又要说话；说了以后，任凭你们嗤笑罢！'),
('CUV', '约伯记', 18, 21, 4, '我岂是向人诉冤？为何不焦急呢？'),
('CUV', '约伯记', 18, 21, 5, '你们要看著我而惊奇，用手摀口。'),
('CUV', '约伯记', 18, 21, 6, '我每逢思想，心就惊惶，浑身战兢。'),
('CUV', '约伯记', 18, 21, 7, '恶人为何存活，享大寿数，势力强盛呢？'),
('CUV', '约伯记', 18, 21, 8, '他们眼见儿孙，和他们一同坚立。'),
('CUV', '约伯记', 18, 21, 9, '他们的家宅平安无惧；神的杖也不加在他们身上。'),
('CUV', '约伯记', 18, 21, 10, '他们的公牛孳生而不断绝；母牛下犊而不掉胎。'),
('CUV', '约伯记', 18, 21, 11, '他们打发小孩子出去，多如羊群；他们的儿女踊跃跳舞。'),
('CUV', '约伯记', 18, 21, 12, '他们随著琴鼓歌唱，又因箫声欢喜。'),
('CUV', '约伯记', 18, 21, 13, '他们度日诸事亨通，转眼下入阴间。'),
('CUV', '约伯记', 18, 21, 14, '他们对神说：离开我们罢！我们不愿晓得你的道。'),
('CUV', '约伯记', 18, 21, 15, '全能者是谁，我们何必事奉他呢？求告他有甚么益处呢？'),
('CUV', '约伯记', 18, 21, 16, '看哪，他们亨通不在乎自己；恶人所谋定的离我好远。'),
('CUV', '约伯记', 18, 21, 17, '恶人的灯何尝熄灭？患难何尝临到他们呢？神何尝发怒，向他们分散灾祸呢？'),
('CUV', '约伯记', 18, 21, 18, '他们何尝像风前的碎秸，如暴风刮去的糠秕呢？'),
('CUV', '约伯记', 18, 21, 19, '你们说：神为恶人的儿女积蓄罪孽；我说：不如本人受报，好使他亲自知道。'),
('CUV', '约伯记', 18, 21, 20, '愿他亲眼看见自己败亡，亲自饮全能者的忿怒。'),
('CUV', '约伯记', 18, 21, 21, '他的岁月既尽，他还顾他本家么？'),
('CUV', '约伯记', 18, 21, 22, '神既审判那在高位的，谁能将知识教训他呢？'),
('CUV', '约伯记', 18, 21, 23, '有人至死身体强壮，尽得平靖安逸；'),
('CUV', '约伯记', 18, 21, 24, '他的奶桶充满，他的骨髓滋润。'),
('CUV', '约伯记', 18, 21, 25, '有人至死心中痛苦，终身未尝福乐的滋味；'),
('CUV', '约伯记', 18, 21, 26, '他们一样躺卧在尘土中，都被虫子遮盖。'),
('CUV', '约伯记', 18, 21, 27, '我知道你们的意思，并诬害我的计谋。'),
('CUV', '约伯记', 18, 21, 28, '你们说：霸者的房屋在哪里？恶人住过的帐棚在哪里？'),
('CUV', '约伯记', 18, 21, 29, '你们岂没有询问过路的人么？不知道他们所引的证据么？'),
('CUV', '约伯记', 18, 21, 30, '就是恶人在祸患的日子得存留，在发怒的日子得逃脱。'),
('CUV', '约伯记', 18, 21, 31, '他所行的，有谁当面给他说明；他所做的，有谁报应他呢？'),
('CUV', '约伯记', 18, 21, 32, '然而他要被抬到茔地；并有人看守坟墓。'),
('CUV', '约伯记', 18, 21, 33, '他要以谷中的土块为甘甜；在他以先去的无数，在他以后去的更多。'),
('CUV', '约伯记', 18, 21, 34, '你们对答的话中既都错谬，怎么徒然安慰我呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 22, 1, '提幔人以利法回答说：'),
('CUV', '约伯记', 18, 22, 2, '人岂能使神有益呢？智慧人但能有益于己。'),
('CUV', '约伯记', 18, 22, 3, '你为人公义，岂叫全能者喜悦呢？你行为完全，岂能使他得利呢？'),
('CUV', '约伯记', 18, 22, 4, '岂是因你敬畏他就责备你、审判你么？'),
('CUV', '约伯记', 18, 22, 5, '你的罪恶岂不是大么？你的罪孽也没有穷尽；'),
('CUV', '约伯记', 18, 22, 6, '因你无故强取弟兄的物为当头，剥去贫寒人的衣服。'),
('CUV', '约伯记', 18, 22, 7, '困乏的人，你没有给他水喝；饥饿的人，你没有给他食物。'),
('CUV', '约伯记', 18, 22, 8, '有能力的人就得地土；尊贵的人也住在其中。'),
('CUV', '约伯记', 18, 22, 9, '你打发寡妇空手回去，折断孤儿的膀臂。'),
('CUV', '约伯记', 18, 22, 10, '因此，有网罗环绕你，有恐惧忽然使你惊惶；'),
('CUV', '约伯记', 18, 22, 11, '或有黑暗蒙蔽你，并有洪水淹没你。'),
('CUV', '约伯记', 18, 22, 12, '神岂不是在高天么？你看星宿何其高呢！'),
('CUV', '约伯记', 18, 22, 13, '你说：神知道甚么？他岂能看透幽暗施行审判呢？'),
('CUV', '约伯记', 18, 22, 14, '密云将他遮盖，使他不能看见；他周游穹苍。'),
('CUV', '约伯记', 18, 22, 15, '你要依从上古的道么？这道是恶人所行的。'),
('CUV', '约伯记', 18, 22, 16, '他们未到死期，忽然除灭；根基毁坏，好像被江河冲去。'),
('CUV', '约伯记', 18, 22, 17, '他们向神说：离开我们罢！又说：全能者能把我们怎么样呢？'),
('CUV', '约伯记', 18, 22, 18, '哪知神以美物充满他们的房屋；但恶人所谋定的离我好远。'),
('CUV', '约伯记', 18, 22, 19, '义人看见他们的结局就欢喜；无辜的人嗤笑他们，'),
('CUV', '约伯记', 18, 22, 20, '说：那起来攻击我们的果然被剪除，其余的都被火烧灭。'),
('CUV', '约伯记', 18, 22, 21, '你要认识神，就得平安；福气也必临到你。'),
('CUV', '约伯记', 18, 22, 22, '你当领受他口中的教训，将他的言语存在心里。'),
('CUV', '约伯记', 18, 22, 23, '你若归向全能者，从你帐棚中远除不义，就必得建立。'),
('CUV', '约伯记', 18, 22, 24, '要将你的珍宝丢在尘土里，将俄斐的黄金丢在溪河石头之间；'),
('CUV', '约伯记', 18, 22, 25, '全能者就必为你的珍宝，作你的宝银。'),
('CUV', '约伯记', 18, 22, 26, '你就要以全能者为喜乐，向神仰起脸来。'),
('CUV', '约伯记', 18, 22, 27, '你要祷告他，他就听你；你也要还你的愿。'),
('CUV', '约伯记', 18, 22, 28, '你定意要做何事，必然给你成就；亮光也必照耀你的路。'),
('CUV', '约伯记', 18, 22, 29, '人使你降卑，你仍可说：必得高升；谦卑的人，神必然拯救。'),
('CUV', '约伯记', 18, 22, 30, '人非无辜，神且要搭救他；他因你手中清洁，必蒙拯救。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 23, 1, '约伯回答说：'),
('CUV', '约伯记', 18, 23, 2, '如今我的哀告还算为悖逆；我的责罚比我的唉哼还重。'),
('CUV', '约伯记', 18, 23, 3, '惟愿我能知道在哪里可以寻见神，能到他的台前，'),
('CUV', '约伯记', 18, 23, 4, '我就在他面前将我的案件陈明，满口辩白。'),
('CUV', '约伯记', 18, 23, 5, '我必知道他回答我的言语，明白他向我所说的话。'),
('CUV', '约伯记', 18, 23, 6, '他岂用大能与我争辩么？必不这样！他必理会我。'),
('CUV', '约伯记', 18, 23, 7, '在他那里正直人可以与他辩论；这样，我必永远脱离那审判我的。'),
('CUV', '约伯记', 18, 23, 8, '只是，我往前行，他不在那里，往后退，也不能见他。'),
('CUV', '约伯记', 18, 23, 9, '他在左边行事，我却不能看见，在右边隐藏，我也不能见他。'),
('CUV', '约伯记', 18, 23, 10, '然而他知道我所行的路；他试炼我之后，我必如精金。'),
('CUV', '约伯记', 18, 23, 11, '我脚追随他的步履；我谨守他的道，并不偏离。'),
('CUV', '约伯记', 18, 23, 12, '他嘴唇的命令，我未曾背弃；我看重他口中的言语，过于我需用的饮食。'),
('CUV', '约伯记', 18, 23, 13, '只是他心志已定，谁能使他转意呢？他心里所愿的，就行出来。'),
('CUV', '约伯记', 18, 23, 14, '他向我所定的，就必做成；这类的事他还有许多。'),
('CUV', '约伯记', 18, 23, 15, '所以我在他面前惊惶；我思念这事便惧怕他。'),
('CUV', '约伯记', 18, 23, 16, '神使我丧胆；全能者使我惊惶。'),
('CUV', '约伯记', 18, 23, 17, '我的恐惧不是因为黑暗，也不是因为幽暗蒙蔽我的脸。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 24, 1, '全能者既定期罚恶，为何不使认识他的人看见那日子呢？'),
('CUV', '约伯记', 18, 24, 2, '有人挪移地界，抢夺群畜而牧养。'),
('CUV', '约伯记', 18, 24, 3, '他们拉去孤儿的驴，强取寡妇的牛为当头。'),
('CUV', '约伯记', 18, 24, 4, '他们使穷人离开正道；世上的贫民尽都隐藏。'),
('CUV', '约伯记', 18, 24, 5, '这些贫穷人如同野驴出到旷野，殷勤寻找食物；他们靠著野地给儿女糊口，'),
('CUV', '约伯记', 18, 24, 6, '收割别人田间的禾稼，摘取恶人余剩的葡萄，'),
('CUV', '约伯记', 18, 24, 7, '终夜赤身无衣，天气寒冷毫无遮盖，'),
('CUV', '约伯记', 18, 24, 8, '在山上被大雨淋湿，因没有避身之处就挨近磐石。'),
('CUV', '约伯记', 18, 24, 9, '又有人从母怀中抢夺孤儿，强取穷人的衣服为当头，'),
('CUV', '约伯记', 18, 24, 10, '使人赤身无衣，到处流行，且因饥饿扛抬禾捆，'),
('CUV', '约伯记', 18, 24, 11, '在那些人的围墙内造油，醡酒，自己还口渴。'),
('CUV', '约伯记', 18, 24, 12, '在多民的城内有人唉哼，受伤的人哀号；神却不理会那恶人的愚妄。'),
('CUV', '约伯记', 18, 24, 13, '又有人背弃光明，不认识光明的道，不住在光明的路上。'),
('CUV', '约伯记', 18, 24, 14, '杀人的黎明起来，杀害困苦穷乏人，夜间又作盗贼。'),
('CUV', '约伯记', 18, 24, 15, '奸夫等候黄昏，说：必无眼能见我，就把脸蒙蔽。'),
('CUV', '约伯记', 18, 24, 16, '盗贼黑夜挖窟窿；白日躲藏，并不认识光明。'),
('CUV', '约伯记', 18, 24, 17, '他们看早晨如幽暗，因为他们晓得幽暗的惊骇。'),
('CUV', '约伯记', 18, 24, 18, '这些恶人犹如浮萍快快飘去。他们所得的分在世上被咒诅；他们不得再走葡萄园的路。'),
('CUV', '约伯记', 18, 24, 19, '干旱炎热消没雪水；阴间也如此消没犯罪之辈。'),
('CUV', '约伯记', 18, 24, 20, '怀他的母（原文是胎）要忘记他；虫子要吃他，觉得甘甜；他不再被人记念。不义的人必如树折断。'),
('CUV', '约伯记', 18, 24, 21, '他恶待（或译：他吞灭）不怀孕不生养的妇人，不善待寡妇。'),
('CUV', '约伯记', 18, 24, 22, '然而神用能力保全有势力的人；那性命难保的人仍然兴起。'),
('CUV', '约伯记', 18, 24, 23, '神使他们安稳，他们就有所倚靠；神的眼目也看顾他们的道路。'),
('CUV', '约伯记', 18, 24, 24, '他们被高举，不过片时就没有了；他们降为卑，被除灭，与众人一样，又如谷穗被割。'),
('CUV', '约伯记', 18, 24, 25, '若不是这样，谁能证实我是说谎的，将我的言语驳为虚空呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 25, 1, '书亚人比勒达回答说：'),
('CUV', '约伯记', 18, 25, 2, '神有治理之权，有威严可畏；他在高处施行和平。'),
('CUV', '约伯记', 18, 25, 3, '他的诸军岂能数算？他的光亮一发，谁不蒙照呢？'),
('CUV', '约伯记', 18, 25, 4, '这样在神面前，人怎能称义？妇人所生的怎能洁净？'),
('CUV', '约伯记', 18, 25, 5, '在神眼前，月亮也无光亮，星宿也不清洁。'),
('CUV', '约伯记', 18, 25, 6, '何况如虫的人，如蛆的世人呢！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 26, 1, '约伯回答说：'),
('CUV', '约伯记', 18, 26, 2, '无能的人蒙你何等的帮助！膀臂无力的人蒙你何等的拯救！'),
('CUV', '约伯记', 18, 26, 3, '无智慧的人蒙你何等的指教！你向他多显大知识！'),
('CUV', '约伯记', 18, 26, 4, '你向谁发出言语来？谁的灵从你而出？'),
('CUV', '约伯记', 18, 26, 5, '在大水和水族以下的阴魂战兢。'),
('CUV', '约伯记', 18, 26, 6, '在神面前，阴间显露；灭亡也不得遮掩。'),
('CUV', '约伯记', 18, 26, 7, '神将北极铺在空中，将大地悬在虚空；'),
('CUV', '约伯记', 18, 26, 8, '将水包在密云中，云却不破裂；'),
('CUV', '约伯记', 18, 26, 9, '遮蔽他的宝座，将云铺在其上；'),
('CUV', '约伯记', 18, 26, 10, '在水面的周围划出界限，直到光明黑暗的交界。'),
('CUV', '约伯记', 18, 26, 11, '天的柱子因他的斥责震动惊奇。'),
('CUV', '约伯记', 18, 26, 12, '他以能力搅动（或译：平静）大海；他藉知识打伤拉哈伯，'),
('CUV', '约伯记', 18, 26, 13, '藉他的灵使天有妆饰；他的手刺杀快蛇。'),
('CUV', '约伯记', 18, 26, 14, '看哪，这不过是神工作的些微；我们所听于他的是何等细微的声音！他大能的雷声谁能明透呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 27, 1, '约伯接著说：'),
('CUV', '约伯记', 18, 27, 2, '神夺去我的理，全能者使我心中愁苦。我指著永生的神起誓：'),
('CUV', '约伯记', 18, 27, 3, '我的生命尚在我里面；神所赐呼吸之气仍在我的鼻孔内。'),
('CUV', '约伯记', 18, 27, 4, '我的嘴决不说非义之言；我的舌也不说诡诈之语。'),
('CUV', '约伯记', 18, 27, 5, '我断不以你们为是；我至死必不以自己为不正！'),
('CUV', '约伯记', 18, 27, 6, '我持定我的义，必不放松；在世的日子，我心必不责备我。'),
('CUV', '约伯记', 18, 27, 7, '愿我的仇敌如恶人一样；愿那起来攻击我的，如不义之人一般。'),
('CUV', '约伯记', 18, 27, 8, '不敬虔的人虽然得利，神夺取其命的时候还有甚么指望呢？'),
('CUV', '约伯记', 18, 27, 9, '患难临到他，神岂能听他的呼求？'),
('CUV', '约伯记', 18, 27, 10, '他岂以全能者为乐，随时求告神呢？'),
('CUV', '约伯记', 18, 27, 11, '神的作为，我要指教你们；全能者所行的，我也不隐瞒。'),
('CUV', '约伯记', 18, 27, 12, '你们自己也都见过，为何全然变为虚妄呢？'),
('CUV', '约伯记', 18, 27, 13, '神为恶人所定的分，强暴人从全能者所得的报（原文是产业）乃是这样：'),
('CUV', '约伯记', 18, 27, 14, '倘或他的儿女增多，还是被刀所杀；他的子孙必不得饱食。'),
('CUV', '约伯记', 18, 27, 15, '他所遗留的人必死而埋葬；他的寡妇也不哀哭。'),
('CUV', '约伯记', 18, 27, 16, '他虽积蓄银子如尘沙，预备衣服如泥土；'),
('CUV', '约伯记', 18, 27, 17, '他只管预备，义人却要穿上；他的银子，无辜的人要分取。'),
('CUV', '约伯记', 18, 27, 18, '他建造房屋如虫做窝，又如守望者所搭的棚。'),
('CUV', '约伯记', 18, 27, 19, '他虽富足躺卧，却不得收殓，转眼之间就不在了。'),
('CUV', '约伯记', 18, 27, 20, '惊恐如波涛将他追上；暴风在夜间将他刮去。'),
('CUV', '约伯记', 18, 27, 21, '东风把他飘去，又刮他离开本处。'),
('CUV', '约伯记', 18, 27, 22, '神要向他射箭，并不留情；他恨不得逃脱神的手。'),
('CUV', '约伯记', 18, 27, 23, '人要向他拍掌，并要发叱声，使他离开本处。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 28, 1, '银子有矿；炼金有方。'),
('CUV', '约伯记', 18, 28, 2, '铁从地里挖出；铜从石中镕化。'),
('CUV', '约伯记', 18, 28, 3, '人为黑暗定界限，查究幽暗阴翳的石头，直到极处，'),
('CUV', '约伯记', 18, 28, 4, '在无人居住之处刨开矿穴，过路的人也想不到他们；又与人远离，悬在空中摇来摇去。'),
('CUV', '约伯记', 18, 28, 5, '至于地，能出粮食，地内好像被火翻起来。'),
('CUV', '约伯记', 18, 28, 6, '地中的石头有蓝宝石，并有金沙。'),
('CUV', '约伯记', 18, 28, 7, '矿中的路鸷鸟不得知道；鹰眼也未见过。'),
('CUV', '约伯记', 18, 28, 8, '狂傲的野兽未曾行过；猛烈的狮子也未曾经过。'),
('CUV', '约伯记', 18, 28, 9, '人伸手凿开坚石，倾倒山根，'),
('CUV', '约伯记', 18, 28, 10, '在磐石中凿出水道，亲眼看见各样宝物。'),
('CUV', '约伯记', 18, 28, 11, '他封闭水不得滴流，使隐藏的物显露出来。'),
('CUV', '约伯记', 18, 28, 12, '然而，智慧有何处可寻？聪明之处在哪里呢？'),
('CUV', '约伯记', 18, 28, 13, '智慧的价值无人能知，在活人之地也无处可寻。'),
('CUV', '约伯记', 18, 28, 14, '深渊说：不在我内；沧海说：不在我中。'),
('CUV', '约伯记', 18, 28, 15, '智慧非用黄金可得，也不能平白银为他的价值。'),
('CUV', '约伯记', 18, 28, 16, '俄斐金和贵重的红玛瑙，并蓝宝石，不足与较量；'),
('CUV', '约伯记', 18, 28, 17, '黄金和玻璃不足与比较；精金的器皿不足与兑换。'),
('CUV', '约伯记', 18, 28, 18, '珊瑚、水晶都不足论；智慧的价值胜过珍珠（或译：红宝石）。'),
('CUV', '约伯记', 18, 28, 19, '古实的红璧玺不足与比较；精金也不足与较量。'),
('CUV', '约伯记', 18, 28, 20, '智慧从何处来呢？聪明之处在哪里呢？'),
('CUV', '约伯记', 18, 28, 21, '是向一切有生命的眼目隐藏，向空中的飞鸟掩蔽。'),
('CUV', '约伯记', 18, 28, 22, '灭没和死亡说：我们风闻其名。'),
('CUV', '约伯记', 18, 28, 23, '神明白智慧的道路，晓得智慧的所在。'),
('CUV', '约伯记', 18, 28, 24, '因他鉴察直到地极，遍观普天之下，'),
('CUV', '约伯记', 18, 28, 25, '要为风定轻重，又度量诸水；'),
('CUV', '约伯记', 18, 28, 26, '他为雨露定命令，为雷电定道路。'),
('CUV', '约伯记', 18, 28, 27, '那时他看见智慧，而且述说；他坚定，并且查究。'),
('CUV', '约伯记', 18, 28, 28, '他对人说：敬畏主就是智慧；远离恶便是聪明。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 29, 1, '约伯又接著说：'),
('CUV', '约伯记', 18, 29, 2, '惟愿我的景况如从前的月份，如神保守我的日子。'),
('CUV', '约伯记', 18, 29, 3, '那时他的灯照在我头上；我藉他的光行过黑暗。'),
('CUV', '约伯记', 18, 29, 4, '我愿如壮年的时候：那时我在帐棚中，神待我有密友之情；'),
('CUV', '约伯记', 18, 29, 5, '全能者仍与我同在；我的儿女都环绕我。'),
('CUV', '约伯记', 18, 29, 6, '奶多可洗我的脚；磐石为我出油成河。'),
('CUV', '约伯记', 18, 29, 7, '我出到城门，在街上设立座位；'),
('CUV', '约伯记', 18, 29, 8, '少年人见我而回避，老年人也起身站立；'),
('CUV', '约伯记', 18, 29, 9, '王子都停止说话，用手摀口；'),
('CUV', '约伯记', 18, 29, 10, '首领静默无声，舌头贴住上膛。'),
('CUV', '约伯记', 18, 29, 11, '耳朵听我的，就称我有福；眼睛看我的，便称赞我；'),
('CUV', '约伯记', 18, 29, 12, '因我拯救哀求的困苦人和无人帮助的孤儿。'),
('CUV', '约伯记', 18, 29, 13, '将要灭亡的为我祝福；我也使寡妇心中欢乐。'),
('CUV', '约伯记', 18, 29, 14, '我以公义为衣服，以公平为外袍和冠冕。'),
('CUV', '约伯记', 18, 29, 15, '我为瞎子的眼，瘸子的脚。'),
('CUV', '约伯记', 18, 29, 16, '我为穷乏人的父；素不认识的人，我查明他的案件。'),
('CUV', '约伯记', 18, 29, 17, '我打破不义之人的牙床，从他牙齿中夺了所抢的。'),
('CUV', '约伯记', 18, 29, 18, '我便说：我必死在家中（原文是窝中），必增添我的日子，多如尘沙。'),
('CUV', '约伯记', 18, 29, 19, '我的根长到水边；露水终夜沾在我的枝上。'),
('CUV', '约伯记', 18, 29, 20, '我的荣耀在身上增新；我的弓在手中日强。'),
('CUV', '约伯记', 18, 29, 21, '人听见我而仰望，静默等候我的指教。'),
('CUV', '约伯记', 18, 29, 22, '我说话之后，他们就不再说；我的言语像雨露滴在他们身上。'),
('CUV', '约伯记', 18, 29, 23, '他们仰望我如仰望雨，又张开口如切慕春雨。'),
('CUV', '约伯记', 18, 29, 24, '他们不敢自信，我就向他们含笑；他们不使我脸上的光改变。'),
('CUV', '约伯记', 18, 29, 25, '我为他们选择道路，又坐首位；我如君王在军队中居住，又如吊丧的安慰伤心的人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 30, 1, '但如今，比我年少的人戏笑我；其人之父我曾藐视，不肯安在看守我羊群的狗中。'),
('CUV', '约伯记', 18, 30, 2, '他们壮年的气力既已衰败，其手之力与我何益呢？'),
('CUV', '约伯记', 18, 30, 3, '他们因穷乏饥饿，身体枯瘦，在荒废凄凉的幽暗中，龈干燥之地，'),
('CUV', '约伯记', 18, 30, 4, '在草丛之中采咸草，罗腾（小树名，松类）的根为他们的食物。'),
('CUV', '约伯记', 18, 30, 5, '他们从人中被赶出；人追喊他们如贼一般，'),
('CUV', '约伯记', 18, 30, 6, '以致他们住在荒谷之间，在地洞和岩穴中；'),
('CUV', '约伯记', 18, 30, 7, '在草丛中叫唤，在荆棘下聚集。'),
('CUV', '约伯记', 18, 30, 8, '这都是愚顽下贱人的儿女；他们被鞭打，赶出境外。'),
('CUV', '约伯记', 18, 30, 9, '现在这些人以我为歌曲，以我为笑谈。'),
('CUV', '约伯记', 18, 30, 10, '他们厌恶我，躲在旁边站著，不住地吐唾沫在我脸上。'),
('CUV', '约伯记', 18, 30, 11, '松开他们的绳索苦待我，在我面前脱去辔头。'),
('CUV', '约伯记', 18, 30, 12, '这等下流人在我右边起来，推开我的脚，筑成战路来攻击我。'),
('CUV', '约伯记', 18, 30, 13, '这些无人帮助的，毁坏我的道，加增我的灾。'),
('CUV', '约伯记', 18, 30, 14, '他们来如同闯进大破口，在毁坏之间滚在我身上。'),
('CUV', '约伯记', 18, 30, 15, '惊恐临到我，驱逐我的尊荣如风；我的福禄如云过去。'),
('CUV', '约伯记', 18, 30, 16, '现在我心极其悲伤；困苦的日子将我抓住。'),
('CUV', '约伯记', 18, 30, 17, '夜间，我里面的骨头刺我，疼痛不止，好像龈我。'),
('CUV', '约伯记', 18, 30, 18, '因神的大力，我的外衣污秽不堪，又如里衣的领子将我缠住。'),
('CUV', '约伯记', 18, 30, 19, '神把我扔在淤泥中，我就像尘土和炉灰一般。'),
('CUV', '约伯记', 18, 30, 20, '主啊，我呼求你，你不应允我；我站起来，你就定睛看我。'),
('CUV', '约伯记', 18, 30, 21, '你向我变心，待我残忍，又用大能追逼我，'),
('CUV', '约伯记', 18, 30, 22, '把我提在风中，使我驾风而行，又使我消灭在烈风中。'),
('CUV', '约伯记', 18, 30, 23, '我知道要使我临到死地，到那为众生所定的阴宅。'),
('CUV', '约伯记', 18, 30, 24, '然而，人仆倒岂不伸手？遇灾难岂不求救呢？'),
('CUV', '约伯记', 18, 30, 25, '人遭难，我岂不为他哭泣呢？人穷乏，我岂不为他忧愁呢？'),
('CUV', '约伯记', 18, 30, 26, '我仰望得好处，灾祸就到了；我等待光明，黑暗便来了。'),
('CUV', '约伯记', 18, 30, 27, '我心里烦扰不安，困苦的日子临到我身。'),
('CUV', '约伯记', 18, 30, 28, '我没有日光就哀哭行去（或译：我面发黑并非因日晒）；我在会中站著求救。'),
('CUV', '约伯记', 18, 30, 29, '我与野狗为弟兄，与鸵鸟为同伴。'),
('CUV', '约伯记', 18, 30, 30, '我的皮肤黑而脱落；我的骨头因热烧焦。'),
('CUV', '约伯记', 18, 30, 31, '所以，我的琴音变为悲音；我的箫声变为哭声。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 31, 1, '我与眼睛立约，怎能恋恋瞻望处女呢？'),
('CUV', '约伯记', 18, 31, 2, '从至上的神所得之分，从至高全能者所得之业是甚么呢？'),
('CUV', '约伯记', 18, 31, 3, '岂不是祸患临到不义的，灾害临到作孽的呢？'),
('CUV', '约伯记', 18, 31, 4, '神岂不是察看我的道路，数点我的脚步呢？'),
('CUV', '约伯记', 18, 31, 5, '我若与虚谎同行，脚若追随诡诈；'),
('CUV', '约伯记', 18, 31, 6, '（我若被公道的天平称度，使神可以知道我的纯正；）'),
('CUV', '约伯记', 18, 31, 7, '我的脚步若偏离正路，我的心若随著我的眼目，若有玷污粘在我手上；'),
('CUV', '约伯记', 18, 31, 8, '就愿我所种的有别人吃，我田所产的被拔出来。'),
('CUV', '约伯记', 18, 31, 9, '我若受迷惑，向妇人起淫念，在邻舍的门外蹲伏，'),
('CUV', '约伯记', 18, 31, 10, '就愿我的妻子给别人推磨，别人也与他同室。'),
('CUV', '约伯记', 18, 31, 11, '因为这是大罪，是审判官当罚的罪孽。'),
('CUV', '约伯记', 18, 31, 12, '这本是火焚烧，直到毁灭，必拔除我所有的家产。'),
('CUV', '约伯记', 18, 31, 13, '我的仆婢与我争辩的时候，我若藐视不听他们的情节；'),
('CUV', '约伯记', 18, 31, 14, '神兴起，我怎样行呢？他察问，我怎样回答呢？'),
('CUV', '约伯记', 18, 31, 15, '造我在腹中的，不也是造他么？将他与我抟在腹中的岂不是一位么？'),
('CUV', '约伯记', 18, 31, 16, '我若不容贫寒人得其所愿，或叫寡妇眼中失望，'),
('CUV', '约伯记', 18, 31, 17, '或独自吃我一点食物，孤儿没有与我同吃；'),
('CUV', '约伯记', 18, 31, 18, '（从幼年时孤儿与我同长，好像父子一样；我从出母腹就扶助寡妇。）'),
('CUV', '约伯记', 18, 31, 19, '我若见人因无衣死亡，或见穷乏人身无遮盖；'),
('CUV', '约伯记', 18, 31, 20, '我若不使他因我羊的毛得暖，为我祝福；'),
('CUV', '约伯记', 18, 31, 21, '我若在城门口见有帮助我的，举手攻击孤儿；'),
('CUV', '约伯记', 18, 31, 22, '情愿我的肩头从缺盆骨脱落，我的膀臂从羊矢骨折断。'),
('CUV', '约伯记', 18, 31, 23, '因神降的灾祸使我恐惧；因他的威严，我不能妄为。'),
('CUV', '约伯记', 18, 31, 24, '我若以黄金为指望，对精金说：你是我的倚靠；'),
('CUV', '约伯记', 18, 31, 25, '我若因财物丰裕，因我手多得资财而欢喜；'),
('CUV', '约伯记', 18, 31, 26, '我若见太阳发光，明月行在空中，'),
('CUV', '约伯记', 18, 31, 27, '心就暗暗被引诱，口便亲手；'),
('CUV', '约伯记', 18, 31, 28, '这也是审判官当罚的罪孽，又是我背弃在上的神。'),
('CUV', '约伯记', 18, 31, 29, '我若见恨我的遭报就欢喜，见他遭灾便高兴；'),
('CUV', '约伯记', 18, 31, 30, '（我没有容口犯罪，咒诅他的生命；）'),
('CUV', '约伯记', 18, 31, 31, '若我帐棚的人未尝说，谁不以主人的食物吃饱呢？'),
('CUV', '约伯记', 18, 31, 32, '（从来我没有容客旅在街上住宿，却开门迎接行路的人；）'),
('CUV', '约伯记', 18, 31, 33, '我若像亚当（或译：别人）遮掩我的过犯，将罪孽藏在怀中；'),
('CUV', '约伯记', 18, 31, 34, '因惧怕大众，又因宗族藐视我使我惊恐，以致闭口无言，杜门不出；'),
('CUV', '约伯记', 18, 31, 35, '惟愿有一位肯听我！（看哪，在这里有我所划的押，愿全能者回答我！）'),
('CUV', '约伯记', 18, 31, 36, '愿那敌我者所写的状词在我这里！我必带在肩上，又绑在头上为冠冕。'),
('CUV', '约伯记', 18, 31, 37, '我必向他述说我脚步的数目，必如君王进到他面前。'),
('CUV', '约伯记', 18, 31, 38, '我若夺取田地，这地向我喊冤，犁沟一同哭泣；'),
('CUV', '约伯记', 18, 31, 39, '我若吃地的出产不给价值，或叫原主丧命；'),
('CUV', '约伯记', 18, 31, 40, '愿这地长蒺藜代替麦子，长恶草代替大麦。约伯的话说完了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 32, 1, '于是这三个人，因约伯自以为义就不再回答他。'),
('CUV', '约伯记', 18, 32, 2, '那时有布西人兰族巴拉迦的儿子以利户向约伯发怒；因约伯自以为义，不以神为义。'),
('CUV', '约伯记', 18, 32, 3, '他又向约伯的三个朋友发怒；因为他们想不出回答的话来，仍以约伯为有罪。'),
('CUV', '约伯记', 18, 32, 4, '以利户要与约伯说话，就等候他们，因为他们比自己年老。'),
('CUV', '约伯记', 18, 32, 5, '以利户见这三个人口中无话回答，就怒气发作。'),
('CUV', '约伯记', 18, 32, 6, '布西人巴拉迦的儿子以利户回答说：我年轻，你们老迈；因此我退让，不敢向你们陈说我的意见。'),
('CUV', '约伯记', 18, 32, 7, '我说，年老的当先说话；寿高的当以智慧.教训人。'),
('CUV', '约伯记', 18, 32, 8, '但在人里面有灵；全能者的气使人有聪明。'),
('CUV', '约伯记', 18, 32, 9, '尊贵的不都有智慧；寿高的不都能明白公平。'),
('CUV', '约伯记', 18, 32, 10, '因此我说：你们要听我言；我也要陈说我的意见。'),
('CUV', '约伯记', 18, 32, 11, '你们查究所要说的话；那时我等候你们的话，侧耳听你们的辩论，'),
('CUV', '约伯记', 18, 32, 12, '留心听你们；谁知你们中间无一人折服约伯，驳倒他的话。'),
('CUV', '约伯记', 18, 32, 13, '你们切不可说：我们寻得智慧；神能胜他，人却不能。'),
('CUV', '约伯记', 18, 32, 14, '约伯没有向我争辩；我也不用你们的话回答他。'),
('CUV', '约伯记', 18, 32, 15, '他们惊奇不再回答，一言不发。'),
('CUV', '约伯记', 18, 32, 16, '我岂因他们不说话，站住不再回答，仍旧等候呢？'),
('CUV', '约伯记', 18, 32, 17, '我也要回答我的一分话，陈说我的意见。'),
('CUV', '约伯记', 18, 32, 18, '因为我的言语满怀；我里面的灵激动我。'),
('CUV', '约伯记', 18, 32, 19, '我的胸怀如盛酒之囊没有出气之缝，又如新皮袋快要破裂。'),
('CUV', '约伯记', 18, 32, 20, '我要说话，使我舒畅；我要开口回答。'),
('CUV', '约伯记', 18, 32, 21, '我必不看人的情面，也不奉承人。'),
('CUV', '约伯记', 18, 32, 22, '我不晓得奉承；若奉承，造我的主必快快除灭我。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 33, 1, '约伯啊，请听我的话，留心听我一切的言语。'),
('CUV', '约伯记', 18, 33, 2, '我现在开口，用舌发言。'),
('CUV', '约伯记', 18, 33, 3, '我的言语要发明心中所存的正直；我所知道的，我嘴唇要诚实地说出。'),
('CUV', '约伯记', 18, 33, 4, '神的灵造我；全能者的气使我得生。'),
('CUV', '约伯记', 18, 33, 5, '你若回答我，就站起来，在我面前陈明。'),
('CUV', '约伯记', 18, 33, 6, '我在神面前与你一样，也是用土造成。'),
('CUV', '约伯记', 18, 33, 7, '我不用威严惊吓你，也不用势力重压你。'),
('CUV', '约伯记', 18, 33, 8, '你所说的，我听见了，也听见你的言语，说：'),
('CUV', '约伯记', 18, 33, 9, '我是清洁无过的，我是无辜的；在我里面也没有罪孽。'),
('CUV', '约伯记', 18, 33, 10, '神找机会攻击我，以我为仇敌，'),
('CUV', '约伯记', 18, 33, 11, '把我的脚上了木狗，窥察我一切的道路。'),
('CUV', '约伯记', 18, 33, 12, '我要回答你说：你这话无理，因神比世人更大。'),
('CUV', '约伯记', 18, 33, 13, '你为何与他争论呢？因他的事都不对人解说？'),
('CUV', '约伯记', 18, 33, 14, '神说一次、两次，世人却不理会。'),
('CUV', '约伯记', 18, 33, 15, '人躺在床上沉睡的时候，神就用梦和夜间的异象，'),
('CUV', '约伯记', 18, 33, 16, '开通他们的耳朵，将当受的教训印在他们心上，'),
('CUV', '约伯记', 18, 33, 17, '好叫人不从自己的谋算，不行骄傲的事（原文是将骄傲向人隐藏），'),
('CUV', '约伯记', 18, 33, 18, '拦阻人不陷于坑里，不死在刀下。'),
('CUV', '约伯记', 18, 33, 19, '人在床上被惩治，骨头中不住地疼痛，'),
('CUV', '约伯记', 18, 33, 20, '以致他的口厌弃食物，心厌恶美味。'),
('CUV', '约伯记', 18, 33, 21, '他的肉消瘦，不得再见；先前不见的骨头都凸出来。'),
('CUV', '约伯记', 18, 33, 22, '他的灵魂临近深坑；他的生命近于灭命的。'),
('CUV', '约伯记', 18, 33, 23, '一千天使中，若有一个作传话的与神同在，指示人所当行的事，'),
('CUV', '约伯记', 18, 33, 24, '神就给他开恩，说：救赎他免得下坑；我已经得了赎价。'),
('CUV', '约伯记', 18, 33, 25, '他的肉要比孩童的肉更嫩；他就返老还童。'),
('CUV', '约伯记', 18, 33, 26, '他祷告神，神就喜悦他，使他欢呼朝见神的面；神又看他为义。'),
('CUV', '约伯记', 18, 33, 27, '他在人前歌唱说：我犯了罪，颠倒是非，这竟与我无益。'),
('CUV', '约伯记', 18, 33, 28, '神救赎我的灵魂免入深坑；我的生命也必见光。'),
('CUV', '约伯记', 18, 33, 29, '神两次、三次向人行这一切的事，'),
('CUV', '约伯记', 18, 33, 30, '为要从深坑救回人的灵魂，使他被光照耀，与活人一样。'),
('CUV', '约伯记', 18, 33, 31, '约伯啊，你当侧耳听我的话，不要作声，等我讲说。'),
('CUV', '约伯记', 18, 33, 32, '你若有话说，就可以回答我；你只管说，因我愿以你为是。'),
('CUV', '约伯记', 18, 33, 33, '若不然，你就听我说；你不要作声，我便将智慧教训你。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 34, 1, '以利户又说：'),
('CUV', '约伯记', 18, 34, 2, '你们智慧人要听我的话；有知识的人要留心听我说。'),
('CUV', '约伯记', 18, 34, 3, '因为耳朵试验话语，好像上膛尝食物。'),
('CUV', '约伯记', 18, 34, 4, '我们当选择何为是，彼此知道何为善。'),
('CUV', '约伯记', 18, 34, 5, '约伯曾说：我是公义，神夺去我的理；'),
('CUV', '约伯记', 18, 34, 6, '我虽有理，还算为说谎言的；我虽无过，受的伤还不能医治。'),
('CUV', '约伯记', 18, 34, 7, '谁像约伯，喝讥诮如同喝水呢？'),
('CUV', '约伯记', 18, 34, 8, '他与作孽的结伴，和恶人同行。'),
('CUV', '约伯记', 18, 34, 9, '他说：人以神为乐，总是无益。'),
('CUV', '约伯记', 18, 34, 10, '所以，你们明理的人要听我的话。神断不致行恶；全能者断不致作孽。'),
('CUV', '约伯记', 18, 34, 11, '他必按人所做的报应人，使各人照所行的得报。'),
('CUV', '约伯记', 18, 34, 12, '神必不作恶；全能者也不偏离公平。'),
('CUV', '约伯记', 18, 34, 13, '谁派他治理地，安定全世界呢？'),
('CUV', '约伯记', 18, 34, 14, '他若专心为己，将灵和气收归自己，'),
('CUV', '约伯记', 18, 34, 15, '凡有血气的就必一同死亡；世人必仍归尘土。'),
('CUV', '约伯记', 18, 34, 16, '你若明理，就当听我的话，留心听我言语的声音。'),
('CUV', '约伯记', 18, 34, 17, '难道恨恶公平的可以掌权么？那有公义的、有大能的，岂可定他有罪么？'),
('CUV', '约伯记', 18, 34, 18, '他对君王说：你是鄙陋的；对贵臣说：你是邪恶的。'),
('CUV', '约伯记', 18, 34, 19, '他待王子不徇情面，也不看重富足的过于贫穷的，因为都是他手所造。'),
('CUV', '约伯记', 18, 34, 20, '在转眼之间，半夜之中，他们就死亡。百姓被震动而去世；有权力的被夺去非借人手。'),
('CUV', '约伯记', 18, 34, 21, '神注目观看人的道路，看明人的脚步。'),
('CUV', '约伯记', 18, 34, 22, '没有黑暗、阴翳能给作孽的藏身。'),
('CUV', '约伯记', 18, 34, 23, '神审判人，不必使人到他面前再三鉴察。'),
('CUV', '约伯记', 18, 34, 24, '他用难测之法打破有能力的人，设立别人代替他们。'),
('CUV', '约伯记', 18, 34, 25, '他原知道他们的行为，使他们在夜间倾倒灭亡。'),
('CUV', '约伯记', 18, 34, 26, '他在众人眼前击打他们，如同击打恶人一样。'),
('CUV', '约伯记', 18, 34, 27, '因为他们偏行不跟从他，也不留心他的道，'),
('CUV', '约伯记', 18, 34, 28, '甚至使贫穷人的哀声达到他那里；他也听了困苦人的哀声。'),
('CUV', '约伯记', 18, 34, 29, '他使人安静，谁能扰乱（或译：定罪）呢？他掩面，谁能见他呢？无论待一国或一人都是如此─'),
('CUV', '约伯记', 18, 34, 30, '使不虔敬的人不得作王，免得有人牢笼百姓。'),
('CUV', '约伯记', 18, 34, 31, '有谁对神说：我受了责罚，不再犯罪；'),
('CUV', '约伯记', 18, 34, 32, '我所看不明的，求你指教我；我若作了孽，必不再作？'),
('CUV', '约伯记', 18, 34, 33, '他施行报应，岂要随你的心愿、叫你推辞不受么？选定的是你，不是我。你所知道的只管说罢！'),
('CUV', '约伯记', 18, 34, 34, '明理的人和听我话的智慧人必对我说：'),
('CUV', '约伯记', 18, 34, 35, '约伯说话没有知识，言语中毫无智慧。'),
('CUV', '约伯记', 18, 34, 36, '愿约伯被试验到底，因他回答像恶人一样。'),
('CUV', '约伯记', 18, 34, 37, '他在罪上又加悖逆；在我们中间拍手，用许多言语轻慢神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 35, 1, '以利户又说：'),
('CUV', '约伯记', 18, 35, 2, '你以为有理，或以为你的公义胜于神的公义，'),
('CUV', '约伯记', 18, 35, 3, '才说这与我有甚么益处？我不犯罪比犯罪有甚么好处呢？'),
('CUV', '约伯记', 18, 35, 4, '我要回答你和在你这里的朋友。'),
('CUV', '约伯记', 18, 35, 5, '你要向天观看，瞻望那高于你的穹苍。'),
('CUV', '约伯记', 18, 35, 6, '你若犯罪，能使神受何害呢？你的过犯加增，能使神受何损呢？'),
('CUV', '约伯记', 18, 35, 7, '你若是公义，还能加增他甚么呢？他从你手里还接受甚么呢？'),
('CUV', '约伯记', 18, 35, 8, '你的过恶或能害你这类的人；你的公义或能叫世人得益处。'),
('CUV', '约伯记', 18, 35, 9, '人因多受欺压就哀求，因受能者的辖制（原文是膀臂）便求救，'),
('CUV', '约伯记', 18, 35, 10, '却无人说：造我的神在哪里？他使人夜间歌唱，'),
('CUV', '约伯记', 18, 35, 11, '教训我们胜于地上的走兽，使我们有聪明胜于空中的飞鸟。'),
('CUV', '约伯记', 18, 35, 12, '他们在那里，因恶人的骄傲呼求，却无人答应。'),
('CUV', '约伯记', 18, 35, 13, '虚妄的呼求，神必不垂听；全能者也必不眷顾。'),
('CUV', '约伯记', 18, 35, 14, '何况你说，你不得见他；你的案件在他面前，你等候他罢。'),
('CUV', '约伯记', 18, 35, 15, '但如今因他未曾发怒降罚，也不甚理会狂傲，'),
('CUV', '约伯记', 18, 35, 16, '所以约伯开口说虚妄的话，多发无知识的言语。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 36, 1, '以利户又接著说：'),
('CUV', '约伯记', 18, 36, 2, '你再容我片时，我就指示你，因我还有话为神说。'),
('CUV', '约伯记', 18, 36, 3, '我要将所知道的从远处引来，将公义归给造我的主。'),
('CUV', '约伯记', 18, 36, 4, '我的言语真不虚谎；有知识全备的与你同在。'),
('CUV', '约伯记', 18, 36, 5, '神有大能，并不藐视人；他的智慧甚广。'),
('CUV', '约伯记', 18, 36, 6, '他不保护恶人的性命，却为困苦人伸冤。'),
('CUV', '约伯记', 18, 36, 7, '他时常看顾义人，使他们和君王同坐宝座，永远要被高举。'),
('CUV', '约伯记', 18, 36, 8, '他们若被锁链捆住，被苦难的绳索缠住，'),
('CUV', '约伯记', 18, 36, 9, '他就把他们的作为和过犯指示他们，叫他们知道有骄傲的行动。'),
('CUV', '约伯记', 18, 36, 10, '他也开通他们的耳朵得受教训，吩咐他们离开罪孽转回。'),
('CUV', '约伯记', 18, 36, 11, '他们若听从事奉他，就必度日亨通，历年福乐；'),
('CUV', '约伯记', 18, 36, 12, '若不听从，就要被刀杀灭，无知无识而死。'),
('CUV', '约伯记', 18, 36, 13, '那心中不敬虔的人积蓄怒气；神捆绑他们，他们竟不求救；'),
('CUV', '约伯记', 18, 36, 14, '必在青年时死亡，与污秽人一样丧命。'),
('CUV', '约伯记', 18, 36, 15, '神藉著困苦救拔困苦人，趁他们受欺压开通他们的耳朵。'),
('CUV', '约伯记', 18, 36, 16, '神也必引你出离患难，进入宽阔不狭窄之地；摆在你席上的必满有肥甘。'),
('CUV', '约伯记', 18, 36, 17, '但你满口有恶人批评的言语；判断和刑罚抓住你。'),
('CUV', '约伯记', 18, 36, 18, '不可容忿怒触动你，使你不服责罚；也不可因赎价大就偏行。'),
('CUV', '约伯记', 18, 36, 19, '你的呼求（或译：资财），或是你一切的势力，果有灵验，叫你不受患难么？'),
('CUV', '约伯记', 18, 36, 20, '不要切慕黑夜，就是众民在本处被除灭的时候。'),
('CUV', '约伯记', 18, 36, 21, '你要谨慎，不可重看罪孽，因你选择罪孽过于选择苦难。'),
('CUV', '约伯记', 18, 36, 22, '神行事有高大的能力；教训人的有谁像他呢？'),
('CUV', '约伯记', 18, 36, 23, '谁派定他的道路？谁能说：你所行的不义？'),
('CUV', '约伯记', 18, 36, 24, '你不可忘记称赞他所行的为大，就是人所歌颂的。'),
('CUV', '约伯记', 18, 36, 25, '他所行的，万人都看见；世人也从远处观看。'),
('CUV', '约伯记', 18, 36, 26, '神为大，我们不能全知；他的年数不能测度。'),
('CUV', '约伯记', 18, 36, 27, '他吸取水点，这水点从云雾中就变成雨；'),
('CUV', '约伯记', 18, 36, 28, '云彩将雨落下，沛然降与世人。'),
('CUV', '约伯记', 18, 36, 29, '谁能明白云彩如何铺张，和神行宫的雷声呢？'),
('CUV', '约伯记', 18, 36, 30, '他将亮光普照在自己的四围；他又遮覆海底。'),
('CUV', '约伯记', 18, 36, 31, '他用这些审判众民，且赐丰富的粮食。'),
('CUV', '约伯记', 18, 36, 32, '他以电光遮手，命闪电击中敌人（或译：中了靶子）。'),
('CUV', '约伯记', 18, 36, 33, '所发的雷声显明他的作为，又向牲畜指明要起暴风。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 37, 1, '因此我心战兢，从原处移动。'),
('CUV', '约伯记', 18, 37, 2, '听啊，神轰轰的声音是他口中所发的响声。'),
('CUV', '约伯记', 18, 37, 3, '他发响声震遍天下，发电光闪到地极。'),
('CUV', '约伯记', 18, 37, 4, '随后人听见有雷声轰轰，大发威严，雷电接连不断。'),
('CUV', '约伯记', 18, 37, 5, '神发出奇妙的雷声；他行大事，我们不能测透。'),
('CUV', '约伯记', 18, 37, 6, '他对雪说：要降在地上；对大雨和暴雨也是这样说。'),
('CUV', '约伯记', 18, 37, 7, '他封住各人的手，叫所造的万人都晓得他的作为。'),
('CUV', '约伯记', 18, 37, 8, '百兽进入穴中，卧在洞内。'),
('CUV', '约伯记', 18, 37, 9, '暴风出于南宫；寒冷出于北方。'),
('CUV', '约伯记', 18, 37, 10, '神嘘气成冰；宽阔之水也都凝结。'),
('CUV', '约伯记', 18, 37, 11, '他使密云盛满水气，布散电光之云；'),
('CUV', '约伯记', 18, 37, 12, '这云是藉他的指引游行旋转，得以在全地面上行他一切所吩咐的，'),
('CUV', '约伯记', 18, 37, 13, '或为责罚，或为润地，或为施行慈爱。'),
('CUV', '约伯记', 18, 37, 14, '约伯啊，你要留心听，要站立思想神奇妙的作为。'),
('CUV', '约伯记', 18, 37, 15, '神如何吩咐这些，如何使云中的电光照耀，你知道么？'),
('CUV', '约伯记', 18, 37, 16, '云彩如何浮于空中，那知识全备者奇妙的作为，你知道么？'),
('CUV', '约伯记', 18, 37, 17, '南风使地寂静，你的衣服就如火热，你知道么？'),
('CUV', '约伯记', 18, 37, 18, '你岂能与神同铺穹苍么？这穹苍坚硬，如同铸成的镜子。'),
('CUV', '约伯记', 18, 37, 19, '我们愚昧不能陈说；请你指教我们该对他说甚么话。'),
('CUV', '约伯记', 18, 37, 20, '人岂可说：我愿与他说话？岂有人自愿灭亡么？'),
('CUV', '约伯记', 18, 37, 21, '现在有云遮蔽，人不得见穹苍的光亮；但风吹过，天又发晴。'),
('CUV', '约伯记', 18, 37, 22, '金光出于北方，在神那里有可怕的威严。'),
('CUV', '约伯记', 18, 37, 23, '论到全能者，我们不能测度；他大有能力，有公平和大义，必不苦待人。'),
('CUV', '约伯记', 18, 37, 24, '所以，人敬畏他；凡自以为心中有智慧的人，他都不顾念。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 38, 1, '那时，耶和华从旋风中回答约伯说：'),
('CUV', '约伯记', 18, 38, 2, '谁用无知的言语使我的旨意暗昧不明，'),
('CUV', '约伯记', 18, 38, 3, '你要如勇士束腰；我问你，你可以指示我。'),
('CUV', '约伯记', 18, 38, 4, '我立大地根基的时候，你在哪里呢？你若有聪明，只管说罢！'),
('CUV', '约伯记', 18, 38, 5, '你若晓得就说，是谁定地的尺度？是谁把准绳拉在其上？'),
('CUV', '约伯记', 18, 38, 6, '地的根基安置在何处？地的角石是谁安放的？'),
('CUV', '约伯记', 18, 38, 7, '那时，晨星一同歌唱；神的众子也都欢呼。'),
('CUV', '约伯记', 18, 38, 8, '海水冲出，如出胎胞，那时谁将他关闭呢？'),
('CUV', '约伯记', 18, 38, 9, '是我用云彩当海的衣服，用幽暗当包裹他的布，'),
('CUV', '约伯记', 18, 38, 10, '为他定界限，又安门和闩，'),
('CUV', '约伯记', 18, 38, 11, '说：你只可到这里，不可越过；你狂傲的浪要到此止住。'),
('CUV', '约伯记', 18, 38, 12, '你自生以来，曾命定晨光，使清晨的日光知道本位，'),
('CUV', '约伯记', 18, 38, 13, '叫这光普照地的四极，将恶人从其中驱逐出来么？'),
('CUV', '约伯记', 18, 38, 14, '因这光，地面改变如泥上印印，万物出现如衣服一样。'),
('CUV', '约伯记', 18, 38, 15, '亮光不照恶人；强横的膀臂也必折断。'),
('CUV', '约伯记', 18, 38, 16, '你曾进到海源，或在深渊的隐密处行走么？'),
('CUV', '约伯记', 18, 38, 17, '死亡的门曾向你显露么？死荫的门你曾见过么？'),
('CUV', '约伯记', 18, 38, 18, '地的广大你能明透么？你若全知道，只管说罢！'),
('CUV', '约伯记', 18, 38, 19, '光明的居所从何而至？黑暗的本位在于何处？'),
('CUV', '约伯记', 18, 38, 20, '你能带到本境，能看明其室之路么？'),
('CUV', '约伯记', 18, 38, 21, '你总知道，因为你早已生在世上，你日子的数目也多。'),
('CUV', '约伯记', 18, 38, 22, '你曾进入雪库，或见过雹仓么？'),
('CUV', '约伯记', 18, 38, 23, '这雪雹乃是我为降灾，并打仗和争战的日子所预备的。'),
('CUV', '约伯记', 18, 38, 24, '光亮从何路分开？东风从何路分散遍地？'),
('CUV', '约伯记', 18, 38, 25, '谁为雨水分道？谁为雷电开路？'),
('CUV', '约伯记', 18, 38, 26, '使雨降在无人之地、无人居住的旷野？'),
('CUV', '约伯记', 18, 38, 27, '使荒废凄凉之地得以丰足，青草得以发生？'),
('CUV', '约伯记', 18, 38, 28, '雨有父么？露水珠是谁生的呢？'),
('CUV', '约伯记', 18, 38, 29, '冰出于谁的胎？天上的霜是谁生的呢？'),
('CUV', '约伯记', 18, 38, 30, '诸水坚硬（或译：隐藏）如石头；深渊之面凝结成冰。'),
('CUV', '约伯记', 18, 38, 31, '你能系住昴星的结么？能解开参星的带么？'),
('CUV', '约伯记', 18, 38, 32, '你能按时领出十二宫么？能引导北斗和随他的众星（星：原文是子）么？'),
('CUV', '约伯记', 18, 38, 33, '你知道天的定例么？能使地归在天的权下么？'),
('CUV', '约伯记', 18, 38, 34, '你能向云彩扬起声来，使倾盆的雨遮盖你么？'),
('CUV', '约伯记', 18, 38, 35, '你能发出闪电，叫他行去，使他对你说：我们在这里？'),
('CUV', '约伯记', 18, 38, 36, '谁将智慧放在怀中？谁将聪明赐于心内？'),
('CUV', '约伯记', 18, 38, 37, '谁能用智慧数算云彩呢？尘土聚集成团，土块紧紧结连；那时，谁能倾倒天上的瓶呢？'),
('CUV', '约伯记', 18, 38, 38, 'a'),
('CUV', '约伯记', 18, 38, 39, '母狮子在洞中蹲伏，少壮狮子在隐密处埋伏；你能为他们抓取食物，使他们饱足么？'),
('CUV', '约伯记', 18, 38, 40, 'a'),
('CUV', '约伯记', 18, 38, 41, '乌鸦之雏因无食物飞来飞去，哀告神；那时，谁为他预备食物呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 39, 1, '山岩间的野山羊几时生产，你知道么？母鹿下犊之期，你能察定么？'),
('CUV', '约伯记', 18, 39, 2, '他们怀胎的月数，你能数算么？他们几时生产，你能晓得么？'),
('CUV', '约伯记', 18, 39, 3, '他们屈身，将子生下，就除掉疼痛。'),
('CUV', '约伯记', 18, 39, 4, '这子渐渐肥壮，在荒野长大，去而不回。'),
('CUV', '约伯记', 18, 39, 5, '谁放野驴出去自由？谁解开快驴的绳索？'),
('CUV', '约伯记', 18, 39, 6, '我使旷野作他的住处，使咸地当他的居所。'),
('CUV', '约伯记', 18, 39, 7, '他嗤笑城内的喧嚷，不听赶牲口的喝声。'),
('CUV', '约伯记', 18, 39, 8, '遍山是他的草场；他寻找各样青绿之物。'),
('CUV', '约伯记', 18, 39, 9, '野牛岂肯服事你？岂肯住在你的槽旁？'),
('CUV', '约伯记', 18, 39, 10, '你岂能用套绳将野牛笼在犁沟之间？他岂肯随你耙山谷之地？'),
('CUV', '约伯记', 18, 39, 11, '岂可因他的力大就倚靠他？岂可把你的工交给他做么？'),
('CUV', '约伯记', 18, 39, 12, '岂可信靠他把你的粮食运到家，又收聚你禾场上的谷么？'),
('CUV', '约伯记', 18, 39, 13, '鸵鸟的翅膀欢然搧展，岂是显慈爱的翎毛和羽毛么？'),
('CUV', '约伯记', 18, 39, 14, '因他把蛋留在地上，在尘土中使得温暖；'),
('CUV', '约伯记', 18, 39, 15, '却想不到被脚踹碎，或被野兽践踏。'),
('CUV', '约伯记', 18, 39, 16, '他忍心待雏，似乎不是自己的；虽然徒受劳苦，也不为雏惧怕；'),
('CUV', '约伯记', 18, 39, 17, '因为神使他没有智慧，也未将悟性赐给他。'),
('CUV', '约伯记', 18, 39, 18, '他几时挺身展开翅膀，就嗤笑马和骑马的人。'),
('CUV', '约伯记', 18, 39, 19, '马的大力是你所赐的么？他颈项上挓挲的鬃是你给他披上的么？'),
('CUV', '约伯记', 18, 39, 20, '是你叫他跳跃像蝗虫么？他喷气之威使人惊惶。'),
('CUV', '约伯记', 18, 39, 21, '他在谷中刨地，自喜其力；他出去迎接佩带兵器的人。'),
('CUV', '约伯记', 18, 39, 22, '他嗤笑可怕的事并不惊惶，也不因刀剑退回。'),
('CUV', '约伯记', 18, 39, 23, '箭袋和发亮的枪，并短枪在他身上铮铮有声。'),
('CUV', '约伯记', 18, 39, 24, '他发猛烈的怒气将地吞下；一听角声就不耐站立。'),
('CUV', '约伯记', 18, 39, 25, '角每发声，他说呵哈；他从远处闻著战气，又听见军长大发雷声和兵丁呐喊。'),
('CUV', '约伯记', 18, 39, 26, '鹰雀飞翔，展开翅膀一直向南，岂是藉你的智慧么？'),
('CUV', '约伯记', 18, 39, 27, '大鹰上腾在高处搭窝，岂是听你的吩咐么？'),
('CUV', '约伯记', 18, 39, 28, '他住在山岩，以山峰和坚固之所为家，'),
('CUV', '约伯记', 18, 39, 29, '从那里窥看食物，眼睛远远观望。'),
('CUV', '约伯记', 18, 39, 30, '他的雏也咂血；被杀的人在哪里，他也在那里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 40, 1, '耶和华又对约伯说：'),
('CUV', '约伯记', 18, 40, 2, '强辩的岂可与全能者争论么？与神辩驳的可以回答这些罢！'),
('CUV', '约伯记', 18, 40, 3, '于是，约伯回答耶和华说：'),
('CUV', '约伯记', 18, 40, 4, '我是卑贱的！我用甚么回答你呢？只好用手摀口。'),
('CUV', '约伯记', 18, 40, 5, '我说了一次，再不回答；说了两次，就不再说。'),
('CUV', '约伯记', 18, 40, 6, '于是，耶和华从旋风中回答约伯说：'),
('CUV', '约伯记', 18, 40, 7, '你要如勇士束腰；我问你，你可以指示我。'),
('CUV', '约伯记', 18, 40, 8, '你岂可废弃我所拟定的？岂可定我有罪，好显自己为义么？'),
('CUV', '约伯记', 18, 40, 9, '你有神那样的膀臂么？你能像他发雷声么？'),
('CUV', '约伯记', 18, 40, 10, '你要以荣耀庄严为妆饰，以尊荣威严为衣服；'),
('CUV', '约伯记', 18, 40, 11, '要发出你满溢的怒气，见一切骄傲的人，使他降卑；'),
('CUV', '约伯记', 18, 40, 12, '见一切骄傲的人，将他制伏，把恶人践踏在本处；'),
('CUV', '约伯记', 18, 40, 13, '将他们一同隐藏在尘土中，把他们的脸蒙蔽在隐密处；'),
('CUV', '约伯记', 18, 40, 14, '我就认你右手能以救自己。'),
('CUV', '约伯记', 18, 40, 15, '你且观看河马；我造你也造他。他吃草与牛一样；'),
('CUV', '约伯记', 18, 40, 16, '他的气力在腰间，能力在肚腹的筋上。'),
('CUV', '约伯记', 18, 40, 17, '他摇动尾巴如香柏树；他大腿的筋互相联络。'),
('CUV', '约伯记', 18, 40, 18, '他的骨头好像铜管；他的肢体仿佛铁棍。'),
('CUV', '约伯记', 18, 40, 19, '他在神所造的物中为首；创造他的给他刀剑。'),
('CUV', '约伯记', 18, 40, 20, '诸山给他出食物，也是百兽游玩之处。'),
('CUV', '约伯记', 18, 40, 21, '他伏在莲叶之下，卧在芦苇隐密处和水洼子里。'),
('CUV', '约伯记', 18, 40, 22, '莲叶的阴凉遮蔽他；溪旁的柳树环绕他。'),
('CUV', '约伯记', 18, 40, 23, '河水泛滥，他不发战；就是约但河的水涨到他口边，也是安然。'),
('CUV', '约伯记', 18, 40, 24, '在他防备的时候，谁能捉拿他？谁能牢笼他穿他的鼻子呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 41, 1, '你能用鱼钩钓上鳄鱼么？能用绳子压下他的舌头么？'),
('CUV', '约伯记', 18, 41, 2, '你能用绳索穿他的鼻子么？能用钩穿他的腮骨么？'),
('CUV', '约伯记', 18, 41, 3, '他岂向你连连恳求，说柔和的话么？'),
('CUV', '约伯记', 18, 41, 4, '岂肯与你立约，使你拿他永远作奴仆么？'),
('CUV', '约伯记', 18, 41, 5, '你岂可拿他当雀鸟玩耍么？岂可为你的幼女将他拴住么？'),
('CUV', '约伯记', 18, 41, 6, '搭伙的渔夫岂可拿他当货物么？能把他分给商人么？'),
('CUV', '约伯记', 18, 41, 7, '你能用倒钩枪扎满他的皮，能用鱼叉叉满他的头么？'),
('CUV', '约伯记', 18, 41, 8, '你按手在他身上，想与他争战，就不再这样行罢！'),
('CUV', '约伯记', 18, 41, 9, '人指望捉拿他是徒然的；一见他，岂不丧胆么？'),
('CUV', '约伯记', 18, 41, 10, '没有那么凶猛的人敢惹他。这样，谁能在我面前站立得住呢？'),
('CUV', '约伯记', 18, 41, 11, '谁先给我甚么，使我偿还呢？天下万物都是我的。'),
('CUV', '约伯记', 18, 41, 12, '论到鳄鱼的肢体和其大力，并美好的骨骼，我不能缄默不言。'),
('CUV', '约伯记', 18, 41, 13, '谁能剥他的外衣？谁能进他上下牙骨之间呢？'),
('CUV', '约伯记', 18, 41, 14, '谁能开他的腮颊？他牙齿四围是可畏的。'),
('CUV', '约伯记', 18, 41, 15, '他以坚固的鳞甲为可夸，紧紧合闭，封得严密。'),
('CUV', '约伯记', 18, 41, 16, '这鳞甲一一相连，甚至气不得透入其间，'),
('CUV', '约伯记', 18, 41, 17, '都是互相联络、胶结，不能分离。'),
('CUV', '约伯记', 18, 41, 18, '他打喷嚏就发出光来；他眼睛好像早晨的光线（原文是眼皮）。'),
('CUV', '约伯记', 18, 41, 19, '从他口中发出烧著的火把，与飞迸的火星；'),
('CUV', '约伯记', 18, 41, 20, '从他鼻孔冒出烟来，如烧开的锅和点著的芦苇。'),
('CUV', '约伯记', 18, 41, 21, '他的气点著煤炭，有火燄从他口中发出。'),
('CUV', '约伯记', 18, 41, 22, '他颈项中存著劲力；在他面前的都恐吓蹦跳。'),
('CUV', '约伯记', 18, 41, 23, '他的肉块互相联络，紧贴其身，不能摇动。'),
('CUV', '约伯记', 18, 41, 24, '他的心结实如石头，如下磨石那样结实。'),
('CUV', '约伯记', 18, 41, 25, '他一起来，勇士都惊恐，心里慌乱，便都昏迷。'),
('CUV', '约伯记', 18, 41, 26, '人若用刀，用枪，用标枪，用尖枪扎他，都是无用。'),
('CUV', '约伯记', 18, 41, 27, '他以铁为干草，以铜为烂木。'),
('CUV', '约伯记', 18, 41, 28, '箭不能恐吓他使他逃避；弹石在他看为碎秸。'),
('CUV', '约伯记', 18, 41, 29, '棍棒算为禾秸；他嗤笑短枪飕的响声。'),
('CUV', '约伯记', 18, 41, 30, '他肚腹下如尖瓦片；他如钉耙经过淤泥。'),
('CUV', '约伯记', 18, 41, 31, '他使深渊开滚如锅，使洋海如锅中的膏油。'),
('CUV', '约伯记', 18, 41, 32, '他行的路随后发光，令人想深渊如同白发。'),
('CUV', '约伯记', 18, 41, 33, '在地上没有像他造的那样，无所惧怕。'),
('CUV', '约伯记', 18, 41, 34, '凡高大的，他无不藐视；他在骄傲的水族上作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约伯记', 18, 42, 1, '约伯回答耶和华说：'),
('CUV', '约伯记', 18, 42, 2, '我知道，你万事都能做；你的旨意不能拦阻。'),
('CUV', '约伯记', 18, 42, 3, '谁用无知的言语使你的旨意隐藏呢？我所说的是我不明白的；这些事太奇妙，是我不知道的。'),
('CUV', '约伯记', 18, 42, 4, '求你听我，我要说话；我问你，求你指示我。'),
('CUV', '约伯记', 18, 42, 5, '我从前风闻有你，现在亲眼看见你。'),
('CUV', '约伯记', 18, 42, 6, '因此我厌恶自己（或译：我的言语），在尘土和炉灰中懊悔。'),
('CUV', '约伯记', 18, 42, 7, '耶和华对约伯说话以后，就对提幔人以利法说：我的怒气向你和你两个朋友发作，因为你们议论我不如我的仆人约伯说的是。'),
('CUV', '约伯记', 18, 42, 8, '现在你们要取七只公牛，七只公羊，到我仆人约伯那里去，为自己献上燔祭，我的仆人约伯就为你们祈祷。我因悦纳他，就不按你们的愚妄办你们。你们议论我，不如我的仆人约伯说的是。'),
('CUV', '约伯记', 18, 42, 9, '于是提幔人以利法、书亚人比勒达、拿玛人琐法照著耶和华所吩咐的去行；耶和华就悦纳约伯。'),
('CUV', '约伯记', 18, 42, 10, '约伯为他的朋友祈祷。耶和华就使约伯从苦境（原文是掳掠）转回，并且耶和华赐给他的比他从前所有的加倍。'),
('CUV', '约伯记', 18, 42, 11, '约伯的弟兄、姊妹，和以先所认识的人都来见他，在他家里一同吃饭；又论到耶和华所降与他的一切灾祸，都为他悲伤安慰他。每人也送他一块银子和一个金环。'),
('CUV', '约伯记', 18, 42, 12, '这样，耶和华后来赐福给约伯比先前更多。他有一万四千羊，六千骆驼，一千对牛，一千母驴。'),
('CUV', '约伯记', 18, 42, 13, '他也有七个儿子，三个女儿。'),
('CUV', '约伯记', 18, 42, 14, '他给长女起名叫耶米玛，次女叫基洗亚，三女叫基连哈朴。'),
('CUV', '约伯记', 18, 42, 15, '在那全地的妇女中找不著像约伯的女儿那样美貌。他们的父亲使他们在弟兄中得产业。'),
('CUV', '约伯记', 18, 42, 16, '此后，约伯又活了一百四十年，得见他的儿孙，直到四代。'),
('CUV', '约伯记', 18, 42, 17, '这样，约伯年纪老迈，日子满足而死。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 1, 1, '不从恶人的计谋，不站罪人的道路，不坐亵慢人的座位，'),
('CUV', '诗篇', 19, 1, 2, '惟喜爱耶和华的律法，昼夜思想，这人便为有福！'),
('CUV', '诗篇', 19, 1, 3, '他要像一棵树栽在溪水旁，按时候结果子，叶子也不枯干。凡他所做的尽都顺利。'),
('CUV', '诗篇', 19, 1, 4, '恶人并不是这样，乃像糠秕被风吹散。'),
('CUV', '诗篇', 19, 1, 5, '因此，当审判的时候恶人必站立不住；罪人在义人的会中也是如此。'),
('CUV', '诗篇', 19, 1, 6, '因为耶和华知道义人的道路；恶人的道路却必灭亡。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 2, 1, '外邦为甚么争闹？万民为甚么谋算虚妄的事？'),
('CUV', '诗篇', 19, 2, 2, '世上的君王一齐起来，臣宰一同商议，要敌挡耶和华并他的受膏者，'),
('CUV', '诗篇', 19, 2, 3, '说：我们要挣开他们的捆绑，脱去他们的绳索。'),
('CUV', '诗篇', 19, 2, 4, '那坐在天上的必发笑；主必嗤笑他们。'),
('CUV', '诗篇', 19, 2, 5, '那时，他要在怒中责备他们，在烈怒中惊吓他们，'),
('CUV', '诗篇', 19, 2, 6, '说：我已经立我的君在锡安─我的圣山上了。'),
('CUV', '诗篇', 19, 2, 7, '受膏者说：我要传圣旨。耶和华曾对我说：你是我的儿子，我今日生你。'),
('CUV', '诗篇', 19, 2, 8, '你求我，我就将列国赐你为基业，将地极赐你为田产。'),
('CUV', '诗篇', 19, 2, 9, '你必用铁杖打破他们；你必将他们如同窑匠的瓦器摔碎。'),
('CUV', '诗篇', 19, 2, 10, '现在，你们君王应当省悟！你们世上的审判官该受管教！'),
('CUV', '诗篇', 19, 2, 11, '当存畏惧事奉耶和华，又当存战兢而快乐。'),
('CUV', '诗篇', 19, 2, 12, '当以嘴亲子，恐怕他发怒，你们便在道中灭亡，因为他的怒气快要发作。凡投靠他的，都是有福的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 3, 1, '（大卫逃避他儿子押沙龙的时候作的诗。）耶和华啊，我的敌人何其加增；有许多人起来攻击我。'),
('CUV', '诗篇', 19, 3, 2, '有许多人议论我说：他得不著神的帮助。（细拉）'),
('CUV', '诗篇', 19, 3, 3, '但你─耶和华是我四围的盾牌，是我的荣耀，又是叫我抬起头来的。'),
('CUV', '诗篇', 19, 3, 4, '我用我的声音求告耶和华，他就从他的圣山上应允我。（细拉）'),
('CUV', '诗篇', 19, 3, 5, '我躺下睡觉，我醒著，耶和华都保佑我。'),
('CUV', '诗篇', 19, 3, 6, '虽有成万的百姓来周围攻击我，我也不怕。'),
('CUV', '诗篇', 19, 3, 7, '耶和华啊，求你起来！我的神啊，求你救我！因为你打了我一切仇敌的腮骨，敲碎了恶人的牙齿。'),
('CUV', '诗篇', 19, 3, 8, '救恩属乎耶和华；愿你赐福给你的百姓。（细拉）')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 4, 1, '（大卫的诗，交与伶长。用丝弦的乐器。）显我为义的神啊，我呼吁的时候，求你应允我！我在困苦中，你曾使我宽广；现在求你怜恤我，听我的祷告！'),
('CUV', '诗篇', 19, 4, 2, '你们这上流人哪，你们将我的尊荣变为羞辱要到几时呢？你们喜爱虚妄，寻找虚假，要到几时呢？（细拉）'),
('CUV', '诗篇', 19, 4, 3, '你们要知道，耶和华已经分别虔诚人归他自己；我求告耶和华，他必听我。'),
('CUV', '诗篇', 19, 4, 4, '你们应当畏惧，不可犯罪；在床上的时候，要心里思想，并要肃静。（细拉）'),
('CUV', '诗篇', 19, 4, 5, '当献上公义的祭，又当倚靠耶和华。'),
('CUV', '诗篇', 19, 4, 6, '有许多人说：谁能指示我们甚么好处？耶和华啊，求你仰起脸来，光照我们。'),
('CUV', '诗篇', 19, 4, 7, '你使我心里快乐，胜过那丰收五谷新酒的人。'),
('CUV', '诗篇', 19, 4, 8, '我必安然躺下睡觉，因为独有你─耶和华使我安然居住。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 5, 1, '（大卫的诗，交与伶长。用吹的乐器。）耶和华啊，求你留心听我的言语，顾念我的心思！'),
('CUV', '诗篇', 19, 5, 2, '我的王我的神啊，求你垂听我呼求的声音！因为我向你祈祷。'),
('CUV', '诗篇', 19, 5, 3, '耶和华啊，早晨你必听我的声音；早晨我必向你陈明我的心意，并要警醒！'),
('CUV', '诗篇', 19, 5, 4, '因为你不是喜悦恶事的神，恶人不能与你同居。'),
('CUV', '诗篇', 19, 5, 5, '狂傲人不能站在你眼前；凡作孽的，都是你所恨恶的。'),
('CUV', '诗篇', 19, 5, 6, '说谎言的，你必灭绝；好流人血弄诡诈的，都为耶和华所憎恶。'),
('CUV', '诗篇', 19, 5, 7, '至于我，我必凭你丰盛的慈爱进入你的居所；我必存敬畏你的心向你的圣殿下拜。'),
('CUV', '诗篇', 19, 5, 8, '耶和华啊，求你因我的仇敌，凭你的公义引领我，使你的道路在我面前正直。'),
('CUV', '诗篇', 19, 5, 9, '因为，他们的口中没有诚实；他们的心里满有邪恶；他们的喉咙是敞开的坟墓；他们用舌头谄媚人。'),
('CUV', '诗篇', 19, 5, 10, '神啊，求你定他们的罪！愿他们因自己的计谋跌倒；愿你在他们许多的过犯中把他们逐出，因为他们背叛了你。'),
('CUV', '诗篇', 19, 5, 11, '凡投靠你的，愿他们喜乐，时常欢呼，因为你护庇他们；又愿那爱你名的人都靠你欢欣。'),
('CUV', '诗篇', 19, 5, 12, '因为你必赐福与义人；耶和华啊，你必用恩惠如同盾牌四面护卫他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 6, 1, '（大卫的诗，交与伶长。用丝弦的乐器，调用第八。）耶和华啊，求你不要在怒中责备我，也不要在烈怒中惩罚我！'),
('CUV', '诗篇', 19, 6, 2, '耶和华啊，求你可怜我，因为我软弱。耶和华啊，求你医治我，因为我的骨头发战。'),
('CUV', '诗篇', 19, 6, 3, '我心也大大地惊惶。耶和华啊，你要到几时才救我呢？'),
('CUV', '诗篇', 19, 6, 4, '耶和华啊，求你转回搭救我！因你的慈爱拯救我。'),
('CUV', '诗篇', 19, 6, 5, '因为，在死地无人记念你，在阴间有谁称谢你？'),
('CUV', '诗篇', 19, 6, 6, '我因唉哼而困乏；我每夜流泪，把床榻漂起，把褥子湿透。'),
('CUV', '诗篇', 19, 6, 7, '我因忧愁眼睛干瘪，又因我一切的敌人眼睛昏花。'),
('CUV', '诗篇', 19, 6, 8, '你们一切作孽的人，离开我罢！因为耶和华听了我哀哭的声音。'),
('CUV', '诗篇', 19, 6, 9, '耶和华听了我的恳求；耶和华必收纳我的祷告。'),
('CUV', '诗篇', 19, 6, 10, '我的一切仇敌都必羞愧，大大惊惶；他们必要退后，忽然羞愧。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 7, 1, '（大卫指著便雅悯人古实的话，向耶和华唱的流离歌。）耶和华─我的神啊，我投靠你！求你救我脱离一切追赶我的人，将我救拔出来！'),
('CUV', '诗篇', 19, 7, 2, '恐怕他们像狮子撕裂我，甚至撕碎，无人搭救。'),
('CUV', '诗篇', 19, 7, 3, '耶和华─我的神啊，我若行了这事，若有罪孽在我手里，'),
('CUV', '诗篇', 19, 7, 4, '我若以恶报那与我交好的人─连那无故与我为敌的，我也救了他，'),
('CUV', '诗篇', 19, 7, 5, '就任凭仇敌追赶我，直到追上，将我的性命踏在地下，使我的荣耀归于灰尘。（细拉）'),
('CUV', '诗篇', 19, 7, 6, '耶和华啊，求你在怒中起来，挺身而立，抵挡我敌人的暴怒！求你为我兴起！你已经命定施行审判！'),
('CUV', '诗篇', 19, 7, 7, '愿众民的会环绕你！愿你从其上归于高位！'),
('CUV', '诗篇', 19, 7, 8, '耶和华向众民施行审判；耶和华啊，求你按我的公义和我心中的纯正判断我。'),
('CUV', '诗篇', 19, 7, 9, '愿恶人的恶断绝！愿你坚立义人！因为公义的神察验人的心肠肺腑。'),
('CUV', '诗篇', 19, 7, 10, '神是我的盾牌；他拯救心里正直的人。'),
('CUV', '诗篇', 19, 7, 11, '神是公义的审判者，又是天天向恶人发怒的神。'),
('CUV', '诗篇', 19, 7, 12, '若有人不回头，他的刀必磨快，弓必上弦，预备妥当了。'),
('CUV', '诗篇', 19, 7, 13, '他也预备了杀人的器械；他所射的是火箭。'),
('CUV', '诗篇', 19, 7, 14, '试看恶人因奸恶而劬劳，所怀的是毒害，所生的是虚假。'),
('CUV', '诗篇', 19, 7, 15, '他掘了坑，又挖深了，竟掉在自己所挖的阱里。'),
('CUV', '诗篇', 19, 7, 16, '他的毒害必临到他自己的头上；他的强暴必落到他自己的脑袋上。'),
('CUV', '诗篇', 19, 7, 17, '我要照著耶和华的公义称谢他，歌颂耶和华至高者的名。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 8, 1, '（大卫的诗，交与伶长。用迦特乐器。）耶和华─我们的主啊，你的名在全地何其美！你将你的荣耀彰显于天。'),
('CUV', '诗篇', 19, 8, 2, '你因敌人的缘故，从婴孩和吃奶的口中，建立了能力，使仇敌和报仇的闭口无言。'),
('CUV', '诗篇', 19, 8, 3, '我观看你指头所造的天，并你所陈设的月亮星宿，'),
('CUV', '诗篇', 19, 8, 4, '便说：人算甚么，你竟顾念他？世人算甚么，你竟眷顾他？'),
('CUV', '诗篇', 19, 8, 5, '你叫他比天使（或译：神）微小一点，并赐他荣耀尊贵为冠冕。'),
('CUV', '诗篇', 19, 8, 6, '你派他管理你手所造的，使万物，就是一切的牛羊、田野的兽、空中的鸟、海里的鱼，凡经行海道的，都服在他的脚下。'),
('CUV', '诗篇', 19, 8, 7, 'a'),
('CUV', '诗篇', 19, 8, 8, 'a'),
('CUV', '诗篇', 19, 8, 9, '耶和华─我们的主啊，你的名在全地何其美！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 9, 1, '（大卫的诗，交与伶长。调用慕拉便。）我要一心称谢耶和华；我要传扬你一切奇妙的作为。'),
('CUV', '诗篇', 19, 9, 2, '我要因你欢喜快乐；至高者啊，我要歌颂你的名！'),
('CUV', '诗篇', 19, 9, 3, '我的仇敌转身退去的时候，他们一见你的面就跌倒灭亡。'),
('CUV', '诗篇', 19, 9, 4, '因你已经为我伸冤，为我辨屈；你坐在宝座上，按公义审判。'),
('CUV', '诗篇', 19, 9, 5, '你曾斥责外邦，你曾灭绝恶人；你曾涂抹他们的名，直到永永远远。'),
('CUV', '诗篇', 19, 9, 6, '仇敌到了尽头；他们被毁坏，直到永远。你拆毁他们的城邑，连他们的名号都归于无有。'),
('CUV', '诗篇', 19, 9, 7, '惟耶和华坐著为王，直到永远；他已经为审判设摆他的宝座。'),
('CUV', '诗篇', 19, 9, 8, '他要按公义审判世界，按正直判断万民。'),
('CUV', '诗篇', 19, 9, 9, '耶和华又要给受欺压的人作高台，在患难的时候作高台。'),
('CUV', '诗篇', 19, 9, 10, '耶和华啊，认识你名的人要倚靠你，因你没有离弃寻求你的人。'),
('CUV', '诗篇', 19, 9, 11, '应当歌颂居锡安的耶和华，将他所行的传扬在众民中。'),
('CUV', '诗篇', 19, 9, 12, '因为那追讨流人血之罪的─他记念受屈的人，不忘记困苦人的哀求。'),
('CUV', '诗篇', 19, 9, 13, '耶和华啊，你是从死门把我提拔起来的；求你怜恤我，看那恨我的人所加给我的苦难，'),
('CUV', '诗篇', 19, 9, 14, '好叫我述说你一切的美德；我必在锡安城（原文是女子）的门因你的救恩欢乐。'),
('CUV', '诗篇', 19, 9, 15, '外邦人陷在自己所掘的坑中；他们的脚在自己暗设的网罗里缠住了。'),
('CUV', '诗篇', 19, 9, 16, '耶和华已将自己显明了，他已施行审判；恶人被自己手所做的缠住了（或译：他叫恶人被自己手所做的累住了）。（细拉）'),
('CUV', '诗篇', 19, 9, 17, '恶人，就是忘记神的外邦人，都必归到阴间。'),
('CUV', '诗篇', 19, 9, 18, '穷乏人必不永久被忘；困苦人的指望必不永远落空。'),
('CUV', '诗篇', 19, 9, 19, '耶和华啊，求你起来，不容人得胜！愿外邦人在你面前受审判！'),
('CUV', '诗篇', 19, 9, 20, '耶和华啊，求你使外邦人恐惧；愿他们知道自己不过是人。（细拉）')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 10, 1, '耶和华啊，你为甚么站在远处？在患难的时候为甚么隐藏？'),
('CUV', '诗篇', 19, 10, 2, '恶人在骄横中把困苦人追得火急；愿他们陷在自己所设的计谋里。'),
('CUV', '诗篇', 19, 10, 3, '因为恶人以心愿自夸；贪财的背弃耶和华，并且轻慢他（或译：他祝福贪财的，却轻慢耶和华）。'),
('CUV', '诗篇', 19, 10, 4, '恶人面带骄傲，说：耶和华必不追究；他一切所想的都以为没有神。'),
('CUV', '诗篇', 19, 10, 5, '凡他所做的，时常稳固；你的审判超过他的眼界。至于他一切的敌人，他都向他们喷气。'),
('CUV', '诗篇', 19, 10, 6, '他心里说：我必不动摇，世世代代不遭灾难。'),
('CUV', '诗篇', 19, 10, 7, '他满口是咒骂、诡诈、欺压，舌底是毒害、奸恶。'),
('CUV', '诗篇', 19, 10, 8, '他在村庄埋伏等候；他在隐密处杀害无辜的人。他的眼睛窥探无倚无靠的人；'),
('CUV', '诗篇', 19, 10, 9, '他埋伏在暗地，如狮子蹲在洞中。他埋伏，要掳去困苦人；他拉网，就把困苦人掳去。'),
('CUV', '诗篇', 19, 10, 10, '他屈身蹲伏，无倚无靠的人就倒在他爪牙（爪牙：或译强暴人）之下。'),
('CUV', '诗篇', 19, 10, 11, '他心里说：神竟忘记了；他掩面永不观看。'),
('CUV', '诗篇', 19, 10, 12, '耶和华啊，求你起来！神啊，求你举手，不要忘记困苦人！'),
('CUV', '诗篇', 19, 10, 13, '恶人为何轻慢神，心里说：你必不追究？'),
('CUV', '诗篇', 19, 10, 14, '其实你已经观看；因为奸恶毒害，你都看见了，为要以手施行报应。无倚无靠的人把自己交托你；你向来是帮助孤儿的。'),
('CUV', '诗篇', 19, 10, 15, '愿你打断恶人的膀臂；至于坏人，愿你追究他的恶，直到净尽。'),
('CUV', '诗篇', 19, 10, 16, '耶和华永永远远为王；外邦人从他的地已经灭绝了。'),
('CUV', '诗篇', 19, 10, 17, '耶和华啊，谦卑人的心愿，你早已知道（原文是听见）。你必预备他们的心，也必侧耳听他们的祈求，'),
('CUV', '诗篇', 19, 10, 18, '为要给孤儿和受欺压的人伸冤，使强横的人不再威吓他们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 11, 1, '（大卫的诗，交与伶长。）我是投靠耶和华；你们怎么对我说：你当像鸟飞往你的山去。'),
('CUV', '诗篇', 19, 11, 2, '看哪，恶人弯弓，把箭搭在弦上，要在暗中射那心里正直的人。'),
('CUV', '诗篇', 19, 11, 3, '根基若毁坏，义人还能做甚么呢？'),
('CUV', '诗篇', 19, 11, 4, '耶和华在他的圣殿里；耶和华的宝座在天上；他的慧眼察看世人。'),
('CUV', '诗篇', 19, 11, 5, '耶和华试验义人；惟有恶人和喜爱强暴的人，他心里恨恶。'),
('CUV', '诗篇', 19, 11, 6, '他要向恶人密布网罗；有烈火、硫磺、热风，作他们杯中的分。'),
('CUV', '诗篇', 19, 11, 7, '因为耶和华是公义的，他喜爱公义；正直人必得见他的面。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 12, 1, '（大卫的诗，交与伶长。调用第八。）耶和华啊，求你帮助，因虔诚人断绝了；世人中间的忠信人没有了。'),
('CUV', '诗篇', 19, 12, 2, '人人向邻舍说谎；他们说话，是嘴唇油滑，心口不一。'),
('CUV', '诗篇', 19, 12, 3, '凡油滑的嘴唇和夸大的舌头，耶和华必要剪除。'),
('CUV', '诗篇', 19, 12, 4, '他们曾说：我们必能以舌头得胜；我们的嘴唇是我们自己的，谁能作我们的主呢？'),
('CUV', '诗篇', 19, 12, 5, '耶和华说：因为困苦人的冤屈和贫穷人的叹息，我现在要起来，把他安置在他所切慕的稳妥之地。'),
('CUV', '诗篇', 19, 12, 6, '耶和华的言语是纯净的言语，如同银子在泥炉中炼过七次。'),
('CUV', '诗篇', 19, 12, 7, '耶和华啊，你必保护他们；你必保佑他们永远脱离这世代的人。'),
('CUV', '诗篇', 19, 12, 8, '下流人在世人中升高，就有恶人到处游行。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 13, 1, '（大卫的诗，交与伶长。）耶和华啊，你忘记我要到几时呢？要到永远么？你掩面不顾我要到几时呢？'),
('CUV', '诗篇', 19, 13, 2, '我心里筹算，终日愁苦，要到几时呢？我的仇敌升高压制我，要到几时呢？'),
('CUV', '诗篇', 19, 13, 3, '耶和华─我的神啊，求你看顾我，应允我！使我眼目光明，免得我沉睡至死；'),
('CUV', '诗篇', 19, 13, 4, '免得我的仇敌说：我胜了他；免得我的敌人在我摇动的时候喜乐。'),
('CUV', '诗篇', 19, 13, 5, '但我倚靠你的慈爱；我的心因你的救恩快乐。'),
('CUV', '诗篇', 19, 13, 6, '我要向耶和华歌唱，因他用厚恩待我。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 14, 1, '（大卫的诗，交与伶长。）愚顽人心里说：没有神。他们都是邪恶，行了可憎恶的事；没有一个人行善。'),
('CUV', '诗篇', 19, 14, 2, '耶和华从天上垂看世人，要看有明白的没有，有寻求神的没有。'),
('CUV', '诗篇', 19, 14, 3, '他们都偏离正路，一同变为污秽；并没有行善的，连一个也没有。'),
('CUV', '诗篇', 19, 14, 4, '作孽的都没有知识么？他们吞吃我的百姓，如同吃饭一样，并不求告耶和华。'),
('CUV', '诗篇', 19, 14, 5, '他们在那里大大地害怕，因为神在义人的族类中。'),
('CUV', '诗篇', 19, 14, 6, '你们叫困苦人的谋算变为羞辱；然而耶和华是他的避难所。'),
('CUV', '诗篇', 19, 14, 7, '但愿以色列的救恩从锡安而出。耶和华救回他被掳的子民那时，雅各要快乐，以色列要欢喜。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 15, 1, '（大卫的诗。）耶和华啊，谁能寄居你的帐幕？谁能住在你的圣山？'),
('CUV', '诗篇', 19, 15, 2, '就是行为正直、做事公义、心里说实话的人。'),
('CUV', '诗篇', 19, 15, 3, '他不以舌头谗谤人，不恶待朋友，也不随伙毁谤邻里。'),
('CUV', '诗篇', 19, 15, 4, '他眼中藐视匪类，却尊重那敬畏耶和华的人。他发了誓，虽然自己吃亏也不更改。'),
('CUV', '诗篇', 19, 15, 5, '他不放债取利，不受贿赂以害无辜。行这些事的人必永不动摇。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 16, 1, '（大卫的金诗。）神啊，求你保佑我，因为我投靠你。'),
('CUV', '诗篇', 19, 16, 2, '我的心哪，你曾对耶和华说：你是我的主；我的好处不在你以外。'),
('CUV', '诗篇', 19, 16, 3, '论到世上的圣民，他们又美又善，是我最喜悦的。'),
('CUV', '诗篇', 19, 16, 4, '以别神代替耶和华的（或译：送礼物给别神的），他们的愁苦必加增；他们所浇奠的血我不献上；我嘴唇也不提别神的名号。'),
('CUV', '诗篇', 19, 16, 5, '耶和华是我的产业，是我杯中的分；我所得的，你为我持守。'),
('CUV', '诗篇', 19, 16, 6, '用绳量给我的地界，坐落在佳美之处；我的产业实在美好。'),
('CUV', '诗篇', 19, 16, 7, '我必称颂那指教我的耶和华；我的心肠在夜间也警戒我。'),
('CUV', '诗篇', 19, 16, 8, '我将耶和华常摆在我面前，因他在我右边，我便不致摇动。'),
('CUV', '诗篇', 19, 16, 9, '因此，我的心欢喜，我的灵（原文是荣耀）快乐；我的肉身也要安然居住。'),
('CUV', '诗篇', 19, 16, 10, '因为你必不将我的灵魂撇在阴间，也不叫你的圣者见朽坏。'),
('CUV', '诗篇', 19, 16, 11, '你必将生命的道路指示我。在你面前有满足的喜乐；在你右手中有永远的福乐。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 17, 1, '（大卫的祈祷。）耶和华啊，求你听闻公义，侧耳听我的呼吁！求你留心听我这不出于诡诈嘴唇的祈祷！'),
('CUV', '诗篇', 19, 17, 2, '愿我的判语从你面前发出；愿你的眼睛观看公正。'),
('CUV', '诗篇', 19, 17, 3, '你已经试验我的心；你在夜间鉴察我；你熬炼我，却找不著甚么；我立志叫我口中没有过失。'),
('CUV', '诗篇', 19, 17, 4, '论到人的行为，我藉著你嘴唇的言语自己谨守，不行强暴人的道路。'),
('CUV', '诗篇', 19, 17, 5, '我的脚踏定了你的路径；我的两脚未曾滑跌。'),
('CUV', '诗篇', 19, 17, 6, '神啊，我曾求告你，因为你必应允我；求你向我侧耳，听我的言语。'),
('CUV', '诗篇', 19, 17, 7, '求你显出你奇妙的慈爱来；你是那用右手拯救投靠你的脱离起来攻击他们的人。'),
('CUV', '诗篇', 19, 17, 8, '求你保护我，如同保护眼中的瞳人；将我隐藏在你翅膀的荫下，'),
('CUV', '诗篇', 19, 17, 9, '使我脱离那欺压我的恶人，就是围困我要害我命的仇敌。'),
('CUV', '诗篇', 19, 17, 10, '他们的心被脂油包裹；他们用口说骄傲的话。'),
('CUV', '诗篇', 19, 17, 11, '他们围困了我们的脚步；他们瞪著眼，要把我们推倒在地。'),
('CUV', '诗篇', 19, 17, 12, '他像狮子急要抓食，又像少壮狮子蹲伏在暗处。'),
('CUV', '诗篇', 19, 17, 13, '耶和华啊，求你起来，前去迎敌，将他打倒！用你的刀救护我命脱离恶人。'),
('CUV', '诗篇', 19, 17, 14, '耶和华啊，求你用手救我脱离世人，脱离那只在今生有福分的世人！你把你的财宝充满他们的肚腹；他们因有儿女就心满意足，将其余的财物留给他们的婴孩。'),
('CUV', '诗篇', 19, 17, 15, '至于我，我必在义中见你的面；我醒了的时候，得见（或译：著）你的形像就心满意足了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 18, 1, '（耶和华的仆人大卫的诗，交与伶长。当耶和华救他脱离一切仇敌和扫罗之手的日子，他向耶和华念这诗的话。说：）耶和华，我的力量啊，我爱你！'),
('CUV', '诗篇', 19, 18, 2, '耶和华是我的岩石，我的山寨，我的救主，我的神，我的磐石，我所投靠的。他是我的盾牌，是拯救我的角，是我的高台。'),
('CUV', '诗篇', 19, 18, 3, '我要求告当赞美的耶和华；这样我必从仇敌手中被救出来。'),
('CUV', '诗篇', 19, 18, 4, '曾有死亡的绳索缠绕我，匪类的急流使我惊惧，'),
('CUV', '诗篇', 19, 18, 5, '阴间的绳索缠绕我，死亡的网罗临到我。'),
('CUV', '诗篇', 19, 18, 6, '我在急难中求告耶和华，向我的神呼求。他从殿中听了我的声音；我在他面前的呼求入了他的耳中。'),
('CUV', '诗篇', 19, 18, 7, '那时，因他发怒，地就摇撼战抖；山的根基也震动摇撼。'),
('CUV', '诗篇', 19, 18, 8, '从他鼻孔冒烟上腾；从他口中发火焚烧，连炭也著了。'),
('CUV', '诗篇', 19, 18, 9, '他又使天下垂，亲自降临，有黑云在他脚下。'),
('CUV', '诗篇', 19, 18, 10, '他坐著基路伯飞行；他藉著风的翅膀快飞。'),
('CUV', '诗篇', 19, 18, 11, '他以黑暗为藏身之处，以水的黑暗、天空的厚云为他四围的行宫。'),
('CUV', '诗篇', 19, 18, 12, '因他面前的光辉，他的厚云行过便有冰雹火炭。'),
('CUV', '诗篇', 19, 18, 13, '耶和华也在天上打雷；至高者发出声音便有冰雹火炭。'),
('CUV', '诗篇', 19, 18, 14, '他射出箭来，使仇敌四散；多多发出闪电，使他们扰乱。'),
('CUV', '诗篇', 19, 18, 15, '耶和华啊，你的斥责一发，你鼻孔的气一出，海底就出现，大地的根基也显露。'),
('CUV', '诗篇', 19, 18, 16, '他从高天伸手抓住我，把我从大水中拉上来。'),
('CUV', '诗篇', 19, 18, 17, '他救我脱离我的劲敌和那些恨我的人，因为他们比我强盛。'),
('CUV', '诗篇', 19, 18, 18, '我遭遇灾难的日子，他们来攻击我；但耶和华是我的倚靠。'),
('CUV', '诗篇', 19, 18, 19, '他又领我到宽阔之处；他救拔我，因他喜悦我。'),
('CUV', '诗篇', 19, 18, 20, '耶和华按著我的公义报答我，按著我手中的清洁赏赐我。'),
('CUV', '诗篇', 19, 18, 21, '因为我遵守了耶和华的道，未曾作恶离开我的神。'),
('CUV', '诗篇', 19, 18, 22, '他的一切典章常在我面前；他的律例我也未曾丢弃。'),
('CUV', '诗篇', 19, 18, 23, '我在他面前作了完全人；我也保守自己远离我的罪孽。'),
('CUV', '诗篇', 19, 18, 24, '所以，耶和华按我的公义，按我在他眼前手中的清洁偿还我。'),
('CUV', '诗篇', 19, 18, 25, '慈爱的人，你以慈爱待他；完全的人，你以完全待他。'),
('CUV', '诗篇', 19, 18, 26, '清洁的人，你以清洁待他；乖僻的人，你以弯曲待他。'),
('CUV', '诗篇', 19, 18, 27, '困苦的百姓，你必拯救；高傲的眼目，你必使他降卑。'),
('CUV', '诗篇', 19, 18, 28, '你必点著我的灯；耶和华─我的神必照明我的黑暗。'),
('CUV', '诗篇', 19, 18, 29, '我藉著你冲入敌军，藉著我的神跳过墙垣。'),
('CUV', '诗篇', 19, 18, 30, '至于神，他的道是完全的；耶和华的话是炼净的。凡投靠他的，他便作他们的盾牌。'),
('CUV', '诗篇', 19, 18, 31, '除了耶和华，谁是神呢？除了我们的神，谁是磐石呢？'),
('CUV', '诗篇', 19, 18, 32, '惟有那以力量束我的腰、使我行为完全的，他是神。'),
('CUV', '诗篇', 19, 18, 33, '他使我的脚快如母鹿的蹄，又使我在高处安稳。'),
('CUV', '诗篇', 19, 18, 34, '他教导我的手能以争战，甚至我的膀臂能开铜弓。'),
('CUV', '诗篇', 19, 18, 35, '你把你的救恩给我作盾牌；你的右手扶持我；你的温和使我为大。'),
('CUV', '诗篇', 19, 18, 36, '你使我脚下的地步宽阔；我的脚未曾滑跌。'),
('CUV', '诗篇', 19, 18, 37, '我要追赶我的仇敌，并要追上他们；不将他们灭绝，我总不归回。'),
('CUV', '诗篇', 19, 18, 38, '我要打伤他们，使他们不能起来；他们必倒在我的脚下。'),
('CUV', '诗篇', 19, 18, 39, '因为你曾以力量束我的腰，使我能争战；你也使那起来攻击我的都服在我以下。'),
('CUV', '诗篇', 19, 18, 40, '你又使我的仇敌在我面前转背逃跑，叫我能以剪除那恨我的人。'),
('CUV', '诗篇', 19, 18, 41, '他们呼求，却无人拯救；就是呼求耶和华，他也不应允。'),
('CUV', '诗篇', 19, 18, 42, '我捣碎他们，如同风前的灰尘，倒出他们，如同街上的泥土。'),
('CUV', '诗篇', 19, 18, 43, '你救我脱离百姓的争竞，立我作列国的元首；我素不认识的民必事奉我。'),
('CUV', '诗篇', 19, 18, 44, '他们一听见我的名声就必顺从我；外邦人要投降我。'),
('CUV', '诗篇', 19, 18, 45, '外邦人要衰残，战战兢兢地出他们的营寨。'),
('CUV', '诗篇', 19, 18, 46, '耶和华是活神。愿我的磐石被人称颂；愿救我的神被人尊崇。'),
('CUV', '诗篇', 19, 18, 47, '这位神，就是那为我伸冤、使众民服在我以下的。'),
('CUV', '诗篇', 19, 18, 48, '你救我脱离仇敌，又把我举起，高过那些起来攻击我的；你救我脱离强暴的人。'),
('CUV', '诗篇', 19, 18, 49, '耶和华啊，因此我要在外邦中称谢你，歌颂你的名。'),
('CUV', '诗篇', 19, 18, 50, '耶和华赐极大的救恩给他所立的王，施慈爱给他的受膏者，就是给大卫和他的后裔，直到永远。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 19, 1, '（大卫的诗，交与伶长。）诸天述说神的荣耀；穹苍传扬他的手段。'),
('CUV', '诗篇', 19, 19, 2, '这日到那日发出言语；这夜到那夜传出知识。'),
('CUV', '诗篇', 19, 19, 3, '无言无语，也无声音可听。'),
('CUV', '诗篇', 19, 19, 4, '他的量带通遍天下，他的言语传到地极。神在其间为太阳安设帐幕；'),
('CUV', '诗篇', 19, 19, 5, '太阳如同新郎出洞房，又如勇士欢然奔路。'),
('CUV', '诗篇', 19, 19, 6, '他从天这边出来，绕到天那边，没有一物被隐藏不得他的热气。'),
('CUV', '诗篇', 19, 19, 7, '耶和华的律法全备，能苏醒人心；耶和华的法度确定，能使愚人有智慧。'),
('CUV', '诗篇', 19, 19, 8, '耶和华的训词正直，能快活人的心；耶和华的命令清洁，能明亮人的眼目。'),
('CUV', '诗篇', 19, 19, 9, '耶和华的道理洁净，存到永远；耶和华的典章真实，全然公义─'),
('CUV', '诗篇', 19, 19, 10, '都比金子可羡慕，且比极多的精金可羡慕；比蜜甘甜，且比蜂房下滴的蜜甘甜。'),
('CUV', '诗篇', 19, 19, 11, '况且你的仆人因此受警戒，守著这些便有大赏。'),
('CUV', '诗篇', 19, 19, 12, '谁能知道自己的错失呢？愿你赦免我隐而未现的过错。'),
('CUV', '诗篇', 19, 19, 13, '求你拦阻仆人不犯任意妄为的罪，不容这罪辖制我，我便完全，免犯大罪。'),
('CUV', '诗篇', 19, 19, 14, '耶和华─我的磐石，我的救赎主啊，愿我口中的言语、心里的意念在你面前蒙悦纳。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 20, 1, '（大卫的诗，交与伶长。）愿耶和华在你遭难的日子应允你；愿名为雅各神的高举你。'),
('CUV', '诗篇', 19, 20, 2, '愿他从圣所救助你，从锡安坚固你，'),
('CUV', '诗篇', 19, 20, 3, '记念你的一切供献，悦纳你的燔祭，（细拉）'),
('CUV', '诗篇', 19, 20, 4, '将你心所愿的赐给你，成就你的一切筹算。'),
('CUV', '诗篇', 19, 20, 5, '我们要因你的救恩夸胜，要奉我们神的名竖立旌旗。愿耶和华成就你一切所求的！'),
('CUV', '诗篇', 19, 20, 6, '现在我知道耶和华救护他的受膏者，必从他的圣天上应允他，用右手的能力救护他。'),
('CUV', '诗篇', 19, 20, 7, '有人靠车，有人靠马，但我们要提到耶和华─我们神的名。'),
('CUV', '诗篇', 19, 20, 8, '他们都屈身仆倒，我们却起来，立得正直。'),
('CUV', '诗篇', 19, 20, 9, '求耶和华施行拯救；我们呼求的时候，愿王应允我们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 21, 1, '（大卫的诗，交与伶长。）耶和华啊，王必因你的能力欢喜；因你的救恩，他的快乐何其大！'),
('CUV', '诗篇', 19, 21, 2, '他心里所愿的，你已经赐给他；他嘴唇所求的，你未尝不应允。（细拉）'),
('CUV', '诗篇', 19, 21, 3, '你以美福迎接他，把精金的冠冕戴在他头上。'),
('CUV', '诗篇', 19, 21, 4, '他向你求寿，你便赐给他，就是日子长久，直到永远。'),
('CUV', '诗篇', 19, 21, 5, '他因你的救恩大有荣耀；你又将尊荣威严加在他身上。'),
('CUV', '诗篇', 19, 21, 6, '你使他有洪福，直到永远，又使他在你面前欢喜快乐。'),
('CUV', '诗篇', 19, 21, 7, '王倚靠耶和华，因至高者的慈爱必不摇动。'),
('CUV', '诗篇', 19, 21, 8, '你的手要搜出你的一切仇敌；你的右手要搜出那些恨你的人。'),
('CUV', '诗篇', 19, 21, 9, '你发怒的时候，要使他们如在炎热的火炉中。耶和华要在他的震怒中吞灭他们；那火要把他们烧尽了。'),
('CUV', '诗篇', 19, 21, 10, '你必从世上灭绝他们的子孙（原文是果子），从人间灭绝他们的后裔。'),
('CUV', '诗篇', 19, 21, 11, '因为他们有意加害于你；他们想出计谋，却不能做成。'),
('CUV', '诗篇', 19, 21, 12, '你必使他们转背逃跑，向他们的脸搭箭在弦。'),
('CUV', '诗篇', 19, 21, 13, '耶和华啊，愿你因自己的能力显为至高！这样，我们就唱诗，歌颂你的大能。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 22, 1, '（大卫的诗，交与伶长。调用朝鹿。）我的神，我的神！为甚么离弃我？为甚么远离不救我？不听我唉哼的言语？'),
('CUV', '诗篇', 19, 22, 2, '我的神啊，我白日呼求，你不应允，夜间呼求，并不住声。'),
('CUV', '诗篇', 19, 22, 3, '但你是圣洁的，是用以色列的赞美为宝座（或译：居所）的。'),
('CUV', '诗篇', 19, 22, 4, '我们的祖宗倚靠你；他们倚靠你，你便解救他们。'),
('CUV', '诗篇', 19, 22, 5, '他们哀求你，便蒙解救；他们倚靠你，就不羞愧。'),
('CUV', '诗篇', 19, 22, 6, '但我是虫，不是人，被众人羞辱，被百姓藐视。'),
('CUV', '诗篇', 19, 22, 7, '凡看见我的都嗤笑我；他们撇嘴摇头，说：'),
('CUV', '诗篇', 19, 22, 8, '他把自己交托耶和华，耶和华可以救他罢！耶和华既喜悦他，可以搭救他罢！'),
('CUV', '诗篇', 19, 22, 9, '但你是叫我出母腹的；我在母怀里，你就使我有倚靠的心。'),
('CUV', '诗篇', 19, 22, 10, '我自出母胎就被交在你手里；从我母亲生我，你就是我的神。'),
('CUV', '诗篇', 19, 22, 11, '求你不要远离我！因为急难临近了，没有人帮助我。'),
('CUV', '诗篇', 19, 22, 12, '有许多公牛围绕我，巴珊大力的公牛四面困住我。'),
('CUV', '诗篇', 19, 22, 13, '他们向我张口，好像抓撕吼叫的狮子。'),
('CUV', '诗篇', 19, 22, 14, '我如水被倒出来；我的骨头都脱了节；我心在我里面如蜡镕化。'),
('CUV', '诗篇', 19, 22, 15, '我的精力枯干，如同瓦片；我的舌头贴在我牙床上。你将我安置在死地的尘土中。'),
('CUV', '诗篇', 19, 22, 16, '犬类围著我，恶党环绕我；他们扎了我的手，我的脚。'),
('CUV', '诗篇', 19, 22, 17, '我的骨头，我都能数过；他们瞪著眼看我。'),
('CUV', '诗篇', 19, 22, 18, '他们分我的外衣，为我的里衣拈阄。'),
('CUV', '诗篇', 19, 22, 19, '耶和华啊，求你不要远离我！我的救主啊，求你快来帮助我！'),
('CUV', '诗篇', 19, 22, 20, '求你救我的灵魂脱离刀剑，救我的生命（生命：原文是独一者）脱离犬类，'),
('CUV', '诗篇', 19, 22, 21, '救我脱离狮子的口；你已经应允我，使我脱离野牛的角。'),
('CUV', '诗篇', 19, 22, 22, '我要将你的名传与我的弟兄，在会中我要赞美你。'),
('CUV', '诗篇', 19, 22, 23, '你们敬畏耶和华的人要赞美他！雅各的后裔都要荣耀他！以色列的后裔都要惧怕他！'),
('CUV', '诗篇', 19, 22, 24, '因为他没有藐视憎恶受苦的人，也没有向他掩面；那受苦之人呼吁的时候，他就垂听。'),
('CUV', '诗篇', 19, 22, 25, '我在大会中赞美你的话是从你而来的；我要在敬畏耶和华的人面前还我的愿。'),
('CUV', '诗篇', 19, 22, 26, '谦卑的人必吃得饱足；寻求耶和华的人必赞美他。愿你们的心永远活著！'),
('CUV', '诗篇', 19, 22, 27, '地的四极都要想念耶和华，并且归顺他；列国的万族都要在你面前敬拜。'),
('CUV', '诗篇', 19, 22, 28, '因为国权是耶和华的；他是管理万国的。'),
('CUV', '诗篇', 19, 22, 29, '地上一切丰肥的人必吃喝而敬拜；凡下到尘土中─不能存活自己性命的人─都要在他面前下拜。'),
('CUV', '诗篇', 19, 22, 30, '他必有后裔事奉他；主所行的事必传与后代。'),
('CUV', '诗篇', 19, 22, 31, '他们必来把他的公义传给将要生的民，言明这事是他所行的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 23, 1, '（大卫的诗。）耶和华是我的牧者，我必不致缺乏。'),
('CUV', '诗篇', 19, 23, 2, '他使我躺卧在青草地上，领我在可安歇的水边。'),
('CUV', '诗篇', 19, 23, 3, '他使我的灵魂苏醒，为自己的名引导我走义路。'),
('CUV', '诗篇', 19, 23, 4, '我虽然行过死荫的幽谷，也不怕遭害，因为你与我同在；你的杖，你的竿，都安慰我。'),
('CUV', '诗篇', 19, 23, 5, '在我敌人面前，你为我摆设筵席；你用油膏了我的头，使我的福杯满溢。'),
('CUV', '诗篇', 19, 23, 6, '我一生一世必有恩惠慈爱随著我；我且要住在耶和华的殿中，直到永远。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 24, 1, '（大卫的诗。）地和其中所充满的，世界和住在其间的，都属耶和华。'),
('CUV', '诗篇', 19, 24, 2, '他把地建立在海上，安定在大水之上。'),
('CUV', '诗篇', 19, 24, 3, '谁能登耶和华的山？谁能站在他的圣所？'),
('CUV', '诗篇', 19, 24, 4, '就是手洁心清、不向虚妄、起誓不怀诡诈的人。'),
('CUV', '诗篇', 19, 24, 5, '他必蒙耶和华赐福，又蒙救他的神使他成义。'),
('CUV', '诗篇', 19, 24, 6, '这是寻求耶和华的族类，是寻求你面的雅各。（细拉）'),
('CUV', '诗篇', 19, 24, 7, '众城门哪，你们要抬起头来！永久的门户，你们要被举起！那荣耀的王将要进来！'),
('CUV', '诗篇', 19, 24, 8, '荣耀的王是谁呢？就是有力有能的耶和华，在战场上有能的耶和华！'),
('CUV', '诗篇', 19, 24, 9, '众城门哪，你们要抬起头来！永久的门户，你们要把头抬起！那荣耀的王将要进来！'),
('CUV', '诗篇', 19, 24, 10, '荣耀的王是谁呢？万军之耶和华，他是荣耀的王！（细拉）')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 25, 1, '（大卫的诗。）耶和华啊，我的心仰望你。'),
('CUV', '诗篇', 19, 25, 2, '我的神啊，我素来倚靠你；求你不要叫我羞愧，不要叫我的仇敌向我夸胜。'),
('CUV', '诗篇', 19, 25, 3, '凡等候你的必不羞愧；惟有那无故行奸诈的必要羞愧。'),
('CUV', '诗篇', 19, 25, 4, '耶和华啊，求你将你的道指示我，将你的路教训我！'),
('CUV', '诗篇', 19, 25, 5, '求你以你的真理引导我，教训我，因为你是救我的神。我终日等候你。'),
('CUV', '诗篇', 19, 25, 6, '耶和华啊，求你记念你的怜悯和慈爱，因为这是亘古以来所常有的。'),
('CUV', '诗篇', 19, 25, 7, '求你不要记念我幼年的罪愆和我的过犯；耶和华啊，求你因你的恩惠，按你的慈爱记念我。'),
('CUV', '诗篇', 19, 25, 8, '耶和华是良善正直的，所以他必指示罪人走正路。'),
('CUV', '诗篇', 19, 25, 9, '他必按公平引领谦卑人，将他的道教训他们。'),
('CUV', '诗篇', 19, 25, 10, '凡遵守他的约和他法度的人，耶和华都以慈爱诚实待他。'),
('CUV', '诗篇', 19, 25, 11, '耶和华啊，求你因你的名赦免我的罪，因为我的罪重大。'),
('CUV', '诗篇', 19, 25, 12, '谁敬畏耶和华，耶和华必指示他当选择的道路。'),
('CUV', '诗篇', 19, 25, 13, '他必安然居住；他的后裔必承受地土。'),
('CUV', '诗篇', 19, 25, 14, '耶和华与敬畏他的人亲密；他必将自己的约指示他们。'),
('CUV', '诗篇', 19, 25, 15, '我的眼目时常仰望耶和华，因为他必将我的脚从网里拉出来。'),
('CUV', '诗篇', 19, 25, 16, '求你转向我，怜恤我，因为我是孤独困苦。'),
('CUV', '诗篇', 19, 25, 17, '我心里的愁苦甚多，求你救我脱离我的祸患。'),
('CUV', '诗篇', 19, 25, 18, '求你看顾我的困苦，我的艰难，赦免我一切的罪。'),
('CUV', '诗篇', 19, 25, 19, '求你察看我的仇敌，因为他们人多，并且痛痛地恨我。'),
('CUV', '诗篇', 19, 25, 20, '求你保护我的性命，搭救我，使我不致羞愧，因为我投靠你。'),
('CUV', '诗篇', 19, 25, 21, '愿纯全、正直保守我，因为我等候你。'),
('CUV', '诗篇', 19, 25, 22, '神啊，求你救赎以色列脱离他一切的愁苦。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 26, 1, '（大卫的诗。）耶和华啊，求你为我伸冤，因我向来行事纯全；我又倚靠耶和华，并不摇动。'),
('CUV', '诗篇', 19, 26, 2, '耶和华啊，求你察看我，试验我，熬炼我的肺腑心肠。'),
('CUV', '诗篇', 19, 26, 3, '因为你的慈爱常在我眼前，我也按你的真理而行。'),
('CUV', '诗篇', 19, 26, 4, '我没有和虚谎人同坐，也不与瞒哄人的同群。'),
('CUV', '诗篇', 19, 26, 5, '我恨恶恶人的会，必不与恶人同坐。'),
('CUV', '诗篇', 19, 26, 6, '耶和华啊，我要洗手表明无辜，才环绕你的祭坛；'),
('CUV', '诗篇', 19, 26, 7, '我好发称谢的声音，也要述说你一切奇妙的作为。'),
('CUV', '诗篇', 19, 26, 8, '耶和华啊，我喜爱你所住的殿和你显荣耀的居所。'),
('CUV', '诗篇', 19, 26, 9, '不要把我的灵魂和罪人一同除掉；不要把我的性命和流人血的一同除掉。'),
('CUV', '诗篇', 19, 26, 10, '他们的手中有奸恶，右手满有贿赂。'),
('CUV', '诗篇', 19, 26, 11, '至于我，却要行事纯全；求你救赎我，怜恤我！'),
('CUV', '诗篇', 19, 26, 12, '我的脚站在平坦地方；在众会中我要称颂耶和华！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 27, 1, '（大卫的诗。）耶和华是我的亮光，是我的拯救，我还怕谁呢？耶和华是我性命的保障（或译：力量），我还惧谁呢？'),
('CUV', '诗篇', 19, 27, 2, '那作恶的就是我的仇敌，前来吃我肉的时候就绊跌仆倒。'),
('CUV', '诗篇', 19, 27, 3, '虽有军兵安营攻击我，我的心也不害怕；虽然兴起刀兵攻击我，我必仍旧安稳。'),
('CUV', '诗篇', 19, 27, 4, '有一件事，我曾求耶和华，我仍要寻求：就是一生一世住在耶和华的殿中，瞻仰他的荣美，在他的殿里求问。'),
('CUV', '诗篇', 19, 27, 5, '因为我遭遇患难，他必暗暗地保守我；在他亭子里，把我藏在他帐幕的隐密处，将我高举在磐石上。'),
('CUV', '诗篇', 19, 27, 6, '现在我得以昂首，高过四面的仇敌。我要在他的帐幕里欢然献祭；我要唱诗歌颂耶和华。'),
('CUV', '诗篇', 19, 27, 7, '耶和华啊，我用声音呼吁的时候，求你垂听；并求你怜恤我，应允我。'),
('CUV', '诗篇', 19, 27, 8, '你说：你们当寻求我的面。那时我心向你说：耶和华啊，你的面我正要寻求。'),
('CUV', '诗篇', 19, 27, 9, '不要向我掩面。不要发怒赶逐仆人，你向来是帮助我的。救我的神啊，不要丢掉我，也不要离弃我。'),
('CUV', '诗篇', 19, 27, 10, '我父母离弃我，耶和华必收留我。'),
('CUV', '诗篇', 19, 27, 11, '耶和华啊，求你将你的道指教我，因我仇敌的缘故引导我走平坦的路。'),
('CUV', '诗篇', 19, 27, 12, '求你不要把我交给敌人，遂其所愿；因为妄作见证的和口吐凶言的，起来攻击我。'),
('CUV', '诗篇', 19, 27, 13, '我若不信在活人之地得见耶和华的恩惠，就早已丧胆了。'),
('CUV', '诗篇', 19, 27, 14, '要等候耶和华！当壮胆，坚固你的心！我再说，要等候耶和华！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 28, 1, '（大卫的诗。）耶和华啊，我要求告你！我的磐石啊，不要向我缄默！倘若你向我闭口，我就如将死的人一样。'),
('CUV', '诗篇', 19, 28, 2, '我呼求你，向你至圣所举手的时候，求你垂听我恳求的声音！'),
('CUV', '诗篇', 19, 28, 3, '不要把我和恶人并作孽的一同除掉；他们与邻舍说和平话，心里却是奸恶。'),
('CUV', '诗篇', 19, 28, 4, '愿你按著他们所做的，并他们所行的恶事待他们。愿你照著他们手所做的待他们，将他们所应得的报应加给他们。'),
('CUV', '诗篇', 19, 28, 5, '他们既然不留心耶和华所行的和他手所做的，他就必毁坏他们，不建立他们。'),
('CUV', '诗篇', 19, 28, 6, '耶和华是应当称颂的，因为他听了我恳求的声音。'),
('CUV', '诗篇', 19, 28, 7, '耶和华是我的力量，是我的盾牌；我心里倚靠他就得帮助。所以我心中欢乐，我必用诗歌颂赞他。'),
('CUV', '诗篇', 19, 28, 8, '耶和华是他百姓的力量，又是他受膏者得救的保障。'),
('CUV', '诗篇', 19, 28, 9, '求你拯救你的百姓，赐福给你的产业，牧养他们，扶持他们，直到永远。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 29, 1, '（大卫的诗。）神的众子啊，你们要将荣耀、能力归给耶和华，归给耶和华！'),
('CUV', '诗篇', 19, 29, 2, '要将耶和华的名所当得的荣耀归给他，以圣洁的（的：或译为）妆饰敬拜耶和华。'),
('CUV', '诗篇', 19, 29, 3, '耶和华的声音发在水上；荣耀的神打雷，耶和华打雷在大水之上。'),
('CUV', '诗篇', 19, 29, 4, '耶和华的声音大有能力；耶和华的声音满有威严。'),
('CUV', '诗篇', 19, 29, 5, '耶和华的声音震破香柏树；耶和华震碎利巴嫩的香柏树。'),
('CUV', '诗篇', 19, 29, 6, '他也使之跳跃如牛犊，使利巴嫩和西连跳跃如野牛犊。'),
('CUV', '诗篇', 19, 29, 7, '耶和华的声音使火燄分岔。'),
('CUV', '诗篇', 19, 29, 8, '耶和华的声音震动旷野；耶和华震动加低斯的旷野。'),
('CUV', '诗篇', 19, 29, 9, '耶和华的声音惊动母鹿落胎，树木也脱落净光。凡在他殿中的，都称说他的荣耀。'),
('CUV', '诗篇', 19, 29, 10, '洪水泛滥之时，耶和华坐著为王；耶和华坐著为王，直到永远。'),
('CUV', '诗篇', 19, 29, 11, '耶和华必赐力量给他的百姓；耶和华必赐平安的福给他的百姓。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 30, 1, '（大卫在献殿的时候，作这诗歌。）耶和华啊，我要尊崇你，因为你曾提拔我，不叫仇敌向我夸耀。'),
('CUV', '诗篇', 19, 30, 2, '耶和华─我的神啊，我曾呼求你，你医治了我。'),
('CUV', '诗篇', 19, 30, 3, '耶和华啊，你曾把我的灵魂从阴间救上来，使我存活，不至于下坑。'),
('CUV', '诗篇', 19, 30, 4, '耶和华的圣民哪，你们要歌颂他，称赞他可记念的圣名。'),
('CUV', '诗篇', 19, 30, 5, '因为，他的怒气不过是转眼之间；他的恩典乃是一生之久。一宿虽然有哭泣，早晨便必欢呼。'),
('CUV', '诗篇', 19, 30, 6, '至于我，我凡事平顺便说：我永不动摇。'),
('CUV', '诗篇', 19, 30, 7, '耶和华啊，你曾施恩，叫我的江山稳固；你掩了面，我就惊惶。'),
('CUV', '诗篇', 19, 30, 8, '耶和华啊，我曾求告你；我向耶和华恳求，说：'),
('CUV', '诗篇', 19, 30, 9, '我被害流血，下到坑中，有甚么益处呢？尘土岂能称赞你，传说你的诚实么？'),
('CUV', '诗篇', 19, 30, 10, '耶和华啊，求你应允我，怜恤我！耶和华啊，求你帮助我！'),
('CUV', '诗篇', 19, 30, 11, '你已将我的哀哭变为跳舞，将我的麻衣脱去，给我披上喜乐，'),
('CUV', '诗篇', 19, 30, 12, '好叫我的灵（原文是荣耀）歌颂你，并不住声。耶和华─我的神啊，我要称谢你，直到永远！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 31, 1, '（大卫的诗，交与伶长。）耶和华啊，我投靠你；求你使我永不羞愧；凭你的公义搭救我！'),
('CUV', '诗篇', 19, 31, 2, '求你侧耳而听，快快救我！作我坚固的磐石，拯救我的保障！'),
('CUV', '诗篇', 19, 31, 3, '因为你是我的岩石，我的山寨；所以，求你为你名的缘故引导我，指点我。'),
('CUV', '诗篇', 19, 31, 4, '求你救我脱离人为我暗设的网罗，因为你是我的保障。'),
('CUV', '诗篇', 19, 31, 5, '我将我的灵魂交在你手里；耶和华诚实的神啊，你救赎了我。'),
('CUV', '诗篇', 19, 31, 6, '我恨恶那信奉虚无之神的人；我却倚靠耶和华。'),
('CUV', '诗篇', 19, 31, 7, '我要为你的慈爱高兴欢喜；因为你见过我的困苦，知道我心中的艰难。'),
('CUV', '诗篇', 19, 31, 8, '你未曾把我交在仇敌手里；你使我的脚站在宽阔之处。'),
('CUV', '诗篇', 19, 31, 9, '耶和华啊，求你怜恤我，因为我在急难之中；我的眼睛因忧愁而干瘪，连我的身心也不安舒。'),
('CUV', '诗篇', 19, 31, 10, '我的生命为愁苦所消耗；我的年岁为叹息所旷废。我的力量因我的罪孽衰败；我的骨头也枯干。'),
('CUV', '诗篇', 19, 31, 11, '我因一切敌人成了羞辱，在我的邻舍跟前更甚；那认识我的都惧怕我，在外头看见我的都躲避我。'),
('CUV', '诗篇', 19, 31, 12, '我被人忘记，如同死人，无人记念；我好像破碎的器皿。'),
('CUV', '诗篇', 19, 31, 13, '我听见了许多人的谗谤，四围都是惊吓；他们一同商议攻击我的时候，就图谋要害我的性命。'),
('CUV', '诗篇', 19, 31, 14, '耶和华啊，我仍旧倚靠你；我说：你是我的神。'),
('CUV', '诗篇', 19, 31, 15, '我终身的事在你手中；求你救我脱离仇敌的手和那些逼迫我的人。'),
('CUV', '诗篇', 19, 31, 16, '求你使你的脸光照仆人，凭你的慈爱拯救我。'),
('CUV', '诗篇', 19, 31, 17, '耶和华啊，求你叫我不致羞愧，因为我曾呼吁你；求你使恶人羞愧，使他们在阴间缄默无声。'),
('CUV', '诗篇', 19, 31, 18, '那撒谎的人逞骄傲轻慢，出狂妄的话攻击义人；愿他的嘴哑而无言。'),
('CUV', '诗篇', 19, 31, 19, '敬畏你、投靠你的人，你为他们所积存的，在世人面前所施行的恩惠是何等大呢！'),
('CUV', '诗篇', 19, 31, 20, '你必把他们藏在你面前的隐密处，免得遇见人的计谋；你必暗暗地保守他们在亭子里，免受口舌的争闹。'),
('CUV', '诗篇', 19, 31, 21, '耶和华是应当称颂的，因为他在坚固城里向我施展奇妙的慈爱。'),
('CUV', '诗篇', 19, 31, 22, '至于我，我曾急促地说：我从你眼前被隔绝。然而，我呼求你的时候，你仍听我恳求的声音。'),
('CUV', '诗篇', 19, 31, 23, '耶和华的圣民哪，你们都要爱他！耶和华保护诚实人，足足报应行事骄傲的人。'),
('CUV', '诗篇', 19, 31, 24, '凡仰望耶和华的人，你们都要壮胆，坚固你们的心！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 32, 1, '（大卫的训诲诗。）得赦免其过、遮盖其罪的，这人是有福的！'),
('CUV', '诗篇', 19, 32, 2, '凡心里没有诡诈、耶和华不算为有罪的，这人是有福的！'),
('CUV', '诗篇', 19, 32, 3, '我闭口不认罪的时候，因终日唉哼而骨头枯干。'),
('CUV', '诗篇', 19, 32, 4, '黑夜白日，你的手在我身上沉重；我的精液耗尽，如同夏天的干旱。（细拉）'),
('CUV', '诗篇', 19, 32, 5, '我向你陈明我的罪，不隐瞒我的恶。我说：我要向耶和华承认我的过犯，你就赦免我的罪恶。（细拉）'),
('CUV', '诗篇', 19, 32, 6, '为此，凡虔诚人都当趁你可寻找的时候祷告你；大水泛溢的时候，必不能到他那里。'),
('CUV', '诗篇', 19, 32, 7, '你是我藏身之处；你必保佑我脱离苦难，以得救的乐歌四面环绕我。（细拉）'),
('CUV', '诗篇', 19, 32, 8, '我要教导你，指示你当行的路；我要定睛在你身上劝戒你。'),
('CUV', '诗篇', 19, 32, 9, '你不可像那无知的骡马，必用嚼环辔头勒住他；不然，就不能驯服。'),
('CUV', '诗篇', 19, 32, 10, '恶人必多受苦楚；惟独倚靠耶和华的必有慈爱四面环绕他。'),
('CUV', '诗篇', 19, 32, 11, '你们义人应当靠耶和华欢喜快乐；你们心里正直的人都当欢呼。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 33, 1, '义人哪，你们应当靠耶和华欢乐；正直人的赞美是合宜的。'),
('CUV', '诗篇', 19, 33, 2, '你们应当弹琴称谢耶和华，用十弦瑟歌颂他。'),
('CUV', '诗篇', 19, 33, 3, '应当向他唱新歌，弹得巧妙，声音洪亮。'),
('CUV', '诗篇', 19, 33, 4, '因为耶和华的言语正直；凡他所做的尽都诚实。'),
('CUV', '诗篇', 19, 33, 5, '他喜爱仁义公平；遍地满了耶和华的慈爱。'),
('CUV', '诗篇', 19, 33, 6, '诸天藉耶和华的命而造；万象藉他口中的气而成。'),
('CUV', '诗篇', 19, 33, 7, '他聚集海水如垒，收藏深洋在库房。'),
('CUV', '诗篇', 19, 33, 8, '愿全地都敬畏耶和华！愿世上的居民都惧怕他！'),
('CUV', '诗篇', 19, 33, 9, '因为他说有，就有，命立，就立。'),
('CUV', '诗篇', 19, 33, 10, '耶和华使列国的筹算归于无有，使众民的思念无有功效。'),
('CUV', '诗篇', 19, 33, 11, '耶和华的筹算永远立定；他心中的思念万代常存。'),
('CUV', '诗篇', 19, 33, 12, '以耶和华为神的，那国是有福的！他所拣选为自己产业的，那民是有福的！'),
('CUV', '诗篇', 19, 33, 13, '耶和华从天上观看；他看见一切的世人。'),
('CUV', '诗篇', 19, 33, 14, '从他的居所往外察看地上一切的居民。'),
('CUV', '诗篇', 19, 33, 15, '他是那造成他们众人心的，留意他们一切作为的。'),
('CUV', '诗篇', 19, 33, 16, '君王不能因兵多得胜；勇士不能因力大得救。'),
('CUV', '诗篇', 19, 33, 17, '靠马得救是枉然的；马也不能因力大救人。'),
('CUV', '诗篇', 19, 33, 18, '耶和华的眼目看顾敬畏他的人和仰望他慈爱的人，'),
('CUV', '诗篇', 19, 33, 19, '要救他们的命脱离死亡，并使他们在饥荒中存活。'),
('CUV', '诗篇', 19, 33, 20, '我们的心向来等候耶和华；他是我们的帮助，我们的盾牌。'),
('CUV', '诗篇', 19, 33, 21, '我们的心必靠他欢喜，因为我们向来倚靠他的圣名。'),
('CUV', '诗篇', 19, 33, 22, '耶和华啊，求你照著我们所仰望你的，向我们施行慈爱！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 34, 1, '（大卫在亚比米勒面前装疯，被他赶出去，就作这诗。）我要时时称颂耶和华；赞美他的话必常在我口中。'),
('CUV', '诗篇', 19, 34, 2, '我的心必因耶和华夸耀；谦卑人听见就要喜乐。'),
('CUV', '诗篇', 19, 34, 3, '你们和我当称耶和华为大，一同高举他的名。'),
('CUV', '诗篇', 19, 34, 4, '我曾寻求耶和华，他就应允我，救我脱离了一切的恐惧。'),
('CUV', '诗篇', 19, 34, 5, '凡仰望他的，便有光荣；他们的脸必不蒙羞。'),
('CUV', '诗篇', 19, 34, 6, '我这困苦人呼求，耶和华便垂听，救我脱离一切患难。'),
('CUV', '诗篇', 19, 34, 7, '耶和华的使者在敬畏他的人四围安营，搭救他们。'),
('CUV', '诗篇', 19, 34, 8, '你们要尝尝主恩的滋味，便知道他是美善；投靠他的人有福了！'),
('CUV', '诗篇', 19, 34, 9, '耶和华的圣民哪，你们当敬畏他，因敬畏他的一无所缺。'),
('CUV', '诗篇', 19, 34, 10, '少壮狮子还缺食忍饿，但寻求耶和华的甚么好处都不缺。'),
('CUV', '诗篇', 19, 34, 11, '众弟子啊，你们当来听我的话！我要将敬畏耶和华的道教训你们。'),
('CUV', '诗篇', 19, 34, 12, '有何人喜好存活，爱慕长寿，得享美福，'),
('CUV', '诗篇', 19, 34, 13, '就要禁止舌头不出恶言，嘴唇不说诡诈的话。'),
('CUV', '诗篇', 19, 34, 14, '要离恶行善，寻求和睦，一心追赶。'),
('CUV', '诗篇', 19, 34, 15, '耶和华的眼目看顾义人；他的耳朵听他们的呼求。'),
('CUV', '诗篇', 19, 34, 16, '耶和华向行恶的人变脸，要从世上除灭他们的名号。'),
('CUV', '诗篇', 19, 34, 17, '义人呼求，耶和华听见了，便救他们脱离一切患难。'),
('CUV', '诗篇', 19, 34, 18, '耶和华靠近伤心的人，拯救灵性痛悔的人。'),
('CUV', '诗篇', 19, 34, 19, '义人多有苦难，但耶和华救他脱离这一切，'),
('CUV', '诗篇', 19, 34, 20, '又保全他一身的骨头，连一根也不折断。'),
('CUV', '诗篇', 19, 34, 21, '恶必害死恶人；恨恶义人的，必被定罪。'),
('CUV', '诗篇', 19, 34, 22, '耶和华救赎他仆人的灵魂；凡投靠他的，必不致定罪。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 35, 1, '（大卫的诗。）耶和华啊，与我相争的，求你与他们相争！与我相战的，求你与他们相战！'),
('CUV', '诗篇', 19, 35, 2, '拿著大小的盾牌，起来帮助我。'),
('CUV', '诗篇', 19, 35, 3, '抽出枪来，挡住那追赶我的；求你对我的灵魂说：我是拯救你的。'),
('CUV', '诗篇', 19, 35, 4, '愿那寻索我命的，蒙羞受辱！愿那谋害我的，退后羞愧！'),
('CUV', '诗篇', 19, 35, 5, '愿他们像风前的糠，有耶和华的使者赶逐他们。'),
('CUV', '诗篇', 19, 35, 6, '愿他们的道路又暗又滑，有耶和华的使者追赶他们。'),
('CUV', '诗篇', 19, 35, 7, '因他们无故地为我暗设网罗，无故地挖坑，要害我的性命。'),
('CUV', '诗篇', 19, 35, 8, '愿灾祸忽然临到他身上！愿他暗设的网缠住自己！愿他落在其中遭灾祸！'),
('CUV', '诗篇', 19, 35, 9, '我的心必靠耶和华快乐，靠他的救恩高兴。'),
('CUV', '诗篇', 19, 35, 10, '我的骨头都要说：耶和华啊，谁能像你救护困苦人脱离那比他强壮的，救护困苦穷乏人脱离那抢夺他的？'),
('CUV', '诗篇', 19, 35, 11, '凶恶的见证人起来，盘问我所不知道的事。'),
('CUV', '诗篇', 19, 35, 12, '他们向我以恶报善，使我的灵魂孤苦。'),
('CUV', '诗篇', 19, 35, 13, '至于我，当他们有病的时候，我便穿麻衣，禁食，刻苦己心；我所求的都归到自己的怀中。'),
('CUV', '诗篇', 19, 35, 14, '我这样行，好像他是我的朋友，我的弟兄；我屈身悲哀，如同人为母亲哀痛。'),
('CUV', '诗篇', 19, 35, 15, '我在患难中，他们却欢喜，大家聚集。我所不认识的那些下流人聚集攻击我；他们不住地把我撕裂。'),
('CUV', '诗篇', 19, 35, 16, '他们如同席上好嬉笑的狂妄人向我咬牙。'),
('CUV', '诗篇', 19, 35, 17, '主啊，你看著不理要到几时呢？求你救我的灵魂脱离他们的残害！救我的生命（生命：原文是独一者）脱离少壮狮子！'),
('CUV', '诗篇', 19, 35, 18, '我在大会中要称谢你，在众民中要赞美你。'),
('CUV', '诗篇', 19, 35, 19, '求你不容那无理与我为仇的向我夸耀！不容那无故恨我的向我挤眼！'),
('CUV', '诗篇', 19, 35, 20, '因为他们不说和平话，倒想出诡诈的言语害地上的安静人。'),
('CUV', '诗篇', 19, 35, 21, '他们大大张口攻击我，说：阿哈，阿哈，我们的眼已经看见了！'),
('CUV', '诗篇', 19, 35, 22, '耶和华啊，你已经看见了，求你不要闭口！主啊，求你不要远离我！'),
('CUV', '诗篇', 19, 35, 23, '我的神我的主啊，求你奋兴醒起，判清我的事，伸明我的冤！'),
('CUV', '诗篇', 19, 35, 24, '耶和华─我的神啊，求你按你的公义判断我，不容他们向我夸耀！'),
('CUV', '诗篇', 19, 35, 25, '不容他们心里说：阿哈，遂我们的心愿了！不容他们说：我们已经把他吞了！'),
('CUV', '诗篇', 19, 35, 26, '愿那喜欢我遭难的一同抱愧蒙羞！愿那向我妄自尊大的披惭愧，蒙羞辱！'),
('CUV', '诗篇', 19, 35, 27, '愿那喜悦我冤屈得伸的（冤屈得伸：原文是公义）欢呼快乐；愿他们常说：当尊耶和华为大！耶和华喜悦他的仆人平安。'),
('CUV', '诗篇', 19, 35, 28, '我的舌头要终日论说你的公义，时常赞美你。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 36, 1, '（耶和华的仆人大卫的诗，交与伶长。）恶人的罪过在他心里说：我眼中不怕神！'),
('CUV', '诗篇', 19, 36, 2, '他自夸自媚，以为他的罪孽终不显露，不被恨恶。'),
('CUV', '诗篇', 19, 36, 3, '他口中的言语尽是罪孽诡诈；他与智慧善行已经断绝。'),
('CUV', '诗篇', 19, 36, 4, '他在床上图谋罪孽，定意行不善的道，不憎恶恶事。'),
('CUV', '诗篇', 19, 36, 5, '耶和华啊，你的慈爱上及诸天；你的信实达到穹苍。'),
('CUV', '诗篇', 19, 36, 6, '你的公义好像高山；你的判断如同深渊。耶和华啊，人民、牲畜，你都救护。'),
('CUV', '诗篇', 19, 36, 7, '神啊，你的慈爱何其宝贵！世人投靠在你翅膀的荫下。'),
('CUV', '诗篇', 19, 36, 8, '他们必因你殿里的肥甘得以饱足；你也必叫他们喝你乐河的水。'),
('CUV', '诗篇', 19, 36, 9, '因为，在你那里有生命的源头；在你的光中，我们必得见光。'),
('CUV', '诗篇', 19, 36, 10, '愿你常施慈爱给认识你的人，常以公义待心里正直的人。'),
('CUV', '诗篇', 19, 36, 11, '不容骄傲人的脚践踏我；不容凶恶人的手赶逐我。'),
('CUV', '诗篇', 19, 36, 12, '在那里，作孽的人已经仆倒；他们被推倒，不能再起来。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 37, 1, '（大卫的诗。）不要为作恶的心怀不平，也不要向那行不义的生出嫉妒。'),
('CUV', '诗篇', 19, 37, 2, '因为他们如草快被割下，又如青菜快要枯干。'),
('CUV', '诗篇', 19, 37, 3, '你当倚靠耶和华而行善，住在地上，以他的信实为粮；'),
('CUV', '诗篇', 19, 37, 4, '又要以耶和华为乐，他就将你心里所求的赐给你。'),
('CUV', '诗篇', 19, 37, 5, '当将你的事交托耶和华，并倚靠他，他就必成全。'),
('CUV', '诗篇', 19, 37, 6, '他要使你的公义如光发出，使你的公平明如正午。'),
('CUV', '诗篇', 19, 37, 7, '你当默然倚靠耶和华，耐性等候他；不要因那道路通达的和那恶谋成就的心怀不平。'),
('CUV', '诗篇', 19, 37, 8, '当止住怒气，离弃忿怒；不要心怀不平，以致作恶。'),
('CUV', '诗篇', 19, 37, 9, '因为作恶的必被剪除；惟有等候耶和华的必承受地土。'),
('CUV', '诗篇', 19, 37, 10, '还有片时，恶人要归于无有；你就是细察他的住处也要归于无有。'),
('CUV', '诗篇', 19, 37, 11, '但谦卑人必承受地土，以丰盛的平安为乐。'),
('CUV', '诗篇', 19, 37, 12, '恶人设谋害义人，又向他咬牙。'),
('CUV', '诗篇', 19, 37, 13, '主要笑他，因见他受罚的日子将要来到。'),
('CUV', '诗篇', 19, 37, 14, '恶人已经弓上弦，刀出鞘，要打倒困苦穷乏的人，要杀害行动正直的人。'),
('CUV', '诗篇', 19, 37, 15, '他们的刀必刺入自己的心；他们的弓必被折断。'),
('CUV', '诗篇', 19, 37, 16, '一个义人所有的虽少，强过许多恶人的富余。'),
('CUV', '诗篇', 19, 37, 17, '因为恶人的膀臂必被折断；但耶和华是扶持义人。'),
('CUV', '诗篇', 19, 37, 18, '耶和华知道完全人的日子；他们的产业要存到永远。'),
('CUV', '诗篇', 19, 37, 19, '他们在急难的时候不致羞愧，在饥荒的日子必得饱足。'),
('CUV', '诗篇', 19, 37, 20, '恶人却要灭亡。耶和华的仇敌要像羊羔的脂油（或译：像草地的华美）；他们要消灭，要如烟消灭。'),
('CUV', '诗篇', 19, 37, 21, '恶人借贷而不偿还；义人却恩待人，并且施舍。'),
('CUV', '诗篇', 19, 37, 22, '蒙耶和华赐福的必承受地土；被他咒诅的必被剪除。'),
('CUV', '诗篇', 19, 37, 23, '义人的脚步被耶和华立定；他的道路，耶和华也喜爱。'),
('CUV', '诗篇', 19, 37, 24, '他虽失脚也不至全身仆倒，因为耶和华用手搀扶他（或译：搀扶他的手）。'),
('CUV', '诗篇', 19, 37, 25, '我从前年幼，现在年老，却未见过义人被弃，也未见过他的后裔讨饭。'),
('CUV', '诗篇', 19, 37, 26, '他终日恩待人，借给人；他的后裔也蒙福！'),
('CUV', '诗篇', 19, 37, 27, '你当离恶行善，就可永远安居。'),
('CUV', '诗篇', 19, 37, 28, '因为，耶和华喜爱公平，不撇弃他的圣民；他们永蒙保佑，但恶人的后裔必被剪除。'),
('CUV', '诗篇', 19, 37, 29, '义人必承受地土，永居其上。'),
('CUV', '诗篇', 19, 37, 30, '义人的口谈论智慧；他的舌头讲说公平。'),
('CUV', '诗篇', 19, 37, 31, '神的律法在他心里；他的脚总不滑跌。'),
('CUV', '诗篇', 19, 37, 32, '恶人窥探义人，想要杀他。'),
('CUV', '诗篇', 19, 37, 33, '耶和华必不撇他在恶人手中；当审判的时候，也不定他的罪。'),
('CUV', '诗篇', 19, 37, 34, '你当等候耶和华，遵守他的道，他就抬举你，使你承受地土；恶人被剪除的时候，你必看见。'),
('CUV', '诗篇', 19, 37, 35, '我见过恶人大有势力，好像一根青翠树在本土生发。'),
('CUV', '诗篇', 19, 37, 36, '有人从那里经过，不料，他没有了；我也寻找他，却寻不著。'),
('CUV', '诗篇', 19, 37, 37, '你要细察那完全人，观看那正直人，因为和平人有好结局。'),
('CUV', '诗篇', 19, 37, 38, '至于犯法的人，必一同灭绝；恶人终必剪除。'),
('CUV', '诗篇', 19, 37, 39, '但义人得救是由于耶和华；他在患难时作他们的营寨。'),
('CUV', '诗篇', 19, 37, 40, '耶和华帮助他们，解救他们；他解救他们脱离恶人，把他们救出来，因为他们投靠他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 38, 1, '（大卫的记念诗。）耶和华啊，求你不要在怒中责备我，不要在烈怒中惩罚我！'),
('CUV', '诗篇', 19, 38, 2, '因为，你的箭射入我身；你的手压住我。'),
('CUV', '诗篇', 19, 38, 3, '因你的恼怒，我的肉无一完全；因我的罪过，我的骨头也不安宁。'),
('CUV', '诗篇', 19, 38, 4, '我的罪孽高过我的头，如同重担叫我担当不起。'),
('CUV', '诗篇', 19, 38, 5, '因我的愚昧，我的伤发臭流脓。'),
('CUV', '诗篇', 19, 38, 6, '我疼痛，大大拳曲，终日哀痛。'),
('CUV', '诗篇', 19, 38, 7, '我满腰是火；我的肉无一完全。'),
('CUV', '诗篇', 19, 38, 8, '我被压伤，身体疲倦；因心里不安，我就唉哼。'),
('CUV', '诗篇', 19, 38, 9, '主啊，我的心愿都在你面前；我的叹息不向你隐瞒。'),
('CUV', '诗篇', 19, 38, 10, '我心跳动，我力衰微，连我眼中的光也没有了。'),
('CUV', '诗篇', 19, 38, 11, '我的良朋密友因我的灾病都躲在旁边站著；我的亲戚本家也远远地站立。'),
('CUV', '诗篇', 19, 38, 12, '那寻索我命的设下网罗；那想要害我的口出恶言，终日思想诡计。'),
('CUV', '诗篇', 19, 38, 13, '但我如聋子不听，像哑巴不开口。'),
('CUV', '诗篇', 19, 38, 14, '我如不听见的人，口中没有回话。'),
('CUV', '诗篇', 19, 38, 15, '耶和华啊，我仰望你！主─我的神啊，你必应允我！'),
('CUV', '诗篇', 19, 38, 16, '我曾说：恐怕他们向我夸耀；我失脚的时候，他们向我夸大。'),
('CUV', '诗篇', 19, 38, 17, '我几乎跌倒；我的痛苦常在我面前。'),
('CUV', '诗篇', 19, 38, 18, '我要承认我的罪孽；我要因我的罪忧愁。'),
('CUV', '诗篇', 19, 38, 19, '但我的仇敌又活泼又强壮，无理恨我的增多了。'),
('CUV', '诗篇', 19, 38, 20, '以恶报善的与我作对，因我是追求良善。'),
('CUV', '诗篇', 19, 38, 21, '耶和华啊，求你不要撇弃我！我的神啊，求你不要远离我！'),
('CUV', '诗篇', 19, 38, 22, '拯救我的主啊，求你快快帮助我！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 39, 1, '（大卫的诗，交与伶长耶杜顿。）我曾说：我要谨慎我的言行，免得我舌头犯罪；恶人在我面前的时候，我要用嚼环勒住我的口。'),
('CUV', '诗篇', 19, 39, 2, '我默然无声，连好话也不出口；我的愁苦就发动了，'),
('CUV', '诗篇', 19, 39, 3, '我的心在我里面发热。我默想的时候，火就烧起，我便用舌头说话。'),
('CUV', '诗篇', 19, 39, 4, '耶和华啊，求你叫我晓得我身之终！我的寿数几何？叫我知道我的生命不长！'),
('CUV', '诗篇', 19, 39, 5, '你使我的年日窄如手掌；我一生的年数，在你面前如同无有。各人最稳妥的时候，真是全然虚幻。（细拉）'),
('CUV', '诗篇', 19, 39, 6, '世人行动实系幻影。他们忙乱，真是枉然；积蓄财宝，不知将来有谁收取。'),
('CUV', '诗篇', 19, 39, 7, '主啊，如今我等甚么呢？我的指望在乎你！'),
('CUV', '诗篇', 19, 39, 8, '求你救我脱离一切的过犯，不要使我受愚顽人的羞辱。'),
('CUV', '诗篇', 19, 39, 9, '因我所遭遇的是出于你，我就默然不语。'),
('CUV', '诗篇', 19, 39, 10, '求你把你的责罚从我身上免去；因你手的责打，我便消灭。'),
('CUV', '诗篇', 19, 39, 11, '你因人的罪恶惩罚他的时候，叫他的笑容（的笑容：或译所喜爱的）消灭，如衣被虫所咬。世人真是虚幻！（细拉）'),
('CUV', '诗篇', 19, 39, 12, '耶和华啊，求你听我的祷告，留心听我的呼求！我流泪，求你不要静默无声！因为我在你面前是客旅，是寄居的，像我列祖一般。'),
('CUV', '诗篇', 19, 39, 13, '求你宽容我，使我在去而不返之先可以力量复原。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 40, 1, '（大卫的诗，交与伶长。）我曾耐性等候耶和华；他垂听我的呼求。'),
('CUV', '诗篇', 19, 40, 2, '他从祸坑里，从淤泥中，把我拉上来，使我的脚立在磐石上，使我脚步稳当。'),
('CUV', '诗篇', 19, 40, 3, '他使我口唱新歌，就是赞美我们神的话。许多人必看见而惧怕，并要倚靠耶和华。'),
('CUV', '诗篇', 19, 40, 4, '那倚靠耶和华、不理会狂傲和偏向虚假之辈的，这人便为有福！'),
('CUV', '诗篇', 19, 40, 5, '耶和华─我的神啊，你所行的奇事，并你向我们所怀的意念甚多，不能向你陈明。若要陈明，其事不可胜数。'),
('CUV', '诗篇', 19, 40, 6, '祭物和礼物，你不喜悦；你已经开通我的耳朵。燔祭和赎罪祭非你所要。'),
('CUV', '诗篇', 19, 40, 7, '那时我说：看哪，我来了！我的事在经卷上已经记载了。'),
('CUV', '诗篇', 19, 40, 8, '我的神啊，我乐意照你的旨意行；你的律法在我心里。'),
('CUV', '诗篇', 19, 40, 9, '我在大会中宣传公义的佳音；我必不止住我的嘴唇。耶和华啊，这是你所知道的。'),
('CUV', '诗篇', 19, 40, 10, '我未曾把你的公义藏在心里；我已陈明你的信实和你的救恩；我在大会中未曾隐瞒你的慈爱和诚实。'),
('CUV', '诗篇', 19, 40, 11, '耶和华啊，求你不要向我止住你的慈悲！愿你的慈爱和诚实常常保佑我！'),
('CUV', '诗篇', 19, 40, 12, '因有无数的祸患围困我，我的罪孽追上了我，使我不能昂首；这罪孽比我的头发还多，我就心寒胆战。'),
('CUV', '诗篇', 19, 40, 13, '耶和华啊，求你开恩搭救我！耶和华啊，求你速速帮助我！'),
('CUV', '诗篇', 19, 40, 14, '愿那些寻找我、要灭我命的，一同抱愧蒙羞！愿那些喜悦我受害的，退后受辱！'),
('CUV', '诗篇', 19, 40, 15, '愿那些对我说阿哈、阿哈的，因羞愧而败亡！'),
('CUV', '诗篇', 19, 40, 16, '愿一切寻求你的，因你高兴欢喜！愿那些喜爱你救恩的，常说：当尊耶和华为大！'),
('CUV', '诗篇', 19, 40, 17, '但我是困苦穷乏的，主仍顾念我；你是帮助我的，搭救我的。神啊，求你不要耽延！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 41, 1, '（大卫的诗，交与伶长。）眷顾贫穷的有福了！他遭难的日子，耶和华必搭救他。'),
('CUV', '诗篇', 19, 41, 2, '耶和华必保全他，使他存活；他必在地上享福。求你不要把他交给仇敌，遂其所愿。'),
('CUV', '诗篇', 19, 41, 3, '他病重在榻，耶和华必扶持他；他在病中，你必给他铺床。'),
('CUV', '诗篇', 19, 41, 4, '我曾说：耶和华啊，求你怜恤我，医治我！因为我得罪了你。'),
('CUV', '诗篇', 19, 41, 5, '我的仇敌用恶言议论我说：他几时死，他的名才灭亡呢？'),
('CUV', '诗篇', 19, 41, 6, '他来看我就说假话；他心存奸恶，走到外边才说出来。'),
('CUV', '诗篇', 19, 41, 7, '一切恨我的，都交头接耳地议论我；他们设计要害我。'),
('CUV', '诗篇', 19, 41, 8, '他们说：有怪病贴在他身上；他已躺卧，必不能再起来。'),
('CUV', '诗篇', 19, 41, 9, '连我知己的朋友，我所倚靠、吃过我饭的也用脚踢我。'),
('CUV', '诗篇', 19, 41, 10, '耶和华啊，求你怜恤我，使我起来，好报复他们！'),
('CUV', '诗篇', 19, 41, 11, '因我的仇敌不得向我夸胜，我从此便知道你喜爱我。'),
('CUV', '诗篇', 19, 41, 12, '你因我纯正就扶持我，使我永远站在你的面前。'),
('CUV', '诗篇', 19, 41, 13, '耶和华─以色列的神是应当称颂的，从亘古直到永远。阿们！阿们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 42, 1, '（可拉后裔的训诲诗，交与伶长。）神啊，我的心切慕你，如鹿切慕溪水。'),
('CUV', '诗篇', 19, 42, 2, '我的心渴想神，就是永生神；我几时得朝见神呢？'),
('CUV', '诗篇', 19, 42, 3, '我昼夜以眼泪当饮食；人不住地对我说：你的神在哪里呢？'),
('CUV', '诗篇', 19, 42, 4, '我从前与众人同往，用欢呼称赞的声音领他们到神的殿里，大家守节。我追想这些事，我的心极其悲伤。'),
('CUV', '诗篇', 19, 42, 5, '我的心哪，你为何忧闷？为何在我里面烦躁？应当仰望神，因他笑脸帮助我；我还要称赞他。'),
('CUV', '诗篇', 19, 42, 6, '我的神啊，我的心在我里面忧闷，所以我从约但地，从黑门岭，从米萨山记念你。'),
('CUV', '诗篇', 19, 42, 7, '你的瀑布发声，深渊就与深渊响应；你的波浪洪涛漫过我身。'),
('CUV', '诗篇', 19, 42, 8, '白昼，耶和华必向我施慈爱；黑夜，我要歌颂祷告赐我生命的神。'),
('CUV', '诗篇', 19, 42, 9, '我要对神─我的磐石说：你为何忘记我呢？我为何因仇敌的欺压时常哀痛呢？'),
('CUV', '诗篇', 19, 42, 10, '我的敌人辱骂我，好像打碎我的骨头，不住地对我说：你的神在哪里呢？'),
('CUV', '诗篇', 19, 42, 11, '我的心哪，你为何忧闷？为何在我里面烦躁？应当仰望神，因我还要称赞他。他是我脸上的光荣（原文是帮助），是我的神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 43, 1, '神啊，求你伸我的冤，向不虔诚的国为我辨屈；求你救我脱离诡诈不义的人。'),
('CUV', '诗篇', 19, 43, 2, '因为你是赐我力量的神，为何丢弃我呢？我为何因仇敌的欺压时常哀痛呢？'),
('CUV', '诗篇', 19, 43, 3, '求你发出你的亮光和真实，好引导我，带我到你的圣山，到你的居所！'),
('CUV', '诗篇', 19, 43, 4, '我就走到神的祭坛，到我最喜乐的神那里。神啊，我的神，我要弹琴称赞你！'),
('CUV', '诗篇', 19, 43, 5, '我的心哪，你为何忧闷？为何在我里面烦躁？应当仰望神，因我还要称赞他。他是我脸上的光荣（原文是帮助），是我的神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 44, 1, '（可拉后裔的训诲诗，交与伶长。）神啊，你在古时，我们列祖的日子所行的事，我们亲耳听见了；我们的列祖也给我们述说过。'),
('CUV', '诗篇', 19, 44, 2, '你曾用手赶出外邦人，却栽培了我们列祖；你苦待列邦，却叫我们列祖发达。'),
('CUV', '诗篇', 19, 44, 3, '因为他们不是靠自己的刀剑得地土，也不是靠自己的膀臂得胜，乃是靠你的右手、你的膀臂，和你脸上的亮光，因为你喜悦他们。'),
('CUV', '诗篇', 19, 44, 4, '神啊，你是我的王；求你出令使雅各得胜。'),
('CUV', '诗篇', 19, 44, 5, '我们靠你要推倒我们的敌人，靠你的名要践踏那起来攻击我们的人。'),
('CUV', '诗篇', 19, 44, 6, '因为，我必不靠我的弓；我的刀也不能使我得胜。'),
('CUV', '诗篇', 19, 44, 7, '惟你救了我们脱离敌人，使恨我们的人羞愧。'),
('CUV', '诗篇', 19, 44, 8, '我们终日因神夸耀，还要永远称谢你的名。（细拉）'),
('CUV', '诗篇', 19, 44, 9, '但如今你丢弃了我们，使我们受辱，不和我们的军兵同去。'),
('CUV', '诗篇', 19, 44, 10, '你使我们向敌人转身退后；那恨我们的人任意抢夺。'),
('CUV', '诗篇', 19, 44, 11, '你使我们当作快要被吃的羊，把我们分散在列邦中。'),
('CUV', '诗篇', 19, 44, 12, '你卖了你的子民也不赚利，所得的价值并不加添你的资财。'),
('CUV', '诗篇', 19, 44, 13, '你使我们受邻国的羞辱，被四围的人嗤笑讥刺。'),
('CUV', '诗篇', 19, 44, 14, '你使我们在列邦中作了笑谈，使众民向我们摇头。'),
('CUV', '诗篇', 19, 44, 15, '我的凌辱终日在我面前，我脸上的羞愧将我遮蔽，'),
('CUV', '诗篇', 19, 44, 16, '都因那辱骂毁谤人的声音，又因仇敌和报仇人的缘故。'),
('CUV', '诗篇', 19, 44, 17, '这都临到我们身上，我们却没有忘记你，也没有违背你的约。'),
('CUV', '诗篇', 19, 44, 18, '我们的心没有退后；我们的脚也没有偏离你的路。'),
('CUV', '诗篇', 19, 44, 19, '你在野狗之处压伤我们，用死荫遮蔽我们。'),
('CUV', '诗篇', 19, 44, 20, '倘若我们忘了神的名，或向别神举手，'),
('CUV', '诗篇', 19, 44, 21, '神岂不鉴察这事么？因为他晓得人心里的隐秘。'),
('CUV', '诗篇', 19, 44, 22, '我们为你的缘故终日被杀；人看我们如将宰的羊。'),
('CUV', '诗篇', 19, 44, 23, '主啊，求你睡醒，为何尽睡呢？求你兴起，不要永远丢弃我们！'),
('CUV', '诗篇', 19, 44, 24, '你为何掩面，不顾我们所遭的苦难和所受的欺压？'),
('CUV', '诗篇', 19, 44, 25, '我们的性命伏于尘土；我们的肚腹紧贴地面。'),
('CUV', '诗篇', 19, 44, 26, '求你起来帮助我们！凭你的慈爱救赎我们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 45, 1, '（可拉后裔的训诲诗，又是爱慕歌，交与伶长。调用百合花。）我心里涌出美辞；我论到我为王做的事，我的舌头是快手笔。'),
('CUV', '诗篇', 19, 45, 2, '你比世人更美；在你嘴里满有恩惠；所以神赐福给你，直到永远。'),
('CUV', '诗篇', 19, 45, 3, '大能者啊，愿你腰间佩刀，大有荣耀和威严！'),
('CUV', '诗篇', 19, 45, 4, '为真理、谦卑、公义赫然坐车前往，无不得胜；你的右手必显明可畏的事。'),
('CUV', '诗篇', 19, 45, 5, '你的箭锋快，射中王敌之心；万民仆倒在你以下。'),
('CUV', '诗篇', 19, 45, 6, '神啊，你的宝座是永永远远的；你的国权是正直的。'),
('CUV', '诗篇', 19, 45, 7, '你喜爱公义，恨恶罪恶；所以神─就是你的神─用喜乐油膏你，胜过膏你的同伴。'),
('CUV', '诗篇', 19, 45, 8, '你的衣服都有没药、沉香、肉桂的香气；象牙宫中有丝弦乐器的声音使你欢喜。'),
('CUV', '诗篇', 19, 45, 9, '有君王的女儿在你尊贵妇女之中；王后佩戴俄斐金饰站在你右边。'),
('CUV', '诗篇', 19, 45, 10, '女子啊，你要听，要想，要侧耳而听！不要记念你的民和你的父家，'),
('CUV', '诗篇', 19, 45, 11, '王就羡慕你的美貌；因为他是你的主，你当敬拜他。'),
('CUV', '诗篇', 19, 45, 12, '推罗的民（原文是女子）必来送礼；民中的富足人也必向你求恩。'),
('CUV', '诗篇', 19, 45, 13, '王女在宫里极其荣华；他的衣服是用金线绣的。'),
('CUV', '诗篇', 19, 45, 14, '他要穿锦绣的衣服，被引到王前；随从他的陪伴童女也要被带到你面前。'),
('CUV', '诗篇', 19, 45, 15, '他们要欢喜快乐被引导；他们要进入王宫。'),
('CUV', '诗篇', 19, 45, 16, '你的子孙要接续你的列祖；你要立他们在全地作王。'),
('CUV', '诗篇', 19, 45, 17, '我必叫你的名被万代记念，所以万民要永永远远称谢你。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 46, 1, '（可拉后裔的诗歌，交与伶长。调用女音。）神是我们的避难所，是我们的力量，是我们在患难中随时的帮助。'),
('CUV', '诗篇', 19, 46, 2, '所以，地虽改变，山虽摇动到海心，'),
('CUV', '诗篇', 19, 46, 3, '其中的水虽匉訇翻腾，山虽因海涨而战抖，我们也不害怕。（细拉）'),
('CUV', '诗篇', 19, 46, 4, '有一道河，这河的分使神的城欢喜；这城就是至高者居住的圣所。'),
('CUV', '诗篇', 19, 46, 5, '神在其中，城必不动摇；到天一亮，神必帮助这城。'),
('CUV', '诗篇', 19, 46, 6, '外邦喧嚷，列国动摇；神发声，地便镕化。'),
('CUV', '诗篇', 19, 46, 7, '万军之耶和华与我们同在；雅各的神是我们的避难所！（细拉）'),
('CUV', '诗篇', 19, 46, 8, '你们来看耶和华的作为，看他使地怎样荒凉。'),
('CUV', '诗篇', 19, 46, 9, '他止息刀兵，直到地极；他折弓、断枪，把战车焚烧在火中。'),
('CUV', '诗篇', 19, 46, 10, '你们要休息，要知道我是神！我必在外邦中被尊崇，在遍地上也被尊崇。'),
('CUV', '诗篇', 19, 46, 11, '万军之耶和华与我们同在；雅各的神是我们的避难所！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 47, 1, '（可拉后裔的诗，交与伶长。）万民哪，你们都要拍掌！要用夸胜的声音向神呼喊！'),
('CUV', '诗篇', 19, 47, 2, '因为耶和华至高者是可畏的；他是治理全地的大君王。'),
('CUV', '诗篇', 19, 47, 3, '他叫万民服在我们以下，又叫列邦服在我们脚下。'),
('CUV', '诗篇', 19, 47, 4, '他为我们选择产业，就是他所爱之雅各的荣耀。（细拉）'),
('CUV', '诗篇', 19, 47, 5, '神上升，有喊声相送；耶和华上升，有角声相送。'),
('CUV', '诗篇', 19, 47, 6, '你们要向神歌颂，歌颂！向我们王歌颂，歌颂！'),
('CUV', '诗篇', 19, 47, 7, '因为神是全地的王；你们要用悟性歌颂。'),
('CUV', '诗篇', 19, 47, 8, '神作王治理万国；神坐在他的圣宝座上。'),
('CUV', '诗篇', 19, 47, 9, '列邦的君王聚集要作亚伯拉罕之神的民。因为世界的盾牌是属神的；他为至高！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 48, 1, '（可拉后裔的诗歌。）耶和华本为大！在我们神的城中，在他的圣山上，该受大赞美。'),
('CUV', '诗篇', 19, 48, 2, '锡安山─大君王的城，在北面居高华美，为全地所喜悦。'),
('CUV', '诗篇', 19, 48, 3, '神在其宫中，自显为避难所。'),
('CUV', '诗篇', 19, 48, 4, '看哪，众王会合，一同经过。'),
('CUV', '诗篇', 19, 48, 5, '他们见了这城就惊奇丧胆，急忙逃跑。'),
('CUV', '诗篇', 19, 48, 6, '他们在那里被战兢疼痛抓住，好像产难的妇人一样。'),
('CUV', '诗篇', 19, 48, 7, '神啊，你用东风打破他施的船只。'),
('CUV', '诗篇', 19, 48, 8, '我们在万军之耶和华的城中─就是我们神的城中─所看见的，正如我们所听见的。神必坚立这城，直到永远。（细拉）'),
('CUV', '诗篇', 19, 48, 9, '神啊，我们在你的殿中想念你的慈爱。'),
('CUV', '诗篇', 19, 48, 10, '神啊，你受的赞美正与你的名相称，直到地极！你的右手满了公义。'),
('CUV', '诗篇', 19, 48, 11, '因你的判断，锡安山应当欢喜，犹大的城邑（原文是女子）应当快乐。'),
('CUV', '诗篇', 19, 48, 12, '你们当周游锡安，四围旋绕，数点城楼，'),
('CUV', '诗篇', 19, 48, 13, '细看他的外郭，察看他的宫殿，为要传说到后代。'),
('CUV', '诗篇', 19, 48, 14, '因为这神永永远远为我们的神；他必作我们引路的，直到死时。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 49, 1, '（可拉后裔的诗，交与伶长。）万民哪，你们都当听这话！世上一切的居民，'),
('CUV', '诗篇', 19, 49, 2, '无论上流下流，富足贫穷，都当留心听！'),
('CUV', '诗篇', 19, 49, 3, '我口要说智慧的言语；我心要想通达的道理。'),
('CUV', '诗篇', 19, 49, 4, '我要侧耳听比喻，用琴解谜语。'),
('CUV', '诗篇', 19, 49, 5, '在患难的日子，奸恶随我脚跟，四面环绕我，我何必惧怕？'),
('CUV', '诗篇', 19, 49, 6, '那些倚仗财货自夸钱财多的人，'),
('CUV', '诗篇', 19, 49, 7, '一个也无法赎自己的弟兄，也不能替他将赎价给神，'),
('CUV', '诗篇', 19, 49, 8, '叫他长远活著，不见朽坏；因为赎他生命的价值极贵，只可永远罢休。'),
('CUV', '诗篇', 19, 49, 9, 'a'),
('CUV', '诗篇', 19, 49, 10, '他必见智慧人死，又见愚顽人和畜类人一同灭亡，将他们的财货留给别人。'),
('CUV', '诗篇', 19, 49, 11, '他们心里思想：他们的家室必永存，住宅必留到万代；他们以自己的名称自己的地。'),
('CUV', '诗篇', 19, 49, 12, '但人居尊贵中不能长久，如同死亡的畜类一样。'),
('CUV', '诗篇', 19, 49, 13, '他们行的这道本为自己的愚昧；但他们以后的人还佩服他们的话语。（细拉）'),
('CUV', '诗篇', 19, 49, 14, '他们如同羊群派定下阴间；死亡必作他们的牧者。到了早晨，正直人必管辖他们；他们的美容必被阴间所灭，以致无处可存。'),
('CUV', '诗篇', 19, 49, 15, '只是神必救赎我的灵魂脱离阴间的权柄，因他必收纳我。（细拉）'),
('CUV', '诗篇', 19, 49, 16, '见人发财、家室增荣的时候，你不要惧怕；'),
('CUV', '诗篇', 19, 49, 17, '因为，他死的时候甚么也不能带去；他的荣耀不能随他下去。'),
('CUV', '诗篇', 19, 49, 18, '他活著的时候，虽然自夸为有福（你若利己，人必夸奖你）；'),
('CUV', '诗篇', 19, 49, 19, '他仍必归到他历代的祖宗那里，永不见光。'),
('CUV', '诗篇', 19, 49, 20, '人在尊贵中而不醒悟，就如死亡的畜类一样。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 50, 1, '（亚萨的诗。）大能者神─耶和华已经发言招呼天下，从日出之地到日落之处。'),
('CUV', '诗篇', 19, 50, 2, '从全美的锡安中，神已经发光了。'),
('CUV', '诗篇', 19, 50, 3, '我们的神要来，决不闭口。有烈火在他面前吞灭；有暴风在他四围大刮。'),
('CUV', '诗篇', 19, 50, 4, '他招呼上天下地，为要审判他的民，'),
('CUV', '诗篇', 19, 50, 5, '说：招聚我的圣民到我这里来，就是那些用祭物与我立约的人。'),
('CUV', '诗篇', 19, 50, 6, '诸天必表明他的公义，因为神是施行审判的。（细拉）'),
('CUV', '诗篇', 19, 50, 7, '我的民哪，你们当听我的话！以色列啊，我要劝戒你；我是神，是你的神！'),
('CUV', '诗篇', 19, 50, 8, '我并不因你的祭物责备你；你的燔祭常在我面前。'),
('CUV', '诗篇', 19, 50, 9, '我不从你家中取公牛，也不从你圈内取山羊；'),
('CUV', '诗篇', 19, 50, 10, '因为，树林中的百兽是我的，千山上的牲畜也是我的。'),
('CUV', '诗篇', 19, 50, 11, '山中的飞鸟，我都知道；野地的走兽也都属我。'),
('CUV', '诗篇', 19, 50, 12, '我若是饥饿，我不用告诉你，因为世界和其中所充满的都是我的。'),
('CUV', '诗篇', 19, 50, 13, '我岂吃公牛的肉呢？我岂喝山羊的血呢？'),
('CUV', '诗篇', 19, 50, 14, '你们要以感谢为祭献与神，又要向至高者还你的愿，'),
('CUV', '诗篇', 19, 50, 15, '并要在患难之日求告我；我必搭救你，你也要荣耀我。'),
('CUV', '诗篇', 19, 50, 16, '但神对恶人说：你怎敢传说我的律例，口中提到我的约呢？'),
('CUV', '诗篇', 19, 50, 17, '其实你恨恶管教，将我的言语丢在背后。'),
('CUV', '诗篇', 19, 50, 18, '你见了盗贼就乐意与他同伙，又与行奸淫的人一同有分。'),
('CUV', '诗篇', 19, 50, 19, '你口任说恶言；你舌编造诡诈。'),
('CUV', '诗篇', 19, 50, 20, '你坐著毁谤你的兄弟，谗毁你亲母的儿子。'),
('CUV', '诗篇', 19, 50, 21, '你行了这些事，我还闭口不言，你想我恰和你一样；其实我要责备你，将这些事摆在你眼前。'),
('CUV', '诗篇', 19, 50, 22, '你们忘记神的，要思想这事，免得我把你们撕碎，无人搭救。'),
('CUV', '诗篇', 19, 50, 23, '凡以感谢献上为祭的便是荣耀我；那按正路而行的，我必使他得著我的救恩。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 51, 1, '（大卫与拔示巴同室以后，先知拿单来见他；他作这诗，交与伶长。）神啊，求你按你的慈爱怜恤我！按你丰盛的慈悲涂抹我的过犯！'),
('CUV', '诗篇', 19, 51, 2, '求你将我的罪孽洗除净尽，并洁除我的罪！'),
('CUV', '诗篇', 19, 51, 3, '因为，我知道我的过犯；我的罪常在我面前。'),
('CUV', '诗篇', 19, 51, 4, '我向你犯罪，惟独得罪了你；在你眼前行了这恶，以致你责备我的时候显为公义，判断我的时候显为清正。'),
('CUV', '诗篇', 19, 51, 5, '我是在罪孽里生的，在我母亲怀胎的时候就有了罪。'),
('CUV', '诗篇', 19, 51, 6, '你所喜爱的是内里诚实；你在我隐密处，必使我得智慧。'),
('CUV', '诗篇', 19, 51, 7, '求你用牛膝草洁净我，我就干净；求你洗涤我，我就比雪更白。'),
('CUV', '诗篇', 19, 51, 8, '求你使我得听欢喜快乐的声音，使你所压伤的骨头可以踊跃。'),
('CUV', '诗篇', 19, 51, 9, '求你掩面不看我的罪，涂抹我一切的罪孽。'),
('CUV', '诗篇', 19, 51, 10, '神啊，求你为我造清洁的心，使我里面重新有正直（或译：坚定）的灵。'),
('CUV', '诗篇', 19, 51, 11, '不要丢弃我，使我离开你的面；不要从我收回你的圣灵。'),
('CUV', '诗篇', 19, 51, 12, '求你使我仍得救恩之乐，赐我乐意的灵扶持我，'),
('CUV', '诗篇', 19, 51, 13, '我就把你的道指教有过犯的人，罪人必归顺你。'),
('CUV', '诗篇', 19, 51, 14, '神啊，你是拯救我的神；求你救我脱离流人血的罪！我的舌头就高声歌唱你的公义。'),
('CUV', '诗篇', 19, 51, 15, '主啊，求你使我嘴唇张开，我的口便传扬赞美你的话！'),
('CUV', '诗篇', 19, 51, 16, '你本不喜爱祭物，若喜爱，我就献上；燔祭，你也不喜悦。'),
('CUV', '诗篇', 19, 51, 17, '神所要的祭就是忧伤的灵；神啊，忧伤痛悔的心，你必不轻看。'),
('CUV', '诗篇', 19, 51, 18, '求你随你的美意善待锡安，建造耶路撒冷的城墙。'),
('CUV', '诗篇', 19, 51, 19, '那时，你必喜爱公义的祭和燔祭并全牲的燔祭；那时，人必将公牛献在你坛上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 52, 1, '（以东人多益来告诉扫罗说：大卫到了亚希米勒家。那时，大卫作这训诲诗，交与伶长。）勇士啊，你为何以作恶自夸？神的慈爱是常存的。'),
('CUV', '诗篇', 19, 52, 2, '你的舌头邪恶诡诈，好像剃头刀，快利伤人。'),
('CUV', '诗篇', 19, 52, 3, '你爱恶胜似爱善，又爱说谎，不爱说公义。（细拉）'),
('CUV', '诗篇', 19, 52, 4, '诡诈的舌头啊，你爱说一切毁灭的话！'),
('CUV', '诗篇', 19, 52, 5, '神也要毁灭你，直到永远；他要把你拿去，从你的帐棚中抽出，从活人之地将你拔出。（细拉）'),
('CUV', '诗篇', 19, 52, 6, '义人要看见而惧怕，并要笑他，'),
('CUV', '诗篇', 19, 52, 7, '说：看哪，这就是那不以神为他力量的人，只倚仗他丰富的财物，在邪恶上坚立自己。'),
('CUV', '诗篇', 19, 52, 8, '至于我，就像神殿中的青橄榄树；我永永远远倚靠神的慈爱。'),
('CUV', '诗篇', 19, 52, 9, '我要称谢你，直到永远，因为你行了这事。我也要在你圣民面前仰望你的名；这名本为美好。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 53, 1, '（大卫的训诲诗，交与伶长。调用麻哈拉。）愚顽人心里说：没有神。他们都是邪恶，行了可憎恶的罪孽；没有一个人行善。'),
('CUV', '诗篇', 19, 53, 2, '神从天上垂看世人，要看有明白的没有？有寻求他的没有？'),
('CUV', '诗篇', 19, 53, 3, '他们各人都退后，一同变为污秽；并没有行善的，连一个也没有。'),
('CUV', '诗篇', 19, 53, 4, '作孽的没有知识么？他们吞吃我的百姓如同吃饭一样，并不求告神。'),
('CUV', '诗篇', 19, 53, 5, '他们在无可惧怕之处就大大害怕，因为神把那安营攻击你之人的骨头散开了。你使他们蒙羞，因为神弃绝了他们。'),
('CUV', '诗篇', 19, 53, 6, '但愿以色列的救恩从锡安而出。神救回他被掳的子民那时，雅各要快乐，以色列要欢喜。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 54, 1, '（西弗人来对扫罗说：大卫岂不是在我们那里藏身么？那时，大卫作这训诲诗，交与伶长。用丝弦的乐器。）神啊，求你以你的名救我，凭你的大能为我伸冤。'),
('CUV', '诗篇', 19, 54, 2, '神啊，求你听我的祷告，留心听我口中的言语。'),
('CUV', '诗篇', 19, 54, 3, '因为，外人起来攻击我，强暴人寻索我的命；他们眼中没有神。（细拉）'),
('CUV', '诗篇', 19, 54, 4, '神是帮助我的，是扶持我命的。'),
('CUV', '诗篇', 19, 54, 5, '他要报应我仇敌所行的恶；求你凭你的诚实灭绝他们。'),
('CUV', '诗篇', 19, 54, 6, '我要把甘心祭献给你。耶和华啊，我要称赞你的名；这名本为美好。'),
('CUV', '诗篇', 19, 54, 7, '他从一切的急难中把我救出来；我的眼睛也看见了我仇敌遭报。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 55, 1, '（大卫的训诲诗，交与伶长。用丝弦的乐器。）神啊，求你留心听我的祷告，不要隐藏不听我的恳求！'),
('CUV', '诗篇', 19, 55, 2, '求你侧耳听我，应允我。我哀叹不安，发声唉哼，'),
('CUV', '诗篇', 19, 55, 3, '都因仇敌的声音，恶人的欺压；因为他们将罪孽加在我身上，发怒气逼迫我。'),
('CUV', '诗篇', 19, 55, 4, '我心在我里面甚是疼痛；死的惊惶临到我身。'),
('CUV', '诗篇', 19, 55, 5, '恐惧战兢归到我身；惊恐漫过了我。'),
('CUV', '诗篇', 19, 55, 6, '我说：但愿我有翅膀像鸽子，我就飞去，得享安息。'),
('CUV', '诗篇', 19, 55, 7, '我必远游，宿在旷野。（细拉）'),
('CUV', '诗篇', 19, 55, 8, '我必速速逃到避所，脱离狂风暴雨。'),
('CUV', '诗篇', 19, 55, 9, '主啊，求你吞灭他们，变乱他们的舌头！因为我在城中见了强暴争竞的事。'),
('CUV', '诗篇', 19, 55, 10, '他们在城墙上昼夜绕行；在城内也有罪孽和奸恶。'),
('CUV', '诗篇', 19, 55, 11, '邪恶在其中；欺压和诡诈不离街市。'),
('CUV', '诗篇', 19, 55, 12, '原来不是仇敌辱骂我，若是仇敌，还可忍耐；也不是恨我的人向我狂大，若是恨我的人就必躲避他。'),
('CUV', '诗篇', 19, 55, 13, '不料是你；你原与我平等，是我的同伴，是我知己的朋友！'),
('CUV', '诗篇', 19, 55, 14, '我们素常彼此谈论，以为甘甜；我们与群众在神的殿中同行。'),
('CUV', '诗篇', 19, 55, 15, '愿死亡忽然临到他们！愿他们活活地下入阴间！因为他们的住处，他们的心中，都是邪恶。'),
('CUV', '诗篇', 19, 55, 16, '至于我，我要求告神；耶和华必拯救我。'),
('CUV', '诗篇', 19, 55, 17, '我要晚上、早晨、晌午哀声悲叹；他也必听我的声音。'),
('CUV', '诗篇', 19, 55, 18, '他救赎我命脱离攻击我的人，使我得享平安，因为与我相争的人甚多。'),
('CUV', '诗篇', 19, 55, 19, '那没有更变、不敬畏神的人，从太古常存的神必听见而苦待他。'),
('CUV', '诗篇', 19, 55, 20, '他背了约，伸手攻击与他和好的人。'),
('CUV', '诗篇', 19, 55, 21, '他的口如奶油光滑，他的心却怀著争战；他的话比油柔和，其实是拔出来的刀。'),
('CUV', '诗篇', 19, 55, 22, '你要把你的重担卸给耶和华，他必抚养你；他永不叫义人动摇。'),
('CUV', '诗篇', 19, 55, 23, '神啊，你必使恶人下入灭亡的坑；流人血、行诡诈的人必活不到半世，但我要倚靠你。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 56, 1, '（非利士人在迦特拿住大卫。那时，他作这金诗，交与伶长。调用远方无声鸽。）神啊，求你怜悯我，因为人要把我吞了，终日攻击欺压我。'),
('CUV', '诗篇', 19, 56, 2, '我的仇敌终日要把我吞了，因逞骄傲攻击我的人甚多。'),
('CUV', '诗篇', 19, 56, 3, '我惧怕的时候要倚靠你。'),
('CUV', '诗篇', 19, 56, 4, '我倚靠神，我要赞美他的话；我倚靠神，必不惧怕。血气之辈能把我怎么样呢？'),
('CUV', '诗篇', 19, 56, 5, '他们终日颠倒我的话；他们一切的心思都是要害我。'),
('CUV', '诗篇', 19, 56, 6, '他们聚集，埋伏窥探我的脚踪，等候要害我的命。'),
('CUV', '诗篇', 19, 56, 7, '他们岂能因罪孽逃脱么？神啊，求你在怒中使众民堕落！'),
('CUV', '诗篇', 19, 56, 8, '我几次流离，你都记数；求你把我眼泪装在你的皮袋里。这不都记在你册子上么？'),
('CUV', '诗篇', 19, 56, 9, '我呼求的日子，我的仇敌都要转身退后。神帮助我，这是我所知道的。'),
('CUV', '诗篇', 19, 56, 10, '我倚靠神，我要赞美他的话我倚靠耶和华，我要赞美他的话。'),
('CUV', '诗篇', 19, 56, 11, '我倚靠神，必不惧怕。人能把我怎么样呢？'),
('CUV', '诗篇', 19, 56, 12, '神啊，我向你所许的愿在我身上；我要将感谢祭献给你。'),
('CUV', '诗篇', 19, 56, 13, '因为你救我的命脱离死亡。你岂不是救护我的脚不跌倒、使我在生命光中行在神面前么？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 57, 1, '（大卫逃避扫罗，藏在洞里。那时，他作这金诗，交与伶长。调用休要毁坏。）神啊，求你怜悯我，怜悯我！因为我的心投靠你。我要投靠在你翅膀的荫下，等到灾害过去。'),
('CUV', '诗篇', 19, 57, 2, '我要求告至高的神，就是为我成全诸事的神。'),
('CUV', '诗篇', 19, 57, 3, '那要吞我的人辱骂我的时候，神从天上必施恩救我，也必向我发出慈爱和诚实。'),
('CUV', '诗篇', 19, 57, 4, '我的性命在狮子中间；我躺卧在性如烈火的世人当中。他们的牙齿是枪、箭；他们的舌头是快刀。'),
('CUV', '诗篇', 19, 57, 5, '神啊，愿你崇高过于诸天！愿你的荣耀高过全地！'),
('CUV', '诗篇', 19, 57, 6, '他们为我的脚设下网罗，压制我的心；他们在我面前挖了坑，自己反掉在其中。（细拉）'),
('CUV', '诗篇', 19, 57, 7, '神啊，我心坚定，我心坚定；我要唱诗，我要歌颂！'),
('CUV', '诗篇', 19, 57, 8, '我的灵（原文是荣耀）啊，你当醒起！琴瑟啊，你们当醒起！我自己要极早醒起！'),
('CUV', '诗篇', 19, 57, 9, '主啊，我要在万民中称谢你，在列邦中歌颂你！'),
('CUV', '诗篇', 19, 57, 10, '因为，你的慈爱高及诸天；你的诚实达到穹苍。'),
('CUV', '诗篇', 19, 57, 11, '神啊，愿你崇高过于诸天！愿你的荣耀高过全地！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 58, 1, '（大卫的金诗，交与伶长。调用休要毁坏。）世人哪，你们默然不语，真合公义么？施行审判，岂按正直么？'),
('CUV', '诗篇', 19, 58, 2, '不然！你们是心中作恶；你们在地上秤出你们手所行的强暴。'),
('CUV', '诗篇', 19, 58, 3, '恶人一出母胎就与神疏远，一离母腹便走错路，说谎话。'),
('CUV', '诗篇', 19, 58, 4, '他们的毒气好像蛇的毒气；他们好像塞耳的聋虺，'),
('CUV', '诗篇', 19, 58, 5, '不听行法术的声音，虽用极灵的咒语也是不听。'),
('CUV', '诗篇', 19, 58, 6, '神啊，求你敲碎他们口中的牙；耶和华啊，求你敲掉少壮狮子的大牙！'),
('CUV', '诗篇', 19, 58, 7, '愿他们消灭，如急流的水一般；他们瞅准射箭的时候，愿箭头仿佛砍断。'),
('CUV', '诗篇', 19, 58, 8, '愿他们像蜗牛消化过去，又像妇人坠落未见天日的胎。'),
('CUV', '诗篇', 19, 58, 9, '你们用荆棘烧火，锅还未热，他要用旋风把青的和烧著的一齐刮去。'),
('CUV', '诗篇', 19, 58, 10, '义人见仇敌遭报就欢喜，要在恶人的血中洗脚。'),
('CUV', '诗篇', 19, 58, 11, '因此，人必说：义人诚然有善报；在地上果有施行判断的神！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 59, 1, '（扫罗打发人窥探大卫的房屋，要杀他。那时，大卫用这金诗，交与伶长。调用休要毁坏。）我的神啊，求你救我脱离仇敌，把我安置在高处，得脱那些起来攻击我的人。'),
('CUV', '诗篇', 19, 59, 2, '求你救我脱离作孽的人和喜爱流人血的人！'),
('CUV', '诗篇', 19, 59, 3, '因为，他们埋伏要害我的命；有能力的人聚集来攻击我。耶和华啊，这不是为我的过犯，也不是为我的罪愆。'),
('CUV', '诗篇', 19, 59, 4, '我虽然无过，他们预备整齐，跑来攻击我。求你兴起鉴察，帮助我！'),
('CUV', '诗篇', 19, 59, 5, '万军之神─耶和华以色列的神啊！求你兴起，惩治万邦！不要怜悯行诡诈的恶人！（细拉）'),
('CUV', '诗篇', 19, 59, 6, '他们晚上转回，叫号如狗，围城绕行。'),
('CUV', '诗篇', 19, 59, 7, '他们口中喷吐恶言，嘴里有刀；他们说：有谁听见？'),
('CUV', '诗篇', 19, 59, 8, '但你─耶和华必笑话他们；你要嗤笑万邦。'),
('CUV', '诗篇', 19, 59, 9, '我的力量啊，我必仰望你，因为神是我的高台。'),
('CUV', '诗篇', 19, 59, 10, '我的神要以慈爱迎接我；神要叫我看见我仇敌遭报。'),
('CUV', '诗篇', 19, 59, 11, '不要杀他们，恐怕我的民忘记。主啊，你是我们的盾牌；求你用你的能力使他们四散，且降为卑。'),
('CUV', '诗篇', 19, 59, 12, '他们口中的罪和嘴里的言语，并咒骂虚谎的话，愿他们在骄傲之中被缠住了。'),
('CUV', '诗篇', 19, 59, 13, '求你发怒，使他们消灭，以致归于无有，叫他们知道神在雅各中间掌权，直到地极。（细拉）'),
('CUV', '诗篇', 19, 59, 14, '到了晚上，任凭他们转回；任凭他们叫号如狗，围城绕行。'),
('CUV', '诗篇', 19, 59, 15, '他们必走来走去，寻找食物，若不得饱就终夜在外。'),
('CUV', '诗篇', 19, 59, 16, '但我要歌颂你的力量，早晨要高唱你的慈爱；因为你作过我的高台，在我急难的日子作过我的避难所。'),
('CUV', '诗篇', 19, 59, 17, '我的力量啊，我要歌颂你；因为神是我的高台，是赐恩与我的神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 60, 1, '（大卫与两河间的亚兰并琐巴的亚兰争战的时候，约押转回，在盐谷攻击以东，杀了一万二千人。那时，大卫作这金诗叫人学习，交与伶长。调用为证的百合花。）神啊，你丢弃了我们，使我们破败；你向我们发怒，求你使我们复兴！'),
('CUV', '诗篇', 19, 60, 2, '你使地震动，而且崩裂；求你将裂口医好，因为地摇动。'),
('CUV', '诗篇', 19, 60, 3, '你叫你的民遇见艰难；你叫我们喝那使人东倒西歪的酒。'),
('CUV', '诗篇', 19, 60, 4, '你把旌旗赐给敬畏你的人，可以为真理扬起来。（细拉）'),
('CUV', '诗篇', 19, 60, 5, '求你应允我们，用右手拯救我们，好叫你所亲爱的人得救。'),
('CUV', '诗篇', 19, 60, 6, '神已经指著他的圣洁说（说：或译应许我）：我要欢乐；我要分开示剑，丈量疏割谷。'),
('CUV', '诗篇', 19, 60, 7, '基列是我的，玛拿西也是我的。以法莲是护卫我头的；犹大是我的杖。'),
('CUV', '诗篇', 19, 60, 8, '摩押是我的沐浴盆；我要向以东抛鞋。非利士啊，你还能因我欢呼么？'),
('CUV', '诗篇', 19, 60, 9, '谁能领我进坚固城？谁能引我到以东地？'),
('CUV', '诗篇', 19, 60, 10, '神啊，你不是丢弃了我们么？神啊，你不和我们的军兵同去么？'),
('CUV', '诗篇', 19, 60, 11, '求你帮助我们攻击敌人，因为人的帮助是枉然的。'),
('CUV', '诗篇', 19, 60, 12, '我们倚靠神才得施展大能，因为践踏我们敌人的就是他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 61, 1, '（大卫的诗，交与伶长。用丝弦的乐器。）神啊，求你听我的呼求，侧耳听我的祷告！'),
('CUV', '诗篇', 19, 61, 2, '我心里发昏的时候，我要从地极求告你。求你领我到那比我更高的磐石！'),
('CUV', '诗篇', 19, 61, 3, '因为你作过我的避难所，作过我的坚固台，脱离仇敌。'),
('CUV', '诗篇', 19, 61, 4, '我要永远住在你的帐幕里！我要投靠在你翅膀下的隐密处！（细拉）'),
('CUV', '诗篇', 19, 61, 5, '神啊，你原是听了我所许的愿；你将产业赐给敬畏你名的人。'),
('CUV', '诗篇', 19, 61, 6, '你要加添王的寿数；他的年岁必存到世世。'),
('CUV', '诗篇', 19, 61, 7, '他必永远坐在神面前；愿你预备慈爱和诚实保佑他！'),
('CUV', '诗篇', 19, 61, 8, '这样，我要歌颂你的名，直到永远，好天天还我所许的愿。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 62, 1, '（大卫的诗，照耶杜顿的作法，交与伶长。）我的心默默无声，专等候神；我的救恩是从他而来。'),
('CUV', '诗篇', 19, 62, 2, '惟独他是我的磐石，我的拯救；他是我的高台，我必不很动摇。'),
('CUV', '诗篇', 19, 62, 3, '你们大家攻击一人，把他毁坏，如同毁坏歪斜的墙、将倒的壁，要到几时呢？'),
('CUV', '诗篇', 19, 62, 4, '他们彼此商议，专要从他的尊位上把他推下；他们喜爱谎话，口虽祝福，心却咒诅。（细拉）'),
('CUV', '诗篇', 19, 62, 5, '我的心哪，你当默默无声，专等候神，因为我的盼望是从他而来。'),
('CUV', '诗篇', 19, 62, 6, '惟独他是我的磐石，我的拯救；他是我的高台，我必不动摇。'),
('CUV', '诗篇', 19, 62, 7, '我的拯救、我的荣耀都在乎神；我力量的磐石、我的避难所都在乎神。'),
('CUV', '诗篇', 19, 62, 8, '你们众民当时时倚靠他，在他面前倾心吐意；神是我们的避难所。（细拉）'),
('CUV', '诗篇', 19, 62, 9, '下流人真是虚空；上流人也是虚假；放在天平里就必浮起；他们一共比空气还轻。'),
('CUV', '诗篇', 19, 62, 10, '不要仗势欺人，也不要因抢夺而骄傲；若财宝加增，不要放在心上。'),
('CUV', '诗篇', 19, 62, 11, '神说了一次、两次，我都听见：就是能力都属乎神。'),
('CUV', '诗篇', 19, 62, 12, '主啊，慈爱也是属乎你，因为你照著各人所行的报应他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 63, 1, '（大卫在犹大旷野的时候，作了这诗。）神啊，你是我的神，我要切切地寻求你，在干旱疲乏无水之地，我渴想你；我的心切慕你。'),
('CUV', '诗篇', 19, 63, 2, '我在圣所中曾如此瞻仰你，为要见你的能力和你的荣耀。'),
('CUV', '诗篇', 19, 63, 3, '因你的慈爱比生命更好，我的嘴唇要颂赞你。'),
('CUV', '诗篇', 19, 63, 4, '我还活的时候要这样称颂你；我要奉你的名举手。'),
('CUV', '诗篇', 19, 63, 5, '我在床上记念你，在夜更的时候思想你；我的心就像饱足了骨髓肥油，我也要以欢乐的嘴唇赞美你。'),
('CUV', '诗篇', 19, 63, 6, '合和译本并入上一节'),
('CUV', '诗篇', 19, 63, 7, '因为你曾帮助我，我就在你翅膀的荫下欢呼。'),
('CUV', '诗篇', 19, 63, 8, '我心紧紧地跟随你；你的右手扶持我。'),
('CUV', '诗篇', 19, 63, 9, '但那些寻索要灭我命的人必往地底下去；'),
('CUV', '诗篇', 19, 63, 10, '他们必被刀剑所杀，被野狗所吃。'),
('CUV', '诗篇', 19, 63, 11, '但是王必因神欢喜。凡指著他发誓的必要夸口，因为说谎之人的口必被塞住。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 64, 1, '（大卫的诗，交与伶长。）神啊，我哀叹的时候，求你听我的声音！求你保护我的性命，不受仇敌的惊恐！'),
('CUV', '诗篇', 19, 64, 2, '求你把我隐藏，使我脱离作恶之人的暗谋和作孽之人的扰乱。'),
('CUV', '诗篇', 19, 64, 3, '他们磨舌如刀，发出苦毒的言语，好像比准了的箭，'),
('CUV', '诗篇', 19, 64, 4, '要在暗地射完全人；他们忽然射他，并不惧怕。'),
('CUV', '诗篇', 19, 64, 5, '他们彼此勉励设下恶计；他们商量暗设网罗，说：谁能看见？'),
('CUV', '诗篇', 19, 64, 6, '他们图谋奸恶，说：我们是极力图谋的。他们各人的意念心思是深的。'),
('CUV', '诗篇', 19, 64, 7, '但神要射他们；他们忽然被箭射伤。'),
('CUV', '诗篇', 19, 64, 8, '他们必然绊跌，被自己的舌头所害；凡看见他们的必都摇头。'),
('CUV', '诗篇', 19, 64, 9, '众人都要害怕，要传扬神的工作，并且明白他的作为。'),
('CUV', '诗篇', 19, 64, 10, '义人必因耶和华欢喜，并要投靠他；凡心里正直的人都要夸口。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 65, 1, '（大卫的诗歌，交与伶长。）神啊，锡安的人都等候赞美你；所许的愿也要向你偿还。'),
('CUV', '诗篇', 19, 65, 2, '听祷告的主啊，凡有血气的都要来就你。'),
('CUV', '诗篇', 19, 65, 3, '罪孽胜了我；至于我们的过犯，你都要赦免。'),
('CUV', '诗篇', 19, 65, 4, '你所拣选、使他亲近你、住在你院中的，这人便为有福！我们必因你居所、你圣殿的美福知足了。'),
('CUV', '诗篇', 19, 65, 5, '拯救我们的神啊，你必以威严秉公义应允我们；你本是一切地极和海上远处的人所倚靠的。'),
('CUV', '诗篇', 19, 65, 6, '他既以大能束腰，就用力量安定诸山，'),
('CUV', '诗篇', 19, 65, 7, '使诸海的响声和其中波浪的响声，并万民的喧哗，都平静了。'),
('CUV', '诗篇', 19, 65, 8, '住在地极的人因你的神迹惧怕；你使日出日落之地都欢呼。'),
('CUV', '诗篇', 19, 65, 9, '你眷顾地，降下透雨，使地大得肥美。神的河满了水；你这样浇灌了地，好为人预备五谷。'),
('CUV', '诗篇', 19, 65, 10, '你浇透地的犁沟，润平犁脊，降甘霖，使地软和；其中发长的，蒙你赐福。'),
('CUV', '诗篇', 19, 65, 11, '你以恩典为年岁的冠冕；你的路径都滴下脂油，'),
('CUV', '诗篇', 19, 65, 12, '滴在旷野的草场上。小山以欢乐束腰；'),
('CUV', '诗篇', 19, 65, 13, '草场以羊群为衣；谷中也长满了五谷。这一切都欢呼歌唱。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 66, 1, '（一篇诗歌，交与伶长。）全地都当向神欢呼！'),
('CUV', '诗篇', 19, 66, 2, '歌颂他名的荣耀！用赞美的言语将他的荣耀发明！'),
('CUV', '诗篇', 19, 66, 3, '当对神说：你的作为何等可畏！因你的大能，仇敌要投降你。'),
('CUV', '诗篇', 19, 66, 4, '全地要敬拜你，歌颂你，要歌颂你的名。（细拉）'),
('CUV', '诗篇', 19, 66, 5, '你们来看神所行的，他向世人所做之事是可畏的。'),
('CUV', '诗篇', 19, 66, 6, '他将海变成干地，众民步行过河；我们在那里因他欢喜。'),
('CUV', '诗篇', 19, 66, 7, '他用权能治理万民，直到永远。他的眼睛鉴察列邦；悖逆的人不可自高。（细拉）'),
('CUV', '诗篇', 19, 66, 8, '万民哪，你们当称颂我们的神，使人得听赞美他的声音。'),
('CUV', '诗篇', 19, 66, 9, '他使我们的性命存活，也不叫我们的脚摇动。'),
('CUV', '诗篇', 19, 66, 10, '神啊，你曾试验我们，熬炼我们，如熬炼银子一样。'),
('CUV', '诗篇', 19, 66, 11, '你使我们进入网罗，把重担放在我们的身上。'),
('CUV', '诗篇', 19, 66, 12, '你使人坐车轧我们的头；我们经过水火，你却使我们到丰富之地。'),
('CUV', '诗篇', 19, 66, 13, '我要用燔祭进你的殿，向你还我的愿，'),
('CUV', '诗篇', 19, 66, 14, '就是在急难时我嘴唇所发的、口中所许的。'),
('CUV', '诗篇', 19, 66, 15, '我要把肥牛作燔祭，将公羊的香祭献给你，又把公牛和山羊献上。（细拉）'),
('CUV', '诗篇', 19, 66, 16, '凡敬畏神的人，你们都来听！我要述说他为我所行的事。'),
('CUV', '诗篇', 19, 66, 17, '我曾用口求告他；我的舌头也称他为高。'),
('CUV', '诗篇', 19, 66, 18, '我若心里注重罪孽，主必不听。'),
('CUV', '诗篇', 19, 66, 19, '但神实在听见了；他侧耳听了我祷告的声音。'),
('CUV', '诗篇', 19, 66, 20, '神是应当称颂的！他并没有推却我的祷告，也没有叫他的慈爱离开我。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 67, 1, '（一篇诗歌，交与伶长。用丝弦的乐器。）愿神怜悯我们，赐福与我们，用脸光照我们，（细拉）'),
('CUV', '诗篇', 19, 67, 2, '好叫世界得知你的道路，万国得知你的救恩。'),
('CUV', '诗篇', 19, 67, 3, '神啊，愿列邦称赞你！愿万民都称赞你！'),
('CUV', '诗篇', 19, 67, 4, '愿万国都快乐欢呼；因为你必按公正审判万民，引导世上的万国。（细拉）'),
('CUV', '诗篇', 19, 67, 5, '神啊，愿列邦称赞你！愿万民都称赞你！'),
('CUV', '诗篇', 19, 67, 6, '地已经出了土产；神─就是我们的神要赐福与我们。'),
('CUV', '诗篇', 19, 67, 7, '神要赐福与我们；地的四极都要敬畏他！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 68, 1, '（大卫的诗歌，交与伶长。）愿神兴起，使他的仇敌四散，叫那恨他的人从他面前逃跑。'),
('CUV', '诗篇', 19, 68, 2, '他们被驱逐，如烟被风吹散；恶人见神之面而消灭，如蜡被火镕化。'),
('CUV', '诗篇', 19, 68, 3, '惟有义人必然欢喜，在神面前高兴快乐。'),
('CUV', '诗篇', 19, 68, 4, '你们当向神唱诗，歌颂他的名；为那坐车行过旷野的修平大路。他的名是耶和华，要在他面前欢乐！'),
('CUV', '诗篇', 19, 68, 5, '神在他的圣所作孤儿的父，作寡妇的伸冤者。'),
('CUV', '诗篇', 19, 68, 6, '神叫孤独的有家，使被囚的出来享福；惟有悖逆的住在干燥之地。'),
('CUV', '诗篇', 19, 68, 7, '神啊，你曾在你百姓前头出来，在旷野行走。（细拉）'),
('CUV', '诗篇', 19, 68, 8, '那时，地见神的面而震动，天也落雨；西乃山见以色列神的面也震动。'),
('CUV', '诗篇', 19, 68, 9, '神啊，你降下大雨；你产业以色列疲乏的时候，你使他坚固。'),
('CUV', '诗篇', 19, 68, 10, '你的会众住在其中；神啊，你的恩惠是为困苦人预备的。'),
('CUV', '诗篇', 19, 68, 11, '主发命令，传好信息的妇女成了大群。'),
('CUV', '诗篇', 19, 68, 12, '统兵的君王逃跑了，逃跑了；在家等候的妇女分受所夺的。'),
('CUV', '诗篇', 19, 68, 13, '你们安卧在羊圈的时候，好像鸽子的翅膀镀白银，翎毛镀黄金一般。'),
('CUV', '诗篇', 19, 68, 14, '全能者在境内赶散列王的时候，势如飘雪在撒们。'),
('CUV', '诗篇', 19, 68, 15, '巴珊山是神的山；巴珊山是多峰多岭的山。'),
('CUV', '诗篇', 19, 68, 16, '你们多峰多岭的山哪，为何斜看神所愿居住的山？耶和华必住这山，直到永远！'),
('CUV', '诗篇', 19, 68, 17, '神的车葱讵万盈千；主在其中，好像在西乃圣山一样。'),
('CUV', '诗篇', 19, 68, 18, '你已经升上高天，掳掠仇敌；你在人间，就是在悖逆的人间，受了供献，叫耶和华神可以与他们同住。'),
('CUV', '诗篇', 19, 68, 19, '天天背负我们重担的主，就是拯救我们的神，是应当称颂的！（细拉）'),
('CUV', '诗篇', 19, 68, 20, '神是为我们施行诸般救恩的神；人能脱离死亡是在乎主耶和华。'),
('CUV', '诗篇', 19, 68, 21, '但神要打破他仇敌的头，就是那常犯罪之人的发顶。'),
('CUV', '诗篇', 19, 68, 22, '主说：我要使众民从巴珊而归，使他们从深海而回，'),
('CUV', '诗篇', 19, 68, 23, '使你打碎仇敌，你的脚踹在血中，使你狗的舌头从其中得分。'),
('CUV', '诗篇', 19, 68, 24, '神啊，你是我的神，我的王；人已经看见你行走，进入圣所。'),
('CUV', '诗篇', 19, 68, 25, '歌唱的行在前，作乐的随在后，都在击鼓的童女中间。'),
('CUV', '诗篇', 19, 68, 26, '从以色列源头而来的，当在各会中称颂主神！'),
('CUV', '诗篇', 19, 68, 27, '在那里，有统管他们的小便雅悯，有犹大的首领和他们的群众，有西布伦的首领，有拿弗他利的首领。'),
('CUV', '诗篇', 19, 68, 28, '以色列的能力是神所赐的；神啊，求你坚固你为我们所成全的事！'),
('CUV', '诗篇', 19, 68, 29, '因你耶路撒冷的殿，列王必带贡物献给你。'),
('CUV', '诗篇', 19, 68, 30, '求你叱喝芦苇中的野兽和群公牛，并列邦中的牛犊。把银块踹在脚下；神已经赶散好争战的列邦。'),
('CUV', '诗篇', 19, 68, 31, '埃及的公侯要出来朝见神；古实人要急忙举手祷告。'),
('CUV', '诗篇', 19, 68, 32, '世上的列国啊，你们要向神歌唱；愿你们歌颂主！'),
('CUV', '诗篇', 19, 68, 33, '歌颂那自古驾行在诸天以上的主！他发出声音，是极大的声音。'),
('CUV', '诗篇', 19, 68, 34, '你们要将能力归给神。他的威荣在以色列之上；他的能力是在穹苍。'),
('CUV', '诗篇', 19, 68, 35, '神啊，你从圣所显为可畏；以色列的神是那将力量权能赐给他百姓的。神是应当称颂的！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 69, 1, '（大卫的诗，交与伶长。调用百合花。）神啊，求你救我！因为众水要淹没我。'),
('CUV', '诗篇', 19, 69, 2, '我陷在深淤泥中，没有立脚之地；我到了深水中，大水漫过我身。'),
('CUV', '诗篇', 19, 69, 3, '我因呼求困乏，喉咙发干；我因等候神，眼睛失明。'),
('CUV', '诗篇', 19, 69, 4, '无故恨我的，比我头发还多；无理与我为仇、要把我剪除的，甚为强盛。我没有抢夺的，要叫我偿还。'),
('CUV', '诗篇', 19, 69, 5, '神啊，我的愚昧，你原知道；我的罪愆不能隐瞒。'),
('CUV', '诗篇', 19, 69, 6, '万军的主─耶和华啊，求你叫那等候你的，不要因我蒙羞！以色列的神啊，求你叫那寻求你的，不要因我受辱！'),
('CUV', '诗篇', 19, 69, 7, '因我为你的缘故受了辱骂，满面羞愧。'),
('CUV', '诗篇', 19, 69, 8, '我的弟兄看我为外路人；我的同胞看我为外邦人。'),
('CUV', '诗篇', 19, 69, 9, '因我为你的殿心里焦急，如同火烧，并且辱骂你人的辱骂都落在我身上。'),
('CUV', '诗篇', 19, 69, 10, '我哭泣，以禁食刻苦我心；这倒算为我的羞辱。'),
('CUV', '诗篇', 19, 69, 11, '我拿麻布当衣裳，就成了他们的笑谈。'),
('CUV', '诗篇', 19, 69, 12, '坐在城门口的谈论我；酒徒也以我为歌曲。'),
('CUV', '诗篇', 19, 69, 13, '但我在悦纳的时候向你─耶和华祈祷。神啊，求你按你丰盛的慈爱，凭你拯救的诚实应允我！'),
('CUV', '诗篇', 19, 69, 14, '求你搭救我出离淤泥，不叫我陷在其中；求你使我脱离那些恨我的人，使我出离深水。'),
('CUV', '诗篇', 19, 69, 15, '求你不容大水漫过我，不容深渊吞灭我，不容坑坎在我以上合口。'),
('CUV', '诗篇', 19, 69, 16, '耶和华啊，求你应允我！因为你的慈爱本为美好；求你按你丰盛的慈悲回转眷顾我！'),
('CUV', '诗篇', 19, 69, 17, '不要掩面不顾你的仆人；我是在急难之中，求你速速地应允我！'),
('CUV', '诗篇', 19, 69, 18, '求你亲近我，救赎我！求你因我的仇敌把我赎回！'),
('CUV', '诗篇', 19, 69, 19, '你知道我受的辱骂、欺凌、羞辱；我的敌人都在你面前。'),
('CUV', '诗篇', 19, 69, 20, '辱骂伤破了我的心，我又满了忧愁。我指望有人体恤，却没有一个；我指望有人安慰，却找不著一个。'),
('CUV', '诗篇', 19, 69, 21, '他们拿苦胆给我当食物；我渴了，他们拿醋给我喝。'),
('CUV', '诗篇', 19, 69, 22, '愿他们的筵席在他们面前变为网罗，在他们平安的时候变为机槛。'),
('CUV', '诗篇', 19, 69, 23, '愿他们的眼睛昏蒙，不得看见；愿你使他们的腰常常战抖。'),
('CUV', '诗篇', 19, 69, 24, '求你将你的恼恨倒在他们身上，叫你的烈怒追上他们。'),
('CUV', '诗篇', 19, 69, 25, '愿他们的住处变为荒场；愿他们的帐棚无人居住。'),
('CUV', '诗篇', 19, 69, 26, '因为，你所击打的，他们就逼迫；你所击伤的，他们戏说他的愁苦。'),
('CUV', '诗篇', 19, 69, 27, '愿你在他们的罪上加罪，不容他们在你面前称义。'),
('CUV', '诗篇', 19, 69, 28, '愿他们从生命册上被涂抹，不得记录在义人之中。'),
('CUV', '诗篇', 19, 69, 29, '但我是困苦忧伤的；神啊，愿你的救恩将我安置在高处。'),
('CUV', '诗篇', 19, 69, 30, '我要以诗歌赞美神的名，以感谢称他为大！'),
('CUV', '诗篇', 19, 69, 31, '这便叫耶和华喜悦，胜似献牛，或是献有角有蹄的公牛。'),
('CUV', '诗篇', 19, 69, 32, '谦卑的人看见了就喜乐；寻求神的人，愿你们的心苏醒。'),
('CUV', '诗篇', 19, 69, 33, '因为耶和华听了穷乏人，不藐视被囚的人。'),
('CUV', '诗篇', 19, 69, 34, '愿天和地、洋海和其中一切的动物都赞美他！'),
('CUV', '诗篇', 19, 69, 35, '因为神要拯救锡安，建造犹大的城邑；他的民要在那里居住，得以为业。'),
('CUV', '诗篇', 19, 69, 36, '他仆人的后裔要承受为业；爱他名的人也要住在其中。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 70, 1, '（大卫的记念诗，交与伶长。）神啊，求你快快搭救我！耶和华啊，求你速速帮助我！'),
('CUV', '诗篇', 19, 70, 2, '愿那些寻索我命的，抱愧蒙羞；愿那些喜悦我遭害的，退后受辱。'),
('CUV', '诗篇', 19, 70, 3, '愿那些对我说阿哈、阿哈的，因羞愧退后。'),
('CUV', '诗篇', 19, 70, 4, '愿一切寻求你的，因你高兴欢喜；愿那些喜爱你救恩的，常说：当尊神为大！'),
('CUV', '诗篇', 19, 70, 5, '但我是困苦穷乏的；神啊，求你速速到我这里来！你是帮助我的，搭救我的。耶和华啊，求你不要耽延！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 71, 1, '耶和华啊，我投靠你；求你叫我永不羞愧！'),
('CUV', '诗篇', 19, 71, 2, '求你凭你的公义搭救我，救拔我；侧耳听我，拯救我！'),
('CUV', '诗篇', 19, 71, 3, '求你作我常住的磐石；你已经命定要救我，因为你是我的岩石，我的山寨。'),
('CUV', '诗篇', 19, 71, 4, '我的神啊，求你救我脱离恶人的手，脱离不义和残暴之人的手。'),
('CUV', '诗篇', 19, 71, 5, '主─耶和华啊，你是我所盼望的；从我年幼，你是我所倚靠的。'),
('CUV', '诗篇', 19, 71, 6, '我从出母胎被你扶持；使我出母腹的是你。我必常常赞美你！'),
('CUV', '诗篇', 19, 71, 7, '许多人以我为怪，但你是我坚固的避难所。'),
('CUV', '诗篇', 19, 71, 8, '你的赞美，你的荣耀终日必满了我的口。'),
('CUV', '诗篇', 19, 71, 9, '我年老的时候，求你不要丢弃我！我力气衰弱的时候，求你不要离弃我！'),
('CUV', '诗篇', 19, 71, 10, '我的仇敌议论我；那些窥探要害我命的彼此商议，'),
('CUV', '诗篇', 19, 71, 11, '说：神已经离弃他；我们追赶他，捉拿他罢！因为没有人搭救。'),
('CUV', '诗篇', 19, 71, 12, '神啊，求你不要远离我！我的神啊，求你速速帮助我！'),
('CUV', '诗篇', 19, 71, 13, '愿那与我性命为敌的，羞愧被灭；愿那谋害我的，受辱蒙羞。'),
('CUV', '诗篇', 19, 71, 14, '我却要常常盼望，并要越发赞美你。'),
('CUV', '诗篇', 19, 71, 15, '我的口终日要述说你的公义和你的救恩，因我不计其数。'),
('CUV', '诗篇', 19, 71, 16, '我要来说主─耶和华大能的事；我单要提说你的公义。'),
('CUV', '诗篇', 19, 71, 17, '神啊，自我年幼时，你就教训我；直到如今，我传扬你奇妙的作为。'),
('CUV', '诗篇', 19, 71, 18, '神啊，我到年老发白的时候，求你不要离弃我！等我将你的能力指示下代，将你的大能指示后世的人。'),
('CUV', '诗篇', 19, 71, 19, '神啊，你的公义甚高；行过大事的神啊，谁能像你！'),
('CUV', '诗篇', 19, 71, 20, '你是叫我们多经历重大急难的，必使我们复活，从地的深处救上来。'),
('CUV', '诗篇', 19, 71, 21, '求你使我越发昌大，又转来安慰我。'),
('CUV', '诗篇', 19, 71, 22, '我的神啊，我要鼓瑟称赞你，称赞你的诚实！以色列的圣者啊，我要弹琴歌颂你！'),
('CUV', '诗篇', 19, 71, 23, '我歌颂你的时候，我的嘴唇和你所赎我的灵魂都必欢呼；'),
('CUV', '诗篇', 19, 71, 24, '并且我的舌头必终日讲论你的公义，因为那些谋害我的人已经蒙羞受辱了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 72, 1, '（所罗门的诗。）神啊，求你将判断的权柄赐给王，将公义赐给王的儿子。'),
('CUV', '诗篇', 19, 72, 2, '他要按公义审判你的民，按公平审判你的困苦人。'),
('CUV', '诗篇', 19, 72, 3, '大山小山都要因公义使民得享平安。'),
('CUV', '诗篇', 19, 72, 4, '他必为民中的困苦人伸冤，拯救穷乏之辈，压碎那欺压人的。'),
('CUV', '诗篇', 19, 72, 5, '太阳还存，月亮还在，人要敬畏你，直到万代！'),
('CUV', '诗篇', 19, 72, 6, '他必降临，像雨降在已割的草地上，如甘霖滋润田地。'),
('CUV', '诗篇', 19, 72, 7, '在他的日子，义人要发旺，大有平安，好像月亮长存。'),
('CUV', '诗篇', 19, 72, 8, '他要执掌权柄，从这海直到那海，从大河直到地极。'),
('CUV', '诗篇', 19, 72, 9, '住在旷野的，必在他面前下拜；他的仇敌必要舔土。'),
('CUV', '诗篇', 19, 72, 10, '他施和海岛的王要进贡；示巴和西巴的王要献礼物。'),
('CUV', '诗篇', 19, 72, 11, '诸王都要叩拜他；万国都要事奉他。'),
('CUV', '诗篇', 19, 72, 12, '因为，穷乏人呼求的时候，他要搭救；没有人帮助的困苦人，他也要搭救。'),
('CUV', '诗篇', 19, 72, 13, '他要怜恤贫寒和穷乏的人，拯救穷苦人的性命。'),
('CUV', '诗篇', 19, 72, 14, '他要救赎他们脱离欺压和强暴；他们的血在他眼中看为宝贵。'),
('CUV', '诗篇', 19, 72, 15, '他们要存活。示巴的金子要奉给他；人要常常为他祷告，终日称颂他。'),
('CUV', '诗篇', 19, 72, 16, '在地的山顶上，五谷必然茂盛（或译：有一把五谷）；所结的谷实要响动，如利巴嫩的树林；城里的人要发旺，如地上的草。'),
('CUV', '诗篇', 19, 72, 17, '他的名要存到永远，要留传如日之久。人要因他蒙福；万国要称他有福。'),
('CUV', '诗篇', 19, 72, 18, '独行奇事的耶和华─以色列的神是应当称颂的！'),
('CUV', '诗篇', 19, 72, 19, '他荣耀的名也当称颂，直到永远。愿他的荣耀充满全地！阿们！阿们！'),
('CUV', '诗篇', 19, 72, 20, '耶西的儿子─大卫的祈祷完毕。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 73, 1, '（亚萨的诗。）神实在恩待以色列那些清心的人！'),
('CUV', '诗篇', 19, 73, 2, '至于我，我的脚几乎失闪；我的脚险些滑跌。'),
('CUV', '诗篇', 19, 73, 3, '我见恶人和狂傲人享平安就心怀不平。'),
('CUV', '诗篇', 19, 73, 4, '他们死的时候没有疼痛；他们的力气却也壮实。'),
('CUV', '诗篇', 19, 73, 5, '他们不像别人受苦，也不像别人遭灾。'),
('CUV', '诗篇', 19, 73, 6, '所以，骄傲如链子戴在他们的项上；强暴像衣裳遮住他们的身体。'),
('CUV', '诗篇', 19, 73, 7, '他们的眼睛因体胖而凸出；他们所得的，过于心里所想的。'),
('CUV', '诗篇', 19, 73, 8, '他们讥笑人，凭恶意说欺压人的话；他们说话自高。'),
('CUV', '诗篇', 19, 73, 9, '他们的口亵渎上天；他们的舌毁谤全地。'),
('CUV', '诗篇', 19, 73, 10, '所以神的民归到这里，喝尽了满杯的苦水。'),
('CUV', '诗篇', 19, 73, 11, '他们说：神怎能晓得？至高者岂有知识呢？'),
('CUV', '诗篇', 19, 73, 12, '看哪，这就是恶人；他们既是常享安逸，财宝便加增。'),
('CUV', '诗篇', 19, 73, 13, '我实在徒然洁净了我的心，徒然洗手表明无辜。'),
('CUV', '诗篇', 19, 73, 14, '因为，我终日遭灾难；每早晨受惩治。'),
('CUV', '诗篇', 19, 73, 15, '我若说，我要这样讲，这就是以奸诈待你的众子。'),
('CUV', '诗篇', 19, 73, 16, '我思索怎能明白这事，眼看实系为难，'),
('CUV', '诗篇', 19, 73, 17, '等我进了神的圣所，思想他们的结局。'),
('CUV', '诗篇', 19, 73, 18, '你实在把他们安在滑地，使他们掉在沉沦之中。'),
('CUV', '诗篇', 19, 73, 19, '他们转眼之间成了何等的荒凉！他们被惊恐灭尽了。'),
('CUV', '诗篇', 19, 73, 20, '人睡醒了，怎样看梦；主啊，你醒了也必照样轻看他们的影像。'),
('CUV', '诗篇', 19, 73, 21, '因而，我心里发酸，肺腑被刺。'),
('CUV', '诗篇', 19, 73, 22, '我这样愚昧无知，在你面前如畜类一般。'),
('CUV', '诗篇', 19, 73, 23, '然而，我常与你同在；你搀著我的右手。'),
('CUV', '诗篇', 19, 73, 24, '你要以你的训言引导我，以后必接我到荣耀里。'),
('CUV', '诗篇', 19, 73, 25, '除你以外，在天上我有谁呢？除你以外，在地上我也没有所爱慕的。'),
('CUV', '诗篇', 19, 73, 26, '我的肉体和我的心肠衰残；但神是我心里的力量，又是我的福分，直到永远。'),
('CUV', '诗篇', 19, 73, 27, '远离你的，必要死亡；凡离弃你行邪淫的，你都灭绝了。'),
('CUV', '诗篇', 19, 73, 28, '但我亲近神是与我有益；我以主耶和华为我的避难所，好叫我述说你一切的作为。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 74, 1, '（亚萨的训诲诗。）神啊，你为何永远丢弃我们呢？你为何向你草场的羊发怒，如烟冒出呢？'),
('CUV', '诗篇', 19, 74, 2, '求你记念你古时所得来的会众，就是你所赎﹔作你产业支派的，并记念你向来所居住的锡安山。'),
('CUV', '诗篇', 19, 74, 3, '求你举步去看那日久荒凉之地，仇敌在圣所中所行的一切恶事。'),
('CUV', '诗篇', 19, 74, 4, '你的敌人在你会中吼叫；他们竖了自己的旗为记号。'),
('CUV', '诗篇', 19, 74, 5, '他们好像人扬起斧子，砍伐林中的树。'),
('CUV', '诗篇', 19, 74, 6, '圣所中一切雕刻的，他们现在用斧子锤子打坏了。'),
('CUV', '诗篇', 19, 74, 7, '他们用火焚烧你的圣所，亵渎你名的居所，拆毁到地。'),
('CUV', '诗篇', 19, 74, 8, '他们心里说：我们要尽行毁灭；他们就在遍地把神的会所都烧毁了。'),
('CUV', '诗篇', 19, 74, 9, '我们不见我们的标帜，不再有先知；我们内中也没有人知道这灾祸要到几时呢！'),
('CUV', '诗篇', 19, 74, 10, '神啊，敌人辱骂要到几时呢？仇敌亵渎你的名要到永远么？'),
('CUV', '诗篇', 19, 74, 11, '你为甚么缩回你的右手？求你从怀中伸出来，毁灭他们。'),
('CUV', '诗篇', 19, 74, 12, '神自古以来为我的王，在地上施行拯救。'),
('CUV', '诗篇', 19, 74, 13, '你曾用能力将海分开，将水中大鱼的头打破。'),
('CUV', '诗篇', 19, 74, 14, '你曾砸碎鳄鱼的头，把他给旷野的禽兽（禽兽：原文是民）为食物。'),
('CUV', '诗篇', 19, 74, 15, '你曾分裂磐石，水便成了溪河；你使长流的江河干了。'),
('CUV', '诗篇', 19, 74, 16, '白昼属你，黑夜也属你；亮光和日头是你所预备的。'),
('CUV', '诗篇', 19, 74, 17, '地的一切疆界是你所立的；夏天和冬天是你所定的。'),
('CUV', '诗篇', 19, 74, 18, '耶和华啊，仇敌辱骂，愚顽民亵渎了你的名，求你记念这事。'),
('CUV', '诗篇', 19, 74, 19, '不要将你斑鸠的性命交给野兽；不要永远忘记你困苦人的性命。'),
('CUV', '诗篇', 19, 74, 20, '求你顾念所立的约，因为地上黑暗之处都满了强暴的居所。'),
('CUV', '诗篇', 19, 74, 21, '不要叫受欺压的人蒙羞回去；要叫困苦穷乏的人赞美你的名。'),
('CUV', '诗篇', 19, 74, 22, '神啊，求你起来为自己伸诉！要记念愚顽人怎样终日辱骂你。'),
('CUV', '诗篇', 19, 74, 23, '不要忘记你敌人的声音；那起来敌你之人的喧哗时常上升。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 75, 1, '（亚萨的诗歌，交与伶长。调用休要毁坏。）神啊，我们称谢你，我们称谢你！因为你的名相近，人都述说你奇妙的作为。'),
('CUV', '诗篇', 19, 75, 2, '我到了所定的日期，必按正直施行审判。'),
('CUV', '诗篇', 19, 75, 3, '地和其上的居民都消化了；我曾立了地的柱子。（细拉）'),
('CUV', '诗篇', 19, 75, 4, '我对狂傲人说：不要行事狂傲！对凶恶人说：不要举角！'),
('CUV', '诗篇', 19, 75, 5, '不要把你们的角高举；不要挺著颈项说话。'),
('CUV', '诗篇', 19, 75, 6, '因为高举非从东，非从西，也非从南而来。'),
('CUV', '诗篇', 19, 75, 7, '惟有神断定；他使这人降卑，使那人升高。'),
('CUV', '诗篇', 19, 75, 8, '耶和华手里有杯，其中的酒起沫，杯内满了搀杂的酒；他倒出来，地上的恶人必都喝这酒的渣滓，而且喝尽。'),
('CUV', '诗篇', 19, 75, 9, '但我要宣扬，直到永远！我要歌颂雅各的神！'),
('CUV', '诗篇', 19, 75, 10, '恶人一切的角，我要砍断；惟有义人的角必被高举。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 76, 1, '（亚萨的诗歌，交与伶长。用丝弦的乐器。）在犹大，神为人所认识；在以色列，他的名为大。'),
('CUV', '诗篇', 19, 76, 2, '在撒冷有他的帐幕；在锡安有他的居所。'),
('CUV', '诗篇', 19, 76, 3, '他在那里折断弓上的火箭，并盾牌、刀剑，和争战的兵器。（细拉）'),
('CUV', '诗篇', 19, 76, 4, '你从有野食之山而来，有光华和荣美。'),
('CUV', '诗篇', 19, 76, 5, '心中勇敢的人都被抢夺；他们睡了长觉，没有一个英雄能措手。'),
('CUV', '诗篇', 19, 76, 6, '雅各的神啊，你的斥责一发，坐车的﹔骑马的都沉睡了。'),
('CUV', '诗篇', 19, 76, 7, '惟独你是可畏的！你怒气一发，谁能在你面前站得住呢？'),
('CUV', '诗篇', 19, 76, 8, '你从天上使人听判断。神起来施行审判，要救地上一切谦卑的人；那时地就惧怕而静默。（细拉）'),
('CUV', '诗篇', 19, 76, 9, 'a'),
('CUV', '诗篇', 19, 76, 10, '人的忿怒要成全你的荣美；人的余怒，你要禁止。'),
('CUV', '诗篇', 19, 76, 11, '你们许愿，当向耶和华─你们的神还愿；在他四面的人都当拿贡物献给那可畏的主。'),
('CUV', '诗篇', 19, 76, 12, '他要挫折王子的骄气；他向地上的君王显威可畏。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 77, 1, '（亚萨的诗，照耶杜顿的作法，交与伶长。）我要向神发声呼求；我向神发声，他必留心听我。'),
('CUV', '诗篇', 19, 77, 2, '我在患难之日寻求主；我在夜间不住地举手祷告；我的心不肯受安慰。'),
('CUV', '诗篇', 19, 77, 3, '我想念神，就烦燥不安；我沉吟悲伤，心便发昏。（细拉）'),
('CUV', '诗篇', 19, 77, 4, '你叫我不能闭眼；我烦乱不安，甚至不能说话。'),
('CUV', '诗篇', 19, 77, 5, '我追想古时之日，上古之年。'),
('CUV', '诗篇', 19, 77, 6, '我想起我夜间的歌曲，扪心自问；我心里也仔细省察。'),
('CUV', '诗篇', 19, 77, 7, '难道主要永远丢弃我，不再施恩么？'),
('CUV', '诗篇', 19, 77, 8, '难道他的慈爱永远穷尽，他的应许世世废弃么？'),
('CUV', '诗篇', 19, 77, 9, '难道神忘记开恩，因发怒就止住他的慈悲么？（细拉）'),
('CUV', '诗篇', 19, 77, 10, '我便说：这是我的懦弱，但我要追念至高者显出右手之年代。'),
('CUV', '诗篇', 19, 77, 11, '我要提说耶和华所行的；我要记念你古时的奇事。'),
('CUV', '诗篇', 19, 77, 12, '我也要思想你的经营，默念你的作为。'),
('CUV', '诗篇', 19, 77, 13, '神啊，你的作为是洁净的；有何神大如神呢？'),
('CUV', '诗篇', 19, 77, 14, '你是行奇事的神；你曾在列邦中彰显你的能力。'),
('CUV', '诗篇', 19, 77, 15, '你曾用你的膀臂赎了你的民，就是雅各和约瑟的子孙。（细拉）'),
('CUV', '诗篇', 19, 77, 16, '神啊，诸水见你，一见就都惊惶；深渊也都战抖。'),
('CUV', '诗篇', 19, 77, 17, '云中倒出水来；天空发出响声；你的箭也飞行四方。'),
('CUV', '诗篇', 19, 77, 18, '你的雷声在旋风中；电光照亮世界；大地战抖震动。'),
('CUV', '诗篇', 19, 77, 19, '你的道在海中；你的路在大水中；你的脚踪无人知道。'),
('CUV', '诗篇', 19, 77, 20, '你曾藉摩西和亚伦的手引导你的百姓，好像羊群一般。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 78, 1, '（亚萨的训诲诗。）我的民哪，你们要留心听我的训诲，侧耳听我口中的话。'),
('CUV', '诗篇', 19, 78, 2, '我要开口说比喻；我要说出古时的谜语，'),
('CUV', '诗篇', 19, 78, 3, '是我们所听见、所知道的，也是我们的祖宗告诉我们的。'),
('CUV', '诗篇', 19, 78, 4, '我们不将这些事向他们的子孙隐瞒，要将耶和华的美德和他的能力，并他奇妙的作为，述说给后代听。'),
('CUV', '诗篇', 19, 78, 5, '因为，他在雅各中立法度，在以色列中设律法；是他吩咐我们祖宗要传给子孙的，'),
('CUV', '诗篇', 19, 78, 6, '使将要生的后代子孙可以晓得；他们也要起来告诉他们的子孙，'),
('CUV', '诗篇', 19, 78, 7, '好叫他们仰望神，不忘记神的作为，惟要守他的命令。'),
('CUV', '诗篇', 19, 78, 8, '不要像他们的祖宗，是顽梗悖逆、居心不正之辈，向著神，心不诚实。'),
('CUV', '诗篇', 19, 78, 9, '以法莲的子孙带著兵器，拿著弓，临阵之日转身退后。'),
('CUV', '诗篇', 19, 78, 10, '他们不遵守神的约，不肯照他的律法行；'),
('CUV', '诗篇', 19, 78, 11, '又忘记他所行的和他显给他们奇妙的作为。'),
('CUV', '诗篇', 19, 78, 12, '他在埃及地，在琐安田，在他们祖宗的眼前施行奇事。'),
('CUV', '诗篇', 19, 78, 13, '他将海分裂，使他们过去，又叫水立起如垒。'),
('CUV', '诗篇', 19, 78, 14, '他白日用云彩，终夜用火光引导他们。'),
('CUV', '诗篇', 19, 78, 15, '他在旷野分裂磐石，多多地给他们水喝，如从深渊而出。'),
('CUV', '诗篇', 19, 78, 16, '他使水从磐石涌出，叫水如江河下流。'),
('CUV', '诗篇', 19, 78, 17, '他们却仍旧得罪他，在干燥之地悖逆至高者。'),
('CUV', '诗篇', 19, 78, 18, '他们心中试探神，随自己所欲的求食物，'),
('CUV', '诗篇', 19, 78, 19, '并且妄论神说：神在旷野岂能摆设筵席么？'),
('CUV', '诗篇', 19, 78, 20, '他曾击打磐石，使水涌出，成了江河；他还能赐粮食么？还能为他的百姓预备肉么？'),
('CUV', '诗篇', 19, 78, 21, '所以，耶和华听见就发怒；有烈火向雅各烧起；有怒气向以色列上腾；'),
('CUV', '诗篇', 19, 78, 22, '因为他们不信服神，不倚赖他的救恩。'),
('CUV', '诗篇', 19, 78, 23, '他却吩咐天空，又敞开天上的门，'),
('CUV', '诗篇', 19, 78, 24, '降吗哪，像雨给他们吃，将天上的粮食赐给他们。'),
('CUV', '诗篇', 19, 78, 25, '各人（或译：人）吃大能者的食物；他赐下粮食，使他们饱足。'),
('CUV', '诗篇', 19, 78, 26, '他领东风起在天空，又用能力引了南风来。'),
('CUV', '诗篇', 19, 78, 27, '他降肉，像雨在他们当中，多如尘土，又降飞鸟，多如海沙，'),
('CUV', '诗篇', 19, 78, 28, '落在他们的营中，在他们住处的四面。'),
('CUV', '诗篇', 19, 78, 29, '他们吃了，而且饱足；这样就随了他们所欲的。'),
('CUV', '诗篇', 19, 78, 30, '他们贪而无厌，食物还在他们口中的时候，'),
('CUV', '诗篇', 19, 78, 31, '神的怒气就向他们上腾，杀了他们内中的肥壮人，打倒以色列的少年人。'),
('CUV', '诗篇', 19, 78, 32, '虽是这样，他们仍旧犯罪，不信他奇妙的作为。'),
('CUV', '诗篇', 19, 78, 33, '因此，他叫他们的日子全归虚空，叫他们的年岁尽属惊恐。'),
('CUV', '诗篇', 19, 78, 34, '他杀他们的时候，他们才求问他，回心转意，切切地寻求神。'),
('CUV', '诗篇', 19, 78, 35, '他们也追念神是他们的磐石，至高的神是他们的救赎主。'),
('CUV', '诗篇', 19, 78, 36, '他们却用口谄媚他，用舌向他说谎。'),
('CUV', '诗篇', 19, 78, 37, '因他们的心向他不正，在他的约上也不忠心。'),
('CUV', '诗篇', 19, 78, 38, '但他有怜悯，赦免他们的罪孽，不灭绝他们，而且屡次消他的怒气，不发尽他的忿怒。'),
('CUV', '诗篇', 19, 78, 39, '他想到他们不过是血气，是一阵去而不返的风。'),
('CUV', '诗篇', 19, 78, 40, '他们在旷野悖逆他，在荒地叫他担忧，何其多呢！'),
('CUV', '诗篇', 19, 78, 41, '他们再三试探神，惹动以色列的圣者。'),
('CUV', '诗篇', 19, 78, 42, '他们不追念他的能力（原文是手）和赎他们脱离敌人的日子；'),
('CUV', '诗篇', 19, 78, 43, '他怎样在埃及地显神迹，在琐安田显奇事，'),
('CUV', '诗篇', 19, 78, 44, '把他们的江河并河的水都变为血，使他们不能喝。'),
('CUV', '诗篇', 19, 78, 45, '他叫苍蝇成群落在他们当中，嘬尽他们，又叫青蛙灭了他们，'),
('CUV', '诗篇', 19, 78, 46, '把他们的土产交给蚂蚱，把他们辛苦得来的交给蝗虫。'),
('CUV', '诗篇', 19, 78, 47, '他降冰雹打坏他们的葡萄树，下严霜打坏他们的桑树，'),
('CUV', '诗篇', 19, 78, 48, '又把他们的牲畜交给冰雹，把他们的群畜交给闪电。'),
('CUV', '诗篇', 19, 78, 49, '他使猛烈的怒气和忿怒、恼恨、苦难成了一群降灾的使者，临到他们。'),
('CUV', '诗篇', 19, 78, 50, '他为自己的怒气修平了路，将他们交给瘟疫，使他们死亡，'),
('CUV', '诗篇', 19, 78, 51, '在埃及击杀一切长子，在含的帐棚中击杀他们强壮时头生的。'),
('CUV', '诗篇', 19, 78, 52, '他却领出自己的民如羊，在旷野引他们如羊群。'),
('CUV', '诗篇', 19, 78, 53, '他领他们稳稳妥妥地，使他们不致害怕；海却淹没他们的仇敌。'),
('CUV', '诗篇', 19, 78, 54, '他带他们到自己圣地的边界，到他右手所得的这山地。'),
('CUV', '诗篇', 19, 78, 55, '他在他们面前赶出外邦人，用绳子将外邦的地量给他们为业，叫以色列支派的人住在他们的帐棚里。'),
('CUV', '诗篇', 19, 78, 56, '他们仍旧试探、悖逆至高的神，不守他的法度，'),
('CUV', '诗篇', 19, 78, 57, '反倒退后，行诡诈，像他们的祖宗一样；他们改变，如同翻背的弓。'),
('CUV', '诗篇', 19, 78, 58, '因他们的邱坛惹了他的怒气；因他们雕刻的偶像触动他的愤恨。'),
('CUV', '诗篇', 19, 78, 59, '神听见就发怒，极其憎恶以色列人。'),
('CUV', '诗篇', 19, 78, 60, '甚至他离弃示罗的帐幕，就是他在人间所搭的帐棚；'),
('CUV', '诗篇', 19, 78, 61, '又将他的约柜（原文是能力）交与人掳去，将他的荣耀交在敌人手中；'),
('CUV', '诗篇', 19, 78, 62, '并将他的百姓交与刀剑，向他的产业发怒。'),
('CUV', '诗篇', 19, 78, 63, '少年人被火烧灭；处女也无喜歌。'),
('CUV', '诗篇', 19, 78, 64, '祭司倒在刀下，寡妇却不哀哭。'),
('CUV', '诗篇', 19, 78, 65, '那时，主像世人睡醒，像勇士饮酒呼喊。'),
('CUV', '诗篇', 19, 78, 66, '他就打退了他的敌人，叫他们永蒙羞辱；'),
('CUV', '诗篇', 19, 78, 67, '并且他弃掉约瑟的帐棚，不拣选以法莲支派，'),
('CUV', '诗篇', 19, 78, 68, '却拣选犹大支派─他所喜爱的锡安山；'),
('CUV', '诗篇', 19, 78, 69, '盖造他的圣所，好像高峰，又像他建立永存之地；'),
('CUV', '诗篇', 19, 78, 70, '又拣选他的仆人大卫，从羊圈中将他召来，'),
('CUV', '诗篇', 19, 78, 71, '叫他不再跟从那些带奶的母羊，为要牧养自己的百姓雅各和自己的产业以色列。'),
('CUV', '诗篇', 19, 78, 72, '于是，他按心中的纯正牧养他们，用手中的巧妙引导他们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 79, 1, '（亚萨的诗。）神啊，外邦人进入你的产业，污秽你的圣殿，使耶路撒冷变成荒堆，'),
('CUV', '诗篇', 19, 79, 2, '把你仆人的尸首交与天空的飞鸟为食，把你圣民的肉交与地上的野兽，'),
('CUV', '诗篇', 19, 79, 3, '在耶路撒冷周围流他们的血如水，无人葬埋。'),
('CUV', '诗篇', 19, 79, 4, '我们成为邻国的羞辱，成为我们四围人的嗤笑讥刺。'),
('CUV', '诗篇', 19, 79, 5, '耶和华啊，这到几时呢？你要动怒到永远么？你的愤恨要如火焚烧么？'),
('CUV', '诗篇', 19, 79, 6, '愿你将你的忿怒倒在那不认识你的外邦和那不求告你名的国度。'),
('CUV', '诗篇', 19, 79, 7, '因为他们吞了雅各，把他的住处变为荒场。'),
('CUV', '诗篇', 19, 79, 8, '求你不要记念我们先祖的罪孽，向我们追讨；愿你的慈悲快迎著我们，因为我们落到极卑微的地步。'),
('CUV', '诗篇', 19, 79, 9, '拯救我们的神啊，求你因你名的荣耀帮助我们！为你名的缘故搭救我们，赦免我们的罪。'),
('CUV', '诗篇', 19, 79, 10, '为何容外邦人说他们的神在哪里呢？愿你使外邦人知道你在我们眼前伸你仆人流血的冤。'),
('CUV', '诗篇', 19, 79, 11, '愿被囚之人的叹息达到你面前；愿你按你的大能力存留那些将要死的人。'),
('CUV', '诗篇', 19, 79, 12, '主啊，愿你将我们邻邦所羞辱你的羞辱加七倍归到他们身上。'),
('CUV', '诗篇', 19, 79, 13, '这样，你的民，你草场的羊，要称谢你，直到永远；要述说赞美你的话，直到万代。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 80, 1, '（亚萨的诗，交与伶长。调用为证的百合花。）领约瑟如领羊群之以色列的牧者啊，求你留心听！坐在二基路伯上的啊，求你发出光来！'),
('CUV', '诗篇', 19, 80, 2, '在以法莲、便雅悯、玛拿西前面施展你的大能，来救我们。'),
('CUV', '诗篇', 19, 80, 3, '神啊，求你使我们回转（或译：复兴），使你的脸发光，我们便要得救！'),
('CUV', '诗篇', 19, 80, 4, '耶和华─万军之神啊，你向你百姓的祷告发怒，要到几时呢？'),
('CUV', '诗篇', 19, 80, 5, '你以眼泪当食物给他们吃，又多量出眼泪给他们喝。'),
('CUV', '诗篇', 19, 80, 6, '你使邻邦因我们纷争；我们的仇敌彼此戏笑。'),
('CUV', '诗篇', 19, 80, 7, '万军之神啊，求你使我们回转，使你的脸发光，我们便要得救！'),
('CUV', '诗篇', 19, 80, 8, '你从埃及挪出一棵葡萄树，赶出外邦人，把这树栽上。'),
('CUV', '诗篇', 19, 80, 9, '你在这树根前预备了地方，他就深深扎根，爬满了地。'),
('CUV', '诗篇', 19, 80, 10, '他的影子遮满了山，枝子好像佳美的香柏树。'),
('CUV', '诗篇', 19, 80, 11, '他发出枝子，长到大海，发出蔓子，延到大河。'),
('CUV', '诗篇', 19, 80, 12, '你为何拆毁这树的篱笆，任凭一切过路的人摘取？'),
('CUV', '诗篇', 19, 80, 13, '林中出来的野猪把他糟踏；野地的走兽拿他当食物。'),
('CUV', '诗篇', 19, 80, 14, '万军之神啊，求你回转！从天上垂看，眷顾这葡萄树，'),
('CUV', '诗篇', 19, 80, 15, '保护你右手所栽的和你为自已所坚固的枝子。'),
('CUV', '诗篇', 19, 80, 16, '这树已经被火焚烧，被刀砍伐；他们因你脸上的怒容就灭亡了。'),
('CUV', '诗篇', 19, 80, 17, '愿你的手扶持你右边的人，就是你为自已所坚固的人子。'),
('CUV', '诗篇', 19, 80, 18, '这样，我们便不退后离开你；求你救活我们，我们就要求告你的名。'),
('CUV', '诗篇', 19, 80, 19, '耶和华─万军之神啊，求你使我们回转，使你的脸发光，我们便要得救！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 81, 1, '（亚萨的诗，交与伶长。用迦特乐器。）你们当向神─我们的力量大声欢呼，向雅各的神发声欢乐！'),
('CUV', '诗篇', 19, 81, 2, '唱起诗歌，打手鼓，弹美琴与瑟。'),
('CUV', '诗篇', 19, 81, 3, '当在月朔并月望─我们过节的日期吹角，'),
('CUV', '诗篇', 19, 81, 4, '因这是为以色列定的律例，是雅各神的典章。'),
('CUV', '诗篇', 19, 81, 5, '他去攻击埃及地的时候，在约瑟中间立此为证。我在那里听见我所不明白的言语：'),
('CUV', '诗篇', 19, 81, 6, '神说：我使你的肩得脱重担，你的手放下筐子。'),
('CUV', '诗篇', 19, 81, 7, '你在急难中呼求，我就搭救你；我在雷的隐密处应允你，在米利巴水那里试验你。（细拉）'),
('CUV', '诗篇', 19, 81, 8, '我的民哪，你当听，我要劝戒你；以色列啊，甚愿你肯听从我。'),
('CUV', '诗篇', 19, 81, 9, '在你当中，不可有别的神；外邦的神，你也不可下拜。'),
('CUV', '诗篇', 19, 81, 10, '我是耶和华─你的神，曾把你从埃及地领上来；你要大大张口，我就给你充满。'),
('CUV', '诗篇', 19, 81, 11, '无奈，我的民不听我的声音；以色列全不理我。'),
('CUV', '诗篇', 19, 81, 12, '我便任凭他们心里刚硬，随自己的计谋而行。'),
('CUV', '诗篇', 19, 81, 13, '甚愿我的民肯听从我，以色列肯行我的道，'),
('CUV', '诗篇', 19, 81, 14, '我便速速治服他们的仇敌，反手攻击他们的敌人。'),
('CUV', '诗篇', 19, 81, 15, '恨耶和华的人必来投降，但他的百姓必永久长存。'),
('CUV', '诗篇', 19, 81, 16, '他也必拿上好的麦子给他们吃，又拿从磐石出的蜂蜜叫他们饱足。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 82, 1, '（亚萨的诗。）神站在有权力者的会中，在诸神中行审判，'),
('CUV', '诗篇', 19, 82, 2, '说：你们审判不秉公义，徇恶人的情面，要到几时呢？（细拉）'),
('CUV', '诗篇', 19, 82, 3, '你们当为贫寒的人和孤儿伸冤；当为困苦和穷乏的人施行公义。'),
('CUV', '诗篇', 19, 82, 4, '当保护贫寒和穷乏的人，救他们脱离恶人的手。'),
('CUV', '诗篇', 19, 82, 5, '你们仍不知道，也不明白，在黑暗中走来走去；地的根基都摇动了。'),
('CUV', '诗篇', 19, 82, 6, '我曾说：你们是神，都是至高者的儿子。'),
('CUV', '诗篇', 19, 82, 7, '然而，你们要死，与世人一样，要仆倒，像王子中的一位。'),
('CUV', '诗篇', 19, 82, 8, '神啊，求你起来审判世界，因为你要得万邦为业。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 83, 1, '（亚萨的诗歌。）神啊，求你不要静默！神啊，求你不要闭口，也不要不作声！'),
('CUV', '诗篇', 19, 83, 2, '因为你的仇敌喧嚷，恨你的抬起头来。'),
('CUV', '诗篇', 19, 83, 3, '他们同谋奸诈要害你的百姓，彼此商议要害你所隐藏的人。'),
('CUV', '诗篇', 19, 83, 4, '他们说：来罢，我们将他们剪灭，使他们不再成国！使以色列的名不再被人记念！'),
('CUV', '诗篇', 19, 83, 5, '他们同心商议，彼此结盟，要抵挡你，'),
('CUV', '诗篇', 19, 83, 6, '就是住帐棚的以东人和以实玛利人，摩押和夏甲人，'),
('CUV', '诗篇', 19, 83, 7, '迦巴勒、亚扪，和亚玛力、非利士并推罗的居民。'),
('CUV', '诗篇', 19, 83, 8, '亚述也与他们连合；他们作罗得子孙的帮手。（细拉）'),
('CUV', '诗篇', 19, 83, 9, '求你待他们，如待米甸，如在基顺河待西西拉和耶宾一样。'),
('CUV', '诗篇', 19, 83, 10, '他们在隐多珥灭亡，成了地上的粪土。'),
('CUV', '诗篇', 19, 83, 11, '求你叫他们的首领像俄立和西伊伯，叫他们的王子都像西巴和撒慕拿。'),
('CUV', '诗篇', 19, 83, 12, '他们说：我们要得神的住处，作为自己的产业。'),
('CUV', '诗篇', 19, 83, 13, '我的神啊，求你叫他们像旋风的尘土，像风前的碎秸。'),
('CUV', '诗篇', 19, 83, 14, '火怎样焚烧树林，火燄怎样烧著山岭，'),
('CUV', '诗篇', 19, 83, 15, '求你也照样用狂风追赶他们，用暴雨恐吓他们。'),
('CUV', '诗篇', 19, 83, 16, '愿你使他们满面羞耻，好叫他们寻求你─耶和华的名！'),
('CUV', '诗篇', 19, 83, 17, '愿他们永远羞愧惊惶！愿他们惭愧灭亡！'),
('CUV', '诗篇', 19, 83, 18, '使他们知道：惟独你─名为耶和华的─是全地以上的至高者！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 84, 1, '（可拉后裔的诗，交与伶长。用迦特乐器。）万军之耶和华啊，你的居所何等可爱！'),
('CUV', '诗篇', 19, 84, 2, '我羡慕渴想耶和华的院宇；我的心肠，我的肉体向永生神呼吁（或译：欢呼）。'),
('CUV', '诗篇', 19, 84, 3, '万军之耶和华─我的王，我的神啊，在你祭坛那里，麻雀为自己找著房屋，燕子为自己找著菢雏之窝。'),
('CUV', '诗篇', 19, 84, 4, '如此住在你殿中的便为有福！他们仍要赞美你。（细拉）'),
('CUV', '诗篇', 19, 84, 5, '靠你有力量、心中想往锡安大道的，这人便为有福！'),
('CUV', '诗篇', 19, 84, 6, '他们经过流泪谷，叫这谷变为泉源之地；并有秋雨之福盖满了全谷。'),
('CUV', '诗篇', 19, 84, 7, '他们行走，力上加力，各人到锡安朝见神。'),
('CUV', '诗篇', 19, 84, 8, '耶和华─万军之神啊，求你听我的祷告！雅各的神啊，求你留心听！（细拉）'),
('CUV', '诗篇', 19, 84, 9, '神啊，你是我们的盾牌；求你垂顾观看你受膏者的面！'),
('CUV', '诗篇', 19, 84, 10, '在你的院宇住一日，胜似在别处住千日；宁可在我神殿中看门，不愿住在恶人的帐棚里。'),
('CUV', '诗篇', 19, 84, 11, '因为耶和华─神是日头，是盾牌，要赐下恩惠和荣耀。他未尝留下一样好处不给那些行动正直的人。'),
('CUV', '诗篇', 19, 84, 12, '万军之耶和华啊，倚靠你的人便为有福！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 85, 1, '（可拉后裔的诗，交与伶长。）耶和华啊，你已经向你的地施恩，救回被掳的雅各。'),
('CUV', '诗篇', 19, 85, 2, '你赦免了你百姓的罪孽，遮盖了他们一切的过犯。（细拉）'),
('CUV', '诗篇', 19, 85, 3, '你收转了所发的忿怒和你猛烈的怒气。'),
('CUV', '诗篇', 19, 85, 4, '拯救我们的神啊，求你使我们回转，叫你的恼恨向我们止息。'),
('CUV', '诗篇', 19, 85, 5, '你要向我们发怒到永远么？你要将你的怒气延留到万代么？'),
('CUV', '诗篇', 19, 85, 6, '你不再将我们救活，使你的百姓靠你欢喜么？'),
('CUV', '诗篇', 19, 85, 7, '耶和华啊，求你使我们得见你的慈爱，又将你的救恩赐给我们。'),
('CUV', '诗篇', 19, 85, 8, '我要听神─耶和华所说的话；因为他必应许将平安赐给他的百姓─他的圣民；他们却不可再转去妄行。'),
('CUV', '诗篇', 19, 85, 9, '他的救恩诚然与敬畏他的人相近，叫荣耀住在我们的地上。'),
('CUV', '诗篇', 19, 85, 10, '慈爱和诚实彼此相遇；公义和平安彼此相亲。'),
('CUV', '诗篇', 19, 85, 11, '诚实从地而生；公义从天而现。'),
('CUV', '诗篇', 19, 85, 12, '耶和华必将好处赐给我们；我们的地也要多出土产。'),
('CUV', '诗篇', 19, 85, 13, '公义要行在他面前，叫他的脚踪成为可走的路。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 86, 1, '（大卫的祈祷。）耶和华啊，求你侧耳应允我，因我是困苦穷乏的。'),
('CUV', '诗篇', 19, 86, 2, '求你保存我的性命，因我是虔诚人。我的神啊，求你拯救这倚靠你的仆人！'),
('CUV', '诗篇', 19, 86, 3, '主啊，求你怜悯我，因我终日求告你。'),
('CUV', '诗篇', 19, 86, 4, '主啊，求你使仆人心里欢喜，因为我的心仰望你。'),
('CUV', '诗篇', 19, 86, 5, '主啊，你本为良善，乐意饶恕人，有丰盛的慈爱赐给凡求告你的人。'),
('CUV', '诗篇', 19, 86, 6, '耶和华啊，求你留心听我的祷告，垂听我恳求的声音。'),
('CUV', '诗篇', 19, 86, 7, '我在患难之日要求告你，因为你必应允我。'),
('CUV', '诗篇', 19, 86, 8, '主啊，诸神之中没有可比你的；你的作为也无可比。'),
('CUV', '诗篇', 19, 86, 9, '主啊，你所造的万民都要来敬拜你；他们也要荣耀你的名。'),
('CUV', '诗篇', 19, 86, 10, '因你为大，且行奇妙的事；惟独你是神。'),
('CUV', '诗篇', 19, 86, 11, '耶和华啊，求你将你的道指教我；我要照你的真理行；求你使我专心敬畏你的名！'),
('CUV', '诗篇', 19, 86, 12, '主─我的神啊，我要一心称赞你；我要荣耀你的名，直到永远。'),
('CUV', '诗篇', 19, 86, 13, '因为，你向我发的慈爱是大的；你救了我的灵魂免入极深的阴间。'),
('CUV', '诗篇', 19, 86, 14, '神啊，骄傲的人起来攻击我，又有一党强横的人寻索我的命；他们没有将你放在眼中。'),
('CUV', '诗篇', 19, 86, 15, '主啊，你是有怜悯有恩典的神，不轻易发怒，并有丰盛的慈爱和诚实。'),
('CUV', '诗篇', 19, 86, 16, '求你向我转脸，怜恤我，将你的力量赐给仆人，救你婢女的儿子。'),
('CUV', '诗篇', 19, 86, 17, '求你向我显出恩待我的凭据，叫恨我的人看见便羞愧，因为你─耶和华帮助我，安慰我。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 87, 1, '（可拉后裔的诗歌。）耶和华所立的根基在圣山上。'),
('CUV', '诗篇', 19, 87, 2, '他爱锡安的门，胜于爱雅各一切的住处。'),
('CUV', '诗篇', 19, 87, 3, '神的城啊，有荣耀的事乃指著你说的。（细拉）'),
('CUV', '诗篇', 19, 87, 4, '我要提起拉哈伯和巴比伦人，是在认识我之中的；看哪，非利士和推罗并古实人，个个生在那里。'),
('CUV', '诗篇', 19, 87, 5, '论到锡安，必说：这一个、那一个都生在其中，而且至高者必亲自坚立这城。'),
('CUV', '诗篇', 19, 87, 6, '当耶和华记录万民的时候，他要点出这一个生在那里。（细拉）'),
('CUV', '诗篇', 19, 87, 7, '歌唱的，跳舞的，都要说：我的泉源都在你里面。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 88, 1, '（可拉后裔的诗歌，就是以斯拉人希幔的训诲诗，交与伶长。调用麻哈拉利暗俄。）耶和华─拯救我的神啊，我昼夜在你面前呼吁。'),
('CUV', '诗篇', 19, 88, 2, '愿我的祷告达到你面前；求你侧耳听我的呼求！'),
('CUV', '诗篇', 19, 88, 3, '因为我心里满了患难；我的性命临近阴间。'),
('CUV', '诗篇', 19, 88, 4, '我算和下坑的人同列，如同无力（或译：没有帮助）的人一样。'),
('CUV', '诗篇', 19, 88, 5, '我被丢在死人中，好像被杀的人躺在坟墓里。他们是你不再记念的，与你隔绝了。'),
('CUV', '诗篇', 19, 88, 6, '你把我放在极深的坑里，在黑暗地方，在深处。'),
('CUV', '诗篇', 19, 88, 7, '你的忿怒重压我身；你用一切的波浪困住我。（细拉）'),
('CUV', '诗篇', 19, 88, 8, '你把我所认识的隔在远处，使我为他们所憎恶；我被拘困，不得出来。'),
('CUV', '诗篇', 19, 88, 9, '我的眼睛因困苦而干瘪。耶和华啊，我天天求告你，向你举手。'),
('CUV', '诗篇', 19, 88, 10, '你岂要行奇事给死人看么？难道阴魂还能起来称赞你么？（细拉）'),
('CUV', '诗篇', 19, 88, 11, '岂能在坟墓里述说你的慈爱么？岂能在灭亡中述说你的信实么？'),
('CUV', '诗篇', 19, 88, 12, '你的奇事岂能在幽暗里被知道么？你的公义岂能在忘记之地被知道么？'),
('CUV', '诗篇', 19, 88, 13, '耶和华啊，我呼求你；我早晨的祷告要达到你面前。'),
('CUV', '诗篇', 19, 88, 14, '耶和华啊，你为何丢弃我？为何掩面不顾我？'),
('CUV', '诗篇', 19, 88, 15, '我自幼受苦，几乎死亡；我受你的惊恐，甚至慌张。'),
('CUV', '诗篇', 19, 88, 16, '你的烈怒漫过我身；你的惊吓把我剪除。'),
('CUV', '诗篇', 19, 88, 17, '这些终日如水环绕我，一齐都来围困我。'),
('CUV', '诗篇', 19, 88, 18, '你把我的良朋密友隔在远处，使我所认识的人进入黑暗里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 89, 1, '（以斯拉人以探的训诲诗。）我要歌唱耶和华的慈爱，直到永远；我要用口将你的信实传与万代。'),
('CUV', '诗篇', 19, 89, 2, '因我曾说：你的慈悲必建立到永远；你的信实必坚立在天上。'),
('CUV', '诗篇', 19, 89, 3, '我与我所拣选的人立了约，向我的仆人大卫起了誓：'),
('CUV', '诗篇', 19, 89, 4, '我要建立你的后裔，直到永远；要建立你的宝座，直到万代。（细拉）'),
('CUV', '诗篇', 19, 89, 5, '耶和华啊，诸天要称赞你的奇事；在圣者的会中，要称赞你的信实。'),
('CUV', '诗篇', 19, 89, 6, '在天空谁能比耶和华呢？神的众子中，谁能像耶和华呢？'),
('CUV', '诗篇', 19, 89, 7, '他在圣者的会中，是大有威严的神，比一切在他四围的更可畏惧。'),
('CUV', '诗篇', 19, 89, 8, '耶和华─万军之神啊，哪一个大能者像你耶和华？你的信实是在你的四围。'),
('CUV', '诗篇', 19, 89, 9, '你管辖海的狂傲；波浪翻腾，你就使他平静了。'),
('CUV', '诗篇', 19, 89, 10, '你打碎了拉哈伯，似乎是已杀的人；你用有能的膀臂打散了你的仇敌。'),
('CUV', '诗篇', 19, 89, 11, '天属你，地也属你；世界和其中所充满的都为你所建立。'),
('CUV', '诗篇', 19, 89, 12, '南北为你所创造；他泊和黑门都因你的名欢呼。'),
('CUV', '诗篇', 19, 89, 13, '你有大能的膀臂；你的手有力，你的右手也高举。'),
('CUV', '诗篇', 19, 89, 14, '公义和公平是你宝座的根基；慈爱和诚实行在你前面。'),
('CUV', '诗篇', 19, 89, 15, '知道向你欢呼的，那民是有福的！耶和华啊，他们在你脸上的末毼行走。'),
('CUV', '诗篇', 19, 89, 16, '他们因你的名终日欢乐，因你的公义得以高举。'),
('CUV', '诗篇', 19, 89, 17, '你是他们力量的荣耀；因为你喜悦我们，我们的角必被高举。'),
('CUV', '诗篇', 19, 89, 18, '我们的盾牌属耶和华；我们的王属以色列的圣者。'),
('CUV', '诗篇', 19, 89, 19, '当时，你在异象中晓谕你的圣民，说：我已把救助之力加在那有能者的身上；我高举那从民中所拣选的。'),
('CUV', '诗篇', 19, 89, 20, '我寻得我的仆人大卫，用我的圣膏膏他。'),
('CUV', '诗篇', 19, 89, 21, '我的手必使他坚立；我的膀臂也必坚固他。'),
('CUV', '诗篇', 19, 89, 22, '仇敌必不勒索他；凶恶之子也不苦害他。'),
('CUV', '诗篇', 19, 89, 23, '我要在他面前打碎他的敌人，击杀那恨他的人。'),
('CUV', '诗篇', 19, 89, 24, '只是我的信实和我的慈爱要与他同在；因我的名，他的角必被高举。'),
('CUV', '诗篇', 19, 89, 25, '我要使他的左手伸到海上，右手伸到河上。'),
('CUV', '诗篇', 19, 89, 26, '他要称呼我说：你是我的父，是我的神，是拯救我的磐石。'),
('CUV', '诗篇', 19, 89, 27, '我也要立他为长子，为世上最高的君王。'),
('CUV', '诗篇', 19, 89, 28, '我要为他存留我的慈爱，直到永远；我与他立的约必要坚定。'),
('CUV', '诗篇', 19, 89, 29, '我也要使他的后裔存到永远，使他的宝座如天之久。'),
('CUV', '诗篇', 19, 89, 30, '倘若他的子孙离弃我的律法，不照我的典章行，'),
('CUV', '诗篇', 19, 89, 31, '背弃我的律例，不遵守我的诫命，'),
('CUV', '诗篇', 19, 89, 32, '我就要用杖责罚他们的过犯，用鞭责罚他们的罪孽。'),
('CUV', '诗篇', 19, 89, 33, '只是我必不将我的慈爱全然收回，也必不叫我的信实废弃。'),
('CUV', '诗篇', 19, 89, 34, '我必不背弃我的约，也不改变我口中所出的。'),
('CUV', '诗篇', 19, 89, 35, '我一次指著自己的圣洁起誓：我决不向大卫说谎！'),
('CUV', '诗篇', 19, 89, 36, '他的后裔要存到永远；他的宝座在我面前如日之恒一般，'),
('CUV', '诗篇', 19, 89, 37, '又如月亮永远坚立，如天上确实的见证。（细拉）'),
('CUV', '诗篇', 19, 89, 38, '但你恼怒你的受膏者，就丢掉弃绝他。'),
('CUV', '诗篇', 19, 89, 39, '你厌恶了与仆人所立的约，将他的冠冕践踏于地。'),
('CUV', '诗篇', 19, 89, 40, '你拆毁了他一切的篱笆，使他的保障变为荒场。'),
('CUV', '诗篇', 19, 89, 41, '凡过路的人都抢夺他；他成为邻邦的羞辱。'),
('CUV', '诗篇', 19, 89, 42, '你高举了他敌人的右手；你叫他一切的仇敌欢喜。'),
('CUV', '诗篇', 19, 89, 43, '你叫他的刀剑卷刃，叫他在争战之中站立不住。'),
('CUV', '诗篇', 19, 89, 44, '你使他的光辉止息，将他的宝座推倒于地。'),
('CUV', '诗篇', 19, 89, 45, '你减少他青年的日子，又使他蒙羞。（细拉）'),
('CUV', '诗篇', 19, 89, 46, '耶和华啊，这要到几时呢？你要将自己隐藏到永远么？你的忿怒如火焚烧要到几时呢？'),
('CUV', '诗篇', 19, 89, 47, '求你想念我的时候是何等的短少；你创造世人，要使他们归何等的虚空呢？'),
('CUV', '诗篇', 19, 89, 48, '谁能常活免死、救他的灵魂脱离阴间的权柄呢？（细拉）'),
('CUV', '诗篇', 19, 89, 49, '主啊，你从前凭你的信实向大卫立誓要施行的慈爱在哪里呢？'),
('CUV', '诗篇', 19, 89, 50, '主啊，求你记念仆人们所受的羞辱，记念我怎样将一切强盛民的羞辱存在我怀里。'),
('CUV', '诗篇', 19, 89, 51, '耶和华啊，你的仇敌用这羞辱羞辱了你的仆人，羞辱了你受膏者的脚踪。'),
('CUV', '诗篇', 19, 89, 52, '耶和华是应当称颂的，直到永远。阿们！阿们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 90, 1, '（神人摩西的祈祷）主啊，你世世代代作我们的居所。'),
('CUV', '诗篇', 19, 90, 2, '诸山未曾生出，地与世界你未曾造成，从亘古到永远，你是神。'),
('CUV', '诗篇', 19, 90, 3, '你使人归于尘土，说：你们世人要归回。'),
('CUV', '诗篇', 19, 90, 4, '在你看来，千年如已过的昨日，又如夜间的一更。'),
('CUV', '诗篇', 19, 90, 5, '你叫他们如水冲去；他们如睡一觉。早晨，他们如生长的草，'),
('CUV', '诗篇', 19, 90, 6, '早晨发芽生长，晚上割下枯干。'),
('CUV', '诗篇', 19, 90, 7, '我们因你的怒气而消灭，因你的忿怒而惊惶。'),
('CUV', '诗篇', 19, 90, 8, '你将我们的罪孽摆在你面前，将我们的隐恶摆在你面光之中。'),
('CUV', '诗篇', 19, 90, 9, '我们经过的日子都在你震怒之下；我们度尽的年岁好像一声叹息。'),
('CUV', '诗篇', 19, 90, 10, '我们一生的年日是七十岁，若是强壮可到八十岁；但其中所矜夸的不过是劳苦愁烦，转眼成空，我们便如飞而去。'),
('CUV', '诗篇', 19, 90, 11, '谁晓得你怒气的权势？谁按著你该受的敬畏晓得你的忿怒呢？'),
('CUV', '诗篇', 19, 90, 12, '求你指教我们怎样数算自己的日子，好叫我们得著智慧的心。'),
('CUV', '诗篇', 19, 90, 13, '耶和华啊，我们要等到几时呢？求你转回，为你的仆人后悔。'),
('CUV', '诗篇', 19, 90, 14, '求你使我们早早饱得你的慈爱，好叫我们一生一世欢呼喜乐。'),
('CUV', '诗篇', 19, 90, 15, '求你照著你使我们受苦的日子，和我们遭难的年岁，叫我们喜乐。'),
('CUV', '诗篇', 19, 90, 16, '愿你的作为向你仆人显现；愿你的荣耀向他们子孙显明。'),
('CUV', '诗篇', 19, 90, 17, '愿主─我们神的荣美归于我们身上。愿你坚立我们手所做的工；我们手所做的工，愿你坚立。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 91, 1, '住在至高者隐密处的，必住在全能者的荫下。'),
('CUV', '诗篇', 19, 91, 2, '我要论到耶和华说：他是我的避难所，是我的山寨，是我的神，是我所倚靠的。'),
('CUV', '诗篇', 19, 91, 3, '他必救你脱离捕鸟人的网罗和毒害的瘟疫。'),
('CUV', '诗篇', 19, 91, 4, '他必用自己的翎毛遮蔽你；你要投靠在他的翅膀底下；他的诚实是大小的盾牌。'),
('CUV', '诗篇', 19, 91, 5, '你必不怕黑夜的惊骇，或是白日飞的箭，'),
('CUV', '诗篇', 19, 91, 6, '也不怕黑夜行的瘟疫，或是午间灭人的毒病。'),
('CUV', '诗篇', 19, 91, 7, '虽有千人仆倒在你旁边，万人仆倒在你右边，这灾却不得临近你。'),
('CUV', '诗篇', 19, 91, 8, '你惟亲眼观看，见恶人遭报。'),
('CUV', '诗篇', 19, 91, 9, '耶和华是我的避难所；你已将至高者当你的居所，'),
('CUV', '诗篇', 19, 91, 10, '祸患必不临到你，灾害也不挨近你的帐棚。'),
('CUV', '诗篇', 19, 91, 11, '因他要为你吩咐他的使者，在你行的一切道路上保护你。'),
('CUV', '诗篇', 19, 91, 12, '他们要用手托著你，免得你的脚碰在石头上。'),
('CUV', '诗篇', 19, 91, 13, '你要踹在狮子和虺蛇的身上，践踏少壮狮子和大蛇。'),
('CUV', '诗篇', 19, 91, 14, '神说：因为他专心爱我，我就要搭救他；因为他知道我的名，我要把他安置在高处。'),
('CUV', '诗篇', 19, 91, 15, '他若求告我，我就应允他；他在急难中，我要与他同在；我要搭救他，使他尊贵。'),
('CUV', '诗篇', 19, 91, 16, '我要使他足享长寿，将我的救恩显明给他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 92, 1, '（安息日的诗歌。）称谢耶和华！歌颂你至高者的名！'),
('CUV', '诗篇', 19, 92, 2, '用十弦的乐器和瑟，用琴弹幽雅的声音，早晨传扬你的慈爱；每夜传扬你的信实。这本为美事。'),
('CUV', '诗篇', 19, 92, 3, 'a'),
('CUV', '诗篇', 19, 92, 4, '因你─耶和华藉著你的作为叫我高兴，我要因你手的工作欢呼。'),
('CUV', '诗篇', 19, 92, 5, '耶和华啊，你的工作何其大！你的心思极其深！'),
('CUV', '诗篇', 19, 92, 6, '畜类人不晓得；愚顽人也不明白。'),
('CUV', '诗篇', 19, 92, 7, '恶人茂盛如草，一切作孽之人发旺的时候，正是他们要灭亡，直到永远。'),
('CUV', '诗篇', 19, 92, 8, '惟你─耶和华是至高，直到永远。'),
('CUV', '诗篇', 19, 92, 9, '耶和华啊，你的仇敌都要灭亡；一切作孽的也要离散。'),
('CUV', '诗篇', 19, 92, 10, '你却高举了我的角，如野牛的角；我是被新油膏了的。'),
('CUV', '诗篇', 19, 92, 11, '我眼睛看见仇敌遭报；我耳朵听见那些起来攻击我的恶人受罚。'),
('CUV', '诗篇', 19, 92, 12, '义人要发旺如棕树，生长如利巴嫩的香柏树。'),
('CUV', '诗篇', 19, 92, 13, '他们栽于耶和华的殿中，发旺在我们神的院里。'),
('CUV', '诗篇', 19, 92, 14, '他们年老的时候仍要结果子，要满了汁浆而常发青，'),
('CUV', '诗篇', 19, 92, 15, '好显明耶和华是正直的。他是我的磐石，在他毫无不义。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 93, 1, '耶和华作王！他以威严为衣穿上；耶和华以能力为衣，以能力束腰，世界就坚定，不得动摇。'),
('CUV', '诗篇', 19, 93, 2, '你的宝座从太初立定；你从亘古就有。'),
('CUV', '诗篇', 19, 93, 3, '耶和华啊，大水扬起，大水发声，波浪澎湃。'),
('CUV', '诗篇', 19, 93, 4, '耶和华在高处大有能力，胜过诸水的响声，洋海的大浪。'),
('CUV', '诗篇', 19, 93, 5, '耶和华啊，你的法度最的确；你的殿永称为圣，是合宜的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 94, 1, '耶和华啊，你是伸冤的神；伸冤的神啊，求你发出光来！'),
('CUV', '诗篇', 19, 94, 2, '审判世界的主啊，求你挺身而立，使骄傲人受应得的报应！'),
('CUV', '诗篇', 19, 94, 3, '耶和华啊，恶人夸胜要到几时呢？要到几时呢？'),
('CUV', '诗篇', 19, 94, 4, '他们絮絮叨叨说傲慢的话；一切作孽的人都自己夸张。'),
('CUV', '诗篇', 19, 94, 5, '耶和华啊，他们强压你的百姓，苦害你的产业。'),
('CUV', '诗篇', 19, 94, 6, '他们杀死寡妇和寄居的，又杀害孤儿。'),
('CUV', '诗篇', 19, 94, 7, '他们说：耶和华必不看见；雅各的神必不思念。'),
('CUV', '诗篇', 19, 94, 8, '你们民间的畜类人当思想；你们愚顽人到几时才有智慧呢？'),
('CUV', '诗篇', 19, 94, 9, '造耳朵的，难道自己不听见么？造眼睛的，难道自己不看见么？'),
('CUV', '诗篇', 19, 94, 10, '管教列邦的，就是叫人得知识的，难道自己不惩治人么？'),
('CUV', '诗篇', 19, 94, 11, '耶和华知道人的意念是虚妄的。'),
('CUV', '诗篇', 19, 94, 12, '耶和华啊，你所管教、用律法所教训的人是有福的！'),
('CUV', '诗篇', 19, 94, 13, '你使他在遭难的日子得享平安；惟有恶人陷在所挖的坑中。'),
('CUV', '诗篇', 19, 94, 14, '因为耶和华必不丢弃他的百姓，也不离弃他的产业。'),
('CUV', '诗篇', 19, 94, 15, '审判要转向公义；心里正直的，必都随从。'),
('CUV', '诗篇', 19, 94, 16, '谁肯为我起来攻击作恶的？谁肯为我站起抵挡作孽的？'),
('CUV', '诗篇', 19, 94, 17, '若不是耶和华帮助我，我就住在寂静之中了。'),
('CUV', '诗篇', 19, 94, 18, '我正说我失了脚，耶和华啊，那时你的慈爱扶助我。'),
('CUV', '诗篇', 19, 94, 19, '我心里多忧多疑，你安慰我，就使我欢乐。'),
('CUV', '诗篇', 19, 94, 20, '那藉著律例架弄残害、在位上行奸恶的，岂能与你相交么？'),
('CUV', '诗篇', 19, 94, 21, '他们大家聚集攻击义人，将无辜的人定为死罪。'),
('CUV', '诗篇', 19, 94, 22, '但耶和华向来作了我的高台；我的神作了我投靠的磐石。'),
('CUV', '诗篇', 19, 94, 23, '他叫他们的罪孽归到他们身上。他们正在行恶之中，他要剪除他们；耶和华─我们的神要把他们剪除。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 95, 1, '来啊，我们要向耶和华歌唱，向拯救我们的磐石欢呼！'),
('CUV', '诗篇', 19, 95, 2, '我们要来感谢他，用诗歌向他欢呼！'),
('CUV', '诗篇', 19, 95, 3, '因耶和华为大神，为大王，超乎万神之上。'),
('CUV', '诗篇', 19, 95, 4, '地的深处在他手中；山的高峰也属他。'),
('CUV', '诗篇', 19, 95, 5, '海洋属他，是他造的；旱地也是他手造成的。'),
('CUV', '诗篇', 19, 95, 6, '来啊，我们要屈身敬拜，在造我们的耶和华面前跪下。'),
('CUV', '诗篇', 19, 95, 7, '因为他是我们的神；我们是他草场的羊，是他手下的民。惟愿你们今天听他的话：'),
('CUV', '诗篇', 19, 95, 8, '你们不可硬著心，像当日在米利巴，就是在旷野的玛撒。'),
('CUV', '诗篇', 19, 95, 9, '那时，你们的祖宗试我探我，并且观看我的作为。'),
('CUV', '诗篇', 19, 95, 10, '四十年之久，我厌烦那世代，说：这是心里迷糊的百姓，竟不晓得我的作为！'),
('CUV', '诗篇', 19, 95, 11, '所以，我在怒中起誓，说：他们断不可进入我的安息！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 96, 1, '你们要向耶和华唱新歌！全地都要向耶和华歌唱！'),
('CUV', '诗篇', 19, 96, 2, '要向耶和华歌唱，称颂他的名！天天传扬他的救恩！'),
('CUV', '诗篇', 19, 96, 3, '在列邦中述说他的荣耀！在万民中述说他的奇事！'),
('CUV', '诗篇', 19, 96, 4, '因耶和华为大，当受极大的赞美；他在万神之上，当受敬畏。'),
('CUV', '诗篇', 19, 96, 5, '外邦的神都属虚无；惟独耶和华创造诸天。'),
('CUV', '诗篇', 19, 96, 6, '有尊荣和威严在他面前；有能力与华美在他圣所。'),
('CUV', '诗篇', 19, 96, 7, '民中的万族啊，你们要将荣耀、能力归给耶和华，都归给耶和华！'),
('CUV', '诗篇', 19, 96, 8, '要将耶和华的名所当得的荣耀归给他，拿供物来进入他的院宇。'),
('CUV', '诗篇', 19, 96, 9, '当以圣洁的（的：或译为）妆饰敬拜耶和华；全地要在他面前战抖！'),
('CUV', '诗篇', 19, 96, 10, '人在列邦中要说：耶和华作王！世界就坚定，不得动摇；他要按公正审判众民。'),
('CUV', '诗篇', 19, 96, 11, '愿天欢喜，愿地快乐！愿海和其中所充满的澎湃！'),
('CUV', '诗篇', 19, 96, 12, '愿田和其中所有的都欢乐！那时，林中的树木都要在耶和华面前欢呼。'),
('CUV', '诗篇', 19, 96, 13, '因为他来了，他来要审判全地。他要按公义审判世界，按他的信实审判万民。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 97, 1, '耶和华作王！愿地快乐！愿众海岛欢喜！'),
('CUV', '诗篇', 19, 97, 2, '密云和幽暗在他的四围；公义和公平是他宝座的根基。'),
('CUV', '诗篇', 19, 97, 3, '有烈火在他前头行，烧灭他四围的敌人。'),
('CUV', '诗篇', 19, 97, 4, '他的闪电光照世界，大地看见便震动。'),
('CUV', '诗篇', 19, 97, 5, '诸山见耶和华的面，就是全地之主的面，便消化如蜡。'),
('CUV', '诗篇', 19, 97, 6, '诸天表明他的公义；万民看见他的荣耀。'),
('CUV', '诗篇', 19, 97, 7, '愿一切事奉雕刻的偶像、靠虚无之神自夸的，都蒙羞愧。万神哪，你们都当拜他。'),
('CUV', '诗篇', 19, 97, 8, '耶和华啊，锡安听见你的判断就欢喜；犹大的城邑（原文是女子）也都快乐。'),
('CUV', '诗篇', 19, 97, 9, '因为你─耶和华至高，超乎全地；你被尊崇，远超万神之上。'),
('CUV', '诗篇', 19, 97, 10, '你们爱耶和华的，都当恨恶罪恶；他保护圣民的性命，搭救他们脱离恶人的手。'),
('CUV', '诗篇', 19, 97, 11, '散布亮光是为义人；预备喜乐是为正直人。'),
('CUV', '诗篇', 19, 97, 12, '你们义人当靠耶和华欢喜，称谢他可记念的圣名。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 98, 1, '（一篇诗。）你们要向耶和华唱新歌！因为他行过奇妙的事；他的右手和圣臂施行救恩。'),
('CUV', '诗篇', 19, 98, 2, '耶和华发明了他的救恩，在列邦人眼前显出公义；'),
('CUV', '诗篇', 19, 98, 3, '记念他向以色列家所发的慈爱，所凭的信实。地的四极都看见我们神的救恩。'),
('CUV', '诗篇', 19, 98, 4, '全地都要向耶和华欢乐；要发起大声，欢呼歌颂！'),
('CUV', '诗篇', 19, 98, 5, '要用琴歌颂耶和华，用琴和诗歌的声音歌颂他！'),
('CUV', '诗篇', 19, 98, 6, '用号和角声，在大君王耶和华面前欢呼！'),
('CUV', '诗篇', 19, 98, 7, '愿海和其中所充满的澎湃；世界和住在其间的也要发声。'),
('CUV', '诗篇', 19, 98, 8, '愿大水拍手；愿诸山在耶和华面前一同欢呼；'),
('CUV', '诗篇', 19, 98, 9, '因为他来要审判遍地。他要按公义审判世界，按公正审判万民。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 99, 1, '耶和华作王；万民当战抖！他坐在二基路伯上，地当动摇。'),
('CUV', '诗篇', 19, 99, 2, '耶和华在锡安为大；他超乎万民之上。'),
('CUV', '诗篇', 19, 99, 3, '他们当称赞他大而可畏的名；他本为圣！'),
('CUV', '诗篇', 19, 99, 4, '王有能力，喜爱公平，坚立公正，在雅各中施行公平和公义。'),
('CUV', '诗篇', 19, 99, 5, '你们当尊崇耶和华─我们的神，在他脚凳前下拜。他本为圣！'),
('CUV', '诗篇', 19, 99, 6, '在他的祭司中有摩西和亚伦；在求告他名的人中有撒母耳。他们求告耶和华，他就应允他们。'),
('CUV', '诗篇', 19, 99, 7, '他在云柱中对他们说话；他们遵守他的法度和他所赐给他们的律例。'),
('CUV', '诗篇', 19, 99, 8, '耶和华─我们的神啊，你应允他们；你是赦免他们的神，却按他们所行的报应他们。'),
('CUV', '诗篇', 19, 99, 9, '你们要尊崇耶和华─我们的神，在他的圣山下拜，因为耶和华─我们的神本为圣！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 100, 1, '（称谢诗。）普天下当向耶和华欢呼！'),
('CUV', '诗篇', 19, 100, 2, '你们当乐意事奉耶和华，当来向他歌唱！'),
('CUV', '诗篇', 19, 100, 3, '你们当晓得耶和华是神！我们是他造的，也是属他的；我们是他的民，也是他草场的羊。'),
('CUV', '诗篇', 19, 100, 4, '当称谢进入他的门；当赞美进入他的院。当感谢他，称颂他的名！'),
('CUV', '诗篇', 19, 100, 5, '因为耶和华本为善。他的慈爱存到永远；他的信实直到万代。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 101, 1, '（大卫的诗）我要歌唱慈爱和公平；耶和华啊，我要向你歌颂！'),
('CUV', '诗篇', 19, 101, 2, '我要用智慧行完全的道。你几时到我这里来呢？我要存完全的心行在我家中。'),
('CUV', '诗篇', 19, 101, 3, '邪僻的事，我都不摆在我眼前；悖逆人所做的事，我甚恨恶，不容沾在我身上。'),
('CUV', '诗篇', 19, 101, 4, '弯曲的心思，我必远离；一切的恶人（或译：恶事），我不认识。'),
('CUV', '诗篇', 19, 101, 5, '在暗中谗谤他邻居的，我必将他灭绝；眼目高傲、心里骄纵的，我必不容他。'),
('CUV', '诗篇', 19, 101, 6, '我眼要看国中的诚实人，叫他们与我同住；行为完全的，他要伺候我。'),
('CUV', '诗篇', 19, 101, 7, '行诡诈的，必不得住在我家里；说谎话的，必不得立在我眼前。'),
('CUV', '诗篇', 19, 101, 8, '我每日早晨要灭绝国中所有的恶人，好把一切作孽的从耶和华的城里剪除。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 102, 1, '（困苦人发昏的时候，在耶和华面前吐露苦情的祷告。）耶和华啊，求你听我的祷告，容我的呼求达到你面前！'),
('CUV', '诗篇', 19, 102, 2, '我在急难的日子，求你向我侧耳；不要向我掩面！我呼求的日子，求你快快应允我！'),
('CUV', '诗篇', 19, 102, 3, '因为，我的年日如烟云消灭；我的骨头如火把烧著。'),
('CUV', '诗篇', 19, 102, 4, '我的心被伤，如草枯干，甚至我忘记吃饭。'),
('CUV', '诗篇', 19, 102, 5, '因我唉哼的声音，我的肉紧贴骨头。'),
('CUV', '诗篇', 19, 102, 6, '我如同旷野的鹈鹕；我好像荒场的鸮鸟。'),
('CUV', '诗篇', 19, 102, 7, '我警醒不睡；我像房顶上孤单的麻雀。'),
('CUV', '诗篇', 19, 102, 8, '我的仇敌终日辱骂我；向我猖狂的人指著我赌咒。'),
('CUV', '诗篇', 19, 102, 9, '我吃过炉灰，如同吃饭；我所喝的与眼泪搀杂。'),
('CUV', '诗篇', 19, 102, 10, '这都因你的恼恨和忿怒；你把我拾起来，又把我摔下去。'),
('CUV', '诗篇', 19, 102, 11, '我的年日如日影偏斜；我也如草枯干。'),
('CUV', '诗篇', 19, 102, 12, '惟你─耶和华必存到永远；你可记念的名也存到万代。'),
('CUV', '诗篇', 19, 102, 13, '你必起来怜恤锡安，因现在是可怜他的时候，日期已经到了。'),
('CUV', '诗篇', 19, 102, 14, '你的仆人原来喜悦他的石头，可怜他的尘土。'),
('CUV', '诗篇', 19, 102, 15, '列国要敬畏耶和华的名；世上诸王都敬畏你的荣耀。'),
('CUV', '诗篇', 19, 102, 16, '因为耶和华建造了锡安，在他荣耀里显现。'),
('CUV', '诗篇', 19, 102, 17, '他垂听穷人的祷告，并不藐视他们的祈求。'),
('CUV', '诗篇', 19, 102, 18, '这必为后代的人记下，将来受造的民要赞美耶和华。'),
('CUV', '诗篇', 19, 102, 19, '因为，他从至高的圣所垂看；耶和华从天向地观察，'),
('CUV', '诗篇', 19, 102, 20, '要垂听被囚之人的叹息，要释放将要死的人，'),
('CUV', '诗篇', 19, 102, 21, '使人在锡安传扬耶和华的名，在耶路撒冷传扬赞美他的话，'),
('CUV', '诗篇', 19, 102, 22, '就是在万民和列国聚会事奉耶和华的时候。'),
('CUV', '诗篇', 19, 102, 23, '他使我的力量中道衰弱，使我的年日短少。'),
('CUV', '诗篇', 19, 102, 24, '我说：我的神啊，不要使我中年去世。你的年数世世无穷！'),
('CUV', '诗篇', 19, 102, 25, '你起初立了地的根基；天也是你手所造的。'),
('CUV', '诗篇', 19, 102, 26, '天地都要灭没，你却要长存；天地都要如外衣渐渐旧了。你要将天地如里衣更换，天地就改变了。'),
('CUV', '诗篇', 19, 102, 27, '惟有你永不改变；你的年数没有穷尽。'),
('CUV', '诗篇', 19, 102, 28, '你仆人的子孙要长存；他们的后裔要坚立在你面前。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 103, 1, '（大卫的诗。）我的心哪，你要称颂耶和华！凡在我里面的，也要称颂他的圣名！'),
('CUV', '诗篇', 19, 103, 2, '我的心哪，你要称颂耶和华！不可忘记他的一切恩惠！'),
('CUV', '诗篇', 19, 103, 3, '他赦免你的一切罪孽，医治你的一切疾病。'),
('CUV', '诗篇', 19, 103, 4, '他救赎你的命脱离死亡，以仁爱和慈悲为你的冠冕。'),
('CUV', '诗篇', 19, 103, 5, '他用美物使你所愿的得以知足，以致你如鹰返老还童。'),
('CUV', '诗篇', 19, 103, 6, '耶和华施行公义，为一切受屈的人伸冤。'),
('CUV', '诗篇', 19, 103, 7, '他使摩西知道他的法则，叫以色列人晓得他的作为。'),
('CUV', '诗篇', 19, 103, 8, '耶和华有怜悯，有恩典，不轻易发怒，且有丰盛的慈爱。'),
('CUV', '诗篇', 19, 103, 9, '他不长久责备，也不永远怀怒。'),
('CUV', '诗篇', 19, 103, 10, '他没有按我们的罪过待我们，也没有照我们的罪孽报应我们。'),
('CUV', '诗篇', 19, 103, 11, '天离地何等的高，他的慈爱向敬畏他的人也是何等的大！'),
('CUV', '诗篇', 19, 103, 12, '东离西有多远，他叫我们的过犯离我们也有多远！'),
('CUV', '诗篇', 19, 103, 13, '父亲怎样怜恤他的儿女，耶和华也怎样怜恤敬畏他的人！'),
('CUV', '诗篇', 19, 103, 14, '因为他知道我们的本体，思念我们不过是尘土。'),
('CUV', '诗篇', 19, 103, 15, '至于世人，他的年日如草一样。他发旺如野地的花，'),
('CUV', '诗篇', 19, 103, 16, '经风一吹，便归无有；他的原处也不再认识他。'),
('CUV', '诗篇', 19, 103, 17, '但耶和华的慈爱归于敬畏他的人，从亘古到永远；他的公义也归于子子孙孙'),
('CUV', '诗篇', 19, 103, 18, '就是那些遵守他的约、记念他的训词而遵行的人。'),
('CUV', '诗篇', 19, 103, 19, '耶和华在天上立定宝座；他的权柄（原文是国）统管万有。'),
('CUV', '诗篇', 19, 103, 20, '听从他命令、成全他旨意、有大能的天使，都要称颂耶和华！'),
('CUV', '诗篇', 19, 103, 21, '你们作他的诸军，作他的仆役，行他所喜悦的，都要称颂耶和华！'),
('CUV', '诗篇', 19, 103, 22, '你们一切被他造的，在他所治理的各处，都要称颂耶和华！我的心哪，你要称颂耶和华！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 104, 1, '我的心哪，你要称颂耶和华！耶和华─我的神啊，你为至大！你以尊荣威严为衣服，'),
('CUV', '诗篇', 19, 104, 2, '披上亮光，如披外袍，铺张穹苍，如铺幔子，'),
('CUV', '诗篇', 19, 104, 3, '在水中立楼阁的栋梁，用云彩为车辇，藉著风的翅膀而行，'),
('CUV', '诗篇', 19, 104, 4, '以风为使者，以火燄为仆役，'),
('CUV', '诗篇', 19, 104, 5, '将地立在根基上，使地永不动摇。'),
('CUV', '诗篇', 19, 104, 6, '你用深水遮盖地面，犹如衣裳；诸水高过山岭。'),
('CUV', '诗篇', 19, 104, 7, '你的斥责一发，水便奔逃；你的雷声一发，水便奔流。'),
('CUV', '诗篇', 19, 104, 8, '诸山升上，诸谷沉下（或译：随山上翻，随谷下流），归你为他所安定之地。'),
('CUV', '诗篇', 19, 104, 9, '你定了界限，使水不能过去，不再转回遮盖地面。'),
('CUV', '诗篇', 19, 104, 10, '耶和华使泉源涌在山谷，流在山间，'),
('CUV', '诗篇', 19, 104, 11, '使野地的走兽有水喝，野驴得解其渴。'),
('CUV', '诗篇', 19, 104, 12, '天上的飞鸟在水旁住宿，在树枝上啼叫。'),
('CUV', '诗篇', 19, 104, 13, '他从楼阁中浇灌山岭；因他作为的功效，地就丰足。'),
('CUV', '诗篇', 19, 104, 14, '他使草生长，给六畜吃，使菜蔬发长，供给人用，使人从地里能得食物，'),
('CUV', '诗篇', 19, 104, 15, '又得酒能悦人心，得油能润人面，得粮能养人心。'),
('CUV', '诗篇', 19, 104, 16, '佳美的树木，就是利巴嫩的香柏树，是耶和华所栽种的，都满了汁浆。'),
('CUV', '诗篇', 19, 104, 17, '雀鸟在其上搭窝；至于鹤，松树是他的房屋。'),
('CUV', '诗篇', 19, 104, 18, '高山为野山羊的住所；岩石为沙番的藏处。'),
('CUV', '诗篇', 19, 104, 19, '你安置月亮为定节令；日头自知沉落。'),
('CUV', '诗篇', 19, 104, 20, '你造黑暗为夜，林中的百兽就都爬出来。'),
('CUV', '诗篇', 19, 104, 21, '少壮狮子吼叫，要抓食，向神寻求食物。'),
('CUV', '诗篇', 19, 104, 22, '日头一出，兽便躲避，卧在洞里。'),
('CUV', '诗篇', 19, 104, 23, '人出去做工，劳碌直到晚上。'),
('CUV', '诗篇', 19, 104, 24, '耶和华啊，你所造的何其多！都是你用智慧造成的；遍地满了你的丰富。'),
('CUV', '诗篇', 19, 104, 25, '那里有海，又大又广；其中有无数的动物，大小活物都有。'),
('CUV', '诗篇', 19, 104, 26, '那里有船行走，有你所造的鳄鱼游泳在其中。'),
('CUV', '诗篇', 19, 104, 27, '这都仰望你按时给他食物。'),
('CUV', '诗篇', 19, 104, 28, '你给他们，他们便拾起来；你张手，他们饱得美食。'),
('CUV', '诗篇', 19, 104, 29, '你掩面，他们便惊惶；你收回他们的气，他们就死亡，归于尘土。'),
('CUV', '诗篇', 19, 104, 30, '你发出你的灵，他们便受造；你使地面更换为新。'),
('CUV', '诗篇', 19, 104, 31, '愿耶和华的荣耀存到永远！愿耶和华喜悦自己所造的！'),
('CUV', '诗篇', 19, 104, 32, '他看地，地便震动；他摸山，山就冒烟。'),
('CUV', '诗篇', 19, 104, 33, '我要一生向耶和华唱诗！我还活的时候，要向我神歌颂！'),
('CUV', '诗篇', 19, 104, 34, '愿他以我的默念为甘甜！我要因耶和华欢喜！'),
('CUV', '诗篇', 19, 104, 35, '愿罪人从世上消灭！愿恶人归于无有！我的心哪，要称颂耶和华！你们要赞美耶和华（原文是哈利路亚；下同）！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 105, 1, '你们要称谢耶和华，求告他的名，在万民中传扬他的作为！'),
('CUV', '诗篇', 19, 105, 2, '要向他唱诗歌颂，谈论他一切奇妙的作为！'),
('CUV', '诗篇', 19, 105, 3, '要以他的圣名夸耀！寻求耶和华的人，心中应当欢喜！'),
('CUV', '诗篇', 19, 105, 4, '要寻求耶和华与他的能力，时常寻求他的面。'),
('CUV', '诗篇', 19, 105, 5, '他仆人亚伯拉罕的后裔，他所拣选雅各的子孙哪，你们要记念他奇妙的作为和他的奇事，并他口中的判语。'),
('CUV', '诗篇', 19, 105, 6, 'a'),
('CUV', '诗篇', 19, 105, 7, '他是耶和华─我们的神；全地都有他的判断。'),
('CUV', '诗篇', 19, 105, 8, '他记念他的约，直到永远；他所吩咐的话，直到千代─'),
('CUV', '诗篇', 19, 105, 9, '就是与亚伯拉罕所立的约，向以撒所起的誓。'),
('CUV', '诗篇', 19, 105, 10, '他又将这约向雅各定为律例，向以色列定为永远的约，'),
('CUV', '诗篇', 19, 105, 11, '说：我必将迦南地赐给你，作你产业的分。'),
('CUV', '诗篇', 19, 105, 12, '当时，他们人丁有限，数目稀少，并且在那地为寄居的。'),
('CUV', '诗篇', 19, 105, 13, '他们从这邦游到那邦，从这国行到那国。'),
('CUV', '诗篇', 19, 105, 14, '他不容甚么人欺负他们，为他们的缘故责备君王，'),
('CUV', '诗篇', 19, 105, 15, '说：不可难为我受膏的人，也不可恶待我的先知。'),
('CUV', '诗篇', 19, 105, 16, '他命饥荒降在那地上，将所倚靠的粮食全行断绝，'),
('CUV', '诗篇', 19, 105, 17, '在他们以先打发一个人去─约瑟被卖为奴仆。'),
('CUV', '诗篇', 19, 105, 18, '人用脚镣伤他的脚；他被铁链捆拘。'),
('CUV', '诗篇', 19, 105, 19, '耶和华的话试炼他，直等到他所说的应验了。'),
('CUV', '诗篇', 19, 105, 20, '王打发人把他解开，就是治理众民的，把他释放，'),
('CUV', '诗篇', 19, 105, 21, '立他作王家之主，掌管他一切所有的，'),
('CUV', '诗篇', 19, 105, 22, '使他随意捆绑他的臣宰，将智慧教导他的长老。'),
('CUV', '诗篇', 19, 105, 23, '以色列也到了埃及；雅各在含地寄居。'),
('CUV', '诗篇', 19, 105, 24, '耶和华使他的百姓生养众多，使他们比敌人强盛，'),
('CUV', '诗篇', 19, 105, 25, '使敌人的心转去恨他的百姓，并用诡计待他的仆人。'),
('CUV', '诗篇', 19, 105, 26, '他打发他的仆人摩西和他所拣选的亚伦，'),
('CUV', '诗篇', 19, 105, 27, '在敌人中间显他的神迹，在含地显他的奇事。'),
('CUV', '诗篇', 19, 105, 28, '他命黑暗，就有黑暗；没有违背他话的。'),
('CUV', '诗篇', 19, 105, 29, '他叫埃及的水变为血，叫他们的鱼死了。'),
('CUV', '诗篇', 19, 105, 30, '在他们的地上以及王宫的内室，青蛙多多滋生。'),
('CUV', '诗篇', 19, 105, 31, '他说一声，苍蝇就成群而来，并有虱子进入他们四境。'),
('CUV', '诗篇', 19, 105, 32, '他给他们降下冰雹为雨，在他们的地上降下火燄。'),
('CUV', '诗篇', 19, 105, 33, '他也击打他们的葡萄树和无花果树，毁坏他们境内的树木。'),
('CUV', '诗篇', 19, 105, 34, '他说一声，就有蝗虫蚂蚱上来，不计其数，'),
('CUV', '诗篇', 19, 105, 35, '吃尽了他们地上各样的菜蔬和田地的出产。'),
('CUV', '诗篇', 19, 105, 36, '他又击杀他们国内一切的长子，就是他们强壮时头生的。'),
('CUV', '诗篇', 19, 105, 37, '他领自己的百姓带银子金子出来；他支派中没有一个软弱的。'),
('CUV', '诗篇', 19, 105, 38, '他们出来的时候，埃及人便欢喜；原来埃及人惧怕他们。'),
('CUV', '诗篇', 19, 105, 39, '他铺张云彩当遮盖，夜间使火光照。'),
('CUV', '诗篇', 19, 105, 40, '他们一求，他就使鹌鹑飞来，并用天上的粮食叫他们饱足。'),
('CUV', '诗篇', 19, 105, 41, '他打开磐石，水就涌出；在干旱之处，水流成河。'),
('CUV', '诗篇', 19, 105, 42, '这都因他记念他的圣言和他的仆人亚伯拉罕。'),
('CUV', '诗篇', 19, 105, 43, '他带领百姓欢乐而出，带领选民欢呼前往。'),
('CUV', '诗篇', 19, 105, 44, '他将列国的地赐给他们，他们便承巡蛦民劳碌得来的，'),
('CUV', '诗篇', 19, 105, 45, '好使他们遵他的律例，守他的律法。你们要赞美耶和华！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 106, 1, '你们要赞美耶和华！要称谢耶和华，因他本为善；他的慈爱永远长存！'),
('CUV', '诗篇', 19, 106, 2, '谁能传说耶和华的大能？谁能表明他一切的美德？'),
('CUV', '诗篇', 19, 106, 3, '凡遵守公平﹔常行公义的，这人便为有福！'),
('CUV', '诗篇', 19, 106, 4, '耶和华啊，你用恩惠待你的百姓；求你也用这恩惠记念我，开你的救恩眷顾我，'),
('CUV', '诗篇', 19, 106, 5, '使我见你选民的福，乐你国民的乐，与你的产业一同夸耀。'),
('CUV', '诗篇', 19, 106, 6, '我们与我们的祖宗一同犯罪；我们作了孽，行了恶。'),
('CUV', '诗篇', 19, 106, 7, '我们的祖宗在埃及不明白你的奇事，不记念你丰盛的慈爱，反倒在红海行了悖逆。'),
('CUV', '诗篇', 19, 106, 8, '然而，他因自己的名拯救他们，为要彰显他的大能，'),
('CUV', '诗篇', 19, 106, 9, '并且斥责红海，海便干了；他带领他们经过深处，如同经过旷野。'),
('CUV', '诗篇', 19, 106, 10, '他拯救他们脱离恨他们人的手，从仇敌手中救赎他们。'),
('CUV', '诗篇', 19, 106, 11, '水淹没他们的敌人，没有一个存留。'),
('CUV', '诗篇', 19, 106, 12, '那时，他们才信了他的话，歌唱赞美他。'),
('CUV', '诗篇', 19, 106, 13, '等不多时，他们就忘了他的作为，不仰望他的指教，'),
('CUV', '诗篇', 19, 106, 14, '反倒在旷野大起欲心，在荒地试探神。'),
('CUV', '诗篇', 19, 106, 15, '他将他们所求的赐给他们，却使他们的心灵软弱。'),
('CUV', '诗篇', 19, 106, 16, '他们又在营中嫉妒摩西和耶和华的圣者亚伦。'),
('CUV', '诗篇', 19, 106, 17, '地裂开，吞下大坍，掩盖亚比兰一党的人。'),
('CUV', '诗篇', 19, 106, 18, '有火在他们的党中发起；有火燄烧毁了恶人。'),
('CUV', '诗篇', 19, 106, 19, '他们在何烈山造了牛犊，叩拜铸成的像。'),
('CUV', '诗篇', 19, 106, 20, '如此将他们荣耀的主换为吃草之牛的像，'),
('CUV', '诗篇', 19, 106, 21, '忘了神─他们的救主；他曾在埃及行大事，'),
('CUV', '诗篇', 19, 106, 22, '在含地行奇事，在红海行可畏的事。'),
('CUV', '诗篇', 19, 106, 23, '所以，他说要灭绝他们；若非有他所拣选的摩西站在当中（原文是破口），使他的忿怒转消，恐怕他就灭绝他们。'),
('CUV', '诗篇', 19, 106, 24, '他们又藐视那美地，不信他的话，'),
('CUV', '诗篇', 19, 106, 25, '在自己帐棚内发怨言，不听耶和华的声音。'),
('CUV', '诗篇', 19, 106, 26, '所以，他对他们起誓：必叫他们倒在旷野，'),
('CUV', '诗篇', 19, 106, 27, '叫他们的后裔倒在列国之中，分散在各地。'),
('CUV', '诗篇', 19, 106, 28, '他们又与巴力•毗珥连合，且吃了祭死神（或译：人）的物。'),
('CUV', '诗篇', 19, 106, 29, '他们这样行，惹耶和华发怒，便有瘟疫流行在他们中间。'),
('CUV', '诗篇', 19, 106, 30, '那时，非尼哈站起，刑罚恶人，瘟疫这才止息。'),
('CUV', '诗篇', 19, 106, 31, '那就算为他的义，世世代代，直到永远。'),
('CUV', '诗篇', 19, 106, 32, '他们在米利巴水又叫耶和华发怒，甚至摩西也受了亏损，'),
('CUV', '诗篇', 19, 106, 33, '是因他们惹动他的灵，摩西（原文是他）用嘴说了急躁的话。'),
('CUV', '诗篇', 19, 106, 34, '他们不照耶和华所吩咐的灭绝外邦人，'),
('CUV', '诗篇', 19, 106, 35, '反与他们混杂相合，学习他们的行为，'),
('CUV', '诗篇', 19, 106, 36, '事奉他们的偶像，这就成了自己的网罗，'),
('CUV', '诗篇', 19, 106, 37, '把自己的儿女祭祀鬼魔，'),
('CUV', '诗篇', 19, 106, 38, '流无辜人的血，就是自己儿女的血，把他们祭祀迦南的偶像，那地就被血污秽了。'),
('CUV', '诗篇', 19, 106, 39, '这样，他们被自己所做的污秽了，在行为上犯了邪淫。'),
('CUV', '诗篇', 19, 106, 40, '所以，耶和华的怒气向他的百姓发作，憎恶他的产业，'),
('CUV', '诗篇', 19, 106, 41, '将他们交在外邦人的手里；恨他们的人就辖制他们。'),
('CUV', '诗篇', 19, 106, 42, '他们的仇敌也欺压他们，他们就伏在敌人手下。'),
('CUV', '诗篇', 19, 106, 43, '他屡次搭救他们，他们却设谋背逆，因自己的罪孽降为卑下。'),
('CUV', '诗篇', 19, 106, 44, '然而，他听见他们哀告的时候，就眷顾他们的急难，'),
('CUV', '诗篇', 19, 106, 45, '为他们记念他的约，照他丰盛的慈爱后悔。'),
('CUV', '诗篇', 19, 106, 46, '他也使他们在凡掳掠他们的人面前蒙怜恤。'),
('CUV', '诗篇', 19, 106, 47, '耶和华─我们的神啊，求你拯救我们，从外邦中招聚我们，我们好称赞你的圣名，以赞美你为夸胜。'),
('CUV', '诗篇', 19, 106, 48, '耶和华─以色列的神是应当称颂的，从亘古直到永远。愿众民都说：阿们！你们要赞美耶和华！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 107, 1, '你们要称谢耶和华，因他本为善；他的慈爱永远长存！'),
('CUV', '诗篇', 19, 107, 2, '愿耶和华的赎民说这话，就是他从敌人手中所救赎的，'),
('CUV', '诗篇', 19, 107, 3, '从各地，从东从西，从南从北，所招聚来的。'),
('CUV', '诗篇', 19, 107, 4, '他们在旷野荒地漂流，寻不见可住的城邑，'),
('CUV', '诗篇', 19, 107, 5, '又饥又渴，心里发昏。'),
('CUV', '诗篇', 19, 107, 6, '于是，他们在苦难中哀求耶和华；他从他们的祸患中搭救他们，'),
('CUV', '诗篇', 19, 107, 7, '又领他们行走直路，使他们往可居住的城邑。'),
('CUV', '诗篇', 19, 107, 8, '但愿人因耶和华的慈爱和他向人所行的奇事都称赞他；'),
('CUV', '诗篇', 19, 107, 9, '因他使心里渴慕的人得以知足，使心里饥饿的人得饱美物。'),
('CUV', '诗篇', 19, 107, 10, '那些坐在黑暗中、死荫里的人被困苦和铁链捆锁，'),
('CUV', '诗篇', 19, 107, 11, '是因他们违背神的话语，藐视至高者的旨意。'),
('CUV', '诗篇', 19, 107, 12, '所以，他用劳苦治服他们的心；他们仆倒，无人扶助。'),
('CUV', '诗篇', 19, 107, 13, '于是，他们在苦难中哀求耶和华；他从他们的祸患中拯救他们。'),
('CUV', '诗篇', 19, 107, 14, '他从黑暗中和死荫里领他们出来，折断他们的绑索。'),
('CUV', '诗篇', 19, 107, 15, '但愿人因耶和华的慈爱和他向人所行的奇事都称赞他；'),
('CUV', '诗篇', 19, 107, 16, '因为他打破了铜门，砍断了铁闩。'),
('CUV', '诗篇', 19, 107, 17, '愚妄人因自己的过犯和自己的罪孽便受苦楚。'),
('CUV', '诗篇', 19, 107, 18, '他们心里厌恶各样的食物，就临近死门。'),
('CUV', '诗篇', 19, 107, 19, '于是，他们在苦难中哀求耶和华；他从他们的祸患中拯救他们。'),
('CUV', '诗篇', 19, 107, 20, '他发命医治他们，救他们脱离死亡。'),
('CUV', '诗篇', 19, 107, 21, '但愿人因耶和华的慈爱和他向人所行的奇事都称赞他。'),
('CUV', '诗篇', 19, 107, 22, '愿他们以感谢为祭献给他，欢呼述说他的作为！'),
('CUV', '诗篇', 19, 107, 23, '在海上坐船，在大水中经理事务的，'),
('CUV', '诗篇', 19, 107, 24, '他们看见耶和华的作为，并他在深水中的奇事。'),
('CUV', '诗篇', 19, 107, 25, '因他一吩咐，狂风就起来，海中的波浪也扬起。'),
('CUV', '诗篇', 19, 107, 26, '他们上到天空，下到海底；他们的心因患难便消化。'),
('CUV', '诗篇', 19, 107, 27, '他们摇摇幌幌，东倒西歪，好像醉酒的人；他们的智慧无法可施。'),
('CUV', '诗篇', 19, 107, 28, '于是，他们在苦难中哀求耶和华，他从他们的祸患中领出他们来。'),
('CUV', '诗篇', 19, 107, 29, '他使狂风止息，波浪就平静。'),
('CUV', '诗篇', 19, 107, 30, '风息浪静，他们便欢喜；他就引他们到所愿去的海口。'),
('CUV', '诗篇', 19, 107, 31, '但愿人因耶和华的慈爱和他向人所行的奇事都称赞他。'),
('CUV', '诗篇', 19, 107, 32, '愿他们在民的会中尊崇他，在长老的位上赞美他！'),
('CUV', '诗篇', 19, 107, 33, '他使江河变为旷野，叫水泉变为干渴之地，'),
('CUV', '诗篇', 19, 107, 34, '使肥地变为碱地；这都因其间居民的罪恶。'),
('CUV', '诗篇', 19, 107, 35, '他使旷野变为水潭，叫旱地变为水泉。'),
('CUV', '诗篇', 19, 107, 36, '他使饥饿的人住在那里，好建造可住的城邑，'),
('CUV', '诗篇', 19, 107, 37, '又种田地，栽葡萄园，得享所出的土产。'),
('CUV', '诗篇', 19, 107, 38, '他又赐福给他们，叫他们生养众多，也不叫他们的牲畜减少。'),
('CUV', '诗篇', 19, 107, 39, '他们又因暴虐、患难、愁苦，就减少且卑下。'),
('CUV', '诗篇', 19, 107, 40, '他使君王蒙羞被辱，使他们在荒废无路之地漂流。'),
('CUV', '诗篇', 19, 107, 41, '他却将穷乏人安置在高处，脱离苦难，使他的家属多如羊群。'),
('CUV', '诗篇', 19, 107, 42, '正直人看见就欢喜；罪孽之辈必塞口无言。'),
('CUV', '诗篇', 19, 107, 43, '凡有智慧的，必在这些事上留心，也必思想耶和华的慈爱。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 108, 1, '（大卫的诗歌。）神啊，我心坚定；我口（原文是荣耀）要唱诗歌颂！'),
('CUV', '诗篇', 19, 108, 2, '琴瑟啊，你们当醒起！我自己要极早醒起！'),
('CUV', '诗篇', 19, 108, 3, '耶和华啊，我要在万民中称谢你，在列邦中歌颂你！'),
('CUV', '诗篇', 19, 108, 4, '因为，你的慈爱大过诸天；你的诚实达到穹苍。'),
('CUV', '诗篇', 19, 108, 5, '神啊，愿你崇高过于诸天！愿你的荣耀高过全地！'),
('CUV', '诗篇', 19, 108, 6, '求你应允我们，用右手拯救我们，好叫你所亲爱的人得救。'),
('CUV', '诗篇', 19, 108, 7, '神已经指著他的圣洁说（说：或译应许我）：我要欢乐；我要分开示剑，丈量疏割谷。'),
('CUV', '诗篇', 19, 108, 8, '基列是我的；玛拿西是我的；以法莲是护卫我头的；犹大是我的杖；'),
('CUV', '诗篇', 19, 108, 9, '摩押是我的沐浴盆；我要向以东抛鞋；我必因胜非利士呼喊。'),
('CUV', '诗篇', 19, 108, 10, '谁能领我进坚固城？谁能引我到以东地？'),
('CUV', '诗篇', 19, 108, 11, '神啊，你不是丢弃了我们么？神啊，你不和我们的军兵同去么？'),
('CUV', '诗篇', 19, 108, 12, '求你帮助我们攻击敌人，因为人的帮助是枉然的。'),
('CUV', '诗篇', 19, 108, 13, '我们倚靠神才得施展大能，因为践踏我们敌人的就是他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 109, 1, '（大卫的诗，交与伶长。）我所赞美的神啊，求你不要闭口不言。'),
('CUV', '诗篇', 19, 109, 2, '因为恶人的嘴和诡诈人的口已经张开攻击我；他们用撒谎的舌头对我说话。'),
('CUV', '诗篇', 19, 109, 3, '他们围绕我，说怨恨的话，又无故地攻打我。'),
('CUV', '诗篇', 19, 109, 4, '他们与我为敌以报我爱，但我专心祈祷。'),
('CUV', '诗篇', 19, 109, 5, '他们向我以恶报善，以恨报爱。'),
('CUV', '诗篇', 19, 109, 6, '愿你派一个恶人辖制他，派一个对头站在他右边！'),
('CUV', '诗篇', 19, 109, 7, '他受审判的时候，愿他出来担当罪名！愿他的祈祷反成为罪！'),
('CUV', '诗篇', 19, 109, 8, '愿他的年日短少！愿别人得他的职分！'),
('CUV', '诗篇', 19, 109, 9, '愿他的儿女为孤儿，他的妻子为寡妇！'),
('CUV', '诗篇', 19, 109, 10, '愿他的儿女漂流讨饭，从他们荒凉之处出来求食！'),
('CUV', '诗篇', 19, 109, 11, '愿强暴的债主牢笼他一切所有的！愿外人抢他劳碌得来的！'),
('CUV', '诗篇', 19, 109, 12, '愿无人向他延绵施恩！愿无人可怜他的孤儿！'),
('CUV', '诗篇', 19, 109, 13, '愿他的后人断绝，名字被涂抹，不传于下代！'),
('CUV', '诗篇', 19, 109, 14, '愿他祖宗的罪孽被耶和华记念！愿他母亲的罪过不被涂抹！'),
('CUV', '诗篇', 19, 109, 15, '愿这些罪常在耶和华面前，使他的名号断绝于世！'),
('CUV', '诗篇', 19, 109, 16, '因为他不想施恩，却逼迫困苦穷乏的和伤心的人，要把他们治死。'),
('CUV', '诗篇', 19, 109, 17, '他爱咒骂，咒骂就临到他；他不喜爱福乐，福乐就与他远离！'),
('CUV', '诗篇', 19, 109, 18, '他拿咒骂当衣服穿上；这咒骂就如水进他里面，像油入他的骨头。'),
('CUV', '诗篇', 19, 109, 19, '愿这咒骂当他遮身的衣服，当他常束的腰带！'),
('CUV', '诗篇', 19, 109, 20, '这就是我对头和用恶言议论我的人从耶和华那里所受的报应。'),
('CUV', '诗篇', 19, 109, 21, '主─耶和华啊，求你为你的名恩待我；因你的慈爱美好，求你搭救我！'),
('CUV', '诗篇', 19, 109, 22, '因为我困苦穷乏，内心受伤。'),
('CUV', '诗篇', 19, 109, 23, '我如日影渐渐偏斜而去；我如蝗虫被抖出来。'),
('CUV', '诗篇', 19, 109, 24, '我因禁食，膝骨软弱；我身上的肉也渐渐瘦了。'),
('CUV', '诗篇', 19, 109, 25, '我受他们的羞辱，他们看见我便摇头。'),
('CUV', '诗篇', 19, 109, 26, '耶和华─我的神啊，求你帮助我，照你的慈爱拯救我，'),
('CUV', '诗篇', 19, 109, 27, '使他们知道这是你的手，是你─耶和华所行的事。'),
('CUV', '诗篇', 19, 109, 28, '任凭他们咒骂，惟愿你赐福；他们几时起来就必蒙羞，你的仆人却要欢喜。'),
('CUV', '诗篇', 19, 109, 29, '愿我的对头披戴羞辱！愿他们以自己的羞愧为外袍遮身！'),
('CUV', '诗篇', 19, 109, 30, '我要用口极力称谢耶和华；我要在众人中间赞美他；'),
('CUV', '诗篇', 19, 109, 31, '因为他必站在穷乏人的右边，要救他脱离审判他灵魂的人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 110, 1, '（大卫的诗。）耶和华对我主说：你坐在我的右边，等我使你仇敌作你的脚凳。'),
('CUV', '诗篇', 19, 110, 2, '耶和华必使你从锡安伸出能力的杖来；你要在你仇敌中掌权。'),
('CUV', '诗篇', 19, 110, 3, '当你掌权的日子（或译：行军的日子），你的民要以圣洁的妆饰为衣（或译：以圣洁为妆饰），甘心牺牲自己；你的民多如清晨的甘露（或译：你少年时光耀如清晨的甘露）。'),
('CUV', '诗篇', 19, 110, 4, '耶和华起了誓，决不后悔，说：你是照著麦基洗德的等次永远为祭司。'),
('CUV', '诗篇', 19, 110, 5, '在你右边的主，当他发怒的日子，必打伤列王。'),
('CUV', '诗篇', 19, 110, 6, '他要在列邦中刑罚恶人，尸首就遍满各处；他要在许多国中打破仇敌的头。'),
('CUV', '诗篇', 19, 110, 7, '他要喝路旁的河水，因此必抬起头来。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 111, 1, '你们要赞美耶和华！我要在正直人的大会中，并公会中，一心称谢耶和华。'),
('CUV', '诗篇', 19, 111, 2, '耶和华的作为本为大；凡喜爱的都必考察。'),
('CUV', '诗篇', 19, 111, 3, '他所行的是尊荣和威严；他的公义存到永远。'),
('CUV', '诗篇', 19, 111, 4, '他行了奇事，使人记念；耶和华有恩惠，有怜悯。'),
('CUV', '诗篇', 19, 111, 5, '他赐粮食给敬畏他的人；他必永远记念他的约。'),
('CUV', '诗篇', 19, 111, 6, '他向百姓显出大能的作为，把外邦的地赐给他们为业。'),
('CUV', '诗篇', 19, 111, 7, '他手所行的是诚实公平；他的训词都是确实的，'),
('CUV', '诗篇', 19, 111, 8, '是永永远远坚定的，是按诚实正直设立的。'),
('CUV', '诗篇', 19, 111, 9, '他向百姓施行救赎，命定他的约，直到永远；他的名圣而可畏。'),
('CUV', '诗篇', 19, 111, 10, '敬畏耶和华是智慧的开端；凡遵行他命令的是聪明人。耶和华是永远当赞美的！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 112, 1, '你们要赞美耶和华！敬畏耶和华，甚喜爱他命令的，这人便为有福！'),
('CUV', '诗篇', 19, 112, 2, '他的后裔在世必强盛；正直人的后代必要蒙福。'),
('CUV', '诗篇', 19, 112, 3, '他家中有货物，有钱财；他的公义存到永远。'),
('CUV', '诗篇', 19, 112, 4, '正直人在黑暗中，有光向他发现；他有恩惠，有怜悯，有公义。'),
('CUV', '诗篇', 19, 112, 5, '施恩与人、借贷与人的，这人事情顺利；他被审判的时候要诉明自己的冤。'),
('CUV', '诗篇', 19, 112, 6, '他永不动摇；义人被记念，直到永远。'),
('CUV', '诗篇', 19, 112, 7, '他必不怕凶恶的信息；他心坚定，倚靠耶和华。'),
('CUV', '诗篇', 19, 112, 8, '他心确定，总不惧怕，直到他看见敌人遭报。'),
('CUV', '诗篇', 19, 112, 9, '他施舍钱财，赒济贫穷；他的仁义存到永远。他的角必被高举，大有荣耀。'),
('CUV', '诗篇', 19, 112, 10, '恶人看见便恼恨，必咬牙而消化；恶人的心愿要归灭绝。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 113, 1, '你们要赞美耶和华！耶和华的仆人哪，你们要赞美，赞美耶和华的名！'),
('CUV', '诗篇', 19, 113, 2, '耶和华的名是应当称颂的，从今时直到永远！'),
('CUV', '诗篇', 19, 113, 3, '从日出之地到日落之处，耶和华的名是应当赞美的！'),
('CUV', '诗篇', 19, 113, 4, '耶和华超乎万民之上；他的荣耀高过诸天。'),
('CUV', '诗篇', 19, 113, 5, '谁像耶和华─我们的神呢？他坐在至高之处，'),
('CUV', '诗篇', 19, 113, 6, '自己谦卑，观看天上地下的事。'),
('CUV', '诗篇', 19, 113, 7, '他从灰尘里抬举贫寒人，从粪堆中提拔穷乏人，'),
('CUV', '诗篇', 19, 113, 8, '使他们与王子同坐，就是与本国的王子同坐。'),
('CUV', '诗篇', 19, 113, 9, '他使不能生育的妇人安居家中，为多子的乐母。你们要赞美耶和华！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 114, 1, '以色列出了埃及，雅各家离开说异言之民；'),
('CUV', '诗篇', 19, 114, 2, '那时，犹大为主的圣所，以色列为他所治理的国度。'),
('CUV', '诗篇', 19, 114, 3, '沧海看见就奔逃；约但河也倒流。'),
('CUV', '诗篇', 19, 114, 4, '大山踊跃，如公羊；小山跳舞，如羊羔。'),
('CUV', '诗篇', 19, 114, 5, '沧海啊，你为何奔逃？约但哪，你为何倒流？'),
('CUV', '诗篇', 19, 114, 6, '大山哪，你为何踊跃，如公羊？小山哪，你为何跳舞，如羊羔？'),
('CUV', '诗篇', 19, 114, 7, '大地啊，你因见主的面，就是雅各神的面，便要震动。'),
('CUV', '诗篇', 19, 114, 8, '他叫磐石变为水池，叫坚石变为泉源。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 115, 1, '耶和华啊，荣耀不要归与我们，不要归与我们；要因你的慈爱和诚实归在你的名下！'),
('CUV', '诗篇', 19, 115, 2, '为何容外邦人说：他们的神在哪里呢？'),
('CUV', '诗篇', 19, 115, 3, '然而，我们的神在天上，都随自己的意旨行事。'),
('CUV', '诗篇', 19, 115, 4, '他们的偶像是金的，银的，是人手所造的，'),
('CUV', '诗篇', 19, 115, 5, '有口却不能言，有眼却不能看，'),
('CUV', '诗篇', 19, 115, 6, '有耳却不能听，有鼻却不能闻，'),
('CUV', '诗篇', 19, 115, 7, '有手却不能摸，有脚却不能走，有喉咙也不能出声。'),
('CUV', '诗篇', 19, 115, 8, '造他的要和他一样；凡靠他的也要如此。'),
('CUV', '诗篇', 19, 115, 9, '以色列啊，你要倚靠耶和华！他是你的帮助和你的盾牌。'),
('CUV', '诗篇', 19, 115, 10, '亚伦家啊，你们要倚靠耶和华！他是你们的帮助和你们的盾牌。'),
('CUV', '诗篇', 19, 115, 11, '你们敬畏耶和华的，要倚靠耶和华！他是你们的帮助和你们的盾牌。'),
('CUV', '诗篇', 19, 115, 12, '耶和华向来眷念我们；他还要赐福给我们：要赐福给以色列的家，赐福给亚伦的家。'),
('CUV', '诗篇', 19, 115, 13, '凡敬畏耶和华的，无论大小，主必赐福给他。'),
('CUV', '诗篇', 19, 115, 14, '愿耶和华叫你们和你们的子孙日见加增。'),
('CUV', '诗篇', 19, 115, 15, '你们蒙了造天地之耶和华的福！'),
('CUV', '诗篇', 19, 115, 16, '天，是耶和华的天；地，他却给了世人。'),
('CUV', '诗篇', 19, 115, 17, '死人不能赞美耶和华；下到寂静中的也都不能。'),
('CUV', '诗篇', 19, 115, 18, '但我们要称颂耶和华，从今时直到永远。你们要赞美耶和华！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 116, 1, '我爱耶和华，因为他听了我的声音和我的恳求。'),
('CUV', '诗篇', 19, 116, 2, '他既向我侧耳，我一生要求告他。'),
('CUV', '诗篇', 19, 116, 3, '死亡的绳索缠绕我；阴间的痛苦抓住我；我遭遇患难愁苦。'),
('CUV', '诗篇', 19, 116, 4, '那时，我便求告耶和华的名，说：耶和华啊，求你救我的灵魂！'),
('CUV', '诗篇', 19, 116, 5, '耶和华有恩惠，有公义；我们的神以怜悯为怀。'),
('CUV', '诗篇', 19, 116, 6, '耶和华保护愚人；我落到卑微的地步，他救了我。'),
('CUV', '诗篇', 19, 116, 7, '我的心哪！你要仍归安乐，因为耶和华用厚恩待你。'),
('CUV', '诗篇', 19, 116, 8, '主啊，你救我的命免了死亡，救我的眼免了流泪，救我的脚免了跌倒。'),
('CUV', '诗篇', 19, 116, 9, '我要在耶和华面前行活人之路。'),
('CUV', '诗篇', 19, 116, 10, '我因信，所以如此说话；我受了极大的困苦。'),
('CUV', '诗篇', 19, 116, 11, '我曾急促地说：人都是说谎的！'),
('CUV', '诗篇', 19, 116, 12, '我拿甚么报答耶和华向我所赐的一切厚恩？'),
('CUV', '诗篇', 19, 116, 13, '我要举起救恩的杯，称扬耶和华的名。'),
('CUV', '诗篇', 19, 116, 14, '我要在他众民面前向耶和华还我的愿。'),
('CUV', '诗篇', 19, 116, 15, '在耶和华眼中，看圣民之死极为宝贵。'),
('CUV', '诗篇', 19, 116, 16, '耶和华啊，我真是你的仆人；我是你的仆人，是你婢女的儿子。你已经解开我的绑索。'),
('CUV', '诗篇', 19, 116, 17, '我要以感谢为祭献给你，又要求告耶和华的名。'),
('CUV', '诗篇', 19, 116, 18, '我要在他众民面前，在耶和华殿的院内，在耶路撒冷当中，向耶和华还我的愿。你们要赞美耶和华！'),
('CUV', '诗篇', 19, 116, 19, 'a')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 117, 1, '万国啊，你们都当赞美耶和华！万民哪，你们都当颂赞他！'),
('CUV', '诗篇', 19, 117, 2, '因为他向我们大施慈爱；耶和华的诚实存到永远。你们要赞美耶和华！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 118, 1, '你们要称谢耶和华，因他本为善；他的慈爱永远长存！'),
('CUV', '诗篇', 19, 118, 2, '愿以色列说：他的慈爱永远长存！'),
('CUV', '诗篇', 19, 118, 3, '愿亚伦的家说：他的慈爱永远长存！'),
('CUV', '诗篇', 19, 118, 4, '愿敬畏耶和华的说：他的慈爱永远长存！'),
('CUV', '诗篇', 19, 118, 5, '我在急难中求告耶和华，他就应允我，把我安置在宽阔之地。'),
('CUV', '诗篇', 19, 118, 6, '有耶和华帮助我，我必不惧怕，人能把我怎么样呢？'),
('CUV', '诗篇', 19, 118, 7, '在那帮助我的人中，有耶和华帮助我，所以我要看见那恨我的人遭报。'),
('CUV', '诗篇', 19, 118, 8, '投靠耶和华，强似倚赖人；'),
('CUV', '诗篇', 19, 118, 9, '投靠耶和华，强似倚赖王子。'),
('CUV', '诗篇', 19, 118, 10, '万民围绕我，我靠耶和华的名必剿灭他们。'),
('CUV', '诗篇', 19, 118, 11, '他们环绕我，围困我，我靠耶和华的名必剿灭他们。'),
('CUV', '诗篇', 19, 118, 12, '他们如同蜂子围绕我，好像烧荆棘的火，必被熄灭；我靠耶和华的名，必剿灭他们。'),
('CUV', '诗篇', 19, 118, 13, '你推我，要叫我跌倒，但耶和华帮助了我。'),
('CUV', '诗篇', 19, 118, 14, '耶和华是我的力量，是我的诗歌；他也成了我的拯救。'),
('CUV', '诗篇', 19, 118, 15, '在义人的帐棚里，有欢呼拯救的声音；耶和华的右手施展大能。'),
('CUV', '诗篇', 19, 118, 16, '耶和华的右手高举；耶和华的右手施展大能。'),
('CUV', '诗篇', 19, 118, 17, '我必不致死，仍要存活，并要传扬耶和华的作为。'),
('CUV', '诗篇', 19, 118, 18, '耶和华虽严严地惩治我，却未曾将我交于死亡。'),
('CUV', '诗篇', 19, 118, 19, '给我敞开义门；我要进去称谢耶和华！'),
('CUV', '诗篇', 19, 118, 20, '这是耶和华的门；义人要进去！'),
('CUV', '诗篇', 19, 118, 21, '我要称谢你，因为你已经应允我，又成了我的拯救！'),
('CUV', '诗篇', 19, 118, 22, '匠人所弃的石头已成了房角的头块石头。'),
('CUV', '诗篇', 19, 118, 23, '这是耶和华所做的，在我们眼中看为希奇。'),
('CUV', '诗篇', 19, 118, 24, '这是耶和华所定的日子，我们在其中要高兴欢喜！'),
('CUV', '诗篇', 19, 118, 25, '耶和华啊，求你拯救！耶和华啊，求你使我们亨通！'),
('CUV', '诗篇', 19, 118, 26, '奉耶和华名来的是应当称颂的！我们从耶和华的殿中为你们祝福！'),
('CUV', '诗篇', 19, 118, 27, '耶和华是神；他光照了我们。理当用绳索把祭牲拴住，牵到坛角那里。'),
('CUV', '诗篇', 19, 118, 28, '你是我的神，我要称谢你！你是我的神，我要尊崇你！'),
('CUV', '诗篇', 19, 118, 29, '你们要称谢耶和华，因他本为善；他的慈爱永远长存！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 119, 1, '行为完全、遵行耶和华律法的，这人便为有福！'),
('CUV', '诗篇', 19, 119, 2, '遵守他的法度、一心寻求他的，这人便为有福！'),
('CUV', '诗篇', 19, 119, 3, '这人不做非义的事，但遵行他的道。'),
('CUV', '诗篇', 19, 119, 4, '耶和华啊，你曾将你的训词吩咐我们，为要我们殷勤遵守。'),
('CUV', '诗篇', 19, 119, 5, '但愿我行事坚定，得以遵守你的律例。'),
('CUV', '诗篇', 19, 119, 6, '我看重你的一切命令，就不至于羞愧。'),
('CUV', '诗篇', 19, 119, 7, '我学了你公义的判语，就要以正直的心称谢你。'),
('CUV', '诗篇', 19, 119, 8, '我必守你的律例；求你总不要丢弃我！'),
('CUV', '诗篇', 19, 119, 9, '少年人用甚么洁净他的行为呢？是要遵行你的话！'),
('CUV', '诗篇', 19, 119, 10, '我一心寻求了你；求你不要叫我偏离你的命令。'),
('CUV', '诗篇', 19, 119, 11, '我将你的话藏在心里，免得我得罪你。'),
('CUV', '诗篇', 19, 119, 12, '耶和华啊，你是应当称颂的！求你将你的律例教训我！'),
('CUV', '诗篇', 19, 119, 13, '我用嘴唇传扬你口中的一切典章。'),
('CUV', '诗篇', 19, 119, 14, '我喜悦你的法度，如同喜悦一切的财物。'),
('CUV', '诗篇', 19, 119, 15, '我要默想你的训词，看重你的道路。'),
('CUV', '诗篇', 19, 119, 16, '我要在你的律例中自乐；我不忘记你的话。'),
('CUV', '诗篇', 19, 119, 17, '求你用厚恩待你的仆人，使我存活，我就遵守你的话。'),
('CUV', '诗篇', 19, 119, 18, '求你开我的眼睛，使我看出你律法中的奇妙。'),
('CUV', '诗篇', 19, 119, 19, '我是在地上作寄居的；求你不要向我隐瞒你的命令！'),
('CUV', '诗篇', 19, 119, 20, '我时常切慕你的典章，甚至心碎。'),
('CUV', '诗篇', 19, 119, 21, '受咒诅、偏离你命令的骄傲人，你已经责备他们。'),
('CUV', '诗篇', 19, 119, 22, '求你除掉我所受的羞辱和藐视，因我遵守你的法度。'),
('CUV', '诗篇', 19, 119, 23, '虽有首领坐著妄论我，你仆人却思想你的律例。'),
('CUV', '诗篇', 19, 119, 24, '你的法度是我所喜乐的，是我的谋士。'),
('CUV', '诗篇', 19, 119, 25, '我的性命几乎归于尘土；求你照你的话将我救活！'),
('CUV', '诗篇', 19, 119, 26, '我述说我所行的，你应允了我；求你将你的律例教训我！'),
('CUV', '诗篇', 19, 119, 27, '求你使我明白你的训词，我就思想你的奇事。'),
('CUV', '诗篇', 19, 119, 28, '我的心因愁苦而消化；求你照你的话使我坚立！'),
('CUV', '诗篇', 19, 119, 29, '求你使我离开奸诈的道，开恩将你的律法赐给我！'),
('CUV', '诗篇', 19, 119, 30, '我拣选了忠信的道，将你的典章摆在我面前。'),
('CUV', '诗篇', 19, 119, 31, '我持守你的法度；耶和华啊，求你不要叫我羞愧！'),
('CUV', '诗篇', 19, 119, 32, '你开广我心的时候，我就往你命令的道上直奔。'),
('CUV', '诗篇', 19, 119, 33, '耶和华啊，求你将你的律例指教我，我必遵守到底！'),
('CUV', '诗篇', 19, 119, 34, '求你赐我悟性，我便遵守你的律法，且要一心遵守。'),
('CUV', '诗篇', 19, 119, 35, '求你叫我遵行你的命令，因为这是我所喜乐的。'),
('CUV', '诗篇', 19, 119, 36, '求你使我的心趋向你的法度，不趋向非义之财。'),
('CUV', '诗篇', 19, 119, 37, '求你叫我转眼不看虚假，又叫我在你的道中生活。'),
('CUV', '诗篇', 19, 119, 38, '你向敬畏你的人所应许的话，求你向仆人坚定！'),
('CUV', '诗篇', 19, 119, 39, '求你使我所怕的羞辱远离我，因你的典章本为美。'),
('CUV', '诗篇', 19, 119, 40, '我羡慕你的训词；求你使我在你的公义上生活！'),
('CUV', '诗篇', 19, 119, 41, '耶和华啊，愿你照你的话，使你的慈爱，就是你的救恩，临到我身上，'),
('CUV', '诗篇', 19, 119, 42, '我就有话回答那羞辱我的，因我倚靠你的话。'),
('CUV', '诗篇', 19, 119, 43, '求你叫真理的话总不离开我口，因我仰望你的典章。'),
('CUV', '诗篇', 19, 119, 44, '我要常守你的律法，直到永永远远。'),
('CUV', '诗篇', 19, 119, 45, '我要自由而行（或译：我要行在宽阔之地），因我素来考究你的训词。'),
('CUV', '诗篇', 19, 119, 46, '我也要在君王面前论说你的法度，并不至于羞愧。'),
('CUV', '诗篇', 19, 119, 47, '我要在你的命令中自乐；这命令素来是我所爱的。'),
('CUV', '诗篇', 19, 119, 48, '我又要遵行（原文是举手）你的命令，这命令素来是我所爱的；我也要思想你的律例。'),
('CUV', '诗篇', 19, 119, 49, '求你记念向你仆人所应许的话，叫我有盼望。'),
('CUV', '诗篇', 19, 119, 50, '这话将我救活了；我在患难中，因此得安慰。'),
('CUV', '诗篇', 19, 119, 51, '骄傲的人甚侮慢我，我却未曾偏离你的律法。'),
('CUV', '诗篇', 19, 119, 52, '耶和华啊，我记念你从古以来的典章，就得了安慰。'),
('CUV', '诗篇', 19, 119, 53, '我见恶人离弃你的律法，就怒气发作，犹如火烧。'),
('CUV', '诗篇', 19, 119, 54, '我在世寄居，素来以你的律例为诗歌。'),
('CUV', '诗篇', 19, 119, 55, '耶和华啊，我夜间记念你的名，遵守你的律法。'),
('CUV', '诗篇', 19, 119, 56, '我所以如此，是因我守你的训词。'),
('CUV', '诗篇', 19, 119, 57, '耶和华是我的福分；我曾说，我要遵守你的言语。'),
('CUV', '诗篇', 19, 119, 58, '我一心求过你的恩；愿你照你的话怜悯我！'),
('CUV', '诗篇', 19, 119, 59, '我思想我所行的道，就转步归向你的法度。'),
('CUV', '诗篇', 19, 119, 60, '我急忙遵守你的命令，并不迟延。'),
('CUV', '诗篇', 19, 119, 61, '恶人的绳索缠绕我，我却没有忘记你的律法。'),
('CUV', '诗篇', 19, 119, 62, '我因你公义的典章，半夜必起来称谢你。'),
('CUV', '诗篇', 19, 119, 63, '凡敬畏你、守你训词的人，我都与他作伴。'),
('CUV', '诗篇', 19, 119, 64, '耶和华啊，你的慈爱遍满大地；求你将你的律例教训我！'),
('CUV', '诗篇', 19, 119, 65, '耶和华啊，你向来是照你的话善待仆人。'),
('CUV', '诗篇', 19, 119, 66, '求你将精明和知识赐给我，因我信了你的命令。'),
('CUV', '诗篇', 19, 119, 67, '我未受苦以先走迷了路，现在却遵守你的话。'),
('CUV', '诗篇', 19, 119, 68, '你本为善，所行的也善；求你将你的律例教训我！'),
('CUV', '诗篇', 19, 119, 69, '骄傲人编造谎言攻击我，我却要一心守你的训词。'),
('CUV', '诗篇', 19, 119, 70, '他们心蒙脂油，我却喜爱你的律法。'),
('CUV', '诗篇', 19, 119, 71, '我受苦是与我有益，为要使我学习你的律例。'),
('CUV', '诗篇', 19, 119, 72, '你口中的训言（或译：律法）与我有益，胜于千万的金银。'),
('CUV', '诗篇', 19, 119, 73, '你的手制造我，建立我；求你赐我悟性，可以学习你的命令！'),
('CUV', '诗篇', 19, 119, 74, '敬畏你的人见我就要欢喜，因我仰望你的话。'),
('CUV', '诗篇', 19, 119, 75, '耶和华啊，我知道你的判语是公义的；你使我受苦是以诚实待我。'),
('CUV', '诗篇', 19, 119, 76, '求你照著应许仆人的话，以慈爱安慰我。'),
('CUV', '诗篇', 19, 119, 77, '愿你的慈悲临到我，使我存活，因你的律法是我所喜爱的。'),
('CUV', '诗篇', 19, 119, 78, '愿骄傲人蒙羞，因为他们无理地倾覆我；但我要思想你的训词。'),
('CUV', '诗篇', 19, 119, 79, '愿敬畏你的人归向我，他们就知道你的法度。'),
('CUV', '诗篇', 19, 119, 80, '愿我的心在你的律例上完全，使我不致蒙羞。'),
('CUV', '诗篇', 19, 119, 81, '我心渴想你的救恩，仰望你的应许。'),
('CUV', '诗篇', 19, 119, 82, '我因盼望你的应许眼睛失明，说：你何时安慰我？'),
('CUV', '诗篇', 19, 119, 83, '我好像烟薰的皮袋，却不忘记你的律例。'),
('CUV', '诗篇', 19, 119, 84, '你仆人的年日有多少呢？你几时向逼迫我的人施行审判呢？'),
('CUV', '诗篇', 19, 119, 85, '不从你律法的骄傲人为我掘了坑。'),
('CUV', '诗篇', 19, 119, 86, '你的命令尽都诚实；他们无理地逼迫我，求你帮助我！'),
('CUV', '诗篇', 19, 119, 87, '他们几乎把我从世上灭绝，但我没有离弃你的训词。'),
('CUV', '诗篇', 19, 119, 88, '求你照你的慈爱将我救活，我就遵守你口中的法度。'),
('CUV', '诗篇', 19, 119, 89, '耶和华啊，你的话安定在天，直到永远。'),
('CUV', '诗篇', 19, 119, 90, '你的诚实存到万代；你坚定了地，地就长存。'),
('CUV', '诗篇', 19, 119, 91, '天地照你的安排存到今日；万物都是你的仆役。'),
('CUV', '诗篇', 19, 119, 92, '我若不是喜爱你的律法，早就在苦难中灭绝了！'),
('CUV', '诗篇', 19, 119, 93, '我永不忘记你的训词，因你用这训词将我救活了。'),
('CUV', '诗篇', 19, 119, 94, '我是属你的，求你救我，因我寻求了你的训词。'),
('CUV', '诗篇', 19, 119, 95, '恶人等待我，要灭绝我，我却要揣摩你的法度。'),
('CUV', '诗篇', 19, 119, 96, '我看万事尽都有限，惟有你的命令极其宽广。'),
('CUV', '诗篇', 19, 119, 97, '我何等爱慕你的律法，终日不住地思想。'),
('CUV', '诗篇', 19, 119, 98, '你的命令常存在我心里，使我比仇敌有智慧。'),
('CUV', '诗篇', 19, 119, 99, '我比我的师傅更通达，因我思想你的法度。'),
('CUV', '诗篇', 19, 119, 100, '我比年老的更明白，因我守了你的训词。'),
('CUV', '诗篇', 19, 119, 101, '我禁止我脚走一切的邪路，为要遵守你的话。'),
('CUV', '诗篇', 19, 119, 102, '我没有偏离你的典章，因为你教训了我。'),
('CUV', '诗篇', 19, 119, 103, '你的言语在我上膛何等甘美，在我口中比蜜更甜！'),
('CUV', '诗篇', 19, 119, 104, '我藉著你的训词得以明白，所以我恨一切的假道。'),
('CUV', '诗篇', 19, 119, 105, '你的话是我脚前的灯，是我路上的光。'),
('CUV', '诗篇', 19, 119, 106, '你公义的典章，我曾起誓遵守，我必按誓而行。'),
('CUV', '诗篇', 19, 119, 107, '我甚是受苦；耶和华啊，求你照你的话将我救活！'),
('CUV', '诗篇', 19, 119, 108, '耶和华啊，求你悦纳我口中的赞美为供物，又将你的典章教训我！'),
('CUV', '诗篇', 19, 119, 109, '我的性命常在危险之中，我却不忘记你的律法。'),
('CUV', '诗篇', 19, 119, 110, '恶人为我设下网罗，我却没有偏离你的训词。'),
('CUV', '诗篇', 19, 119, 111, '我以你的法度为永远的产业，因这是我心中所喜爱的。'),
('CUV', '诗篇', 19, 119, 112, '我的心专向你的律例，永远遵行，一直到底。'),
('CUV', '诗篇', 19, 119, 113, '心怀二意的人为我所恨；但你的律法为我所爱。'),
('CUV', '诗篇', 19, 119, 114, '你是我藏身之处，又是我的盾牌；我甚仰望你的话语。'),
('CUV', '诗篇', 19, 119, 115, '作恶的人哪，你们离开我罢！我好遵守我神的命令。'),
('CUV', '诗篇', 19, 119, 116, '求你照你的话扶持我，使我存活，也不叫我因失望而害羞。'),
('CUV', '诗篇', 19, 119, 117, '求你扶持我，我便得救，时常看重你的律例。'),
('CUV', '诗篇', 19, 119, 118, '凡偏离你律例的人，你都轻弃他们，因为他们的诡诈必归虚空。'),
('CUV', '诗篇', 19, 119, 119, '凡地上的恶人，你除掉他，好像除掉渣滓；因此我爱你的法度。'),
('CUV', '诗篇', 19, 119, 120, '我因惧怕你，肉就发抖；我也怕你的判语。'),
('CUV', '诗篇', 19, 119, 121, '我行过公平和公义，求你不要撇下我给欺压我的人！'),
('CUV', '诗篇', 19, 119, 122, '求你为仆人作保，使我得好处，不容骄傲人欺压我！'),
('CUV', '诗篇', 19, 119, 123, '我因盼望你的救恩和你公义的话眼睛失明。'),
('CUV', '诗篇', 19, 119, 124, '求你照你的慈爱待仆人，将你的律例教训我。'),
('CUV', '诗篇', 19, 119, 125, '我是你的仆人，求你赐我悟性，使我得知你的法度。'),
('CUV', '诗篇', 19, 119, 126, '这是耶和华降罚的时候，因人废了你的律法。'),
('CUV', '诗篇', 19, 119, 127, '所以，我爱你的命令胜于金子，更胜于精金。'),
('CUV', '诗篇', 19, 119, 128, '你一切的训词，在万事上我都以为正直；我却恨恶一切假道。'),
('CUV', '诗篇', 19, 119, 129, '你的法度奇妙，所以我一心谨守。'),
('CUV', '诗篇', 19, 119, 130, '你的言语一解开就发出亮光，使愚人通达。'),
('CUV', '诗篇', 19, 119, 131, '我张口而气喘，因我切慕你的命令。'),
('CUV', '诗篇', 19, 119, 132, '求你转向我，怜悯我，好像你素常待那些爱你名的人。'),
('CUV', '诗篇', 19, 119, 133, '求你用你的话使我脚步稳当，不许甚么罪孽辖制我。'),
('CUV', '诗篇', 19, 119, 134, '求你救我脱离人的欺压，我要遵守你的训词。'),
('CUV', '诗篇', 19, 119, 135, '求你用脸光照仆人，又将你的律例教训我。'),
('CUV', '诗篇', 19, 119, 136, '我的眼泪下流成河，因为他们不守你的律法。'),
('CUV', '诗篇', 19, 119, 137, '耶和华啊，你是公义的；你的判语也是正直的！'),
('CUV', '诗篇', 19, 119, 138, '你所命定的法度是凭公义和至诚。'),
('CUV', '诗篇', 19, 119, 139, '我心焦急，如同火烧，因我敌人忘记你的言语。'),
('CUV', '诗篇', 19, 119, 140, '你的话极其精炼，所以你的仆人喜爱。'),
('CUV', '诗篇', 19, 119, 141, '我微小，被人藐视，却不忘记你的训词。'),
('CUV', '诗篇', 19, 119, 142, '你的公义永远长存；你的律法尽都真实。'),
('CUV', '诗篇', 19, 119, 143, '我遭遇患难愁苦，你的命令却是我所喜爱的。'),
('CUV', '诗篇', 19, 119, 144, '你的法度永远是公义的；求你赐我悟性，我就活了。'),
('CUV', '诗篇', 19, 119, 145, '耶和华啊，我一心呼吁你；求你应允我，我必谨守你的律例！'),
('CUV', '诗篇', 19, 119, 146, '我向你呼吁，求你救我！我要遵守你的法度。'),
('CUV', '诗篇', 19, 119, 147, '我趁天未亮呼求；我仰望了你的言语。'),
('CUV', '诗篇', 19, 119, 148, '我趁夜更未换将眼睁开，为要思想你的话语。'),
('CUV', '诗篇', 19, 119, 149, '求你照你的慈爱听我的声音；耶和华啊，求你照你的典章将我救活！'),
('CUV', '诗篇', 19, 119, 150, '追求奸恶的人临近了；他们远离你的律法。'),
('CUV', '诗篇', 19, 119, 151, '耶和华啊，你与我相近；你一切的命令尽都真实！'),
('CUV', '诗篇', 19, 119, 152, '我因学你的法度，久已知道是你永远立定的。'),
('CUV', '诗篇', 19, 119, 153, '求你看顾我的苦难，搭救我，因我不忘记你的律法。'),
('CUV', '诗篇', 19, 119, 154, '求你为我辨屈，救赎我，照你的话将我救活。'),
('CUV', '诗篇', 19, 119, 155, '救恩远离恶人，因为他们不寻求你的律例。'),
('CUV', '诗篇', 19, 119, 156, '耶和华啊，你的慈悲本为大；求你照你的典章将我救活。'),
('CUV', '诗篇', 19, 119, 157, '逼迫我的，抵挡我的，很多，我却没有偏离你的法度。'),
('CUV', '诗篇', 19, 119, 158, '我看见奸恶的人就甚憎恶，因为他们不遵守你的话。'),
('CUV', '诗篇', 19, 119, 159, '你看我怎样爱你的训词！耶和华啊，求你照你的慈爱将我救活！'),
('CUV', '诗篇', 19, 119, 160, '你话的总纲是真实；你一切公义的典章是永远长存。'),
('CUV', '诗篇', 19, 119, 161, '首领无故地逼迫我，但我的心畏惧你的言语。'),
('CUV', '诗篇', 19, 119, 162, '我喜爱你的话，好像人得了许多掳物。'),
('CUV', '诗篇', 19, 119, 163, '谎话是我所恨恶所憎嫌的；惟你的律法是我所爱的。'),
('CUV', '诗篇', 19, 119, 164, '我因你公义的典章一天七次赞美你。'),
('CUV', '诗篇', 19, 119, 165, '爱你律法的人有大平安，甚么都不能使他们绊脚。'),
('CUV', '诗篇', 19, 119, 166, '耶和华啊，我仰望了你的救恩，遵行了你的命令。'),
('CUV', '诗篇', 19, 119, 167, '我心里守了你的法度；这法度我甚喜爱。'),
('CUV', '诗篇', 19, 119, 168, '我遵守了你的训词和法度，因我一切所行的都在你面前。'),
('CUV', '诗篇', 19, 119, 169, '耶和华啊，愿我的呼吁达到你面前，照你的话赐我悟性。'),
('CUV', '诗篇', 19, 119, 170, '愿我的恳求达到你面前，照你的话搭救我。'),
('CUV', '诗篇', 19, 119, 171, '愿我的嘴发出赞美的话，因为你将律例教训我。'),
('CUV', '诗篇', 19, 119, 172, '愿我的舌头歌唱你的话，因你一切的命令尽都公义。'),
('CUV', '诗篇', 19, 119, 173, '愿你用手帮助我，因我拣选了你的训词。'),
('CUV', '诗篇', 19, 119, 174, '耶和华啊，我切慕你的救恩！你的律法也是我所喜爱的。'),
('CUV', '诗篇', 19, 119, 175, '愿我的性命存活，得以赞美你！愿你的典章帮助我！'),
('CUV', '诗篇', 19, 119, 176, '我如亡羊走迷了路，求你寻找仆人，因我不忘记你的命令。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 120, 1, '（上行（或作登阶，下同）之诗。）我在急难中求告耶和华，他就应允我。'),
('CUV', '诗篇', 19, 120, 2, '耶和华啊，求你救我脱离说谎的嘴唇和诡诈的舌头！'),
('CUV', '诗篇', 19, 120, 3, '诡诈的舌头啊，要给你甚么呢？要拿甚么加给你呢？'),
('CUV', '诗篇', 19, 120, 4, '就是勇士的利箭和罗腾木（小树名，松类）的炭火。'),
('CUV', '诗篇', 19, 120, 5, '我寄居在米设，住在基达帐棚之中，有祸了！'),
('CUV', '诗篇', 19, 120, 6, '我与那恨恶和睦的人许久同住。'),
('CUV', '诗篇', 19, 120, 7, '我愿和睦，但我发言，他们就要争战。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 121, 1, '（上行之诗。）我要向山举目；我的帮助从何而来？'),
('CUV', '诗篇', 19, 121, 2, '我的帮助从造天地的耶和华而来。'),
('CUV', '诗篇', 19, 121, 3, '他必不叫你的脚摇动；保护你的必不打盹！'),
('CUV', '诗篇', 19, 121, 4, '保护以色列的，也不打盹也不睡觉。'),
('CUV', '诗篇', 19, 121, 5, '保护你的是耶和华；耶和华在你右边荫庇你。'),
('CUV', '诗篇', 19, 121, 6, '白日，太阳必不伤你；夜间，月亮必不害你。'),
('CUV', '诗篇', 19, 121, 7, '耶和华要保护你，免受一切的灾害；他要保护你的性命。'),
('CUV', '诗篇', 19, 121, 8, '你出你入，耶和华要保护你，从今时直到永远。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 122, 1, '（大卫上行之诗。）人对我说：我们往耶和华的殿去，我就欢喜。'),
('CUV', '诗篇', 19, 122, 2, '耶路撒冷啊，我们的脚站在你的门内。'),
('CUV', '诗篇', 19, 122, 3, '耶路撒冷被建造，如同连络整齐的一座城。'),
('CUV', '诗篇', 19, 122, 4, '众支派，就是耶和华的支派，上那里去，按以色列的常例（或译：作以色列的证据）称赞耶和华的名。'),
('CUV', '诗篇', 19, 122, 5, '因为在那里设立审判的宝座，就是大卫家的宝座。'),
('CUV', '诗篇', 19, 122, 6, '你们要为耶路撒冷求平安！耶路撒冷啊，爱你的人必然兴旺！'),
('CUV', '诗篇', 19, 122, 7, '愿你城中平安！愿你宫内兴旺！'),
('CUV', '诗篇', 19, 122, 8, '因我弟兄和同伴的缘故，我要说：愿平安在你中间！'),
('CUV', '诗篇', 19, 122, 9, '因耶和华─我们神殿的缘故，我要为你求福！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 123, 1, '（上行之诗。）坐在天上的主啊，我向你举目。'),
('CUV', '诗篇', 19, 123, 2, '看哪，仆人的眼睛怎样望主人的手，使女的眼睛怎样望主母的手，我们的眼睛也照样望耶和华─我们的神，直到他怜悯我们。'),
('CUV', '诗篇', 19, 123, 3, '耶和华啊，求你怜悯我们，怜悯我们！因为我们被藐视，已到极处。'),
('CUV', '诗篇', 19, 123, 4, '我们被那些安逸人的讥诮和骄傲人的藐视，已到极处。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 124, 1, '（大卫上行之诗。）以色列人要说：若不是耶和华帮助我们，'),
('CUV', '诗篇', 19, 124, 2, '若不是耶和华帮助我们，当人起来攻击我们、'),
('CUV', '诗篇', 19, 124, 3, '向我们发怒的时候，就把我们活活地吞了。'),
('CUV', '诗篇', 19, 124, 4, '那时，波涛必漫过我们，河水必淹没我们，'),
('CUV', '诗篇', 19, 124, 5, '狂傲的水必淹没我们。'),
('CUV', '诗篇', 19, 124, 6, '耶和华是应当称颂的！他没有把我们当野食交给他们吞吃（原文是牙齿）。'),
('CUV', '诗篇', 19, 124, 7, '我们好像雀鸟，从捕鸟人的网罗里逃脱；网罗破裂，我们逃脱了。'),
('CUV', '诗篇', 19, 124, 8, '我们得帮助，是在乎倚靠造天地之耶和华的名。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 125, 1, '（上行之诗。）倚靠耶和华的人好像锡安山，永不动摇。'),
('CUV', '诗篇', 19, 125, 2, '众山怎样围绕耶路撒冷，耶和华也照样围绕他的百姓，从今时直到永远。'),
('CUV', '诗篇', 19, 125, 3, '恶人的杖不常落在义人的分上，免得义人伸手作恶。'),
('CUV', '诗篇', 19, 125, 4, '耶和华啊，求你善待那些为善和心里正直的人。'),
('CUV', '诗篇', 19, 125, 5, '至于那偏行弯曲道路的人，耶和华必使他和作恶的人一同出去受刑。愿平安归于以色列！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 126, 1, '（上行之诗。）当耶和华将那些被掳的带回锡安的时候，我们好像做梦的人。'),
('CUV', '诗篇', 19, 126, 2, '我们满口喜笑、满舌欢呼的时候，外邦中就有人说：耶和华为他们行了大事！'),
('CUV', '诗篇', 19, 126, 3, '耶和华果然为我们行了大事，我们就欢喜。'),
('CUV', '诗篇', 19, 126, 4, '耶和华啊，求你使我们被掳的人归回，好像南地的河水复流。'),
('CUV', '诗篇', 19, 126, 5, '流泪撒种的，必欢呼收割！'),
('CUV', '诗篇', 19, 126, 6, '那带种流泪出去的，必要欢欢乐乐地带禾捆回来！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 127, 1, '（所罗门上行之诗。）若不是耶和华建造房屋，建造的人就枉然劳力；若不是耶和华看守城池，看守的人就枉然警醒。'),
('CUV', '诗篇', 19, 127, 2, '你们清晨早起，夜晚安歇，吃劳碌得来的饭，本是枉然；惟有耶和华所亲爱的，必叫他安然睡觉。'),
('CUV', '诗篇', 19, 127, 3, '儿女是耶和华所赐的产业；所怀的胎是他所给的赏赐。'),
('CUV', '诗篇', 19, 127, 4, '少年时所生的儿女好像勇士手中的箭。'),
('CUV', '诗篇', 19, 127, 5, '箭袋充满的人便为有福；他们在城门口和仇敌说话的时候，必不至于羞愧。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 128, 1, '（上行之诗。）凡敬畏耶和华、遵行他道的人便为有福！'),
('CUV', '诗篇', 19, 128, 2, '你要吃劳碌得来的；你要享福，事情顺利。'),
('CUV', '诗篇', 19, 128, 3, '你妻子在你的内室，好像多结果子的葡萄树；你儿女围绕你的桌子，好像橄榄栽子。'),
('CUV', '诗篇', 19, 128, 4, '看哪，敬畏耶和华的人必要这样蒙福！'),
('CUV', '诗篇', 19, 128, 5, '愿耶和华从锡安赐福给你！愿你一生一世看见耶路撒冷的好处！'),
('CUV', '诗篇', 19, 128, 6, '愿你看见你儿女的儿女！愿平安归于以色列！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 129, 1, '（上行之诗。）以色列当说：从我幼年以来，敌人屡次苦害我，'),
('CUV', '诗篇', 19, 129, 2, '从我幼年以来，敌人屡次苦害我，却没有胜了我。'),
('CUV', '诗篇', 19, 129, 3, '如同扶犁的在我背上扶犁而耕，耕的犁沟甚长。'),
('CUV', '诗篇', 19, 129, 4, '耶和华是公义的；他砍断了恶人的绳索。'),
('CUV', '诗篇', 19, 129, 5, '愿恨恶锡安的都蒙羞退后！'),
('CUV', '诗篇', 19, 129, 6, '愿他们像房顶上的草，未长成而枯干，'),
('CUV', '诗篇', 19, 129, 7, '收割的不够一把，捆禾的也不满怀。'),
('CUV', '诗篇', 19, 129, 8, '过路的也不说：愿耶和华所赐的福归与你们！我们奉耶和华的名给你们祝福！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 130, 1, '（上行之诗。）耶和华啊，我从深处向你求告！'),
('CUV', '诗篇', 19, 130, 2, '主啊，求你听我的声音！愿你侧耳听我恳求的声音！'),
('CUV', '诗篇', 19, 130, 3, '主─耶和华啊，你若究察罪孽，谁能站得住呢？'),
('CUV', '诗篇', 19, 130, 4, '但在你有赦免之恩，要叫人敬畏你。'),
('CUV', '诗篇', 19, 130, 5, '我等候耶和华，我的心等候；我也仰望他的话。'),
('CUV', '诗篇', 19, 130, 6, '我的心等候主，胜于守夜的，等候天亮，胜于守夜的，等候天亮。'),
('CUV', '诗篇', 19, 130, 7, '以色列啊，你当仰望耶和华！因他有慈爱，有丰盛的救恩。'),
('CUV', '诗篇', 19, 130, 8, '他必救赎以色列脱离一切的罪孽。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 131, 1, '（大卫上行之诗。）耶和华啊，我的心不狂傲，我的眼不高大；重大和测不透的事，我也不敢行。'),
('CUV', '诗篇', 19, 131, 2, '我的心平稳安静，好像断过奶的孩子在他母亲的怀中；我的心在我里面真像断过奶的孩子。'),
('CUV', '诗篇', 19, 131, 3, '以色列啊，你当仰望耶和华，从今时直到永远！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 132, 1, '（上行之诗。）耶和华啊，求你记念大卫所受的一切苦难！'),
('CUV', '诗篇', 19, 132, 2, '他怎样向耶和华起誓，向雅各的大能者许愿，'),
('CUV', '诗篇', 19, 132, 3, '说：我必不进我的帐幕，也不上我的床榻；'),
('CUV', '诗篇', 19, 132, 4, '我不容我的眼睛睡觉，也不容我的眼目打盹；'),
('CUV', '诗篇', 19, 132, 5, '直等我为耶和华寻得所在，为雅各的大能者寻得居所。'),
('CUV', '诗篇', 19, 132, 6, '我们听说约柜在以法他，我们在基列耶琳就寻见了。'),
('CUV', '诗篇', 19, 132, 7, '我们要进他的居所，在他脚凳前下拜。'),
('CUV', '诗篇', 19, 132, 8, '耶和华啊，求你兴起，和你有能力的约柜同入安息之所！'),
('CUV', '诗篇', 19, 132, 9, '愿你的祭司披上公义！愿你的圣民欢呼！'),
('CUV', '诗篇', 19, 132, 10, '求你因你仆人大卫的缘故，不要厌弃你的受膏者！'),
('CUV', '诗篇', 19, 132, 11, '耶和华向大卫、凭诚实起了誓，必不反复，说：我要使你所生的坐在你的宝座上。'),
('CUV', '诗篇', 19, 132, 12, '你的众子若守我的约和我所教训他们的法度，他们的子孙必永远坐在你的宝座上。'),
('CUV', '诗篇', 19, 132, 13, '因为耶和华拣选了锡安，愿意当作自己的居所，'),
('CUV', '诗篇', 19, 132, 14, '说：这是我永远安息之所；我要住在这里，因为是我所愿意的。'),
('CUV', '诗篇', 19, 132, 15, '我要使其中的粮食丰满，使其中的穷人饱足。'),
('CUV', '诗篇', 19, 132, 16, '我要使祭司披上救恩，圣民大声欢呼！'),
('CUV', '诗篇', 19, 132, 17, '我要叫大卫的角在那里发生；我为我的受膏者预备明灯。'),
('CUV', '诗篇', 19, 132, 18, '我要使他的仇敌披上羞耻；但他的冠冕要在头上发光。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 133, 1, '（大卫上行之诗。）看哪，弟兄和睦同居是何等地善，何等地美！'),
('CUV', '诗篇', 19, 133, 2, '这好比那贵重的油浇在亚伦的头上，流到胡须，又流到他的衣襟；'),
('CUV', '诗篇', 19, 133, 3, '又好比黑门的甘露降在锡安山；因为在那里有耶和华所命定的福，就是永远的生命。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 134, 1, '（上行之诗。）耶和华的仆人夜间站在耶和华殿中的，你们当称颂耶和华！'),
('CUV', '诗篇', 19, 134, 2, '你们当向圣所举手，称颂耶和华！'),
('CUV', '诗篇', 19, 134, 3, '愿造天地的耶和华，从锡安赐福给你们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 135, 1, '你们要赞美耶和华！你们要赞美耶和华的名！耶和华的仆人站在耶和华殿中；站在我们神殿院中的，你们要赞美他！'),
('CUV', '诗篇', 19, 135, 2, 'a'),
('CUV', '诗篇', 19, 135, 3, '你们要赞美耶和华！耶和华本为善；要歌颂他的名，因为这是美好的。'),
('CUV', '诗篇', 19, 135, 4, '耶和华拣选雅各归自己，拣选以色列特作自己的子民。'),
('CUV', '诗篇', 19, 135, 5, '原来我知道耶和华为大，也知道我们的主超乎万神之上。'),
('CUV', '诗篇', 19, 135, 6, '耶和华在天上，在地下，在海中，在一切的深处，都随自己的意旨而行。'),
('CUV', '诗篇', 19, 135, 7, '他使云雾从地极上腾，造电随雨而闪，从府库中带出风来。'),
('CUV', '诗篇', 19, 135, 8, '他将埃及头生的，连人带牲畜都击杀了。'),
('CUV', '诗篇', 19, 135, 9, '埃及啊，他施行神迹奇事，在你当中，在法老和他一切臣仆身上。'),
('CUV', '诗篇', 19, 135, 10, '他击杀许多的民，又杀戮大能的王，'),
('CUV', '诗篇', 19, 135, 11, '就是亚摩利王西宏和巴珊王噩，并迦南一切的国王，'),
('CUV', '诗篇', 19, 135, 12, '将他们的地赏赐他的百姓以色列为业。'),
('CUV', '诗篇', 19, 135, 13, '耶和华啊，你的名存到永远！耶和华啊，你可记念的名存到万代！'),
('CUV', '诗篇', 19, 135, 14, '耶和华要为他的百姓伸冤，为他的仆人后悔。'),
('CUV', '诗篇', 19, 135, 15, '外邦的偶像是金的，银的，是人手所造的；'),
('CUV', '诗篇', 19, 135, 16, '有口却不能言，有眼却不能看，'),
('CUV', '诗篇', 19, 135, 17, '有耳却不能听，口中也没有气息。'),
('CUV', '诗篇', 19, 135, 18, '造他的要和他一样，凡靠他的也要如此。'),
('CUV', '诗篇', 19, 135, 19, '以色列家啊，你们要称颂耶和华！亚伦家啊，你们要称颂耶和华！'),
('CUV', '诗篇', 19, 135, 20, '利未家啊，你们要称颂耶和华！你们敬畏耶和华的，要称颂耶和华！'),
('CUV', '诗篇', 19, 135, 21, '住在耶路撒冷的，耶和华该从锡安受称颂。你们要赞美耶和华！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 136, 1, '你们要称谢耶和华，因他本为善；他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 2, '你们要称谢万神之神，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 3, '你们要称谢万主之主，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 4, '称谢那独行大奇事的，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 5, '称谢那用智慧造天的，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 6, '称谢那铺地在水以上的，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 7, '称谢那造成大光的，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 8, '他造日头管白昼，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 9, '他造月亮星宿管黑夜，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 10, '称谢那击杀埃及人之长子的，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 11, '他领以色列人从他们中间出来，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 12, '他施展大能的手和伸出来的膀臂，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 13, '称谢那分裂红海的，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 14, '他领以色列从其中经过，因他的慈爱永远长存；'),
('CUV', '诗篇', 19, 136, 15, '却把法老和他的军兵推翻在红海里，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 16, '称谢那引导自己的民行走旷野的，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 17, '称谢那击杀大君王的，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 18, '他杀戮有名的君王，因他的慈爱永远长存；'),
('CUV', '诗篇', 19, 136, 19, '就是杀戮亚摩利王西宏，因他的慈爱永远长存；'),
('CUV', '诗篇', 19, 136, 20, '又杀巴珊王噩，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 21, '他将他们的地赐他的百姓为业，因他的慈爱永远长存；'),
('CUV', '诗篇', 19, 136, 22, '就是赐他的仆人以色列为业，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 23, '他顾念我们在卑微的地步，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 24, '他救拔我们脱离敌人，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 25, '他赐粮食给凡有血气的，因他的慈爱永远长存。'),
('CUV', '诗篇', 19, 136, 26, '你们要称谢天上的神，因他的慈爱永远长存。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 137, 1, '我们曾在巴比伦的河边坐下，一追想锡安就哭了。'),
('CUV', '诗篇', 19, 137, 2, '我们把琴挂在那里的柳树上；'),
('CUV', '诗篇', 19, 137, 3, '因为在那里，掳掠我们的要我们唱歌，抢夺我们的要我们作乐，说：给我们唱一首锡安歌罢！'),
('CUV', '诗篇', 19, 137, 4, '我们怎能在外邦唱耶和华的歌呢？'),
('CUV', '诗篇', 19, 137, 5, '耶路撒冷啊，我若忘记你，情愿我的右手忘记技巧！'),
('CUV', '诗篇', 19, 137, 6, '我若不记念你，若不看耶路撒冷过于我所最喜乐的，情愿我的舌头贴于上膛！'),
('CUV', '诗篇', 19, 137, 7, '耶路撒冷遭难的日子，以东人说：拆毁！拆毁！直拆到根基！耶和华啊，求你记念这仇！'),
('CUV', '诗篇', 19, 137, 8, '将要被灭的巴比伦城啊（城：原文是女子），报复你像你待我们的，那人便为有福！'),
('CUV', '诗篇', 19, 137, 9, '拿你的婴孩摔在磐石上的，那人便为有福！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 138, 1, '（大卫的诗。）我要一心称谢你，在诸神面前歌颂你。'),
('CUV', '诗篇', 19, 138, 2, '我要向你的圣殿下拜，为你的慈爱和诚实称赞你的名；因你使你的话显为大，过于你所应许的（或译：超乎你的名声）。'),
('CUV', '诗篇', 19, 138, 3, '我呼求的日子，你就应允我，鼓励我，使我心里有能力。'),
('CUV', '诗篇', 19, 138, 4, '耶和华啊，地上的君王都要称谢你，因他们听见了你口中的言语。'),
('CUV', '诗篇', 19, 138, 5, '他们要歌颂耶和华的作为，因耶和华大有荣耀。'),
('CUV', '诗篇', 19, 138, 6, '耶和华虽高，仍看顾低微的人；他却从远处看出骄傲的人。'),
('CUV', '诗篇', 19, 138, 7, '我虽行在患难中，你必将我救活；我的仇敌发怒，你必伸手抵挡他们；你的右手也必救我。'),
('CUV', '诗篇', 19, 138, 8, '耶和华必成全关乎我的事；耶和华啊，你的慈爱永远长存！求你不要离弃你手所造的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 139, 1, '（大卫的诗，交与伶长。）耶和华啊，你已经鉴察我，认识我。'),
('CUV', '诗篇', 19, 139, 2, '我坐下，我起来，你都晓得；你从远处知道我的意念。'),
('CUV', '诗篇', 19, 139, 3, '我行路，我躺卧，你都细察；你也深知我一切所行的。'),
('CUV', '诗篇', 19, 139, 4, '耶和华啊，我舌头上的话，你没有一句不知道的。'),
('CUV', '诗篇', 19, 139, 5, '你在我前后环绕我，按手在我身上。'),
('CUV', '诗篇', 19, 139, 6, '这样的知识奇妙，是我不能测的，至高，是我不能及的。'),
('CUV', '诗篇', 19, 139, 7, '我往哪里去躲避你的灵？我往哪里逃、躲避你的面？'),
('CUV', '诗篇', 19, 139, 8, '我若升到天上，你在那里；我若在阴间下榻，你也在那里。'),
('CUV', '诗篇', 19, 139, 9, '我若展开清晨的翅膀，飞到海极居住，'),
('CUV', '诗篇', 19, 139, 10, '就是在那里，你的手必引导我；你的右手也必扶持我。'),
('CUV', '诗篇', 19, 139, 11, '我若说：黑暗必定遮蔽我，我周围的亮光必成为黑夜；'),
('CUV', '诗篇', 19, 139, 12, '黑暗也不能遮蔽我，使你不见，黑夜却如白昼发亮。黑暗和光明，在你看都是一样。'),
('CUV', '诗篇', 19, 139, 13, '我的肺腑是你所造的；我在母腹中，你已覆庇我。'),
('CUV', '诗篇', 19, 139, 14, '我要称谢你，因我受造，奇妙可畏；你的作为奇妙，这是我心深知道的。'),
('CUV', '诗篇', 19, 139, 15, '我在暗中受造，在地的深处被联络；那时，我的形体并不向你隐藏。'),
('CUV', '诗篇', 19, 139, 16, '我未成形的体质，你的眼早已看见了；你所定的日子，我尚未度一日（或译：我被造的肢体尚未有其一），你都写在你的册上了。'),
('CUV', '诗篇', 19, 139, 17, '神啊，你的意念向我何等宝贵！其数何等众多！'),
('CUV', '诗篇', 19, 139, 18, '我若数点，比海沙更多；我睡醒的时候，仍和你同在。'),
('CUV', '诗篇', 19, 139, 19, '神啊，你必要杀戮恶人；所以，你们好流人血的，离开我去罢！'),
('CUV', '诗篇', 19, 139, 20, '因为他们说恶言顶撞你；你的仇敌也妄称你的名。'),
('CUV', '诗篇', 19, 139, 21, '耶和华啊，恨恶你的，我岂不恨恶他们么？攻击你的，我岂不憎嫌他们么？'),
('CUV', '诗篇', 19, 139, 22, '我切切地恨恶他们，以他们为仇敌。'),
('CUV', '诗篇', 19, 139, 23, '神啊，求你鉴察我，知道我的心思，试炼我，知道我的意念，'),
('CUV', '诗篇', 19, 139, 24, '看在我里面有甚么恶行没有，引导我走永生的道路。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 140, 1, '（大卫的诗，交与伶长。）耶和华啊，求你拯救我脱离凶恶的人，保护我脱离强暴的人！'),
('CUV', '诗篇', 19, 140, 2, '他们心中图谋奸恶，常常聚集要争战。'),
('CUV', '诗篇', 19, 140, 3, '他们使舌头尖利如蛇，嘴里有虺蛇的毒气。（细拉）'),
('CUV', '诗篇', 19, 140, 4, '耶和华啊，求你拯救我脱离恶人的手，保护我脱离强暴的人！他们图谋推我跌倒。'),
('CUV', '诗篇', 19, 140, 5, '骄傲人为我暗设网罗和绳索；他们在路旁铺下网，设下圈套。（细拉）'),
('CUV', '诗篇', 19, 140, 6, '我曾对耶和华说：你是我的神。耶和华啊，求你留心听我恳求的声音！'),
('CUV', '诗篇', 19, 140, 7, '主─耶和华、我救恩的力量啊，在争战的日子，你遮蔽了我的头。'),
('CUV', '诗篇', 19, 140, 8, '耶和华啊，求你不要遂恶人的心愿；不要成就他们的计谋，恐怕他们自高。（细拉）'),
('CUV', '诗篇', 19, 140, 9, '至于那些昂首围困我的人，愿他们嘴唇的奸恶陷害（原文是遮蔽自己）！'),
('CUV', '诗篇', 19, 140, 10, '愿火炭落在他们身上！愿他们被丢在火中，抛在深坑里，不能再起来。'),
('CUV', '诗篇', 19, 140, 11, '说恶言的人在地上必坚立不住；祸患必猎取强暴的人，将他打倒。'),
('CUV', '诗篇', 19, 140, 12, '我知道耶和华必为困苦人伸冤，必为穷乏人辨屈。'),
('CUV', '诗篇', 19, 140, 13, '义人必要称赞你的名；正直人必住在你面前。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 141, 1, '（大卫的诗。）耶和华啊，我曾求告你，求你快快临到我这里！我求告你的时候，愿你留心听我的声音！'),
('CUV', '诗篇', 19, 141, 2, '愿我的祷告如香陈列在你面前！愿我举手祈求，如献晚祭！'),
('CUV', '诗篇', 19, 141, 3, '耶和华啊，求你禁止我的口，把守我的嘴！'),
('CUV', '诗篇', 19, 141, 4, '求你不叫我的心偏向邪恶，以致我和作孽的人同行恶事；也不叫我吃他们的美食。'),
('CUV', '诗篇', 19, 141, 5, '任凭义人击打我，这算为仁慈；任凭他责备我，这算为头上的膏油；我的头不要躲闪。正在他们行恶的时候，我仍要祈祷。'),
('CUV', '诗篇', 19, 141, 6, '他们的审判官被扔在岩下；众人要听我的话，因为这话甘甜。'),
('CUV', '诗篇', 19, 141, 7, '我们的骨头散在墓旁，好像人耕田、刨地的土块。'),
('CUV', '诗篇', 19, 141, 8, '主─耶和华啊，我的眼目仰望你；我投靠你，求你不要将我撇得孤苦！'),
('CUV', '诗篇', 19, 141, 9, '求你保护我脱离恶人为我设的网罗和作孽之人的圈套！'),
('CUV', '诗篇', 19, 141, 10, '愿恶人落在自己的网里，我却得以逃脱。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 142, 1, '（大卫在洞里作的训诲诗，乃是祈祷。）我发声哀告耶和华，发声恳求耶和华。'),
('CUV', '诗篇', 19, 142, 2, '我在他面前吐露我的苦情，陈说我的患难。'),
('CUV', '诗篇', 19, 142, 3, '我的灵在我里面发昏的时候，你知道我的道路。在我行的路上，敌人为我暗设网罗。'),
('CUV', '诗篇', 19, 142, 4, '求你向我右边观看，因为没有人认识我；我无处避难，也没有人眷顾我。'),
('CUV', '诗篇', 19, 142, 5, '耶和华啊，我曾向你哀求。我说：你是我的避难所；在活人之地，你是我的福分。'),
('CUV', '诗篇', 19, 142, 6, '求你侧耳听我的呼求，因我落到极卑之地；求你救我脱离逼迫我的人，因为他们比我强盛。'),
('CUV', '诗篇', 19, 142, 7, '求你领我出离被囚之地，我好称赞你的名。义人必环绕我，因为你是用厚恩待我。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 143, 1, '（大卫的诗。）耶和华啊，求你听我的祷告，留心听我的恳求，凭你的信实和公义应允我。'),
('CUV', '诗篇', 19, 143, 2, '求你不要审问仆人；因为在你面前，凡活著的人没有一个是义的。'),
('CUV', '诗篇', 19, 143, 3, '原来仇敌逼迫我，将我打倒在地，使我住在幽暗之处，像死了许久的人一样。'),
('CUV', '诗篇', 19, 143, 4, '所以，我的灵在我里面发昏；我的心在我里面凄惨。'),
('CUV', '诗篇', 19, 143, 5, '我追想古时之日，思想你的一切作为，默念你手的工作。'),
('CUV', '诗篇', 19, 143, 6, '我向你举手；我的心渴想你，如干旱之地盼雨一样。（细拉）'),
('CUV', '诗篇', 19, 143, 7, '耶和华啊，求你速速应允我！我心神耗尽！不要向我掩面，免得我像那些下坑的人一样。'),
('CUV', '诗篇', 19, 143, 8, '求你使我清晨得听你慈爱之言，因我倚靠你；求你使我知道当行的路，因我的心仰望你。'),
('CUV', '诗篇', 19, 143, 9, '耶和华啊，求你救我脱离我的仇敌！我往你那里藏身。'),
('CUV', '诗篇', 19, 143, 10, '求你指教我遵行你的旨意，因你是我的神。你的灵本为善；求你引我到平坦之地。'),
('CUV', '诗篇', 19, 143, 11, '耶和华啊，求你为你的名将我救活，凭你的公义，将我从患难中领出来，'),
('CUV', '诗篇', 19, 143, 12, '凭你的慈爱剪除我的仇敌，灭绝一切苦待我的人，因我是你的仆人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 144, 1, '（大卫的诗。）耶和华─我的磐石是应当称颂的！他教导我的手争战，教导我的指头打仗。'),
('CUV', '诗篇', 19, 144, 2, '他是我慈爱的主，我的山寨，我的高台，我的救主，我的盾牌，是我所投靠的；他使我的百姓服在我以下。'),
('CUV', '诗篇', 19, 144, 3, '耶和华啊，人算甚么，你竟认识他！世人算甚么，你竟顾念他！'),
('CUV', '诗篇', 19, 144, 4, '人好像一口气；他的年日如同影儿快快过去。'),
('CUV', '诗篇', 19, 144, 5, '耶和华啊，求你使天下垂，亲自降临，摸山，山就冒烟。'),
('CUV', '诗篇', 19, 144, 6, '求你发出闪电，使他们四散，射出你的箭，使他们扰乱。'),
('CUV', '诗篇', 19, 144, 7, '求你从上伸手救拔我，救我出离大水，救我脱离外邦人的手。'),
('CUV', '诗篇', 19, 144, 8, '他们的口说谎话；他们的右手起假誓。'),
('CUV', '诗篇', 19, 144, 9, '神啊，我要向你唱新歌，用十弦瑟向你歌颂。'),
('CUV', '诗篇', 19, 144, 10, '你是那拯救君王的；你是那救仆人大卫脱离害命之刀的。'),
('CUV', '诗篇', 19, 144, 11, '求你救拔我，救我脱离外邦人的手。他们的口说谎话；他们的右手起假誓。'),
('CUV', '诗篇', 19, 144, 12, '我们的儿子从幼年好像树栽子长大；我们的女儿如同殿角石，是按建宫的样式凿成的。'),
('CUV', '诗篇', 19, 144, 13, '我们的仓盈满，能出各样的粮食；我们的羊在田间孳生千万。'),
('CUV', '诗篇', 19, 144, 14, '我们的牛驮著满驮，没有人闯进来抢夺，也没有人出去争战；我们的街市上也没有哭号的声音。'),
('CUV', '诗篇', 19, 144, 15, '遇见这光景的百姓便为有福！有耶和华为他们的神，这百姓便为有福！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 145, 1, '（大卫的赞美诗。）我的神我的王啊，我要尊崇你！我要永永远远称颂你的名！'),
('CUV', '诗篇', 19, 145, 2, '我要天天称颂你，也要永永远远赞美你的名！'),
('CUV', '诗篇', 19, 145, 3, '耶和华本为大，该受大赞美；其大无法测度。'),
('CUV', '诗篇', 19, 145, 4, '这代要对那代颂赞你的作为，也要传扬你的大能。'),
('CUV', '诗篇', 19, 145, 5, '我要默念你威严的尊荣和你奇妙的作为。'),
('CUV', '诗篇', 19, 145, 6, '人要传说你可畏之事的能力；我也要传扬你的大德。'),
('CUV', '诗篇', 19, 145, 7, '他们记念你的大恩就要传出来，并要歌唱你的公义。'),
('CUV', '诗篇', 19, 145, 8, '耶和华有恩惠，有怜悯，不轻易发怒，大有慈爱。'),
('CUV', '诗篇', 19, 145, 9, '耶和华善待万民；他的慈悲覆庇他一切所造的。'),
('CUV', '诗篇', 19, 145, 10, '耶和华啊，你一切所造的都要称谢你；你的圣民也要称颂你，'),
('CUV', '诗篇', 19, 145, 11, '传说你国的荣耀，谈论你的大能，'),
('CUV', '诗篇', 19, 145, 12, '好叫世人知道你大能的作为，并你国度威严的荣耀。'),
('CUV', '诗篇', 19, 145, 13, '你的国是永远的国！你执掌的权柄存到万代！'),
('CUV', '诗篇', 19, 145, 14, '凡跌倒的，耶和华将他们扶持；凡被压下的，将他们扶起。'),
('CUV', '诗篇', 19, 145, 15, '万民都举目仰望你；你随时给他们食物。'),
('CUV', '诗篇', 19, 145, 16, '你张手，使有生气的都随愿饱足。'),
('CUV', '诗篇', 19, 145, 17, '耶和华在他一切所行的，无不公义；在他一切所做的都有慈爱。'),
('CUV', '诗篇', 19, 145, 18, '凡求告耶和华的，就是诚心求告他的，耶和华便与他们相近。'),
('CUV', '诗篇', 19, 145, 19, '敬畏他的，他必成就他们的心愿，也必听他们的呼求，拯救他们。'),
('CUV', '诗篇', 19, 145, 20, '耶和华保护一切爱他的人，却要灭绝一切的恶人。'),
('CUV', '诗篇', 19, 145, 21, '我的口要说出赞美耶和华的话；惟愿凡有血气的都永永远远称颂他的圣名。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 146, 1, '你们要赞美耶和华！我的心哪，你要赞美耶和华！'),
('CUV', '诗篇', 19, 146, 2, '我一生要赞美耶和华！我还活的时候要歌颂我的神！'),
('CUV', '诗篇', 19, 146, 3, '你们不要倚靠君王，不要倚靠世人；他一点不能帮助。'),
('CUV', '诗篇', 19, 146, 4, '他的气一断，就归回尘土；他所打算的，当日就消灭了。'),
('CUV', '诗篇', 19, 146, 5, '以雅各的神为帮助、仰望耶和华─他神的，这人便为有福！'),
('CUV', '诗篇', 19, 146, 6, '耶和华造天、地、海，和其中的万物；他守诚实，直到永远。'),
('CUV', '诗篇', 19, 146, 7, '他为受屈的伸冤，赐食物与饥饿的。耶和华释放被囚的；'),
('CUV', '诗篇', 19, 146, 8, '耶和华开了瞎子的眼睛；耶和华扶起被压下的人。耶和华喜爱义人。'),
('CUV', '诗篇', 19, 146, 9, '耶和华保护寄居的，扶持孤儿和寡妇，却使恶人的道路弯曲。'),
('CUV', '诗篇', 19, 146, 10, '耶和华要作王，直到永远！锡安哪，你的神要作王，直到万代！你们要赞美耶和华！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 147, 1, '你们要赞美耶和华！因歌颂我们的神为善为美；赞美的话是合宜的。'),
('CUV', '诗篇', 19, 147, 2, '耶和华建造耶路撒冷，聚集以色列中被赶散的人。'),
('CUV', '诗篇', 19, 147, 3, '他医好伤心的人，裹好他们的伤处。'),
('CUV', '诗篇', 19, 147, 4, '他数点星宿的数目，一一称他的名。'),
('CUV', '诗篇', 19, 147, 5, '我们的主为大，最有能力；他的智慧无法测度。'),
('CUV', '诗篇', 19, 147, 6, '耶和华扶持谦卑人，将恶人倾覆于地。'),
('CUV', '诗篇', 19, 147, 7, '你们要以感谢向耶和华歌唱，用琴向我们的神歌颂。'),
('CUV', '诗篇', 19, 147, 8, '他用云遮天，为地降雨，使草生长在山上。'),
('CUV', '诗篇', 19, 147, 9, '他赐食给走兽和啼叫的小乌鸦。'),
('CUV', '诗篇', 19, 147, 10, '他不喜悦马的力大，不喜爱人的腿快。'),
('CUV', '诗篇', 19, 147, 11, '耶和华喜爱敬畏他和盼望他慈爱的人。'),
('CUV', '诗篇', 19, 147, 12, '耶路撒冷啊，你要颂赞耶和华！锡安哪，你要赞美你的神！'),
('CUV', '诗篇', 19, 147, 13, '因为他坚固了你的门闩，赐福给你中间的儿女。'),
('CUV', '诗篇', 19, 147, 14, '他使你境内平安，用上好的麦子使你满足。'),
('CUV', '诗篇', 19, 147, 15, '他发命在地；他的话颁行最快。'),
('CUV', '诗篇', 19, 147, 16, '他降雪如羊毛，撒霜如炉灰。'),
('CUV', '诗篇', 19, 147, 17, '他掷下冰雹如碎渣；他发出寒冷，谁能当得起呢？'),
('CUV', '诗篇', 19, 147, 18, '他一出令，这些就都消化；他使风刮起，水便流动。'),
('CUV', '诗篇', 19, 147, 19, '他将他的道指示雅各，将他的律例典章指示以色列。'),
('CUV', '诗篇', 19, 147, 20, '别国他都没有这样待过；至于他的典章，他们向来没有知道。你们要赞美耶和华！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 148, 1, '你们要赞美耶和华！从天上赞美耶和华，在高处赞美他！'),
('CUV', '诗篇', 19, 148, 2, '他的众使者都要赞美他！他的诸军都要赞美他！'),
('CUV', '诗篇', 19, 148, 3, '日头月亮，你们要赞美他！放光的星宿，你们都要赞美他！'),
('CUV', '诗篇', 19, 148, 4, '天上的天和天上的水，你们都要赞美他！'),
('CUV', '诗篇', 19, 148, 5, '愿这些都赞美耶和华的名！因他一吩咐便都造成。'),
('CUV', '诗篇', 19, 148, 6, '他将这些立定，直到永永远远；他定了命，不能废去（或译：越过）。'),
('CUV', '诗篇', 19, 148, 7, '所有在地上的，大鱼和一切深洋，'),
('CUV', '诗篇', 19, 148, 8, '火与冰雹，雪和雾气，成就他命的狂风，'),
('CUV', '诗篇', 19, 148, 9, '大山和小山，结果的树木和一切香柏树，'),
('CUV', '诗篇', 19, 148, 10, '野兽和一切牲畜，昆虫和飞鸟，'),
('CUV', '诗篇', 19, 148, 11, '世上的君王和万民，首领和世上一切审判官，'),
('CUV', '诗篇', 19, 148, 12, '少年人和处女，老年人和孩童，都当赞美耶和华！'),
('CUV', '诗篇', 19, 148, 13, '愿这些都赞美耶和华的名！因为独有他的名被尊崇；他的荣耀在天地之上。'),
('CUV', '诗篇', 19, 148, 14, '他将他百姓的角高举，因此他（或译：他使）一切圣民以色列人，就是与他相近的百姓，都赞美他！你们要赞美耶和华！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 149, 1, '你们要赞美耶和华！向耶和华唱新歌，在圣民的会中赞美他！'),
('CUV', '诗篇', 19, 149, 2, '愿以色列因造他的主欢喜！愿锡安的民因他们的王快乐！'),
('CUV', '诗篇', 19, 149, 3, '愿他们跳舞赞美他的名，击鼓弹琴歌颂他！'),
('CUV', '诗篇', 19, 149, 4, '因为耶和华喜爱他的百姓；他要用救恩当作谦卑人的妆饰。'),
('CUV', '诗篇', 19, 149, 5, '愿圣民因所得的荣耀高兴！愿他们在床上欢呼！'),
('CUV', '诗篇', 19, 149, 6, '愿他们口中称赞神为高，手里有两刃的刀，'),
('CUV', '诗篇', 19, 149, 7, '为要报复列邦，刑罚万民。'),
('CUV', '诗篇', 19, 149, 8, '要用链子捆他们的君王，用铁镣锁他们的大臣；'),
('CUV', '诗篇', 19, 149, 9, '要在他们身上施行所记录的审判。他的圣民都有这荣耀。你们要赞美耶和华！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '诗篇', 19, 150, 1, '你们要赞美耶和华！在神的圣所赞美他！在他显能力的穹苍赞美他！'),
('CUV', '诗篇', 19, 150, 2, '要因他大能的作为赞美他，按著他极美的大德赞美他！'),
('CUV', '诗篇', 19, 150, 3, '要用角声赞美他，鼓瑟弹琴赞美他！'),
('CUV', '诗篇', 19, 150, 4, '击鼓跳舞赞美他！用丝弦的乐器和箫的声音赞美他！'),
('CUV', '诗篇', 19, 150, 5, '用大响的钹赞美他！用高声的钹赞美他！'),
('CUV', '诗篇', 19, 150, 6, '凡有气息的都要赞美耶和华！你们要赞美耶和华！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 1, 1, '以色列王大卫儿子所罗门的箴言：'),
('CUV', '箴言', 20, 1, 2, '要使人晓得智慧和训诲，分辨通达的言语，'),
('CUV', '箴言', 20, 1, 3, '使人处事领受智慧、仁义、公平、正直的训诲，'),
('CUV', '箴言', 20, 1, 4, '使愚人灵明，使少年人有知识和谋略，'),
('CUV', '箴言', 20, 1, 5, '使智慧人听见，增长学问，使聪明人得著智谋'),
('CUV', '箴言', 20, 1, 6, '使人明白箴言和譬喻，懂得智慧人的言词和谜语。'),
('CUV', '箴言', 20, 1, 7, '敬畏耶和华是知识的开端；愚妄人藐视智慧和训诲。'),
('CUV', '箴言', 20, 1, 8, '我儿，要听你父亲的训诲，不可离弃你母亲的法则（或译：指教）；'),
('CUV', '箴言', 20, 1, 9, '因为这要作你头上的华冠，你项上的金链。'),
('CUV', '箴言', 20, 1, 10, '我儿，恶人若引诱你，你不可随从。'),
('CUV', '箴言', 20, 1, 11, '他们若说：你与我们同去，我们要埋伏流人之血，要蹲伏害无罪之人；'),
('CUV', '箴言', 20, 1, 12, '我们好像阴间，把他们活活吞下；他们如同下坑的人，被我们囫囵吞了；'),
('CUV', '箴言', 20, 1, 13, '我们必得各样宝物，将所掳来的，装满房屋；'),
('CUV', '箴言', 20, 1, 14, '你与我们大家同分，我们共用一个囊袋；'),
('CUV', '箴言', 20, 1, 15, '我儿，不要与他们同行一道，禁止你脚走他们的路。'),
('CUV', '箴言', 20, 1, 16, '因为，他们的脚奔跑行恶；他们急速流人的血，'),
('CUV', '箴言', 20, 1, 17, '好像飞鸟，网罗设在眼前仍不躲避。'),
('CUV', '箴言', 20, 1, 18, '这些人埋伏，是为自流己血；蹲伏，是为自害己命。'),
('CUV', '箴言', 20, 1, 19, '凡贪恋财利的，所行之路都是如此；这贪恋之心乃夺去得财者之命。'),
('CUV', '箴言', 20, 1, 20, '智慧在街市上呼喊，在宽阔处发声，'),
('CUV', '箴言', 20, 1, 21, '在热闹街头喊叫，在城门口，在城中发出言语，'),
('CUV', '箴言', 20, 1, 22, '说：你们愚昧人喜爱愚昧，亵慢人喜欢亵慢，愚顽人恨恶知识，要到几时呢？'),
('CUV', '箴言', 20, 1, 23, '你们当因我的责备回转；我要将我的灵浇灌你们，将我的话指示你们。'),
('CUV', '箴言', 20, 1, 24, '我呼唤，你们不肯听从；我伸手，无人理会；'),
('CUV', '箴言', 20, 1, 25, '反轻弃我一切的劝戒，不肯受我的责备。'),
('CUV', '箴言', 20, 1, 26, '你们遭灾难，我就发笑；惊恐临到你们，我必嗤笑。'),
('CUV', '箴言', 20, 1, 27, '惊恐临到你们，好像狂风；灾难来到，如同暴风；急难痛苦临到你们身上。'),
('CUV', '箴言', 20, 1, 28, '那时，你们必呼求我，我却不答应，恳切地寻找我，却寻不见。'),
('CUV', '箴言', 20, 1, 29, '因为，你们恨恶知识，不喜爱敬畏耶和华，'),
('CUV', '箴言', 20, 1, 30, '不听我的劝戒，藐视我一切的责备，'),
('CUV', '箴言', 20, 1, 31, '所以必吃自结的果子，充满自设的计谋.。'),
('CUV', '箴言', 20, 1, 32, '愚昧人背道，必杀己身；愚顽人安逸，必害己命。'),
('CUV', '箴言', 20, 1, 33, '惟有听从我的，必安然居住，得享安静，不怕灾祸。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 2, 1, '我儿，你若领受我的言语，存记我的命令，'),
('CUV', '箴言', 20, 2, 2, '侧耳听智慧，专心求聪明，'),
('CUV', '箴言', 20, 2, 3, '呼求明哲，扬声求聪明，'),
('CUV', '箴言', 20, 2, 4, '寻找他，如寻找银子，搜求他，如搜求隐藏的珍宝，'),
('CUV', '箴言', 20, 2, 5, '你就明白敬畏耶和华，得以认识神。'),
('CUV', '箴言', 20, 2, 6, '因为，耶和华赐人智慧；知识和聪明都由他口而出。'),
('CUV', '箴言', 20, 2, 7, '他给正直人存留真智慧，给行为纯正的人作盾牌，'),
('CUV', '箴言', 20, 2, 8, '为要保守公平人的路，护庇虔敬人的道。'),
('CUV', '箴言', 20, 2, 9, '你也必明白仁义、公平、正直、一切的善道。'),
('CUV', '箴言', 20, 2, 10, '智慧必入你心；你的灵要以知识为美。'),
('CUV', '箴言', 20, 2, 11, '谋略必护卫你；聪明必保守你，'),
('CUV', '箴言', 20, 2, 12, '要救你脱离恶道（或译：恶人的道），脱离说乖谬话的人。'),
('CUV', '箴言', 20, 2, 13, '那等人舍弃正直的路，行走黑暗的道，'),
('CUV', '箴言', 20, 2, 14, '欢喜作恶，喜爱恶人的乖僻，'),
('CUV', '箴言', 20, 2, 15, '在他们的道中弯曲，在他们的路上偏僻。'),
('CUV', '箴言', 20, 2, 16, '智慧要救你脱离淫妇，就是那油嘴滑舌的外女。'),
('CUV', '箴言', 20, 2, 17, '他离弃幼年的配偶，忘了神的盟约。'),
('CUV', '箴言', 20, 2, 18, '他的家陷入死地；他的路偏向阴间。'),
('CUV', '箴言', 20, 2, 19, '凡到他那里去的，不得转回，也得不著生命的路。'),
('CUV', '箴言', 20, 2, 20, '智慧必使你行善人的道，守义人的路。'),
('CUV', '箴言', 20, 2, 21, '正直人必在世上居住；完全人必在地上存留。'),
('CUV', '箴言', 20, 2, 22, '惟有恶人必然剪除；奸诈的，必然拔出。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 3, 1, '我儿，不要忘记我的法则（或译：指教）；你心要谨守我的诫命；'),
('CUV', '箴言', 20, 3, 2, '因为他必将长久的日子，生命的年数与平安，加给你。'),
('CUV', '箴言', 20, 3, 3, '不可使慈爱、诚实离开你，要系在你颈项上，刻在你心版上。'),
('CUV', '箴言', 20, 3, 4, '这样，你必在神和世人眼前蒙恩宠，有聪明。'),
('CUV', '箴言', 20, 3, 5, '你要专心仰赖耶和华，不可倚靠自己的聪明，'),
('CUV', '箴言', 20, 3, 6, '在你一切所行的事上都要认定他，他必指引你的路。'),
('CUV', '箴言', 20, 3, 7, '不要自以为有智慧；要敬畏耶和华，远离恶事。'),
('CUV', '箴言', 20, 3, 8, '这便医治你的肚脐，滋润你的百骨。'),
('CUV', '箴言', 20, 3, 9, '你要以财物和一切初熟的土产尊荣耶和华。'),
('CUV', '箴言', 20, 3, 10, '这样，你的仓房必充满有余；你的酒醡有新酒盈溢。'),
('CUV', '箴言', 20, 3, 11, '我儿，你不可轻看耶和华的管教（或译：惩治），也不可厌烦他的责备；'),
('CUV', '箴言', 20, 3, 12, '因为耶和华所爱的，他必责备，正如父亲责备所喜爱的儿子。'),
('CUV', '箴言', 20, 3, 13, '得智慧，得聪明的，这人便为有福。'),
('CUV', '箴言', 20, 3, 14, '因为得智慧胜过得银子，其利益强如精金，'),
('CUV', '箴言', 20, 3, 15, '比珍珠（或译：红宝石）宝贵；你一切所喜爱的，都不足与比较。'),
('CUV', '箴言', 20, 3, 16, '他右手有长寿，左手有富贵。'),
('CUV', '箴言', 20, 3, 17, '他的道是安乐；他的路全是平安。'),
('CUV', '箴言', 20, 3, 18, '他与持守他的作生命树；持定他的，俱各有福。'),
('CUV', '箴言', 20, 3, 19, '耶和华以智慧立地，以聪明定天，'),
('CUV', '箴言', 20, 3, 20, '以知识使深渊裂开，使天空滴下甘露。'),
('CUV', '箴言', 20, 3, 21, '我儿，要谨守真智慧和谋略，不可使他离开你的眼目。'),
('CUV', '箴言', 20, 3, 22, '这样，他必作你的生命，颈项的美饰。'),
('CUV', '箴言', 20, 3, 23, '你就坦然行路，不致碰脚。'),
('CUV', '箴言', 20, 3, 24, '你躺下，必不惧怕；你躺卧，睡得香甜。'),
('CUV', '箴言', 20, 3, 25, '忽然来的惊恐，不要害怕；恶人遭毁灭，也不要恐惧。'),
('CUV', '箴言', 20, 3, 26, '因为耶和华是你所倚靠的；他必保守你的脚不陷入网罗。'),
('CUV', '箴言', 20, 3, 27, '你手若有行善的力量，不可推辞，就当向那应得的人施行。'),
('CUV', '箴言', 20, 3, 28, '你那里若有现成的，不可对邻舍说：去罢，明天再来，我必给你。'),
('CUV', '箴言', 20, 3, 29, '你的邻舍既在你附近安居，你不可设计害他。'),
('CUV', '箴言', 20, 3, 30, '人未曾加害与你，不可无故与他相争。'),
('CUV', '箴言', 20, 3, 31, '不可嫉妒强暴的人，也不可选择他所行的路。'),
('CUV', '箴言', 20, 3, 32, '因为，乖僻人为耶和华所憎恶；正直人为他所亲密。'),
('CUV', '箴言', 20, 3, 33, '耶和华咒诅恶人的家庭，赐福与义人的居所。'),
('CUV', '箴言', 20, 3, 34, '他讥诮那好讥诮的人，赐恩给谦卑的人。'),
('CUV', '箴言', 20, 3, 35, '智慧人必承受尊荣；愚昧人高升也成为羞辱。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 4, 1, '众子啊，要听父亲的教训，留心得知聪明。'),
('CUV', '箴言', 20, 4, 2, '因我所给你们的是好教训；不可离弃我的法则（或译：指教）。'),
('CUV', '箴言', 20, 4, 3, '我在父亲面前为孝子，在母亲眼中为独一的娇儿。'),
('CUV', '箴言', 20, 4, 4, '父亲教训我说：你心要存记我的言语，遵守我的命令，便得存活。'),
('CUV', '箴言', 20, 4, 5, '要得智慧，要得聪明，不可忘记，也不可偏离我口中的言语。'),
('CUV', '箴言', 20, 4, 6, '不可离弃智慧，智慧就护卫你；要爱他，他就保守你。'),
('CUV', '箴言', 20, 4, 7, '智慧为首；所以，要得智慧。在你一切所得之内必得聪明.（或译：用你一切所得的去换聪明）。'),
('CUV', '箴言', 20, 4, 8, '高举智慧，他就使你高升；怀抱智慧，他就使你尊荣。'),
('CUV', '箴言', 20, 4, 9, '他必将华冠加在你头上，把荣冕交给你。'),
('CUV', '箴言', 20, 4, 10, '我儿，你要听受我的言语，就必延年益寿。'),
('CUV', '箴言', 20, 4, 11, '我已指教你走智慧的道，引导你行正直的路。'),
('CUV', '箴言', 20, 4, 12, '你行走，脚步必不致狭窄；你奔跑，也不致跌倒。'),
('CUV', '箴言', 20, 4, 13, '要持定训诲，不可放松；必当谨守，因为他是你的生命。'),
('CUV', '箴言', 20, 4, 14, '不可行恶人的路；不要走坏人的道。'),
('CUV', '箴言', 20, 4, 15, '要躲避，不可经过；要转身而去。'),
('CUV', '箴言', 20, 4, 16, '这等人若不行恶，不得睡觉；不使人跌倒，睡卧不安；'),
('CUV', '箴言', 20, 4, 17, '因为他们以奸恶吃饼，以强暴喝酒。'),
('CUV', '箴言', 20, 4, 18, '但义人的路好像黎明的光，越照越明，直到日午。'),
('CUV', '箴言', 20, 4, 19, '恶人的道好像幽暗，自己不知因甚么跌倒。'),
('CUV', '箴言', 20, 4, 20, '我儿，要留心听我的言词，侧耳听我的话语，'),
('CUV', '箴言', 20, 4, 21, '都不可离你的眼目，要存记在你心中。'),
('CUV', '箴言', 20, 4, 22, '因为得著他的，就得了生命，又得了医全体的良药。'),
('CUV', '箴言', 20, 4, 23, '你要保守你心，胜过保守一切（或译：你要切切保守你心），因为一生的果效是由心发出。'),
('CUV', '箴言', 20, 4, 24, '你要除掉邪僻的口，弃绝乖谬的嘴。'),
('CUV', '箴言', 20, 4, 25, '你的眼目要向前正看；你的眼睛（原文是皮）当向前直观。'),
('CUV', '箴言', 20, 4, 26, '要修平你脚下的路，坚定你一切的道。'),
('CUV', '箴言', 20, 4, 27, '不可偏向左右；要使你的脚离开邪恶。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 5, 1, '我儿，要留心我智慧的话语，侧耳听我聪明的言词，'),
('CUV', '箴言', 20, 5, 2, '为要使你谨守谋略，嘴唇保存知识。'),
('CUV', '箴言', 20, 5, 3, '因为淫妇的嘴滴下蜂蜜；他的口比油更滑，'),
('CUV', '箴言', 20, 5, 4, '至终却苦似茵𫈟，快如两刃的刀。'),
('CUV', '箴言', 20, 5, 5, '他的脚下入死地；他脚步踏住阴间，'),
('CUV', '箴言', 20, 5, 6, '以致他找不著生命平坦的道。他的路变迁不定，自己还不知道。'),
('CUV', '箴言', 20, 5, 7, '众子啊，现在要听从我；不可离弃我口中的话。'),
('CUV', '箴言', 20, 5, 8, '你所行的道要离他远，不可就近他的房门，'),
('CUV', '箴言', 20, 5, 9, '恐怕将你的尊荣给别人，将你的岁月给残忍的人；'),
('CUV', '箴言', 20, 5, 10, '恐怕外人满得你的力量，你劳碌得来的，归入外人的家；'),
('CUV', '箴言', 20, 5, 11, '终久，你皮肉和身体消毁，你就悲叹，'),
('CUV', '箴言', 20, 5, 12, '说：我怎么恨恶训诲，心中藐视责备，'),
('CUV', '箴言', 20, 5, 13, '也不听从我师傅的话，又不侧耳听那教训我的人？'),
('CUV', '箴言', 20, 5, 14, '我在圣会里，几乎落在诸般恶中。'),
('CUV', '箴言', 20, 5, 15, '你要喝自己池中的水，饮自己井里的活水。'),
('CUV', '箴言', 20, 5, 16, '你的泉源岂可涨溢在外？你的河水岂可流在街上？'),
('CUV', '箴言', 20, 5, 17, '惟独归你一人，不可与外人同用。'),
('CUV', '箴言', 20, 5, 18, '要使你的泉源蒙福；要喜悦你幼年所娶的妻。'),
('CUV', '箴言', 20, 5, 19, '他如可爱的麀鹿，可喜的母鹿；愿他的胸怀使你时时知足，他的爱情使你常常恋慕。'),
('CUV', '箴言', 20, 5, 20, '我儿，你为何恋慕淫妇？为何抱外女的胸怀？'),
('CUV', '箴言', 20, 5, 21, '因为，人所行的道都在耶和华眼前；他也修平人一切的路。'),
('CUV', '箴言', 20, 5, 22, '恶人必被自己的罪孽捉住；他必被自己的罪恶如绳索缠绕。'),
('CUV', '箴言', 20, 5, 23, '他因不受训诲就必死亡；又因愚昧过甚，必走差了路。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 6, 1, '我儿，你若为朋友作保，替外人击掌，'),
('CUV', '箴言', 20, 6, 2, '你就被口中的话语缠住，被嘴里的言语捉住。'),
('CUV', '箴言', 20, 6, 3, '我儿，你既落在朋友手中，就当这样行才可救自己：你要自卑，去恳求你的朋友。'),
('CUV', '箴言', 20, 6, 4, '不要容你的眼睛睡觉；不要容你的眼皮打盹。'),
('CUV', '箴言', 20, 6, 5, '要救自己，如鹿脱离猎户的手，如鸟脱离捕鸟人的手。'),
('CUV', '箴言', 20, 6, 6, '懒惰人哪，你去察看蚂蚁的动作就可得智慧。'),
('CUV', '箴言', 20, 6, 7, '蚂蚁没有元帅，没有官长，没有君王，'),
('CUV', '箴言', 20, 6, 8, '尚且在夏天预备食物，在收割时聚敛粮食。'),
('CUV', '箴言', 20, 6, 9, '懒惰人哪，你要睡到几时呢？你何时睡醒呢？'),
('CUV', '箴言', 20, 6, 10, '再睡片时，打盹片时，抱著手躺卧片时，'),
('CUV', '箴言', 20, 6, 11, '你的贫穷就必如强盗速来，你的缺乏仿佛拿兵器的人来到。'),
('CUV', '箴言', 20, 6, 12, '无赖的恶徒，行动就用乖僻的口，'),
('CUV', '箴言', 20, 6, 13, '用眼传神，用脚示意，用指点划，'),
('CUV', '箴言', 20, 6, 14, '心中乖僻，常设恶谋，布散纷争。'),
('CUV', '箴言', 20, 6, 15, '所以，灾难必忽然临到他身；他必顷刻败坏，无法可治。'),
('CUV', '箴言', 20, 6, 16, '耶和华所恨恶的有六样，连他心所憎恶的共有七样：'),
('CUV', '箴言', 20, 6, 17, '就是高傲的眼，撒谎的舌，流无辜人血的手，'),
('CUV', '箴言', 20, 6, 18, '图谋恶计的心，飞跑行恶的脚，'),
('CUV', '箴言', 20, 6, 19, '吐谎言的假见证，并弟兄中布散纷争的人。'),
('CUV', '箴言', 20, 6, 20, '我儿，要谨守你父亲的诫命；不可离弃你母亲的法则（或译：指教），'),
('CUV', '箴言', 20, 6, 21, '要常系在你心上，挂在你项上。'),
('CUV', '箴言', 20, 6, 22, '你行走，他必引导你；你躺卧，他必保守你；你睡醒，他必与你谈论。'),
('CUV', '箴言', 20, 6, 23, '因为诫命是灯，法则（或译：指教）是光，训诲的责备是生命的道，'),
('CUV', '箴言', 20, 6, 24, '能保你远离恶妇，远离外女谄媚的舌头。'),
('CUV', '箴言', 20, 6, 25, '你心中不要恋慕他的美色，也不要被他眼皮勾引。'),
('CUV', '箴言', 20, 6, 26, '因为，妓女能使人只剩一块饼；淫妇猎取人宝贵的生命。'),
('CUV', '箴言', 20, 6, 27, '人若怀里搋火，衣服岂能不烧呢？'),
('CUV', '箴言', 20, 6, 28, '人若在火炭上走，脚岂能不烫呢？'),
('CUV', '箴言', 20, 6, 29, '亲近邻舍之妻的，也是如此；凡挨近他的，不免受罚。'),
('CUV', '箴言', 20, 6, 30, '贼因饥饿偷窃充饥，人不藐视他，'),
('CUV', '箴言', 20, 6, 31, '若被找著，他必赔还七倍，必将家中所有的尽都偿还。'),
('CUV', '箴言', 20, 6, 32, '与妇人行淫的，便是无知；行这事的，必丧掉生命。'),
('CUV', '箴言', 20, 6, 33, '他必受伤损，必被凌辱；他的羞耻不得涂抹。'),
('CUV', '箴言', 20, 6, 34, '因为人的嫉恨成了烈怒，报仇的时候决不留情。'),
('CUV', '箴言', 20, 6, 35, '甚么赎价，他都不顾；你虽送许多礼物，他也不肯干休。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 7, 1, '我儿，你要遵守我的言语，将我的命令存记在心。'),
('CUV', '箴言', 20, 7, 2, '遵守我的命令就得存活；保守我的法则（或译：指教），好像保守眼中的瞳人，'),
('CUV', '箴言', 20, 7, 3, '系在你指头上，刻在你心版上。'),
('CUV', '箴言', 20, 7, 4, '对智慧说：你是我的姊妹，称呼聪明为你的亲人，'),
('CUV', '箴言', 20, 7, 5, '他就保你远离淫妇，远离说谄媚话的外女。'),
('CUV', '箴言', 20, 7, 6, '我曾在我房屋的窗户内，从我窗櫺之间往外观看：'),
('CUV', '箴言', 20, 7, 7, '见愚蒙人内，少年人中，分明有一个无知的少年人，'),
('CUV', '箴言', 20, 7, 8, '从街上经过，走近淫妇的巷口，直往通他家的路去，'),
('CUV', '箴言', 20, 7, 9, '在黄昏，或晚上，或半夜，或黑暗之中。'),
('CUV', '箴言', 20, 7, 10, '看哪，有一个妇人来迎接他，是妓女的打扮，有诡诈的心思。'),
('CUV', '箴言', 20, 7, 11, '这妇人喧嚷，不守约束，在家里停不住脚，'),
('CUV', '箴言', 20, 7, 12, '有时在街市上，有时在宽阔处，或在各巷口蹲伏，'),
('CUV', '箴言', 20, 7, 13, '拉住那少年人，与他亲嘴，脸无羞耻对他说：'),
('CUV', '箴言', 20, 7, 14, '平安祭在我这里，今日才还了我所许的愿。'),
('CUV', '箴言', 20, 7, 15, '因此，我出来迎接你，恳切求见你的面，恰巧遇见了你。'),
('CUV', '箴言', 20, 7, 16, '我已经用绣花毯子和埃及线织的花纹布铺了我的床。'),
('CUV', '箴言', 20, 7, 17, '我又用没药、沉香、桂皮薰了我的榻。'),
('CUV', '箴言', 20, 7, 18, '你来，我们可以饱享爱情，直到早晨；我们可以彼此亲爱欢乐。'),
('CUV', '箴言', 20, 7, 19, '因为我丈夫不在家，出门行远路；'),
('CUV', '箴言', 20, 7, 20, '他手拿银囊，必到月望才回家。'),
('CUV', '箴言', 20, 7, 21, '淫妇用许多巧言诱他随从，用谄媚的嘴逼他同行。'),
('CUV', '箴言', 20, 7, 22, '少年人立刻跟随他，好像牛往宰杀之地，又像愚昧人带锁链去受刑罚，'),
('CUV', '箴言', 20, 7, 23, '直等箭穿他的肝，如同雀鸟急入网罗，却不知是自丧己命。'),
('CUV', '箴言', 20, 7, 24, '众子啊，现在要听从我，留心听我口中的话。'),
('CUV', '箴言', 20, 7, 25, '你的心不可偏向淫妇的道，不要入他的迷途。'),
('CUV', '箴言', 20, 7, 26, '因为，被他伤害仆倒的不少；被他杀戮的而且甚多。'),
('CUV', '箴言', 20, 7, 27, '他的家是在阴间之路，下到死亡之宫。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 8, 1, '智慧岂不呼叫？聪明岂不发声？'),
('CUV', '箴言', 20, 8, 2, '他在道旁高处的顶上，在十字路口站立，'),
('CUV', '箴言', 20, 8, 3, '在城门旁，在城门口，在城门洞，大声说：'),
('CUV', '箴言', 20, 8, 4, '众人哪，我呼叫你们，我向世人发声。'),
('CUV', '箴言', 20, 8, 5, '说：愚蒙人哪，你们要会悟灵明；愚昧人哪，你们当心里明白。'),
('CUV', '箴言', 20, 8, 6, '你们当听，因我要说极美的话；我张嘴要论正直的事。'),
('CUV', '箴言', 20, 8, 7, '我的口要发出真理；我的嘴憎恶邪恶。'),
('CUV', '箴言', 20, 8, 8, '我口中的言语都是公义，并无弯曲乖僻。'),
('CUV', '箴言', 20, 8, 9, '有聪明的，以为明显，得知识的，以为正直。'),
('CUV', '箴言', 20, 8, 10, '你们当受我的教训，不受白银；宁得知识，胜过黄金。'),
('CUV', '箴言', 20, 8, 11, '因为智慧比珍珠（或译：红宝石）更美；一切可喜爱的都不足与比较。'),
('CUV', '箴言', 20, 8, 12, '我─智慧以灵明为居所，又寻得知识和谋略。'),
('CUV', '箴言', 20, 8, 13, '敬畏耶和华在乎恨恶邪恶；那骄傲、狂妄，并恶道，以及乖谬的口，都为我所恨恶。'),
('CUV', '箴言', 20, 8, 14, '我有谋略和真知识；我乃聪明，我有能力。'),
('CUV', '箴言', 20, 8, 15, '帝王藉我坐国位；君王藉我定公平。'),
('CUV', '箴言', 20, 8, 16, '王子和首领，世上一切的审判官，都是藉我掌权。'),
('CUV', '箴言', 20, 8, 17, '爱我的，我也爱他；恳切寻求我的，必寻得见。'),
('CUV', '箴言', 20, 8, 18, '丰富尊荣在我；恒久的财并公义也在我。'),
('CUV', '箴言', 20, 8, 19, '我的果实胜过黄金，强如精金；我的出产超乎高银。'),
('CUV', '箴言', 20, 8, 20, '我在公义的道上走，在公平的路中行，'),
('CUV', '箴言', 20, 8, 21, '使爱我的，承受货财，并充满他们的府库。'),
('CUV', '箴言', 20, 8, 22, '在耶和华造化的起头，在太初创造万物之先，就有了我。'),
('CUV', '箴言', 20, 8, 23, '从亘古，从太初，未有世界以前，我已被立。'),
('CUV', '箴言', 20, 8, 24, '没有深渊，没有大水的泉源，我已生出。'),
('CUV', '箴言', 20, 8, 25, '大山未曾奠定，小山未有之先，我已生出。'),
('CUV', '箴言', 20, 8, 26, '耶和华还没有创造大地和田野，并世上的土质，我已生出。'),
('CUV', '箴言', 20, 8, 27, '他立高天，我在那里；他在渊面的周围，划出圆圈。'),
('CUV', '箴言', 20, 8, 28, '上使穹苍坚硬，下使渊源稳固，'),
('CUV', '箴言', 20, 8, 29, '为沧海定出界限，使水不越过他的命令，立定大地的根基。'),
('CUV', '箴言', 20, 8, 30, '那时，我在他那里为工师，日日为他所喜爱，常常在他面前踊跃，'),
('CUV', '箴言', 20, 8, 31, '踊跃在他为人预备可住之地，也喜悦住在世人之间。'),
('CUV', '箴言', 20, 8, 32, '众子啊，现在要听从我，因为谨守我道的，便为有福。'),
('CUV', '箴言', 20, 8, 33, '要听教训就得智慧，不可弃绝。'),
('CUV', '箴言', 20, 8, 34, '听从我、日日在我门口仰望、在我门框旁边等候的，那人便为有福。'),
('CUV', '箴言', 20, 8, 35, '因为寻得我的，就寻得生命，也必蒙耶和华的恩惠。'),
('CUV', '箴言', 20, 8, 36, '得罪我的，却害了自己的性命；恨恶我的，都喜爱死亡。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 9, 1, '智慧建造房屋，凿成七根柱子，'),
('CUV', '箴言', 20, 9, 2, '宰杀牲畜，调和旨酒，设摆筵席；'),
('CUV', '箴言', 20, 9, 3, '打发使女出去，自己在城中至高处呼叫，'),
('CUV', '箴言', 20, 9, 4, '说：谁是愚蒙人，可以转到这里来！又对那无知的人说：'),
('CUV', '箴言', 20, 9, 5, '你们来，吃我的饼，喝我调和的酒。'),
('CUV', '箴言', 20, 9, 6, '你们愚蒙人，要舍弃愚蒙，就得存活，并要走光明的道。'),
('CUV', '箴言', 20, 9, 7, '指斥亵慢人的，必受辱骂；责备恶人的，必被玷污。'),
('CUV', '箴言', 20, 9, 8, '不要责备亵慢人，恐怕他恨你；要责备智慧人，他必爱你。'),
('CUV', '箴言', 20, 9, 9, '教导智慧人，他就越发有智慧；指示义人，他就增长学问。'),
('CUV', '箴言', 20, 9, 10, '敬畏耶和华是智慧的开端；认识至圣者便是聪明。'),
('CUV', '箴言', 20, 9, 11, '你藉著我，日子必增多，年岁也必加添。'),
('CUV', '箴言', 20, 9, 12, '你若有智慧，是与自己有益；你若亵慢，就必独自担当。'),
('CUV', '箴言', 20, 9, 13, '愚昧的妇人喧嚷；他是愚蒙，一无所知。'),
('CUV', '箴言', 20, 9, 14, '他坐在自己的家门口，坐在城中高处的座位上，'),
('CUV', '箴言', 20, 9, 15, '呼叫过路的，就是直行其道的人，'),
('CUV', '箴言', 20, 9, 16, '说：谁是愚蒙人，可以转到这里来！又对那无知的人说：'),
('CUV', '箴言', 20, 9, 17, '偷来的水是甜的，暗吃的饼是好的。'),
('CUV', '箴言', 20, 9, 18, '人却不知有阴魂在他那里；他的客在阴间的深处。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 10, 1, '所罗门的箴言：智慧之子使父亲欢乐；愚昧之子叫母亲担忧。'),
('CUV', '箴言', 20, 10, 2, '不义之财毫无益处；惟有公义能救人脱离死亡。'),
('CUV', '箴言', 20, 10, 3, '耶和华不使义人受饥饿；恶人所欲的，他必推开。'),
('CUV', '箴言', 20, 10, 4, '手懒的，要受贫穷；手勤的，却要富足。'),
('CUV', '箴言', 20, 10, 5, '夏天聚敛的，是智慧之子；收割时沉睡的，是贻羞之子。'),
('CUV', '箴言', 20, 10, 6, '福祉临到义人的头；强暴蒙蔽恶人的口。'),
('CUV', '箴言', 20, 10, 7, '义人的纪念被称赞；恶人的名字必朽烂。'),
('CUV', '箴言', 20, 10, 8, '心中智慧的，必受命令；口里愚妄的，必致倾倒。'),
('CUV', '箴言', 20, 10, 9, '行正直路的，步步安稳；走弯曲道的，必致败露。'),
('CUV', '箴言', 20, 10, 10, '以眼传神的，使人忧患；口里愚妄的，必致倾倒。'),
('CUV', '箴言', 20, 10, 11, '义人的口是生命的泉源；强暴蒙蔽恶人的口。'),
('CUV', '箴言', 20, 10, 12, '恨能挑启争端；爱能遮掩一切过错。'),
('CUV', '箴言', 20, 10, 13, '明哲人嘴里有智慧；无知人背上受刑杖。'),
('CUV', '箴言', 20, 10, 14, '智慧人积存知识；愚妄人的口速致败坏。'),
('CUV', '箴言', 20, 10, 15, '富户的财物是他的坚城；穷人的贫乏是他的败坏。'),
('CUV', '箴言', 20, 10, 16, '义人的勤劳致生；恶人的进项致死（死：原文是罪）。'),
('CUV', '箴言', 20, 10, 17, '谨守训诲的，乃在生命的道上；违弃责备的，便失迷了路。'),
('CUV', '箴言', 20, 10, 18, '隐藏怨恨的，有说谎的嘴；口出谗谤的，是愚妄的人。'),
('CUV', '箴言', 20, 10, 19, '多言多语难免有过；禁止嘴唇是有智慧。'),
('CUV', '箴言', 20, 10, 20, '义人的舌乃似高银；恶人的心所值无几。'),
('CUV', '箴言', 20, 10, 21, '义人的口教养多人；愚昧人因无知而死亡。'),
('CUV', '箴言', 20, 10, 22, '耶和华所赐的福使人富足，并不加上忧虑。'),
('CUV', '箴言', 20, 10, 23, '愚妄人以行恶为戏耍；明哲人却以智慧为乐。'),
('CUV', '箴言', 20, 10, 24, '恶人所怕的，必临到他；义人所愿的，必蒙应允。'),
('CUV', '箴言', 20, 10, 25, '暴风一过，恶人归于无有；义人的根基却是永久。'),
('CUV', '箴言', 20, 10, 26, '懒惰人叫差他的人如醋倒牙，如烟薰目。'),
('CUV', '箴言', 20, 10, 27, '敬畏耶和华使人日子加多；但恶人的年岁必被减少。'),
('CUV', '箴言', 20, 10, 28, '义人的盼望必得喜乐；恶人的指望必致灭没。'),
('CUV', '箴言', 20, 10, 29, '耶和华的道是正直人的保障，却成了作孽人的败坏。'),
('CUV', '箴言', 20, 10, 30, '义人永不挪移；恶人不得住在地上。'),
('CUV', '箴言', 20, 10, 31, '义人的口滋生智慧；乖谬的舌必被割断。'),
('CUV', '箴言', 20, 10, 32, '义人的嘴能令人喜悦；恶人的口说乖谬的话。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 11, 1, '诡诈的天平为耶和华所憎恶；公平的法码为他所喜悦。'),
('CUV', '箴言', 20, 11, 2, '骄傲来，羞耻也来；谦逊人却有智慧。'),
('CUV', '箴言', 20, 11, 3, '正直人的纯正必引导自己；奸诈人的乖僻必毁灭自己。'),
('CUV', '箴言', 20, 11, 4, '发怒的日子资财无益；惟有公义能救人脱离死亡。'),
('CUV', '箴言', 20, 11, 5, '完全人的义必指引他的路；但恶人必因自己的恶跌倒。'),
('CUV', '箴言', 20, 11, 6, '正直人的义必拯救自己；奸诈人必陷在自己的罪孽中。'),
('CUV', '箴言', 20, 11, 7, '恶人一死，他的指望必灭绝；罪人的盼望也必灭没。'),
('CUV', '箴言', 20, 11, 8, '义人得脱离患难，有恶人来代替他。'),
('CUV', '箴言', 20, 11, 9, '不虔敬的人用口败坏邻舍；义人却因知识得救。'),
('CUV', '箴言', 20, 11, 10, '义人享福，合城喜乐；恶人灭亡，人都欢呼。'),
('CUV', '箴言', 20, 11, 11, '城因正直人祝福便高举，却因邪恶人的口就倾覆。'),
('CUV', '箴言', 20, 11, 12, '藐视邻舍的，毫无智慧；明哲人却静默不言。'),
('CUV', '箴言', 20, 11, 13, '往来传舌的，泄漏密事；心中诚实的，遮隐事情。'),
('CUV', '箴言', 20, 11, 14, '无智谋，民就败落；谋士多，人便安居。'),
('CUV', '箴言', 20, 11, 15, '为外人作保的，必受亏损；恨恶击掌的，却得安稳。'),
('CUV', '箴言', 20, 11, 16, '恩德的妇女得尊荣；强暴的男子得资财。'),
('CUV', '箴言', 20, 11, 17, '仁慈的人善待自己；残忍的人扰害己身。'),
('CUV', '箴言', 20, 11, 18, '恶人经营，得虚浮的工价；撒义种的，得实在的果效。'),
('CUV', '箴言', 20, 11, 19, '恒心为义的，必得生命；追求邪恶的，必致死亡。'),
('CUV', '箴言', 20, 11, 20, '心中乖僻的，为耶和华所憎恶；行事完全的，为他所喜悦。'),
('CUV', '箴言', 20, 11, 21, '恶人虽然连手，必不免受罚；义人的后裔必得拯救。'),
('CUV', '箴言', 20, 11, 22, '妇女美貌而无见识，如同金环带在猪鼻上。'),
('CUV', '箴言', 20, 11, 23, '义人的心愿尽得好处；恶人的指望致干忿怒。'),
('CUV', '箴言', 20, 11, 24, '有施散的，却更增添；有吝惜过度的，反致穷乏。'),
('CUV', '箴言', 20, 11, 25, '好施舍的，必得丰裕；滋润人的，必得滋润。'),
('CUV', '箴言', 20, 11, 26, '屯粮不卖的，民必咒诅他；情愿出卖的，人必为他祝福。'),
('CUV', '箴言', 20, 11, 27, '恳切求善的，就求得恩惠；惟独求恶的，恶必临到他身。'),
('CUV', '箴言', 20, 11, 28, '倚仗自己财物的，必跌倒；义人必发旺，如青叶。'),
('CUV', '箴言', 20, 11, 29, '扰害己家的，必承受清风；愚昧人必作慧心人的仆人。'),
('CUV', '箴言', 20, 11, 30, '义人所结的果子就是生命树；有智慧的，必能得人。'),
('CUV', '箴言', 20, 11, 31, '看哪，义人在世尚且受报，何况恶人和罪人呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 12, 1, '喜爱管教的，就是喜爱知识；恨恶责备的，却是畜类。'),
('CUV', '箴言', 20, 12, 2, '善人必蒙耶和华的恩惠；设诡计的人，耶和华必定他的罪。'),
('CUV', '箴言', 20, 12, 3, '人靠恶行不能坚立；义人的根必不动摇。'),
('CUV', '箴言', 20, 12, 4, '才德的妇人是丈夫的冠冕；贻羞的妇人如同朽烂在他丈夫的骨中。'),
('CUV', '箴言', 20, 12, 5, '义人的思念是公平；恶人的计谋是诡诈。'),
('CUV', '箴言', 20, 12, 6, '恶人的言论是埋伏流人的血；正直人的口必拯救人。'),
('CUV', '箴言', 20, 12, 7, '恶人倾覆，归于无有；义人的家必站得住。'),
('CUV', '箴言', 20, 12, 8, '人必按自己的智慧被称赞；心中乖谬的，必被藐视。'),
('CUV', '箴言', 20, 12, 9, '被人轻贱，却有仆人，强如自尊，缺少食物。'),
('CUV', '箴言', 20, 12, 10, '义人顾惜他牲畜的命；恶人的怜悯也是残忍。'),
('CUV', '箴言', 20, 12, 11, '耕种自己田地的，必得饱食；追随虚浮的，却是无知。'),
('CUV', '箴言', 20, 12, 12, '恶人想得坏人的网罗；义人的根得以结实。'),
('CUV', '箴言', 20, 12, 13, '恶人嘴中的过错是自己的网罗；但义人必脱离患难。'),
('CUV', '箴言', 20, 12, 14, '人因口所结的果子，必饱得美福；人手所做的，必为自己的报应。'),
('CUV', '箴言', 20, 12, 15, '愚妄人所行的，在自己眼中看为正直；惟智慧人肯听人的劝教。'),
('CUV', '箴言', 20, 12, 16, '愚妄人的恼怒立时显露；通达人能忍辱藏羞。'),
('CUV', '箴言', 20, 12, 17, '说出真话的，显明公义；作假见证的，显出诡诈。'),
('CUV', '箴言', 20, 12, 18, '说话浮躁的，如刀刺人；智慧人的舌头却为医人的良药。'),
('CUV', '箴言', 20, 12, 19, '口吐真言，永远坚立；舌说谎话，只存片时。'),
('CUV', '箴言', 20, 12, 20, '图谋恶事的，心存诡诈；劝人和睦的，便得喜乐。'),
('CUV', '箴言', 20, 12, 21, '义人不遭灾害；恶人满受祸患。'),
('CUV', '箴言', 20, 12, 22, '说谎言的嘴为耶和华所憎恶；行事诚实的，为他所喜悦。'),
('CUV', '箴言', 20, 12, 23, '通达人隐藏知识；愚昧人的心彰显愚昧。'),
('CUV', '箴言', 20, 12, 24, '殷勤人的手必掌权；懒惰的人必服苦。'),
('CUV', '箴言', 20, 12, 25, '人心忧虑，屈而不伸；一句良言，使心欢乐。'),
('CUV', '箴言', 20, 12, 26, '义人引导他的邻舍；恶人的道叫人失迷。'),
('CUV', '箴言', 20, 12, 27, '懒惰的人不烤打猎所得的；殷勤的人却得宝贵的财物。'),
('CUV', '箴言', 20, 12, 28, '在公义的道上有生命；其路之中并无死亡。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 13, 1, '智慧子听父亲的教训；亵慢人不听责备。'),
('CUV', '箴言', 20, 13, 2, '人因口所结的果子，必享美福；奸诈人必遭强暴。'),
('CUV', '箴言', 20, 13, 3, '谨守口的，得保生命；大张嘴的，必致败亡。'),
('CUV', '箴言', 20, 13, 4, '懒惰人羡慕，却无所得；殷勤人必得丰裕。'),
('CUV', '箴言', 20, 13, 5, '义人恨恶谎言；恶人有臭名，且致惭愧。'),
('CUV', '箴言', 20, 13, 6, '行为正直的，有公义保守；犯罪的，被邪恶倾覆。'),
('CUV', '箴言', 20, 13, 7, '假作富足的，却一无所有；装作穷乏的，却广有财物。'),
('CUV', '箴言', 20, 13, 8, '人的资财是他生命的赎价；穷乏人却听不见威吓的话。'),
('CUV', '箴言', 20, 13, 9, '义人的光明亮（原文是欢喜）；恶人的灯要熄灭.。'),
('CUV', '箴言', 20, 13, 10, '骄傲只启争竞；听劝言的，却有智慧。'),
('CUV', '箴言', 20, 13, 11, '不劳而得之财必然消耗；勤劳积蓄的，必见加增。'),
('CUV', '箴言', 20, 13, 12, '所盼望的迟延未得，令人心忧；所愿意的临到，却是生命树。'),
('CUV', '箴言', 20, 13, 13, '藐视训言的，自取灭亡；敬畏诫命的，必得善报。'),
('CUV', '箴言', 20, 13, 14, '智慧人的法则（或译：指教）是生命的泉源，可以使人离开死亡的网罗。'),
('CUV', '箴言', 20, 13, 15, '美好的聪明使人蒙恩；奸诈人的道路崎岖难行。'),
('CUV', '箴言', 20, 13, 16, '凡通达人都凭知识行事；愚昧人张扬自己的愚昧。'),
('CUV', '箴言', 20, 13, 17, '奸恶的使者必陷在祸患里；忠信的使臣乃医人的良药。'),
('CUV', '箴言', 20, 13, 18, '弃绝管教的，必致贫受辱；领受责备的，必得尊荣。'),
('CUV', '箴言', 20, 13, 19, '所欲的成就，心觉甘甜；远离恶事，为愚昧人所憎恶。'),
('CUV', '箴言', 20, 13, 20, '与智慧人同行的，必得智慧；和愚昧人作伴的，必受亏损。'),
('CUV', '箴言', 20, 13, 21, '祸患追赶罪人；义人必得善报。'),
('CUV', '箴言', 20, 13, 22, '善人给子孙遗留产业；罪人为义人积存资财。'),
('CUV', '箴言', 20, 13, 23, '穷人耕种多得粮食，但因不义，有消灭的。'),
('CUV', '箴言', 20, 13, 24, '不忍用杖打儿子的，是恨恶他；疼爱儿子的，随时管教。'),
('CUV', '箴言', 20, 13, 25, '义人吃得饱足；恶人肚腹缺粮。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 14, 1, '智慧妇人建立家室；愚妄妇人亲手拆毁。'),
('CUV', '箴言', 20, 14, 2, '行动正直的，敬畏耶和华；行事乖僻的，却藐视他。'),
('CUV', '箴言', 20, 14, 3, '愚妄人口中骄傲，如杖责打己身；智慧人的嘴必保守自己。'),
('CUV', '箴言', 20, 14, 4, '家里无牛，槽头干净；土产加多乃凭牛力。'),
('CUV', '箴言', 20, 14, 5, '诚实见证人不说谎话；假见证人吐出谎言。'),
('CUV', '箴言', 20, 14, 6, '亵慢人寻智慧，却寻不著；聪明人易得知识。'),
('CUV', '箴言', 20, 14, 7, '到愚昧人面前，不见他嘴中有知识。'),
('CUV', '箴言', 20, 14, 8, '通达人的智慧在乎明白己道；愚昧人的愚妄乃是诡诈（或译：自叹）。'),
('CUV', '箴言', 20, 14, 9, '愚妄人犯罪，以为戏耍（或译：赎愆祭愚弄愚妄人）；正直人互相喜悦。'),
('CUV', '箴言', 20, 14, 10, '心中的苦楚，自己知道；心里的喜乐，外人无干。'),
('CUV', '箴言', 20, 14, 11, '奸恶人的房屋必倾倒；正直人的帐棚必兴盛。'),
('CUV', '箴言', 20, 14, 12, '有一条路，人以为正，至终成为死亡之路。'),
('CUV', '箴言', 20, 14, 13, '人在喜笑中，心也忧愁；快乐至极就生愁苦。'),
('CUV', '箴言', 20, 14, 14, '心中背道的，必满得自己的结果；善人必从自己的行为得以知足。'),
('CUV', '箴言', 20, 14, 15, '愚蒙人是话都信；通达人步步谨慎。'),
('CUV', '箴言', 20, 14, 16, '智慧人惧怕，就远离恶事；愚妄人却狂傲自恃。'),
('CUV', '箴言', 20, 14, 17, '轻易发怒的，行事愚妄；设立诡计的，被人恨恶。'),
('CUV', '箴言', 20, 14, 18, '愚蒙人得愚昧为产业；通达人得知识为冠冕。'),
('CUV', '箴言', 20, 14, 19, '坏人俯伏在善人面前；恶人俯伏在义人门口。'),
('CUV', '箴言', 20, 14, 20, '贫穷人连邻舍也恨他；富足人朋友最多。'),
('CUV', '箴言', 20, 14, 21, '藐视邻舍的，这人有罪；怜悯贫穷的，这人有福。'),
('CUV', '箴言', 20, 14, 22, '谋恶的，岂非走入迷途么？谋善的，必得慈爱和诚实。'),
('CUV', '箴言', 20, 14, 23, '诸般勤劳都有益处；嘴上多言乃致穷乏。'),
('CUV', '箴言', 20, 14, 24, '智慧人的财为自己的冠冕；愚妄人的愚昧终是愚昧。'),
('CUV', '箴言', 20, 14, 25, '作真见证的，救人性命；吐出谎言的，施行诡诈。'),
('CUV', '箴言', 20, 14, 26, '敬畏耶和华的，大有倚靠；他的儿女也有避难所。'),
('CUV', '箴言', 20, 14, 27, '敬畏耶和华就是生命的泉源，可以使人离开死亡的网罗。'),
('CUV', '箴言', 20, 14, 28, '帝王荣耀在乎民多；君王衰败在乎民少。'),
('CUV', '箴言', 20, 14, 29, '不轻易发怒的，大有聪明；性情暴躁的，大显愚妄。'),
('CUV', '箴言', 20, 14, 30, '心中安静是肉体的生命；嫉妒是骨中的朽烂。'),
('CUV', '箴言', 20, 14, 31, '欺压贫寒的，是辱没造他的主；怜悯穷乏的，乃是尊敬主。'),
('CUV', '箴言', 20, 14, 32, '恶人在所行的恶上必被推倒；义人临死，有所投靠。'),
('CUV', '箴言', 20, 14, 33, '智慧存在聪明人心中；愚昧人心里所存的，显而易见。'),
('CUV', '箴言', 20, 14, 34, '公义使邦国高举；罪恶是人民的羞辱。'),
('CUV', '箴言', 20, 14, 35, '智慧的臣子蒙王恩惠；贻羞的仆人遭其震怒。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 15, 1, '回答柔和，使怒消退；言语暴戾，触动怒气。'),
('CUV', '箴言', 20, 15, 2, '智慧人的舌善发知识；愚昧人的口吐出愚昧。'),
('CUV', '箴言', 20, 15, 3, '耶和华的眼目无处不在；恶人善人，他都鉴察。'),
('CUV', '箴言', 20, 15, 4, '温良的舌是生命树；乖谬的嘴使人心碎。'),
('CUV', '箴言', 20, 15, 5, '愚妄人藐视父亲的管教；领受责备的，得著见识。'),
('CUV', '箴言', 20, 15, 6, '义人家中多有财宝；恶人得利反受扰害。'),
('CUV', '箴言', 20, 15, 7, '智慧人的嘴播扬知识；愚昧人的心并不如此。'),
('CUV', '箴言', 20, 15, 8, '恶人献祭，为耶和华所憎恶；正直人祈祷，为他所喜悦。'),
('CUV', '箴言', 20, 15, 9, '恶人的道路，为耶和华所憎恶；追求公义的，为他所喜爱。'),
('CUV', '箴言', 20, 15, 10, '舍弃正路的，必受严刑；恨恶责备的，必致死亡。'),
('CUV', '箴言', 20, 15, 11, '阴间和灭亡尚在耶和华眼前，何况世人的心呢？'),
('CUV', '箴言', 20, 15, 12, '亵慢人不爱受责备；他也不就近智慧人。'),
('CUV', '箴言', 20, 15, 13, '心中喜乐，面带笑容；心里忧愁，灵被损伤。'),
('CUV', '箴言', 20, 15, 14, '聪明人心求知识；愚昧人口吃愚昧。'),
('CUV', '箴言', 20, 15, 15, '困苦人的日子都是愁苦；心中欢畅的，常享丰筵。'),
('CUV', '箴言', 20, 15, 16, '少有财宝，敬畏耶和华，强如多有财宝，烦乱不安。'),
('CUV', '箴言', 20, 15, 17, '吃素菜，彼此相爱，强如吃肥牛，彼此相恨。'),
('CUV', '箴言', 20, 15, 18, '暴怒的人挑启争端；忍怒的人止息纷争。'),
('CUV', '箴言', 20, 15, 19, '懒惰人的道像荆棘的篱笆；正直人的路是平坦的大道。'),
('CUV', '箴言', 20, 15, 20, '智慧子使父亲喜乐；愚昧人藐视母亲。'),
('CUV', '箴言', 20, 15, 21, '无知的人以愚妄为乐；聪明的人按正直而行。'),
('CUV', '箴言', 20, 15, 22, '不先商议，所谋无效；谋士众多，所谋乃成。'),
('CUV', '箴言', 20, 15, 23, '口善应对，自觉喜乐；话合其时，何等美好。'),
('CUV', '箴言', 20, 15, 24, '智慧人从生命的道上升，使他远离在下的阴间。'),
('CUV', '箴言', 20, 15, 25, '耶和华必拆毁骄傲人的家，却要立定寡妇的地界。'),
('CUV', '箴言', 20, 15, 26, '恶谋为耶和华所憎恶；良言乃为纯净。'),
('CUV', '箴言', 20, 15, 27, '贪恋财利的，扰害己家；恨恶贿赂的，必得存活。'),
('CUV', '箴言', 20, 15, 28, '义人的心，思量如何回答；恶人的口吐出恶言。'),
('CUV', '箴言', 20, 15, 29, '耶和华远离恶人，却听义人的祷告。'),
('CUV', '箴言', 20, 15, 30, '眼有光，使心喜乐；好信息，使骨滋润。'),
('CUV', '箴言', 20, 15, 31, '听从生命责备的，必常在智慧人中。'),
('CUV', '箴言', 20, 15, 32, '弃绝管教的，轻看自己的生命；听从责备的，却得智慧。'),
('CUV', '箴言', 20, 15, 33, '敬畏耶和华是智慧的训诲；尊荣以前，必有谦卑。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 16, 1, '心中的谋算在乎人；舌头的应对由于耶和华。'),
('CUV', '箴言', 20, 16, 2, '人一切所行的，在自己眼中看为清洁；惟有耶和华衡量人心。'),
('CUV', '箴言', 20, 16, 3, '你所做的，要交托耶和华，你所谋的，就必成立。'),
('CUV', '箴言', 20, 16, 4, '耶和华所造的，各适其用；就是恶人也为祸患的日子所造。'),
('CUV', '箴言', 20, 16, 5, '凡心里骄傲的，为耶和华所憎恶；虽然连手，他必不免受罚。'),
('CUV', '箴言', 20, 16, 6, '因怜悯诚实，罪孽得赎；敬畏耶和华的，远离恶事。'),
('CUV', '箴言', 20, 16, 7, '人所行的，若蒙耶和华喜悦，耶和华也使他的仇敌与他和好。'),
('CUV', '箴言', 20, 16, 8, '多有财利，行事不义，不如少有财利，行事公义。'),
('CUV', '箴言', 20, 16, 9, '人心筹算自己的道路；惟耶和华指引他的脚步。'),
('CUV', '箴言', 20, 16, 10, '王的嘴中有神语，审判之时，他的口必不差错。'),
('CUV', '箴言', 20, 16, 11, '公道的天平和秤都属耶和华；囊中一切法码都为他所定。'),
('CUV', '箴言', 20, 16, 12, '作恶，为王所憎恶，因国位是靠公义坚立。'),
('CUV', '箴言', 20, 16, 13, '公义的嘴为王所喜悦；说正直话的，为王所喜爱。'),
('CUV', '箴言', 20, 16, 14, '王的震怒如杀人的使者；但智慧人能止息王怒。'),
('CUV', '箴言', 20, 16, 15, '王的脸光使人有生命；王的恩典好像春云时雨。'),
('CUV', '箴言', 20, 16, 16, '得智慧胜似得金子；选聪明强如选银子。'),
('CUV', '箴言', 20, 16, 17, '正直人的道是远离恶事；谨守己路的，是保全性命。'),
('CUV', '箴言', 20, 16, 18, '骄傲在败坏以先；狂心在跌倒之前。'),
('CUV', '箴言', 20, 16, 19, '心里谦卑与穷乏人来往，强如将掳物与骄傲人同分。'),
('CUV', '箴言', 20, 16, 20, '谨守训言的，必得好处；倚靠耶和华的，便为有福。'),
('CUV', '箴言', 20, 16, 21, '心中有智慧，必称为通达人；嘴中的甜言，加增人的学问。'),
('CUV', '箴言', 20, 16, 22, '人有智慧就有生命的泉源；愚昧人必被愚昧惩治。'),
('CUV', '箴言', 20, 16, 23, '智慧人的心教训他的口，又使他的嘴增长学问。'),
('CUV', '箴言', 20, 16, 24, '良言如同蜂房，使心觉甘甜，使骨得医治。'),
('CUV', '箴言', 20, 16, 25, '有一条路，人以为正，至终成为死亡之路。'),
('CUV', '箴言', 20, 16, 26, '劳力人的胃口使他劳力，因为他的口腹催逼他。'),
('CUV', '箴言', 20, 16, 27, '匪徒图谋奸恶，嘴上仿佛有烧焦的火。'),
('CUV', '箴言', 20, 16, 28, '乖僻人播散纷争；传舌的，离间密友。'),
('CUV', '箴言', 20, 16, 29, '强暴人诱惑邻舍，领他走不善之道。'),
('CUV', '箴言', 20, 16, 30, '眼目紧合的，图谋乖僻；嘴唇紧闭的，成就邪恶。'),
('CUV', '箴言', 20, 16, 31, '白发是荣耀的冠冕，在公义的道上必能得著。'),
('CUV', '箴言', 20, 16, 32, '不轻易发怒的，胜过勇士；治服己心的，强如取城。'),
('CUV', '箴言', 20, 16, 33, '签放在怀里，定事由耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 17, 1, '设筵满屋，大家相争，不如有块干饼，大家相安。'),
('CUV', '箴言', 20, 17, 2, '仆人办事聪明，必管辖贻羞之子，又在众子中同分产业。'),
('CUV', '箴言', 20, 17, 3, '鼎为炼银，炉为炼金；惟有耶和华熬炼人心。'),
('CUV', '箴言', 20, 17, 4, '行恶的，留心听奸诈之言；说谎的，侧耳听邪恶之语。'),
('CUV', '箴言', 20, 17, 5, '戏笑穷人的，是辱没造他的主；幸灾乐祸的，必不免受罚。'),
('CUV', '箴言', 20, 17, 6, '子孙为老人的冠冕；父亲是儿女的荣耀。'),
('CUV', '箴言', 20, 17, 7, '愚顽人说美言本不相宜，何况君王说谎话呢？'),
('CUV', '箴言', 20, 17, 8, '贿赂在餽送的人眼中看为宝玉，随处运动都得顺利。'),
('CUV', '箴言', 20, 17, 9, '遮掩人过的，寻求人爱；屡次挑错的，离间密友。'),
('CUV', '箴言', 20, 17, 10, '一句责备话深入聪明人的心，强如责打愚昧人一百下。'),
('CUV', '箴言', 20, 17, 11, '恶人只寻背叛，所以必有严厉的使者奉差攻击他。'),
('CUV', '箴言', 20, 17, 12, '宁可遇见丢崽子的母熊，不可遇见正行愚妄的愚昧人。'),
('CUV', '箴言', 20, 17, 13, '以恶报善的，祸患必不离他的家。'),
('CUV', '箴言', 20, 17, 14, '纷争的起头如水放开，所以，在争闹之先必当止息争竞。'),
('CUV', '箴言', 20, 17, 15, '定恶人为义的，定义人为恶的，这都为耶和华所憎恶。'),
('CUV', '箴言', 20, 17, 16, '愚昧人既无聪明，为何手拿价银买智慧呢？'),
('CUV', '箴言', 20, 17, 17, '朋友乃时常亲爱，弟兄为患难而生。'),
('CUV', '箴言', 20, 17, 18, '在邻舍面前击掌作保乃是无知的人。'),
('CUV', '箴言', 20, 17, 19, '喜爱争竞的，是喜爱过犯；高立家门的，乃自取败坏。'),
('CUV', '箴言', 20, 17, 20, '心存邪僻的，寻不著好处；舌弄是非的，陷在祸患中。'),
('CUV', '箴言', 20, 17, 21, '生愚昧子的，必自愁苦；愚顽人的父毫无喜乐。'),
('CUV', '箴言', 20, 17, 22, '喜乐的心乃是良药；忧伤的灵使骨枯干。'),
('CUV', '箴言', 20, 17, 23, '恶人暗中受贿赂，为要颠倒判断。'),
('CUV', '箴言', 20, 17, 24, '明哲人眼前有智慧；愚昧人眼望地极。'),
('CUV', '箴言', 20, 17, 25, '愚昧子使父亲愁烦，使母亲忧苦。'),
('CUV', '箴言', 20, 17, 26, '刑罚义人为不善；责打君子为不义。'),
('CUV', '箴言', 20, 17, 27, '寡少言语的，有知识；性情温良的，有聪明。'),
('CUV', '箴言', 20, 17, 28, '愚昧人若静默不言也可算为智慧；闭口不说也可算为聪明。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 18, 1, '与众寡合的，独自寻求心愿，并恼恨一切真智慧。'),
('CUV', '箴言', 20, 18, 2, '愚昧人不喜爱明哲，只喜爱显露心意。'),
('CUV', '箴言', 20, 18, 3, '恶人来，藐视随来；羞耻到，辱骂同到。'),
('CUV', '箴言', 20, 18, 4, '人口中的言语如同深水；智慧的泉源好像涌流的河水。'),
('CUV', '箴言', 20, 18, 5, '瞻徇恶人的情面，偏断义人的案件，都为不善。'),
('CUV', '箴言', 20, 18, 6, '愚昧人张嘴启争端，开口招鞭打。'),
('CUV', '箴言', 20, 18, 7, '愚昧人的口自取败坏；他的嘴是他生命的网罗。'),
('CUV', '箴言', 20, 18, 8, '传舌人的言语如同美食，深入人的心腹。'),
('CUV', '箴言', 20, 18, 9, '做工懈怠的，与浪费人为弟兄。'),
('CUV', '箴言', 20, 18, 10, '耶和华的名是坚固台；义人奔入便得安稳。'),
('CUV', '箴言', 20, 18, 11, '富足人的财物是他的坚城，在他心想，犹如高墙。'),
('CUV', '箴言', 20, 18, 12, '败坏之先，人心骄傲；尊荣以前，必有谦卑。'),
('CUV', '箴言', 20, 18, 13, '未曾听完先回答的，便是他的愚昧和羞辱。'),
('CUV', '箴言', 20, 18, 14, '人有疾病，心能忍耐；心灵忧伤，谁能承当呢？'),
('CUV', '箴言', 20, 18, 15, '聪明人的心得知识；智慧人的耳求知识。'),
('CUV', '箴言', 20, 18, 16, '人的礼物为他开路，引他到高位的人面前。'),
('CUV', '箴言', 20, 18, 17, '先诉情由的，似乎有理；但邻舍来到，就察出实情。'),
('CUV', '箴言', 20, 18, 18, '掣签能止息争竞，也能解散强胜的人。'),
('CUV', '箴言', 20, 18, 19, '弟兄结怨，劝他和好，比取坚固城还难；这样的争竞如同坚寨的门闩。'),
('CUV', '箴言', 20, 18, 20, '人口中所结的果子，必充满肚腹；他嘴所出的，必使他饱足。'),
('CUV', '箴言', 20, 18, 21, '生死在舌头的权下，喜爱他的，必吃他所结的果子。'),
('CUV', '箴言', 20, 18, 22, '得著贤妻的，是得著好处，也是蒙了耶和华的恩惠。'),
('CUV', '箴言', 20, 18, 23, '贫穷人说哀求的话；富足人用威吓的话回答。'),
('CUV', '箴言', 20, 18, 24, '滥交朋友的，自取败坏；但有一朋友比弟兄更亲密。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 19, 1, '行为纯正的贫穷人胜过乖谬愚妄的富足人。'),
('CUV', '箴言', 20, 19, 2, '心无知识的，乃为不善；脚步急快的，难免犯罪。'),
('CUV', '箴言', 20, 19, 3, '人的愚昧倾败他的道；他的心也抱怨耶和华。'),
('CUV', '箴言', 20, 19, 4, '财物使朋友增多；但穷人朋友远离。'),
('CUV', '箴言', 20, 19, 5, '作假见证的，必不免受罚；吐出谎言的，终不能逃脱。'),
('CUV', '箴言', 20, 19, 6, '好施散的，有多人求他的恩情；爱送礼的，人都为他的朋友。'),
('CUV', '箴言', 20, 19, 7, '贫穷人，弟兄都恨他；何况他的朋友，更远离他！他用言语追随，他们却走了。'),
('CUV', '箴言', 20, 19, 8, '得著智慧的，爱惜生命；保守聪明的，必得好处。'),
('CUV', '箴言', 20, 19, 9, '作假见证的，不免受罚；吐出谎言的，也必灭亡。'),
('CUV', '箴言', 20, 19, 10, '愚昧人宴乐度日是不合宜的；何况仆人管辖王子呢？'),
('CUV', '箴言', 20, 19, 11, '人有见识就不轻易发怒；宽恕人的过失便是自己的荣耀。'),
('CUV', '箴言', 20, 19, 12, '王的忿怒好像狮子吼叫；他的恩典却如草上的甘露。'),
('CUV', '箴言', 20, 19, 13, '愚昧的儿子是父亲的祸患；妻子的争吵如雨连连滴漏。'),
('CUV', '箴言', 20, 19, 14, '房屋钱财是祖宗所遗留的；惟有贤慧的妻是耶和华所赐的。'),
('CUV', '箴言', 20, 19, 15, '懒惰使人沉睡；懈怠的人必受饥饿。'),
('CUV', '箴言', 20, 19, 16, '谨守诫命的，保全生命；轻忽己路的，必致死亡。'),
('CUV', '箴言', 20, 19, 17, '怜悯贫穷的，就是借给耶和华；他的善行，耶和华必偿还。'),
('CUV', '箴言', 20, 19, 18, '趁有指望，管教你的儿子；你的心不可任他死亡。'),
('CUV', '箴言', 20, 19, 19, '暴怒的人必受刑罚；你若救他，必须再救。'),
('CUV', '箴言', 20, 19, 20, '你要听劝教，受训诲，使你终久有智慧。'),
('CUV', '箴言', 20, 19, 21, '人心多有计谋；惟有耶和华的筹算才能立定。'),
('CUV', '箴言', 20, 19, 22, '施行仁慈的，令人爱慕；穷人强如说谎言的。'),
('CUV', '箴言', 20, 19, 23, '敬畏耶和华的，得著生命；他必恒久知足，不遭祸患。'),
('CUV', '箴言', 20, 19, 24, '懒惰人放手在盘子里，就是向口撤回，他也不肯。'),
('CUV', '箴言', 20, 19, 25, '鞭打亵慢人，愚蒙人必长见识；责备明哲人，他就明白知识。'),
('CUV', '箴言', 20, 19, 26, '虐待父亲、撵出母亲的，是贻羞致辱之子。'),
('CUV', '箴言', 20, 19, 27, '我儿，不可听了教训而又偏离知识的言语。'),
('CUV', '箴言', 20, 19, 28, '匪徒作见证戏笑公平；恶人的口吞下罪孽。'),
('CUV', '箴言', 20, 19, 29, '刑罚是为亵慢人预备的；鞭打是为愚昧人的背预备的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 20, 1, '酒能使人亵慢，浓酒使人喧嚷；凡因酒错误的，就无智慧。'),
('CUV', '箴言', 20, 20, 2, '王的威吓如同狮子吼叫；惹动他怒的，是自害己命。'),
('CUV', '箴言', 20, 20, 3, '远离纷争是人的尊荣；愚妄人都爱争闹。'),
('CUV', '箴言', 20, 20, 4, '懒惰人因冬寒不肯耕种，到收割的时候，他必讨饭而无所得。'),
('CUV', '箴言', 20, 20, 5, '人心怀藏谋略，好像深水，惟明哲人才能汲引出来。'),
('CUV', '箴言', 20, 20, 6, '人多述说自己的仁慈，但忠信人谁能遇著呢？'),
('CUV', '箴言', 20, 20, 7, '行为纯正的义人，他的子孙是有福的！'),
('CUV', '箴言', 20, 20, 8, '王坐在审判的位上，以眼目驱散诸恶。'),
('CUV', '箴言', 20, 20, 9, '谁能说，我洁净了我的心，我脱净了我的罪？'),
('CUV', '箴言', 20, 20, 10, '两样的法码，两样的升斗，都为耶和华所憎恶。'),
('CUV', '箴言', 20, 20, 11, '孩童的动作是清洁，是正直，都显明他的本性。'),
('CUV', '箴言', 20, 20, 12, '能听的耳，能看的眼，都是耶和华所造的。'),
('CUV', '箴言', 20, 20, 13, '不要贪睡，免致贫穷；眼要睁开，你就吃饱。'),
('CUV', '箴言', 20, 20, 14, '买物的说：不好，不好；及至买去，他便自夸。'),
('CUV', '箴言', 20, 20, 15, '有金子和许多珍珠（或译：红宝石），惟有知识的嘴乃为贵重的珍宝。'),
('CUV', '箴言', 20, 20, 16, '谁为生人作保，就拿谁的衣服；谁为外人作保，谁就要承当。'),
('CUV', '箴言', 20, 20, 17, '以虚谎而得的食物，人觉甘甜；但后来，他的口必充满尘沙。'),
('CUV', '箴言', 20, 20, 18, '计谋都凭筹算立定；打仗要凭智谋。'),
('CUV', '箴言', 20, 20, 19, '往来传舌的，泄漏密事；大张嘴的，不可与他结交。'),
('CUV', '箴言', 20, 20, 20, '咒骂父母的，他的灯必灭，变为漆黑的黑暗。'),
('CUV', '箴言', 20, 20, 21, '起初速得的产业，终久却不为福。'),
('CUV', '箴言', 20, 20, 22, '你不要说，我要以恶报恶；要等候耶和华，他必拯救你。'),
('CUV', '箴言', 20, 20, 23, '两样的法码为耶和华所憎恶；诡诈的天平也为不善。'),
('CUV', '箴言', 20, 20, 24, '人的脚步为耶和华所定；人岂能明白自己的路呢？'),
('CUV', '箴言', 20, 20, 25, '人冒失说，这是圣物，许愿之后才查问，就是自陷网罗。'),
('CUV', '箴言', 20, 20, 26, '智慧的王簸散恶人，用碌碡滚轧他们。'),
('CUV', '箴言', 20, 20, 27, '人的灵是耶和华的灯，鉴察人的心腹。'),
('CUV', '箴言', 20, 20, 28, '王因仁慈和诚实得以保全他的国位，也因仁慈立稳。'),
('CUV', '箴言', 20, 20, 29, '强壮乃少年人的荣耀；白发为老年人的尊荣。'),
('CUV', '箴言', 20, 20, 30, '鞭伤除净人的罪恶；责打能入人的心腹。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 21, 1, '王的心在耶和华手中，好像陇沟的水随意流转。'),
('CUV', '箴言', 20, 21, 2, '人所行的，在自己眼中都看为正；惟有耶和华衡量人心。'),
('CUV', '箴言', 20, 21, 3, '行仁义公平比献祭更蒙耶和华悦纳。'),
('CUV', '箴言', 20, 21, 4, '恶人发达（发达：原文是灯），眼高心傲，这乃是罪。'),
('CUV', '箴言', 20, 21, 5, '殷勤筹划的，足致丰裕；行事急躁的，都必缺乏。'),
('CUV', '箴言', 20, 21, 6, '用诡诈之舌求财的，就是自己取死；所得之财乃是吹来吹去的浮云。'),
('CUV', '箴言', 20, 21, 7, '恶人的强暴必将自己扫除，因他们不肯按公平行事。'),
('CUV', '箴言', 20, 21, 8, '负罪之人的路甚是弯曲；至于清洁的人，他所行的乃是正直。'),
('CUV', '箴言', 20, 21, 9, '宁可住在房顶的角上，不在宽阔的房屋与争吵的妇人同住。'),
('CUV', '箴言', 20, 21, 10, '恶人的心乐人受祸；他眼并不怜恤邻舍。'),
('CUV', '箴言', 20, 21, 11, '亵慢的人受刑罚，愚蒙的人就得智慧；智慧人受训诲，便得知识。'),
('CUV', '箴言', 20, 21, 12, '义人思想恶人的家，知道恶人倾倒，必致灭亡。'),
('CUV', '箴言', 20, 21, 13, '塞耳不听穷人哀求的，他将来呼吁也不蒙应允。'),
('CUV', '箴言', 20, 21, 14, '暗中送的礼物挽回怒气；怀中搋的贿赂止息暴怒。'),
('CUV', '箴言', 20, 21, 15, '秉公行义使义人喜乐，使作孽的人败坏。'),
('CUV', '箴言', 20, 21, 16, '迷离通达道路的，必住在阴魂的会中。'),
('CUV', '箴言', 20, 21, 17, '爱宴乐的，必致穷乏；好酒，爱膏油的，必不富足。'),
('CUV', '箴言', 20, 21, 18, '恶人作了义人的赎价；奸诈人代替正直人。'),
('CUV', '箴言', 20, 21, 19, '宁可住在旷野，不与争吵使气的妇人同住。'),
('CUV', '箴言', 20, 21, 20, '智慧人家中积蓄宝物膏油；愚昧人随得来随吞下。'),
('CUV', '箴言', 20, 21, 21, '追求公义仁慈的，就寻得生命、公义，和尊荣。'),
('CUV', '箴言', 20, 21, 22, '智慧人爬上勇士的城墙，倾覆他所倚靠的坚垒。'),
('CUV', '箴言', 20, 21, 23, '谨守口与舌的，就保守自己免受灾难。'),
('CUV', '箴言', 20, 21, 24, '心骄气傲的人名叫亵慢；他行事狂妄，都出于骄傲。'),
('CUV', '箴言', 20, 21, 25, '懒惰人的心愿将他杀害，因为他手不肯做工。'),
('CUV', '箴言', 20, 21, 26, '有终日贪得无餍的；义人施舍而不吝惜。'),
('CUV', '箴言', 20, 21, 27, '恶人的祭物是可憎的；何况他存恶意来献呢？'),
('CUV', '箴言', 20, 21, 28, '作假见证的必灭亡；惟有听真情而言的，其言长存。'),
('CUV', '箴言', 20, 21, 29, '恶人脸无羞耻；正直人行事坚定。'),
('CUV', '箴言', 20, 21, 30, '没有人能以智慧、聪明、谋略敌挡耶和华。'),
('CUV', '箴言', 20, 21, 31, '马是为打仗之日预备的；得胜乃在乎耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 22, 1, '美名胜过大财；恩宠强如金银。'),
('CUV', '箴言', 20, 22, 2, '富户穷人在世相遇，都为耶和华所造。'),
('CUV', '箴言', 20, 22, 3, '通达人见祸藏躲；愚蒙人前往受害。'),
('CUV', '箴言', 20, 22, 4, '敬畏耶和华心存谦卑，就得富有、尊荣、生命为赏赐。'),
('CUV', '箴言', 20, 22, 5, '乖僻人的路上有荆棘和网罗；保守自己生命的，必要远离。'),
('CUV', '箴言', 20, 22, 6, '教养孩童，使他走当行的道，就是到老他也不偏离。'),
('CUV', '箴言', 20, 22, 7, '富户管辖穷人；欠债的是债主的仆人。'),
('CUV', '箴言', 20, 22, 8, '撒罪孽的，必收灾祸；他逞怒的杖也必废掉。'),
('CUV', '箴言', 20, 22, 9, '眼目慈善的，就必蒙福，因他将食物分给穷人。'),
('CUV', '箴言', 20, 22, 10, '赶出亵慢人，争端就消除；纷争和羞辱也必止息。'),
('CUV', '箴言', 20, 22, 11, '喜爱清心的人因他嘴上的恩言，王必与他为友。'),
('CUV', '箴言', 20, 22, 12, '耶和华的眼目眷顾聪明人，却倾败奸诈人的言语。'),
('CUV', '箴言', 20, 22, 13, '懒惰人说：外头有狮子；我在街上就必被杀。'),
('CUV', '箴言', 20, 22, 14, '淫妇的口为深坑；耶和华所憎恶的，必陷在其中。'),
('CUV', '箴言', 20, 22, 15, '愚蒙迷住孩童的心，用管教的杖可以远远赶除。'),
('CUV', '箴言', 20, 22, 16, '欺压贫穷为要利己的，并送礼与富户的，都必缺乏。'),
('CUV', '箴言', 20, 22, 17, '你须侧耳听受智慧人的言语，留心领会我的知识。'),
('CUV', '箴言', 20, 22, 18, '你若心中存记，嘴上咬定，这便为美。'),
('CUV', '箴言', 20, 22, 19, '我今日以此特特指教你，为要使你倚靠耶和华。'),
('CUV', '箴言', 20, 22, 20, '谋略和知识的美事，我岂没有写给你么？'),
('CUV', '箴言', 20, 22, 21, '要使你知道真言的实理，你好将真言回复那打发你来的人。'),
('CUV', '箴言', 20, 22, 22, '贫穷人，你不可因他贫穷就抢夺他的物，也不可在城门口欺压困苦人；'),
('CUV', '箴言', 20, 22, 23, '因耶和华必为他辨屈；抢夺他的，耶和华必夺取那人的命。'),
('CUV', '箴言', 20, 22, 24, '好生气的人，不可与他结交；暴怒的人，不可与他来往；'),
('CUV', '箴言', 20, 22, 25, '恐怕你效法他的行为，自己就陷在网罗里。'),
('CUV', '箴言', 20, 22, 26, '不要与人击掌，不要为欠债的作保。'),
('CUV', '箴言', 20, 22, 27, '你若没有甚么偿还，何必使人夺去你睡卧的床呢？'),
('CUV', '箴言', 20, 22, 28, '你先祖所立的地界，你不可挪移。'),
('CUV', '箴言', 20, 22, 29, '你看见办事殷勤的人么？他必站在君王面前，必不站在下贱人面前。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 23, 1, '你若与官长坐席，要留意在你面前的是谁。'),
('CUV', '箴言', 20, 23, 2, '你若是贪食的，就当拿刀放在喉咙上。'),
('CUV', '箴言', 20, 23, 3, '不可贪恋他的美食，因为是哄人的食物。'),
('CUV', '箴言', 20, 23, 4, '不要劳碌求富，休仗自己的聪明。'),
('CUV', '箴言', 20, 23, 5, '你岂要定睛在虚无的钱财上么？因钱财必长翅膀，如鹰向天飞去。'),
('CUV', '箴言', 20, 23, 6, '不要吃恶眼人的饭，也不要贪他的美味；'),
('CUV', '箴言', 20, 23, 7, '因为他心怎样思量，他为人就是怎样。他虽对你说，请吃，请喝，他的心却与你相背。'),
('CUV', '箴言', 20, 23, 8, '你所吃的那点食物必吐出来；你所说的甘美言语也必落空。'),
('CUV', '箴言', 20, 23, 9, '你不要说话给愚昧人听，因他必藐视你智慧的言语。'),
('CUV', '箴言', 20, 23, 10, '不可挪移古时的地界，也不可侵入孤儿的田地；'),
('CUV', '箴言', 20, 23, 11, '因他们的救赎主大有能力，他必向你为他们辨屈。'),
('CUV', '箴言', 20, 23, 12, '你要留心领受训诲，侧耳听从知识的言语。'),
('CUV', '箴言', 20, 23, 13, '不可不管教孩童；你用杖打他，他必不至于死。'),
('CUV', '箴言', 20, 23, 14, '你要用杖打他，就可以救他的灵魂免下阴间。'),
('CUV', '箴言', 20, 23, 15, '我儿，你心若存智慧，我的心也甚欢喜。'),
('CUV', '箴言', 20, 23, 16, '你的嘴若说正直话，我的心肠也必快乐。'),
('CUV', '箴言', 20, 23, 17, '你心中不要嫉妒罪人，只要终日敬畏耶和华；'),
('CUV', '箴言', 20, 23, 18, '因为至终必有善报，你的指望也不致断绝。'),
('CUV', '箴言', 20, 23, 19, '我儿，你当听，当存智慧，好在正道上引导你的心。'),
('CUV', '箴言', 20, 23, 20, '好饮酒的，好吃肉的，不要与他们来往；'),
('CUV', '箴言', 20, 23, 21, '因为好酒贪食的，必致贫穷；好睡觉的，必穿破烂衣服。'),
('CUV', '箴言', 20, 23, 22, '你要听从生你的父亲；你母亲老了，也不可藐视他。'),
('CUV', '箴言', 20, 23, 23, '你当买真理；就是智慧、训诲，和聪明也都不可卖。'),
('CUV', '箴言', 20, 23, 24, '义人的父亲必大得快乐；人生智慧的儿子，必因他欢喜。'),
('CUV', '箴言', 20, 23, 25, '你要使父母欢喜，使生你的快乐。'),
('CUV', '箴言', 20, 23, 26, '我儿，要将你的心归我；你的眼目也要喜悦我的道路。'),
('CUV', '箴言', 20, 23, 27, '妓女是深坑；外女是窄阱。'),
('CUV', '箴言', 20, 23, 28, '他埋伏好像强盗；他使人中多有奸诈的。'),
('CUV', '箴言', 20, 23, 29, '谁有祸患？谁有忧愁？谁有争斗？谁有哀叹（或译：怨言）？谁无故受伤？谁眼目红赤？'),
('CUV', '箴言', 20, 23, 30, '就是那流连饮酒、常去寻找调和酒的人。'),
('CUV', '箴言', 20, 23, 31, '酒发红，在杯中闪烁，你不可观看，虽然下咽舒畅，终久是咬你如蛇，刺你如毒蛇。'),
('CUV', '箴言', 20, 23, 32, 'a'),
('CUV', '箴言', 20, 23, 33, '你眼必看见异怪的事（或译：淫妇）；你心必发出乖谬的话。'),
('CUV', '箴言', 20, 23, 34, '你必像躺在海中，或像卧在桅杆上。'),
('CUV', '箴言', 20, 23, 35, '你必说：人打我，我却未受伤；人鞭打我，我竟不觉得。我几时清醒，我仍去寻酒。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 24, 1, '你不要嫉妒恶人，也不要起意与他们相处；'),
('CUV', '箴言', 20, 24, 2, '因为，他们的心图谋强暴，他们的口谈论奸恶。'),
('CUV', '箴言', 20, 24, 3, '房屋因智慧建造，又因聪明立稳；'),
('CUV', '箴言', 20, 24, 4, '其中因知识充满各样美好宝贵的财物。'),
('CUV', '箴言', 20, 24, 5, '智慧人大有能力；有知识的人力上加力。'),
('CUV', '箴言', 20, 24, 6, '你去打仗，要凭智谋；谋士众多，人便得胜。'),
('CUV', '箴言', 20, 24, 7, '智慧极高，非愚昧人所能及，所以在城门内不敢开口。'),
('CUV', '箴言', 20, 24, 8, '设计作恶的，必称为奸人。'),
('CUV', '箴言', 20, 24, 9, '愚妄人的思念乃是罪恶；亵慢者为人所憎恶。'),
('CUV', '箴言', 20, 24, 10, '你在患难之日若胆怯，你的力量就微小。'),
('CUV', '箴言', 20, 24, 11, '人被拉到死地，你要解救；人将被杀，你须拦阻。'),
('CUV', '箴言', 20, 24, 12, '你若说：这事我未曾知道，那衡量人心的岂不明白么？保守你命的岂不知道么？他岂不按各人所行的报应各人么？'),
('CUV', '箴言', 20, 24, 13, '我儿，你要吃蜜，因为是好的；吃蜂房下滴的蜜便觉甘甜。'),
('CUV', '箴言', 20, 24, 14, '你心得了智慧，也必觉得如此。你若找著，至终必有善报；你的指望也不致断绝。'),
('CUV', '箴言', 20, 24, 15, '你这恶人，不要埋伏攻击义人的家；不要毁坏他安居之所。'),
('CUV', '箴言', 20, 24, 16, '因为，义人虽七次跌倒，仍必兴起；恶人却被祸患倾倒。'),
('CUV', '箴言', 20, 24, 17, '你仇敌跌倒，你不要欢喜；他倾倒，你心不要快乐；'),
('CUV', '箴言', 20, 24, 18, '恐怕耶和华看见就不喜悦，将怒气从仇敌身上转过来。'),
('CUV', '箴言', 20, 24, 19, '不要为作恶的心怀不平，也不要嫉妒恶人；'),
('CUV', '箴言', 20, 24, 20, '因为，恶人终不得善报；恶人的灯也必熄灭。'),
('CUV', '箴言', 20, 24, 21, '我儿，你要敬畏耶和华与君王，不要与反复无常的人结交，'),
('CUV', '箴言', 20, 24, 22, '因为他们的灾难必忽然而起。耶和华与君王所施行的毁灭，谁能知道呢？'),
('CUV', '箴言', 20, 24, 23, '以下也是智慧人的箴言：审判时看人情面是不好的。'),
('CUV', '箴言', 20, 24, 24, '对恶人说：你是义人的，这人万民必咒诅，列邦必憎恶。'),
('CUV', '箴言', 20, 24, 25, '责备恶人的，必得喜悦；美好的福也必临到他。'),
('CUV', '箴言', 20, 24, 26, '应对正直的，犹如与人亲嘴。'),
('CUV', '箴言', 20, 24, 27, '你要在外头预备工料，在田间办理整齐，然后建造房屋。'),
('CUV', '箴言', 20, 24, 28, '不可无故作见证陷害邻舍，也不可用嘴欺骗人。'),
('CUV', '箴言', 20, 24, 29, '不可说：人怎样待我，我也怎样待他；我必照他所行的报复他。'),
('CUV', '箴言', 20, 24, 30, '我经过懒惰人的田地、无知人的葡萄园，'),
('CUV', '箴言', 20, 24, 31, '荆棘长满了地皮，刺草遮盖了田面，石墙也坍塌了。'),
('CUV', '箴言', 20, 24, 32, '我看见就留心思想；我看著就领了训诲。'),
('CUV', '箴言', 20, 24, 33, '再睡片时，打盹片时，抱著手躺卧片时，'),
('CUV', '箴言', 20, 24, 34, '你的贫穷就必如强盗速来，你的缺乏仿佛拿兵器的人来到。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 25, 1, '以下也是所罗门的箴言，是犹大王希西家的人所誊录的。'),
('CUV', '箴言', 20, 25, 2, '将事隐秘乃神的荣耀；将事察清乃君王的荣耀。'),
('CUV', '箴言', 20, 25, 3, '天之高，地之厚，君王之心也测不透。'),
('CUV', '箴言', 20, 25, 4, '除去银子的渣滓就有银子出来，银匠能以做器皿。'),
('CUV', '箴言', 20, 25, 5, '除去王面前的恶人，国位就靠公义坚立。'),
('CUV', '箴言', 20, 25, 6, '不要在王面前妄自尊大；不要在大人的位上站立。'),
('CUV', '箴言', 20, 25, 7, '宁可有人说：请你上来，强如在你觐见的王子面前叫你退下。'),
('CUV', '箴言', 20, 25, 8, '不要冒失出去与人争竞，免得至终被他羞辱，你就不知道怎样行了。'),
('CUV', '箴言', 20, 25, 9, '你与邻舍争讼，要与他一人辩论，不可泄漏人的密事，'),
('CUV', '箴言', 20, 25, 10, '恐怕听见的人骂你，你的臭名就难以脱离。'),
('CUV', '箴言', 20, 25, 11, '一句话说得合宜，就如金苹果在银网子里。'),
('CUV', '箴言', 20, 25, 12, '智慧人的劝戒，在顺从的人耳中，好像金耳环和精金的妆饰。'),
('CUV', '箴言', 20, 25, 13, '忠信的使者叫差他的人心里舒畅，就如在收割时有冰雪的凉气。'),
('CUV', '箴言', 20, 25, 14, '空夸赠送礼物的，好像无雨的风云。'),
('CUV', '箴言', 20, 25, 15, '恒常忍耐可以劝动君王；柔和的舌头能折断骨头。'),
('CUV', '箴言', 20, 25, 16, '你得了蜜么？只可吃够而已，恐怕你过饱就呕吐出来。'),
('CUV', '箴言', 20, 25, 17, '你的脚要少进邻舍的家，恐怕他厌烦你，恨恶你。'),
('CUV', '箴言', 20, 25, 18, '作假见证陷害邻舍的，就是大槌，是利刀，是快箭。'),
('CUV', '箴言', 20, 25, 19, '患难时倚靠不忠诚的人，好像破坏的牙，错骨缝的脚。'),
('CUV', '箴言', 20, 25, 20, '对伤心的人唱歌，就如冷天脱衣服，又如碱上倒醋。'),
('CUV', '箴言', 20, 25, 21, '你的仇敌若饿了，就给他饭吃；若渴了，就给他水喝；'),
('CUV', '箴言', 20, 25, 22, '因为，你这样行就是把炭火堆在他的头上；耶和华也必赏赐你。'),
('CUV', '箴言', 20, 25, 23, '北风生雨，谗谤人的舌头也生怒容。'),
('CUV', '箴言', 20, 25, 24, '宁可住在房顶的角上，不在宽阔的房屋与争吵的妇人同住。'),
('CUV', '箴言', 20, 25, 25, '有好消息从远方来，就如拿凉水给口渴的人喝。'),
('CUV', '箴言', 20, 25, 26, '义人在恶人面前退缩，好像逿浑之泉，弄浊之井。'),
('CUV', '箴言', 20, 25, 27, '吃蜜过多是不好的；考究自己的荣耀也是可厌的。'),
('CUV', '箴言', 20, 25, 28, '人不制伏自己的心，好像毁坏的城邑没有墙垣。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 26, 1, '夏天落雪，收割时下雨，都不相宜；愚昧人得尊荣也是如此。'),
('CUV', '箴言', 20, 26, 2, '麻雀往来，燕子翻飞；这样，无故的咒诅也必不临到。'),
('CUV', '箴言', 20, 26, 3, '鞭子是为打马，辔头是为勒驴；刑杖是为打愚昧人的背。'),
('CUV', '箴言', 20, 26, 4, '不要照愚昧人的愚妄话回答他，恐怕你与他一样。'),
('CUV', '箴言', 20, 26, 5, '要照愚昧人的愚妄话回答他，免得他自以为有智慧。'),
('CUV', '箴言', 20, 26, 6, '藉愚昧人手寄信的，是砍断自己的脚，自受（原文是：喝）损害。'),
('CUV', '箴言', 20, 26, 7, '瘸子的脚空存无用；箴言在愚昧人的口中也是如此。'),
('CUV', '箴言', 20, 26, 8, '将尊荣给愚昧人的，好像人把石子包在机弦里。'),
('CUV', '箴言', 20, 26, 9, '箴言在愚昧人的口中，好像荆棘刺入醉汉的手。'),
('CUV', '箴言', 20, 26, 10, '雇愚昧人的，与雇过路人的，就像射伤众人的弓箭手。'),
('CUV', '箴言', 20, 26, 11, '愚昧人行愚妄事，行了又行，就如狗转过来吃他所吐的。'),
('CUV', '箴言', 20, 26, 12, '你见自以为有智慧的人么？愚昧人比他更有指望。'),
('CUV', '箴言', 20, 26, 13, '懒惰人说：道上有猛狮，街上有壮狮。'),
('CUV', '箴言', 20, 26, 14, '门在枢纽转动，懒惰人在床上也是如此。'),
('CUV', '箴言', 20, 26, 15, '懒惰人放手在盘子里，就是向口撤回也以为劳乏。'),
('CUV', '箴言', 20, 26, 16, '懒惰人看自己比七个善于应对的人更有智慧。'),
('CUV', '箴言', 20, 26, 17, '过路被事激动，管理不干己的争竞，好像人揪住狗耳。'),
('CUV', '箴言', 20, 26, 18, '人欺凌邻舍，却说：我岂不是戏耍么？他就像疯狂的人抛掷火把、利箭，与杀人的兵器（原文是死亡）。'),
('CUV', '箴言', 20, 26, 19, 'a'),
('CUV', '箴言', 20, 26, 20, '火缺了柴就必熄灭；无人传舌，争竞便止息。'),
('CUV', '箴言', 20, 26, 21, '好争竞的人煽惑争端，就如余火加炭，火上加柴一样。'),
('CUV', '箴言', 20, 26, 22, '传舌人的言语，如同美食，深入人的心腹。'),
('CUV', '箴言', 20, 26, 23, '火热的嘴，奸恶的心，好像银渣包的瓦器。'),
('CUV', '箴言', 20, 26, 24, '怨恨人的，用嘴粉饰，心里却藏著诡诈；'),
('CUV', '箴言', 20, 26, 25, '他用甜言蜜语，你不可信他，因为他心中有七样可憎恶的。'),
('CUV', '箴言', 20, 26, 26, '他虽用诡诈遮掩自己的怨恨，他的邪恶必在会中显露。'),
('CUV', '箴言', 20, 26, 27, '挖陷坑的，自己必掉在其中；滚石头的，石头必反滚在他身上。'),
('CUV', '箴言', 20, 26, 28, '虚谎的舌恨他所压伤的人；谄媚的口败坏人的事。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 27, 1, '不要为明日自夸，因为一日要生何事，你尚且不能知道。'),
('CUV', '箴言', 20, 27, 2, '要别人夸奖你，不可用口自夸；等外人称赞你，不可用嘴自称。'),
('CUV', '箴言', 20, 27, 3, '石头重，沙土沉，愚妄人的恼怒比这两样更重。'),
('CUV', '箴言', 20, 27, 4, '忿怒为残忍，怒气为狂澜，惟有嫉妒，谁能敌得住呢？'),
('CUV', '箴言', 20, 27, 5, '当面的责备强如背地的爱情。'),
('CUV', '箴言', 20, 27, 6, '朋友加的伤痕出于忠诚；仇敌连连亲嘴却是多余。'),
('CUV', '箴言', 20, 27, 7, '人吃饱了，厌恶蜂房的蜜；人饥饿了，一切苦物都觉甘甜。'),
('CUV', '箴言', 20, 27, 8, '人离本处飘流，好像雀鸟离窝游飞。'),
('CUV', '箴言', 20, 27, 9, '膏油与香料使人心喜悦；朋友诚实的劝教也是如此甘美。'),
('CUV', '箴言', 20, 27, 10, '你的朋友和父亲的朋友，你都不可离弃。你遭难的日子，不要上弟兄的家去；相近的邻舍强如远方的弟兄。'),
('CUV', '箴言', 20, 27, 11, '我儿，你要作智慧人，好叫我的心欢喜，使我可以回答那讥诮我的人。'),
('CUV', '箴言', 20, 27, 12, '通达人见祸藏躲；愚蒙人前往受害。'),
('CUV', '箴言', 20, 27, 13, '谁为生人作保，就拿谁的衣服；谁为外女作保，谁就承当。'),
('CUV', '箴言', 20, 27, 14, '清晨起来，大声给朋友祝福的，就算是咒诅他。'),
('CUV', '箴言', 20, 27, 15, '大雨之日连连滴漏，和争吵的妇人一样；'),
('CUV', '箴言', 20, 27, 16, '想拦阻他的，便是拦阻风，也是右手抓油。'),
('CUV', '箴言', 20, 27, 17, '铁磨铁，磨出刃来；朋友相感（原文是磨朋友的脸）也是如此。'),
('CUV', '箴言', 20, 27, 18, '看守无花果树的，必吃树上的果子；敬奉主人的，必得尊荣。'),
('CUV', '箴言', 20, 27, 19, '水中照脸，彼此相符；人与人，心也相对。'),
('CUV', '箴言', 20, 27, 20, '阴间和灭亡永不满足；人的眼目也是如此。'),
('CUV', '箴言', 20, 27, 21, '鼎为炼银，炉为炼金，人的称赞也试炼人。'),
('CUV', '箴言', 20, 27, 22, '你虽用杵将愚妄人与打碎的麦子一同捣在臼中，他的愚妄还是离不了他。'),
('CUV', '箴言', 20, 27, 23, '你要详细知道你羊群的景况，留心料理你的牛群；'),
('CUV', '箴言', 20, 27, 24, '因为资财不能永有，冠冕岂能存到万代？'),
('CUV', '箴言', 20, 27, 25, '干草割去，嫩草发现，山上的菜蔬也被收敛。'),
('CUV', '箴言', 20, 27, 26, '羊羔之毛是为你作衣服；山羊是为作田地的价值，'),
('CUV', '箴言', 20, 27, 27, '并有母山羊奶够你吃，也够你的家眷吃，且够养你的婢女。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 28, 1, '恶人虽无人追赶也逃跑；义人却胆壮像狮子。'),
('CUV', '箴言', 20, 28, 2, '邦国因有罪过，君王就多更换；因有聪明知识的人，国必长存。'),
('CUV', '箴言', 20, 28, 3, '穷人欺压贫民，好像暴雨冲没粮食。'),
('CUV', '箴言', 20, 28, 4, '违弃律法的，夸奖恶人；遵守律法的，却与恶人相争。'),
('CUV', '箴言', 20, 28, 5, '坏人不明白公义；惟有寻求耶和华的，无不明白。'),
('CUV', '箴言', 20, 28, 6, '行为纯正的穷乏人胜过行事乖僻的富足人。'),
('CUV', '箴言', 20, 28, 7, '谨守律法的，是智慧之子；与贪食人作伴的，却羞辱其父。'),
('CUV', '箴言', 20, 28, 8, '人以厚利加增财物，是给那怜悯穷人者积蓄的。'),
('CUV', '箴言', 20, 28, 9, '转耳不听律法的，他的祈祷也为可憎。'),
('CUV', '箴言', 20, 28, 10, '诱惑正直人行恶道的，必掉在自己的坑里；惟有完全人必承受福分。'),
('CUV', '箴言', 20, 28, 11, '富足人自以为有智慧，但聪明的贫穷人能将他查透。'),
('CUV', '箴言', 20, 28, 12, '义人得志，有大荣耀；恶人兴起，人就躲藏。'),
('CUV', '箴言', 20, 28, 13, '遮掩自己罪过的，必不亨通；承认离弃罪过的，必蒙怜恤。'),
('CUV', '箴言', 20, 28, 14, '常存敬畏的，便为有福；心存刚硬的，必陷在祸患里。'),
('CUV', '箴言', 20, 28, 15, '暴虐的君王辖制贫民，好像吼叫的狮子、觅食的熊。'),
('CUV', '箴言', 20, 28, 16, '无知的君多行暴虐；以贪财为可恨的，必年长日久。'),
('CUV', '箴言', 20, 28, 17, '背负流人血之罪的，必往坑里奔跑，谁也不可拦阻他。'),
('CUV', '箴言', 20, 28, 18, '行动正直的，必蒙拯救；行事弯曲的，立时跌倒。'),
('CUV', '箴言', 20, 28, 19, '耕种自己田地的，必得饱食；追随虚浮的，足受穷乏。'),
('CUV', '箴言', 20, 28, 20, '诚实人必多得福；想要急速发财的，不免受罚。'),
('CUV', '箴言', 20, 28, 21, '看人的情面乃为不好；人因一块饼枉法也为不好。'),
('CUV', '箴言', 20, 28, 22, '人有恶眼想要急速发财，却不知穷乏必临到他身。'),
('CUV', '箴言', 20, 28, 23, '责备人的，后来蒙人喜悦，多于那用舌头谄媚人的。'),
('CUV', '箴言', 20, 28, 24, '偷窃父母的，说：这不是罪，此人就是与强盗同类。'),
('CUV', '箴言', 20, 28, 25, '心中贪婪的，挑起争端；倚靠耶和华的，必得丰裕。'),
('CUV', '箴言', 20, 28, 26, '心中自是的，便是愚昧人；凭智慧行事的，必蒙拯救。'),
('CUV', '箴言', 20, 28, 27, '赒济贫穷的，不致缺乏；佯为不见的，必多受咒诅。'),
('CUV', '箴言', 20, 28, 28, '恶人兴起，人就躲藏；恶人败亡，义人增多。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 29, 1, '人屡次受责罚，仍然硬著颈项；他必顷刻败坏，无法可治。'),
('CUV', '箴言', 20, 29, 2, '义人增多，民就喜乐；恶人掌权，民就叹息。'),
('CUV', '箴言', 20, 29, 3, '爱慕智慧的，使父亲喜乐；与妓女结交的，却浪费钱财。'),
('CUV', '箴言', 20, 29, 4, '王藉公平，使国坚定；索要贿赂，使国倾败。'),
('CUV', '箴言', 20, 29, 5, '谄媚邻舍的，就是设网罗绊他的脚。'),
('CUV', '箴言', 20, 29, 6, '恶人犯罪，自陷网罗；惟独义人欢呼喜乐。'),
('CUV', '箴言', 20, 29, 7, '义人知道查明穷人的案；恶人没有聪明，就不得而知。'),
('CUV', '箴言', 20, 29, 8, '亵慢人煽惑通城；智慧人止息众怒。'),
('CUV', '箴言', 20, 29, 9, '智慧人与愚妄人相争，或怒或笑，总不能使他止息。'),
('CUV', '箴言', 20, 29, 10, '好流人血的，恨恶完全人，索取正直人的性命。'),
('CUV', '箴言', 20, 29, 11, '愚妄人怒气全发；智慧人忍气含怒。'),
('CUV', '箴言', 20, 29, 12, '君王若听谎言，他一切臣仆都是奸恶。'),
('CUV', '箴言', 20, 29, 13, '贫穷人、强暴人在世相遇；他们的眼目都蒙耶和华光照。'),
('CUV', '箴言', 20, 29, 14, '君王凭诚实判断穷人；他的国位必永远坚立。'),
('CUV', '箴言', 20, 29, 15, '杖打和责备能加增智慧；放纵的儿子使母亲羞愧。'),
('CUV', '箴言', 20, 29, 16, '恶人加多，过犯也加多，义人必看见他们跌倒。'),
('CUV', '箴言', 20, 29, 17, '管教你的儿子，他就使你得安息，也必使你心里喜乐。'),
('CUV', '箴言', 20, 29, 18, '没有异象（或译：默示），民就放肆；惟遵守律法的，便为有福。'),
('CUV', '箴言', 20, 29, 19, '只用言语，仆人不肯受管教；他虽然明白，也不留意。'),
('CUV', '箴言', 20, 29, 20, '你见言语急躁的人吗？愚昧人比他更有指望。'),
('CUV', '箴言', 20, 29, 21, '人将仆人从小娇养，这仆人终久必成了他的儿子。'),
('CUV', '箴言', 20, 29, 22, '好气的人挑启争端；暴怒的人多多犯罪。'),
('CUV', '箴言', 20, 29, 23, '人的高傲必使他卑下；心里谦逊的，必得尊荣。'),
('CUV', '箴言', 20, 29, 24, '人与盗贼分赃，是恨恶自己的性命；他听见叫人发誓的声音，却不言语。'),
('CUV', '箴言', 20, 29, 25, '惧怕人的，陷入网罗；惟有倚靠耶和华的，必得安稳。'),
('CUV', '箴言', 20, 29, 26, '求王恩的人多；定人事乃在耶和华。'),
('CUV', '箴言', 20, 29, 27, '为非作歹的，被义人憎嫌；行事正直的，被恶人憎恶。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 30, 1, '雅基的儿子亚古珥的言语就是真言。这人对以铁和乌甲说：'),
('CUV', '箴言', 20, 30, 2, '我比众人更蠢笨，也没有人的聪明。'),
('CUV', '箴言', 20, 30, 3, '我没有学好智慧，也不认识至圣者。'),
('CUV', '箴言', 20, 30, 4, '谁升天又降下来？谁聚风在掌握中？谁包水在衣服里？谁立定地的四极？他名叫甚么？他儿子名叫甚么？你知道吗？'),
('CUV', '箴言', 20, 30, 5, '神的言语句句都是炼净的；投靠他的，他便作他们的盾牌。'),
('CUV', '箴言', 20, 30, 6, '他的言语，你不可加添，恐怕他责备你，你就显为说谎言的。'),
('CUV', '箴言', 20, 30, 7, '我求你两件事，在我未死之先，不要不赐给我：'),
('CUV', '箴言', 20, 30, 8, '求你使虚假和谎言远离我；使我也不贫穷也不富足；赐给我需用的饮食，'),
('CUV', '箴言', 20, 30, 9, '恐怕我饱足不认你，说：耶和华是谁呢？又恐怕我贫穷就偷窃，以致亵渎我神的名。'),
('CUV', '箴言', 20, 30, 10, '你不要向主人谗谤仆人，恐怕他咒诅你，你便算为有罪。'),
('CUV', '箴言', 20, 30, 11, '有一宗人（宗：原文是代；下同），咒诅父亲，不给母亲祝福。'),
('CUV', '箴言', 20, 30, 12, '有一宗人，自以为清洁，却没有洗去自己的污秽。'),
('CUV', '箴言', 20, 30, 13, '有一宗人，眼目何其高傲，眼皮也是高举。'),
('CUV', '箴言', 20, 30, 14, '有一宗人，牙如剑，齿如刀，要吞灭地上的困苦人和世间的穷乏人。'),
('CUV', '箴言', 20, 30, 15, '蚂蟥有两个女儿，常说：给呀，给呀！有三样不知足的，连不说够的共有四样：'),
('CUV', '箴言', 20, 30, 16, '就是阴间和石胎，浸水不足的地，并火。'),
('CUV', '箴言', 20, 30, 17, '戏笑父亲、藐视而不听从母亲的，他的眼睛必为谷中的乌鸦啄出来，为鹰雏所吃。'),
('CUV', '箴言', 20, 30, 18, '我所测不透的奇妙有三样，连我所不知道的共有四样：'),
('CUV', '箴言', 20, 30, 19, '就是鹰在空中飞的道；蛇在磐石上爬的道；船在海中行的道；男与女交合的道。'),
('CUV', '箴言', 20, 30, 20, '淫妇的道也是这样：他吃了，把嘴一擦就说：我没有行恶。'),
('CUV', '箴言', 20, 30, 21, '使地震动的有三样，连地担不起的共有四样：'),
('CUV', '箴言', 20, 30, 22, '就是仆人作王；愚顽人吃饱；'),
('CUV', '箴言', 20, 30, 23, '丑恶的女子出嫁；婢女接续主母。'),
('CUV', '箴言', 20, 30, 24, '地上有四样小物，却甚聪明：'),
('CUV', '箴言', 20, 30, 25, '蚂蚁是无力之类，却在夏天预备粮食。'),
('CUV', '箴言', 20, 30, 26, '沙番是软弱之类，却在磐石中造房。'),
('CUV', '箴言', 20, 30, 27, '蝗虫没有君王，却分队而出。'),
('CUV', '箴言', 20, 30, 28, '守宫用爪抓墙，却住在王宫。'),
('CUV', '箴言', 20, 30, 29, '步行威武的有三样，连行走威武的共有四样：'),
('CUV', '箴言', 20, 30, 30, '就是狮子─乃百兽中最为猛烈、无所躲避的，'),
('CUV', '箴言', 20, 30, 31, '猎狗，公山羊，和无人能敌的君王。'),
('CUV', '箴言', 20, 30, 32, '你若行事愚顽，自高自傲，或是怀了恶念，就当用手摀口。'),
('CUV', '箴言', 20, 30, 33, '摇牛奶必成奶油；扭鼻子必出血。照样，激动怒气必起争端。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '箴言', 20, 31, 1, '利慕伊勒王的言语，是他母亲教训他的真言。'),
('CUV', '箴言', 20, 31, 2, '我的儿啊，我腹中生的儿啊，我许愿得的儿啊！我当怎样教训你呢？'),
('CUV', '箴言', 20, 31, 3, '不要将你的精力给妇女；也不要有败坏君王的行为。'),
('CUV', '箴言', 20, 31, 4, '利慕伊勒啊，君王喝酒，君王喝酒不相宜；王子说浓酒在那里也不相宜；'),
('CUV', '箴言', 20, 31, 5, '恐怕喝了就忘记律例，颠倒一切困苦人的是非。'),
('CUV', '箴言', 20, 31, 6, '可以把浓酒给将亡的人喝，把清酒给苦心的人喝，'),
('CUV', '箴言', 20, 31, 7, '让他喝了，就忘记他的贫穷，不再记念他的苦楚。'),
('CUV', '箴言', 20, 31, 8, '你当为哑巴（或译：不能自辩的）开口，为一切孤独的伸冤。'),
('CUV', '箴言', 20, 31, 9, '你当开口按公义判断，为困苦和穷乏的辨屈。'),
('CUV', '箴言', 20, 31, 10, '才德的妇人谁能得著呢？他的价值远胜过珍珠。'),
('CUV', '箴言', 20, 31, 11, '他丈夫心里倚靠他，必不缺少利益.；'),
('CUV', '箴言', 20, 31, 12, '他一生使丈夫有益无损。'),
('CUV', '箴言', 20, 31, 13, '他寻找羊羢和麻，甘心用手做工。'),
('CUV', '箴言', 20, 31, 14, '他好像商船从远方运粮来，'),
('CUV', '箴言', 20, 31, 15, '未到黎明他就起来，把食物分给家中的人，将当做的工分派婢女。'),
('CUV', '箴言', 20, 31, 16, '他想得田地就买来；用手所得之利栽种葡萄园。'),
('CUV', '箴言', 20, 31, 17, '他以能力束腰，使膀臂有力。'),
('CUV', '箴言', 20, 31, 18, '他觉得所经营的有利；他的灯终夜不灭'),
('CUV', '箴言', 20, 31, 19, '他手拿撚线竿，手把纺线车。'),
('CUV', '箴言', 20, 31, 20, '他张手赒济困苦人，伸手帮补穷乏人。'),
('CUV', '箴言', 20, 31, 21, '他不因下雪为家里的人担心，因为全家都穿著朱红衣服。'),
('CUV', '箴言', 20, 31, 22, '他为自己制作绣花毯子；他的衣服是细麻和紫色布作的。'),
('CUV', '箴言', 20, 31, 23, '他丈夫在城门口与本地的长老同坐，为众人所认识。'),
('CUV', '箴言', 20, 31, 24, '他做细麻布衣裳出卖，又将腰带卖与商家。'),
('CUV', '箴言', 20, 31, 25, '能力和威仪是他的衣服；他想到日后的景况就喜笑。'),
('CUV', '箴言', 20, 31, 26, '他开口就发智慧；他舌上有仁慈的法则。'),
('CUV', '箴言', 20, 31, 27, '他观察家务，并不吃闲饭。'),
('CUV', '箴言', 20, 31, 28, '他的儿女起来，称他有福；他的丈夫也称赞他，'),
('CUV', '箴言', 20, 31, 29, '说：才德的女子很多，惟独你超过一切。'),
('CUV', '箴言', 20, 31, 30, '艳丽是虚假的，美容是虚浮的；惟敬畏耶和华的妇女必得称赞。'),
('CUV', '箴言', 20, 31, 31, '愿他享受操作所得的；愿他的工作在城门口荣耀他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '传道书', 21, 1, 1, '在耶路撒冷作王、大卫的儿子、传道者的言语。'),
('CUV', '传道书', 21, 1, 2, '传道者说：虚空的虚空，虚空的虚空，凡事都是虚空。'),
('CUV', '传道书', 21, 1, 3, '人一切的劳碌，就是他在日光之下的劳碌，有甚么益处呢？'),
('CUV', '传道书', 21, 1, 4, '一代过去，一代又来，地却永远长存。'),
('CUV', '传道书', 21, 1, 5, '日头出来，日头落下，急归所出之地。'),
('CUV', '传道书', 21, 1, 6, '风往南刮，又向北转，不住地旋转，而且返回转行原道。'),
('CUV', '传道书', 21, 1, 7, '江河都往海里流，海却不满；江河从何处流，仍归还何处。'),
('CUV', '传道书', 21, 1, 8, '万事令人厌烦（或译：万物满有困乏），人不能说尽。眼看，看不饱；耳听，听不足。'),
('CUV', '传道书', 21, 1, 9, '已有的事后必再有；已行的事后必再行。日光之下并无新事。'),
('CUV', '传道书', 21, 1, 10, '岂有一件事人能指著说这是新的？哪知，在我们以前的世代早已有了。'),
('CUV', '传道书', 21, 1, 11, '已过的世代，无人记念；将来的世代，后来的人也不记念。'),
('CUV', '传道书', 21, 1, 12, '我传道者在耶路撒冷作过以色列的王。'),
('CUV', '传道书', 21, 1, 13, '我专心用智慧寻求、查究天下所做的一切事，乃知神叫世人所经练的是极重的劳苦。'),
('CUV', '传道书', 21, 1, 14, '我见日光之下所做的一切事，都是虚空，都是捕风。'),
('CUV', '传道书', 21, 1, 15, '弯曲的，不能变直；缺少的，不能足数。'),
('CUV', '传道书', 21, 1, 16, '我心里议论说：我得了大智慧，胜过我以前在耶路撒冷的众人，而且我心中多经历智慧和知识的事。'),
('CUV', '传道书', 21, 1, 17, '我又专心察明智慧、狂妄，和愚昧，乃知这也是捕风。'),
('CUV', '传道书', 21, 1, 18, '因为多有智慧，就多有愁烦；加增知识的，就加增忧伤。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '传道书', 21, 2, 1, '我心里说：来罢，我以喜乐试试你，你好享福！谁知，这也是虚空。'),
('CUV', '传道书', 21, 2, 2, '我指嬉笑说：这是狂妄。论喜乐说：有何功效呢？'),
('CUV', '传道书', 21, 2, 3, '我心里察究，如何用酒使我肉体舒畅，我心却仍以智慧引导我；又如何持住愚昧，等我看明世人，在天下一生当行何事为美。'),
('CUV', '传道书', 21, 2, 4, '我为自己动大工程，建造房屋，栽种葡萄园，'),
('CUV', '传道书', 21, 2, 5, '修造园囿，在其中栽种各样果木树；'),
('CUV', '传道书', 21, 2, 6, '挖造水池，用以浇灌嫩小的树木。'),
('CUV', '传道书', 21, 2, 7, '我买了仆婢，也有生在家中的仆婢；又有许多牛群羊群，胜过以前在耶路撒冷众人所有的。'),
('CUV', '传道书', 21, 2, 8, '我又为自己积蓄金银和君王的财宝，并各省的财宝；又得唱歌的男女和世人所喜爱的物，并许多的妃嫔。'),
('CUV', '传道书', 21, 2, 9, '这样，我就日见昌盛，胜过以前在耶路撒冷的众人。我的智慧仍然存留。'),
('CUV', '传道书', 21, 2, 10, '凡我眼所求的，我没有留下不给他的；我心所乐的，我没有禁止不享受的；因我的心为我一切所劳碌的快乐，这就是我从劳碌中所得的分。'),
('CUV', '传道书', 21, 2, 11, '后来，我察看我手所经营的一切事和我劳碌所成的功。谁知都是虚空，都是捕风；在日光之下毫无益处。'),
('CUV', '传道书', 21, 2, 12, '我转念观看智慧、狂妄，和愚昧。在王以后而来的人还能做甚么呢？也不过行早先所行的就是了。'),
('CUV', '传道书', 21, 2, 13, '我便看出智慧胜过愚昧，如同光明胜过黑暗。'),
('CUV', '传道书', 21, 2, 14, '智慧人的眼目光明（光明原文是在他头上），愚昧人在黑暗里行。我却看明有一件事，这两等人都必遇见。'),
('CUV', '传道书', 21, 2, 15, '我就心里说：愚昧人所遇见的，我也必遇见，我为何更有智慧呢？我心里说，这也是虚空。'),
('CUV', '传道书', 21, 2, 16, '智慧人和愚昧人一样，永远无人记念，因为日后都被忘记；可叹智慧人死亡，与愚昧人无异。'),
('CUV', '传道书', 21, 2, 17, '我所以恨恶生命；因为在日光之下所行的事我都以为烦恼，都是虚空，都是捕风。'),
('CUV', '传道书', 21, 2, 18, '我恨恶一切的劳碌，就是我在日光之下的劳碌，因为我得来的必留给我以后的人。'),
('CUV', '传道书', 21, 2, 19, '那人是智慧是愚昧，谁能知道？他竟要管理我劳碌所得的，就是我在日光之下用智慧所得的。这也是虚空。'),
('CUV', '传道书', 21, 2, 20, '故此，我转想我在日光之下所劳碌的一切工作，心便绝望。'),
('CUV', '传道书', 21, 2, 21, '因为有人用智慧、知识、灵巧所劳碌得来的，却要留给未曾劳碌的人为分.。这也是虚空，也是大患。'),
('CUV', '传道书', 21, 2, 22, '人在日光之下劳碌累心，在他一切的劳碌上得著甚么呢？'),
('CUV', '传道书', 21, 2, 23, '因为他日日忧虑，他的劳苦成为愁烦，连夜间心也不安。这也是虚空。'),
('CUV', '传道书', 21, 2, 24, '人莫强如吃喝，且在劳碌中享福，我看这也是出于神的手。'),
('CUV', '传道书', 21, 2, 25, '论到吃用、享福，谁能胜过我呢？'),
('CUV', '传道书', 21, 2, 26, '神喜悦谁，就给谁智慧、知识，和喜乐；惟有罪人，神使他劳苦，叫他将所收聚的、所堆积的归给神所喜悦的人。这也是虚空，也是捕风。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '传道书', 21, 3, 1, '凡事都有定期，天下万务都有定时。'),
('CUV', '传道书', 21, 3, 2, '生有时，死有时；栽种有时，拔出所栽种的也有时；'),
('CUV', '传道书', 21, 3, 3, '杀戮有时，医治有时；拆毁有时，建造有时；'),
('CUV', '传道书', 21, 3, 4, '哭有时，笑有时；哀恸有时，跳舞有时；'),
('CUV', '传道书', 21, 3, 5, '抛掷石头有时，堆聚石头有时；怀抱有时，不怀抱有时；'),
('CUV', '传道书', 21, 3, 6, '寻找有时，失落有时；保守有时，舍弃有时；'),
('CUV', '传道书', 21, 3, 7, '撕裂有时，缝补有时；静默有时，言语有时；'),
('CUV', '传道书', 21, 3, 8, '喜爱有时，恨恶有时；争战有时，和好有时。'),
('CUV', '传道书', 21, 3, 9, '这样看来，做事的人在他的劳碌上有甚么益处呢？'),
('CUV', '传道书', 21, 3, 10, '我见神叫世人劳苦，使他们在其中受经练。'),
('CUV', '传道书', 21, 3, 11, '神造万物，各按其时成为美好，又将永生（原文是永远）安置在世人心里。然而神从始至终的作为，人不能参透。'),
('CUV', '传道书', 21, 3, 12, '我知道世人，莫强如终身喜乐行善；'),
('CUV', '传道书', 21, 3, 13, '并且人人吃喝，在他一切劳碌中享福，这也是神的恩赐。'),
('CUV', '传道书', 21, 3, 14, '我知道神一切所做的都必永存；无所增添，无所减少。神这样行，是要人在他面前存敬畏的心。'),
('CUV', '传道书', 21, 3, 15, '现今的事早先就有了，将来的事早已也有了，并且神使已过的事重新再来（或译：并且神再寻回已过的事）。'),
('CUV', '传道书', 21, 3, 16, '我又见日光之下，在审判之处有奸恶，在公义之处也有奸恶。'),
('CUV', '传道书', 21, 3, 17, '我心里说，神必审判义人和恶人；因为在那里，各样事务，一切工作，都有定时。'),
('CUV', '传道书', 21, 3, 18, '我心里说，这乃为世人的缘故，是神要试验他们，使他们觉得自己不过像兽一样。'),
('CUV', '传道书', 21, 3, 19, '因为世人遭遇的，兽也遭遇，所遭遇的都是一样：这个怎样死，那个也怎样死，气息都是一样。人不能强于兽，都是虚空。'),
('CUV', '传道书', 21, 3, 20, '都归一处，都是出于尘土，也都归于尘土。'),
('CUV', '传道书', 21, 3, 21, '谁知道人的灵是往上升，兽的魂是下入地呢？'),
('CUV', '传道书', 21, 3, 22, '故此，我见人莫强如在他经营的事上喜乐，因为这是他的分。他身后的事谁能使他回来得见呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '传道书', 21, 4, 1, '我又转念，见日光之下所行的一切欺压。看哪，受欺压的流泪，且无人安慰；欺压他们的有势力，也无人安慰他们。'),
('CUV', '传道书', 21, 4, 2, '因此，我赞叹那早已死的死人，胜过那还活著的活人。'),
('CUV', '传道书', 21, 4, 3, '并且我以为那未曾生的，就是未见过日光之下恶事的，比这两等人更强。'),
('CUV', '传道书', 21, 4, 4, '我又见人为一切的劳碌和各样灵巧的工作就被邻舍嫉妒。这也是虚空，也是捕风。'),
('CUV', '传道书', 21, 4, 5, '愚昧人抱著手，吃自己的肉。'),
('CUV', '传道书', 21, 4, 6, '满了一把，得享安静，强如满了两把，劳碌捕风。'),
('CUV', '传道书', 21, 4, 7, '我又转念，见日光之下有一件虚空的事：'),
('CUV', '传道书', 21, 4, 8, '有人孤单无二，无子无兄，竟劳碌不息，眼目也不以钱财为足。他说：我劳劳碌碌，刻苦自己，不享福乐，到底是为谁呢？这也是虚空，是极重的劳苦。'),
('CUV', '传道书', 21, 4, 9, '两个人总比一个人好，因为二人劳碌同得美好的果效。'),
('CUV', '传道书', 21, 4, 10, '若是跌倒，这人可以扶起他的同伴；若是孤身跌倒，没有别人扶起他来，这人就有祸了。'),
('CUV', '传道书', 21, 4, 11, '再者，二人同睡就都暖和，一人独睡怎能暖和呢？'),
('CUV', '传道书', 21, 4, 12, '有人攻胜孤身一人，若有二人便能敌挡他；三股合成的绳子不容易折断。'),
('CUV', '传道书', 21, 4, 13, '贫穷而有智慧的少年人胜过年老不肯纳谏的愚昧王。'),
('CUV', '传道书', 21, 4, 14, '这人是从监牢中出来作王，在他国中，生来原是贫穷的。'),
('CUV', '传道书', 21, 4, 15, '我见日光之下一切行动的活人都随从那第二位，就是起来代替老王的少年人。'),
('CUV', '传道书', 21, 4, 16, '他所治理的众人就是他的百姓，多得无数；在他后来的人尚且不喜悦他。这真是虚空，也是捕风。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '传道书', 21, 5, 1, '你到神的殿要谨慎脚步；因为近前听，胜过愚昧人献祭（或译：胜过献愚昧人的祭），他们本不知道所做的是恶。'),
('CUV', '传道书', 21, 5, 2, '你在神面前不可冒失开口，也不可心急发言；因为神在天上，你在地下，所以你的言语要寡少。'),
('CUV', '传道书', 21, 5, 3, '事务多，就令人做梦；言语多，就显出愚昧。'),
('CUV', '传道书', 21, 5, 4, '你向神许愿，偿还不可迟延，因他不喜悦愚昧人，所以你许的愿应当偿还。'),
('CUV', '传道书', 21, 5, 5, '你许愿不还，不如不许。'),
('CUV', '传道书', 21, 5, 6, '不可任你的口使肉体犯罪，也不可在祭司（原文是使者）面前说是错许了。为何使神因你的声音发怒，败坏你手所做的呢？'),
('CUV', '传道书', 21, 5, 7, '多梦和多言，其中多有虚幻，你只要敬畏神。'),
('CUV', '传道书', 21, 5, 8, '你若在一省之中见穷人受欺压，并夺去公义公平的事，不要因此诧异；因有一位高过居高位的鉴察，在他们以上还有更高的。'),
('CUV', '传道书', 21, 5, 9, '况且地的益处归众人，就是君王也受田地的供应。'),
('CUV', '传道书', 21, 5, 10, '贪爱银子的，不因得银子知足；贪爱丰富的，也不因得利益知足。这也是虚空。'),
('CUV', '传道书', 21, 5, 11, '货物增添，吃的人也增添，物主得甚么益处呢？不过眼看而已！'),
('CUV', '传道书', 21, 5, 12, '劳碌的人不拘吃多吃少，睡得香甜；富足人的丰满却不容他睡觉。'),
('CUV', '传道书', 21, 5, 13, '我见日光之下有一宗大祸患，就是财主积存资财，反害自己。'),
('CUV', '传道书', 21, 5, 14, '因遭遇祸患，这些资财就消灭；那人若生了儿子，手里也一无所有。'),
('CUV', '传道书', 21, 5, 15, '他怎样从母胎赤身而来，也必照样赤身而去；他所劳碌得来的，手中分毫不能带去。'),
('CUV', '传道书', 21, 5, 16, '他来的情形怎样，他去的情形也怎样。这也是一宗大祸患。他为风劳碌有甚么益处呢？'),
('CUV', '传道书', 21, 5, 17, '并且他终身在黑暗中吃喝，多有烦恼，又有病患呕气。'),
('CUV', '传道书', 21, 5, 18, '我所见为善为美的，就是人在神赐他一生的日子吃喝，享受日光之下劳碌得来的好处，因为这是他的分。'),
('CUV', '传道书', 21, 5, 19, '神赐人资财丰富，使他能以吃用，能取自己的分，在他劳碌中喜乐，这乃是神的恩赐。'),
('CUV', '传道书', 21, 5, 20, '他不多思念自己一生的年日，因为神应他的心使他喜乐。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '传道书', 21, 6, 1, '我见日光之下有一宗祸患重压在人身上，'),
('CUV', '传道书', 21, 6, 2, '就是人蒙神赐他资财、丰富、尊荣，以致他心里所愿的一样都不缺，只是神使他不能吃用，反有外人来吃用。这是虚空，也是祸患。'),
('CUV', '传道书', 21, 6, 3, '人若生一百个儿子，活许多岁数，以致他的年日甚多，心里却不得满享福乐，又不得埋葬；据我说，那不到期而落的胎比他倒好。'),
('CUV', '传道书', 21, 6, 4, '因为虚虚而来，暗暗而去，名字被黑暗遮蔽，'),
('CUV', '传道书', 21, 6, 5, '并且没有见过天日，也毫无知觉；这胎，比那人倒享安息。'),
('CUV', '传道书', 21, 6, 6, '那人虽然活千年，再活千年，却不享福，众人岂不都归一个地方去么？'),
('CUV', '传道书', 21, 6, 7, '人的劳碌都为口腹，心里却不知足。'),
('CUV', '传道书', 21, 6, 8, '这样看来，智慧人比愚昧人有甚么长处呢？穷人在众人面前知道如何行，有甚么长处呢？'),
('CUV', '传道书', 21, 6, 9, '眼睛所看的比心里妄想的倒好。这也是虚空，也是捕风。'),
('CUV', '传道书', 21, 6, 10, '先前所有的，早已起了名，并知道何为人，他也不能与那比自己力大的相争。'),
('CUV', '传道书', 21, 6, 11, '加增虚浮的事既多，这与人有甚么益处呢？'),
('CUV', '传道书', 21, 6, 12, '人一生虚度的日子，就如影儿经过，谁知道甚么与他有益呢？谁能告诉他身后在日光之下有甚么事呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '传道书', 21, 7, 1, '名誉强如美好的的膏油；人死的日子胜过人生的日子。'),
('CUV', '传道书', 21, 7, 2, '往遭丧的家去，强如往宴乐的家去；因为死是众人的结局，活人也必将这事放在心上。'),
('CUV', '传道书', 21, 7, 3, '忧愁强如喜笑；因为面带愁容，终必使心喜乐。'),
('CUV', '传道书', 21, 7, 4, '智慧人的心在遭丧之家；愚昧人的心在快乐之家。'),
('CUV', '传道书', 21, 7, 5, '听智慧人的责备，强如听愚昧人的歌唱。'),
('CUV', '传道书', 21, 7, 6, '愚昧人的笑声，好像锅下烧荆棘的爆声；这也是虚空。'),
('CUV', '传道书', 21, 7, 7, '勒索使智慧人变为愚妄；贿赂能败坏人的慧心。'),
('CUV', '传道书', 21, 7, 8, '事情的终局强如事情的起头；存心忍耐的，胜过居心骄傲的。'),
('CUV', '传道书', 21, 7, 9, '你不要心里急躁恼怒，因为恼怒存在愚昧人的怀中。'),
('CUV', '传道书', 21, 7, 10, '不要说：先前的日子强过如今的日子，是甚么缘故呢？你这样问，不是出于智慧。'),
('CUV', '传道书', 21, 7, 11, '智慧和产业并好，而且见天日的人得智慧更为有益。'),
('CUV', '传道书', 21, 7, 12, '因为智慧护庇人，好像银钱护庇人一样。惟独智慧能保全智慧人的生命。这就是知识的益处。'),
('CUV', '传道书', 21, 7, 13, '你要察看神的作为；因神使为曲的，谁能变为直呢？'),
('CUV', '传道书', 21, 7, 14, '遇亨通的日子你当喜乐；遭患难的日子你当思想；因为神使这两样并列，为的是叫人查不出身后有甚么事。'),
('CUV', '传道书', 21, 7, 15, '有义人行义，反致灭亡；有恶人行恶，倒享长寿。这都是我在虚度之日中所见过的。'),
('CUV', '传道书', 21, 7, 16, '不要行义过分，也不要过于自逞智慧，何必自取败亡呢？'),
('CUV', '传道书', 21, 7, 17, '不要行恶过分，也不要为人愚昧，何必不到期而死呢？'),
('CUV', '传道书', 21, 7, 18, '你持守这个为美，那个也不要松手；因为敬畏神的人，必从这两样出来。'),
('CUV', '传道书', 21, 7, 19, '智慧使有智慧的人比城中十个官长更有能力。'),
('CUV', '传道书', 21, 7, 20, '时常行善而不犯罪的义人，世上实在没有。'),
('CUV', '传道书', 21, 7, 21, '人所说的一切话，你不要放在心上，恐怕听见你的仆人咒诅你。'),
('CUV', '传道书', 21, 7, 22, '因为你心里知道，自己也曾屡次咒诅别人。'),
('CUV', '传道书', 21, 7, 23, '我曾用智慧试验这一切事；我说，要得智慧，智慧却离我远。'),
('CUV', '传道书', 21, 7, 24, '万事之理，离我甚远，而且最深，谁能测透呢？'),
('CUV', '传道书', 21, 7, 25, '我转念，一心要知道，要考察，要寻求智慧和万事的理由；又要知道邪恶为愚昧，愚昧为狂妄。'),
('CUV', '传道书', 21, 7, 26, '我得知有等妇人比死还苦：他的心是网罗，手是锁链。凡蒙神喜悦的人必能躲避他；有罪的人却被他缠住了。'),
('CUV', '传道书', 21, 7, 27, '传道者说：看哪，一千男子中，我找到一个正直人，但众女子中，没有找到一个。我将这事一一比较，要寻求其理，我心仍要寻找，却未曾找到。'),
('CUV', '传道书', 21, 7, 28, 'a'),
('CUV', '传道书', 21, 7, 29, '我所找到的只有一件，就是神造人原是正直，但他们寻出许多巧计。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '传道书', 21, 8, 1, '谁如智慧人呢？谁知道事情的解释呢？人的智慧使他的脸发光，并使他脸上的暴气改变。'),
('CUV', '传道书', 21, 8, 2, '我劝你遵守王的命令；既指神起誓，理当如此。'),
('CUV', '传道书', 21, 8, 3, '不要急躁离开王的面前，不要固执行恶，因为他凡事都随自己的心意而行。'),
('CUV', '传道书', 21, 8, 4, '王的话本有权力，谁敢问他说你做甚么呢？'),
('CUV', '传道书', 21, 8, 5, '凡遵守命令的，必不经历祸患；智慧人的心能辨明时候和定理（原文是审判；下节同）。'),
('CUV', '传道书', 21, 8, 6, '各样事务成就都有时候和定理，因为人的苦难重压在他身上。'),
('CUV', '传道书', 21, 8, 7, '他不知道将来的事，因为将来如何，谁能告诉他呢？'),
('CUV', '传道书', 21, 8, 8, '无人有权力掌管生命，将生命留住；也无人有权力掌管死期；这场争战，无人能免；邪恶也不能救那好行邪恶的人。'),
('CUV', '传道书', 21, 8, 9, '这一切我都见过，也专心查考日光之下所做的一切事。有时这人管辖那人，令人受害。'),
('CUV', '传道书', 21, 8, 10, '我见恶人埋葬，归入坟墓；又见行正直事的离开圣地，在城中被人忘记。这也是虚空。'),
('CUV', '传道书', 21, 8, 11, '因为断定罪名不立刻施刑，所以世人满心作恶。'),
('CUV', '传道书', 21, 8, 12, '罪人虽然作恶百次，倒享长久的年日；然而我准知道，敬畏神的，就是在他面前敬畏的人，终久必得福乐。'),
('CUV', '传道书', 21, 8, 13, '恶人却不得福乐，也不得长久的年日；这年日好像影儿，因他不敬畏神。'),
('CUV', '传道书', 21, 8, 14, '世上有一件虚空的事，就是义人所遭遇的，反照恶人所行的；又有恶人所遭遇的，反照义人所行的。我说，这也是虚空。'),
('CUV', '传道书', 21, 8, 15, '我就称赞快乐，原来人在日光之下，莫强如吃喝快乐；因为他在日光之下，神赐他一生的年日，要从劳碌中，时常享受所得的。'),
('CUV', '传道书', 21, 8, 16, '我专心求智慧，要看世上所做的事。（有昼夜不睡觉不合眼的。）'),
('CUV', '传道书', 21, 8, 17, '我就看明神一切的作为，知道人查不出日光之下所做的事；任凭他费多少力寻查，都查不出来，就是智慧人虽想知道，也是查不出来。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '传道书', 21, 9, 1, '我将这一切事放在心上，详细考究，就知道义人和智慧人，并他们的作为都在神手中；或是爱，或是恨，都在他们的前面，人不能知道。'),
('CUV', '传道书', 21, 9, 2, '凡临到众人的事都是一样：义人和恶人都遭遇一样的事；好人，洁净人和不洁净人，献祭的与不献祭的，也是一样。好人如何，罪人也如何；起誓的如何，怕起誓的也如何。'),
('CUV', '传道书', 21, 9, 3, '在日光之下所行的一切事上有一件祸患，就是众人所遭遇的都是一样，并且世人的心充满了恶；活著的时候心里狂妄，后来就归死人那里去了。'),
('CUV', '传道书', 21, 9, 4, '与一切活人相连的，那人还有指望，因为活著的狗比死了的狮子更强。'),
('CUV', '传道书', 21, 9, 5, '活著的人知道必死；死了的人毫无所知，也不再得赏赐；他们的名无人记念。'),
('CUV', '传道书', 21, 9, 6, '他们的爱，他们的恨，他们的嫉妒，早都消灭了。在日光之下所行的一切事上，他们永不再有分了。'),
('CUV', '传道书', 21, 9, 7, '你只管去欢欢喜喜吃你的饭，心中快乐喝你的酒，因为神已经悦纳你的作为。'),
('CUV', '传道书', 21, 9, 8, '你的衣服当时常洁白，你头上也不要缺少膏油。'),
('CUV', '传道书', 21, 9, 9, '在你一生虚空的年日，就是神赐你在日光之下虚空的年日，当同你所爱的妻，快活度日，因为那是你生前在日光之下劳碌的事上所得的分。'),
('CUV', '传道书', 21, 9, 10, '凡你手所当做的事要尽力去做；因为在你所必去的阴间没有工作，没有谋算，没有知识，也没有智慧。'),
('CUV', '传道书', 21, 9, 11, '我又转念：见日光之下，快跑的未必能赢；力战的未必得胜；智慧的未必得粮食；明哲的未必得资财；灵巧的未必得喜悦。所临到众人的是在乎当时的机会。'),
('CUV', '传道书', 21, 9, 12, '原来人也不知道自己的定期。鱼被恶网圈住，鸟被网罗捉住，祸患忽然临到的时候，世人陷在其中也是如此。'),
('CUV', '传道书', 21, 9, 13, '我见日光之下有一样智慧，据我看乃是广大，'),
('CUV', '传道书', 21, 9, 14, '就是有一小城，其中的人数稀少，有大君王来攻击，修筑营垒，将城围困。'),
('CUV', '传道书', 21, 9, 15, '城中有一个贫穷的智慧人，他用智慧救了那城，却没有人记念那穷人。'),
('CUV', '传道书', 21, 9, 16, '我就说，智慧胜过勇力；然而那贫穷人的智慧被人藐视，他的话也无人听从。'),
('CUV', '传道书', 21, 9, 17, '宁可在安静之中听智慧人的言语，不听掌管愚昧人的喊声。'),
('CUV', '传道书', 21, 9, 18, '智慧胜过打仗的兵器；但一个罪人能败坏许多善事。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '传道书', 21, 10, 1, '死苍蝇使做香的膏油发出臭气；这样，一点愚昧也能败坏智慧和尊荣。'),
('CUV', '传道书', 21, 10, 2, '智慧人的心居右；愚昧人的心居左。'),
('CUV', '传道书', 21, 10, 3, '并且愚昧人行路显出无知，对众人说，他是愚昧人。'),
('CUV', '传道书', 21, 10, 4, '掌权者的心若向你发怒，不要离开你的本位，因为柔和能免大过。'),
('CUV', '传道书', 21, 10, 5, '我见日光之下有一件祸患，似乎出于掌权的错误，'),
('CUV', '传道书', 21, 10, 6, '就是愚昧人立在高位；富足人坐在低位。'),
('CUV', '传道书', 21, 10, 7, '我见过仆人骑马，王子像仆人在地上步行。'),
('CUV', '传道书', 21, 10, 8, '挖陷坑的，自己必掉在其中；拆墙垣的，必为蛇所咬。'),
('CUV', '传道书', 21, 10, 9, '凿开（或译：挪移）石头的，必受损伤；劈开木头的，必遭危险。'),
('CUV', '传道书', 21, 10, 10, '铁器钝了，若不将刃磨快，就必多费气力；但得智慧指教，便有益处。'),
('CUV', '传道书', 21, 10, 11, '未行法术以先，蛇若咬人，后行法术也是无益。'),
('CUV', '传道书', 21, 10, 12, '智慧人的口说出恩言；愚昧人的嘴吞灭自己。'),
('CUV', '传道书', 21, 10, 13, '他口中的言语起头是愚昧；他话的末尾是奸恶的狂妄。'),
('CUV', '传道书', 21, 10, 14, '愚昧人多有言语，人却不知将来有甚么事；他身后的事谁能告诉他呢？'),
('CUV', '传道书', 21, 10, 15, '凡愚昧人，他的劳碌使自己困乏，因为连进城的路，他也不知道。'),
('CUV', '传道书', 21, 10, 16, '邦国啊，你的王若是孩童，你的群臣早晨宴乐，你就有祸了！'),
('CUV', '传道书', 21, 10, 17, '邦国啊，你的王若是贵胄之子，你的群臣按时吃喝，为要补力，不为酒醉，你就有福了！'),
('CUV', '传道书', 21, 10, 18, '因人懒惰，房顶塌下；因人手懒，房屋滴漏。'),
('CUV', '传道书', 21, 10, 19, '设摆筵席是为喜笑。酒能使人快活；钱能叫万事应心。'),
('CUV', '传道书', 21, 10, 20, '你不可咒诅君王，也不可心怀此念；在你卧房也不可咒诅富户。因为空中的鸟必传扬这声音，有翅膀的也必述说这事。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '传道书', 21, 11, 1, '当将你的粮食撒在水面，因为日久必能得著。'),
('CUV', '传道书', 21, 11, 2, '你要分给七人，或分给八人，因为你不知道将来有甚么灾祸临到地上。'),
('CUV', '传道书', 21, 11, 3, '云若满了雨，就必倾倒在地上。树若向南倒，或向北倒，树倒在何处，就存在何处。'),
('CUV', '传道书', 21, 11, 4, '看风的，必不撒种；望云的，必不收割。'),
('CUV', '传道书', 21, 11, 5, '风从何道来，骨头在怀孕妇人的胎中如何长成，你尚且不得知道；这样，行万事之神的作为，你更不得知道。'),
('CUV', '传道书', 21, 11, 6, '早晨要撒你的种，晚上也不要歇你的手，因为你不知道哪一样发旺；或是早撒的，或是晚撒的，或是两样都好。'),
('CUV', '传道书', 21, 11, 7, '光本是佳美的，眼见日光也是可悦的。'),
('CUV', '传道书', 21, 11, 8, '人活多年，就当快乐多年；然而也当想到黑暗的日子。因为这日子必多，所要来的都是虚空。'),
('CUV', '传道书', 21, 11, 9, '少年人哪，你在幼年时当快乐。在幼年的日子，使你的心欢畅，行你心所愿行的，看你眼所爱看的；却要知道，为这一切的事，神必审问你。'),
('CUV', '传道书', 21, 11, 10, '所以，你当从心中除掉愁烦，从肉体克去邪恶；因为一生的开端和幼年之时，都是虚空的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '传道书', 21, 12, 1, '你趁著年幼、衰败的日子尚未来到，就是你所说，我毫无喜乐的那些年日未曾临近之先，当记念造你的主。'),
('CUV', '传道书', 21, 12, 2, '不要等到日头、光明、月亮、星宿变为黑暗，雨后云彩反回，'),
('CUV', '传道书', 21, 12, 3, '看守房屋的发颤，有力的屈身，推磨的稀少就止息，从窗户往外看的都昏暗；'),
('CUV', '传道书', 21, 12, 4, '街门关闭，推磨的响声微小，雀鸟一叫，人就起来，唱歌的女子也都衰微。'),
('CUV', '传道书', 21, 12, 5, '人怕高处，路上有惊慌，杏树开花，蚱蜢成为重担，人所愿的也都废掉；因为人归他永远的家，吊丧的在街上往来。'),
('CUV', '传道书', 21, 12, 6, '银链折断，金罐破裂，瓶子在泉旁损坏，水轮在井口破烂，'),
('CUV', '传道书', 21, 12, 7, '尘土仍归于地，灵仍归于赐灵的神。'),
('CUV', '传道书', 21, 12, 8, '传道者说：虚空的虚空，凡事都是虚空。'),
('CUV', '传道书', 21, 12, 9, '再者，传道者因有智慧，仍将知识教训众人；又默想，又考查，又陈说许多箴言。'),
('CUV', '传道书', 21, 12, 10, '传道者专心寻求可喜悦的言语，是凭正直写的诚实话。'),
('CUV', '传道书', 21, 12, 11, '智慧人的言语好像刺棍；会中之师的言语又像钉稳的钉子，都是一个牧者所赐的。'),
('CUV', '传道书', 21, 12, 12, '我儿，还有一层，你当受劝戒：著书多，没有穷尽；读书多，身体疲倦。'),
('CUV', '传道书', 21, 12, 13, '这些事都已听见了，总意就是：敬畏神，谨守他的诫命，这是人所当尽的本分（或译：这是众人的本分）。'),
('CUV', '传道书', 21, 12, 14, '因为人所做的事，连一切隐藏的事，无论是善是恶，神都必审问。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '雅歌', 22, 1, 1, '所罗门的歌，是歌中的雅歌。（新娘）'),
('CUV', '雅歌', 22, 1, 2, '愿他用口与我亲嘴；因你的爱情比酒更美。'),
('CUV', '雅歌', 22, 1, 3, '你的膏油馨香；你的名如同倒出来的香膏，所以众童女都爱你。'),
('CUV', '雅歌', 22, 1, 4, '愿你吸引我，我们就快跑跟随你。王带我进了内室，我们必因你欢喜快乐。我们要称赞你的爱情，胜似称赞美酒。他们爱你是理所当然的。'),
('CUV', '雅歌', 22, 1, 5, '耶路撒冷的众女子啊，我虽然黑，却是秀美，如同基达的帐棚，好像所罗门的幔子。'),
('CUV', '雅歌', 22, 1, 6, '不要因日头把我晒黑了就轻看我。我同母的弟兄向我发怒，他们使我看守葡萄园；我自己的葡萄园却没有看守。'),
('CUV', '雅歌', 22, 1, 7, '我心所爱的啊，求你告诉我，你在何处牧羊？晌午在何处使羊歇卧？我何必在你同伴的羊群旁边好像蒙著脸的人呢？（新郎）'),
('CUV', '雅歌', 22, 1, 8, '你这女子中极美丽的，你若不知道，只管跟随羊群的脚踪去，把你的山羊羔牧放在牧人帐棚的旁边。'),
('CUV', '雅歌', 22, 1, 9, '我的佳偶，我将你比法老车上套的骏马。'),
('CUV', '雅歌', 22, 1, 10, '你的两腮因发辫而秀美；你的颈项因珠串而华丽。'),
('CUV', '雅歌', 22, 1, 11, '我们要为你编上金辫，镶上银钉。（新娘）'),
('CUV', '雅歌', 22, 1, 12, '王正坐席的时候，我的哪哒香膏发出香味。'),
('CUV', '雅歌', 22, 1, 13, '我以我的良人为一袋没药，常在我怀中。'),
('CUV', '雅歌', 22, 1, 14, '我以我的良人为一棵凤仙花，在隐基底葡萄园中。（新郎）'),
('CUV', '雅歌', 22, 1, 15, '我的佳偶，你甚美丽！你甚美丽！你的眼好像鸽子眼。（新娘）'),
('CUV', '雅歌', 22, 1, 16, '我的良人哪，你甚美丽可爱！我们以青草为床榻，'),
('CUV', '雅歌', 22, 1, 17, '以香柏树为房屋的栋梁，以松树为椽子。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '雅歌', 22, 2, 1, '我是沙仑的玫瑰花（或译：水仙花），是谷中的百合花。（新郎）'),
('CUV', '雅歌', 22, 2, 2, '我的佳偶在女子中，好像百合花在荆棘内。（新娘）'),
('CUV', '雅歌', 22, 2, 3, '我的良人在男子中，如同苹果树在树林中。我欢欢喜喜坐在他的荫下，尝他果子的滋味，觉得甘甜。'),
('CUV', '雅歌', 22, 2, 4, '他带我入筵宴所，以爱为旗在我以上。'),
('CUV', '雅歌', 22, 2, 5, '求你们给我葡萄干增补我力，给我苹果畅快我心，因我思爱成病。'),
('CUV', '雅歌', 22, 2, 6, '他的左手在我头下；他的右手将我抱住。'),
('CUV', '雅歌', 22, 2, 7, '耶路撒冷的众女子啊，我指著羚羊或田野的母鹿嘱咐你们：不要惊动、不要叫醒我所亲爱的，等他自己情愿（不要叫醒……情愿：或译不要激动爱情，等他自发）。'),
('CUV', '雅歌', 22, 2, 8, '听啊！是我良人的声音；看哪！他蹿山越岭而来。'),
('CUV', '雅歌', 22, 2, 9, '我的良人好像羚羊，或像小鹿。他站在我们墙壁后，从窗户往里观看，从窗櫺往里窥探。'),
('CUV', '雅歌', 22, 2, 10, '我良人对我说：（新郎）我的佳偶，我的美人，起来，与我同去！'),
('CUV', '雅歌', 22, 2, 11, '因为冬天已往，雨水止住过去了。'),
('CUV', '雅歌', 22, 2, 12, '地上百花开放，百鸟鸣叫的时候（或译：修理葡萄树的时候）已经来到；斑鸠的声音在我们境内也听见了。'),
('CUV', '雅歌', 22, 2, 13, '无花果树的果子渐渐成熟；葡萄树开花放香。我的佳偶，我的美人，起来，与我同去！'),
('CUV', '雅歌', 22, 2, 14, '我的鸽子啊，你在磐石穴中，在陡岩的隐密处。求你容我得见你的面貌，得听你的声音；因为你的声音柔和，你的面貌秀美。'),
('CUV', '雅歌', 22, 2, 15, '要给我们擒拿狐狸，就是毁坏葡萄园的小狐狸，因为我们的葡萄正在开花。（新娘）'),
('CUV', '雅歌', 22, 2, 16, '良人属我，我也属他；他在百合花中牧放群羊。'),
('CUV', '雅歌', 22, 2, 17, '我的良人哪，求你等到天起凉风、日影飞去的时候，你要转回，好像羚羊，或像小鹿在比特山上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '雅歌', 22, 3, 1, '我夜间躺卧在床上，寻找我心所爱的；我寻找他，却寻不见。'),
('CUV', '雅歌', 22, 3, 2, '我说：我要起来，游行城中，在街市上，在宽阔处，寻找我心所爱的。我寻找他，却寻不见。'),
('CUV', '雅歌', 22, 3, 3, '城中巡逻看守的人遇见我；我问他们：你们看见我心所爱的没有？'),
('CUV', '雅歌', 22, 3, 4, '我刚离开他们就遇见我心所爱的。我拉住他，不容他走，领他入我母家，到怀我者的内室。'),
('CUV', '雅歌', 22, 3, 5, '耶路撒冷的众女子啊，我指著羚羊或田野的母鹿嘱咐你们：不要惊动、不要叫醒我所亲爱的，等他自己情愿（不要叫醒……情愿：或译不要激动爱情，等他自发）。'),
('CUV', '雅歌', 22, 3, 6, '那从旷野上来、形状如烟柱、以没药和乳香并商人各样香粉薰的是谁呢？'),
('CUV', '雅歌', 22, 3, 7, '看哪，是所罗门的轿；四围有六十个勇士，都是以色列中的勇士；'),
('CUV', '雅歌', 22, 3, 8, '手都持刀，善于争战，腰间佩刀，防备夜间有惊慌。'),
('CUV', '雅歌', 22, 3, 9, '所罗门王用利巴嫩木为自己制造一乘华轿。'),
('CUV', '雅歌', 22, 3, 10, '轿柱是用银做的，轿底是用金做的；坐垫是紫色的，其中所铺的乃耶路撒冷众女子的爱情。'),
('CUV', '雅歌', 22, 3, 11, '锡安的众女子啊，你们出去观看所罗门王！头戴冠冕，就是在他婚筵的日子、心中喜乐的时候，他母亲给他戴上的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '雅歌', 22, 4, 1, '我的佳偶，你甚美丽！你甚美丽！你的眼在帕子内好像鸽子眼。你的头发如同山羊群卧在基列山旁。'),
('CUV', '雅歌', 22, 4, 2, '你的牙齿如新剪毛的一群母羊，洗净上来，个个都有双生，没有一只丧掉子的。'),
('CUV', '雅歌', 22, 4, 3, '你的唇好像一条朱红线；你的嘴也秀美。你的两太阳在帕子内，如同一块石榴。'),
('CUV', '雅歌', 22, 4, 4, '你的颈项好像大卫建造收藏军器的高台，其上悬挂一千盾牌，都是勇士的籐牌。'),
('CUV', '雅歌', 22, 4, 5, '你的两乳好像百合花中吃草的一对小鹿，就是母鹿双生的。'),
('CUV', '雅歌', 22, 4, 6, '我要往没药山和乳香冈去，直等到天起凉风、日影飞去的时候回来。'),
('CUV', '雅歌', 22, 4, 7, '我的佳偶，你全然美丽，毫无瑕疵！'),
('CUV', '雅歌', 22, 4, 8, '我的新妇，求你与我一同离开利巴嫩，与我一同离开利巴嫩。从亚玛拿顶，从示尼珥与黑门顶，从有狮子的洞，从有豹子的山往下观看。'),
('CUV', '雅歌', 22, 4, 9, '我妹子，我新妇，你夺了我的心。你用眼一看，用你项上的一条金链，夺了我的心！'),
('CUV', '雅歌', 22, 4, 10, '我妹子，我新妇，你的爱情何其美！你的爱情比酒更美！你膏油的香气胜过一切香品！'),
('CUV', '雅歌', 22, 4, 11, '我新妇，你的嘴唇滴蜜，好像蜂房滴蜜；你的舌下有蜜，有奶。你衣服的香气如利巴嫩的香气。'),
('CUV', '雅歌', 22, 4, 12, '我妹子，我新妇，乃是关锁的园，禁闭的井，封闭的泉源。'),
('CUV', '雅歌', 22, 4, 13, '你园内所种的结了石榴，有佳美的果子，并凤仙花与哪哒树。'),
('CUV', '雅歌', 22, 4, 14, '有哪哒和番红花，菖蒲和桂树，并各样乳香木、没药、沉香，与一切上等的果品。'),
('CUV', '雅歌', 22, 4, 15, '你是园中的泉，活水的井，从利巴嫩流下来的溪水。（新娘）'),
('CUV', '雅歌', 22, 4, 16, '北风啊，兴起！南风啊，吹来！吹在我的园内，使其中的香气发出来。愿我的良人进入自己园里，吃他佳美的果子。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '雅歌', 22, 5, 1, '我妹子，我新妇，我进了我的园中，采了我的没药和香料，吃了我的蜜房和蜂蜜，喝了我的酒和奶。（耶路撒冷的众女子）我的朋友们，请吃！我所亲爱的，请喝，且多多地喝！'),
('CUV', '雅歌', 22, 5, 2, '我身睡卧，我心却醒。这是我良人的声音；他敲门说：（新郎）我的妹子，我的佳偶，我的鸽子，我的完全人，求你给我开门；因我的头满了露水，我的头发被夜露滴湿。（新娘）'),
('CUV', '雅歌', 22, 5, 3, '我回答说：我脱了衣裳，怎能再穿上呢？我洗了脚，怎能再玷污呢？'),
('CUV', '雅歌', 22, 5, 4, '我的良人从门孔里伸进手来，我便因他动了心。'),
('CUV', '雅歌', 22, 5, 5, '我起来，要给我良人开门。我的两手滴下没药；我的指头有没药汁滴在门闩上。'),
('CUV', '雅歌', 22, 5, 6, '我给我的良人开了门；我的良人却已转身走了。他说话的时候，我神不守舍；我寻找他，竟寻不见；我呼叫他，他却不回答。'),
('CUV', '雅歌', 22, 5, 7, '城中巡逻看守的人遇见我，打了我，伤了我；看守城墙的人夺去我的披肩。'),
('CUV', '雅歌', 22, 5, 8, '耶路撒冷的众女子啊，我嘱咐你们：若遇见我的良人，要告诉他，我因思爱成病。（耶路撒冷的众女子）'),
('CUV', '雅歌', 22, 5, 9, '你这女子中极美丽的，你的良人比别人的良人有何强处？你的良人比别人的良人有何强处，你就这样嘱咐我们？（新娘）'),
('CUV', '雅歌', 22, 5, 10, '我的良人白而且红，超乎万人之上。'),
('CUV', '雅歌', 22, 5, 11, '他的头像至精的金子；他的头发厚密累垂，黑如乌鸦。'),
('CUV', '雅歌', 22, 5, 12, '他的眼如溪水旁的鸽子眼，用奶洗净，安得合式。'),
('CUV', '雅歌', 22, 5, 13, '他的两腮如香花畦，如香草台；他的嘴唇像百合花，且滴下没药汁。'),
('CUV', '雅歌', 22, 5, 14, '他的两手好像金管，镶嵌水苍玉；他的身体如同雕刻的象牙，周围镶嵌蓝宝石。'),
('CUV', '雅歌', 22, 5, 15, '他的腿好像白玉石柱，安在精金座上；他的形状如利巴嫩，且佳美如香柏树。'),
('CUV', '雅歌', 22, 5, 16, '他的口极其甘甜；他全然可爱。耶路撒冷的众女子啊，这是我的良人；这是我的朋友。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '雅歌', 22, 6, 1, '你这女子中极美丽的，你的良人往何处去了？你的良人转向何处去了，我们好与你同去寻找他。（新娘）'),
('CUV', '雅歌', 22, 6, 2, '我的良人下入自己园中，到香花畦，在园内牧放群羊，采百合花。'),
('CUV', '雅歌', 22, 6, 3, '我属我的良人，我的良人也属我；他在百合花中牧放群羊。'),
('CUV', '雅歌', 22, 6, 4, '我的佳偶啊，你美丽如得撒，秀美如耶路撒冷，威武如展开旌旗的军队。'),
('CUV', '雅歌', 22, 6, 5, '求你掉转眼目不看我，因你的眼目使我惊乱。你的头发如同山羊群卧在基列山旁。'),
('CUV', '雅歌', 22, 6, 6, '你的牙齿如一群母羊洗净上来，个个都有双生，没有一只丧掉子的。'),
('CUV', '雅歌', 22, 6, 7, '你的两太阳在帕子内，如同一块石榴。'),
('CUV', '雅歌', 22, 6, 8, '有六十王后八十妃嫔，并有无数的童女。'),
('CUV', '雅歌', 22, 6, 9, '我的鸽子，我的完全人，只有这一个是他母亲独生的，是生养他者所宝爱的。众女子见了就称他有福；王后妃嫔见了也赞美他。'),
('CUV', '雅歌', 22, 6, 10, '那向外观看、如晨光发现、美丽如月亮、皎洁如日头、威武如展开旌旗军队的是谁呢？'),
('CUV', '雅歌', 22, 6, 11, '我下入核桃园，要看谷中青绿的植物，要看葡萄发芽没有，石榴开花没有。'),
('CUV', '雅歌', 22, 6, 12, '不知不觉，我的心将我安置在我尊长的车中。（耶路撒冷的众女子）'),
('CUV', '雅歌', 22, 6, 13, '回来，回来，书拉密女；你回来，你回来，使我们得观看你。（新娘）你们为何要观看书拉密女，像观看玛哈念跳舞的呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '雅歌', 22, 7, 1, '王女啊，你的脚在鞋中何其美好！你的大腿圆润，好像美玉，是巧匠的手做成的。'),
('CUV', '雅歌', 22, 7, 2, '你的肚脐如圆杯，不缺调和的酒；你的腰如一堆麦子，周围有百合花。'),
('CUV', '雅歌', 22, 7, 3, '你的两乳好像一对小鹿，就是母鹿双生的。'),
('CUV', '雅歌', 22, 7, 4, '你的颈项如象牙台；你的眼目像希实本、巴特拉并门旁的水池；你的鼻子仿佛朝大马色的利巴嫩塔。'),
('CUV', '雅歌', 22, 7, 5, '你的头在你身上好像迦密山；你头上的发是紫黑色；王的心因这下垂的发绺系住了。'),
('CUV', '雅歌', 22, 7, 6, '我所爱的，你何其美好！何其可悦，使人欢畅喜乐！'),
('CUV', '雅歌', 22, 7, 7, '你的身量好像棕树；你的两乳如同其上的果子，累累下垂。'),
('CUV', '雅歌', 22, 7, 8, '我说：我要上这棕树，抓住枝子。愿你的两乳好像葡萄累累下垂，你鼻子的气味香如苹果；'),
('CUV', '雅歌', 22, 7, 9, '你的口如上好的酒。（新娘）女子说：为我的良人下咽舒畅，流入睡觉人的嘴中。'),
('CUV', '雅歌', 22, 7, 10, '我属我的良人，他也恋慕我。'),
('CUV', '雅歌', 22, 7, 11, '我的良人，来吧！你我可以往田间去；你我可以在村庄住宿。'),
('CUV', '雅歌', 22, 7, 12, '我们早晨起来往葡萄园去，看看葡萄发芽开花没有，石榴放蕊没有；我在那里要将我的爱情给你。'),
('CUV', '雅歌', 22, 7, 13, '风茄放香，在我们的门内有各样新陈佳美的果子；我的良人，这都是我为你存留的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '雅歌', 22, 8, 1, '巴不得你像我的兄弟，像吃我母亲奶的兄弟；我在外头遇见你就与你亲嘴，谁也不轻看我。'),
('CUV', '雅歌', 22, 8, 2, '我必引导你，领你进我母亲的家；我可以领受教训，也就使你喝石榴汁酿的香酒。'),
('CUV', '雅歌', 22, 8, 3, '他的左手必在我头下；他的右手必将我抱住。'),
('CUV', '雅歌', 22, 8, 4, '耶路撒冷的众女子啊，我嘱咐你们：不要惊动、不要叫醒我所亲爱的，等他自己情愿（不要叫醒……情愿：或译不要激动爱情，等他自发）。'),
('CUV', '雅歌', 22, 8, 5, '那靠著良人从旷野上来是谁呢？（新娘）我在苹果树下叫醒你。你母亲在的那里为你劬劳；生养你的在那里为你劬劳。'),
('CUV', '雅歌', 22, 8, 6, '求你将我放在你心上如印记，带在你臂上如戳记。因为爱情如死之坚强，嫉恨如阴间之残忍；所发的电光是火焰的电光，是耶和华的烈焰。'),
('CUV', '雅歌', 22, 8, 7, '爱情，众水不能息灭，大水也不能淹没。若有人拿家中所有的财宝要换爱情，就全被藐视。（新娘的兄弟）'),
('CUV', '雅歌', 22, 8, 8, '我们有一小妹；他的两乳尚未长成，人来提亲的日子，我们当为他怎样办理？'),
('CUV', '雅歌', 22, 8, 9, '他若是墙，我们要在其上建造银塔；他若是门，我们要用香柏木板围护他。（新娘）'),
('CUV', '雅歌', 22, 8, 10, '我是墙；我两乳像其上的楼。那时，我在他眼中像得平安的人。（新郎）'),
('CUV', '雅歌', 22, 8, 11, '所罗门在巴力哈们有一葡萄园；他将这葡萄园交给看守的人，为其中的果子必交一千舍客勒银子。'),
('CUV', '雅歌', 22, 8, 12, '我自己的葡萄园在我面前。所罗门哪，一千舍客勒归你，二百舍客勒归看守果子的人。'),
('CUV', '雅歌', 22, 8, 13, '你这住在园中的，同伴都要听你的声音，求你使我也得听见。（新娘）'),
('CUV', '雅歌', 22, 8, 14, '我的良人哪，求你快来！如羚羊或小鹿在香草山上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 1, 1, '当乌西雅、约坦、亚哈斯、希西家作犹大王的时候，亚摩斯的儿子以赛亚得默示，论到犹大和耶路撒冷。'),
('CUV', '以赛亚书', 23, 1, 2, '天哪，要听！地啊，侧耳而听！因为耶和华说：我养育儿女，将他们养大，他们竟悖逆我。'),
('CUV', '以赛亚书', 23, 1, 3, '牛认识主人，驴认识主人的槽，以色列却不认识；我的民却不留意。'),
('CUV', '以赛亚书', 23, 1, 4, '嗐！犯罪的国民，担著罪孽的百姓；行恶的种类，败坏的儿女！他们离弃耶和华，藐视以色列的圣者，与他生疏，往后退步。'),
('CUV', '以赛亚书', 23, 1, 5, '你们为甚么屡次悖逆，还要受责打吗？你们已经满头疼痛，全心发昏。'),
('CUV', '以赛亚书', 23, 1, 6, '从脚掌到头顶，没有一处完全的，尽是伤口、青肿，与新打的伤痕，都没有收口，没有缠裹，也没有用膏滋润。'),
('CUV', '以赛亚书', 23, 1, 7, '你们的地土已经荒凉；你们的城邑被火焚毁。你们的田地在你们眼前为外邦人所侵吞，既被外邦人倾覆就成为荒凉。'),
('CUV', '以赛亚书', 23, 1, 8, '仅存锡安城（原文是女子），好像葡萄园的草棚，瓜田的茅屋，被围困的城邑。'),
('CUV', '以赛亚书', 23, 1, 9, '若不是万军之耶和华给我们稍留余种，我们早已像所多玛、蛾摩拉的样子了。'),
('CUV', '以赛亚书', 23, 1, 10, '你们这所多玛的官长啊，要听耶和华的话！你们这蛾摩拉的百姓啊，要侧耳听我们神的训诲！'),
('CUV', '以赛亚书', 23, 1, 11, '耶和华说：你们所献的许多祭物与我何益呢？公绵羊的燔祭和肥畜的脂油，我已经够了；公牛的血，羊羔的血，公山羊的血，我都不喜悦。'),
('CUV', '以赛亚书', 23, 1, 12, '你们来朝见我，谁向你们讨这些，使你们践踏我的院宇呢？'),
('CUV', '以赛亚书', 23, 1, 13, '你们不要再献虚浮的供物。香品是我所憎恶的；月朔和安息日，并宣召的大会，也是我所憎恶的；作罪孽，又守严肃会，我也不能容忍。'),
('CUV', '以赛亚书', 23, 1, 14, '你们的月朔和节期，我心里恨恶，我都以为麻烦；我担当，便不耐烦。'),
('CUV', '以赛亚书', 23, 1, 15, '你们举手祷告，我必遮眼不看；就是你们多多地祈祷，我也不听。你们的手都满了杀人的血。'),
('CUV', '以赛亚书', 23, 1, 16, '你们要洗濯、自洁，从我眼前除掉你们的恶行，要止住作恶，'),
('CUV', '以赛亚书', 23, 1, 17, '学习行善，寻求公平，解救受欺压的；给孤儿伸冤，为寡妇辨屈。'),
('CUV', '以赛亚书', 23, 1, 18, '耶和华说：你们来，我们彼此辩论。你们的罪虽像朱红，必变成雪白；虽红如丹颜，必白如羊毛。'),
('CUV', '以赛亚书', 23, 1, 19, '你们若甘心听从，必吃地上的美物，'),
('CUV', '以赛亚书', 23, 1, 20, '若不听从，反倒悖逆，必被刀剑吞灭。这是耶和华亲口说的。'),
('CUV', '以赛亚书', 23, 1, 21, '可叹，忠信的城变为妓女！从前充满了公平，公义居在其中，现今却有凶手居住。'),
('CUV', '以赛亚书', 23, 1, 22, '你的银子变为渣滓；你的酒用水搀对。'),
('CUV', '以赛亚书', 23, 1, 23, '你的官长居心悖逆，与盗贼作伴，各都喜爱贿赂，追求赃私。他们不为孤儿伸冤；寡妇的案件也不得呈到他们面前。'),
('CUV', '以赛亚书', 23, 1, 24, '因此，主─万军之耶和华、以色列的大能者说：哎！我要向我的对头雪恨，向我的敌人报仇。'),
('CUV', '以赛亚书', 23, 1, 25, '我必反手加在你身上，炼尽你的渣滓，除净你的杂质。'),
('CUV', '以赛亚书', 23, 1, 26, '我也必复还你的审判官，像起初一样，复还你的谋士，像起先一般。然后，你必称为公义之城，忠信之邑。'),
('CUV', '以赛亚书', 23, 1, 27, '锡安必因公平得蒙救赎；其中归正的人必因公义得蒙救赎。'),
('CUV', '以赛亚书', 23, 1, 28, '但悖逆的和犯罪的必一同败亡；离弃耶和华的必致消灭。'),
('CUV', '以赛亚书', 23, 1, 29, '那等人必因你们所喜爱的橡树抱愧；你们必因所选择的园子蒙羞。'),
('CUV', '以赛亚书', 23, 1, 30, '因为，你们必如叶子枯干的橡树，好像无水浇灌的园子。'),
('CUV', '以赛亚书', 23, 1, 31, '有权势的必如麻瓤；他的工作好像火星，都要一同焚毁，无人扑灭。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 2, 1, '亚摩斯的儿子以赛亚得默示，论到犹大和耶路撒冷。'),
('CUV', '以赛亚书', 23, 2, 2, '末后的日子，耶和华殿的山必坚立，超乎诸山，高举过于万岭；万民都要流归这山。'),
('CUV', '以赛亚书', 23, 2, 3, '必有许多国的民前往，说：来吧，我们登耶和华的山，奔雅各神的殿。主必将他的道教训我们；我们也要行他的路。因为训诲必出于锡安；耶和华的言语必出于耶路撒冷。'),
('CUV', '以赛亚书', 23, 2, 4, '他必在列国中施行审判，为许多国民断定是非。他们要将刀打成犁头，把枪打成镰刀。这国不举刀攻击那国；他们也不再学习战事。'),
('CUV', '以赛亚书', 23, 2, 5, '雅各家啊，来吧！我们在耶和华的光明中行走。'),
('CUV', '以赛亚书', 23, 2, 6, '耶和华，你离弃了你百姓雅各家，是因他们充满了东方的风俗，作观兆的，像非利士人一样，并与外邦人击掌。'),
('CUV', '以赛亚书', 23, 2, 7, '他们的国满了金银，财宝也无穷；他们的地满了马匹，车辆也无数。'),
('CUV', '以赛亚书', 23, 2, 8, '他们的地满了偶像；他们跪拜自己手所造的，就是自己指头所做的。'),
('CUV', '以赛亚书', 23, 2, 9, '卑贱人屈膝；尊贵人下跪；所以不可饶恕他们。'),
('CUV', '以赛亚书', 23, 2, 10, '你当进入岩穴，藏在土中，躲避耶和华的惊吓和他威严的荣光。'),
('CUV', '以赛亚书', 23, 2, 11, '到那日，眼目高傲的必降为卑；性情狂傲的都必屈膝；惟独耶和华被尊崇。'),
('CUV', '以赛亚书', 23, 2, 12, '必有万军耶和华降罚的一个日子，要临到骄傲狂妄的；一切自高的都必降为卑；'),
('CUV', '以赛亚书', 23, 2, 13, '又临到利巴嫩高大的香柏树和巴珊的橡树；'),
('CUV', '以赛亚书', 23, 2, 14, '又临到一切高山的峻岭；'),
('CUV', '以赛亚书', 23, 2, 15, '又临到高台和坚固城墙；'),
('CUV', '以赛亚书', 23, 2, 16, '又临到他施的船只并一切可爱的美物。'),
('CUV', '以赛亚书', 23, 2, 17, '骄傲的必屈膝；狂妄的必降卑。在那日，惟独耶和华被尊崇；'),
('CUV', '以赛亚书', 23, 2, 18, '偶像必全然废弃。'),
('CUV', '以赛亚书', 23, 2, 19, '耶和华兴起，使地大震动的时候，人就进入石洞，进入土穴，躲避耶和华的惊吓和他威严的荣光。'),
('CUV', '以赛亚书', 23, 2, 20, '到那日，人必将为拜而造的金偶像、银偶像抛给田鼠和蝙蝠。'),
('CUV', '以赛亚书', 23, 2, 21, '到耶和华兴起，使地大震动的时候，人好进入磐石洞中和岩石穴里，躲避耶和华的惊吓和他威严的荣光。'),
('CUV', '以赛亚书', 23, 2, 22, '你们休要倚靠世人。他鼻孔里不过有气息；他在一切事上可算甚么呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 3, 1, '主─万军之耶和华从耶路撒冷和犹大，除掉众人所倚靠的，所仗赖的，就是所倚靠的粮，所仗赖的水；'),
('CUV', '以赛亚书', 23, 3, 2, '除掉勇士和战士，审判官和先知，占卜的和长老，'),
('CUV', '以赛亚书', 23, 3, 3, '五十夫长和尊贵人，谋士和有巧艺的，以及妙行法术的。'),
('CUV', '以赛亚书', 23, 3, 4, '主说：我必使孩童作他们的首领，使婴孩辖管他们。'),
('CUV', '以赛亚书', 23, 3, 5, '百姓要彼此欺压；各人受邻舍的欺压。少年人必侮慢老年人；卑贱人必侮慢尊贵人。'),
('CUV', '以赛亚书', 23, 3, 6, '人在父家拉住弟兄，说：你有衣服，可以作我们的官长。这败落的事归在你手下吧！'),
('CUV', '以赛亚书', 23, 3, 7, '那时，他必扬声说：我不作医治你们的人；因我家中没有粮食，也没有衣服，你们不可立我作百姓的官长。'),
('CUV', '以赛亚书', 23, 3, 8, '耶路撒冷败落，犹大倾倒；因为他们的舌头和行为与耶和华反对，惹了他荣光的眼目。'),
('CUV', '以赛亚书', 23, 3, 9, '他们的面色证明自己的不正；他们述说自己的罪恶，并不隐瞒，好像所多玛一样。他们有祸了！因为作恶自害。'),
('CUV', '以赛亚书', 23, 3, 10, '你们要论义人说：他必享福乐，因为要吃自己行为所结的果子。'),
('CUV', '以赛亚书', 23, 3, 11, '恶人有祸了！他必遭灾难！因为要照自己手所行的受报应。'),
('CUV', '以赛亚书', 23, 3, 12, '至于我的百姓，孩童欺压他们，妇女辖管他们。我的百姓啊，引导你的使你走错，并毁坏你所行的道路。'),
('CUV', '以赛亚书', 23, 3, 13, '耶和华起来辩论，站著审判众民。'),
('CUV', '以赛亚书', 23, 3, 14, '耶和华必审问他民中的长老和首领，说：吃尽葡萄园果子的就是你们；向贫穷人所夺的都在你们家中。'),
('CUV', '以赛亚书', 23, 3, 15, '主─万军之耶和华说：你们为何压制我的百姓，搓磨贫穷人的脸呢？'),
('CUV', '以赛亚书', 23, 3, 16, '耶和华又说：因为锡安的女子狂傲，行走挺项，卖弄眼目，俏步徐行，脚下玎珰，'),
('CUV', '以赛亚书', 23, 3, 17, '所以，主必使锡安的女子头长秃疮；耶和华又使他们赤露下体。'),
('CUV', '以赛亚书', 23, 3, 18, '到那日，主必除掉他们华美的脚钏、发网、月牙圈、'),
('CUV', '以赛亚书', 23, 3, 19, '耳环、手镯、蒙脸的帕子、'),
('CUV', '以赛亚书', 23, 3, 20, '华冠、足炼、华带、香盒、符囊、'),
('CUV', '以赛亚书', 23, 3, 21, '戒指、鼻环、'),
('CUV', '以赛亚书', 23, 3, 22, '吉服、外套、云肩、荷包、'),
('CUV', '以赛亚书', 23, 3, 23, '手镜、细麻衣、裹头巾、蒙身的帕子。'),
('CUV', '以赛亚书', 23, 3, 24, '必有臭烂代替馨香，绳子代替腰带，光秃代替美发，麻衣系腰代替华服，烙伤代替美容。'),
('CUV', '以赛亚书', 23, 3, 25, '你的男丁必倒在刀下；你的勇士必死在阵上。'),
('CUV', '以赛亚书', 23, 3, 26, '锡安（原文是他）的城门必悲伤、哀号；他必荒凉坐在地上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 4, 1, '在那日，七个女人必拉住一个男人，说：我们吃自己的食物，穿自己的衣服，但求你许我们归你名下；求你除掉我们的羞耻。'),
('CUV', '以赛亚书', 23, 4, 2, '到那日，耶和华发生的苗必华美尊荣，地的出产必为以色列逃脱的人显为荣华茂盛。'),
('CUV', '以赛亚书', 23, 4, 3, '主以公义的灵和焚烧的灵，将锡安女子的污秽洗去，又将耶路撒冷中杀人的血除净。那时，剩在锡安、留在耶路撒冷的，就是一切住耶路撒冷、在生命册上记名的，必称为圣。'),
('CUV', '以赛亚书', 23, 4, 4, 'a'),
('CUV', '以赛亚书', 23, 4, 5, '耶和华也必在锡安全山，并各会众以上，使白日有烟云，黑夜有火燄的光。因为在全荣耀之上必有遮蔽。'),
('CUV', '以赛亚书', 23, 4, 6, '必有亭子，白日可以得荫避暑，也可以作为藏身之处，躲避狂风暴雨。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 5, 1, '我要为我所亲爱的唱歌，是我所爱者的歌，论他葡萄园的事：我所亲爱的有葡萄园在肥美的山冈上。'),
('CUV', '以赛亚书', 23, 5, 2, '他刨挖园子，捡去石头，栽种上等的葡萄树，在园中盖了一座楼，又凿出压酒池；指望结好葡萄，反倒结了野葡萄。'),
('CUV', '以赛亚书', 23, 5, 3, '耶路撒冷的居民和犹大人哪，请你们现今在我与我的葡萄园中，断定是非。'),
('CUV', '以赛亚书', 23, 5, 4, '我为我葡萄园所做之外，还有甚么可做的呢？我指望结好葡萄，怎么倒结了野葡萄呢？'),
('CUV', '以赛亚书', 23, 5, 5, '现在我告诉你们，我要向我葡萄园怎样行：我必撤去篱笆，使他被吞灭，拆毁墙垣，使他被践踏。'),
('CUV', '以赛亚书', 23, 5, 6, '我必使他荒废，不再修理，不再锄刨，荆棘蒺藜倒要生长。我也必命云不降雨在其上。'),
('CUV', '以赛亚书', 23, 5, 7, '万军之耶和华的葡萄园就是以色列家；他所喜爱的树就是犹大人。他指望的是公平，谁知倒有暴虐（或译：倒流人血）；指望的是公义，谁知倒有冤声。'),
('CUV', '以赛亚书', 23, 5, 8, '祸哉！那些以房接房，以地连地，以致不留余地的，只顾自己独居境内。'),
('CUV', '以赛亚书', 23, 5, 9, '我耳闻万军之耶和华说：必有许多又大又美的房屋成为荒凉，无人居住。'),
('CUV', '以赛亚书', 23, 5, 10, '三十亩葡萄园只出一罢特酒；一贺梅珥谷种只结一伊法粮食。'),
('CUV', '以赛亚书', 23, 5, 11, '祸哉！那些清早起来追求浓酒，留连到夜深，甚至因酒发烧的人。'),
('CUV', '以赛亚书', 23, 5, 12, '他们在筵席上弹琴，鼓瑟，击鼓，吹笛，饮酒，却不顾念耶和华的作为，也不留心他手所做的。'),
('CUV', '以赛亚书', 23, 5, 13, '所以，我的百姓因无知就被掳去；他们的尊贵人甚是饥饿，群众极其干渴。'),
('CUV', '以赛亚书', 23, 5, 14, '故此，阴间扩张其欲，开了无限量的口；他们的荣耀、群众、繁华，并快乐的人都落在其中。'),
('CUV', '以赛亚书', 23, 5, 15, '卑贱人被压服；尊贵人降为卑；眼目高傲的人也降为卑。'),
('CUV', '以赛亚书', 23, 5, 16, '惟有万军之耶和华因公平而崇高；圣者神因公义显为圣。'),
('CUV', '以赛亚书', 23, 5, 17, '那时，羊羔必来吃草，如同在自己的草场；丰肥人的荒场被游行的人吃尽。'),
('CUV', '以赛亚书', 23, 5, 18, '祸哉！那些以虚假之细绳牵罪孽的人！他们又像以套绳拉罪恶，'),
('CUV', '以赛亚书', 23, 5, 19, '说：任他急速行，赶快成就他的作为，使我们看看；任以色列圣者所谋划的临近成就，使我们知道。'),
('CUV', '以赛亚书', 23, 5, 20, '祸哉！那些称恶为善，称善为恶，以暗为光，以光为暗，以苦为甜，以甜为苦的人。'),
('CUV', '以赛亚书', 23, 5, 21, '祸哉！那些自以为有智慧，自看为通达的人。'),
('CUV', '以赛亚书', 23, 5, 22, '祸哉！那些勇于饮酒，以能力调浓酒的人。'),
('CUV', '以赛亚书', 23, 5, 23, '他们因受贿赂，就称恶人为义，将义人的义夺去。'),
('CUV', '以赛亚书', 23, 5, 24, '火苗怎样吞灭碎秸，干草怎样落在火燄之中，照样，他们的根必像朽物，他们的花必像灰尘飞腾；因为他们厌弃万军之耶和华的训诲，藐视以色列圣者的言语。'),
('CUV', '以赛亚书', 23, 5, 25, '所以，耶和华的怒气向他的百姓发作。他的手伸出攻击他们，山岭就震动；他们的尸首在街市上好像粪土。虽然如此，他的怒气还未转消；他的手仍伸不缩。'),
('CUV', '以赛亚书', 23, 5, 26, '他必竖立大旗，招远方的国民，发嘶声叫他们从地极而来；看哪，他们必急速奔来。'),
('CUV', '以赛亚书', 23, 5, 27, '其中没有疲倦的，绊跌的；没有打盹的，睡觉的；腰带并不放松，鞋带也不折断。'),
('CUV', '以赛亚书', 23, 5, 28, '他们的箭快利，弓也上了弦。马蹄算如坚石，车轮好像旋风。'),
('CUV', '以赛亚书', 23, 5, 29, '他们要吼叫，像母狮子，咆哮，像少壮狮子；他们要咆哮抓食，坦然叼去，无人救回。'),
('CUV', '以赛亚书', 23, 5, 30, '那日，他们要向以色列人吼叫，像海浪匉訇；人若望地，只见黑暗艰难，光明在云中变为昏暗。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 6, 1, '当乌西雅王崩的那年，我见主坐在高高的宝座上。他的衣裳垂下，遮满圣殿。'),
('CUV', '以赛亚书', 23, 6, 2, '其上有撒拉弗侍立，各有六个翅膀：用两个翅膀遮脸，两个翅膀遮脚，两个翅膀飞翔；'),
('CUV', '以赛亚书', 23, 6, 3, '彼此呼喊说：圣哉！圣哉！圣哉！万军之耶和华；他的荣光充满全地！'),
('CUV', '以赛亚书', 23, 6, 4, '因呼喊者的声音，门槛的根基震动，殿充满了烟云。'),
('CUV', '以赛亚书', 23, 6, 5, '那时我说：祸哉！我灭亡了！因为我是嘴唇不洁的人，又住在嘴唇不洁的民中，又因我眼见大君王─万军之耶和华。'),
('CUV', '以赛亚书', 23, 6, 6, '有一撒拉弗飞到我跟前，手里拿著红炭，是用火剪从坛上取下来的，'),
('CUV', '以赛亚书', 23, 6, 7, '将炭沾我的口，说：看哪，这炭沾了你的嘴，你的罪孽便除掉，你的罪恶就赦免了。'),
('CUV', '以赛亚书', 23, 6, 8, '我又听见主的声音说：我可以差遣谁呢？谁肯为我们去呢？我说：我在这里，请差遣我！'),
('CUV', '以赛亚书', 23, 6, 9, '他说：你去告诉这百姓说：你们听是要听见，却不明白；看是要看见，却不晓得。'),
('CUV', '以赛亚书', 23, 6, 10, '要使这百姓心蒙脂油，耳朵发沉，眼睛昏迷；恐怕眼睛看见，耳朵听见，心里明白，回转过来，便得医治。'),
('CUV', '以赛亚书', 23, 6, 11, '我就说：主啊，这到几时为止呢？他说：直到城邑荒凉，无人居住，房屋空闲无人，地土极其荒凉。'),
('CUV', '以赛亚书', 23, 6, 12, '并且耶和华将人迁到远方，在这境内撇下的地土很多。'),
('CUV', '以赛亚书', 23, 6, 13, '境内剩下的人若还有十分之一，也必被吞灭，像栗树、橡树虽被砍伐，树墩子却仍存留。这圣洁的种类在国中也是如此。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 7, 1, '乌西雅的孙子、约坦的儿子、犹大王亚哈斯在位的时候，亚兰王利汛和利玛利的儿子、以色列王比加上来攻打耶路撒冷，却不能攻取。'),
('CUV', '以赛亚书', 23, 7, 2, '有人告诉大卫家说：亚兰与以法莲已经同盟。王的心和百姓的心就都跳动，好像林中的树被风吹动一样。'),
('CUV', '以赛亚书', 23, 7, 3, '耶和华对以赛亚说：你和你的儿子施亚雅述出去，到上池的水沟头，在漂布地的大路上，去迎接亚哈斯，'),
('CUV', '以赛亚书', 23, 7, 4, '对他说：你要谨慎安静，不要因亚兰王利汛和利玛利的儿子这两个冒烟的火把头所发的烈怒害怕，也不要心里胆怯。'),
('CUV', '以赛亚书', 23, 7, 5, '因为亚兰和以法莲，并利玛利的儿子，设恶谋害你，'),
('CUV', '以赛亚书', 23, 7, 6, '说：我们可以上去攻击犹大，扰乱他，攻破他，在其中立他比勒的儿子为王。'),
('CUV', '以赛亚书', 23, 7, 7, '所以主耶和华如此说：这所谋的必立不住，也不得成就。'),
('CUV', '以赛亚书', 23, 7, 8, '原来亚兰的首城是大马色；大马色的首领是利汛。（六十五年之内，以法莲必然破坏，不再成为国民。）'),
('CUV', '以赛亚书', 23, 7, 9, '以法莲的首城是撒玛利亚；撒玛利亚的首领是利玛利的儿子。你们若是不信，定然不得立稳。'),
('CUV', '以赛亚书', 23, 7, 10, '耶和华又晓谕亚哈斯说：'),
('CUV', '以赛亚书', 23, 7, 11, '你向耶和华─你的神求一个兆头：或求显在深处，或求显在高处。'),
('CUV', '以赛亚书', 23, 7, 12, '亚哈斯说：我不求；我不试探耶和华。'),
('CUV', '以赛亚书', 23, 7, 13, '以赛亚说：大卫家啊，你们当听！你们使人厌烦岂算小事，还要使我的神厌烦吗？'),
('CUV', '以赛亚书', 23, 7, 14, '因此，主自己要给你们一个兆头，必有童女怀孕生子，给他起名叫以马内利（就是神与我们同在的意思）。'),
('CUV', '以赛亚书', 23, 7, 15, '到他晓得弃恶择善的时候，他必吃奶油与蜂蜜。'),
('CUV', '以赛亚书', 23, 7, 16, '因为在这孩子还不晓得弃恶择善之先，你所憎恶的那二王之地必致见弃。'),
('CUV', '以赛亚书', 23, 7, 17, '耶和华必使亚述王攻击你的日子临到你和你的百姓，并你的父家，自从以法莲离开犹大以来，未曾有这样的日子。'),
('CUV', '以赛亚书', 23, 7, 18, '那时，耶和华要发嘶声，使埃及江河源头的苍蝇和亚述地的蜂子飞来；'),
('CUV', '以赛亚书', 23, 7, 19, '都必飞来，落在荒凉的谷内、磐石的穴里，和一切荆棘篱笆中，并一切的草场上。'),
('CUV', '以赛亚书', 23, 7, 20, '那时，主必用大河外赁的剃头刀，就是亚述王，剃去头发和脚上的毛，并要剃净胡须。'),
('CUV', '以赛亚书', 23, 7, 21, '那时，一个人要养活一只母牛犊，两只母绵羊；'),
('CUV', '以赛亚书', 23, 7, 22, '因为出的奶多，他就得吃奶油，在境内所剩的人都要吃奶油与蜂蜜。'),
('CUV', '以赛亚书', 23, 7, 23, '从前，凡种一千棵葡萄树、值银一千舍客勒的地方，到那时必长荆棘和蒺藜。'),
('CUV', '以赛亚书', 23, 7, 24, '人上那里去，必带弓箭，因为遍地满了荆棘和蒺藜。'),
('CUV', '以赛亚书', 23, 7, 25, '所有用锄刨挖的山地，你因怕荆棘和蒺藜，不敢上那里去；只可成了放牛之处，为羊践踏之地。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 8, 1, '耶和华对我说：你取一个大牌，拿人所用的笔（或译：人常用的字），写上玛黑珥沙拉勒哈施罢斯（就是掳掠速临、抢夺快到的意思）。'),
('CUV', '以赛亚书', 23, 8, 2, '我要用诚实的见证人，祭司乌利亚和耶比利家的儿子撒迦利亚记录这事。'),
('CUV', '以赛亚书', 23, 8, 3, '我─以赛亚与妻子（原文是女先知）同室；他怀孕生子，耶和华就对我说：给他起名叫玛黑珥沙拉勒哈施罢斯；'),
('CUV', '以赛亚书', 23, 8, 4, '因为在这小孩子不晓得叫父叫母之先，大马色的财宝和撒玛利亚的掳物必在亚述王面前搬了去。'),
('CUV', '以赛亚书', 23, 8, 5, '耶和华又晓谕我说：'),
('CUV', '以赛亚书', 23, 8, 6, '这百姓既厌弃西罗亚缓流的水，喜悦利汛和利玛利的儿子；'),
('CUV', '以赛亚书', 23, 8, 7, '因此，主必使大河翻腾的水猛然冲来，就是亚述王和他所有的威势，必漫过一切的水道，涨过两岸；'),
('CUV', '以赛亚书', 23, 8, 8, '必冲入犹大，涨溢泛滥，直到颈项。以马内利啊，他展开翅膀，遍满你的地。'),
('CUV', '以赛亚书', 23, 8, 9, '列国的人民哪，任凭你们喧嚷，终必破坏；远方的众人哪，当侧耳而听！任凭你们束起腰来，终必破坏；你们束起腰来，终必破坏。'),
('CUV', '以赛亚书', 23, 8, 10, '任凭你们同谋，终归无有；任凭你们言定，终不成立；因为神与我们同在。'),
('CUV', '以赛亚书', 23, 8, 11, '耶和华以大能的手，指教我不可行这百姓所行的道，对我这样说：'),
('CUV', '以赛亚书', 23, 8, 12, '这百姓说同谋背叛，你们不要说同谋背叛。他们所怕的，你们不要怕，也不要畏惧。'),
('CUV', '以赛亚书', 23, 8, 13, '但要尊万军之耶和华为圣，以他为你们所当怕的，所当畏惧的。'),
('CUV', '以赛亚书', 23, 8, 14, '他必作为圣所，却向以色列两家作绊脚的石头，跌人的磐石；向耶路撒冷的居民作为圈套和网罗。'),
('CUV', '以赛亚书', 23, 8, 15, '许多人必在其上绊脚跌倒，而且跌碎，并陷入网罗，被缠住。'),
('CUV', '以赛亚书', 23, 8, 16, '你要卷起律法书，在我门徒中间封住训诲。'),
('CUV', '以赛亚书', 23, 8, 17, '我要等候那掩面不顾雅各家的耶和华；我也要仰望他。'),
('CUV', '以赛亚书', 23, 8, 18, '看哪，我与耶和华所给我的儿女，就是从住在锡安山万军之耶和华来的，在以色列中作为预兆和奇迹。'),
('CUV', '以赛亚书', 23, 8, 19, '有人对你们说：当求问那些交鬼的和行巫术的，就是声音绵蛮，言语微细的。你们便回答说：百姓不当求问自己的神吗？岂可为活人求问死人呢？'),
('CUV', '以赛亚书', 23, 8, 20, '人当以训诲和法度为标准；他们所说的，若不与此相符，必不得见晨光。'),
('CUV', '以赛亚书', 23, 8, 21, '他们必经过这地，受艰难，受饥饿；饥饿的时候，心中焦躁，咒骂自己的君王和自己的神。'),
('CUV', '以赛亚书', 23, 8, 22, '仰观上天，俯察下地，不料，尽是艰难、黑暗，和幽暗的痛苦。他们必被赶入乌黑的黑暗中去。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 9, 1, '但那受过痛苦的必不再见幽暗。从前神使西布伦地和拿弗他利地被藐视，末后却使这沿海的路，约但河外，外邦人的加利利地得著荣耀。'),
('CUV', '以赛亚书', 23, 9, 2, '在黑暗中行走的百姓看见了大光，住在死荫之地的人有光照耀他们。'),
('CUV', '以赛亚书', 23, 9, 3, '你使这国民繁多，加增他们的喜乐；他们在你面前欢喜，好像收割的欢喜，像人分掳物那样的快乐。'),
('CUV', '以赛亚书', 23, 9, 4, '因为他们所负的重轭和肩头上的杖，并欺压他们人的棍，你都已经折断，好像在米甸的日子一样。'),
('CUV', '以赛亚书', 23, 9, 5, '战士在乱杀之间所穿戴的盔甲，并那滚在血中的衣服，都必作为可烧的，当作火柴。'),
('CUV', '以赛亚书', 23, 9, 6, '因有一婴孩为我们而生；有一子赐给我们。政权必担在他的肩头上；他名称为奇妙策士、全能的神、永在的父、和平的君。'),
('CUV', '以赛亚书', 23, 9, 7, '他的政权与平安必加增无穷。他必在大卫的宝座上治理他的国，以公平公义使国坚定稳固，从今直到永远。万军之耶和华的热心必成就这事。'),
('CUV', '以赛亚书', 23, 9, 8, '主使一言入于雅各家，落于以色列家。'),
('CUV', '以赛亚书', 23, 9, 9, '这众百姓，就是以法莲和撒玛利亚的居民，都要知道；他们凭骄傲自大的心说：'),
('CUV', '以赛亚书', 23, 9, 10, '砖墙塌了，我们却要凿石头建筑；桑树砍了，我们却要换香柏树。'),
('CUV', '以赛亚书', 23, 9, 11, '因此，耶和华要高举利汛的敌人来攻击以色列，并要激动以色列的仇敌。'),
('CUV', '以赛亚书', 23, 9, 12, '东有亚兰人，西有非利士人；他们张口要吞吃以色列。虽然如此，耶和华的怒气还未转消；他的手仍伸不缩。'),
('CUV', '以赛亚书', 23, 9, 13, '这百姓还没有归向击打他们的主，也没有寻求万军之耶和华。'),
('CUV', '以赛亚书', 23, 9, 14, '因此，耶和华一日之间必从以色列中剪除头与尾，棕枝与芦苇─'),
('CUV', '以赛亚书', 23, 9, 15, '长老和尊贵人就是头，以谎言教人的先知就是尾。'),
('CUV', '以赛亚书', 23, 9, 16, '因为，引导这百姓的使他们走错了路；被引导的都必败亡。'),
('CUV', '以赛亚书', 23, 9, 17, '所以，主必不喜悦他们的少年人，也不怜恤他们的孤儿寡妇；因为，各人是亵渎的，是行恶的，并且各人的口都说愚妄的话。虽然如此，耶和华的怒气还未转消；他的手仍伸不缩。'),
('CUV', '以赛亚书', 23, 9, 18, '邪恶像火焚烧，烧灭荆棘和蒺藜，在稠密的树林中著起来，就成为烟柱，旋转上腾。'),
('CUV', '以赛亚书', 23, 9, 19, '因万军之耶和华的烈怒，地都烧遍；百姓成为火柴；无人怜爱弟兄。'),
('CUV', '以赛亚书', 23, 9, 20, '有人右边抢夺，仍受饥饿，左边吞吃，仍不饱足；各人吃自己膀臂上的肉。'),
('CUV', '以赛亚书', 23, 9, 21, '玛拿西吞吃（或译：攻击；下同）以法莲；以法莲吞吃玛拿西，又一同攻击犹大。虽然如此，耶和华的怒气还未转消；他的手仍伸不缩。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 10, 1, '祸哉！那些设立不义之律例的和记录奸诈之判语的，'),
('CUV', '以赛亚书', 23, 10, 2, '为要屈枉穷乏人，夺去我民中困苦人的理，以寡妇当作掳物，以孤儿当作掠物。'),
('CUV', '以赛亚书', 23, 10, 3, '到降罚的日子，有灾祸从远方临到，那时，你们怎样行呢？你们向谁逃奔求救呢？你们的荣耀（或译：财宝）存留何处呢？'),
('CUV', '以赛亚书', 23, 10, 4, '他们只得屈身在被掳的人以下，仆倒在被杀的人以下。虽然如此，耶和华的怒气还未转消；他的手仍伸不缩。'),
('CUV', '以赛亚书', 23, 10, 5, '亚述是我怒气的棍，手中拿我恼恨的杖。'),
('CUV', '以赛亚书', 23, 10, 6, '我要打发他攻击亵渎的国民，吩咐他攻击我所恼怒的百姓，抢财为掳物，夺货为掠物，将他们践踏，像街上的泥土一样。'),
('CUV', '以赛亚书', 23, 10, 7, '然而，他不是这样的意思；他心也不这样打算。他心里倒想毁灭，剪除不少的国。'),
('CUV', '以赛亚书', 23, 10, 8, '他说：我的臣仆岂不都是王吗？'),
('CUV', '以赛亚书', 23, 10, 9, '迦勒挪岂不像迦基米施吗？哈马岂不像亚珥拔吗？撒玛利亚岂不像大马色吗？'),
('CUV', '以赛亚书', 23, 10, 10, '我手已经搆到有偶像的国；这些国雕刻的偶像过于耶路撒冷和撒玛利亚的偶像。'),
('CUV', '以赛亚书', 23, 10, 11, '我怎样待撒玛利亚和其中的偶像，岂不照样待耶路撒冷和其中的偶像吗？'),
('CUV', '以赛亚书', 23, 10, 12, '主在锡安山和耶路撒冷成就他一切工作的时候，主说：我必罚亚述王自大的心和他高傲眼目的荣耀。'),
('CUV', '以赛亚书', 23, 10, 13, '因为他说：我所成就的事是靠我手的能力和我的智慧，我本有聪明。我挪移列国的地界，抢夺他们所积蓄的财宝；并且我像勇士，使坐宝座的降为卑。'),
('CUV', '以赛亚书', 23, 10, 14, '我的手搆到列国的财宝，好像人搆到鸟窝；我也得了全地，好像人拾起所弃的雀蛋。没有动翅膀的；没有张嘴的，也没有鸣叫的。'),
('CUV', '以赛亚书', 23, 10, 15, '斧岂可向用斧砍木的自夸呢？锯岂可向用锯的自大呢？好比棍抡起那举棍的，好比杖举起那非木的人。'),
('CUV', '以赛亚书', 23, 10, 16, '因此，主─万军之耶和华必使亚述王的肥壮人变为瘦弱，在他的荣华之下必有火著起，如同焚烧一样。'),
('CUV', '以赛亚书', 23, 10, 17, '以色列的光必如火；他的圣者必如火燄。在一日之间，将亚述王的荆棘和蒺藜焚烧净尽；'),
('CUV', '以赛亚书', 23, 10, 18, '又将他树林和肥田的荣耀全然烧尽，好像拿军旗的昏过去一样。'),
('CUV', '以赛亚书', 23, 10, 19, '他林中剩下的树必稀少，就是孩子也能写其数。'),
('CUV', '以赛亚书', 23, 10, 20, '到那日，以色列所剩下的和雅各家所逃脱的，不再倚靠那击打他们的，却要诚实倚靠耶和华─以色列的圣者。'),
('CUV', '以赛亚书', 23, 10, 21, '所剩下的，就是雅各家所剩下的，必归回全能的神。'),
('CUV', '以赛亚书', 23, 10, 22, '以色列啊，你的百姓虽多如海沙，惟有剩下的归回。原来灭绝的事已定，必有公义施行，如水涨溢。'),
('CUV', '以赛亚书', 23, 10, 23, '因为主─万军之耶和华在全地之中必成就所定规的结局。'),
('CUV', '以赛亚书', 23, 10, 24, '所以，主─万军之耶和华如此说：住锡安我的百姓啊，亚述王虽然用棍击打你，又照埃及的样子举杖攻击你，你却不要怕他。'),
('CUV', '以赛亚书', 23, 10, 25, '因为还有一点点时候，向你们发的忿恨就要完毕，我的怒气要向他发作，使他灭亡。'),
('CUV', '以赛亚书', 23, 10, 26, '万军之耶和华要兴起鞭来攻击他，好像在俄立磐石那里杀戮米甸人一样。耶和华的杖要向海伸出，把杖举起，像在埃及一样。'),
('CUV', '以赛亚书', 23, 10, 27, '到那日，亚述王的重担必离开你的肩头；他的轭必离开你的颈项；那轭也必因肥壮的缘故撑断（或译：因膏油的缘故毁坏）。'),
('CUV', '以赛亚书', 23, 10, 28, '亚述王来到亚叶，经过米矶仑，在密抹安放辎重。'),
('CUV', '以赛亚书', 23, 10, 29, '他们过了隘口，在迦巴住宿。拉玛人战兢；扫罗的基比亚人逃跑。'),
('CUV', '以赛亚书', 23, 10, 30, '迦琳的居民（原文是女子）哪，要高声呼喊！莱煞人哪，须听！哀哉！困苦的亚拿突啊。'),
('CUV', '以赛亚书', 23, 10, 31, '玛得米那人躲避；基柄的居民逃遁。'),
('CUV', '以赛亚书', 23, 10, 32, '当那日，亚述王要在挪伯歇兵，向锡安女子的山─就是耶路撒冷的山─抡手攻他。'),
('CUV', '以赛亚书', 23, 10, 33, '看哪，主─万军之耶和华以惊吓削去树枝；长高的必被砍下，高大的必被伐倒。'),
('CUV', '以赛亚书', 23, 10, 34, '稠密的树林，他要用铁器砍下；利巴嫩的树木必被大能者伐倒。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 11, 1, '从耶西的本（原文是墩）必发一条；从他根生的枝子必结果实。'),
('CUV', '以赛亚书', 23, 11, 2, '耶和华的灵必住在他身上，就是使他有智慧和聪明的灵，谋略和能力的灵，知识和敬畏耶和华的灵。'),
('CUV', '以赛亚书', 23, 11, 3, '他必以敬畏耶和华为乐；行审判不凭眼见，断是非也不凭耳闻；'),
('CUV', '以赛亚书', 23, 11, 4, '却要以公义审判贫穷人，以正直判断世上的谦卑人，以口中的杖击打世界，以嘴里的气杀戮恶人。'),
('CUV', '以赛亚书', 23, 11, 5, '公义必当他的腰带；信实必当他胁下的带子。'),
('CUV', '以赛亚书', 23, 11, 6, '豺狼必与绵羊羔同居，豹子与山羊羔同卧；少壮狮子与牛犊并肥畜同群；小孩子要牵引他们。'),
('CUV', '以赛亚书', 23, 11, 7, '牛必与熊同食；牛犊必与小熊同卧；狮子必吃草，与牛一样。'),
('CUV', '以赛亚书', 23, 11, 8, '吃奶的孩子必玩耍在虺蛇的洞口；断奶的婴儿必按手在毒蛇的穴上。'),
('CUV', '以赛亚书', 23, 11, 9, '在我圣山的遍处，这一切都不伤人，不害物；因为认识耶和华的知识要充满遍地，好像水充满洋海一般。'),
('CUV', '以赛亚书', 23, 11, 10, '到那日，耶西的根立作万民的大旗；外邦人必寻求他，他安息之所大有荣耀。'),
('CUV', '以赛亚书', 23, 11, 11, '当那日，主必二次伸手救回自己百姓中所余剩的，就是在亚述、埃及、巴忒罗、古实、以拦、示拿、哈马，并众海岛所剩下的。'),
('CUV', '以赛亚书', 23, 11, 12, '他必向列国竖立大旗，招回以色列被赶散的人，又从地的四方聚集分散的犹大人。'),
('CUV', '以赛亚书', 23, 11, 13, '以法莲的嫉妒就必消散；扰害犹大的必被剪除。以法莲必不嫉妒犹大，犹大也不扰害以法莲。'),
('CUV', '以赛亚书', 23, 11, 14, '他们要向西飞，扑在非利士人的肩头上（肩头上：或译西界），一同掳掠东方人，伸手按住以东和摩押；亚扪人也必顺服他们。'),
('CUV', '以赛亚书', 23, 11, 15, '耶和华必使埃及海汊枯干，抡手用暴热的风使大河分为七条，令人过去不致湿脚。'),
('CUV', '以赛亚书', 23, 11, 16, '为主余剩的百姓，就是从亚述剩下回来的，必有一条大道，如当日以色列从埃及地上来一样。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 12, 1, '到那日，你必说：耶和华啊，我要称谢你！因为你虽然向我发怒，你的怒气却已转消；你又安慰了我。'),
('CUV', '以赛亚书', 23, 12, 2, '看哪！神是我的拯救；我要倚靠他，并不惧怕。因为主耶和华是我的力量，是我的诗歌，他也成了我的拯救。'),
('CUV', '以赛亚书', 23, 12, 3, '所以，你们必从救恩的泉源欢然取水。'),
('CUV', '以赛亚书', 23, 12, 4, '在那日，你们要说：当称谢耶和华，求告他的名；将他所行的传扬在万民中，提说他的名已被尊崇。'),
('CUV', '以赛亚书', 23, 12, 5, '你们要向耶和华唱歌，因他所行的甚是美好；但愿这事普传天下。'),
('CUV', '以赛亚书', 23, 12, 6, '锡安的居民哪，当扬声欢呼，因为在你们中间的以色列圣者乃为至大。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 13, 1, '亚摩斯的儿子以赛亚得默示，论巴比伦。'),
('CUV', '以赛亚书', 23, 13, 2, '应当在净光的山竖立大旗，向群众扬声招手，使他们进入贵胄的门。'),
('CUV', '以赛亚书', 23, 13, 3, '我吩咐我所挑出来的人；我招呼我的勇士─就是那矜夸高傲之辈，为要成就我怒中所定的。'),
('CUV', '以赛亚书', 23, 13, 4, '山间有多人的声音，好像是大国人民。有许多国的民聚集哄嚷的声音；这是万军之耶和华点齐军队，预备打仗。'),
('CUV', '以赛亚书', 23, 13, 5, '他们从远方来，从天边来，就是耶和华并他恼恨的兵器要毁灭这全地。'),
('CUV', '以赛亚书', 23, 13, 6, '你们要哀号，因为耶和华的日子临近了！这日来到，好像毁灭从全能者来到。'),
('CUV', '以赛亚书', 23, 13, 7, '所以，人手都必软弱；人心都必消化。'),
('CUV', '以赛亚书', 23, 13, 8, '他们必惊惶悲痛；愁苦必将他们抓住。他们疼痛，好像产难的妇人一样，彼此惊奇相看，脸如火燄。'),
('CUV', '以赛亚书', 23, 13, 9, '耶和华的日子临到，必有残忍、忿恨、烈怒，使这地荒凉，从其中除灭罪人。'),
('CUV', '以赛亚书', 23, 13, 10, '天上的众星群宿都不发光，日头一出就变黑暗；月亮也不放光。'),
('CUV', '以赛亚书', 23, 13, 11, '我必因邪恶刑罚世界，因罪孽刑罚恶人，使骄傲人的狂妄止息，制伏强暴人的狂傲。'),
('CUV', '以赛亚书', 23, 13, 12, '我必使人比精金还少，使人比俄斐纯金更少。'),
('CUV', '以赛亚书', 23, 13, 13, '我─万军之耶和华在忿恨中发烈怒的日子，必使天震动，使地摇撼，离其本位。'),
('CUV', '以赛亚书', 23, 13, 14, '人必像被追赶的鹿，像无人收聚的羊，各归回本族，各逃到本土。'),
('CUV', '以赛亚书', 23, 13, 15, '凡被仇敌追上的必被刺死；凡被捉住的必被刀杀。'),
('CUV', '以赛亚书', 23, 13, 16, '他们的婴孩必在他们眼前摔碎；他们的房屋必被抢夺；他们的妻子必被玷污。'),
('CUV', '以赛亚书', 23, 13, 17, '我必激动玛代人来攻击他们。玛代人不注重银子，也不喜爱金子。'),
('CUV', '以赛亚书', 23, 13, 18, '他们必用弓击碎少年人，不怜悯妇人所生的，眼也不顾惜孩子。'),
('CUV', '以赛亚书', 23, 13, 19, '巴比伦素来为列国的荣耀，为迦勒底人所矜夸的华美，必像神所倾覆的所多玛、蛾摩拉一样。'),
('CUV', '以赛亚书', 23, 13, 20, '其内必永无人烟，世世代代无人居住。亚拉伯人也不在那里支搭帐棚；牧羊的人也不使羊群卧在那里。'),
('CUV', '以赛亚书', 23, 13, 21, '只有旷野的走兽卧在那里；咆哮的兽满了房屋。鸵鸟住在那里；野山羊在那里跳舞。'),
('CUV', '以赛亚书', 23, 13, 22, '豺狼必在他宫中呼号；野狗必在他华美殿内吼叫。巴比伦受罚的时候临近；他的日子必不长久。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 14, 1, '耶和华要怜恤雅各，必再拣选以色列，将他们安置在本地。寄居的必与他们联合，紧贴雅各家。'),
('CUV', '以赛亚书', 23, 14, 2, '外邦人必将他们带回本土；以色列家必在耶和华的地上得外邦人为仆婢，也要掳掠先前掳掠他们的，辖制先前欺压他们的。'),
('CUV', '以赛亚书', 23, 14, 3, '当耶和华使你脱离愁苦、烦恼，并人勉强你做的苦工，得享安息的日子，'),
('CUV', '以赛亚书', 23, 14, 4, '你必题这诗歌论巴比伦王说：欺压人的何竟息灭？强暴的何竟止息？'),
('CUV', '以赛亚书', 23, 14, 5, '耶和华折断了恶人的杖，辖制人的圭，'),
('CUV', '以赛亚书', 23, 14, 6, '就是在忿怒中连连攻击众民的，在怒气中辖制列国，行逼迫无人阻止的。'),
('CUV', '以赛亚书', 23, 14, 7, '现在全地得安息，享平静；人皆发声欢呼。'),
('CUV', '以赛亚书', 23, 14, 8, '松树和利巴嫩的香柏树都因你欢乐，说：自从你仆倒，再无人上来砍伐我们。'),
('CUV', '以赛亚书', 23, 14, 9, '你下到阴间，阴间就因你震动来迎接你，又因你惊动在世曾为首领的阴魂，并使那曾为列国君王的，都离位站起。'),
('CUV', '以赛亚书', 23, 14, 10, '他们都要发言对你说：你也变为软弱像我们一样吗？你也成了我们的样子吗？'),
('CUV', '以赛亚书', 23, 14, 11, '你的威势和你琴瑟的声音都下到阴间。你下铺的是虫，上盖的是蛆。'),
('CUV', '以赛亚书', 23, 14, 12, '明亮之星，早晨之子啊，你何竟从天坠落？你这攻败列国的何竟被砍倒在地上？'),
('CUV', '以赛亚书', 23, 14, 13, '你心里曾说：我要升到天上；我要高举我的宝座在神众星以上；我要坐在聚会的山上，在北方的极处。'),
('CUV', '以赛亚书', 23, 14, 14, '我要升到高云之上；我要与至上者同等。'),
('CUV', '以赛亚书', 23, 14, 15, '然而，你必坠落阴间，到坑中极深之处。'),
('CUV', '以赛亚书', 23, 14, 16, '凡看见你的都要定睛看你，留意看你，说：使大地战抖，使列国震动，'),
('CUV', '以赛亚书', 23, 14, 17, '使世界如同荒野，使城邑倾覆，不释放被掳的人归家，是这个人吗？'),
('CUV', '以赛亚书', 23, 14, 18, '列国的君王俱各在自己阴宅的荣耀中安睡。'),
('CUV', '以赛亚书', 23, 14, 19, '惟独你被抛弃，不得入你的坟墓，好像可憎的枝子，以被杀的人为衣，就是被刀刺透，坠落坑中石头那里的；你又像被践踏的尸首一样。'),
('CUV', '以赛亚书', 23, 14, 20, '你不得与君王同葬；因为你败坏你的国，杀戮你的民。恶人后裔的名，必永不提说。'),
('CUV', '以赛亚书', 23, 14, 21, '先人既有罪孽，就要预备杀戮他的子孙，免得他们兴起来，得了遍地，在世上修满城邑。'),
('CUV', '以赛亚书', 23, 14, 22, '万军之耶和华说：我必兴起攻击他们，将巴比伦的名号和所余剩的人，连子带孙一并剪除。这是耶和华说的。'),
('CUV', '以赛亚书', 23, 14, 23, '我必使巴比伦为箭猪所得，又变为水池；我要用灭亡的扫帚扫净他。这是万军之耶和华说的。'),
('CUV', '以赛亚书', 23, 14, 24, '万军之耶和华起誓说：我怎样思想，必照样成就；我怎样定意，必照样成立，'),
('CUV', '以赛亚书', 23, 14, 25, '就是在我地上打折亚述人，在我山上将他践踏。他加的轭必离开以色列人；他加的重担必离开他们的肩头。'),
('CUV', '以赛亚书', 23, 14, 26, '这是向全地所定的旨意；这是向万国所伸出的手。'),
('CUV', '以赛亚书', 23, 14, 27, '万军之耶和华既然定意，谁能废弃呢？他的手已经伸出，谁能转回呢？'),
('CUV', '以赛亚书', 23, 14, 28, '亚哈斯王崩的那年，就有以下的默示：'),
('CUV', '以赛亚书', 23, 14, 29, '非利士全地啊，不要因击打你的杖折断就喜乐。因为从蛇的根必生出毒蛇；他所生的是火燄的飞龙。'),
('CUV', '以赛亚书', 23, 14, 30, '贫寒人的长子必有所食；穷乏人必安然躺卧。我必以饥荒治死你的根；你所余剩的人必被杀戮。'),
('CUV', '以赛亚书', 23, 14, 31, '门哪，应当哀号！城啊，应当呼喊！非利士全地啊，你都消化了！因为有烟从北方出来，他行伍中并无乱队的。'),
('CUV', '以赛亚书', 23, 14, 32, '可怎样回答外邦（或指非利士）的使者呢？必说：耶和华建立了锡安；他百姓中的困苦人必投奔在其中。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 15, 1, '论摩押的默示：一夜之间，摩押的亚珥变为荒废，归于无有；一夜之间，摩押的基珥变为荒废，归于无有。'),
('CUV', '以赛亚书', 23, 15, 2, '他们上巴益，又往底本，到高处去哭泣。摩押人因尼波和米底巴哀号，各人头上光秃，胡须剃净。'),
('CUV', '以赛亚书', 23, 15, 3, '他们在街市上都腰束麻布，在房顶上和宽阔处俱各哀号，眼泪汪汪。'),
('CUV', '以赛亚书', 23, 15, 4, '希实本和以利亚利悲哀的声音达到雅杂，所以摩押带兵器的高声喊嚷，人心战兢。'),
('CUV', '以赛亚书', 23, 15, 5, '我心为摩押悲哀；他的贵胄（或译：逃民）逃到琐珥，到伊基拉施利施亚。他们上鲁希坡，随走随哭。在何罗念的路上，因毁灭举起哀声。'),
('CUV', '以赛亚书', 23, 15, 6, '因为宁林的水成为干涸，青草枯干，嫩草灭没，青绿之物，一无所有。'),
('CUV', '以赛亚书', 23, 15, 7, '因此，摩押人所得的财物和所积蓄的都要运过柳树河。'),
('CUV', '以赛亚书', 23, 15, 8, '哀声遍闻摩押的四境；哀号的声音达到以基莲；哀号的声音达到比珥以琳。'),
('CUV', '以赛亚书', 23, 15, 9, '底们的水充满了血；我还要加增底们的灾难，叫狮子来追上摩押逃脱的民和那地上所余剩的人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 16, 1, '你们当将羊羔奉给那地掌权的，从西拉往旷野，送到锡安城（原文是女子）的山。'),
('CUV', '以赛亚书', 23, 16, 2, '摩押的居民（原文是女子）在亚嫩渡口，必像游飞的鸟，如拆窝的雏。'),
('CUV', '以赛亚书', 23, 16, 3, '求你献谋略，行公平，使你的影子在午间如黑夜，隐藏被赶散的人，不可显露逃民。'),
('CUV', '以赛亚书', 23, 16, 4, '求你容我这被赶散的人和你同居。至于摩押，求你作他的隐密处，脱离灭命者的面。勒索人的归于无有，毁灭的事止息了，欺压人的从国中除灭了，'),
('CUV', '以赛亚书', 23, 16, 5, '必有宝座因慈爱坚立；必有一位诚诚实实坐在其上，在大卫帐幕中施行审判，寻求公平，速行公义。'),
('CUV', '以赛亚书', 23, 16, 6, '我们听说摩押人骄傲，是极其骄傲；听说他狂妄、骄傲、忿怒；他夸大的话是虚空的。'),
('CUV', '以赛亚书', 23, 16, 7, '因此，摩押人必为摩押哀号；人人都要哀号。你们摩押人要为吉珥哈列设的葡萄饼哀叹，极其忧伤。'),
('CUV', '以赛亚书', 23, 16, 8, '因为希实本的田地和西比玛的葡萄树都衰残了。列国的君主折断其上美好的枝子；这枝子长到雅谢延到旷野，嫩枝向外探出，直探过盐海。'),
('CUV', '以赛亚书', 23, 16, 9, '因此，我要为西比玛的葡萄树哀哭，与雅谢人哀哭一样。希实本、以利亚利啊，我要以眼泪浇灌你；因为有交战呐喊的声音临到你夏天的果子，并你收割的庄稼。'),
('CUV', '以赛亚书', 23, 16, 10, '从肥美的田中夺去了欢喜快乐；在葡萄园里必无歌唱，也无欢呼的声音。踹酒的在酒醡中不得踹出酒来；我使他欢呼的声音止息。'),
('CUV', '以赛亚书', 23, 16, 11, '因此，我心腹为摩押哀鸣如琴；我心肠为吉珥哈列设也是如此。'),
('CUV', '以赛亚书', 23, 16, 12, '摩押人朝见的时候，在高处疲乏，又到他圣所祈祷，也不蒙应允。'),
('CUV', '以赛亚书', 23, 16, 13, '这是耶和华从前论摩押的话。'),
('CUV', '以赛亚书', 23, 16, 14, '但现在耶和华说：三年之内，照雇工的年数，摩押的荣耀与他的群众必被藐视，余剩的人甚少无几。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 17, 1, '论大马色的默示：看哪，大马色已被废弃，不再为城，必变作乱堆。'),
('CUV', '以赛亚书', 23, 17, 2, '亚罗珥的城邑已被撇弃，必成为牧羊之处；羊在那里躺卧，无人惊吓。'),
('CUV', '以赛亚书', 23, 17, 3, '以法莲不再有保障；大马色不再有国权；亚兰所剩下的必像以色列人的荣耀消灭一样。这是万军之耶和华说的。'),
('CUV', '以赛亚书', 23, 17, 4, '到那日，雅各的荣耀必至枵薄；他肥胖的身体必渐瘦弱。'),
('CUV', '以赛亚书', 23, 17, 5, '就必像收割的人收敛禾稼，用手割取穗子，又像人在利乏音谷拾取遗落的穗子。'),
('CUV', '以赛亚书', 23, 17, 6, '其间所剩下的不多，好像人打橄榄树─在尽上的枝梢上只剩两三个果子；在多果树的旁枝上只剩四五个果子。这是耶和华─以色列的神说的。'),
('CUV', '以赛亚书', 23, 17, 7, '当那日，人必仰望造他们的主，眼目重看以色列的圣者。'),
('CUV', '以赛亚书', 23, 17, 8, '他们必不仰望祭坛，就是自己手所筑的，也不重看自己指头所做的，无论是木偶是日像。'),
('CUV', '以赛亚书', 23, 17, 9, '在那日，他们的坚固城必像树林中和山顶上所撇弃的地方，就是从前在以色列人面前被人撇弃的。这样，地就荒凉了。'),
('CUV', '以赛亚书', 23, 17, 10, '因你忘记救你的神，不记念你能力的磐石；所以，你栽上佳美的树秧子，插上异样的栽子。'),
('CUV', '以赛亚书', 23, 17, 11, '栽种的日子，你周围圈上篱笆，又到早晨使你所种的开花；但在愁苦极其伤痛的日子，所收割的都飞去了。'),
('CUV', '以赛亚书', 23, 17, 12, '唉！多民哄嚷，好像海浪匉訇；列邦奔腾，好像猛水滔滔；'),
('CUV', '以赛亚书', 23, 17, 13, '列邦奔腾，好像多水滔滔；但神斥责他们，他们就远远逃避，又被追赶，如同山上的风前糠，又如暴风前的旋风土。'),
('CUV', '以赛亚书', 23, 17, 14, '到晚上有惊吓，未到早晨他们就没有了。这是掳掠我们之人所得的分，是抢夺我们之人的报应。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 18, 1, '唉！古实河外翅膀刷刷响声之地，'),
('CUV', '以赛亚书', 23, 18, 2, '差遣使者在水面上，坐蒲草船过海。先知说：你们快行的使者，要到高大光滑的民那里去。自从开国以来，那民极其可畏，是分地界践踏人的；他们的地有江河分开。'),
('CUV', '以赛亚书', 23, 18, 3, '世上一切的居民和地上所住的人哪，山上竖立大旗的时候你们要看；吹角的时候你们要听。'),
('CUV', '以赛亚书', 23, 18, 4, '耶和华对我这样说：我要安静，在我的居所观看，如同日光中的清热，又如露水的云雾在收割的热天。'),
('CUV', '以赛亚书', 23, 18, 5, '收割之先，花开已谢，花也成了将熟的葡萄；他必用镰刀削去嫩枝，又砍掉蔓延的枝条，'),
('CUV', '以赛亚书', 23, 18, 6, '都要撇给山间的鸷鸟和地上的野兽。夏天，鸷鸟要宿在其上；冬天，野兽都卧在其中。'),
('CUV', '以赛亚书', 23, 18, 7, '到那时，这高大光滑的民，就是从开国以来极其可畏、分地界践踏人的，他们的地有江河分开；他们必将礼物奉给万军之耶和华，就是奉到锡安山─耶和华安置他名的地方。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 19, 1, '论埃及的默示：看哪，耶和华乘驾快云，临到埃及。埃及的偶像在他面前战兢；埃及人的心在里面消化。'),
('CUV', '以赛亚书', 23, 19, 2, '我必激动埃及人攻击埃及人─弟兄攻击弟兄，邻舍攻击邻舍；这城攻击那城，这国攻击那国。'),
('CUV', '以赛亚书', 23, 19, 3, '埃及人的心神必在里面耗尽；我必败坏他们的谋略。他们必求问偶像和念咒的、交鬼的、行巫术的。'),
('CUV', '以赛亚书', 23, 19, 4, '我必将埃及人交在残忍主的手中；强暴王必辖制他们。这是主─万军之耶和华说的。'),
('CUV', '以赛亚书', 23, 19, 5, '海中的水必绝尽，河也消没干涸。'),
('CUV', '以赛亚书', 23, 19, 6, '江河要变臭；埃及的河水都必减少枯干。苇子和芦荻都必衰残；'),
('CUV', '以赛亚书', 23, 19, 7, '靠尼罗河旁的草田，并沿尼罗河所种的田，都必枯干。庄稼被风吹去，归于无有。'),
('CUV', '以赛亚书', 23, 19, 8, '打鱼的必哀哭。在尼罗河一切钓鱼的必悲伤；在水上撒网的必都衰弱。'),
('CUV', '以赛亚书', 23, 19, 9, '用梳好的麻造物的和织白布的都必羞愧；'),
('CUV', '以赛亚书', 23, 19, 10, '国柱必被打碎，所有佣工的，心必愁烦。'),
('CUV', '以赛亚书', 23, 19, 11, '琐安的首领极其愚昧；法老大有智慧的谋士，所筹划的成为愚谋。你们怎敢对法老说：我是智慧人的子孙，我是古王的后裔？'),
('CUV', '以赛亚书', 23, 19, 12, '你的智慧人在哪里呢？万军之耶和华向埃及所定的旨意，他们可以知道，可以告诉你吧！'),
('CUV', '以赛亚书', 23, 19, 13, '琐安的首领都变为愚昧；挪弗的首领都受了迷惑。当埃及支派房角石的，使埃及人走错了路。'),
('CUV', '以赛亚书', 23, 19, 14, '耶和华使乖谬的灵搀入埃及中间；首领使埃及一切所做的都有差错，好像醉酒之人呕吐的时候东倒西歪一样。'),
('CUV', '以赛亚书', 23, 19, 15, '埃及中，无论是头与尾，棕枝与芦苇，所做之工都不成就。'),
('CUV', '以赛亚书', 23, 19, 16, '到那日，埃及人必像妇人一样，他们必因万军之耶和华在埃及以上所抡的手，战兢惧怕。'),
('CUV', '以赛亚书', 23, 19, 17, '犹大地必使埃及惊恐，向谁提起犹大地，谁就惧怕。这是因万军之耶和华向埃及所定的旨意。'),
('CUV', '以赛亚书', 23, 19, 18, '当那日，埃及地必有五城的人说迦南的方言，又指著万军之耶和华起誓。有一城必称为灭亡城。'),
('CUV', '以赛亚书', 23, 19, 19, '当那日，在埃及地中必有为耶和华筑的一座坛；在埃及的边界上必有为耶和华立的一根柱。'),
('CUV', '以赛亚书', 23, 19, 20, '这都要在埃及地为万军之耶和华作记号和证据。埃及人因为受人的欺压哀求耶和华，他就差遣一位救主作护卫者，拯救他们。'),
('CUV', '以赛亚书', 23, 19, 21, '耶和华必被埃及人所认识。在那日，埃及人必认识耶和华，也要献祭物和供物敬拜他，并向耶和华许愿还愿。'),
('CUV', '以赛亚书', 23, 19, 22, '耶和华必击打埃及，又击打又医治，埃及人就归向耶和华。他必应允他们的祷告，医治他们。'),
('CUV', '以赛亚书', 23, 19, 23, '当那日，必有从埃及通亚述去的大道。亚述人要进入埃及，埃及人也进入亚述；埃及人要与亚述人一同敬拜耶和华。'),
('CUV', '以赛亚书', 23, 19, 24, '当那日，以色列必与埃及、亚述三国一律，使地上的人得福；'),
('CUV', '以赛亚书', 23, 19, 25, '因为万军之耶和华赐福给他们，说：埃及─我的百姓，亚述─我手的工作，以色列─我的产业，都有福了！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 20, 1, '亚述王撒珥根打发他珥探到亚实突的那年，他珥探就攻打亚实突，将城攻取。'),
('CUV', '以赛亚书', 23, 20, 2, '那时，耶和华晓谕亚摩斯的儿子以赛亚说：你去解掉你腰间的麻布，脱下你脚上的鞋。以赛亚就这样做，露身赤脚行走。'),
('CUV', '以赛亚书', 23, 20, 3, '耶和华说：我仆人以赛亚怎样露身赤脚行走三年，作为关乎埃及和古实的预兆奇迹。'),
('CUV', '以赛亚书', 23, 20, 4, '照样，亚述王也必掳去埃及人，掠去古实人，无论老少，都露身赤脚，现出下体，使埃及蒙羞。'),
('CUV', '以赛亚书', 23, 20, 5, '以色列人必因所仰望的古实，所夸耀的埃及，惊惶羞愧。'),
('CUV', '以赛亚书', 23, 20, 6, '那时，这沿海一带的居民必说：看哪，我们素所仰望的，就是我们为脱离亚述王逃往求救的，不过是如此！我们怎能逃脱呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 21, 1, '论海旁旷野的默示：有仇敌从旷野，从可怕之地而来，好像南方的旋风，猛然扫过。'),
('CUV', '以赛亚书', 23, 21, 2, '令人凄惨的异象已默示于我。诡诈的行诡诈，毁灭的行毁灭。以拦哪，你要上去！玛代啊，你要围困！主说：我使一切叹息止住。'),
('CUV', '以赛亚书', 23, 21, 3, '所以，我满腰疼痛；痛苦将我抓住，好像产难的妇人一样。我疼痛甚至不能听；我惊惶甚至不能看。'),
('CUV', '以赛亚书', 23, 21, 4, '我心慌张，惊恐威吓我。我所羡慕的黄昏，变为我的战兢。'),
('CUV', '以赛亚书', 23, 21, 5, '他们摆设筵席，派人守望，又吃，又喝。首领啊，你们起来，用油抹盾牌。'),
('CUV', '以赛亚书', 23, 21, 6, '主对我如此说：你去设立守望的，使他将所看见的述说。'),
('CUV', '以赛亚书', 23, 21, 7, '他看见军队，就是骑马的一对一对地来，又看见驴队，骆驼队，就要侧耳细听。'),
('CUV', '以赛亚书', 23, 21, 8, '他像狮子吼叫，说：主啊，我白日常站在望楼上，整夜立在我守望所。'),
('CUV', '以赛亚书', 23, 21, 9, '看哪，有一队军兵骑著马，一对一对地来。他就说：巴比伦倾倒了！倾倒了！他一切雕刻的神像都打碎于地。'),
('CUV', '以赛亚书', 23, 21, 10, '我被打的禾稼，我场上的谷啊，我从万军之耶和华─以色列的神那里所听见的，都告诉你们了。'),
('CUV', '以赛亚书', 23, 21, 11, '论度玛的默示：有人声从西珥呼问我说：守望的啊，夜里如何？守望的啊，夜里如何？'),
('CUV', '以赛亚书', 23, 21, 12, '守望的说：早晨将到，黑夜也来。你们若要问就可以问，可以回头再来。'),
('CUV', '以赛亚书', 23, 21, 13, '论亚拉伯的默示：底但结伴的客旅啊，你们必在亚拉伯的树林中住宿。'),
('CUV', '以赛亚书', 23, 21, 14, '提玛地的居民拿水来，送给口渴的，拿饼来迎接逃避的。'),
('CUV', '以赛亚书', 23, 21, 15, '因为他们逃避刀剑和出了鞘的刀，并上了弦的弓与刀兵的重灾。'),
('CUV', '以赛亚书', 23, 21, 16, '主对我这样说：一年之内，照雇工的年数，基达的一切荣耀必归于无有。'),
('CUV', '以赛亚书', 23, 21, 17, '弓箭手所余剩的，就是基达人的勇士，必然稀少，因为这是耶和华─以色列的神说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 22, 1, '论异象谷的默示：有甚么事使你这满城的人都上房顶呢？'),
('CUV', '以赛亚书', 23, 22, 2, '你这满处呐喊、大有喧哗的城，欢乐的邑啊，你中间被杀的并不是被刀杀，也不是因打仗死亡。'),
('CUV', '以赛亚书', 23, 22, 3, '你所有的官长一同逃跑，都为弓箭手所捆绑。你中间一切被找到的都一同被捆绑；他们本是逃往远方的。'),
('CUV', '以赛亚书', 23, 22, 4, '所以我说：你们转眼不看我，我要痛哭。不要因我众民（原文是民女）的毁灭，就竭力安慰我。'),
('CUV', '以赛亚书', 23, 22, 5, '因为主─万军之耶和华使异象谷有溃乱、践踏、烦扰的日子。城被攻破，哀声达到山间。'),
('CUV', '以赛亚书', 23, 22, 6, '以拦带著箭袋，还有坐战车的和马兵；吉珥揭开盾牌。'),
('CUV', '以赛亚书', 23, 22, 7, '你嘉美的谷遍满战车，也有马兵在城门前排列。'),
('CUV', '以赛亚书', 23, 22, 8, '他去掉犹大的遮盖。那日，你就仰望林库内的军器。'),
('CUV', '以赛亚书', 23, 22, 9, '你们看见大卫城的破口很多，便聚积下池的水，'),
('CUV', '以赛亚书', 23, 22, 10, '又数点耶路撒冷的房屋，将房屋拆毁，修补城墙，'),
('CUV', '以赛亚书', 23, 22, 11, '又在两道城墙中间挖一个聚水池可盛旧池的水，却不仰望做这事的主，也不顾念从古定这事的。'),
('CUV', '以赛亚书', 23, 22, 12, '当那日，主─万军之耶和华叫人哭泣哀号，头上光秃，身披麻布。'),
('CUV', '以赛亚书', 23, 22, 13, '谁知，人倒欢喜快乐，宰牛杀羊，吃肉喝酒，说：我们吃喝吧！因为明天要死了。'),
('CUV', '以赛亚书', 23, 22, 14, '万军之耶和华亲自默示我说：这罪孽直到你们死，断不得赦免！这是主─万军之耶和华说的。'),
('CUV', '以赛亚书', 23, 22, 15, '主─万军之耶和华这样说：你去见掌银库的，就是家宰舍伯那，对他说：'),
('CUV', '以赛亚书', 23, 22, 16, '你在这里做甚么呢？有甚么人竟在这里凿坟墓，就是在高处为自己凿坟墓，在磐石中为自己凿出安身之所？'),
('CUV', '以赛亚书', 23, 22, 17, '看哪，耶和华必像大有力的人，将你紧紧缠裹，竭力抛去。'),
('CUV', '以赛亚书', 23, 22, 18, '他必将你滚成一团，抛在宽阔之地，好像抛球一样。你这主人家的羞辱，必在那里坐你荣耀的车，也必在那里死亡。'),
('CUV', '以赛亚书', 23, 22, 19, '我必赶逐你离开官职；你必从你的原位撤下。'),
('CUV', '以赛亚书', 23, 22, 20, '到那日，我必召我仆人希勒家的儿子以利亚敬来，'),
('CUV', '以赛亚书', 23, 22, 21, '将你的外袍给他穿上，将你的腰带给他系紧，将你的政权交在他手中。他必作耶路撒冷居民和犹大家的父。'),
('CUV', '以赛亚书', 23, 22, 22, '我必将大卫家的钥匙放在他肩头上。他开，无人能关；他关，无人能开。'),
('CUV', '以赛亚书', 23, 22, 23, '我必将他安稳，像钉子钉在坚固处；他必作为他父家荣耀的宝座。'),
('CUV', '以赛亚书', 23, 22, 24, '他父家所有的荣耀，连儿女带子孙，都挂在他身上，好像一切小器皿，从杯子到酒瓶挂上一样。'),
('CUV', '以赛亚书', 23, 22, 25, '万军之耶和华说：当那日，钉在坚固处的钉子必压斜，被砍断落地；挂在其上的重担必被剪断。因为这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 23, 1, '论推罗的默示：他施的船只都要哀号；因为罗变为荒场，甚至没有房屋，没有可进之路。这消息是从基提地得来的。'),
('CUV', '以赛亚书', 23, 23, 2, '沿海的居民，就是素来靠航海西顿的商家得丰盛的，你们当静默无言。'),
('CUV', '以赛亚书', 23, 23, 3, '在大水之上，西曷的粮食、尼罗河的庄稼是推罗的进项；他作列国的大码头。'),
('CUV', '以赛亚书', 23, 23, 4, '西顿哪，你当惭愧；因为大海说，就是海中的保障说：我没有劬劳，也没有生产，没有养育男子，也没有抚养童女。'),
('CUV', '以赛亚书', 23, 23, 5, '这风声传到埃及；埃及人为推罗的风声极其疼痛。'),
('CUV', '以赛亚书', 23, 23, 6, '推罗人哪，你们当过到他施去；沿海的居民哪，你们都当哀号。'),
('CUV', '以赛亚书', 23, 23, 7, '这是你们欢乐的城，从上古而有的吗？其中的居民往远方寄居。'),
('CUV', '以赛亚书', 23, 23, 8, '推罗本是赐冠冕的。他的商家是王子；他的买卖人是世上的尊贵人。遭遇如此是谁定的呢？'),
('CUV', '以赛亚书', 23, 23, 9, '是万军之耶和华所定的！为要污辱一切高傲的荣耀，使地上一切的尊贵人被藐视。'),
('CUV', '以赛亚书', 23, 23, 10, '他施的民（原文是女）哪，可以流行你的地，好像尼罗河；不再有腰带拘紧你。'),
('CUV', '以赛亚书', 23, 23, 11, '耶和华已经向海伸手，震动列国。至于迦南，他已经吩咐拆毁其中的保障。'),
('CUV', '以赛亚书', 23, 23, 12, '他又说：受欺压西顿的居民（原文是处女）哪，你必不得再欢乐。起来！过到基提去；就是在那里也不得安歇。'),
('CUV', '以赛亚书', 23, 23, 13, '（看哪，迦勒底人之地向来没有这民，这国是亚述人为住旷野的人所立的。现在他们建筑戍楼，拆毁推罗的宫殿，使他成为荒凉。）'),
('CUV', '以赛亚书', 23, 23, 14, '他施的船只都要哀号，因为你们的保障变为荒场。'),
('CUV', '以赛亚书', 23, 23, 15, '到那时，推罗必被忘记七十年，照著一王的年日。七十年后，推罗的景况必像妓女所唱的歌：'),
('CUV', '以赛亚书', 23, 23, 16, '你这被忘记的妓女啊，拿琴周流城内，巧弹多唱，使人再想念你。'),
('CUV', '以赛亚书', 23, 23, 17, '七十年后，耶和华必眷顾推罗，他就仍得利息（原文是雇价；下同），与地上的万国交易（原文是行淫）。'),
('CUV', '以赛亚书', 23, 23, 18, '他的货财和利息要归耶和华为圣，必不积攒存留；因为他的货财必为住在耶和华面前的人所得，使他们吃饱，穿耐久的衣服。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 24, 1, '看哪，耶和华使地空虚，变为荒凉；又翻转大地，将居民分散。'),
('CUV', '以赛亚书', 23, 24, 2, '那时百姓怎样，祭司也怎样；仆人怎样，主人也怎样；婢女怎样，主母也怎样；买物的怎样，卖物的也怎样；放债的怎样，借债的也怎样；取利的怎样，出利的也怎样。'),
('CUV', '以赛亚书', 23, 24, 3, '地必全然空虚，尽都荒凉；因为这话是耶和华说的。'),
('CUV', '以赛亚书', 23, 24, 4, '地上悲哀衰残，世界败落衰残；地上居高位的人也败落了。'),
('CUV', '以赛亚书', 23, 24, 5, '地被其上的居民污秽；因为他们犯了律法，废了律例，背了永约。'),
('CUV', '以赛亚书', 23, 24, 6, '所以，地被咒诅吞灭；住在其上的显为有罪。地上的居民被火焚烧，剩下的人稀少。'),
('CUV', '以赛亚书', 23, 24, 7, '新酒悲哀，葡萄树衰残；心中欢乐的俱都叹息。'),
('CUV', '以赛亚书', 23, 24, 8, '击鼓之乐止息；宴乐人的声音完毕，弹琴之乐也止息了。'),
('CUV', '以赛亚书', 23, 24, 9, '人必不得饮酒唱歌；喝浓酒的，必以为苦。'),
('CUV', '以赛亚书', 23, 24, 10, '荒凉的城拆毁了；各家关门闭户，使人都不得进去。'),
('CUV', '以赛亚书', 23, 24, 11, '在街上因酒有悲叹的声音；一切喜乐变为昏暗；地上的欢乐归于无有。'),
('CUV', '以赛亚书', 23, 24, 12, '城中只有荒凉；城门拆毁净尽。'),
('CUV', '以赛亚书', 23, 24, 13, '在地上的万民中，必像打过的橄榄树，又像已摘的葡萄所剩无几。'),
('CUV', '以赛亚书', 23, 24, 14, '这些人要高声欢呼；他们为耶和华的威严，从海那里扬起声来。'),
('CUV', '以赛亚书', 23, 24, 15, '因此，你们要在东方荣耀耶和华；在众海岛荣耀耶和华─以色列神的名。'),
('CUV', '以赛亚书', 23, 24, 16, '我们听见从地极有人歌唱，说：荣耀归于义人。我却说：我消灭了！我消灭了，我有祸了！诡诈的行诡诈；诡诈的大行诡诈。'),
('CUV', '以赛亚书', 23, 24, 17, '地上的居民哪，恐惧、陷坑、网罗都临近你。'),
('CUV', '以赛亚书', 23, 24, 18, '躲避恐惧声音的必坠入陷坑；从陷坑上来的必被网罗缠住；因为天上的窗户都开了，地的根基也震动了。'),
('CUV', '以赛亚书', 23, 24, 19, '地全然破坏，尽都崩裂，大大地震动了。'),
('CUV', '以赛亚书', 23, 24, 20, '地要东倒西歪，好像醉酒的人；又摇来摇去，好像吊床。罪过在其上沉重，必然塌陷，不能复起。'),
('CUV', '以赛亚书', 23, 24, 21, '到那日，耶和华在高处必惩罚高处的众军，在地上必惩罚地上的列王。'),
('CUV', '以赛亚书', 23, 24, 22, '他们必被聚集，像囚犯被聚在牢狱中，并要囚在监牢里，多日之后便被讨罪（或译：眷顾）。'),
('CUV', '以赛亚书', 23, 24, 23, '那时，月亮要蒙羞，日头要惭愧；因为万军之耶和华必在锡安山，在耶路撒冷作王；在敬畏他的长老面前，必有荣耀。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 25, 1, '耶和华啊，你是我的神；我要尊崇你，我要称赞你的名。因为你以忠信诚实行过奇妙的事，成就你古时所定的。'),
('CUV', '以赛亚书', 23, 25, 2, '你使城变为乱堆，使坚固城变为荒场，使外邦人宫殿的城不再为城，永远不再建造。'),
('CUV', '以赛亚书', 23, 25, 3, '所以，刚强的民必荣耀你；强暴之国的城必敬畏你。'),
('CUV', '以赛亚书', 23, 25, 4, '因为当强暴人催逼人的时候，如同暴风直吹墙壁，你就作贫穷人的保障，作困乏人急难中的保障，作躲暴风之处，作避炎热的阴凉。'),
('CUV', '以赛亚书', 23, 25, 5, '你要压制外邦人的喧哗，好像干燥地的热气下落；禁止强暴人的凯歌，好像热气被云影消化。'),
('CUV', '以赛亚书', 23, 25, 6, '在这山上，万军之耶和华必为万民用肥甘设摆筵席，用陈酒和满髓的肥甘，并澄清的陈酒，设摆筵席。'),
('CUV', '以赛亚书', 23, 25, 7, '他又必在这山上除灭遮盖万民之物和遮蔽万国蒙脸的帕子。'),
('CUV', '以赛亚书', 23, 25, 8, '他已经吞灭死亡直到永远。主耶和华必擦去各人脸上的眼泪，又除掉普天下他百姓的羞辱，因为这是耶和华说的。'),
('CUV', '以赛亚书', 23, 25, 9, '到那日，人必说：看哪，这是我们的神；我们素来等候他，他必拯救我们。这是耶和华，我们素来等候他，我们必因他的救恩欢喜快乐。'),
('CUV', '以赛亚书', 23, 25, 10, '耶和华的手必按在这山上；摩押人在所居之地必被践踏，好像干草被践踏在粪池的水中。'),
('CUV', '以赛亚书', 23, 25, 11, '他必在其中伸开手，好像洑水的伸开手洑水一样；但耶和华必使他的骄傲和他手所行的诡计一并败落。'),
('CUV', '以赛亚书', 23, 25, 12, '耶和华使你城上的坚固高台倾倒，拆平，直到尘埃。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 26, 1, '当那日，在犹大地人必唱这歌说：我们有坚固的城。耶和华要将救恩定为城墙，为外郭。'),
('CUV', '以赛亚书', 23, 26, 2, '敞开城门，使守信的义民得以进入。'),
('CUV', '以赛亚书', 23, 26, 3, '坚心倚赖你的，你必保守他十分平安，因为他倚靠你。'),
('CUV', '以赛亚书', 23, 26, 4, '你们当倚靠耶和华直到永远，因为耶和华是永久的磐石。'),
('CUV', '以赛亚书', 23, 26, 5, '他使住高处的与高城一并败落，将城拆毁，拆平，直到尘埃，'),
('CUV', '以赛亚书', 23, 26, 6, '要被脚践踏，就是被困苦人的脚和穷乏人的脚践踏。'),
('CUV', '以赛亚书', 23, 26, 7, '义人的道是正直的；你为正直的主，必修平义人的路。'),
('CUV', '以赛亚书', 23, 26, 8, '耶和华啊，我们在你行审判的路上等候你；我们心里所羡慕的是你的名，就是你那可记念的名。'),
('CUV', '以赛亚书', 23, 26, 9, '夜间，我心中羡慕你；我里面的灵切切寻求你。因为你在世上行审判的时候，地上的居民就学习公义。'),
('CUV', '以赛亚书', 23, 26, 10, '以恩惠待恶人，他仍不学习公义；在正直的地上，他必行事不义，也不注意耶和华的威严。'),
('CUV', '以赛亚书', 23, 26, 11, '耶和华啊，你的手高举，他们仍然不看；却要看你为百姓发的热心，因而抱愧，并且有火烧灭你的敌人。'),
('CUV', '以赛亚书', 23, 26, 12, '耶和华啊，你必派定我们得平安，因为我们所做的事都是你给我们成就的。'),
('CUV', '以赛亚书', 23, 26, 13, '耶和华─我们的神啊，在你以外曾有别的主管辖我们，但我们专要倚靠你，提你的名。'),
('CUV', '以赛亚书', 23, 26, 14, '他们死了，必不能再活；他们去世，必不能再起；因为你刑罚他们，毁灭他们，他们的名号就全然消灭。'),
('CUV', '以赛亚书', 23, 26, 15, '耶和华啊，你增添国民，你增添国民；你得了荣耀，又扩张地的四境。'),
('CUV', '以赛亚书', 23, 26, 16, '耶和华啊，他们在急难中寻求你；你的惩罚临到他们身上，他们就倾心吐胆祷告你。'),
('CUV', '以赛亚书', 23, 26, 17, '妇人怀孕，临产疼痛，在痛苦之中喊叫；耶和华啊，我们在你面前也是如此。'),
('CUV', '以赛亚书', 23, 26, 18, '我们也曾怀孕疼痛，所产的竟像风一样。我们在地上未曾行甚么拯救的事；世上的居民也未曾败落。'),
('CUV', '以赛亚书', 23, 26, 19, '死人（原文是你的死人）要复活，尸首（原文是我的尸首）要兴起。睡在尘埃的啊，要醒起歌唱！因你的甘露好像菜蔬上的甘露，地也要交出死人来。'),
('CUV', '以赛亚书', 23, 26, 20, '我的百姓啊，你们要来进入内室，关上门，隐藏片时，等到忿怒过去。'),
('CUV', '以赛亚书', 23, 26, 21, '因为耶和华从他的居所出来，要刑罚地上居民的罪孽。地也必露出其中的血，不再掩盖被杀的人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 27, 1, '到那日，耶和华必用他刚硬有力的大刀刑罚鳄鱼─就是那快行的蛇，刑罚鳄鱼─就是那曲行的蛇，并杀海中的大鱼。'),
('CUV', '以赛亚书', 23, 27, 2, '当那日，有出酒的葡萄园，你们要指这园唱歌说：'),
('CUV', '以赛亚书', 23, 27, 3, '我─耶和华是看守葡萄园的；我必时刻浇灌，昼夜看守，免得有人损害。'),
('CUV', '以赛亚书', 23, 27, 4, '我心中不存忿怒。惟愿荆棘蒺藜与我交战，我就勇往直前，把他一同焚烧。'),
('CUV', '以赛亚书', 23, 27, 5, '不然，让他持住我的能力，使他与我和好，愿他与我和好。'),
('CUV', '以赛亚书', 23, 27, 6, '将来雅各要扎根，以色列要发芽开花；他们的果实必充满世界。'),
('CUV', '以赛亚书', 23, 27, 7, '主击打他们，岂像击打那些击打他们的人吗？他们被杀戮，岂像被他们所杀戮的吗？'),
('CUV', '以赛亚书', 23, 27, 8, '你打发他们去，是相机宜与他们相争；刮东风的日子，就用暴风将他们逐去。'),
('CUV', '以赛亚书', 23, 27, 9, '所以，雅各的罪孽得赦免，他的罪过得除掉的果效，全在乎此：就是他叫祭坛的石头变为打碎的灰石，以致木偶和日像不再立起。'),
('CUV', '以赛亚书', 23, 27, 10, '因为坚固城变为凄凉，成了撇下离弃的居所，像旷野一样；牛犊必在那里吃草，在那里躺卧，并吃尽其中的树枝。'),
('CUV', '以赛亚书', 23, 27, 11, '枝条枯干，必被折断；妇女要来点火烧著。因为这百姓蒙昧无知，所以，创造他们的必不怜恤他们；造成他们的也不施恩与他们。'),
('CUV', '以赛亚书', 23, 27, 12, '以色列人哪，到那日，耶和华必从大河，直到埃及小河，将你们一一地收集，如同人打树拾果一样。'),
('CUV', '以赛亚书', 23, 27, 13, '当那日，必大发角声，在亚述地将要灭亡的，并在埃及地被赶散的，都要来，他们就在耶路撒冷圣山上敬拜耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 28, 1, '祸哉！以法莲的酒徒，住在肥美谷的山上，他们心里高傲，以所夸的为冠冕，犹如将残之花。'),
('CUV', '以赛亚书', 23, 28, 2, '看哪，主有一大能大力者，像一阵冰雹，像毁灭的暴风，像涨溢的大水，他必用手将冠冕摔落于地。'),
('CUV', '以赛亚书', 23, 28, 3, '以法莲高傲的酒徒，他的冠冕必被踏在脚下。'),
('CUV', '以赛亚书', 23, 28, 4, '那荣美将残之花，就是在肥美谷山上的，必像夏令以前初熟的无花果；看见这果的就注意，一到手中就吞吃了。'),
('CUV', '以赛亚书', 23, 28, 5, '到那日，万军之耶和华必作他余剩之民的荣冠华冕，'),
('CUV', '以赛亚书', 23, 28, 6, '也作了在位上行审判者公平之灵，并城门口打退仇敌者的力量。'),
('CUV', '以赛亚书', 23, 28, 7, '就是这地的人也因酒摇摇晃晃，因浓酒东倒西歪。祭司和先知因浓酒摇摇晃晃，被酒所困，因浓酒东倒西歪。他们错解默示，谬行审判。'),
('CUV', '以赛亚书', 23, 28, 8, '因为各席上满了呕吐的污秽，无一处干净。'),
('CUV', '以赛亚书', 23, 28, 9, '讥诮先知的说：他要将知识指教谁呢？要使谁明白传言呢？是那刚断奶离怀的么？'),
('CUV', '以赛亚书', 23, 28, 10, '他竟命上加命，令上加令，律上加律，例上加例，这里一点，那里一点。'),
('CUV', '以赛亚书', 23, 28, 11, '先知说：不然，主要藉异邦人的嘴唇和外邦人的舌头对这百姓说话。'),
('CUV', '以赛亚书', 23, 28, 12, '他曾对他们说：你们要使疲乏人得安息，这样才得安息，才得舒畅，他们却不肯听。'),
('CUV', '以赛亚书', 23, 28, 13, '所以，耶和华向他们说的话是命上加命，令上加令，律上加律，例上加例，这里一点，那里一点，以致他们前行仰面跌倒，而且跌碎，并陷入网罗被缠住。'),
('CUV', '以赛亚书', 23, 28, 14, '所以，你们这些亵慢的人，就是辖管住在耶路撒冷这百姓的，要听耶和华的话。'),
('CUV', '以赛亚书', 23, 28, 15, '你们曾说：我们与死亡立约，与阴间结盟；敌军（原文是鞭子）如水涨漫经过的时候，必不临到我们；因我们以谎言为避所，在虚假以下藏身。'),
('CUV', '以赛亚书', 23, 28, 16, '所以，主耶和华如此说：看哪，我在锡安放一块石头作为根基，是试验过的石头，是稳固根基，宝贵的房角石；信靠的人必不著急。'),
('CUV', '以赛亚书', 23, 28, 17, '我必以公平为准绳，以公义为线铊。冰雹必冲去谎言的避所；大水必漫过藏身之处。'),
('CUV', '以赛亚书', 23, 28, 18, '你们与死亡所立的约必然废掉，与阴间所结的盟必立不住。敌军（原文是鞭子）如水涨漫经过的时候，你们必被他践踏；'),
('CUV', '以赛亚书', 23, 28, 19, '每逢经过必将你们掳去。因为每早晨他必经过，白昼黑夜都必如此。明白传言的必受惊恐。'),
('CUV', '以赛亚书', 23, 28, 20, '原来，床榻短，使人不能舒身；被窝窄，使人不能遮体。'),
('CUV', '以赛亚书', 23, 28, 21, '耶和华必兴起，像在毗拉心山；他必发怒，像在基遍谷，好做成他的工，就是非常的工；成就他的事，就是奇异的事。'),
('CUV', '以赛亚书', 23, 28, 22, '现在你们不可亵慢，恐怕捆你们的绑索更结实了；因为我从主─万军之耶和华那里听见，已经决定在全地上施行灭绝的事。'),
('CUV', '以赛亚书', 23, 28, 23, '你们当侧耳听我的声音，留心听我的言语。'),
('CUV', '以赛亚书', 23, 28, 24, '那耕地为要撒种的，岂是常常耕地呢？岂是常常开垦耙地呢？'),
('CUV', '以赛亚书', 23, 28, 25, '他拉平了地面，岂不就撒种小茴香，播种大茴香，按行列种小麦，在定处种大麦，在田边种粗麦呢？'),
('CUV', '以赛亚书', 23, 28, 26, '因为他的神教导他务农相宜，并且指教他。'),
('CUV', '以赛亚书', 23, 28, 27, '原来打小茴香，不用尖利的器具，轧大茴香，也不用碌碡（原文是车轮；下同）；但用杖打小茴香，用棍打大茴香。'),
('CUV', '以赛亚书', 23, 28, 28, '做饼的粮食是用磨磨碎，因他不必常打；虽用碌碡和马打散，却不磨他。'),
('CUV', '以赛亚书', 23, 28, 29, '这也是出于万军之耶和华─他的谋略奇妙；他的智慧广大。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 29, 1, '唉！亚利伊勒，亚利伊勒，大卫安营的城，任凭你年上加年，节期照常周流。'),
('CUV', '以赛亚书', 23, 29, 2, '我终必使亚利伊勒困难；他必悲伤哀号，我却仍以他为亚利伊勒。'),
('CUV', '以赛亚书', 23, 29, 3, '我必四围安营攻击你，屯兵围困你，筑垒攻击你。'),
('CUV', '以赛亚书', 23, 29, 4, '你必败落，从地中说话；你的言语必微细出于尘埃。你的声音必像那交鬼者的声音出于地；你的言语低低微微出于尘埃。'),
('CUV', '以赛亚书', 23, 29, 5, '你仇敌的群众，却要像细尘；强暴人的群众，也要像飞糠。这事必顷刻之间忽然临到。'),
('CUV', '以赛亚书', 23, 29, 6, '万军之耶和华必用雷轰、地震、大声、旋风、暴风，并吞灭的火燄，向他讨罪。'),
('CUV', '以赛亚书', 23, 29, 7, '那时，攻击亚利伊勒列国的群众，就是一切攻击亚利伊勒和他的保障，并使他困难的，必如梦景，如夜间的异象；'),
('CUV', '以赛亚书', 23, 29, 8, '又必像饥饿的人梦中吃饭，醒了仍觉腹空；或像口渴的人梦中喝水，醒了仍觉发昏，心里想喝。攻击锡安山列国的群众也必如此。'),
('CUV', '以赛亚书', 23, 29, 9, '你们等候惊奇吧！你们宴乐昏迷吧！他们醉了，却非因酒；他们东倒西歪，却非因浓酒。'),
('CUV', '以赛亚书', 23, 29, 10, '因为耶和华将沉睡的灵浇灌你们，封闭你们的眼，蒙盖你们的头。你们的眼就是先知；你们的头就是先见。'),
('CUV', '以赛亚书', 23, 29, 11, '所有的默示，你们看如封住的书卷，人将这书卷交给识字的，说：请念吧！他说：我不能念，因为是封住了。'),
('CUV', '以赛亚书', 23, 29, 12, '又将这书卷交给不识字的人，说：请念吧！他说：我不识字。'),
('CUV', '以赛亚书', 23, 29, 13, '主说：因为这百姓亲近我，用嘴唇尊敬我，心却远离我；他们敬畏我，不过是领受人的吩咐。'),
('CUV', '以赛亚书', 23, 29, 14, '所以，我在这百姓中要行奇妙的事，就是奇妙又奇妙的事。他们智慧人的智慧必然消灭，聪明人的聪明必然隐藏。'),
('CUV', '以赛亚书', 23, 29, 15, '祸哉！那些向耶和华深藏谋略的，又在暗中行事，说：谁看见我们呢？谁知道我们呢？'),
('CUV', '以赛亚书', 23, 29, 16, '你们把事颠倒了，岂可看窑匠如泥吗？被制作的物岂可论制作物的说：他没有制作我？或是被创造的物论造物的说：他没有聪明。'),
('CUV', '以赛亚书', 23, 29, 17, '利巴嫩变为肥田，肥田看如树林，不是只有一点点时候吗？'),
('CUV', '以赛亚书', 23, 29, 18, '那时，聋子必听见这书上的话；瞎子的眼必从迷蒙黑暗中得以看见。'),
('CUV', '以赛亚书', 23, 29, 19, '谦卑人必因耶和华增添欢喜；人间贫穷的必因以色列的圣者快乐。'),
('CUV', '以赛亚书', 23, 29, 20, '因为，强暴人已归无有，亵慢人已经灭绝，一切找机会作孽的都被剪除。'),
('CUV', '以赛亚书', 23, 29, 21, '他们在争讼的事上定无罪的为有罪，为城门口责备人的设下网罗，用虚无的事屈枉义人。'),
('CUV', '以赛亚书', 23, 29, 22, '所以，救赎亚伯拉罕的耶和华论雅各家如此说：雅各必不再羞愧，面容也不致变色。'),
('CUV', '以赛亚书', 23, 29, 23, '但他看见他的众子，就是我手的工作在他那里，他们必尊我的名为圣，必尊雅各的圣者为圣，必敬畏以色列的神。'),
('CUV', '以赛亚书', 23, 29, 24, '心中迷糊的必得明白；发怨言的必受训诲。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 30, 1, '耶和华说：祸哉！这悖逆的儿女。他们同谋，却不由于我，结盟，却不由于我的灵，以致罪上加罪；'),
('CUV', '以赛亚书', 23, 30, 2, '起身下埃及去，并没有求问我；要靠法老的力量加添自己的力量，并投在埃及的荫下。'),
('CUV', '以赛亚书', 23, 30, 3, '所以，法老的力量必作你们的羞辱；投在埃及的荫下，要为你们的惭愧。'),
('CUV', '以赛亚书', 23, 30, 4, '他们的首领已在琐安；他们的使臣到了哈内斯。'),
('CUV', '以赛亚书', 23, 30, 5, '他们必因那不利于他们的民蒙羞。那民并非帮助，也非利益，只作羞耻凌辱。'),
('CUV', '以赛亚书', 23, 30, 6, '论南方牲畜的默示：他们把财物驮在驴驹的脊背上，将宝物驮在骆驼的肉鞍上，经过艰难困苦之地，就是公狮、母狮、蝮蛇、火燄的飞龙之地，往那不利于他们的民那里去。'),
('CUV', '以赛亚书', 23, 30, 7, '埃及的帮助是徒然无益的；所以我称他为坐而不动的拉哈伯。'),
('CUV', '以赛亚书', 23, 30, 8, '现今你去，在他们面前将这话刻在版上，写在书上，以便传留后世，直到永永远远。'),
('CUV', '以赛亚书', 23, 30, 9, '因为他们是悖逆的百姓、说谎的儿女，不肯听从耶和华训诲的儿女。'),
('CUV', '以赛亚书', 23, 30, 10, '他们对先见说：不要望见不吉利的事，对先知说：不要向我们讲正直的话；要向我们说柔和的话，言虚幻的事。'),
('CUV', '以赛亚书', 23, 30, 11, '你们要离弃正道，偏离直路，不要在我们面前再提说以色列的圣者。'),
('CUV', '以赛亚书', 23, 30, 12, '所以，以色列的圣者如此说：因为你们藐视这训诲的话，倚赖欺压和乖僻，以此为可靠的，'),
('CUV', '以赛亚书', 23, 30, 13, '故此，这罪孽在你们身上，好像将要破裂凸出来的高墙，顷刻之间忽然坍塌；'),
('CUV', '以赛亚书', 23, 30, 14, '要被打碎，好像把窑匠的瓦器打碎，毫不顾惜，甚至碎块中找不到一片可用以从炉内取火，从池中舀水。'),
('CUV', '以赛亚书', 23, 30, 15, '主耶和华─以色列的圣者曾如此说：你们得救在乎归回安息；你们得力在乎平静安稳；你们竟自不肯。'),
('CUV', '以赛亚书', 23, 30, 16, '你们却说：不然，我们要骑马奔走。所以你们必然奔走；又说：我们要骑飞快的牲口。所以追赶你们的，也必飞快。'),
('CUV', '以赛亚书', 23, 30, 17, '一人叱喝，必令千人逃跑；五人叱喝，你们都必逃跑；以致剩下的，好像山顶的旗杆，冈上的大旗。'),
('CUV', '以赛亚书', 23, 30, 18, '耶和华必然等候，要施恩给你们；必然兴起，好怜悯你们。因为耶和华是公平的神；凡等候他的都是有福的！'),
('CUV', '以赛亚书', 23, 30, 19, '百姓必在锡安、在耶路撒冷居住；你不要哭泣。主必因你哀求的声音施恩给你；他听见的时候就必应允你。'),
('CUV', '以赛亚书', 23, 30, 20, '主虽以艰难给你当饼，以困苦给你当水，你的教师却不再隐藏；你眼必看见你的教师。'),
('CUV', '以赛亚书', 23, 30, 21, '你或向左或向右，你必听见后边有声音说：这是正路，要行在其间。'),
('CUV', '以赛亚书', 23, 30, 22, '你雕刻偶像所包的银子和铸造偶像所镀的金子，你要玷污，要抛弃，好像污秽之物，对偶像说：去罢！'),
('CUV', '以赛亚书', 23, 30, 23, '你将种子撒在地里，主必降雨在其上，并使地所出的粮肥美丰盛。到那时，你的牲畜必在宽阔的草场吃草。'),
('CUV', '以赛亚书', 23, 30, 24, '耕地的牛和驴驹必吃加盐的料；这料是用木杴和杈子扬净的。'),
('CUV', '以赛亚书', 23, 30, 25, '在大行杀戮的日子，高台倒塌的时候，各高山冈陵必有川流河涌。'),
('CUV', '以赛亚书', 23, 30, 26, '当耶和华缠裹他百姓的损处，医治他民鞭伤的日子，月光必像日光，日光必加七倍，像七日的光一样。'),
('CUV', '以赛亚书', 23, 30, 27, '看哪，耶和华的名从远方来，怒气烧起，密烟上腾。他的嘴唇满有忿恨；他的舌头像吞灭的火。'),
('CUV', '以赛亚书', 23, 30, 28, '他的气如涨溢的河水，直涨到颈项，要用毁灭的筛箩筛净列国，并且在众民的口中必有使人错行的嚼环。'),
('CUV', '以赛亚书', 23, 30, 29, '你们必唱歌，像守圣节的夜间一样，并且心中喜乐，像人吹笛，上耶和华的山，到以色列的磐石那里。'),
('CUV', '以赛亚书', 23, 30, 30, '耶和华必使人听他威严的声音，又显他降罚的膀臂和他怒中的忿恨，并吞灭的火燄与霹雷、暴风、冰雹。'),
('CUV', '以赛亚书', 23, 30, 31, '亚述人必因耶和华的声音惊惶；耶和华必用杖击打他。'),
('CUV', '以赛亚书', 23, 30, 32, '耶和华必将命定的杖加在他身上；每打一下，人必击鼓弹琴。打杖的时候，耶和华必抡起手来，与他交战。'),
('CUV', '以赛亚书', 23, 30, 33, '原来陀斐特又深又宽，早已为王预备好了；其中堆的是火与许多木柴。耶和华的气如一股硫磺火使他著起来。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 31, 1, '祸哉！那些下埃及求帮助的，是因仗赖马匹，倚靠甚多的车辆，并倚靠强壮的马兵，却不仰望以色列的圣者，也不求问耶和华。'),
('CUV', '以赛亚书', 23, 31, 2, '其实，耶和华有智慧；他必降灾祸，并不反悔自己的话，却要兴起攻击那作恶之家，又攻击那作孽帮助人的。'),
('CUV', '以赛亚书', 23, 31, 3, '埃及人不过是人，并不是神；他们的马不过是血肉，并不是灵。耶和华一伸手，那帮助人的必绊跌，那受帮助的也必跌倒，都一同灭亡。'),
('CUV', '以赛亚书', 23, 31, 4, '耶和华对我如此说：狮子和少壮狮子护食咆哮，就是喊许多牧人来攻击他，他总不因他们的声音惊惶，也不因他们的喧哗缩伏。如此，万军之耶和华也必降临在锡安山冈上争战。'),
('CUV', '以赛亚书', 23, 31, 5, '雀鸟怎样搧翅覆雏，万军之耶和华也要照样保护耶路撒冷。他必保护拯救，要越门保守。'),
('CUV', '以赛亚书', 23, 31, 6, '以色列人哪，你们深深地悖逆耶和华，现今要归向他。'),
('CUV', '以赛亚书', 23, 31, 7, '到那日，各人必将他金偶像银偶像，就是亲手所造、陷自己在罪中的，都抛弃了。'),
('CUV', '以赛亚书', 23, 31, 8, '亚述人必倒在刀下，并非人的刀；有刀要将他吞灭，并非人的刀。他必逃避这刀；他的少年人必成为服苦的。'),
('CUV', '以赛亚书', 23, 31, 9, '他的磐石必因惊吓挪去；他的首领必因大旗惊惶。这是那有火在锡安、有炉在耶路撒冷的耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 32, 1, '看哪，必有一王凭公义行政；必有首领藉公平掌权。'),
('CUV', '以赛亚书', 23, 32, 2, '必有一人像避风所和避暴雨的隐密处，又像河流在干旱之地，像大磐石的影子在疲乏之地。'),
('CUV', '以赛亚书', 23, 32, 3, '那能看的人，眼不再昏迷；能听的人，耳必得听闻。'),
('CUV', '以赛亚书', 23, 32, 4, '冒失人的心必明白知识；结巴人的舌必说话通快。'),
('CUV', '以赛亚书', 23, 32, 5, '愚顽人不再称为高明，吝啬人不再称为大方。'),
('CUV', '以赛亚书', 23, 32, 6, '因为愚顽人必说愚顽话，心里想作罪孽，惯行亵渎的事，说错谬的话攻击耶和华，使饥饿的人无食可吃，使口渴的人无水可喝。'),
('CUV', '以赛亚书', 23, 32, 7, '吝啬人所用的法子是恶的；他图谋恶计，用谎言毁灭谦卑人；穷乏人讲公理的时候，他也是这样行。'),
('CUV', '以赛亚书', 23, 32, 8, '高明人却谋高明事，在高明事上也必永存。'),
('CUV', '以赛亚书', 23, 32, 9, '安逸的妇女啊，起来听我的声音！无虑的女子啊，侧耳听我的言语！'),
('CUV', '以赛亚书', 23, 32, 10, '无虑的女子啊，再过一年多，必受骚扰；因为无葡萄可摘，无果子（或译：禾稼）可收。'),
('CUV', '以赛亚书', 23, 32, 11, '安逸的妇女啊，要战兢；无虑的女子啊，要受骚扰。脱去衣服，赤著身体，腰束麻布。'),
('CUV', '以赛亚书', 23, 32, 12, '他们必为美好的田地和多结果的葡萄树，搥胸哀哭。'),
('CUV', '以赛亚书', 23, 32, 13, '荆棘蒺藜必长在我百姓的地上，又长在欢乐的城中和一切快乐的房屋上。'),
('CUV', '以赛亚书', 23, 32, 14, '因为宫殿必被撇下，多民的城必被离弃；山冈望楼永为洞穴，作野驴所喜乐的，为羊群的草场。'),
('CUV', '以赛亚书', 23, 32, 15, '等到圣灵从上浇灌我们，旷野就变为肥田，肥田看如树林。'),
('CUV', '以赛亚书', 23, 32, 16, '那时，公平要居在旷野；公义要居在肥田。'),
('CUV', '以赛亚书', 23, 32, 17, '公义的果效必是平安；公义的效验必是平稳，直到永远。'),
('CUV', '以赛亚书', 23, 32, 18, '我的百姓必住在平安的居所，安稳的住处，平静的安歇所。'),
('CUV', '以赛亚书', 23, 32, 19, '（但要降冰雹打倒树林；城必全然拆平。）'),
('CUV', '以赛亚书', 23, 32, 20, '你们在各水边撒种、牧放牛驴的有福了！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 33, 1, '祸哉！你这毁灭人的，自己倒不被毁灭；行事诡诈的，人倒不以诡诈待你。你毁灭罢休了，自己必被毁灭；你行完了诡诈，人必以诡诈待你。'),
('CUV', '以赛亚书', 23, 33, 2, '耶和华啊，求你施恩于我们；我们等候你。求你每早晨作我们的膀臂，遭难的时候为我们的拯救。'),
('CUV', '以赛亚书', 23, 33, 3, '喧嚷的响声一发，众民奔逃；你一兴起，列国四散。'),
('CUV', '以赛亚书', 23, 33, 4, '你们所掳的必被敛尽，好像蚂蚱吃（原文是敛）尽禾稼。人要蹦在其上，好像蝗虫一样。'),
('CUV', '以赛亚书', 23, 33, 5, '耶和华被尊崇，因他居在高处；他以公平公义充满锡安。'),
('CUV', '以赛亚书', 23, 33, 6, '你一生一世必得安稳─有丰盛的救恩，并智慧和知识；你以敬畏耶和华为至宝。'),
('CUV', '以赛亚书', 23, 33, 7, '看哪，他们的豪杰在外头哀号；求和的使臣痛痛哭泣。'),
('CUV', '以赛亚书', 23, 33, 8, '大路荒凉，行人止息；敌人背约，藐视城邑，不顾人民。'),
('CUV', '以赛亚书', 23, 33, 9, '地上悲哀衰残；利巴嫩羞愧枯干；沙仑像旷野；巴珊和迦密的树林凋残。'),
('CUV', '以赛亚书', 23, 33, 10, '耶和华说：现在我要起来；我要兴起；我要勃然而兴。'),
('CUV', '以赛亚书', 23, 33, 11, '你们要怀的是糠秕，要生的是碎秸；你们的气就是吞灭自己的火。'),
('CUV', '以赛亚书', 23, 33, 12, '列邦必像已烧的石灰，像已割的荆棘在火中焚烧。'),
('CUV', '以赛亚书', 23, 33, 13, '你们远方的人当听我所行的；你们近处的人当承认我的大能。'),
('CUV', '以赛亚书', 23, 33, 14, '锡安中的罪人都惧怕；不敬虔的人被战兢抓住。我们中间谁能与吞灭的火同住？我们中间谁能与永火同住呢？'),
('CUV', '以赛亚书', 23, 33, 15, '行事公义、说话正直、憎恶欺压的财利、摆手不受贿赂、塞耳不听流血的话，闭眼不看邪恶事的，'),
('CUV', '以赛亚书', 23, 33, 16, '他必居高处；他的保障是磐石的坚垒；他的粮必不缺乏（原文是赐给）；他的水必不断绝。'),
('CUV', '以赛亚书', 23, 33, 17, '你的眼必见王的荣美，必见辽阔之地。'),
('CUV', '以赛亚书', 23, 33, 18, '你的心必思想那惊吓的事，自问说：记数目的在哪里呢？平贡银的在哪里呢？数戍楼的在哪里呢？'),
('CUV', '以赛亚书', 23, 33, 19, '你必不见那强暴的民，就是说话深奥，你不能明白，言语呢喃，你不能懂得的。'),
('CUV', '以赛亚书', 23, 33, 20, '你要看锡安─我们守圣节的城！你的眼必见耶路撒冷为安静的居所，为不挪移的帐幕，橛子永不拔出，绳索一根也不折断。'),
('CUV', '以赛亚书', 23, 33, 21, '在那里，耶和华必显威严与我们同在，当作江河宽阔之地；其中必没有荡桨摇橹的船来往，也没有威武的船经过。'),
('CUV', '以赛亚书', 23, 33, 22, '因为，耶和华是审判我们的；耶和华是给我们设律法的；耶和华是我们的王；他必拯救我们。'),
('CUV', '以赛亚书', 23, 33, 23, '你的绳索松开：不能栽稳桅杆，也不能扬起篷来。那时许多掳来的物被分了；瘸腿的把掠物夺去了。'),
('CUV', '以赛亚书', 23, 33, 24, '城内居民必不说：我病了；其中居住的百姓，罪孽都赦免了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 34, 1, '列国啊，要近前来听！众民哪，要侧耳而听！地和其上所充满的，世界和其中一切所出的都应当听！'),
('CUV', '以赛亚书', 23, 34, 2, '因为耶和华向万国发忿恨，向他们的全军发烈怒，将他们灭尽，交出他们受杀戮。'),
('CUV', '以赛亚书', 23, 34, 3, '被杀的必然抛弃，尸首臭气上腾；诸山被他们的血融化。'),
('CUV', '以赛亚书', 23, 34, 4, '天上的万象都要消没；天被卷起，好像书卷。其上的万象要残败，像葡萄树的叶子残败，又像无花果树的叶子残败一样。'),
('CUV', '以赛亚书', 23, 34, 5, '因为我的刀在天上已经喝足；这刀必临到以东和我所咒诅的民，要施行审判。'),
('CUV', '以赛亚书', 23, 34, 6, '耶和华的刀满了血，用脂油和羊羔、公山羊的血，并公绵羊腰子的脂油滋润的；因为耶和华在波斯拉有献祭的事，在以东地大行杀戮。'),
('CUV', '以赛亚书', 23, 34, 7, '野牛、牛犊，和公牛要一同下来。他们的地喝醉了血；他们的尘土因脂油肥润。'),
('CUV', '以赛亚书', 23, 34, 8, '因耶和华有报仇之日，为锡安的争辩有报应之年。'),
('CUV', '以赛亚书', 23, 34, 9, '以东的河水要变为石油，尘埃要变为硫磺；地土成为烧著的石油，'),
('CUV', '以赛亚书', 23, 34, 10, '昼夜总不熄灭，烟气永远上腾，必世世代代成为荒废，永永远远无人经过。'),
('CUV', '以赛亚书', 23, 34, 11, '鹈鹕、箭猪却要得为业；猫头鹰、乌鸦要住在其间。耶和华必将空虚的准绳，混沌的线铊，拉在其上。'),
('CUV', '以赛亚书', 23, 34, 12, '以东人要召贵胄来治国；那里却无一个，首领也都归于无有。'),
('CUV', '以赛亚书', 23, 34, 13, '以东的宫殿要长荆棘；保障要长蒺藜和刺草；要作野狗的住处，鸵鸟的居所。'),
('CUV', '以赛亚书', 23, 34, 14, '旷野的走兽要和豺狼相遇；野山羊要与伴偶对叫。夜间的怪物必在那里栖身，自找安歇之处。'),
('CUV', '以赛亚书', 23, 34, 15, '箭蛇要在那里做窝，下蛋，菢蛋，生子，聚子在其影下；鹞鹰各与伴偶聚集在那里。'),
('CUV', '以赛亚书', 23, 34, 16, '你们要查考宣读耶和华的书。这都无一缺少，无一没有伴偶；因为我的口已经吩咐，他的灵将他们聚集。'),
('CUV', '以赛亚书', 23, 34, 17, '他也为他们拈阄，又亲手用准绳给他们分地；他们必永得为业，世世代代住在其间。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 35, 1, '旷野和干旱之地必然欢喜；沙漠也必快乐；又像玫瑰开花，'),
('CUV', '以赛亚书', 23, 35, 2, '必开花繁盛，乐上加乐，而且欢呼。利巴嫩的荣耀，并迦密与沙仑的华美，必赐给他。人必看见耶和华的荣耀，我们神的华美。'),
('CUV', '以赛亚书', 23, 35, 3, '你们要使软弱的手坚壮，无力的膝稳固。'),
('CUV', '以赛亚书', 23, 35, 4, '对胆怯的人说：你们要刚强，不要惧怕。看哪，你们的神必来报仇，必来施行极大的报应；他必来拯救你们。'),
('CUV', '以赛亚书', 23, 35, 5, '那时，瞎子的眼必睁开；聋子的耳必开通。'),
('CUV', '以赛亚书', 23, 35, 6, '那时，瘸子必跳跃像鹿；哑巴的舌头必能歌唱。在旷野必有水发出；在沙漠必有河涌流。'),
('CUV', '以赛亚书', 23, 35, 7, '发光的沙（或译：蜃楼）要变为水池；干渴之地要变为泉源。在野狗躺卧之处，必有青草、芦苇，和蒲草。'),
('CUV', '以赛亚书', 23, 35, 8, '在那里必有一条大道，称为圣路。污秽人不得经过，必专为赎民行走；行路的人虽愚昧，也不致失迷。'),
('CUV', '以赛亚书', 23, 35, 9, '在那里必没有狮子，猛兽也不登这路；在那里都遇不见，只有赎民在那里行走。'),
('CUV', '以赛亚书', 23, 35, 10, '并且耶和华救赎的民必归回，歌唱来到锡安；永乐必归到他们的头上；他们必得著欢喜快乐，忧愁叹息尽都逃避。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 36, 1, '希西家王十四年，亚述王西拿基立上来攻击犹大的一切坚固城，将城攻取。'),
('CUV', '以赛亚书', 23, 36, 2, '亚述王从拉吉差遣拉伯沙基率领大军往耶路撒冷，到希西家王那里去。他就站在上池的水沟旁，在漂布地的大路上。'),
('CUV', '以赛亚书', 23, 36, 3, '于是希勒家的儿子家宰以利亚敬，并书记舍伯那和亚萨的儿子史官约亚，出来见拉伯沙基。'),
('CUV', '以赛亚书', 23, 36, 4, '拉伯沙基对他们说：你们去告诉希西家说，亚述大王如此说：你所倚靠的有甚么可仗赖的呢？'),
('CUV', '以赛亚书', 23, 36, 5, '你说，有打仗的计谋和能力，我看不过是虚话。你到底倚靠谁才背叛我呢？'),
('CUV', '以赛亚书', 23, 36, 6, '看哪，你所倚靠的埃及是那压伤的苇杖，人若靠这杖，就必刺透他的手。埃及王法老向一切倚靠他的人也是这样。'),
('CUV', '以赛亚书', 23, 36, 7, '你若对我说：我们倚靠耶和华─我们的神。希西家岂不是将神的邱坛和祭坛废去，且对犹大和耶路撒冷的人说：你们当在这坛前敬拜么？'),
('CUV', '以赛亚书', 23, 36, 8, '现在你把当头给我主亚述王，我给你二千匹马，看你这一面骑马的人够不够。'),
('CUV', '以赛亚书', 23, 36, 9, '若不然，怎能打败我主臣仆中最小的军长呢？你竟倚靠埃及的战车马兵么？'),
('CUV', '以赛亚书', 23, 36, 10, '现在我上来攻击毁灭这地，岂没有耶和华的意思么？耶和华吩咐我说，你上去攻击毁灭这地罢！'),
('CUV', '以赛亚书', 23, 36, 11, '以利亚敬、舍伯那、约亚对拉伯沙基说：求你用亚兰言语和仆人说话，因为我们懂得；不要用犹大言语和我们说话，达到城上百姓的耳中。'),
('CUV', '以赛亚书', 23, 36, 12, '拉伯沙基说：我主差遣我来，岂是单对你和你的主说这些话么？不也是对这些坐在城上、要与你们一同吃自己粪喝自己尿的人说么？'),
('CUV', '以赛亚书', 23, 36, 13, '于是，拉伯沙基站著，用犹大言语大声喊著说：你们当听亚述大王的话。'),
('CUV', '以赛亚书', 23, 36, 14, '王如此说：你们不要被希西家欺哄了，因他不能拯救你们。'),
('CUV', '以赛亚书', 23, 36, 15, '也不要听希西家使你们倚靠耶和华说：耶和华必要拯救我们，这城必不交在亚述王的手中。'),
('CUV', '以赛亚书', 23, 36, 16, '不要听希西家的话，因亚述王如此说：你们要与我和好。出来投降我，各人就可以吃自己葡萄树和无花果树的果子，喝自己井里的水。'),
('CUV', '以赛亚书', 23, 36, 17, '等我来领你们到一个地方，与你们本地一样，就是有五壳和新酒之地，有粮食和葡萄园之地。'),
('CUV', '以赛亚书', 23, 36, 18, '你们要谨防，恐怕希西家劝导你们说：耶和华必拯救我们。列国的神有哪一个救他本国脱离亚述王的手呢？'),
('CUV', '以赛亚书', 23, 36, 19, '哈马和亚珥拔的神在哪里呢？西法瓦音的神在哪里呢？他们曾救撒玛利亚脱离我的手么？'),
('CUV', '以赛亚书', 23, 36, 20, '这些国的神有谁曾救自己的国脱离我的手呢？难道耶和华能救耶路撒冷脱离我的手么？'),
('CUV', '以赛亚书', 23, 36, 21, '百姓静默不言，并不回答一句，因为王曾吩咐说：不要回答他。'),
('CUV', '以赛亚书', 23, 36, 22, '当下希勒家的儿子家宰以利亚敬和书记舍伯那，并亚萨的儿子史官约亚，都撕裂衣服，来到希西家那里，将拉伯沙基的话告诉了他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 37, 1, '希西家王听见就撕裂衣服，披上麻布，进了耶和华的殿，'),
('CUV', '以赛亚书', 23, 37, 2, '使家宰以利亚敬和书记舍伯那，并祭司中的长老，都披上麻布，去见亚摩斯的儿子先知以赛亚，'),
('CUV', '以赛亚书', 23, 37, 3, '对他说：希西家如此说：今日是急难、责罚、凌辱的日子，就如妇人将要生产婴孩，却没有力量生产。'),
('CUV', '以赛亚书', 23, 37, 4, '或者耶和华─你的神听见拉伯沙基的话，就是他主人亚述王打发他来辱骂永生神的话；耶和华─你的神听见这话就发斥责。故此，求你为余剩的民扬声祷告。'),
('CUV', '以赛亚书', 23, 37, 5, '希西家王的臣仆就去见以赛亚。'),
('CUV', '以赛亚书', 23, 37, 6, '以赛亚对他们说：要这样对你们的主人说，耶和华如此说：你听见亚述王的仆人亵渎我的话，不要惧怕。'),
('CUV', '以赛亚书', 23, 37, 7, '我必惊动（原文是使灵进入）他的心；他要听见风声就归回本地，我必使他在那里倒在刀下。'),
('CUV', '以赛亚书', 23, 37, 8, '拉伯沙基回去，正遇见亚述王攻打立拿；原来他早听见亚述王拔营离开拉吉。'),
('CUV', '以赛亚书', 23, 37, 9, '亚述王听见人论古实王特哈加说：他出来要与你争战。亚述王一听见，就打发使者去见希西家，吩咐他们说：'),
('CUV', '以赛亚书', 23, 37, 10, '你们对犹大王希西家如此说：不要听你所倚靠的神欺哄你说：耶路撒冷必不交在亚述王的手中。'),
('CUV', '以赛亚书', 23, 37, 11, '你总听说亚述诸王向列国所行的乃是尽行灭绝，难道你还能得救吗？'),
('CUV', '以赛亚书', 23, 37, 12, '我列祖所毁灭的，就是歌散、哈兰、利色，和属提拉撒的伊甸人；这些国的神何曾拯救这些国呢？'),
('CUV', '以赛亚书', 23, 37, 13, '哈马的王，亚珥拔的王，西法瓦音城的王，希拿和以瓦的王，都在哪里呢？'),
('CUV', '以赛亚书', 23, 37, 14, '希西家从使者手里接过书信来，看完了，就上耶和华的殿，将书信在耶和华面前展开。'),
('CUV', '以赛亚书', 23, 37, 15, '希西家向耶和华祷告说：'),
('CUV', '以赛亚书', 23, 37, 16, '坐在二基路伯上万军之耶和华─以色列的神啊，你─惟有你是天下万国的神，你曾创造天地。'),
('CUV', '以赛亚书', 23, 37, 17, '耶和华啊，求你侧耳而听；耶和华啊，求你睁眼而看，要听西拿基立的一切话，他是打发使者来辱骂永生神的。'),
('CUV', '以赛亚书', 23, 37, 18, '耶和华啊，亚述诸王果然使列国和列国之地变为荒凉，'),
('CUV', '以赛亚书', 23, 37, 19, '将列国的神像都扔在火里；因为他本不是神，乃是人手所造的，是木头、石头的，所以灭绝他。'),
('CUV', '以赛亚书', 23, 37, 20, '耶和华─我们的神啊，现在求你救我们脱离亚述王的手，使天下万国都知道唯有你是耶和华。'),
('CUV', '以赛亚书', 23, 37, 21, '亚摩斯的儿子以赛亚就打发人去见希西家，说：耶和华─以色列的神如此说，你既然求我攻击亚述王西拿基立，'),
('CUV', '以赛亚书', 23, 37, 22, '所以耶和华论他这样说：锡安的处女藐视你，嗤笑你；耶路撒冷的女子向你摇头。'),
('CUV', '以赛亚书', 23, 37, 23, '你辱骂谁，亵渎谁？扬起声来，高举眼目攻击谁呢？乃是攻击以色列的圣者。'),
('CUV', '以赛亚书', 23, 37, 24, '你藉你的臣仆辱骂主说：我率领许多战车上山顶，到利巴嫩极深之处；我要砍伐其中高大的香柏树和佳美的松树。我必上极高之处，进入肥田的树林。'),
('CUV', '以赛亚书', 23, 37, 25, '我已经挖井喝水；我必用脚掌踏干埃及的一切河。'),
('CUV', '以赛亚书', 23, 37, 26, '耶和华说：你岂没有听见我早先所做的，古时所立的吗？现在藉你使坚固城荒废，变为乱堆。'),
('CUV', '以赛亚书', 23, 37, 27, '所以其中的居民力量甚小，惊惶羞愧。他们像野草，像青菜，如房顶上的草，又如田间未长成的禾稼。'),
('CUV', '以赛亚书', 23, 37, 28, '你坐下，你出去，你进来，你向我发烈怒，我都知道。'),
('CUV', '以赛亚书', 23, 37, 29, '因你向我发烈怒，又因你狂傲的话达到我耳中，我就要用钩子钩上你的鼻子，把嚼环放在你口里，使你从原路转回去。'),
('CUV', '以赛亚书', 23, 37, 30, '以色列人哪，我赐你们一个证据：你们今年要吃自生的，明年也要吃自长的，至于后年，你们要耕种收割，栽植葡萄园，吃其中的果子。'),
('CUV', '以赛亚书', 23, 37, 31, '犹大家所逃脱余剩的，仍要往下扎根，向上结果。'),
('CUV', '以赛亚书', 23, 37, 32, '必有余剩的民从耶路撒冷而出；必有逃脱的人从锡安山而来。万军之耶和华的热心必成就这事。'),
('CUV', '以赛亚书', 23, 37, 33, '所以耶和华论亚述王如此说：他必不得来到这城，也不在这里射箭，不得拿盾牌到城前，也不筑垒攻城。'),
('CUV', '以赛亚书', 23, 37, 34, '他从哪条路来，必从那条路回去，必不得来到这城。这是耶和华说的。'),
('CUV', '以赛亚书', 23, 37, 35, '因我为自己的缘故，又为我仆人大卫的缘故，必保护拯救这城。'),
('CUV', '以赛亚书', 23, 37, 36, '耶和华的使者出去，在亚述营中杀了十八万五千人。清早有人起来一看，都是死尸了。'),
('CUV', '以赛亚书', 23, 37, 37, '亚述王西拿基立就拔营回去，住在尼尼微。'),
('CUV', '以赛亚书', 23, 37, 38, '一日在他的神─尼斯洛庙里叩拜，他儿子亚得米勒和沙利色用刀杀了他，就逃到亚拉腊地。他儿子以撒哈顿接续他作王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 38, 1, '那时希西家病得要死，亚摩斯的儿子先知以赛亚去见他，对他说：耶和华如此说：你当留遗命与你的家，因为你必死不能活了。'),
('CUV', '以赛亚书', 23, 38, 2, '希西家就转脸朝墙，祷告耶和华说：'),
('CUV', '以赛亚书', 23, 38, 3, '耶和华啊，求你记念我在你面前怎样存完全的心，按诚实行事，又做你眼中所看为善的。希西家就痛哭了。'),
('CUV', '以赛亚书', 23, 38, 4, '耶和华的话临到以赛亚说：'),
('CUV', '以赛亚书', 23, 38, 5, '你去告诉希西家说，耶和华─你祖大卫的神如此说：我听见了你的祷告，看见了你的眼泪。我必加增你十五年的寿数；'),
('CUV', '以赛亚书', 23, 38, 6, '并且我要救你和这城脱离亚述王的手，也要保护这城。'),
('CUV', '以赛亚书', 23, 38, 7, '我─耶和华必成就我所说的。我先给你一个兆头，'),
('CUV', '以赛亚书', 23, 38, 8, '就是叫亚哈斯的日晷，向前进的日影往后退十度。于是，前进的日影果然在日晷上往后退了十度。'),
('CUV', '以赛亚书', 23, 38, 9, '犹大王希西家患病已经痊愈，就作诗说：'),
('CUV', '以赛亚书', 23, 38, 10, '我说：正在我中年（或译：晌午）之日必进入阴间的门；我余剩的年岁不得享受。'),
('CUV', '以赛亚书', 23, 38, 11, '我说：我必不得见耶和华，就是在活人之地不见耶和华；我与世上的居民不再见面。'),
('CUV', '以赛亚书', 23, 38, 12, '我的住处被迁去离开我，好像牧人的帐棚一样；我将性命卷起，像织布的卷布一样。耶和华必将我从机头剪断，从早到晚，他要使我完结。'),
('CUV', '以赛亚书', 23, 38, 13, '我使自己安静直到天亮；他像狮子折断我一切的骨头，从早到晚，他要使我完结。'),
('CUV', '以赛亚书', 23, 38, 14, '我像燕子呢喃，像白鹤鸣叫，又像鸽子哀鸣；我因仰观，眼睛困倦。耶和华啊，我受欺压，求你为我作保。'),
('CUV', '以赛亚书', 23, 38, 15, '我可说甚么呢？他应许我的，也给我成就了。我因心里的苦楚，在一生的年日必悄悄而行。'),
('CUV', '以赛亚书', 23, 38, 16, '主啊，人得存活乃在乎此。我灵存活也全在此。所以求你使我痊愈，仍然存活。'),
('CUV', '以赛亚书', 23, 38, 17, '看哪，我受大苦，本为使我得平安；你因爱我的灵魂（或译：生命）便救我脱离败坏的坑，因为你将我一切的罪扔在你的背后。'),
('CUV', '以赛亚书', 23, 38, 18, '原来，阴间不能称谢你，死亡不能颂扬你；下坑的人不能盼望你的诚实。'),
('CUV', '以赛亚书', 23, 38, 19, '只有活人，活人必称谢你，像我今日称谢你一样。为父的，必使儿女知道你的诚实。'),
('CUV', '以赛亚书', 23, 38, 20, '耶和华肯救我，所以，我们要一生一世在耶和华殿中用丝弦的乐器唱我的诗歌。'),
('CUV', '以赛亚书', 23, 38, 21, '以赛亚说：当取一块无花果饼来，贴在疮上，王必痊愈。'),
('CUV', '以赛亚书', 23, 38, 22, '希西家问说：我能上耶和华的殿，有甚么兆头呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 39, 1, '那时，巴比伦王巴拉但的儿子米罗达巴拉但听见希西家病而痊愈，就送书信和礼物给他。'),
('CUV', '以赛亚书', 23, 39, 2, '希西家喜欢见使者，就把自己宝库的金子、银子、香料、贵重的膏油，和他武库的一切军器，并所有的财宝都给他们看；他家中和全国之内，希西家没有一样不给他们看的。'),
('CUV', '以赛亚书', 23, 39, 3, '于是先知以赛亚来见希西家王，问他说：这些人说甚么？他们从哪里来见你？希西家说：他们从远方的巴比伦来见我。'),
('CUV', '以赛亚书', 23, 39, 4, '以赛亚说：他们在你家里看见了甚么？希西家说：凡我家中所有的，他们都看见了；我财宝中没有一样不给他们看的。'),
('CUV', '以赛亚书', 23, 39, 5, '以赛亚对希西家说：你要听万军之耶和华的话：'),
('CUV', '以赛亚书', 23, 39, 6, '日子必到，凡你家里所有的，并你列祖积蓄到如今的，都要被掳到巴比伦去，不留下一样；这是耶和华说的。'),
('CUV', '以赛亚书', 23, 39, 7, '并且从你本身所生的众子，其中必有被掳去、在巴比伦王宫里当太监的。'),
('CUV', '以赛亚书', 23, 39, 8, '希西家对以赛亚说：你所说耶和华的话甚好，因为在我的年日中必有太平和稳固的景况。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 40, 1, '你们的神说：你们要安慰，安慰我的百姓。'),
('CUV', '以赛亚书', 23, 40, 2, '要对耶路撒冷说安慰的话，又向他宣告说，他争战的日子已满了；他的罪孽赦免了；他为自己的一切罪，从耶和华手中加倍受罚。'),
('CUV', '以赛亚书', 23, 40, 3, '有人声喊著说：在旷野预备耶和华的路（或译：在旷野，有人声喊著说：当预备耶和华的路），在沙漠地修平我们神的道。'),
('CUV', '以赛亚书', 23, 40, 4, '一切山洼都要填满，大小山冈都要削平；高高低低的要改为平坦，崎崎岖岖的必成为平原。'),
('CUV', '以赛亚书', 23, 40, 5, '耶和华的荣耀必然显现；凡有血气的必一同看见；因为这是耶和华亲口说的。'),
('CUV', '以赛亚书', 23, 40, 6, '有人声说：你喊叫罢！有一个说：我喊叫甚么呢？说：凡有血气的尽都如草；他的美容都像野地的花。'),
('CUV', '以赛亚书', 23, 40, 7, '草必枯干，花必凋残，因为耶和华的气吹在其上；百姓诚然是草。'),
('CUV', '以赛亚书', 23, 40, 8, '草必枯干，花必凋残，惟有我们神的话必永远立定。'),
('CUV', '以赛亚书', 23, 40, 9, '报好信息给锡安的啊，你要登高山；报好信息给耶路撒冷的啊，你要极力扬声。扬声不要惧怕，对犹大的城邑说：看哪，你们的神！'),
('CUV', '以赛亚书', 23, 40, 10, '主耶和华必像大能者临到；他的膀臂必为他掌权。他的赏赐在他那里；他的报应在他面前。'),
('CUV', '以赛亚书', 23, 40, 11, '他必像牧人牧养自己的羊群，用膀臂聚集羊羔抱在怀中，慢慢引导那乳养小羊的。'),
('CUV', '以赛亚书', 23, 40, 12, '谁曾用手心量诸水，用手虎口量苍天，用升斗盛大地的尘土，用秤称山岭，用天平平冈陵呢？'),
('CUV', '以赛亚书', 23, 40, 13, '谁曾测度耶和华的心（或译：谁曾指示耶和华的灵），或作他的谋士指教他呢？'),
('CUV', '以赛亚书', 23, 40, 14, '他与谁商议，谁教导他，谁将公平的路指示他，又将知识教训他，将通达的道指教他呢？'),
('CUV', '以赛亚书', 23, 40, 15, '看哪，万民都像水桶的一滴，又算如天平上的微尘；他举起众海岛，好像极微之物。'),
('CUV', '以赛亚书', 23, 40, 16, '利巴嫩的树林不够当柴烧；其中的走兽也不够作燔祭。'),
('CUV', '以赛亚书', 23, 40, 17, '万民在他面前好像虚无，被他看为不及虚无，乃为虚空。'),
('CUV', '以赛亚书', 23, 40, 18, '你们究竟将谁比神，用甚么形像与神比较呢？'),
('CUV', '以赛亚书', 23, 40, 19, '偶像是匠人铸造，银匠用金包裹，为他铸造银链。'),
('CUV', '以赛亚书', 23, 40, 20, '穷乏献不起这样供物的，就拣选不能朽坏的树木，为自己寻找巧匠，立起不能摇动的偶像。'),
('CUV', '以赛亚书', 23, 40, 21, '你们岂不曾知道么？你们岂不曾听见么？从起初岂没有人告诉你们么？自从立地的根基，你们岂没有明白么？'),
('CUV', '以赛亚书', 23, 40, 22, '神坐在地球大圈之上；地上的居民好像蝗虫。他铺张穹苍如幔子，展开诸天如可住的帐棚。'),
('CUV', '以赛亚书', 23, 40, 23, '他使君王归于虚无，使地上的审判官成为虚空。'),
('CUV', '以赛亚书', 23, 40, 24, '他们是刚才（或译：不曾；下同）栽上，刚才种上，根也刚才扎在地里，他一吹在其上，便都枯干；旋风将他们吹去，像碎秸一样。'),
('CUV', '以赛亚书', 23, 40, 25, '那圣者说：你们将谁比我，叫他与我相等呢？'),
('CUV', '以赛亚书', 23, 40, 26, '你们向上举目，看谁创造这万象，按数目领出，他一一称其名；因他的权能，又因他的大能大力，连一个都不缺。'),
('CUV', '以赛亚书', 23, 40, 27, '雅各啊，你为何说，我的道路向耶和华隐藏？以色列啊，你为何言，我的冤屈神并不查问？'),
('CUV', '以赛亚书', 23, 40, 28, '你岂不曾知道么？你岂不曾听见么？永在的神耶和华，创造地极的主，并不疲乏，也不困倦；他的智慧无法测度。'),
('CUV', '以赛亚书', 23, 40, 29, '疲乏的，他赐能力；软弱的，他加力量。'),
('CUV', '以赛亚书', 23, 40, 30, '就是少年人也要疲乏困倦；强壮的也必全然跌倒。'),
('CUV', '以赛亚书', 23, 40, 31, '但那等候耶和华的必从新得力。他们必如鹰展翅上腾；他们奔跑却不困倦，行走却不疲乏。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 41, 1, '众海岛啊，当在我面前静默；众民当从新得力，都要近前来才可以说话，我们可以彼此辩论。'),
('CUV', '以赛亚书', 23, 41, 2, '谁从东方兴起一人，凭公义召他来到脚前呢？耶和华将列国交给他，使他管辖君王，把他们如灰尘交与他的刀，如风吹的碎秸交与他的弓。'),
('CUV', '以赛亚书', 23, 41, 3, '他追赶他们，走他所未走的道，坦然前行。'),
('CUV', '以赛亚书', 23, 41, 4, '谁行做成就这事，从起初宣召历代呢？就是我─耶和华！我是首先的，也与末后的同在。'),
('CUV', '以赛亚书', 23, 41, 5, '海岛看见就都害怕；地极也都战兢，就近前来。'),
('CUV', '以赛亚书', 23, 41, 6, '他们各人帮助邻舍，各人对弟兄说：壮胆罢！'),
('CUV', '以赛亚书', 23, 41, 7, '木匠勉励银匠，用锤打光的勉励打砧的，论銲工说，銲得好；又用钉子钉稳，免得偶像动摇。'),
('CUV', '以赛亚书', 23, 41, 8, '惟你以色列─我的仆人，雅各─我所拣选的，我朋友亚伯拉罕的后裔，'),
('CUV', '以赛亚书', 23, 41, 9, '你是我从地极所领（原文是抓）来的，从地角所召来的，且对你说：你是我的仆人；我拣选你，并不弃绝你。'),
('CUV', '以赛亚书', 23, 41, 10, '你不要害怕，因为我与你同在；不要惊惶，因为我是你的神。我必坚固你，我必帮助你；我必用我公义的右手扶持你。'),
('CUV', '以赛亚书', 23, 41, 11, '凡向你发怒的必都抱愧蒙羞；与你相争的必如无有，并要灭亡。'),
('CUV', '以赛亚书', 23, 41, 12, '与你争竞的，你要找他们也找不著；与你争战的必如无有，成为虚无。'),
('CUV', '以赛亚书', 23, 41, 13, '因为我耶和华─你的神必搀扶你的右手，对你说：不要害怕！我必帮助你。'),
('CUV', '以赛亚书', 23, 41, 14, '你这虫雅各和你们以色列人，不要害怕！耶和华说：我必帮助你。你的救赎主就是以色列的圣者。'),
('CUV', '以赛亚书', 23, 41, 15, '看哪，我已使你成为有快齿打粮的新器具；你要把山岭打得粉碎，使冈陵如同糠秕。'),
('CUV', '以赛亚书', 23, 41, 16, '你要把他簸扬，风要吹去；旋风要把他刮散。你倒要以耶和华为喜乐，以色列的圣者为夸耀。'),
('CUV', '以赛亚书', 23, 41, 17, '困苦穷乏人寻求水却没有；他们因口渴，舌头干燥。我─耶和华必应允他们；我─以色列的神必不离弃他们。'),
('CUV', '以赛亚书', 23, 41, 18, '我要在净光的高处开江河，在谷中开泉源；我要使沙漠变为水池，使干地变为涌泉。'),
('CUV', '以赛亚书', 23, 41, 19, '我要在旷野种上香柏树、皂荚树、番石榴树，和野橄榄树。我在沙漠要把松树、杉树，并黄杨树一同栽植；'),
('CUV', '以赛亚书', 23, 41, 20, '好叫人看见、知道、思想、明白；这是耶和华的手所做的，是以色列的圣者所造的。'),
('CUV', '以赛亚书', 23, 41, 21, '耶和华对假神说：你们要呈上你们的案件；雅各的君说：你们要声明你们确实的理由。'),
('CUV', '以赛亚书', 23, 41, 22, '可以声明，指示我们将来必遇的事，说明先前的是甚么事，好叫我们思索，得知事的结局，或者把将来的事指示我们。'),
('CUV', '以赛亚书', 23, 41, 23, '要说明后来的事，好叫我们知道你们是神。你们或降福，或降祸，使我们惊奇，一同观看。'),
('CUV', '以赛亚书', 23, 41, 24, '看哪，你们属乎虚无；你们的作为也属乎虚空。那选择你们的是可憎恶的。'),
('CUV', '以赛亚书', 23, 41, 25, '我从北方兴起一人；他是求告我名的，从日出之地而来。他必临到掌权的，好像临到灰泥，仿佛窑匠踹泥一样。'),
('CUV', '以赛亚书', 23, 41, 26, '谁从起初指明这事，使我们知道呢？谁从先前说明，使我们说他不错呢？谁也没有指明，谁也没有说明。谁也没有听见你们的话。'),
('CUV', '以赛亚书', 23, 41, 27, '我首先对锡安说：看哪，我要将一位报好信息的赐给耶路撒冷。'),
('CUV', '以赛亚书', 23, 41, 28, '我看的时候并没有人；我问的时候，他们中间也没有谋士可以回答一句。'),
('CUV', '以赛亚书', 23, 41, 29, '看哪，他们和他们的工作都是虚空，且是虚无。他们所铸的偶像都是风，都是虚的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 42, 1, '看哪，我的仆人─我所扶持所拣选、心里所喜悦的！我已将我的灵赐给他；他必将公理传给外邦。'),
('CUV', '以赛亚书', 23, 42, 2, '他不喧嚷，不扬声，也不使街上听见他的声音。'),
('CUV', '以赛亚书', 23, 42, 3, '压伤的芦苇，他不折断；将残的灯火，他不吹灭。他凭真实将公理传开。'),
('CUV', '以赛亚书', 23, 42, 4, '他不灰心，也不丧胆，直到他在地上设立公理；海岛都等候他的训诲。'),
('CUV', '以赛亚书', 23, 42, 5, '创造诸天，铺张穹苍，将地和地所出的一并铺开，赐气息给地上的众人，又赐灵性给行在其上之人的神耶和华，他如此说：'),
('CUV', '以赛亚书', 23, 42, 6, '我─耶和华凭公义召你，必搀扶你的手，保守你，使你作众民的中保（中保：原文是约），作外邦人的光，'),
('CUV', '以赛亚书', 23, 42, 7, '开瞎子的眼，领被囚的出牢狱，领坐黑暗的出监牢。'),
('CUV', '以赛亚书', 23, 42, 8, '我是耶和华，这是我的名；我必不将我的荣耀归给假神，也不将我的称赞归给雕刻的偶像。'),
('CUV', '以赛亚书', 23, 42, 9, '看哪，先前的事已经成就，现在我将新事说明，这事未发以先，我就说给你们听。'),
('CUV', '以赛亚书', 23, 42, 10, '航海的和海中所有的，海岛和其上的居民，都当向耶和华唱新歌，从地极赞美他。'),
('CUV', '以赛亚书', 23, 42, 11, '旷野和其中的城邑，并基达人居住的村庄都当扬声；西拉的居民当欢呼，在山顶上呐喊。'),
('CUV', '以赛亚书', 23, 42, 12, '他们当将荣耀归给耶和华，在海岛中传扬他的颂赞。'),
('CUV', '以赛亚书', 23, 42, 13, '耶和华必像勇士出去，必像战士激动热心，要喊叫，大声呐喊，要用大力攻击仇敌。'),
('CUV', '以赛亚书', 23, 42, 14, '我许久闭口不言，静默不语；现在我要喊叫，像产难的妇人；我要急气而喘哮。'),
('CUV', '以赛亚书', 23, 42, 15, '我要使大山小冈变为荒场，使其上的花草都枯干；我要使江河变为洲岛，使水池都干涸。'),
('CUV', '以赛亚书', 23, 42, 16, '我要引瞎子行不认识的道，领他们走不知道的路；在他们面前使黑暗变为光明，使弯曲变为平直。这些事我都要行，并不离弃他们。'),
('CUV', '以赛亚书', 23, 42, 17, '倚靠雕刻的偶像，对铸造的偶像说：你是我们的神；这等人要退后，全然蒙羞。'),
('CUV', '以赛亚书', 23, 42, 18, '你们这耳聋的，听罢！你们这眼瞎的，看罢！使你们能看见。'),
('CUV', '以赛亚书', 23, 42, 19, '谁比我的仆人眼瞎呢？谁比我差遣的使者耳聋呢？谁瞎眼像那与我和好的？谁瞎眼像耶和华的仆人呢？'),
('CUV', '以赛亚书', 23, 42, 20, '你看见许多事却不领会，耳朵开通却不听见。'),
('CUV', '以赛亚书', 23, 42, 21, '耶和华因自己公义的缘故，喜欢使律法（或译：训诲）为大，为尊。'),
('CUV', '以赛亚书', 23, 42, 22, '但这百姓是被抢被夺的，都牢笼在坑中，隐藏在狱里；他们作掠物，无人拯救，作掳物，无人说交还。'),
('CUV', '以赛亚书', 23, 42, 23, '你们中间谁肯侧耳听此，谁肯留心而听，以防将来呢？'),
('CUV', '以赛亚书', 23, 42, 24, '谁将雅各交出当作掳物，将以色列交给抢夺的呢？岂不是耶和华么？就是我们所得罪的那位。他们不肯遵行他的道，也不听从他的训诲。'),
('CUV', '以赛亚书', 23, 42, 25, '所以，他将猛烈的怒气和争战的勇力倾倒在以色列的身上。在他四围如火著起，他还不知道，烧著他，他也不介意。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 43, 1, '雅各啊，创造你的耶和华，以色列啊，造成你的那位，现在如此说：你不要害怕！因为我救赎了你。我曾提你的名召你，你是属我的。'),
('CUV', '以赛亚书', 23, 43, 2, '你从水中经过，我必与你同在；你逿过江河，水必不漫过你；你从火中行过，必不被烧，火燄也不著在你身上。'),
('CUV', '以赛亚书', 23, 43, 3, '因为我是耶和华─你的神，是以色列的圣者─你的救主；我已经使埃及作你的赎价，使古实和西巴代替你。'),
('CUV', '以赛亚书', 23, 43, 4, '因我看你为宝为尊；又因我爱你，所以我使人代替你，使列邦人替换你的生命。'),
('CUV', '以赛亚书', 23, 43, 5, '不要害怕，因我与你同在；我必领你的后裔从东方来，又从西方招聚你。'),
('CUV', '以赛亚书', 23, 43, 6, '我要对北方说，交出来！对南方说，不要拘留！将我的众子从远方带来，将我的众女从地极领回，'),
('CUV', '以赛亚书', 23, 43, 7, '就是凡称为我名下的人，是我为自己的荣耀创造的，是我所做成，所造作的。'),
('CUV', '以赛亚书', 23, 43, 8, '你要将有眼而瞎、有耳而聋的民都带出来！'),
('CUV', '以赛亚书', 23, 43, 9, '任凭万国聚集；任凭众民会合。其中谁能将此声明，并将先前的事说给我们听呢？他们可以带出见证来，自显为是；或者他们听见便说：这是真的。'),
('CUV', '以赛亚书', 23, 43, 10, '耶和华说：你们是我的见证，我所拣选的仆人。既是这样，便可以知道，且信服我，又明白我就是耶和华。在我以前没有真神（真：原文是造作的）；在我以后也必没有。'),
('CUV', '以赛亚书', 23, 43, 11, '惟有我是耶和华；除我以外没有救主。'),
('CUV', '以赛亚书', 23, 43, 12, '我曾指示，我曾拯救，我曾说明，并且在你们中间没有别神。所以耶和华说：你们是我的见证。我也是神；'),
('CUV', '以赛亚书', 23, 43, 13, '自从有日子以来，我就是神；谁也不能救人脱离我手。我要行事谁能阻止呢？'),
('CUV', '以赛亚书', 23, 43, 14, '耶和华─你们的救赎主、以色列的圣者如此说：因你们的缘故，我已经打发人到巴比伦去；并且我要使迦勒底人如逃民，都坐自己喜乐的船下来。'),
('CUV', '以赛亚书', 23, 43, 15, '我是耶和华─你们的圣者，是创造以色列的，是你们的君王。'),
('CUV', '以赛亚书', 23, 43, 16, '耶和华在沧海中开道，在大水中开路，'),
('CUV', '以赛亚书', 23, 43, 17, '使车辆、马匹、军兵、勇士都出来，一同躺下，不再起来；他们灭没，好像熄灭的灯火。'),
('CUV', '以赛亚书', 23, 43, 18, '耶和华如此说：你们不要记念从前的事，也不要思想古时的事。'),
('CUV', '以赛亚书', 23, 43, 19, '看哪，我要做一件新事；如今要发现，你们岂不知道么？我必在旷野开道路，在沙漠开江河。'),
('CUV', '以赛亚书', 23, 43, 20, '野地的走兽必尊重我；野狗和鸵鸟也必如此。因我使旷野有水，使沙漠有河，好赐给我的百姓、我的选民喝。'),
('CUV', '以赛亚书', 23, 43, 21, '这百姓是我为自己所造的，好述说我的美德。'),
('CUV', '以赛亚书', 23, 43, 22, '雅各啊，你并没有求告我；以色列啊，你倒厌烦我。'),
('CUV', '以赛亚书', 23, 43, 23, '你没有将你的羊带来给我作燔祭，也没有用祭物尊敬我；我没有因供物使你服劳，也没有因乳香使你厌烦。'),
('CUV', '以赛亚书', 23, 43, 24, '你没有用银子为我买菖蒲，也没有用祭物的脂油使我饱足；倒使我因你的罪恶服劳，使我因你的罪孽厌烦。'),
('CUV', '以赛亚书', 23, 43, 25, '惟有我为自己的缘故涂抹你的过犯；我也不记念你的罪恶。'),
('CUV', '以赛亚书', 23, 43, 26, '你要提醒我，你我可以一同辩论；你可以将你的理陈明，自显为义。'),
('CUV', '以赛亚书', 23, 43, 27, '你的始祖犯罪；你的师傅违背我。'),
('CUV', '以赛亚书', 23, 43, 28, '所以，我要辱没圣所的首领，使雅各成为咒诅，使以色列成为辱骂。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 44, 1, '我的仆人雅各，我所拣选的以色列啊，现在你当听。'),
('CUV', '以赛亚书', 23, 44, 2, '造做你，又从你出胎造就你，并要帮助你的耶和华如此说：我的仆人雅各，我所拣选的耶书仑哪，不要害怕！'),
('CUV', '以赛亚书', 23, 44, 3, '因为我要将水浇灌口渴的人，将河浇灌干旱之地。我要将我的灵浇灌你的后裔，将我的福浇灌你的子孙。'),
('CUV', '以赛亚书', 23, 44, 4, '他们要发生在草中，像溪水旁的柳树。'),
('CUV', '以赛亚书', 23, 44, 5, '这个要说：我是属耶和华的；那个要以雅各的名自称；又一个要亲手写：归耶和华的（或译：在手上写归耶和华），并自称为以色列。'),
('CUV', '以赛亚书', 23, 44, 6, '耶和华─以色列的君，以色列的救赎主─万军之耶和华如此说：我是首先的，我是末后的；除我以外再没有真神。'),
('CUV', '以赛亚书', 23, 44, 7, '自从我设立古时的民，谁能像我宣告，并且指明，又为自己陈说呢？让他将未来来的事和必成的事说明。'),
('CUV', '以赛亚书', 23, 44, 8, '你们不要恐惧，也不要害怕。我岂不是从上古就说明指示你们么？并且你们是我的见证！除我以外，岂有真神么？诚然没有磐石，我不知道一个！'),
('CUV', '以赛亚书', 23, 44, 9, '制造雕刻偶像的尽都虚空；他们所喜悦的都无益处；他们的见证无所看见，无所知晓，他们便觉羞愧。'),
('CUV', '以赛亚书', 23, 44, 10, '谁制造神像，铸造无益的偶像？'),
('CUV', '以赛亚书', 23, 44, 11, '看哪，他的同伴都必羞愧。工匠也不过是人，任他们聚会，任他们站立，都必惧怕，一同羞愧。'),
('CUV', '以赛亚书', 23, 44, 12, '铁匠把铁在火炭中烧热，用锤打铁器，用他有力的膀臂锤成；他饥饿而无力，不喝水而发倦。'),
('CUV', '以赛亚书', 23, 44, 13, '木匠拉线，用笔划出样子，用铇子铇成形状，用圆尺划了模样，仿照人的体态，做成人形，好住在房屋中。'),
('CUV', '以赛亚书', 23, 44, 14, '他砍伐香柏树，又取柞（或译：青桐）树和橡树，在树林中选定了一棵。他栽种松树，得雨长养。'),
('CUV', '以赛亚书', 23, 44, 15, '这树，人可用以烧火；他自己取些烤火，又烧著烤饼，而且做神像跪拜，做雕刻的偶像向他叩拜。'),
('CUV', '以赛亚书', 23, 44, 16, '他把一分烧在火中，把一分烤肉吃饱。自己烤火说：啊哈，我暖和了，我见火了。'),
('CUV', '以赛亚书', 23, 44, 17, '他用剩下的做了一神，就是雕刻的偶像。他向这偶像俯伏叩拜，祷告他说：求你拯救我，因你是我的神。'),
('CUV', '以赛亚书', 23, 44, 18, '他们不知道，也不思想；因为耶和华闭住他们的眼，不能看见，塞住他们的心，不能明白。'),
('CUV', '以赛亚书', 23, 44, 19, '谁心里也不醒悟，也没有知识，没有聪明，能说：我曾拿一分在火中烧了，在炭火上烤过饼；我也烤过肉吃。这剩下的，我岂要作可憎的物吗？我岂可向木丕子叩拜呢？'),
('CUV', '以赛亚书', 23, 44, 20, '他以灰为食，心中昏迷，使他偏邪，他不能自救，也不能说：我右手中岂不是有虚谎么？'),
('CUV', '以赛亚书', 23, 44, 21, '雅各，以色列啊，你是我的仆人，要记念这些事。以色列啊，你是我的仆人，我造就你必不忘记你。'),
('CUV', '以赛亚书', 23, 44, 22, '我涂抹了你的过犯，像厚云消散；我涂抹了你的罪恶，如薄云灭没。你当归向我，因我救赎了你。'),
('CUV', '以赛亚书', 23, 44, 23, '诸天哪，应当歌唱，因为耶和华做成这事。地的深处啊，应当欢呼；众山应当发声歌唱；树林和其中所有的树都当如此！因为耶和华救赎了雅各，并要因以色列荣耀自己。'),
('CUV', '以赛亚书', 23, 44, 24, '从你出胎，造就你的救赎主─耶和华如此说：我─耶和华是创造万物的，是独自铺张诸天、铺开大地的。谁与我同在呢？'),
('CUV', '以赛亚书', 23, 44, 25, '使说假话的兆头失效，使占卜的癫狂，使智慧人退后，使他的知识变为愚拙；'),
('CUV', '以赛亚书', 23, 44, 26, '使我仆人的话语立定，我使者的谋算成就。论到耶路撒冷说：必有人居住；论到犹大的城邑说：必被建造，其中的荒场我也必兴起。'),
('CUV', '以赛亚书', 23, 44, 27, '对深渊说：你干了罢！我也要使你的江河干涸。'),
('CUV', '以赛亚书', 23, 44, 28, '论古列说：他是我的牧人，必成就我所喜悦的，必下令建造耶路撒冷，发命立稳圣殿的根基。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 45, 1, '我─耶和华所膏的古列；我搀扶他的右手，使列国降伏在他面前。我也要放松列王的腰带，使城门在他面前敞开，不得关闭。我对他如此说：'),
('CUV', '以赛亚书', 23, 45, 2, '我必在你前面行，修平崎岖之地。我必打破铜门，砍断铁闩。'),
('CUV', '以赛亚书', 23, 45, 3, '我要将暗中的宝物和隐密的财宝赐给你，使你知道提名召你的，就是我─耶和华、以色列的神。'),
('CUV', '以赛亚书', 23, 45, 4, '因我仆人雅各，我所拣选以色列的缘故，我就提名召你；你虽不认识我，我也加给你名号。'),
('CUV', '以赛亚书', 23, 45, 5, '我是耶和华，在我以外并没有别神；除了我以外再没有神。你虽不认识我，我必给你束腰。'),
('CUV', '以赛亚书', 23, 45, 6, '从日出之地到日落之处使人都知道除了我以外，没有别神。我是耶和华；在我以外并没有别神。'),
('CUV', '以赛亚书', 23, 45, 7, '我造光，又造暗；我施平安，又降灾祸；造作这一切的是我─耶和华。'),
('CUV', '以赛亚书', 23, 45, 8, '诸天哪，自上而滴，穹苍降下公义；地面开裂，产出救恩，使公义一同发生；这都是我─耶和华所造的。'),
('CUV', '以赛亚书', 23, 45, 9, '祸哉，那与造他的主争论的！他不过是地上瓦片中的一块瓦片。泥土岂可对抟弄他的说：你做甚么呢？所做的物岂可说：你没有手呢？'),
('CUV', '以赛亚书', 23, 45, 10, '祸哉，那对父亲说：你生的是甚么呢？或对母亲（原文是妇人）说：你产的是甚么呢？'),
('CUV', '以赛亚书', 23, 45, 11, '耶和华─以色列的圣者，就是造就以色列的如此说：将来的事，你们可以问我；至于我的众子，并我手的工作，你们可以求我命定（原文是吩咐我）。'),
('CUV', '以赛亚书', 23, 45, 12, '我造地，又造人在地上。我亲手铺张诸天；天上万象也是我所命定的。'),
('CUV', '以赛亚书', 23, 45, 13, '我凭公义兴起古列（原文是他），又要修直他一切道路。他必建造我的城，释放我被掳的民；不是为工价，也不是为赏赐。这是万军之耶和华说的。'),
('CUV', '以赛亚书', 23, 45, 14, '耶和华如此说：埃及劳碌得来的和古实的货物必归你；身量高大的西巴人必投降你，也要属你。他们必带著锁链过来随从你，又向你下拜，祈求你说：神真在你们中间，此外再没有别神；再没有别的神。'),
('CUV', '以赛亚书', 23, 45, 15, '救主─以色列的神啊，你实在是自隐的神。'),
('CUV', '以赛亚书', 23, 45, 16, '凡制造偶像的都必抱愧蒙羞，都要一同归于惭愧。'),
('CUV', '以赛亚书', 23, 45, 17, '惟有以色列必蒙耶和华的拯救，得永远的救恩。你们必不蒙羞，也不抱愧，直到永世无尽。'),
('CUV', '以赛亚书', 23, 45, 18, '创造诸天的耶和华，制造成全大地的神，他创造坚定大地，并非使地荒凉，是要给人居住。他如此说：我是耶和华，再没有别神。'),
('CUV', '以赛亚书', 23, 45, 19, '我没有在隐密黑暗之地说话；我没有对雅各的后裔说：你们寻求我是徒然的。我─耶和华所讲的是公义，所说的是正直。'),
('CUV', '以赛亚书', 23, 45, 20, '你们从列国逃脱的人，要一同聚集前来。那些抬著雕刻木偶、祷告不能救人之神的，毫无知识。'),
('CUV', '以赛亚书', 23, 45, 21, '你们要述说陈明你们的理，让他们彼此商议。谁从古时指明，谁从上古述说？不是我─耶和华么？除了我以外，再没有神；我是公义的神，又是救主；除了我以外，再没有别神。'),
('CUV', '以赛亚书', 23, 45, 22, '地极的人都当仰望我，就必得救；因为我是神，再没有别神。'),
('CUV', '以赛亚书', 23, 45, 23, '我指著自己起誓，我口所出的话是凭公义，并不反回：万膝必向我跪拜；万口必凭我起誓。'),
('CUV', '以赛亚书', 23, 45, 24, '人论我说，公义、能力，惟独在乎耶和华；人都必归向他。凡向他发怒的必至蒙羞。'),
('CUV', '以赛亚书', 23, 45, 25, '以色列的后裔都必因耶和华得称为义，并要夸耀。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 46, 1, '彼勒屈身，尼波弯腰；巴比伦的偶像驮在兽和牲畜上。他们所抬的如今成了重驮，使牲畜疲乏，'),
('CUV', '以赛亚书', 23, 46, 2, '都一同弯腰屈身，不能保全重驮，自己倒被掳去。'),
('CUV', '以赛亚书', 23, 46, 3, '雅各家，以色列家一切余剩的要听我言：你们自从生下，就蒙我保抱，自从出胎，便蒙我怀搋。'),
('CUV', '以赛亚书', 23, 46, 4, '直到你们年老，我仍这样；直到你们发白，我仍怀搋。我已造作，也必保抱；我必怀抱，也必拯救。'),
('CUV', '以赛亚书', 23, 46, 5, '你们将谁与我相比，与我同等，可以与我比较，使我们相同呢？'),
('CUV', '以赛亚书', 23, 46, 6, '那从囊中抓金子，用天平平银子的人，雇银匠制造神像，他们又俯伏，又叩拜。'),
('CUV', '以赛亚书', 23, 46, 7, '他们将神像抬起，扛在肩上，安置在定处，他就站立，不离本位；人呼求他，他不能答应，也不能救人脱离患难。'),
('CUV', '以赛亚书', 23, 46, 8, '你们当想念这事，自己作大丈夫。悖逆的人哪，要心里思想。'),
('CUV', '以赛亚书', 23, 46, 9, '你们要追念上古的事。因为我是神，并无别神；我是神，再没有能比我的。'),
('CUV', '以赛亚书', 23, 46, 10, '我从起初指明末后的事，从古时言明未成的事，说：我的筹算必立定；凡我所喜悦的，我必成就。'),
('CUV', '以赛亚书', 23, 46, 11, '我召鸷鸟从东方来，召那成就我筹算的人从远方来。我已说出，也必成就；我已谋定，也必做成。'),
('CUV', '以赛亚书', 23, 46, 12, '你们这些心中顽梗、远离公义的，当听我言。'),
('CUV', '以赛亚书', 23, 46, 13, '我使我的公义临近，必不远离。我的救恩必不迟延；我要为以色列─我的荣耀，在锡安施行救恩。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 47, 1, '巴比伦的处女啊，下来坐在尘埃；迦勒底的闺女啊，没有宝座，要坐在地上；因为你不再称为柔弱娇嫩的。'),
('CUV', '以赛亚书', 23, 47, 2, '要用磨磨面，揭去帕子，脱去长衣，露腿逿河。'),
('CUV', '以赛亚书', 23, 47, 3, '你的下体必被露出；你的丑陋必被看见。我要报仇，谁也不宽容。'),
('CUV', '以赛亚书', 23, 47, 4, '我们救赎主的名是万军之耶和华─以色列的圣者。'),
('CUV', '以赛亚书', 23, 47, 5, '迦勒底的闺女啊，你要默然静坐，进入暗中，因为你不再称为列国的主母。'),
('CUV', '以赛亚书', 23, 47, 6, '我向我的百姓发怒，使我的产业被亵渎，将他们交在你手中，你毫不怜悯他们，把极重的轭加在老年人身上。'),
('CUV', '以赛亚书', 23, 47, 7, '你自己说：我必永为主母，所以你不将这事放在心上，也不想这事的结局。'),
('CUV', '以赛亚书', 23, 47, 8, '你这专好宴乐、安然居住的，现在当听这话。你心中说：惟有我，除我以外再没有别的。我必不致寡居，也不遭丧子之事。'),
('CUV', '以赛亚书', 23, 47, 9, '哪知，丧子、寡居这两件事在一日转眼之间必临到你；正在你多行邪术、广施符咒的时候，这两件事必全然临到你身上。'),
('CUV', '以赛亚书', 23, 47, 10, '你素来倚仗自己的恶行，说：无人看见我。你的智慧聪明使你偏邪，并且你心里说：惟有我，除我以外再没有别的。'),
('CUV', '以赛亚书', 23, 47, 11, '因此，祸患要临到你身；你不知何时发现（或译：如何驱逐）灾害落在你身上，你也不能除掉；所不知道的毁灭也必忽然临到你身。'),
('CUV', '以赛亚书', 23, 47, 12, '站起来罢！用你从幼年劳神施行的符咒和你许多的邪术；或者可得益处，或者可得强胜。'),
('CUV', '以赛亚书', 23, 47, 13, '你筹划太多，以致疲倦。让那些观天象的，看星宿的，在月朔说预言的，都站起来，救你脱离所要临到你的事。'),
('CUV', '以赛亚书', 23, 47, 14, '他们要像碎秸被火焚烧，不能救自己脱离火燄之力；这火并非可烤的炭火，也不是可以坐在其前的火。'),
('CUV', '以赛亚书', 23, 47, 15, '你所劳神的事都要这样与你无益；从幼年与你贸易的也都各奔各乡，无人救你。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 48, 1, '雅各家，称为以色列名下，从犹大水源出来的，当听我言！你们指著耶和华的名起誓，提说以色列的神，却不凭诚实，不凭公义。'),
('CUV', '以赛亚书', 23, 48, 2, '他们自称为圣城的人，所倚靠的是名为万军之耶和华─以色列的神。'),
('CUV', '以赛亚书', 23, 48, 3, '主说：早先的事，我从古时说明，已经出了我的口，也是我所指示的；我忽然行做，事便成就。'),
('CUV', '以赛亚书', 23, 48, 4, '因为我素来知道你是顽梗的─你的颈项是铁的；你的额是铜的。'),
('CUV', '以赛亚书', 23, 48, 5, '所以，我从古时将这事给你说明，在未成以先指示你，免得你说：这些事是我的偶像所行的，是我雕刻的偶像和我铸造的偶像所命定的。'),
('CUV', '以赛亚书', 23, 48, 6, '你已经听见，现在要看见这一切；你不说明么？从今以后，我将新事，就是你所不知道的隐密事指示你。'),
('CUV', '以赛亚书', 23, 48, 7, '这事是现今造的，并非从古就有；在今日以先，你也未曾听见，免得你说：这事我早已知道了。'),
('CUV', '以赛亚书', 23, 48, 8, '你未曾听见，未曾知道；你的耳朵从来未曾开通。我原知道你行事极其诡诈，你自从出胎以来，便称为悖逆的。'),
('CUV', '以赛亚书', 23, 48, 9, '我为}我的名暂且忍怒，为我的颂赞向你容忍，不将你剪除。'),
('CUV', '以赛亚书', 23, 48, 10, '我熬炼你，却不像熬炼银子；你在苦难的炉中，我拣选你。'),
('CUV', '以赛亚书', 23, 48, 11, '我为自己的缘故必行这事，我焉能使我的名被亵渎？我必不将我的荣耀归给假神。'),
('CUV', '以赛亚书', 23, 48, 12, '雅各─我所选召的以色列啊，当听我言：我是耶和华，我是首先的，也是末后的。'),
('CUV', '以赛亚书', 23, 48, 13, '我手立了地的根基；我右手铺张诸天；我一招呼便都立住。'),
('CUV', '以赛亚书', 23, 48, 14, '你们都当聚集而听，他们（或译：偶像）内中谁说过这些事？耶和华所爱的人必向巴比伦行他所喜悦的事；他的膀臂也要加在迦勒底人身上。'),
('CUV', '以赛亚书', 23, 48, 15, '惟有我曾说过，我又选召他，领他来，他的道路就必亨通。'),
('CUV', '以赛亚书', 23, 48, 16, '你们要就近我来听这话：我从起头并未曾在隐密处说话；自从有这事，我就在那里。现在，主耶和华差遣我和他的灵来（或译：耶和华和他的灵差遣我来）。'),
('CUV', '以赛亚书', 23, 48, 17, '耶和华─你的救赎主，以色列的圣者如此说：我是耶和华─你的神，教训你，使你得益处，引导你所当行的路。'),
('CUV', '以赛亚书', 23, 48, 18, '甚愿你素来听从我的命令！你的平安就如河水；你的公义就如海浪。'),
('CUV', '以赛亚书', 23, 48, 19, '你的后裔也必多如海沙；你腹中所生的也必多如沙粒。他的名在我面前必不剪除，也不灭绝。'),
('CUV', '以赛亚书', 23, 48, 20, '你们要从巴比伦出来，从迦勒底人中逃脱，以欢呼的声音传扬说：耶和华救赎了他的仆人雅各！你们要将这事宣扬到地极。'),
('CUV', '以赛亚书', 23, 48, 21, '耶和华引导他们经过沙漠。他们并不干渴；他为他们使水从磐石而流，分裂磐石，水就涌出。'),
('CUV', '以赛亚书', 23, 48, 22, '耶和华说：恶人必不得平安！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 49, 1, '众海岛啊，当听我言！远方的众民哪，留心而听！自我出胎，耶和华就选召我；自出母腹，他就提我的名。'),
('CUV', '以赛亚书', 23, 49, 2, '他使我的口如快刀，将我藏在他手荫之下；又使我成为磨亮的箭，将我藏在他箭袋之中；'),
('CUV', '以赛亚书', 23, 49, 3, '对我说：你是我的仆人以色列；我必因你得荣耀。'),
('CUV', '以赛亚书', 23, 49, 4, '我却说：我劳碌是徒然；我尽力是虚无虚空。然而，我当得的理必在耶和华那里；我的赏赐必在我神那里。'),
('CUV', '以赛亚书', 23, 49, 5, '耶和华从我出胎，造就我作他的仆人，要使雅各归向他，使以色列到他那里聚集。原来耶和华看我为尊贵；我的神也成为我的力量。'),
('CUV', '以赛亚书', 23, 49, 6, '现在他说：你作我的仆人，使雅各众支派复兴，使以色列中得保全的归回尚为小事，我还要使你作外邦人的光，叫你施行我的救恩，直到地极。'),
('CUV', '以赛亚书', 23, 49, 7, '救赎主─以色列的圣者耶和华对那被人所藐视、本国所憎恶、官长所虐待的如此说：君王要看见就站起，首领也要下拜；都因信实的耶和华，就是拣选你─以色列的圣者。'),
('CUV', '以赛亚书', 23, 49, 8, '耶和华如此说：在悦纳的时候，我应允了你；在拯救的日子，我济助了你。我要保护你，使你作众民的中保（中保：原文是约）；复兴遍地，使人承受荒凉之地为业。'),
('CUV', '以赛亚书', 23, 49, 9, '对那被捆绑的人说：出来罢！对那在黑暗的人说：显露罢！他们在路上必得饮食，在一切净光的高处必有食物。'),
('CUV', '以赛亚书', 23, 49, 10, '不饥不渴，炎热和烈日必不伤害他们；因为怜恤他们的必引导他们，领他们到水泉旁边。'),
('CUV', '以赛亚书', 23, 49, 11, '我必使我的众山成为大道；我的大路也被修高。'),
('CUV', '以赛亚书', 23, 49, 12, '看哪，这些从远方来；这些从北方、从西方来；这些从秦（原文是希尼）国来。'),
('CUV', '以赛亚书', 23, 49, 13, '诸天哪，应当欢呼！大地啊，应当快乐！众山哪，应当发声歌唱！因为耶和华已经安慰他的百姓，也要怜恤他困苦之民。'),
('CUV', '以赛亚书', 23, 49, 14, '锡安说：耶和华离弃了我；主忘记了我。'),
('CUV', '以赛亚书', 23, 49, 15, '妇人焉能忘记他吃奶的婴孩，不怜恤他所生的儿子？即或有忘记的，我却不忘记你。'),
('CUV', '以赛亚书', 23, 49, 16, '看哪，我将你铭刻在我掌上；你的墙垣常在我眼前。'),
('CUV', '以赛亚书', 23, 49, 17, '你的儿女必急速归回；毁坏你的，使你荒废的，必都离你出去，'),
('CUV', '以赛亚书', 23, 49, 18, '你举目向四方观看；他们都聚集来到你这里。耶和华说：我指著我的永生起誓：你必要以他们为妆饰佩戴，以他们为华带束腰，像新妇一样。'),
('CUV', '以赛亚书', 23, 49, 19, '至于你荒废凄凉之处，并你被毁坏之地，现今众民居住必显为太窄；吞灭你的必离你遥远。'),
('CUV', '以赛亚书', 23, 49, 20, '你必听见丧子之后所生的儿女说：这地方我居住太窄，求你给我地方居住。'),
('CUV', '以赛亚书', 23, 49, 21, '那时你心里必说：我既丧子独居，是被掳的，漂流在外。谁给我生这些？谁将这些养大呢？撇下我一人独居的时候，这些在哪里呢？'),
('CUV', '以赛亚书', 23, 49, 22, '主耶和华如此说：我必向列国举手，向万民竖立大旗；他们必将你的众子怀中抱来，将你的众女肩上扛来。'),
('CUV', '以赛亚书', 23, 49, 23, '列王必作你的养父；王后必作你的乳母。他们必将脸伏地，向你下拜，并舔你脚上的尘土。你便知道我是耶和华；等候我的必不致羞愧。'),
('CUV', '以赛亚书', 23, 49, 24, '勇士抢去的岂能夺回？该掳掠的岂能解救么？'),
('CUV', '以赛亚书', 23, 49, 25, '但耶和华如此说：就是勇士所掳掠的，也可以夺回；强暴人所抢的，也可以解救。与你相争的，我必与他相争；我要拯救你的儿女。'),
('CUV', '以赛亚书', 23, 49, 26, '并且我必使那欺压你的吃自己的肉，也要以自己的血喝醉，好像喝甜酒一样。凡有血气的必都知道我─耶和华是你的救主，是你的救赎主，是雅各的大能者。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 50, 1, '耶和华如此说：我休你们的母亲，休书在哪里呢？我将你们卖给我哪一个债主呢？你们被卖，是因你们的罪孽；你们的母亲被休，是因你们的过犯。'),
('CUV', '以赛亚书', 23, 50, 2, '我来的时候，为何无人等候呢？我呼唤的时候，为何无人答应呢？我的膀臂岂是缩短、不能救赎吗？我岂无拯救之力么？看哪，我一斥责，海就干了；我使江河变为旷野；其中的鱼因无水腥臭，干渴而死。'),
('CUV', '以赛亚书', 23, 50, 3, '我使诸天以黑暗为衣服，以麻布为遮盖。'),
('CUV', '以赛亚书', 23, 50, 4, '主耶和华赐我受教者的舌头，使我知道怎样用言语扶助疲乏的人。主每早晨提醒，提醒我的耳朵，使我能听，像受教者一样。'),
('CUV', '以赛亚书', 23, 50, 5, '主耶和华开通我的耳朵；我并没有违背，也没有退后。'),
('CUV', '以赛亚书', 23, 50, 6, '人打我的背，我任他打；人拔我腮颊的胡须，我由他拔；人辱我，吐我，我并不掩面。'),
('CUV', '以赛亚书', 23, 50, 7, '主耶和华必帮助我，所以我不抱愧。我硬著脸面好像坚石；我也知道我必不致蒙羞。'),
('CUV', '以赛亚书', 23, 50, 8, '称我为义的与我相近；谁与我争论，可以与我一同站立；谁与我作对，可以就近我来。'),
('CUV', '以赛亚书', 23, 50, 9, '主耶和华要帮助我；谁能定我有罪呢？他们都像衣服渐渐旧了，为蛀虫所咬。'),
('CUV', '以赛亚书', 23, 50, 10, '你们中间谁是敬畏耶和华、听从他仆人之话的？这人行在暗中，没有亮光。当倚靠耶和华的名，仗赖自己的神。'),
('CUV', '以赛亚书', 23, 50, 11, '凡你们点火，用火把围绕自己的可以行在你们的火燄里，并你们所点的火把中。这是我手所定的；你们必躺在悲惨之中，')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 51, 1, '你们这追求公义、寻求耶和华的，当听我言！你们要追想被凿而出的磐石，被挖而出的岩穴。'),
('CUV', '以赛亚书', 23, 51, 2, '要追想你们的祖宗亚伯拉罕和生养你们的撒拉；因为亚伯拉罕独自一人的时候，我选召他，赐福与他，使他人数增多。'),
('CUV', '以赛亚书', 23, 51, 3, '耶和华已经安慰锡安和锡安一切的荒场，使旷野像伊甸，使沙漠像耶和华的园囿；在其中必有欢喜、快乐、感谢，和歌唱的声音。'),
('CUV', '以赛亚书', 23, 51, 4, '我的百姓啊，要向我留心；我的国民哪，要向我侧耳；因为训诲必从我而出；我必坚定我的公理为万民之光。'),
('CUV', '以赛亚书', 23, 51, 5, '我的公义临近；我的救恩发出。我的膀臂要审判万民；海岛都要等候我，倚赖我的膀臂。'),
('CUV', '以赛亚书', 23, 51, 6, '你们要向天举目，观看下地；因为天必像烟云消散，地必如衣服渐渐旧了；其上的居民也要如此死亡（如此死亡：或译像蠓虫死亡）。惟有我的救恩永远长存；我的公义也不废掉。'),
('CUV', '以赛亚书', 23, 51, 7, '知道公义、将我训诲存在心中的民，要听我言！不要怕人的辱骂，也不要因人的毁谤惊惶。'),
('CUV', '以赛亚书', 23, 51, 8, '因为蛀虫必咬他们，好像咬衣服；虫子必咬他们，如同咬羊绒。惟有我的公义永远长存，我的救恩直到万代。'),
('CUV', '以赛亚书', 23, 51, 9, '耶和华的膀臂啊，兴起！兴起！以能力为衣穿上，像古时的年日、上古的世代兴起一样。从前砍碎拉哈伯、刺透大鱼的，不是你么？'),
('CUV', '以赛亚书', 23, 51, 10, '使海与深渊的水干涸、使海的深处变为赎民经过之路的，不是你么？'),
('CUV', '以赛亚书', 23, 51, 11, '耶和华救赎的民必归回，歌唱来到锡安；永乐必归到他们的头上。他们必得著欢喜快乐；忧愁叹息尽都逃避。'),
('CUV', '以赛亚书', 23, 51, 12, '惟有我，是安慰你们的。你是谁，竟怕那必死的人？怕那要变如草的世人？'),
('CUV', '以赛亚书', 23, 51, 13, '却忘记铺张诸天、立定地基、创造你的耶和华？又因欺压者图谋毁灭要发的暴怒，整天害怕，其实那欺压者的暴怒在哪里呢？'),
('CUV', '以赛亚书', 23, 51, 14, '被掳去的快得释放，必不死而下坑；他的食物也不致缺乏。'),
('CUV', '以赛亚书', 23, 51, 15, '我是耶和华─你的神─搅动大海，使海中的波浪匉訇─万军之耶和华是我的名。'),
('CUV', '以赛亚书', 23, 51, 16, '我将我的话传给你，用我的手影遮蔽你，为要栽定诸天，立定地基，又对锡安说：你是我的百姓。'),
('CUV', '以赛亚书', 23, 51, 17, '耶路撒冷啊，兴起！兴起！站起来！你从耶和华手中喝了他忿怒之杯，喝了那使人东倒西歪的爵，以致喝尽。'),
('CUV', '以赛亚书', 23, 51, 18, '他所生育的诸子中，没有一个引导他的；他所养大的诸子中，没有一个搀扶他的。'),
('CUV', '以赛亚书', 23, 51, 19, '荒凉、毁灭、饥荒、刀兵，这几样临到你，谁为你举哀？我如何能安慰你呢？'),
('CUV', '以赛亚书', 23, 51, 20, '你的众子发昏，在各市口上躺卧，好像黄羊在网罗之中，都满了耶和华的忿怒─你神的斥责。'),
('CUV', '以赛亚书', 23, 51, 21, '因此，你这困苦却非因酒而醉的，要听我言。'),
('CUV', '以赛亚书', 23, 51, 22, '你的主耶和华─就是为他百姓辨屈的神如此说：看哪，我已将那使人东倒西歪的杯，就是我忿怒的爵，从你手中接过来；你必不致再喝。'),
('CUV', '以赛亚书', 23, 51, 23, '我必将这杯递在苦待你的人手中；他们曾对你说：你屈身，由我们践踏过去罢！你便以背为地，好像街市，任人经过。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 52, 1, '锡安哪，兴起！兴起！披上你的能力！圣城耶路撒冷啊，穿上你华美的衣服！因为从今以后，未受割礼、不洁净的必不再进入你中间。'),
('CUV', '以赛亚书', 23, 52, 2, '耶路撒冷啊，要抖下尘土！起来坐在位上！锡安被掳的居民（原文是女子）哪，要解开你颈项的锁链！'),
('CUV', '以赛亚书', 23, 52, 3, '耶和华如此说：你们是无价被卖的，也必无银被赎。'),
('CUV', '以赛亚书', 23, 52, 4, '主耶和华如此说：起先我的百姓下到埃及，在那里寄居，又有亚述人无故欺压他们。'),
('CUV', '以赛亚书', 23, 52, 5, '耶和华说：我的百姓既是无价被掳去，如今我在这里做甚么呢？耶和华说：辖制他们的人呼叫，我的名整天受亵渎。'),
('CUV', '以赛亚书', 23, 52, 6, '所以，我的百姓必知道我的名；到那日他们必知道说这话的就是我。看哪，是我！'),
('CUV', '以赛亚书', 23, 52, 7, '那报佳音，传平安，报好信，传救恩的，对锡安说：你的神作王了！这人的脚登山何等佳美！'),
('CUV', '以赛亚书', 23, 52, 8, '听啊，你守望之人的声音，他们扬起声来，一同歌唱；因为耶和华归回锡安的时候，他们必亲眼看见。'),
('CUV', '以赛亚书', 23, 52, 9, '耶路撒冷的荒场啊，要发起欢声，一同歌唱；因为耶和华安慰了他的百姓，救赎了耶路撒冷。'),
('CUV', '以赛亚书', 23, 52, 10, '耶和华在万国眼前露出圣臂；地极的人都看见我们神的救恩了。'),
('CUV', '以赛亚书', 23, 52, 11, '你们离开罢！离开罢！从巴比伦出来。不要沾不洁净的物；要从其中出来。你们扛抬耶和华器皿的人哪，务要自洁。'),
('CUV', '以赛亚书', 23, 52, 12, '你们出来必不致急忙，也不致奔逃。因为，耶和华必在你们前头行；以色列的神必作你们的后盾。'),
('CUV', '以赛亚书', 23, 52, 13, '我的仆人行事必有智慧（或译：行事通达），必被高举上升，且成为至高。'),
('CUV', '以赛亚书', 23, 52, 14, '许多人因他（原文是你）惊奇；他的面貌比别人憔悴；他的形容比世人枯槁。'),
('CUV', '以赛亚书', 23, 52, 15, '这样，他必洗净（或译：鼓动）许多国民；君王要向他闭口。因所未曾传与他们的，他们必看见；未曾听见的，他们要明白。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 53, 1, '我们所传的（或译：所传与我们的）有谁信呢？耶和华的膀臂向谁显露呢？'),
('CUV', '以赛亚书', 23, 53, 2, '他在耶和华面前生长如嫩芽，像根出于干地。他无佳形美容；我们看见他的时候，也无美貌使我们羡慕他。'),
('CUV', '以赛亚书', 23, 53, 3, '他被藐视，被人厌弃；多受痛苦，常经忧患。他被藐视，好像被人掩面不看的一样；我们也不尊重他。'),
('CUV', '以赛亚书', 23, 53, 4, '他诚然担当我们的忧患，背负我们的痛苦；我们却以为他受责罚，被神击打苦待了。'),
('CUV', '以赛亚书', 23, 53, 5, '哪知他为我们的过犯受害，为我们的罪孽压伤。因他受的刑罚，我们得平安；因他受的鞭伤，我们得医治。'),
('CUV', '以赛亚书', 23, 53, 6, '我们都如羊走迷；各人偏行己路；耶和华使我们众人的罪孽都归在他身上。'),
('CUV', '以赛亚书', 23, 53, 7, '他被欺压，在受苦的时候却不开口（或译：他受欺压，却自卑不开口）；他像羊羔被牵到宰杀之地，又像羊在剪毛的人手下无声，他也是这样不开口。'),
('CUV', '以赛亚书', 23, 53, 8, '因受欺压和审判，他被夺去，至于他同世的人，谁想他受鞭打、从活人之地被剪除，是因我百姓的罪过呢？'),
('CUV', '以赛亚书', 23, 53, 9, '他虽然未行强暴，口中也没有诡诈，人还使他与恶人同埋；谁知死的时候与财主同葬。'),
('CUV', '以赛亚书', 23, 53, 10, '耶和华却定意（或译：喜悦）将他压伤，使他受痛苦。耶和华以他为赎罪祭（或译：他献本身为赎罪祭）。他必看见后裔，并且延长年日。耶和华所喜悦的事必在他手中亨通。'),
('CUV', '以赛亚书', 23, 53, 11, '他必看见自己劳苦的功效，便心满意足。有许多人因认识我的义仆得称为义；并且他要担当他们的罪孽。'),
('CUV', '以赛亚书', 23, 53, 12, '所以，我要使他与位大的同分，与强盛的均分掳物。因为他将命倾倒，以致于死；他也被列在罪犯之中。他却担当多人的罪，又为罪犯代求。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 54, 1, '你这不怀孕、不生养的要歌唱；你这未曾经过产难的要发声歌唱，扬声欢呼；因为没有丈夫的比有丈夫的儿女更多。这是耶和华说的。'),
('CUV', '以赛亚书', 23, 54, 2, '要扩张你帐幕之地，张大你居所的幔子，不要限止；要放长你的绳子，坚固你的橛子。'),
('CUV', '以赛亚书', 23, 54, 3, '因为你要向左向右开展；你的后裔必得多国为业，又使荒凉的城邑有人居住。'),
('CUV', '以赛亚书', 23, 54, 4, '不要惧怕，因你必不致蒙羞；也不要抱愧，因你必不致受辱。你必忘记幼年的羞愧，不再记念你寡居的羞辱。'),
('CUV', '以赛亚书', 23, 54, 5, '因为造你的是你的丈夫；万军之耶和华是他的名。救赎你的是以色列的圣者；他必称为全地之神。'),
('CUV', '以赛亚书', 23, 54, 6, '耶和华召你，如召被离弃心中忧伤的妻，就是幼年所娶被弃的妻。这是你神所说的。'),
('CUV', '以赛亚书', 23, 54, 7, '我离弃你不过片时，却要施大恩将你收回。'),
('CUV', '以赛亚书', 23, 54, 8, '我的怒气涨溢，顷刻之间向你掩面，却要以永远的慈爱怜恤你。这是耶和华─你的救赎主说的。'),
('CUV', '以赛亚书', 23, 54, 9, '这事在我好像挪亚的洪水。我怎样起誓不再使挪亚的洪水漫过遍地，我也照样起誓不再向你发怒，也不斥责你。'),
('CUV', '以赛亚书', 23, 54, 10, '大山可以挪开，小山可以迁移；但我的慈爱必不离开你；我平安的约也不迁移。这是怜恤你的耶和华说的。'),
('CUV', '以赛亚书', 23, 54, 11, '你这受困苦、被风飘荡不得安慰的人哪，我必以彩色安置你的石头，以蓝宝石立定你的根基；'),
('CUV', '以赛亚书', 23, 54, 12, '又以红宝石造你的女墙，以红玉造你的城门，以宝石造你四围的边界（或译：外郭）。'),
('CUV', '以赛亚书', 23, 54, 13, '你的儿女都要受耶和华的教训；你的儿女必大享平安。'),
('CUV', '以赛亚书', 23, 54, 14, '你必因公义得坚立，必远离欺压，不致害怕；你必远离惊吓，惊吓必不临近你。'),
('CUV', '以赛亚书', 23, 54, 15, '即或有人聚集，却不由于我；凡聚集攻击你的，必因你仆倒（或译：投降你）。'),
('CUV', '以赛亚书', 23, 54, 16, '吹嘘炭火、打造合用器械的铁匠是我所造；残害人、行毁灭的也是我所造。'),
('CUV', '以赛亚书', 23, 54, 17, '凡为攻击你造成的器械必不利用；凡在审判时兴起用舌攻击你的，你必定他为有罪。这是耶和华仆人的产业，是他们从我所得的义。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 55, 1, '你们一切干渴的都当就近水来；没有银钱的也可以来。你们都来，买了吃；不用银钱，不用价值，也来买酒和奶。'),
('CUV', '以赛亚书', 23, 55, 2, '你们为何花钱（原文是平银）买那不足为食物的？用劳碌得来的买那不使人饱足的呢？你们要留意听我的话就能吃那美物，得享肥甘，心中喜乐。'),
('CUV', '以赛亚书', 23, 55, 3, '你们当就近我来；侧耳而听，就必得活。我必与你们立永约，就是应许大卫那可靠的恩典。'),
('CUV', '以赛亚书', 23, 55, 4, '我已立他作万民的见证，为万民的君王和司令。'),
('CUV', '以赛亚书', 23, 55, 5, '你素不认识的国民，你也必召来；素不认识你的国民也必向你奔跑，都因耶和华─你的神以色列的圣者，因为他已经荣耀你。'),
('CUV', '以赛亚书', 23, 55, 6, '当趁耶和华可寻找的时候寻找他，相近的时候求告他。'),
('CUV', '以赛亚书', 23, 55, 7, '恶人当离弃自己的道路；不义的人当除掉自己的意念。归向耶和华，耶和华就必怜恤他；当归向我们的神，因为神必广行赦免。'),
('CUV', '以赛亚书', 23, 55, 8, '耶和华说：我的意念非同你们的意念；我的道路非同你们的道路。'),
('CUV', '以赛亚书', 23, 55, 9, '天怎样高过地，照样，我的道路高过你们的道路；我的意念高过你们的意念。'),
('CUV', '以赛亚书', 23, 55, 10, '雨雪从天而降，并不返回，却滋润地土，使地上发芽结实，使撒种的有种，使要吃的有粮。'),
('CUV', '以赛亚书', 23, 55, 11, '我口所出的话也必如此，决不徒然返回，却要成就我所喜悦的，在我发他去成就（发他去成就：或译所命定）的事上必然亨通。'),
('CUV', '以赛亚书', 23, 55, 12, '你们必欢欢喜喜而出来，平平安安蒙引导。大山小山必在你们面前发声歌唱；田野的树木也都拍掌。'),
('CUV', '以赛亚书', 23, 55, 13, '松树长出，代替荆棘；番石榴长出，代替蒺藜。这要为耶和华留名，作为永远的证据，不能剪除。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 56, 1, '耶和华如此说：你们当守公平，行公义；因我的救恩临近，我的公义将要显现。'),
('CUV', '以赛亚书', 23, 56, 2, '谨守安息日而不干犯，禁止己手而不作恶；如此行、如此持守的人便为有福。'),
('CUV', '以赛亚书', 23, 56, 3, '与耶和华联合的外邦人不要说：耶和华必定将我从他民中分别出来。太监也不要说：我是枯树。'),
('CUV', '以赛亚书', 23, 56, 4, '因为耶和华如此说：那些}谨守我的安息日，拣选我所喜悦的事，持守我约的太监，'),
('CUV', '以赛亚书', 23, 56, 5, '我必使他们在我殿中，在我墙内，有记念，有名号，比有儿女的更美。我必赐他们永远的名，不能剪除。'),
('CUV', '以赛亚书', 23, 56, 6, '还有那些与耶和华联合的外邦人，要事奉他，要爱耶和华的名，要作他的仆人─就是凡守安息日不干犯，又持守他（原文是我）约的人。'),
('CUV', '以赛亚书', 23, 56, 7, '我必领他们到我的圣山，使他们在祷告我的殿中喜乐。他们的燔祭和平安祭，在我坛上必蒙悦纳，因我的殿必称为万民祷告的殿。'),
('CUV', '以赛亚书', 23, 56, 8, '主耶和华，就是招聚以色列被赶散的，说：在这被招聚的人以外，我还要招聚别人归并他们。'),
('CUV', '以赛亚书', 23, 56, 9, '田野的诸兽都来吞吃罢！林中的诸兽也要如此。'),
('CUV', '以赛亚书', 23, 56, 10, '他看守的人是瞎眼的，都没有知识，都是哑巴狗，不能叫唤；但知做梦，躺卧，贪睡，'),
('CUV', '以赛亚书', 23, 56, 11, '这些狗贪食，不知饱足。这些牧人不能明白─各人偏行己路，各从各方求自己的利益。'),
('CUV', '以赛亚书', 23, 56, 12, '他们说：来罢！我去拿酒，我们饱饮浓酒；明日必和今日一样，就是宴乐无量极大之日。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 57, 1, '义人死亡，无人放在心上；虔诚人被收去，无人思念。这义人被收去是免了将来的祸患；'),
('CUV', '以赛亚书', 23, 57, 2, '他们得享（原文是进入）平安。素行正直的，各人在坟里（原文是床上）安歇。'),
('CUV', '以赛亚书', 23, 57, 3, '你们这些巫婆的儿子，奸夫和妓女的种子，都要前来！'),
('CUV', '以赛亚书', 23, 57, 4, '你们向谁戏笑？向谁张口吐舌呢？你们岂不是悖逆的儿女，虚谎的种类呢？'),
('CUV', '以赛亚书', 23, 57, 5, '你们在橡树中间，在各青翠树下欲火攻心；在山谷间，在石穴下杀了儿女；'),
('CUV', '以赛亚书', 23, 57, 6, '在谷中光滑石头里有你的分。这些就是你所得的分；你也向他浇了奠祭，献了供物，因这事我岂能容忍么？'),
('CUV', '以赛亚书', 23, 57, 7, '你在高而又高的山上安设床榻，也上那里去献祭。'),
('CUV', '以赛亚书', 23, 57, 8, '你在门后，在门框后，立起你的纪念；向外人赤露，又上去扩张床榻，与他们立约；你在那里看见他们的床就甚喜爱。'),
('CUV', '以赛亚书', 23, 57, 9, '你把油带到王那里，又多加香料，打发使者往远方去，自卑自贱直到阴间，'),
('CUV', '以赛亚书', 23, 57, 10, '你因路远疲倦，却不说这是枉然；你以为有复兴之力，所以不觉疲惫。'),
('CUV', '以赛亚书', 23, 57, 11, '你怕谁？因谁恐惧？竟说谎，不记念我，又不将这事放在心上。我不是许久闭口不言，你仍不怕我么？'),
('CUV', '以赛亚书', 23, 57, 12, '我要指明你的公义；至于你所行的都必与你无益。'),
('CUV', '以赛亚书', 23, 57, 13, '你哀求的时候，让你所聚集的拯救你罢！风要把他们刮散，一口气要把他们都吹去。但那投靠我的必得地土，必承受我的圣山为业。'),
('CUV', '以赛亚书', 23, 57, 14, '耶和华要说：你们修筑修筑，预备道路，将绊脚石从我百姓的路中除掉。'),
('CUV', '以赛亚书', 23, 57, 15, '因为那至高至上、永远长存（原文是住在永远）、名为圣者的如此说：我住在至高至圣的所在，也与心灵痛悔谦卑的人同居；要使谦卑人的灵苏醒，也使痛悔人的心苏醒。'),
('CUV', '以赛亚书', 23, 57, 16, '我必不永远相争，也不长久发怒，恐怕我所造的人与灵性都必发昏。'),
('CUV', '以赛亚书', 23, 57, 17, '因他贪婪的罪孽，我就发怒击打他；我向他掩面发怒，他却仍然随心背道。'),
('CUV', '以赛亚书', 23, 57, 18, '我看见他所行的道，也要医治他；又要引导他，使他和那一同伤心的人再得安慰。'),
('CUV', '以赛亚书', 23, 57, 19, '我造就嘴唇的果子；愿平安康泰归与远处的人，也归与近处的人；并且我要医治他。这是耶和华说的。'),
('CUV', '以赛亚书', 23, 57, 20, '惟独恶人，好像翻腾的海，不得平静；其中的水常涌出污秽和淤泥来。'),
('CUV', '以赛亚书', 23, 57, 21, '我的神说：恶人必不得平安！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 58, 1, '你要大声喊叫，不可止息；扬起声来，好像吹角。向我百姓说明他们的过犯；向雅各家说明他们的罪恶。'),
('CUV', '以赛亚书', 23, 58, 2, '他们天天寻求我，乐意明白我的道，好像行义的国民，不离弃他们神的典章，向我求问公义的判语，喜悦亲近神。'),
('CUV', '以赛亚书', 23, 58, 3, '他们说：我们禁食，你为何不看见呢？我们刻苦己心，你为何不理会呢？看哪，你们禁食的日子仍求利益，勒逼人为你们做苦工。'),
('CUV', '以赛亚书', 23, 58, 4, '你们禁食，却互相争竞，以凶恶的拳头打人。你们今日禁食，不得使你们的声音听闻于上。'),
('CUV', '以赛亚书', 23, 58, 5, '这样禁食岂是我所拣选、使人刻苦己心的日子么？岂是叫人垂头像苇子，用麻布和炉灰铺在他以下么？你这可称为禁食、为耶和华所悦纳的日子么？'),
('CUV', '以赛亚书', 23, 58, 6, '我所拣选的禁食不是要松开凶恶的绳，解下轭上的索，使被欺压的得自由，折断一切的轭么？'),
('CUV', '以赛亚书', 23, 58, 7, '不是要把你的饼分给饥饿的人，将飘流的穷人接到你家中，见赤身的给他衣服遮体，顾恤自己的骨肉而不掩藏么？'),
('CUV', '以赛亚书', 23, 58, 8, '这样，你的光就必发现如早晨的光，你所得的医治要速速发明。你的公义必在你前面行；耶和华的荣光必作你的后盾。'),
('CUV', '以赛亚书', 23, 58, 9, '那时你求告，耶和华必应允；你呼求，他必说：我在这里。你若从你中间除掉重轭和指摘人的指头，并发恶言的事，'),
('CUV', '以赛亚书', 23, 58, 10, '你心若向饥饿的人发怜悯，使困苦的人得满足，你的光就必在黑暗中发现；你的幽暗必变如正午。'),
('CUV', '以赛亚书', 23, 58, 11, '耶和华也必时常引导你，在干旱之地使你心满意足，骨头强壮。你必像浇灌的园子，又像水流不绝的泉源。'),
('CUV', '以赛亚书', 23, 58, 12, '那些出于你的人必修造久已荒废之处；你要建立拆毁累代的根基。你必称为补破口的，和重修路径与人居住的。'),
('CUV', '以赛亚书', 23, 58, 13, '你若在安息日掉转（或译：谨慎）你的脚步，在我圣日不以操作为喜乐，称安息日为可喜乐的，称耶和华的圣日为可尊重的；而且尊敬这日，不办自己的私事，不随自己的私意，不说自己的私话，'),
('CUV', '以赛亚书', 23, 58, 14, '你就以耶和华为乐。耶和华要使你乘驾地的高处，又以你祖雅各的产业养育你。这是耶和华亲口说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 59, 1, '耶和华的膀臂并非缩短，不能拯救，耳朵并非发沉，不能听见，'),
('CUV', '以赛亚书', 23, 59, 2, '但你们的罪孽使你们与神隔绝；你们的罪恶使他掩面不听你们。'),
('CUV', '以赛亚书', 23, 59, 3, '因你们的手被血沾染，你们的指头被罪孽沾污，你们的嘴唇说谎言，你们的舌头出恶语。'),
('CUV', '以赛亚书', 23, 59, 4, '无一人按公义告状，无一人凭诚实辨白；都倚靠虚妄，说谎言。所怀的是毒害；所生的是罪孽。'),
('CUV', '以赛亚书', 23, 59, 5, '他们菢毒蛇蛋，结蜘蛛网；人吃这蛋必死。这蛋被踏，必出蝮蛇。'),
('CUV', '以赛亚书', 23, 59, 6, '所结的网不能成为衣服；所做的也不能遮盖自己。他们的行为都是罪孽；手所做的都是强暴。'),
('CUV', '以赛亚书', 23, 59, 7, '他们的脚奔跑行恶；他们急速流无辜人的血；意念都是罪孽，所经过的路都荒凉毁灭。'),
('CUV', '以赛亚书', 23, 59, 8, '平安的路，他们不知道；所行的事没有公平。他们为自己修弯曲的路；凡行此路的都不知道平安。'),
('CUV', '以赛亚书', 23, 59, 9, '因此，公平离我们远，公义追不上我们。我们指望光亮，却是黑暗，指望光明，却行幽暗。'),
('CUV', '以赛亚书', 23, 59, 10, '我们摸索墙壁，好像瞎子；我们摸索，如同无目之人。我们晌午绊脚，如在黄昏一样；我们在肥壮人中，像死人一般。'),
('CUV', '以赛亚书', 23, 59, 11, '我们咆哮如熊，哀鸣如鸽；指望公平，却是没有；指望救恩，却远离我们。'),
('CUV', '以赛亚书', 23, 59, 12, '我们的过犯在你面前增多，罪恶作见证告我们；过犯与我们同在。至于我们的罪孽，我们都知道：'),
('CUV', '以赛亚书', 23, 59, 13, '就是悖逆、不认识耶和华，转去不跟从我们的神，说欺压和叛逆的话，心怀谎言，随即说出。'),
('CUV', '以赛亚书', 23, 59, 14, '并且公平转而退后，公义站在远处；诚实在街上仆倒，正直也不得进入。'),
('CUV', '以赛亚书', 23, 59, 15, '诚实少见；离恶的人反成掠物。那时，耶和华看见没有公平，甚不喜悦。'),
('CUV', '以赛亚书', 23, 59, 16, '他见无人拯救，无人代求，甚为诧异，就用自己的膀臂施行拯救，以公义扶持自己。'),
('CUV', '以赛亚书', 23, 59, 17, '他以公义为铠甲（或译：护心镜），以拯救为头盔，以报仇为衣服，以热心为外袍。'),
('CUV', '以赛亚书', 23, 59, 18, '他必按人的行为施报，恼怒他的敌人，报复他的仇敌向众海岛施行报应。'),
('CUV', '以赛亚书', 23, 59, 19, '如此，人从日落之处必敬畏耶和华的名，从日出之地也必敬畏他的荣耀；因为仇敌好像急流的河水冲来，是耶和华之气所驱逐的。'),
('CUV', '以赛亚书', 23, 59, 20, '必有一位救赎主来到锡安─雅各族中转离过犯的人那里。这是耶和华说的。'),
('CUV', '以赛亚书', 23, 59, 21, '耶和华说：至于我与他们所立的约乃是这样：我加给你的灵，传给你的话，必不离你的口，也不离你后裔与你后裔之后裔的口，从今直到永远；这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 60, 1, '兴起，发光！因为你的光已经来到！耶和华的荣耀发现照耀你。'),
('CUV', '以赛亚书', 23, 60, 2, '看哪，黑暗遮盖大地，幽暗遮盖万民，耶和华却要显现照耀你；他的荣耀要现在你身上。'),
('CUV', '以赛亚书', 23, 60, 3, '万国要来就你的光，君王要来就你发现的光辉。'),
('CUV', '以赛亚书', 23, 60, 4, '你举目向四方观看；众人都聚集来到你这里。你的众子从远方而来；你的众女也被怀抱而来。'),
('CUV', '以赛亚书', 23, 60, 5, '那时，你看见就有光荣；你心又跳动又宽畅；因为大海丰盛的货物必转来归你；列国的财宝也必来归你。'),
('CUV', '以赛亚书', 23, 60, 6, '成群的骆驼，并米甸和以法的独峰驼必遮满你；示巴的众人都必来到；要奉上黄金乳香，又要传说耶和华的赞美。'),
('CUV', '以赛亚书', 23, 60, 7, '基达的羊群都必聚集到你这里，尼拜约的公羊要供你使用，在我坛上必蒙悦纳；我必荣耀我荣耀的殿。'),
('CUV', '以赛亚书', 23, 60, 8, '那些飞来如云、又如鸽子向窗户飞回的是谁呢？'),
('CUV', '以赛亚书', 23, 60, 9, '众海岛必等候我，首先是他施的船只，将你的众子连他们的金银从远方一同带来，都为耶和华─你神的名，又为以色列的圣者，因为他已经荣耀了你。'),
('CUV', '以赛亚书', 23, 60, 10, '外邦人必建筑你的城墙；他们的王必服事你。我曾发怒击打你，现今却施恩怜恤你。'),
('CUV', '以赛亚书', 23, 60, 11, '你的城门必时常开放，昼夜不关；使人把列国的财物带来归你，并将他们的君王牵引而来。'),
('CUV', '以赛亚书', 23, 60, 12, '哪一邦哪一国不事奉你，就必灭亡，也必全然荒废。'),
('CUV', '以赛亚书', 23, 60, 13, '利巴嫩的荣耀，就是松树、杉树、黄杨树，都必一同归你，为要修饰我圣所之地；我也要使我脚踏之处得荣耀。'),
('CUV', '以赛亚书', 23, 60, 14, '素来苦待你的，他的子孙都必屈身来就你；藐视你的，都要在你脚下跪拜。他们要称你为耶和华的城，为以色列圣者的锡安。'),
('CUV', '以赛亚书', 23, 60, 15, '你虽然被撇弃被厌恶，甚至无人经过，我却使你变为永远的荣华，成为累代的喜乐。'),
('CUV', '以赛亚书', 23, 60, 16, '你也必吃万国的奶，又吃君王的奶。你便知道我─耶和华是你的救主，是你的救赎主，雅各的大能者。'),
('CUV', '以赛亚书', 23, 60, 17, '我要拿金子代替铜，拿银子代替铁，拿铜代替木头，拿铁代替石头；并要以和平为你的官长，以公义为你的监督。'),
('CUV', '以赛亚书', 23, 60, 18, '你地上不再听见强暴的事，境内不再听见荒凉毁灭的事。你必称你的墙为拯救，称你的门为赞美。'),
('CUV', '以赛亚书', 23, 60, 19, '日头不再作你白昼的光，月亮也不再发光照耀你。耶和华却要作你永远的光你神要为你的荣耀。'),
('CUV', '以赛亚书', 23, 60, 20, '你的日头不再下落；你的月亮也不退缩；因为耶和华必作你永远的光。你悲哀的日子也完毕了。'),
('CUV', '以赛亚书', 23, 60, 21, '你的居民都成为义人，永远得地为业；是我种的栽子，我手的工作，使我得荣耀。'),
('CUV', '以赛亚书', 23, 60, 22, '至小的族要加增千倍；微弱的国必成为强盛。我─耶和华要按定期速成这事。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 61, 1, '主耶和华的灵在我身上；因为耶和华用膏膏我，叫我传好信息给谦卑的人（或译：传福音给贫穷的人），差遣我医好伤心的人，报告被掳的得释放，被囚的出监牢；'),
('CUV', '以赛亚书', 23, 61, 2, '报告耶和华的恩年，和我们神报仇的日子；安慰一切悲哀的人，'),
('CUV', '以赛亚书', 23, 61, 3, '赐华冠与锡安悲哀的人，代替灰尘；喜乐油代替悲哀；赞美衣代替忧伤之灵；使他们称为公义树，是耶和华所栽的，叫他得荣耀。'),
('CUV', '以赛亚书', 23, 61, 4, '他们必修造已久的荒场，建立先前凄凉之处，重修历代荒凉之城。'),
('CUV', '以赛亚书', 23, 61, 5, '那时，外人必起来牧放你们的羊群；外邦人必作你们耕种田地的，修理葡萄园的。'),
('CUV', '以赛亚书', 23, 61, 6, '你们倒要称为耶和华的祭司；人必称你们为我们神的仆役。你们必吃用列国的财物，因得他们的荣耀自夸。'),
('CUV', '以赛亚书', 23, 61, 7, '你们必得加倍的好处，代替所受的羞辱；分中所得的喜乐，必代替所受的凌辱。在境内必得加倍的产业；永远之乐必归与你们（原文是他们）。'),
('CUV', '以赛亚书', 23, 61, 8, '因为我─耶和华喜爱公平，恨恶抢夺和罪孽；我要凭诚实施行报应，并要与我的百姓立永约。'),
('CUV', '以赛亚书', 23, 61, 9, '他们的后裔必在列国中被人认识；他们的子孙在众民中也是如此。凡看见他们的必认他们是耶和华赐福的后裔。'),
('CUV', '以赛亚书', 23, 61, 10, '我因耶和华大大欢喜；我的心靠神快乐。因他以拯救为衣给我穿上，以公义为袍给我披上，好像新郎戴上华冠，又像新妇佩戴妆饰。'),
('CUV', '以赛亚书', 23, 61, 11, '田地怎样使百谷发芽，园子怎样使所种的发生，主耶和华必照样使公义和赞美在万民中发出。')
on conflict (version, book, chapter, verse) do nothing;
